    def _classify_trade_readiness_nearest_pass(self, candidate=None):
        candidate = candidate if isinstance(candidate, dict) else {}
        decision_reason = str(candidate.get("decision_reason") or "").strip().lower()
        phase55_status = str(candidate.get("phase55_status") or "").strip().lower()
        entry_ready_reason = str(candidate.get("entry_ready_reason") or "").strip().lower()
        reject_reason = str(candidate.get("reject_reason") or "").strip().lower()
        score_breakdown = candidate.get("score_breakdown") if isinstance(candidate.get("score_breakdown"), dict) else {}
        if candidate.get("execution_safety_blocked") or phase55_status in {"immediate_reject", "probability_block", "capital_block", "psychology_block"}:
            return "execution_safety_block"
        if decision_reason in {"wide_spread", "poor_spread_score", "spread_too_wide"}:
            return "spread_near_pass"
        if decision_reason in {"low_liquidity_score", "low_liquidity", "not_tradable"}:
            return "liquidity_near_pass"
        if decision_reason in {"timing_penalty", "no_stochastic_crossover", "no_micro_pullback"}:
            return "continuity_near_pass" if decision_reason != "timing_penalty" else "momentum_near_pass"
        if phase55_status in {"pullback_wait", "trigger_wait"} or entry_ready_reason in {"no_micro_pullback", "no_stochastic_crossover", "standard_rules"}:
            return "phase55_near_pass" if phase55_status == "pullback_wait" else "continuity_near_pass"
        if reject_reason in {"insufficient_history", "insufficient_data"} or phase55_status == "insufficient_data":
            return "continuity_near_pass"
        if decision_reason in {"low_score"}:
            liquidity_component = self.to_float(score_breakdown.get("liquidity"), 0.0)
            spread_component = self.to_float(score_breakdown.get("spread"), 0.0)
            timing_component = self.to_float(score_breakdown.get("timing"), 0.0)
            if spread_component < 10.0 and spread_component <= liquidity_component:
                return "spread_near_pass"
            if liquidity_component < 10.0 and liquidity_component <= timing_component:
                return "liquidity_near_pass"
            if timing_component < 5.0:
                return "momentum_near_pass"
            return "phase55_near_pass"
        if phase55_status == "entry_ready":
            return "no_viable_candidate"
        return "no_viable_candidate"

    def _trade_readiness_next_condition(self, nearest_pass_reason):
        mapping = {
            "spread_near_pass": "needs tighter spread",
            "liquidity_near_pass": "needs stronger liquidity",
            "momentum_near_pass": "needs stronger directional momentum",
            "continuity_near_pass": "needs continuity confirmation",
            "phase55_near_pass": "waiting for Phase 5.5 pullback",
            "execution_safety_block": "execution safety must clear",
            "no_viable_candidate": "waiting for a viable candidate",
        }
        return mapping.get(str(nearest_pass_reason or "").strip().lower(), "waiting for a viable candidate")

    def _realm_xxxii_shadow_arb_audit(self, market, q, spread, family, decision=None, decision_reason=None, score_breakdown=None, confidence_score=None, edge_quality=None):
        market = market if isinstance(market, dict) else {}
        q = q if q is not None else None
        def _q_value(name, default=None):
            if isinstance(q, dict):
                value = q.get(name, default)
            else:
                value = getattr(q, name, default) if q is not None else default
            return default if value is None else value
        score_breakdown = score_breakdown if isinstance(score_breakdown, dict) else {}
        edge_quality = edge_quality if isinstance(edge_quality, dict) else {}
        ticker = str((getattr(q, "ticker", "") or market.get("ticker", "") or "")).strip() or "unknown"
        family = str(family or self.get_market_family(market) or market.get("family") or market.get("category") or "unknown").strip() or "unknown"
        yes_bid = self.to_float(_q_value("yes_bid", None), None)
        yes_ask = self.to_float(_q_value("yes_ask", None), None)
        no_bid = self.to_float(_q_value("no_bid", None), None)
        no_ask = self.to_float(_q_value("no_ask", None), None)
        spread_value = self.to_float(spread, None)
        if spread_value is None:
            if yes_bid is not None and yes_ask is not None:
                spread_value = max(0.0, float(yes_ask) - float(yes_bid))
            elif no_bid is not None and no_ask is not None:
                spread_value = max(0.0, float(no_ask) - float(no_bid))
            else:
                spread_value = 0.0
        yes_bid_size = self.to_float(_q_value("yes_bid_size", 0.0), 0.0)
        yes_ask_size = self.to_float(_q_value("yes_ask_size", 0.0), 0.0)
        no_bid_size = self.to_float(_q_value("no_bid_size", 0.0), 0.0)
        no_ask_size = self.to_float(_q_value("no_ask_size", 0.0), 0.0)
        topbook_yes = max(0.0, yes_bid_size or 0.0, yes_ask_size or 0.0)
        topbook_no = max(0.0, no_bid_size or 0.0, no_ask_size or 0.0)
        open_interest = self.to_float(_q_value("open_interest", None), None)
        if open_interest is None:
            open_interest = self.to_float(market.get("open_interest"), None)
        if open_interest is None:
            open_interest = self.to_float(market.get("openInterest"), 0.0) or 0.0
        imbalance_score = 0.0
        if topbook_yes + topbook_no > 0:
            imbalance_score = abs(topbook_yes - topbook_no) / max(topbook_yes + topbook_no, 1.0)
        dynamic_spread_limit = max(0.01, min(AION_MAX_PREFERRED_SPREAD, AION_MAX_PREFERRED_SPREAD + min(0.03, spread_value * 0.5) - min(0.03, imbalance_score * 0.03)))
        fair_value_price = 0.5
        if yes_bid is not None and yes_ask is not None:
            fair_value_price = max(0.0, min(1.0, (float(yes_bid) + float(yes_ask)) / 2.0))
        elif no_bid is not None and no_ask is not None:
            fair_value_price = max(0.0, min(1.0, 1.0 - ((float(no_bid) + float(no_ask)) / 2.0)))
        estimated_cost = max(0.0, spread_value) + 0.01 + AION_EDGE_COST_BUFFER
        edge_score = 0.0
        if yes_ask is not None:
            edge_score = max(edge_score, fair_value_price - float(yes_ask))
        if no_ask is not None:
            edge_score = max(edge_score, (1.0 - fair_value_price) - float(no_ask))
        if yes_bid is not None:
            edge_score = max(edge_score, float(yes_bid) - fair_value_price)
        if no_bid is not None:
            edge_score = max(edge_score, float(no_bid) - (1.0 - fair_value_price))
        missing_quotes = yes_bid is None and yes_ask is None and no_bid is None and no_ask is None
        thin_top_book = topbook_yes < AION_MIN_TOPBOOK_SIZE or topbook_no < AION_MIN_TOPBOOK_SIZE
        weak_open_interest = open_interest < AION_MIN_OPEN_INTEREST
        spread_too_wide = spread_value > AION_MAX_PREFERRED_SPREAD
        unstable_orderbook = spread_value > dynamic_spread_limit * 1.25 or spread_value > AION_MAX_PREFERRED_SPREAD * 1.5
        excessive_imbalance = imbalance_score >= 0.80
        resolution_context = self.get_market_event_timestamp_details(market or {}, keys=("close_time", "close_time_ts", "expiration_time", "expiration_time_ts", "settlement_time", "settlement_time_ts"))
        resolution_uncertainty = resolution_context is None
        reject_reason = "none"
        hard_block = False
        if missing_quotes:
            reject_reason = "missing_quotes"
            hard_block = True
        elif spread_too_wide and thin_top_book:
            reject_reason = "spread_too_wide"
            hard_block = True
        elif thin_top_book and weak_open_interest:
            reject_reason = "thin_top_book"
            hard_block = True
        elif weak_open_interest and excessive_imbalance:
            reject_reason = "weak_open_interest"
            hard_block = True
        elif unstable_orderbook and (spread_value > dynamic_spread_limit or excessive_imbalance):
            reject_reason = "unstable_orderbook"
            hard_block = True
        elif excessive_imbalance and spread_value > AION_MAX_PREFERRED_SPREAD:
            reject_reason = "excessive_imbalance"
            hard_block = True
        elif resolution_uncertainty:
            reject_reason = "resolution_uncertainty"
            hard_block = True
        elif edge_score <= estimated_cost:
            reject_reason = "edge_below_cost"
            hard_block = True
        would_trade_shadow = bool(not hard_block and edge_score > estimated_cost and edge_score >= AION_ARB_MIN_EDGE)
        common = {
            "ticker": ticker,
            "family": family,
            "yes_bid": yes_bid,
            "yes_ask": yes_ask,
            "no_bid": no_bid,
            "no_ask": no_ask,
            "spread": round(spread_value, 4),
            "topbook_yes": round(topbook_yes, 4),
            "topbook_no": round(topbook_no, 4),
            "open_interest": round(open_interest, 4),
            "imbalance_score": round(imbalance_score, 4),
            "dynamic_spread_limit": round(dynamic_spread_limit, 4),
            "edge_score": round(edge_score, 4),
            "estimated_cost": round(estimated_cost, 4),
            "fair_value_source": "shadow_placeholder_midpoint",
            "fair_value_price": round(fair_value_price, 4),
            "shadow_arb_edge": round(edge_score, 4),
            "would_trade_shadow": would_trade_shadow,
            "reject_reason": reject_reason,
            "resolution_uncertainty": resolution_uncertainty,
            "orderbook_quality_pass": bool(not missing_quotes and not spread_too_wide and not thin_top_book and not weak_open_interest and not unstable_orderbook and not excessive_imbalance),
            "price_safety_pass": bool(not missing_quotes and not resolution_uncertainty and not spread_too_wide and not unstable_orderbook),
        }
        now = time.time()
        if now - float(getattr(self, "last_realm_xxxii_orderbook_quality_ts", 0.0) or 0.0) >= 120.0:
            self.last_realm_xxxii_orderbook_quality_ts = now
            print("[LIVE-ORDERBOOK-QUALITY] " + json.dumps(common, sort_keys=True, default=str))
        if now - float(getattr(self, "last_realm_xxxii_price_safety_ts", 0.0) or 0.0) >= 120.0:
            self.last_realm_xxxii_price_safety_ts = now
            print("[LIVE-PRICE-SAFETY] " + json.dumps({**common, "hard_block": hard_block, "spread_too_wide": spread_too_wide, "thin_top_book": thin_top_book, "weak_open_interest": weak_open_interest, "unstable_orderbook": unstable_orderbook, "excessive_imbalance": excessive_imbalance}, sort_keys=True, default=str))
        if now - float(getattr(self, "last_realm_xxxii_edge_cost_ts", 0.0) or 0.0) >= 120.0:
            self.last_realm_xxxii_edge_cost_ts = now
            print("[LIVE-EDGE-COST-CHECK] " + json.dumps({**common, "passes_edge_cost": edge_score > estimated_cost}, sort_keys=True, default=str))
        if now - float(getattr(self, "last_realm_xxxii_fair_value_ts", 0.0) or 0.0) >= 120.0:
            self.last_realm_xxxii_fair_value_ts = now
            print("[LIVE-FAIR-VALUE-SHADOW] " + json.dumps({**common, "shadow_mode": AION_FAIR_VALUE_SHADOW, "decision": decision or "unknown", "decision_reason": decision_reason or "unknown"}, sort_keys=True, default=str))
        if now - float(getattr(self, "last_realm_xxxii_arb_shadow_ts", 0.0) or 0.0) >= 120.0:
            self.last_realm_xxxii_arb_shadow_ts = now
            print("[LIVE-ARB-SHADOW] " + json.dumps({**common, "live_arb_enabled": AION_LIVE_ARB_ENABLED, "max_canary_contracts": AION_ARB_MAX_CANARY_CONTRACTS}, sort_keys=True, default=str))
        if missing_quotes:
            reject_reason = reject_reason or "no_decision_available"
        return {
            **common,
            "hard_block": hard_block,
            "live_arb_enabled": AION_LIVE_ARB_ENABLED,
            "max_canary_contracts": AION_ARB_MAX_CANARY_CONTRACTS,
        }

    def _evaluate_shadow_arb_canary_gate(self, audit, tracker_record=None, market=None, q=None, decision=None, decision_reason=None):
        audit = audit if isinstance(audit, dict) else {}
        tracker_record = tracker_record if isinstance(tracker_record, dict) else {}
        ticker = str(audit.get("ticker") or tracker_record.get("ticker") or getattr(q, "ticker", None) or (market or {}).get("ticker") or "").strip()
        if not ticker:
            return None
        family = str(audit.get("family") or tracker_record.get("family") or self.get_market_family(market or {}) or getattr(q, "family", None) or "UNKNOWN").strip() or "UNKNOWN"
        repeat_count = int(tracker_record.get("repeat_count") or audit.get("repeat_count") or 0)
        avg_edge = self.to_float(tracker_record.get("avg_edge"), self.to_float(audit.get("avg_edge"), self.to_float(audit.get("shadow_arb_edge"), 0.0))) or 0.0
        max_edge = self.to_float(tracker_record.get("max_edge"), self.to_float(audit.get("max_edge"), self.to_float(audit.get("shadow_arb_edge"), 0.0))) or 0.0
        estimated_cost = self.to_float(audit.get("estimated_cost"), 0.0) or 0.0
        edge_above_cost = bool(audit.get("edge_above_cost"))
        orderbook_quality_pass = bool(audit.get("orderbook_quality_pass"))
        price_safety_pass = bool(audit.get("price_safety_pass"))
        missing_quotes = bool(audit.get("reject_reason") == "missing_quotes")
        resolution_uncertainty = bool(audit.get("resolution_uncertainty"))
        duplicate_detail = self.check_live_duplicate_position_api(ticker)
        duplicate_block = bool(duplicate_detail.get("blocked"))
        daily_cap_day = time.strftime("%Y-%m-%d")
        if self.live_trade_day != daily_cap_day:
            self.live_trade_day = daily_cap_day
            self.live_trade_count_today = 0
        daily_cap_block = bool(self.live_trade_count_today >= MAX_LIVE_TRADES_PER_DAY)
        live_armed = bool(globals().get("LIVE_ARMED", False))
        live_env_confirmed = bool(globals().get("LIVE_ENV_CONFIRMED", False))
        live_arm_gate = bool(live_armed and live_env_confirmed)
        telegram_configured = bool((os.environ.get("TELEGRAM_BOT_TOKEN", "") or "").strip() and (os.environ.get("TELEGRAM_CHAT_ID", "") or "").strip())
        telegram_alert_ready = bool((not AION_ARB_REQUIRE_TELEGRAM_ALERT) or telegram_configured)
        canary_contracts_ok = int(AION_ARB_MAX_CANARY_CONTRACTS or 1) == 1
        shadow_canary_eligible = bool(
            repeat_count >= AION_ARB_MIN_REPEAT_COUNT
            and avg_edge >= AION_ARB_MIN_EDGE
            and edge_above_cost
            and orderbook_quality_pass
            and price_safety_pass
            and not missing_quotes
            and not resolution_uncertainty
            and not duplicate_block
            and not daily_cap_block
            and telegram_alert_ready
            and canary_contracts_ok
        )
        live_arb_enabled = bool(AION_LIVE_ARB_ENABLED)
        final_canary_eligible = bool(shadow_canary_eligible and live_arb_enabled and live_arm_gate)
        block_reason = None
        if not live_arb_enabled:
            block_reason = "live_arb_disabled"
        elif not live_arm_gate:
            block_reason = "live_arm_gate_disabled"
        elif repeat_count < AION_ARB_MIN_REPEAT_COUNT:
            block_reason = "repeat_count_below_threshold"
        elif avg_edge < AION_ARB_MIN_EDGE:
            block_reason = "avg_edge_below_min_edge"
        elif not edge_above_cost:
            block_reason = "edge_below_cost"
        elif not orderbook_quality_pass:
            block_reason = "orderbook_quality_block"
        elif not price_safety_pass:
            block_reason = "price_safety_block"
        elif missing_quotes:
            block_reason = "missing_quotes"
        elif resolution_uncertainty:
            block_reason = "resolution_uncertainty"
        elif duplicate_block:
            block_reason = duplicate_detail.get("reason") or "duplicate_block"
        elif daily_cap_block:
            block_reason = "daily_trade_cap"
        elif not telegram_alert_ready:
            block_reason = "telegram_alert_not_ready"
        elif not canary_contracts_ok:
            block_reason = "canary_contracts_exhausted"
        gate_record = {
            "ticker": ticker,
            "family": family,
            "live_arb_enabled": live_arb_enabled,
            "repeat_count": repeat_count,
            "avg_edge": round(avg_edge, 4),
            "max_edge": round(max_edge, 4),
            "estimated_cost": round(estimated_cost, 4),
            "edge_above_cost": bool(edge_above_cost),
            "orderbook_quality_pass": bool(orderbook_quality_pass),
            "price_safety_pass": bool(price_safety_pass),
            "duplicate_block": bool(duplicate_block),
            "daily_cap_block": bool(daily_cap_block),
            "live_arm_gate": bool(live_arm_gate),
            "telegram_alert_ready": bool(telegram_alert_ready),
            "max_canary_contracts": int(AION_ARB_MAX_CANARY_CONTRACTS or 1),
            "shadow_canary_eligible": bool(shadow_canary_eligible),
            "final_canary_eligible": bool(final_canary_eligible),
            "block_reason": block_reason,
            "decision": decision or "unknown",
            "decision_reason": decision_reason or audit.get("reject_reason") or "unknown",
        }
        now = time.time()
        last_emit = float(getattr(self, "shadow_arb_canary_gate_last_signal_ts_by_ticker", {}).get(ticker, 0.0) or 0.0)
        if now - last_emit >= 120.0:
            self.shadow_arb_canary_gate_last_signal_ts_by_ticker[ticker] = now
            print("[LIVE-ARB-CANARY-GATE] " + json.dumps(gate_record, sort_keys=True, default=str))
            if shadow_canary_eligible:
                print("[LIVE-ARB-CANARY-ELIGIBLE-SHADOW] " + json.dumps(gate_record, sort_keys=True, default=str))
            if not final_canary_eligible:
                print("[LIVE-ARB-CANARY-BLOCK] " + json.dumps(gate_record, sort_keys=True, default=str))
        if final_canary_eligible:
            canary_result = self._maybe_execute_live_arb_canary(market, audit, decision=decision, decision_reason=decision_reason)
            if isinstance(canary_result, dict) and canary_result.get("enabled"):
                gate_record["canary_execution"] = canary_result
        return gate_record

    def _maybe_execute_live_arb_canary(self, market, audit, decision=None, decision_reason=None):
        if not AION_LIVE_ARB_ENABLED:
            return None
        if not isinstance(audit, dict) or not audit.get("would_trade_shadow"):
            return None
        if int(audit.get("max_canary_contracts") or 1) < 1:
            return None
        if decision == "SKIP":
            return None
        return {
            "enabled": True,
            "contracts": 1,
            "ticker": audit.get("ticker") or (market or {}).get("ticker"),
            "decision_reason": decision_reason or audit.get("reject_reason") or "future_canary_inert",
        }

    def _record_shadow_arb_validation(self, audit, market=None, q=None, decision=None, decision_reason=None):
        audit = audit if isinstance(audit, dict) else {}
        edge_quality = audit.get("edge_quality") if isinstance(audit.get("edge_quality"), dict) else {}
        ticker = str(audit.get("ticker") or getattr(q, "ticker", None) or (market or {}).get("ticker") or "").strip()
        if not ticker:
            return None
        family = str(audit.get("family") or self.get_market_family(market or {}) or getattr(q, "family", None) or "UNKNOWN").strip() or "UNKNOWN"
        shadow_edge = self.to_float(audit.get("shadow_arb_edge"), self.to_float(audit.get("edge_score"), 0.0)) or 0.0
        estimated_cost = self.to_float(audit.get("estimated_cost"), 0.0) or 0.0
        yes_bid = self.to_float(audit.get("yes_bid"), self.to_float(getattr(q, "yes_bid", None), self.to_float((market or {}).get("yes_bid"), None)))
        yes_ask = self.to_float(audit.get("yes_ask"), self.to_float(getattr(q, "yes_ask", None), self.to_float((market or {}).get("yes_ask"), None)))
        no_bid = self.to_float(audit.get("no_bid"), self.to_float(getattr(q, "no_bid", None), self.to_float((market or {}).get("no_bid"), None)))
        no_ask = self.to_float(audit.get("no_ask"), self.to_float(getattr(q, "no_ask", None), self.to_float((market or {}).get("no_ask"), None)))
        spread_value = self.to_float(audit.get("spread"), None)
        if spread_value is None and yes_bid is not None and yes_ask is not None:
            spread_value = max(0.0, float(yes_ask) - float(yes_bid))
        elif spread_value is None and no_bid is not None and no_ask is not None:
            spread_value = max(0.0, float(no_ask) - float(no_bid))
        if spread_value is None:
            spread_value = 0.0
        reject_reason = str(audit.get("reject_reason") or decision_reason or "unknown").strip().lower()
        hard_block = bool(audit.get("hard_block"))
        safety_reject_reasons = {"missing_quotes", "spread_too_wide", "thin_top_book", "weak_open_interest", "unstable_orderbook", "excessive_imbalance"}
        price_safety_reject = reject_reason in safety_reject_reasons
        resolution_uncertainty = bool(audit.get("resolution_uncertainty")) or reject_reason == "resolution_uncertainty"
        passed_price_safety = not price_safety_reject and not resolution_uncertainty
        edge_above_cost = shadow_edge > estimated_cost
        now = time.time()
        cycle_stats = getattr(self, "shadow_arb_validation_cycle_stats", None)
        if not isinstance(cycle_stats, Counter):
            cycle_stats = Counter()
            self.shadow_arb_validation_cycle_stats = cycle_stats
        rolling_stats = getattr(self, "shadow_arb_validation_totals", None)
        if not isinstance(rolling_stats, Counter):
            rolling_stats = Counter()
            self.shadow_arb_validation_totals = rolling_stats
        family_stats = getattr(self, "shadow_arb_validation_family_stats", None)
        if not isinstance(family_stats, dict):
            family_stats = {}
            self.shadow_arb_validation_family_stats = family_stats
        repeat_tracker = getattr(self, "shadow_arb_repeat_tracker", None)
        if not isinstance(repeat_tracker, dict):
            repeat_tracker = {}
            self.shadow_arb_repeat_tracker = repeat_tracker

        cycle_stats["shadow_arb_candidates_seen"] += 1
        rolling_stats["shadow_arb_candidates_seen"] += 1
        if passed_price_safety:
            cycle_stats["shadow_arb_candidates_passed_price_safety"] += 1
            rolling_stats["shadow_arb_candidates_passed_price_safety"] += 1
        if edge_above_cost:
            cycle_stats["shadow_arb_candidates_edge_above_cost"] += 1
            rolling_stats["shadow_arb_candidates_edge_above_cost"] += 1
        if reject_reason == "edge_below_cost" or (not edge_above_cost and not price_safety_reject and not resolution_uncertainty):
            cycle_stats["shadow_arb_rejected_edge_below_cost"] += 1
            rolling_stats["shadow_arb_rejected_edge_below_cost"] += 1
        if reject_reason == "spread_too_wide":
            cycle_stats["shadow_arb_rejected_spread"] += 1
            rolling_stats["shadow_arb_rejected_spread"] += 1
        if reject_reason in {"thin_top_book", "weak_open_interest", "unstable_orderbook", "excessive_imbalance"}:
            cycle_stats["shadow_arb_rejected_liquidity"] += 1
            rolling_stats["shadow_arb_rejected_liquidity"] += 1
        if reject_reason == "missing_quotes":
            cycle_stats["shadow_arb_rejected_missing_quotes"] += 1
            rolling_stats["shadow_arb_rejected_missing_quotes"] += 1
        if resolution_uncertainty:
            cycle_stats["shadow_arb_rejected_resolution_uncertainty"] += 1
            rolling_stats["shadow_arb_rejected_resolution_uncertainty"] += 1

        family_entry = family_stats.setdefault(
            family,
            {
                "count": 0,
                "edge_sum": 0.0,
                "max_edge": 0.0,
                "edge_above_cost_count": 0,
                "reject_reasons": Counter(),
            },
        )
        family_entry["count"] += 1
        family_entry["edge_sum"] += shadow_edge
        family_entry["max_edge"] = max(self.to_float(family_entry.get("max_edge"), 0.0), shadow_edge)
        if edge_above_cost:
            family_entry["edge_above_cost_count"] += 1
        family_entry["reject_reasons"][reject_reason] += 1

        tracker = repeat_tracker.setdefault(
            ticker,
            {
                "first_seen_time": now,
                "last_seen_time": now,
                "repeat_count": 0,
                "pass_count": 0,
                "price_safety_pass_count": 0,
                "edge_above_cost_count": 0,
                "edges": deque(maxlen=12),
                "costs": deque(maxlen=12),
                "family": family,
                "reject_reasons": Counter(),
            },
        )
        tracker["repeat_count"] += 1
        tracker["last_seen_time"] = now
        tracker["family"] = family
        tracker["edges"].append(shadow_edge)
        tracker["costs"].append(estimated_cost)
        if passed_price_safety:
            tracker["price_safety_pass_count"] += 1
        if edge_above_cost:
            tracker["edge_above_cost_count"] += 1
        if passed_price_safety and edge_above_cost:
            tracker["pass_count"] += 1
        tracker["reject_reasons"][reject_reason] += 1

        edges = list(tracker["edges"]) or [shadow_edge]
        avg_edge = sum(edges) / max(len(edges), 1)
        max_edge = max(edges)
        min_edge = min(edges)
        edge_span = max(0.0, max_edge - min_edge)
        stability_denominator = max(abs(avg_edge), abs(max_edge), abs(min_edge), estimated_cost, 0.01)
        edge_stability_score = max(0.0, min(1.0, 1.0 - (edge_span / stability_denominator)))
        consistency_score = round(tracker["pass_count"] / max(tracker["repeat_count"], 1), 4)
        tracker_record = {
            "ticker": ticker,
            "family": family,
            "shadow_edge": round(shadow_edge, 4),
            "estimated_cost": round(estimated_cost, 4),
            "edge_above_cost": bool(edge_above_cost),
            "passed_price_safety": bool(passed_price_safety),
            "reject_reason": reject_reason,
            "repeat_count": int(tracker["repeat_count"]),
            "consistency_score": consistency_score,
            "edge_stability_score": round(edge_stability_score, 4),
            "avg_edge": round(avg_edge, 4),
            "max_edge": round(max_edge, 4),
            "first_seen_time": tracker["first_seen_time"],
            "last_seen_time": tracker["last_seen_time"],
            "live_arb_enabled": bool(AION_LIVE_ARB_ENABLED),
        }

        best_cycle = getattr(self, "shadow_arb_validation_cycle_best", None)
        if not isinstance(best_cycle, dict) or shadow_edge > self.to_float(best_cycle.get("shadow_edge"), -1e9):
            self.shadow_arb_validation_cycle_best = dict(tracker_record)

        if tracker["repeat_count"] > 1:
            cycle_stats["shadow_arb_repeat_count"] += 1
            rolling_stats["shadow_arb_repeat_count"] += 1

        if tracker["repeat_count"] >= 2:
            last_emit = float(getattr(self, "shadow_arb_repeat_last_signal_ts_by_ticker", {}).get(ticker, 0.0) or 0.0)
            if now - last_emit >= 120.0:
                self.shadow_arb_repeat_last_signal_ts_by_ticker[ticker] = now
                print(
                    "[LIVE-ARB-REPEAT-SIGNAL] " + json.dumps({
                        **tracker_record,
                        "shadow_arb_repeat_count": tracker["repeat_count"],
                    }, sort_keys=True, default=str)
                )
        if tracker["repeat_count"] >= 3 and tracker["pass_count"] >= 2 and passed_price_safety and edge_above_cost:
            last_ready_emit = float(getattr(self, "shadow_arb_canary_ready_last_signal_ts_by_ticker", {}).get(ticker, 0.0) or 0.0)
            if now - last_ready_emit >= 120.0:
                self.shadow_arb_canary_ready_last_signal_ts_by_ticker[ticker] = now
                print(
                    "[LIVE-ARB-CANARY-READY-SHADOW] " + json.dumps({
                        "ticker": ticker,
                        "family": family,
                        "repeat_count": tracker["repeat_count"],
                        "avg_edge": round(avg_edge, 4),
                        "max_edge": round(max_edge, 4),
                        "estimated_cost": round(estimated_cost, 4),
                        "reason": "shadow_signal_consistent_not_live_enabled",
                        "live_arb_enabled": bool(AION_LIVE_ARB_ENABLED),
                    }, sort_keys=True, default=str)
                )
        self._update_shadow_arb_stability_memory(
            ticker=ticker,
            family=family,
            shadow_edge=shadow_edge,
            estimated_cost=estimated_cost,
            passed_price_safety=passed_price_safety,
            edge_above_cost=edge_above_cost,
            unstable=bool(not passed_price_safety or resolution_uncertainty or reject_reason in {"unsafe_price", "low_volume", "missing_quotes", "spread_too_wide", "thin_top_book", "weak_open_interest", "unstable_orderbook", "excessive_imbalance"}),
            reject_reason=reject_reason,
        )
        try:
            self._update_live_microstructure_memory(
                market=market,
                q=q,
                family=family,
                spread=spread_value,
                audit={
                    "shadow_arb_edge": shadow_edge,
                    "estimated_cost": estimated_cost,
                    "edge_above_cost": edge_above_cost,
                    "hard_block": hard_block,
                    "resolution_uncertainty": resolution_uncertainty,
                    "reject_reason": reject_reason,
                },
                decision=decision,
                decision_reason=decision_reason,
                edge_quality=edge_quality,
            )
        except Exception as exc:
            print(f"[LIVE-MICROSTRUCTURE-DEGRADED] ticker={ticker} family={family} reason={exc.__class__.__name__}")
        reactivation_summary = None
        try:
            ticker_bucket = getattr(self, "live_microstructure_by_ticker", {}).get(f"ticker:{ticker}") if isinstance(getattr(self, "live_microstructure_by_ticker", {}), dict) else None
            family_summary = self._build_live_microstructure_family_summary(family=family)
            reactivation_summary = self._update_reactivation_watchlist(
                ticker=ticker,
                family=family,
                ticker_bucket=ticker_bucket if isinstance(ticker_bucket, dict) else {},
                family_summary=family_summary if isinstance(family_summary, dict) else {},
                audit={
                    "shadow_arb_edge": shadow_edge,
                    "estimated_cost": estimated_cost,
                    "edge_above_cost": edge_above_cost,
                    "hard_block": hard_block,
                    "resolution_uncertainty": resolution_uncertainty,
                    "reject_reason": reject_reason,
                },
                decision_reason=decision_reason,
            )
            tracker_record["reactivation"] = reactivation_summary
        except Exception as exc:
            print(f"[LIVE-REACTIVATION-DEGRADED] ticker={ticker} family={family} reason={exc.__class__.__name__}")
        try:
            family_microstructure_summary = self._build_live_microstructure_family_summary(family=family)
            adaptive_priority_summary = getattr(self, "last_adaptive_priority_summary", {}) if isinstance(getattr(self, "last_adaptive_priority_summary", {}), dict) else {}
            candidate_learning_summary = self._update_candidate_learning_memory(
                market=market,
                q=q,
                family=family,
                audit={
                    "ticker": ticker,
                    "family": family,
                    "shadow_arb_edge": shadow_edge,
                    "estimated_cost": estimated_cost,
                    "edge_above_cost": edge_above_cost,
                    "hard_block": hard_block,
                    "resolution_uncertainty": resolution_uncertainty,
                    "reject_reason": reject_reason,
                },
                decision=decision,
                decision_reason=decision_reason,
                shadow_arb_validation={
                    "passed_price_safety": passed_price_safety,
                    "edge_above_cost": edge_above_cost,
                    "reject_reason": reject_reason,
                },
                reactivation_summary=reactivation_summary if isinstance(reactivation_summary, dict) else {},
                adaptive_priority_summary=adaptive_priority_summary if isinstance(adaptive_priority_summary, dict) else {},
                family_microstructure_summary=family_microstructure_summary if isinstance(family_microstructure_summary, dict) else {},
                count_rejections=True,
            )
            tracker_record["learning"] = candidate_learning_summary
        except Exception as exc:
            print(f"[LIVE-LEARNING-DEGRADED] ticker={ticker} family={family} reason={exc.__class__.__name__}")
        canary_gate = self._evaluate_shadow_arb_canary_gate(
            audit,
            tracker_record=tracker_record,
            market=market,
            q=q,
            decision=decision,
            decision_reason=decision_reason,
        )
        if isinstance(canary_gate, dict):
            tracker_record["canary_gate"] = canary_gate
        self._maybe_emit_shadow_arb_validation_snapshot()
        self._maybe_emit_shadow_arb_canary_readiness_dashboard()
        self._maybe_emit_shadow_arb_readiness_score()
        self._maybe_emit_shadow_arb_canary_recommendation()
        return tracker_record

    def _get_shadow_arb_stability_bucket(self, container_name, key):
        buckets = getattr(self, container_name, None)
        if not isinstance(buckets, dict):
            buckets = {}
            setattr(self, container_name, buckets)
        bucket = buckets.setdefault(
            key,
            {
                "first_seen_timestamp": None,
                "last_seen_timestamp": 0.0,
                "repeat_count": 0,
                "repeated_edge_count": 0,
                "repeated_safe_orderbook_count": 0,
                "repeated_above_cost_count": 0,
                "repeated_unstable_count": 0,
                "avg_edge": 0.0,
                "avg_estimated_cost": 0.0,
                "last_edge": None,
                "last_estimated_cost": None,
                "last_reason": None,
                "edge_history": deque(maxlen=12),
                "cost_history": deque(maxlen=12),
            },
        )
        return bucket

    def _update_shadow_arb_stability_memory(self, *, ticker=None, family=None, shadow_edge=None, estimated_cost=None, passed_price_safety=None, edge_above_cost=None, unstable=False, reject_reason=None):
        now = time.time()
        if ticker:
            ticker_bucket = self._get_shadow_arb_stability_bucket("shadow_arb_stability_by_ticker", f"ticker:{ticker}")
            self._update_shadow_arb_stability_bucket(
                ticker_bucket,
                now=now,
                shadow_edge=shadow_edge,
                estimated_cost=estimated_cost,
                passed_price_safety=passed_price_safety,
                edge_above_cost=edge_above_cost,
                unstable=unstable,
                reject_reason=reject_reason,
            )
        if family:
            family_bucket = self._get_shadow_arb_stability_bucket("shadow_arb_stability_by_family", f"family:{family}")
            self._update_shadow_arb_stability_bucket(
                family_bucket,
                now=now,
                shadow_edge=shadow_edge,
                estimated_cost=estimated_cost,
                passed_price_safety=passed_price_safety,
                edge_above_cost=edge_above_cost,
                unstable=unstable,
                reject_reason=reject_reason,
            )
        ticker_bucket = getattr(self, "shadow_arb_stability_by_ticker", {}).get(f"ticker:{ticker}") if ticker else None
        if isinstance(ticker_bucket, dict):
            ticker_bucket["last_ticker"] = ticker
            ticker_bucket["last_family"] = family
        family_bucket = getattr(self, "shadow_arb_stability_by_family", {}).get(f"family:{family}") if family else None
        if isinstance(family_bucket, dict):
            family_bucket["last_ticker"] = ticker
            family_bucket["last_family"] = family

    def _update_shadow_arb_stability_bucket(self, bucket, *, now, shadow_edge=None, estimated_cost=None, passed_price_safety=None, edge_above_cost=None, unstable=False, reject_reason=None):
        if not isinstance(bucket, dict):
            return
        if bucket.get("first_seen_timestamp") is None:
            bucket["first_seen_timestamp"] = now
        bucket["repeat_count"] = int(bucket.get("repeat_count", 0) or 0) + 1
        bucket["last_seen_timestamp"] = now
        bucket["repeated_edge_count"] = int(bucket.get("repeated_edge_count", 0) or 0) + (1 if shadow_edge is not None else 0)
        if passed_price_safety:
            bucket["repeated_safe_orderbook_count"] = int(bucket.get("repeated_safe_orderbook_count", 0) or 0) + 1
        if edge_above_cost:
            bucket["repeated_above_cost_count"] = int(bucket.get("repeated_above_cost_count", 0) or 0) + 1
        if unstable:
            bucket["repeated_unstable_count"] = int(bucket.get("repeated_unstable_count", 0) or 0) + 1
        if shadow_edge is not None:
            try:
                bucket.setdefault("edge_history", deque(maxlen=12)).append(float(shadow_edge))
            except (TypeError, ValueError):
                pass
        if estimated_cost is not None:
            try:
                bucket.setdefault("cost_history", deque(maxlen=12)).append(float(estimated_cost))
            except (TypeError, ValueError):
                pass
        edge_history = list(bucket.get("edge_history") or [])
        cost_history = list(bucket.get("cost_history") or [])
        if edge_history:
            bucket["avg_edge"] = round(sum(edge_history) / max(len(edge_history), 1), 4)
        if cost_history:
            bucket["avg_estimated_cost"] = round(sum(cost_history) / max(len(cost_history), 1), 4)
        bucket["last_edge"] = shadow_edge
        bucket["last_estimated_cost"] = estimated_cost
        bucket["last_reason"] = reject_reason
        bucket["last_safe_orderbook"] = bool(passed_price_safety)
        bucket["last_above_cost"] = bool(edge_above_cost)
        bucket["last_unstable"] = bool(unstable)

    def _get_live_microstructure_bucket(self, container_name, key):
        buckets = getattr(self, container_name, None)
        if not isinstance(buckets, dict):
            buckets = {}
            setattr(self, container_name, buckets)
        bucket = buckets.setdefault(
            key,
            {
                "first_seen_timestamp": None,
                "last_seen_timestamp": 0.0,
                "repeat_count": 0,
                "ticker": None,
                "family": None,
                "last_quote_signature": None,
                "last_quote_change_ts": None,
                "last_spread_signature": None,
                "last_spread_change_ts": None,
                "last_edge_signature": None,
                "last_edge_change_ts": None,
                "last_unsafe_signature": None,
                "last_unsafe_change_ts": None,
                "best_bid_value": None,
                "best_ask_value": None,
                "spread_value": None,
                "yes_depth_value": None,
                "no_depth_value": None,
                "last_depth_sum": None,
                "quote_lifetime_total_seconds": 0.0,
                "spread_lifetime_total_seconds": 0.0,
                "edge_lifetime_total_seconds": 0.0,
                "unsafe_price_total_seconds": 0.0,
                "quote_churn_count": 0,
                "spread_change_count": 0,
                "edge_collapse_count": 0,
                "edge_survival_cycles": 0,
                "unsafe_price_cycles": 0,
                "quote_withdrawal_count": 0,
                "disappearing_liquidity_count": 0,
                "liquidity_decay_total": 0.0,
                "liquidity_decay_samples": 0,
                "liquidity_decay_rate": 0.0,
                "imbalance_ratio": 0.0,
                "pressure_direction": "unknown",
                "last_imbalance_ratio": None,
                "imbalance_history": deque(maxlen=12),
                "spread_history": deque(maxlen=12),
                "edge_history": deque(maxlen=12),
                "quote_history": deque(maxlen=12),
                "rapid_quote_move_count": 0,
                "fake_liquidity_count": 0,
                "unstable_topbook_count": 0,
                "repeated_spread_widening_count": 0,
                "aggressive_quote_fade_count": 0,
                "market_maker_behavior_score": 0.5,
                "execution_survivability_score": 0.5,
                "edge_durability_score": 0.5,
                "spread_stability_score": 0.5,
                "liquidity_reliability_score": 0.5,
                "readiness_state": "not_ready",
                "top_blocker": "insufficient_data",
                "last_summary": {},
            },
        )
        return bucket

    def _update_live_microstructure_memory(self, *, market=None, q=None, family=None, spread=None, audit=None, decision=None, decision_reason=None, edge_quality=None):
        market = market if isinstance(market, dict) else {}
        q = q if q is not None else None
        audit = audit if isinstance(audit, dict) else {}
        edge_quality = edge_quality if isinstance(edge_quality, dict) else {}
        family = str(family or self.get_market_family(market) or market.get("family") or market.get("category") or "UNKNOWN").strip().upper() or "UNKNOWN"
        ticker = str(getattr(q, "ticker", "") or market.get("ticker", "") or "").strip()
        if not ticker:
            return None
        now = time.time()
        topbook_snapshot = self._extract_non_targeted_topbook_snapshot(market)
        cached_topbook = getattr(self, "targeted_orderbook_cache", {}).get(ticker, {}) if isinstance(getattr(self, "targeted_orderbook_cache", {}), dict) else {}
        yes_bid = self.to_float(getattr(q, "yes_bid", None), self.to_float(market.get("yes_bid"), None))
        yes_ask = self.to_float(getattr(q, "yes_ask", None), self.to_float(market.get("yes_ask"), None))
        no_bid = self.to_float(getattr(q, "no_bid", None), self.to_float(market.get("no_bid"), None))
        no_ask = self.to_float(getattr(q, "no_ask", None), self.to_float(market.get("no_ask"), None))
        if yes_bid is None:
            yes_bid = self.to_float(market.get("yes_bid_dollars"), None)
        if yes_ask is None:
            yes_ask = self.to_float(market.get("yes_ask_dollars"), None)
        if no_bid is None:
            no_bid = self.to_float(market.get("no_bid_dollars"), None)
        if no_ask is None:
            no_ask = self.to_float(market.get("no_ask_dollars"), None)
        spread_value = self.to_float(spread, None)
        if spread_value is None and yes_bid is not None and yes_ask is not None:
            spread_value = max(0.0, float(yes_ask) - float(yes_bid))
        elif spread_value is None and no_bid is not None and no_ask is not None:
            spread_value = max(0.0, float(no_ask) - float(no_bid))
        spread_value = self.to_float(spread_value, 0.0) or 0.0
        yes_depth = self.to_float(topbook_snapshot.get("yes_top_size"), None)
        no_depth = self.to_float(topbook_snapshot.get("no_top_size"), None)
        if yes_depth is None:
            yes_depth = self.to_float(cached_topbook.get("yes_top_size"), 0.0) or 0.0
        if no_depth is None:
            no_depth = self.to_float(cached_topbook.get("no_top_size"), 0.0) or 0.0
        if yes_depth <= 0.0 and no_depth <= 0.0:
            yes_depth = self.to_float(getattr(q, "yes_bid_size", None), 0.0) or 0.0
            no_depth = self.to_float(getattr(q, "no_bid_size", None), 0.0) or 0.0
        depth_sum = max(0.0, yes_depth) + max(0.0, no_depth)
        imbalance_ratio = 0.0
        if depth_sum > 0:
            imbalance_ratio = abs(max(0.0, yes_depth) - max(0.0, no_depth)) / max(depth_sum, 1.0)
        if max(yes_depth, no_depth) <= 0.0:
            pressure_direction = "unknown"
        elif yes_depth > no_depth * 1.15:
            pressure_direction = "yes_pressure"
        elif no_depth > yes_depth * 1.15:
            pressure_direction = "no_pressure"
        else:
            pressure_direction = "balanced"
        quote_signature = (
            round(yes_bid, 4) if yes_bid is not None else None,
            round(yes_ask, 4) if yes_ask is not None else None,
            round(no_bid, 4) if no_bid is not None else None,
            round(no_ask, 4) if no_ask is not None else None,
        )
        spread_signature = round(spread_value, 4)
        edge_value = self.to_float(audit.get("shadow_arb_edge"), self.to_float(edge_quality.get("shadow_arb_edge"), self.to_float(audit.get("edge_score"), 0.0))) or 0.0
        estimated_cost = self.to_float(audit.get("estimated_cost"), self.to_float(edge_quality.get("estimated_cost"), 0.0)) or 0.0
        edge_above_cost = bool(audit.get("edge_above_cost") or edge_value > estimated_cost)
        unsafe_price = bool(
            audit.get("hard_block")
            or audit.get("resolution_uncertainty")
            or audit.get("reject_reason") in {"unsafe_price", "missing_quotes", "spread_too_wide", "thin_top_book", "weak_open_interest", "unstable_orderbook", "excessive_imbalance"}
            or str(decision_reason or "").strip().lower() in {"unsafe_price", "missing_quotes", "spread_too_wide", "thin_top_book", "weak_open_interest", "unstable_orderbook", "excessive_imbalance"}
        )
        ticker_bucket = self._get_live_microstructure_bucket("live_microstructure_by_ticker", f"ticker:{ticker}")
        family_bucket = self._get_live_microstructure_bucket("live_microstructure_by_family", f"family:{family}")
        self._update_live_microstructure_bucket(
            ticker_bucket,
            now=now,
            ticker=ticker,
            family=family,
            quote_signature=quote_signature,
            spread_signature=spread_signature,
            edge_value=edge_value,
            estimated_cost=estimated_cost,
            yes_depth=yes_depth,
            no_depth=no_depth,
            imbalance_ratio=imbalance_ratio,
            pressure_direction=pressure_direction,
            unsafe_price=unsafe_price,
            edge_above_cost=edge_above_cost,
        )
        self._update_live_microstructure_bucket(
            family_bucket,
            now=now,
            ticker=ticker,
            family=family,
            quote_signature=quote_signature,
            spread_signature=spread_signature,
            edge_value=edge_value,
            estimated_cost=estimated_cost,
            yes_depth=yes_depth,
            no_depth=no_depth,
            imbalance_ratio=imbalance_ratio,
            pressure_direction=pressure_direction,
            unsafe_price=unsafe_price,
            edge_above_cost=edge_above_cost,
        )
        ticker_summary = dict(ticker_bucket.get("last_summary") or {})
        family_summary = self._build_live_microstructure_family_summary(family=family)
        ticker_summary.update(
            {
                "ticker": ticker,
                "family": family,
                "quote_lifetime_seconds": ticker_bucket.get("quote_lifetime_seconds"),
                "spread_lifetime_seconds": ticker_bucket.get("spread_lifetime_seconds"),
                "edge_persistence_seconds": ticker_bucket.get("edge_lifetime_total_seconds"),
                "unsafe_price_seconds": ticker_bucket.get("unsafe_price_total_seconds"),
                "imbalance_ratio": round(self.to_float(ticker_bucket.get("imbalance_ratio"), imbalance_ratio), 4),
                "liquidity_decay_rate": round(self.to_float(ticker_bucket.get("liquidity_decay_rate"), 0.0), 4),
                "pressure_direction": ticker_bucket.get("pressure_direction") or pressure_direction,
                "edge_stability_score": round(self.to_float(ticker_bucket.get("edge_durability_score"), 0.5), 4),
                "execution_survivability_score": round(self.to_float(ticker_bucket.get("execution_survivability_score"), 0.5), 4),
                "market_maker_behavior_score": round(self.to_float(ticker_bucket.get("market_maker_behavior_score"), 0.5), 4),
                "edge_survival_cycles": int(ticker_bucket.get("edge_survival_cycles", 0) or 0),
                "quote_churn_count": int(ticker_bucket.get("quote_churn_count", 0) or 0),
                "quote_withdrawal_count": int(ticker_bucket.get("quote_withdrawal_count", 0) or 0),
                "spread_change_count": int(ticker_bucket.get("spread_change_count", 0) or 0),
                "unsafe_price_cycles": int(ticker_bucket.get("unsafe_price_cycles", 0) or 0),
                "readiness_state": family_summary.get("readiness_state"),
                "top_blocker": family_summary.get("top_blocker"),
            }
        )
        ticker_bucket["last_summary"] = ticker_summary
        family_bucket["last_summary"] = family_summary
        self.last_live_microstructure_summary = ticker_summary
        self.last_live_microstructure_family_summary = family_summary
        self.last_live_microstructure_readiness_state = family_summary.get("readiness_state")
        self._emit_live_microstructure_telemetry(ticker_bucket=ticker_bucket, family_bucket=family_bucket, family=family, ticker=ticker, force=False)
        return ticker_summary

    def _update_live_microstructure_bucket(self, bucket, *, now, ticker=None, family=None, quote_signature=None, spread_signature=None, edge_value=None, estimated_cost=None, yes_depth=None, no_depth=None, imbalance_ratio=None, pressure_direction=None, unsafe_price=False, edge_above_cost=False):
        if not isinstance(bucket, dict):
            return
        if bucket.get("first_seen_timestamp") is None:
            bucket["first_seen_timestamp"] = now
        last_seen = float(bucket.get("last_seen_timestamp", 0.0) or 0.0)
        elapsed = max(0.0, now - last_seen) if last_seen > 0 else 0.0
        bucket["last_seen_timestamp"] = now
        bucket["repeat_count"] = int(bucket.get("repeat_count", 0) or 0) + 1
        bucket["ticker"] = ticker or bucket.get("ticker")
        bucket["family"] = family or bucket.get("family")
        previous_quote = bucket.get("last_quote_signature")
        previous_spread = bucket.get("last_spread_signature")
        previous_edge = bucket.get("last_edge_signature")
        previous_unsafe = bucket.get("last_unsafe_signature")
        previous_depth_sum = self.to_float(bucket.get("last_depth_sum"), None)
        current_depth_sum = max(0.0, self.to_float(yes_depth, 0.0) or 0.0) + max(0.0, self.to_float(no_depth, 0.0) or 0.0)
        if previous_quote is None:
            bucket["quote_lifetime_total_seconds"] = 0.0
            bucket["last_quote_change_ts"] = now
        elif previous_quote != quote_signature:
            bucket["quote_churn_count"] = int(bucket.get("quote_churn_count", 0) or 0) + 1
            bucket["quote_lifetime_total_seconds"] = float(bucket.get("quote_lifetime_total_seconds", 0.0) or 0.0) + elapsed
            bucket["last_quote_change_ts"] = now
        if previous_spread is None:
            bucket["last_spread_change_ts"] = now
        elif previous_spread != spread_signature:
            bucket["spread_change_count"] = int(bucket.get("spread_change_count", 0) or 0) + 1
            if spread_signature > previous_spread:
                bucket["repeated_spread_widening_count"] = int(bucket.get("repeated_spread_widening_count", 0) or 0) + 1
            bucket["spread_lifetime_total_seconds"] = float(bucket.get("spread_lifetime_total_seconds", 0.0) or 0.0) + elapsed
            bucket["last_spread_change_ts"] = now
        if previous_edge is None:
            bucket["last_edge_change_ts"] = now
        elif bool(previous_edge > 0.0) != bool(edge_value > 0.0) or abs(float(previous_edge) - float(edge_value)) >= 0.01:
            if previous_edge > 0.0 and edge_value <= 0.0:
                bucket["edge_collapse_count"] = int(bucket.get("edge_collapse_count", 0) or 0) + 1
            bucket["edge_lifetime_total_seconds"] = float(bucket.get("edge_lifetime_total_seconds", 0.0) or 0.0) + elapsed
            bucket["last_edge_change_ts"] = now
        if previous_unsafe is None:
            bucket["last_unsafe_change_ts"] = now
        elif bool(previous_unsafe) != bool(unsafe_price):
            if previous_unsafe:
                bucket["unsafe_price_total_seconds"] = float(bucket.get("unsafe_price_total_seconds", 0.0) or 0.0) + elapsed
            bucket["last_unsafe_change_ts"] = now
        if previous_depth_sum is not None and previous_depth_sum > 0.0:
            if current_depth_sum <= 0.0:
                bucket["quote_withdrawal_count"] = int(bucket.get("quote_withdrawal_count", 0) or 0) + 1
            if current_depth_sum < previous_depth_sum * 0.75:
                bucket["disappearing_liquidity_count"] = int(bucket.get("disappearing_liquidity_count", 0) or 0) + 1
                decay = (previous_depth_sum - current_depth_sum) / max(previous_depth_sum, 1.0)
                if elapsed > 0:
                    bucket["liquidity_decay_total"] = float(bucket.get("liquidity_decay_total", 0.0) or 0.0) + (decay / elapsed)
                    bucket["liquidity_decay_samples"] = int(bucket.get("liquidity_decay_samples", 0) or 0) + 1
        bucket["last_quote_signature"] = quote_signature
        bucket["last_spread_signature"] = spread_signature
        bucket["last_edge_signature"] = edge_value
        bucket["last_unsafe_signature"] = bool(unsafe_price)
        bucket["best_bid_value"] = quote_signature[0] if isinstance(quote_signature, tuple) else bucket.get("best_bid_value")
        bucket["best_ask_value"] = quote_signature[1] if isinstance(quote_signature, tuple) else bucket.get("best_ask_value")
        bucket["spread_value"] = spread_signature
        bucket["yes_depth_value"] = self.to_float(yes_depth, 0.0) or 0.0
        bucket["no_depth_value"] = self.to_float(no_depth, 0.0) or 0.0
        bucket["last_depth_sum"] = current_depth_sum
        bucket["imbalance_ratio"] = round(self.to_float(imbalance_ratio, 0.0) or 0.0, 4)
        bucket["pressure_direction"] = str(pressure_direction or "unknown").strip().lower() or "unknown"
        bucket["last_imbalance_ratio"] = bucket["imbalance_ratio"]
        bucket.setdefault("imbalance_history", deque(maxlen=12)).append(bucket["imbalance_ratio"])
        bucket.setdefault("spread_history", deque(maxlen=12)).append(spread_signature)
        bucket.setdefault("edge_history", deque(maxlen=12)).append(edge_value)
        bucket.setdefault("quote_history", deque(maxlen=12)).append(quote_signature)
        if unsafe_price:
            bucket["unsafe_price_cycles"] = int(bucket.get("unsafe_price_cycles", 0) or 0) + 1
        if edge_above_cost:
            bucket["edge_survival_cycles"] = int(bucket.get("edge_survival_cycles", 0) or 0) + 1
        if current_depth_sum > 0.0 and previous_depth_sum not in (None, 0.0):
            decay_rate = max(0.0, (previous_depth_sum - current_depth_sum) / max(previous_depth_sum, 1.0))
            bucket["liquidity_decay_rate"] = round(decay_rate / max(elapsed, 1.0), 4) if elapsed > 0 else round(decay_rate, 4)
        else:
            bucket["liquidity_decay_rate"] = round(self.to_float(bucket.get("liquidity_decay_rate"), 0.0), 4)
        quote_lifetime = max(0.0, now - float(bucket.get("last_quote_change_ts") or bucket.get("first_seen_timestamp") or now))
        spread_lifetime = max(0.0, now - float(bucket.get("last_spread_change_ts") or bucket.get("first_seen_timestamp") or now))
        edge_lifetime = max(0.0, now - float(bucket.get("last_edge_change_ts") or bucket.get("first_seen_timestamp") or now)) if edge_above_cost else 0.0
        unsafe_lifetime = max(0.0, now - float(bucket.get("last_unsafe_change_ts") or bucket.get("first_seen_timestamp") or now)) if unsafe_price else 0.0
        bucket["quote_lifetime_seconds"] = round(quote_lifetime, 4)
        bucket["spread_lifetime_seconds"] = round(spread_lifetime, 4)
        bucket["edge_lifetime_seconds"] = round(edge_lifetime, 4)
        bucket["unsafe_price_seconds"] = round(unsafe_lifetime, 4)
        spread_volatility = 0.0
        spread_history = list(bucket.get("spread_history") or [])
        if len(spread_history) >= 2:
            valid_history = [self.to_float(item, None) for item in spread_history if self.to_float(item, None) is not None]
            if len(valid_history) >= 2:
                spread_volatility = max(valid_history) - min(valid_history)
        quote_churn_frequency = bucket["quote_churn_count"] / max(bucket["repeat_count"], 1)
        repeated_spread_widening = bucket.get("repeated_spread_widening_count", 0) or 0
        unstable_topbook = bool(
            bucket["imbalance_ratio"] >= 0.70
            or spread_volatility >= 0.03
            or current_depth_sum <= 0.0
            or repeated_spread_widening >= 2
        )
        aggressive_quote_fade = False
        fake_liquidity = False
        if previous_depth_sum not in (None, 0.0):
            aggressive_quote_fade = bool(bucket["quote_churn_count"] >= 2 and current_depth_sum < max(previous_depth_sum, 0.0) * 0.80)
            fake_liquidity = bool(bucket["disappearing_liquidity_count"] > 0 and bucket["quote_churn_count"] > 0 and current_depth_sum < max(previous_depth_sum, 0.0) * 0.60)
        else:
            aggressive_quote_fade = bool(bucket["quote_churn_count"] >= 3)
        rapid_quote_move = bool(bucket["quote_churn_count"] >= 2 or spread_volatility >= 0.02)
        bucket["rapid_quote_move_count"] = int(bucket.get("rapid_quote_move_count", 0) or 0) + (1 if rapid_quote_move else 0)
        bucket["fake_liquidity_count"] = int(bucket.get("fake_liquidity_count", 0) or 0) + (1 if fake_liquidity else 0)
        bucket["unstable_topbook_count"] = int(bucket.get("unstable_topbook_count", 0) or 0) + (1 if unstable_topbook else 0)
        bucket["aggressive_quote_fade_count"] = int(bucket.get("aggressive_quote_fade_count", 0) or 0) + (1 if aggressive_quote_fade else 0)
        bucket["spread_stability_score"] = round(max(0.0, min(1.0, 1.0 - min(spread_volatility * 12.0, 1.0) - min(quote_churn_frequency * 0.25, 0.4))), 4)
        edge_duration = bucket["edge_lifetime_seconds"] if edge_above_cost else 0.0
        bucket["edge_durability_score"] = round(max(0.0, min(1.0, (
            (1.0 if edge_above_cost else 0.0) * 0.35
            + min(edge_duration / 240.0, 1.0) * 0.35
            + max(0.0, 1.0 - min(bucket.get("edge_collapse_count", 0) / max(bucket["repeat_count"], 1), 1.0)) * 0.30
        ))), 4)
        decay_component = max(0.0, min(bucket["liquidity_decay_rate"] * 4.0, 1.0))
        imbalance_penalty = min(bucket["imbalance_ratio"], 1.0)
        churn_penalty = min(quote_churn_frequency, 1.0)
        unsafe_penalty = 1.0 if unsafe_price else min(bucket["unsafe_price_cycles"] / max(bucket["repeat_count"], 1), 1.0)
        bucket["liquidity_reliability_score"] = round(max(0.0, min(1.0, 1.0 - (decay_component * 0.45 + imbalance_penalty * 0.25 + churn_penalty * 0.20 + unsafe_penalty * 0.10))), 4)
        behavior_flags = sum(1 for flag in (rapid_quote_move, fake_liquidity, unstable_topbook, aggressive_quote_fade, repeated_spread_widening >= 2) if flag)
        bucket["market_maker_behavior_score"] = round(max(0.0, min(1.0, 1.0 - (behavior_flags / 5.0))), 4)
        bucket["execution_survivability_score"] = round(max(0.0, min(1.0, (
            bucket["spread_stability_score"] * 0.30
            + bucket["edge_durability_score"] * 0.30
            + bucket["liquidity_reliability_score"] * 0.25
            + max(0.0, 1.0 - bucket["imbalance_ratio"]) * 0.10
            + max(0.0, 1.0 - min(bucket["quote_churn_count"] / max(bucket["repeat_count"], 1), 1.0)) * 0.05
        ))), 4)
        bucket["readiness_state"], bucket["top_blocker"] = self._classify_live_microstructure_readiness(bucket)

    def _classify_live_microstructure_readiness(self, bucket):
        bucket = bucket if isinstance(bucket, dict) else {}
        repeat_count = int(bucket.get("repeat_count", 0) or 0)
        quote_churn_frequency = self.to_float(bucket.get("quote_churn_count"), 0.0) / max(repeat_count, 1)
        execution_survivability = self.to_float(bucket.get("execution_survivability_score"), 0.0) or 0.0
        edge_durability = self.to_float(bucket.get("edge_durability_score"), 0.0) or 0.0
        liquidity_reliability = self.to_float(bucket.get("liquidity_reliability_score"), 0.0) or 0.0
        spread_stability = self.to_float(bucket.get("spread_stability_score"), 0.0) or 0.0
        unstable_topbook_count = int(bucket.get("unstable_topbook_count", 0) or 0)
        fake_liquidity_count = int(bucket.get("fake_liquidity_count", 0) or 0)
        quote_withdrawal_count = int(bucket.get("quote_withdrawal_count", 0) or 0)
        if repeat_count < 2:
            return "not_ready", "insufficient_data"
        if execution_survivability < 0.35 or edge_durability < 0.25:
            return "unstable", "edge_or_survivability_weak"
        if quote_churn_frequency >= 0.65 or unstable_topbook_count > max(repeat_count // 2, 0) or fake_liquidity_count > 0:
            return "unstable", "quote_churn_or_fake_liquidity"
        if execution_survivability < 0.55 or liquidity_reliability < 0.45 or spread_stability < 0.45:
            return "stabilizing", "microstructure_settling"
        if execution_survivability < 0.75 or edge_durability < 0.70 or liquidity_reliability < 0.65:
            return "candidate_ready", "building_durability"
        if quote_withdrawal_count == 0 and liquidity_reliability >= 0.72 and spread_stability >= 0.70:
            return "canary_ready", "stable_microstructure"
        return "candidate_ready", "awaiting_final_stability"

    def _build_live_microstructure_family_summary(self, family=None):
        family = str(family or "UNKNOWN").strip().upper() or "UNKNOWN"
        family_buckets = []
        ticker_buckets = getattr(self, "live_microstructure_by_ticker", {}) or {}
        if isinstance(ticker_buckets, dict):
            for bucket in ticker_buckets.values():
                if not isinstance(bucket, dict):
                    continue
                if str(bucket.get("family") or "").strip().upper() == family:
                    family_buckets.append(bucket)
        if not family_buckets:
            family_bucket = self._get_live_microstructure_bucket("live_microstructure_by_family", f"family:{family}")
            summary = {
                "family": family,
                "observations": 0,
                "avg_spread_stability": 0.0,
                "avg_edge_durability": 0.0,
                "avg_survivability": 0.0,
                "quote_churn_frequency": 0.0,
                "liquidity_reliability": 0.0,
                "readiness_state": "not_ready",
                "top_blocker": "insufficient_data",
            }
            family_bucket["last_summary"] = summary
            return summary
        observations = sum(int(bucket.get("repeat_count", 0) or 0) for bucket in family_buckets)
        count = max(len(family_buckets), 1)
        avg_spread_stability = sum(self.to_float(bucket.get("spread_stability_score"), 0.0) or 0.0 for bucket in family_buckets) / count
        avg_edge_durability = sum(self.to_float(bucket.get("edge_durability_score"), 0.0) or 0.0 for bucket in family_buckets) / count
        avg_survivability = sum(self.to_float(bucket.get("execution_survivability_score"), 0.0) or 0.0 for bucket in family_buckets) / count
        quote_churn_frequency = sum((self.to_float(bucket.get("quote_churn_count"), 0.0) or 0.0) / max(int(bucket.get("repeat_count", 0) or 0), 1) for bucket in family_buckets) / count
        liquidity_reliability = sum(self.to_float(bucket.get("liquidity_reliability_score"), 0.0) or 0.0 for bucket in family_buckets) / count
        unstable_rate = sum(1 for bucket in family_buckets if int(bucket.get("unstable_topbook_count", 0) or 0) > 0) / count
        fake_liquidity_rate = sum(1 for bucket in family_buckets if int(bucket.get("fake_liquidity_count", 0) or 0) > 0) / count
        quote_withdrawal_rate = sum(1 for bucket in family_buckets if int(bucket.get("quote_withdrawal_count", 0) or 0) > 0) / count
        if observations < 2:
            readiness_state = "not_ready"
            top_blocker = "insufficient_data"
        elif unstable_rate >= 0.60 or fake_liquidity_rate >= 0.35 or quote_churn_frequency >= 0.65:
            readiness_state = "unstable"
            top_blocker = "quote_churn_or_fake_liquidity"
        elif avg_survivability < 0.55 or avg_edge_durability < 0.55 or liquidity_reliability < 0.55:
            readiness_state = "stabilizing"
            top_blocker = "microstructure_settling"
        elif avg_survivability < 0.75 or avg_edge_durability < 0.75 or liquidity_reliability < 0.72:
            readiness_state = "candidate_ready"
            top_blocker = "building_durability"
        else:
            readiness_state = "canary_ready"
            top_blocker = "stable_microstructure"
        summary = {
            "family": family,
            "observations": int(observations),
            "avg_spread_stability": round(avg_spread_stability, 4),
            "avg_edge_durability": round(avg_edge_durability, 4),
            "avg_survivability": round(avg_survivability, 4),
            "quote_churn_frequency": round(quote_churn_frequency, 4),
            "liquidity_reliability": round(liquidity_reliability, 4),
            "unstable_rate": round(unstable_rate, 4),
            "fake_liquidity_rate": round(fake_liquidity_rate, 4),
            "quote_withdrawal_rate": round(quote_withdrawal_rate, 4),
            "readiness_state": readiness_state,
            "top_blocker": top_blocker,
        }
        family_bucket = self._get_live_microstructure_bucket("live_microstructure_by_family", f"family:{family}")
        family_bucket["last_summary"] = summary
        return summary

    def _build_live_microstructure_overall_summary(self):
        family_container = getattr(self, "live_microstructure_by_family", {}) or {}
        family_summaries = []
        if isinstance(family_container, dict):
            for bucket in family_container.values():
                if not isinstance(bucket, dict):
                    continue
                summary = bucket.get("last_summary") if isinstance(bucket.get("last_summary"), dict) else {}
                if not summary:
                    continue
                family_summaries.append(summary)
        if not family_summaries:
            return {
                "scope": "overall",
                "observations": 0,
                "avg_spread_stability": 0.0,
                "avg_edge_durability": 0.0,
                "avg_survivability": 0.0,
                "quote_churn_frequency": 0.0,
                "liquidity_reliability": 0.0,
                "readiness_state": "not_ready",
                "top_blocker": "insufficient_data",
            }
        total_observations = sum(int(summary.get("observations", 0) or 0) for summary in family_summaries)
        count = max(len(family_summaries), 1)
        avg_spread_stability = sum(self.to_float(summary.get("avg_spread_stability"), 0.0) or 0.0 for summary in family_summaries) / count
        avg_edge_durability = sum(self.to_float(summary.get("avg_edge_durability"), 0.0) or 0.0 for summary in family_summaries) / count
        avg_survivability = sum(self.to_float(summary.get("avg_survivability"), 0.0) or 0.0 for summary in family_summaries) / count
        quote_churn_frequency = sum(self.to_float(summary.get("quote_churn_frequency"), 0.0) or 0.0 for summary in family_summaries) / count
        liquidity_reliability = sum(self.to_float(summary.get("liquidity_reliability"), 0.0) or 0.0 for summary in family_summaries) / count
        unstable_rate = sum(self.to_float(summary.get("unstable_rate"), 0.0) or 0.0 for summary in family_summaries) / count
        fake_liquidity_rate = sum(self.to_float(summary.get("fake_liquidity_rate"), 0.0) or 0.0 for summary in family_summaries) / count
        quote_withdrawal_rate = sum(self.to_float(summary.get("quote_withdrawal_rate"), 0.0) or 0.0 for summary in family_summaries) / count
        readiness_rank = {"not_ready": 0, "unstable": 1, "stabilizing": 2, "candidate_ready": 3, "canary_ready": 4}
        top_blocker = "stable_microstructure"
        readiness_state = "not_ready"
        if total_observations < 2:
            top_blocker = "insufficient_data"
        else:
            if unstable_rate >= 0.60 or fake_liquidity_rate >= 0.35 or quote_churn_frequency >= 0.65:
                readiness_state = "unstable"
                top_blocker = "quote_churn_or_fake_liquidity"
            elif avg_survivability < 0.55 or avg_edge_durability < 0.55 or liquidity_reliability < 0.55:
                readiness_state = "stabilizing"
                top_blocker = "microstructure_settling"
            elif avg_survivability < 0.75 or avg_edge_durability < 0.75 or liquidity_reliability < 0.72:
                readiness_state = "candidate_ready"
                top_blocker = "building_durability"
            else:
                readiness_state = "canary_ready"
                top_blocker = "stable_microstructure"
        summary = {
            "scope": "overall",
            "observations": int(total_observations),
            "avg_spread_stability": round(avg_spread_stability, 4),
            "avg_edge_durability": round(avg_edge_durability, 4),
            "avg_survivability": round(avg_survivability, 4),
            "quote_churn_frequency": round(quote_churn_frequency, 4),
            "liquidity_reliability": round(liquidity_reliability, 4),
            "unstable_rate": round(unstable_rate, 4),
            "fake_liquidity_rate": round(fake_liquidity_rate, 4),
            "quote_withdrawal_rate": round(quote_withdrawal_rate, 4),
            "readiness_state": readiness_state,
            "top_blocker": top_blocker,
            "readiness_rank": readiness_rank.get(readiness_state, 0),
        }
        return summary

    def _get_reactivation_watchlist_bucket(self, container_name, key):
        buckets = getattr(self, container_name, None)
        if not isinstance(buckets, dict):
            buckets = {}
            setattr(self, container_name, buckets)
        bucket = buckets.setdefault(
            key,
            {
                "first_seen_time": None,
                "last_seen_time": 0.0,
                "improving_cycles": 0,
                "unstable_cycles": 0,
                "best_reactivation_score": 0.0,
                "latest_reactivation_state": "dead",
                "last_reactivation_score": 0.0,
                "ticker": None,
                "family": None,
                "state_history": deque(maxlen=12),
                "score_history": deque(maxlen=12),
                "last_summary": {},
            },
        )
        return bucket

    def _safe_ratio_score(self, numerator, denominator, cap=1.0):
        try:
            denom = float(denominator)
            num = float(numerator)
        except (TypeError, ValueError):
            return 0.0
        if denom <= 0:
            return 0.0
        return max(0.0, min(float(cap), num / denom))

    def _compute_reactivation_score(self, *, ticker_bucket=None, family_summary=None, audit=None, decision_reason=None):
        ticker_bucket = ticker_bucket if isinstance(ticker_bucket, dict) else {}
        family_summary = family_summary if isinstance(family_summary, dict) else {}
        audit = audit if isinstance(audit, dict) else {}
        execution_survivability_score = self.to_float(ticker_bucket.get("execution_survivability_score"), self.to_float(family_summary.get("avg_survivability"), 0.0)) or 0.0
        edge_durability_score = self.to_float(ticker_bucket.get("edge_durability_score"), self.to_float(family_summary.get("avg_edge_durability"), 0.0)) or 0.0
        quote_lifetime_seconds = self.to_float(ticker_bucket.get("quote_lifetime_seconds"), 0.0) or 0.0
        spread_lifetime_seconds = self.to_float(ticker_bucket.get("spread_lifetime_seconds"), 0.0) or 0.0
        imbalance_ratio = self.to_float(ticker_bucket.get("imbalance_ratio"), 0.0) or 0.0
        family_microstructure_score = max(
            0.0,
            min(
                1.0,
                (
                    self.to_float(family_summary.get("avg_survivability"), 0.0) * 0.45
                    + self.to_float(family_summary.get("avg_edge_durability"), 0.0) * 0.25
                    + self.to_float(family_summary.get("avg_spread_stability"), 0.0) * 0.20
                    + self.to_float(family_summary.get("liquidity_reliability"), 0.0) * 0.10
                ),
            ),
        )
        spread_lifetime_score = min(1.0, max(0.0, spread_lifetime_seconds / 240.0))
        quote_lifetime_score = min(1.0, max(0.0, quote_lifetime_seconds / 240.0))
        orderbook_imbalance_score = max(0.0, min(1.0, 1.0 - imbalance_ratio))
        base_score = (
            execution_survivability_score * 0.30
            + edge_durability_score * 0.20
            + spread_lifetime_score * 0.10
            + quote_lifetime_score * 0.10
            + orderbook_imbalance_score * 0.15
            + family_microstructure_score * 0.15
        )
        unstable_penalty = 0.0
        reject_reason = str(audit.get("reject_reason") or decision_reason or "").strip().lower()
        if reject_reason in {"missing_quotes", "unsafe_price", "spread_too_wide", "thin_top_book", "weak_open_interest", "unstable_orderbook", "excessive_imbalance"}:
            unstable_penalty += 0.15
        if bool(audit.get("hard_block")):
            unstable_penalty += 0.10
        if self.to_float(ticker_bucket.get("unstable_topbook_count"), 0.0) > 0:
            unstable_penalty += 0.10
        if self.to_float(ticker_bucket.get("fake_liquidity_count"), 0.0) > 0:
            unstable_penalty += 0.10
        if self.to_float(ticker_bucket.get("quote_withdrawal_count"), 0.0) > 0:
            unstable_penalty += 0.05
        score = max(0.0, min(1.0, base_score - unstable_penalty))
        return {
            "reactivation_score": round(score, 4),
            "execution_survivability_score": round(execution_survivability_score, 4),
            "edge_durability_score": round(edge_durability_score, 4),
            "spread_lifetime_score": round(spread_lifetime_score, 4),
            "quote_lifetime_score": round(quote_lifetime_score, 4),
            "orderbook_imbalance_score": round(orderbook_imbalance_score, 4),
            "family_microstructure_score": round(family_microstructure_score, 4),
        }

    def _classify_reactivation_state(self, *, reactivation_score=0.0, ticker_bucket=None, family_summary=None, audit=None, watchlist_bucket=None):
        ticker_bucket = ticker_bucket if isinstance(ticker_bucket, dict) else {}
        family_summary = family_summary if isinstance(family_summary, dict) else {}
        audit = audit if isinstance(audit, dict) else {}
        watchlist_bucket = watchlist_bucket if isinstance(watchlist_bucket, dict) else {}
        repeat_count = int(ticker_bucket.get("repeat_count", 0) or 0)
        quote_churn = int(ticker_bucket.get("quote_churn_count", 0) or 0)
        unstable_cycles = int(watchlist_bucket.get("unstable_cycles", 0) or 0)
        improving_cycles = int(watchlist_bucket.get("improving_cycles", 0) or 0)
        micro_ready = str(ticker_bucket.get("readiness_state") or family_summary.get("readiness_state") or "not_ready").strip().lower()
        reject_reason = str(audit.get("reject_reason") or "").strip().lower()
        if repeat_count < 2 or reactivation_score < 0.20:
            return "dead"
        if micro_ready == "unstable" or reject_reason in {"missing_quotes", "unsafe_price", "spread_too_wide", "thin_top_book", "weak_open_interest", "unstable_orderbook", "excessive_imbalance"}:
            return "unstable"
        if reactivation_score < 0.45:
            return "watchlist"
        if improving_cycles >= 2 and reactivation_score >= 0.55:
            return "improving"
        if reactivation_score >= 0.75 and improving_cycles >= 1 and unstable_cycles == 0 and quote_churn <= max(1, repeat_count // 3):
            return "reactivation_candidate"
        if micro_ready in {"candidate_ready", "canary_ready"} and reactivation_score >= 0.60:
            return "reactivation_candidate"
        if reactivation_score >= 0.50:
            return "improving"
        return "watchlist"

    def _update_reactivation_watchlist(self, *, ticker=None, family=None, ticker_bucket=None, family_summary=None, audit=None, decision_reason=None):
        ticker = str(ticker or "").strip()
        family = str(family or "").strip().upper() or "UNKNOWN"
        if not ticker:
            return None
        ticker_bucket = ticker_bucket if isinstance(ticker_bucket, dict) else {}
        family_summary = family_summary if isinstance(family_summary, dict) else {}
        audit = audit if isinstance(audit, dict) else {}
        now = time.time()
        ticker_key = f"ticker:{ticker}"
        family_key = f"family:{family}"
        score_payload = self._compute_reactivation_score(
            ticker_bucket=ticker_bucket,
            family_summary=family_summary,
            audit=audit,
            decision_reason=decision_reason,
        )
        watchlist_bucket = self._get_reactivation_watchlist_bucket("reactivation_watchlist_by_ticker", ticker_key)
        family_watchlist_bucket = self._get_reactivation_watchlist_bucket("reactivation_watchlist_by_family", family_key)
        state = self._classify_reactivation_state(
            reactivation_score=score_payload.get("reactivation_score", 0.0),
            ticker_bucket=ticker_bucket,
            family_summary=family_summary,
            audit=audit,
            watchlist_bucket=watchlist_bucket,
        )
        previous_score = self.to_float(watchlist_bucket.get("last_reactivation_score"), None)
        previous_state = str(watchlist_bucket.get("latest_reactivation_state") or "dead").strip().lower()
        watchlist_bucket["first_seen_time"] = watchlist_bucket.get("first_seen_time") or now
        watchlist_bucket["last_seen_time"] = now
        watchlist_bucket["ticker"] = ticker
        watchlist_bucket["family"] = family
        watchlist_bucket["last_reactivation_score"] = score_payload.get("reactivation_score", 0.0)
        watchlist_bucket["latest_reactivation_state"] = state
        watchlist_bucket["best_reactivation_score"] = max(self.to_float(watchlist_bucket.get("best_reactivation_score"), 0.0) or 0.0, score_payload.get("reactivation_score", 0.0) or 0.0)
        if state in {"watchlist", "improving", "reactivation_candidate"}:
            if previous_score is None or score_payload.get("reactivation_score", 0.0) >= previous_score - 0.01:
                watchlist_bucket["improving_cycles"] = int(watchlist_bucket.get("improving_cycles", 0) or 0) + 1
        if state in {"unstable", "dead"}:
            watchlist_bucket["unstable_cycles"] = int(watchlist_bucket.get("unstable_cycles", 0) or 0) + 1
        watchlist_bucket.setdefault("state_history", deque(maxlen=12)).append(state)
        watchlist_bucket.setdefault("score_history", deque(maxlen=12)).append(score_payload.get("reactivation_score", 0.0))
        family_watchlist_bucket["first_seen_time"] = family_watchlist_bucket.get("first_seen_time") or now
        family_watchlist_bucket["last_seen_time"] = now
        family_watchlist_bucket["ticker"] = ticker
        family_watchlist_bucket["family"] = family
        family_watchlist_bucket["last_reactivation_score"] = score_payload.get("reactivation_score", 0.0)
        family_watchlist_bucket["latest_reactivation_state"] = state
        family_watchlist_bucket["best_reactivation_score"] = max(self.to_float(family_watchlist_bucket.get("best_reactivation_score"), 0.0) or 0.0, score_payload.get("reactivation_score", 0.0) or 0.0)
        if state in {"watchlist", "improving", "reactivation_candidate"}:
            if previous_score is None or score_payload.get("reactivation_score", 0.0) >= previous_score - 0.01:
                family_watchlist_bucket["improving_cycles"] = int(family_watchlist_bucket.get("improving_cycles", 0) or 0) + 1
        if state in {"unstable", "dead"}:
            family_watchlist_bucket["unstable_cycles"] = int(family_watchlist_bucket.get("unstable_cycles", 0) or 0) + 1
        family_watchlist_bucket.setdefault("state_history", deque(maxlen=12)).append(state)
        family_watchlist_bucket.setdefault("score_history", deque(maxlen=12)).append(score_payload.get("reactivation_score", 0.0))
        summary = {
            "ticker": ticker,
            "family": family,
            **score_payload,
            "latest_reactivation_state": state,
            "improving_cycles": int(watchlist_bucket.get("improving_cycles", 0) or 0),
            "unstable_cycles": int(watchlist_bucket.get("unstable_cycles", 0) or 0),
            "best_reactivation_score": round(self.to_float(watchlist_bucket.get("best_reactivation_score"), 0.0) or 0.0, 4),
            "first_seen_time": watchlist_bucket.get("first_seen_time"),
            "last_seen_time": watchlist_bucket.get("last_seen_time"),
        }
        watchlist_bucket["last_summary"] = summary
        family_watchlist_bucket["last_summary"] = dict(summary)
        self.last_reactivation_summary = summary
        self.last_reactivation_family_summary = dict(family_watchlist_bucket["last_summary"] or {})
        self._emit_reactivation_telemetry(ticker_bucket=watchlist_bucket, family_bucket=family_watchlist_bucket, force=False)
        return summary

    def _build_reactivation_watchlist_summary(self):
        ticker_watchlist = getattr(self, "reactivation_watchlist_by_ticker", {}) or {}
        family_watchlist = getattr(self, "reactivation_watchlist_by_family", {}) or {}
        ticker_buckets = [bucket for bucket in ticker_watchlist.values() if isinstance(bucket, dict)]
        family_buckets = [bucket for bucket in family_watchlist.values() if isinstance(bucket, dict)]
        improving_candidates_count = sum(1 for bucket in ticker_buckets if str(bucket.get("latest_reactivation_state") or "").strip().lower() == "improving")
        reactivation_candidates_count = sum(1 for bucket in ticker_buckets if str(bucket.get("latest_reactivation_state") or "").strip().lower() == "reactivation_candidate")
        unstable_candidates_count = sum(1 for bucket in ticker_buckets if str(bucket.get("latest_reactivation_state") or "").strip().lower() == "unstable")
        best_bucket = None
        if ticker_buckets:
            best_bucket = max(
                ticker_buckets,
                key=lambda bucket: (
                    self.to_float(bucket.get("best_reactivation_score"), 0.0),
                    int(bucket.get("improving_cycles", 0) or 0),
                    -int(bucket.get("unstable_cycles", 0) or 0),
                ),
            )
        best_reactivation_ticker = None
        best_reactivation_family = None
        best_reactivation_score = 0.0
        if isinstance(best_bucket, dict):
            best_reactivation_ticker = str(best_bucket.get("ticker") or "").strip() or None
            best_reactivation_family = str(best_bucket.get("family") or "").strip() or None
            best_reactivation_score = round(self.to_float(best_bucket.get("best_reactivation_score"), 0.0) or 0.0, 4)
        overall_score = 0.0
        if ticker_buckets:
            overall_score = sum(self.to_float(bucket.get("best_reactivation_score"), 0.0) or 0.0 for bucket in ticker_buckets) / max(len(ticker_buckets), 1)
        summary = {
            "ticker_watchlist_count": len(ticker_buckets),
            "family_watchlist_count": len(family_buckets),
            "reactivation_candidates_count": int(reactivation_candidates_count),
            "improving_candidates_count": int(improving_candidates_count),
            "unstable_candidates_count": int(unstable_candidates_count),
            "best_reactivation_ticker": best_reactivation_ticker,
            "best_reactivation_family": best_reactivation_family,
            "best_reactivation_score": best_reactivation_score,
            "overall_reactivation_score": round(overall_score, 4),
            "watchlist_top_states": Counter(str(bucket.get("latest_reactivation_state") or "dead").strip().lower() for bucket in ticker_buckets).most_common(5),
        }
        return summary

    def _emit_reactivation_telemetry(self, *, ticker_bucket=None, family_bucket=None, force=False):
        ticker_bucket = ticker_bucket if isinstance(ticker_bucket, dict) else {}
        family_bucket = family_bucket if isinstance(family_bucket, dict) else {}
        ticker = str(ticker_bucket.get("ticker") or "").strip()
        family = str(family_bucket.get("family") or ticker_bucket.get("family") or "").strip().upper() or "UNKNOWN"
        now = time.time()
        score_payload = ticker_bucket.get("last_summary") if isinstance(ticker_bucket.get("last_summary"), dict) else {}
        if not score_payload:
            score_payload = {
                "ticker": ticker or "unknown",
                "family": family,
                "reactivation_score": round(self.to_float(ticker_bucket.get("best_reactivation_score"), 0.0) or 0.0, 4),
                "execution_survivability_score": round(self.to_float(ticker_bucket.get("execution_survivability_score"), 0.0) or 0.0, 4),
                "edge_durability_score": round(self.to_float(ticker_bucket.get("edge_durability_score"), 0.0) or 0.0, 4),
                "spread_lifetime_score": round(min(1.0, max(0.0, self.to_float(ticker_bucket.get("spread_lifetime_seconds"), 0.0) / 240.0)), 4),
                "quote_lifetime_score": round(min(1.0, max(0.0, self.to_float(ticker_bucket.get("quote_lifetime_seconds"), 0.0) / 240.0)), 4),
                "orderbook_imbalance_score": round(max(0.0, min(1.0, 1.0 - (self.to_float(ticker_bucket.get("imbalance_ratio"), 0.0) or 0.0))), 4),
                "family_microstructure_score": round(self.to_float(family_bucket.get("best_reactivation_score"), 0.0) or 0.0, 4),
                "latest_reactivation_state": str(ticker_bucket.get("latest_reactivation_state") or "dead").strip().lower(),
            }
        emit_key = ticker or family
        last_emit = float(getattr(self, "reactivation_last_signal_ts_by_key", {}).get(emit_key, 0.0) or 0.0)
        if not force and ticker and (now - last_emit) < 120.0:
            return None
        if ticker:
            self.reactivation_last_signal_ts_by_key[ticker] = now
        if family:
            self.reactivation_last_signal_ts_by_key[family] = now
        print("[LIVE-REACTIVATION-SCORE] " + json.dumps(score_payload, sort_keys=True, default=str))
        print(
            "[LIVE-REACTIVATION-STATE] "
            + json.dumps(
                {
                    "ticker": ticker or score_payload.get("ticker"),
                    "family": family,
                    "latest_reactivation_state": score_payload.get("latest_reactivation_state"),
                    "reactivation_score": score_payload.get("reactivation_score"),
                    "improving_cycles": int(ticker_bucket.get("improving_cycles", 0) or 0),
                    "unstable_cycles": int(ticker_bucket.get("unstable_cycles", 0) or 0),
                    "best_reactivation_score": round(self.to_float(ticker_bucket.get("best_reactivation_score"), 0.0) or 0.0, 4),
                },
                sort_keys=True,
                default=str,
            )
        )
        watchlist_summary = self._build_reactivation_watchlist_summary()
        self.last_reactivation_overall_summary = watchlist_summary
        print("[LIVE-REACTIVATION-WATCHLIST] " + json.dumps(watchlist_summary, sort_keys=True, default=str))
        return score_payload

    def _get_adaptive_priority_watchlist_bucket(self, container_name, key):
        buckets = getattr(self, container_name, None)
        if not isinstance(buckets, dict):
            buckets = {}
            setattr(self, container_name, buckets)
        bucket = buckets.setdefault(
            key,
            {
                "first_seen_time": None,
                "last_seen_time": 0.0,
                "best_priority_score": 0.0,
                "avg_priority_score": 0.0,
                "latest_priority_bucket": "ignore",
                "latest_reactivation_state": "dead",
                "ticker": None,
                "family": None,
                "improving_hits": 0.0,
                "decaying_hits": 0.0,
                "unstable_hits": 0.0,
                "stable_hits": 0.0,
                "persistence_score": 0.0,
                "decay_score": 0.0,
                "improvement_velocity": 0.0,
                "promotion_strength": 0.0,
                "demotion_strength": 0.0,
                "promotion_multiplier": 0.0,
                "demotion_multiplier": 0.0,
                "improving_count": 0,
                "high_priority_count": 0,
                "priority_watch_count": 0,
                "low_priority_count": 0,
                "monitor_count": 0,
                "ignore_count": 0,
                "score_history": deque(maxlen=24),
                "bucket_history": deque(maxlen=24),
                "blocker_history": deque(maxlen=24),
                "last_summary": {},
            },
        )
        return bucket

    def _compute_adaptive_priority_score(self, *, ticker_bucket=None, family_summary=None, reactivation_summary=None, recent_blocker_reason=None, audit=None, decision_reason=None):
        ticker_bucket = ticker_bucket if isinstance(ticker_bucket, dict) else {}
        family_summary = family_summary if isinstance(family_summary, dict) else {}
        reactivation_summary = reactivation_summary if isinstance(reactivation_summary, dict) else {}
        audit = audit if isinstance(audit, dict) else {}
        reactivation_score = self.to_float(
            ticker_bucket.get("reactivation_score"),
            self.to_float(reactivation_summary.get("reactivation_score"), self.to_float(family_summary.get("best_reactivation_score"), 0.0)),
        ) or 0.0
        execution_survivability_score = self.to_float(
            ticker_bucket.get("execution_survivability_score"),
            self.to_float(family_summary.get("avg_survivability"), 0.0),
        ) or 0.0
        edge_durability_score = self.to_float(
            ticker_bucket.get("edge_durability_score"),
            self.to_float(family_summary.get("avg_edge_durability"), 0.0),
        ) or 0.0
        quote_lifetime_seconds = self.to_float(ticker_bucket.get("quote_lifetime_seconds"), 0.0) or 0.0
        spread_lifetime_seconds = self.to_float(ticker_bucket.get("spread_lifetime_seconds"), 0.0) or 0.0
        family_microstructure_score = max(
            0.0,
            min(
                1.0,
                (
                    self.to_float(family_summary.get("avg_survivability"), 0.0) * 0.40
                    + self.to_float(family_summary.get("avg_edge_durability"), 0.0) * 0.25
                    + self.to_float(family_summary.get("avg_spread_stability"), 0.0) * 0.20
                    + self.to_float(family_summary.get("liquidity_reliability"), 0.0) * 0.15
                ),
            ),
        )
        spread_lifetime_score = min(1.0, max(0.0, spread_lifetime_seconds / 240.0))
        quote_lifetime_score = min(1.0, max(0.0, quote_lifetime_seconds / 240.0))
        blocker_history = list(ticker_bucket.get("blocker_history") or [])
        candidate_blocker = str(
            recent_blocker_reason
            or audit.get("reject_reason")
            or decision_reason
            or ticker_bucket.get("recent_blocker_reason")
            or family_summary.get("top_blocker")
            or reactivation_summary.get("top_blocker")
            or ""
        ).strip().lower()
        if candidate_blocker:
            if not blocker_history or blocker_history[-1] != candidate_blocker:
                blocker_history.append(candidate_blocker)
        severe_blockers = {
            "missing_quotes",
            "unsafe_price",
            "edge_below_cost",
            "low_volume",
            "spread_too_wide",
            "thin_top_book",
            "weak_open_interest",
            "unstable_orderbook",
            "excessive_imbalance",
        }
        moderate_blockers = {
            "low_liquidity",
            "liquidity_below_synthetic_floor",
            "resolution_uncertainty",
            "timing_penalty",
            "duplicate",
            "cooldown",
            "stale_signal",
        }
        recent_blocker_count = sum(1 for reason in blocker_history[-8:] if reason in severe_blockers)
        repeated_blocker_count = sum(1 for reason in blocker_history[-8:] if reason in moderate_blockers)
        blocker_pressure = 0.0
        if candidate_blocker in severe_blockers:
            blocker_pressure += 0.18
        elif candidate_blocker in moderate_blockers:
            blocker_pressure += 0.10
        blocker_pressure += min(0.35, recent_blocker_count * 0.04 + repeated_blocker_count * 0.02 + max(0, len(blocker_history) - 3) * 0.01)
        recent_blocker_history_score = max(0.0, 1.0 - blocker_pressure)
        adaptive_priority_score = (
            reactivation_score * 0.24
            + execution_survivability_score * 0.22
            + edge_durability_score * 0.18
            + family_microstructure_score * 0.14
            + quote_lifetime_score * 0.08
            + spread_lifetime_score * 0.08
            + recent_blocker_history_score * 0.06
        )
        adaptive_priority_score = max(0.0, min(1.0, adaptive_priority_score))
        return {
            "adaptive_priority_score": round(adaptive_priority_score, 4),
            "reactivation_score": round(reactivation_score, 4),
            "execution_survivability_score": round(execution_survivability_score, 4),
            "edge_durability_score": round(edge_durability_score, 4),
            "family_microstructure_score": round(family_microstructure_score, 4),
            "quote_lifetime_score": round(quote_lifetime_score, 4),
            "spread_lifetime_score": round(spread_lifetime_score, 4),
            "recent_blocker_history_score": round(recent_blocker_history_score, 4),
            "recent_blocker_reason": candidate_blocker or None,
        }

    def compute_adaptive_priority_score(
        self,
        *,
        predictive_regime_score=None,
        regime_transition=None,
        improvement_velocity=None,
        edge_durability_trend=None,
        quote_stability_trend=None,
        orderbook_consistency_trend=None,
        family_learning_trend=None,
        persistence_score=None,
        decay_score=None,
        memory_bucket=None,
        base_priority_score=None,
    ):
        memory_bucket = memory_bucket if isinstance(memory_bucket, dict) else {}
        predictive_regime_score = self._clamp(self.to_float(predictive_regime_score, 0.0))
        base_priority_score = self._clamp(self.to_float(base_priority_score, predictive_regime_score))
        regime_transition = str(regime_transition or "unknown").strip().lower()
        improvement_velocity = self._clamp(self.to_float(improvement_velocity, self.to_float(memory_bucket.get("improvement_velocity"), 0.0)))
        edge_durability_trend = self._clamp(self.to_float(edge_durability_trend, 0.0))
        quote_stability_trend = self._clamp(self.to_float(quote_stability_trend, 0.0))
        orderbook_consistency_trend = self._clamp(self.to_float(orderbook_consistency_trend, 0.0))
        family_learning_trend = self._clamp(self.to_float(family_learning_trend, 0.0))
        persistence_score = self._clamp(self.to_float(persistence_score, self.to_float(memory_bucket.get("persistence_score"), 0.0)))
        decay_score = self._clamp(self.to_float(decay_score, self.to_float(memory_bucket.get("decay_score"), 0.0)))
        stable_bias = self._clamp(
            (
                base_priority_score * 0.22
                + predictive_regime_score * 0.18
                + persistence_score * 0.20
                + edge_durability_trend * 0.15
                + quote_stability_trend * 0.12
                + orderbook_consistency_trend * 0.08
                + family_learning_trend * 0.05
            )
        )
        unstable_bias = self._clamp(
            (
                decay_score * 0.26
                + max(0.0, 1.0 - edge_durability_trend) * 0.18
                + max(0.0, 1.0 - quote_stability_trend) * 0.15
                + max(0.0, 1.0 - orderbook_consistency_trend) * 0.15
                + max(0.0, 1.0 - predictive_regime_score) * 0.12
                + max(0.0, 1.0 - improvement_velocity) * 0.14
            )
        )
        if regime_transition in {"stabilizing", "unstable->stabilizing"}:
            stable_bias += 0.04
        elif regime_transition in {"improving", "stabilizing->improving"}:
            stable_bias += 0.06
        elif regime_transition in {"stable", "improving->stable"}:
            stable_bias += 0.08
        elif regime_transition in {"high_quality", "stable->high_quality"}:
            stable_bias += 0.10
        elif regime_transition in {"unstable", "weak", "stable->unstable", "improving->unstable"}:
            unstable_bias += 0.08
        promotion_strength = self._clamp(
            (
                stable_bias * 0.55
                + improvement_velocity * 0.15
                + persistence_score * 0.15
                + max(0.0, 1.0 - decay_score) * 0.10
                + family_learning_trend * 0.05
            )
        )
        demotion_strength = self._clamp(
            (
                unstable_bias * 0.60
                + decay_score * 0.15
                + max(0.0, 1.0 - improvement_velocity) * 0.10
                + max(0.0, 1.0 - persistence_score) * 0.10
                + max(0.0, 1.0 - family_learning_trend) * 0.05
            )
        )
        adaptive_priority_score = self._clamp(base_priority_score + (promotion_strength - demotion_strength) * 0.08)
        promotion_reason = "improving_regime_persistence" if promotion_strength >= demotion_strength else "none"
        demotion_reason = "regime_decay_pressure" if demotion_strength > promotion_strength else "none"
        soft_priority_adjustment = max(-0.08, min(0.08, (promotion_strength - demotion_strength) * 0.08))
        promotion_multiplier = max(0.0, min(0.03, promotion_strength * 0.03))
        demotion_multiplier = max(0.0, min(0.03, demotion_strength * 0.03))
        return {
            "adaptive_priority_score": round(adaptive_priority_score, 4),
            "promotion_reason": promotion_reason,
            "demotion_reason": demotion_reason,
            "promotion_strength": round(promotion_strength, 4),
            "demotion_strength": round(demotion_strength, 4),
            "promotion_multiplier": round(promotion_multiplier, 4),
            "demotion_multiplier": round(demotion_multiplier, 4),
            "soft_priority_adjustment": round(soft_priority_adjustment, 4),
            "persistence_score": round(persistence_score, 4),
            "decay_score": round(decay_score, 4),
            "improvement_velocity": round(improvement_velocity, 4),
            "stable_regime_bias": round(stable_bias, 4),
            "unstable_regime_bias": round(unstable_bias, 4),
        }

    def _classify_adaptive_priority_bucket(self, *, adaptive_priority_score=0.0, reactivation_summary=None, ticker_bucket=None, family_summary=None, recent_blocker_reason=None):
        reactivation_summary = reactivation_summary if isinstance(reactivation_summary, dict) else {}
        ticker_bucket = ticker_bucket if isinstance(ticker_bucket, dict) else {}
        family_summary = family_summary if isinstance(family_summary, dict) else {}
        latest_reactivation_state = str(
            reactivation_summary.get("latest_reactivation_state")
            or ticker_bucket.get("latest_reactivation_state")
            or "dead"
        ).strip().lower()
        blocker_reason = str(
            recent_blocker_reason
            or ticker_bucket.get("recent_blocker_reason")
            or family_summary.get("top_blocker")
            or reactivation_summary.get("top_blocker")
            or ""
        ).strip().lower()
        if adaptive_priority_score < 0.18 or latest_reactivation_state == "dead":
            return "ignore"
        if adaptive_priority_score < 0.38 or blocker_reason in {"missing_quotes", "unsafe_price"}:
            return "low_priority"
        if adaptive_priority_score < 0.58 or blocker_reason in {"low_volume", "edge_below_cost", "low_liquidity"}:
            return "monitor"
        if adaptive_priority_score < 0.80:
            return "high_priority"
        return "priority_watch"

    def _build_adaptive_priority_family_summary(self, family=None):
        family = str(family or "UNKNOWN").strip().upper() or "UNKNOWN"
        ticker_container = getattr(self, "adaptive_priority_by_ticker", {}) or {}
        family_buckets = []
        if isinstance(ticker_container, dict):
            for bucket in ticker_container.values():
                if not isinstance(bucket, dict):
                    continue
                if str(bucket.get("family") or "").strip().upper() == family:
                    family_buckets.append(bucket)
        family_bucket = self._get_adaptive_priority_watchlist_bucket("adaptive_priority_by_family", f"family:{family}")
        if not family_buckets:
            summary = {
                "family": family,
                "observations": 0,
                "avg_priority_score": 0.0,
                "best_priority_score": round(self.to_float(family_bucket.get("best_priority_score"), 0.0) or 0.0, 4),
                "reject_reason_top": str(family_bucket.get("reject_reason_top") or "insufficient_data"),
                "improving_count": int(family_bucket.get("improving_count", 0) or 0),
                "high_priority_count": int(family_bucket.get("high_priority_count", 0) or 0),
                "priority_watch_count": int(family_bucket.get("priority_watch_count", 0) or 0),
                "latest_priority_bucket": family_bucket.get("latest_priority_bucket") or "ignore",
            }
            family_bucket["last_summary"] = summary
            return summary
        count = max(len(family_buckets), 1)
        avg_priority_score = sum(self.to_float(bucket.get("avg_priority_score"), 0.0) or 0.0 for bucket in family_buckets) / count
        best_bucket = max(
            family_buckets,
            key=lambda bucket: (
                self.to_float(bucket.get("best_priority_score"), 0.0),
                self.to_float(bucket.get("avg_priority_score"), 0.0),
                int(bucket.get("priority_watch_count", 0) or 0),
                int(bucket.get("high_priority_count", 0) or 0),
            ),
        )
        reject_reason_counts = Counter()
        improving_count = 0
        high_priority_count = 0
        priority_watch_count = 0
        for bucket in family_buckets:
            improving_count += int(bucket.get("improving_count", 0) or 0)
            high_priority_count += int(bucket.get("high_priority_count", 0) or 0)
            priority_watch_count += int(bucket.get("priority_watch_count", 0) or 0)
            for reason in list(bucket.get("blocker_history") or []):
                if reason:
                    reject_reason_counts[str(reason).strip().lower()] += 1
        reject_reason_top = reject_reason_counts.most_common(1)[0][0] if reject_reason_counts else str(best_bucket.get("recent_blocker_reason") or "none")
        summary = {
            "family": family,
            "observations": int(sum(int(bucket.get("observation_count", 0) or 0) for bucket in family_buckets)),
            "avg_priority_score": round(avg_priority_score, 4),
            "best_priority_score": round(self.to_float(best_bucket.get("best_priority_score"), 0.0) or 0.0, 4),
            "reject_reason_top": reject_reason_top,
            "improving_count": int(improving_count),
            "high_priority_count": int(high_priority_count),
            "priority_watch_count": int(priority_watch_count),
            "latest_priority_bucket": best_bucket.get("latest_priority_bucket") or "ignore",
        }
        family_bucket["last_summary"] = summary
        family_bucket["best_priority_score"] = summary["best_priority_score"]
        family_bucket["avg_priority_score"] = summary["avg_priority_score"]
        family_bucket["reject_reason_top"] = summary["reject_reason_top"]
        family_bucket["improving_count"] = summary["improving_count"]
        family_bucket["high_priority_count"] = summary["high_priority_count"]
        family_bucket["priority_watch_count"] = summary["priority_watch_count"]
        return summary

    def _build_adaptive_priority_overall_summary(self):
        ticker_container = getattr(self, "adaptive_priority_by_ticker", {}) or {}
        family_container = getattr(self, "adaptive_priority_by_family", {}) or {}
        ticker_buckets = [bucket for bucket in ticker_container.values() if isinstance(bucket, dict)]
        family_buckets = [bucket for bucket in family_container.values() if isinstance(bucket, dict)]
        if not ticker_buckets:
            return {
                "scope": "overall",
                "candidate_count": 0,
                "avg_priority_score": 0.0,
                "best_priority_ticker": None,
                "best_priority_family": None,
                "best_priority_score": 0.0,
                "priority_watch_count": 0,
                "high_priority_count": 0,
                "monitor_count": 0,
                "low_priority_count": 0,
                "ignore_count": 0,
                "promoted_candidate_count": 0,
                "demoted_candidate_count": 0,
                "strongest_promoted_family": None,
                "strongest_demoted_family": None,
                "highest_priority_candidate": None,
                "stable_regime_bias": 0.0,
                "unstable_regime_bias": 0.0,
                "top_reject_reason": "insufficient_data",
            }
        best_bucket = max(
            ticker_buckets,
            key=lambda bucket: (
                self.to_float(bucket.get("best_priority_score"), 0.0),
                self.to_float(bucket.get("avg_priority_score"), 0.0),
                int(bucket.get("priority_watch_count", 0) or 0),
                int(bucket.get("high_priority_count", 0) or 0),
            ),
        )
        avg_priority_score = sum(self.to_float(bucket.get("avg_priority_score"), 0.0) or 0.0 for bucket in ticker_buckets) / max(len(ticker_buckets), 1)
        priority_watch_count = sum(1 for bucket in ticker_buckets if str(bucket.get("latest_priority_bucket") or "").strip().lower() == "priority_watch")
        high_priority_count = sum(1 for bucket in ticker_buckets if str(bucket.get("latest_priority_bucket") or "").strip().lower() == "high_priority")
        monitor_count = sum(1 for bucket in ticker_buckets if str(bucket.get("latest_priority_bucket") or "").strip().lower() == "monitor")
        low_priority_count = sum(1 for bucket in ticker_buckets if str(bucket.get("latest_priority_bucket") or "").strip().lower() == "low_priority")
        ignore_count = sum(1 for bucket in ticker_buckets if str(bucket.get("latest_priority_bucket") or "").strip().lower() == "ignore")
        promoted_candidate_count = sum(1 for bucket in ticker_buckets if self.to_float(bucket.get("promotion_multiplier"), 0.0) > self.to_float(bucket.get("demotion_multiplier"), 0.0))
        demoted_candidate_count = sum(1 for bucket in ticker_buckets if self.to_float(bucket.get("demotion_multiplier"), 0.0) > self.to_float(bucket.get("promotion_multiplier"), 0.0))
        strongest_promoted_bucket = max(
            ticker_buckets,
            key=lambda bucket: (
                self.to_float(bucket.get("promotion_multiplier"), 0.0),
                self.to_float(bucket.get("promotion_strength"), 0.0),
                self.to_float(bucket.get("adaptive_priority_score"), 0.0),
            ),
        )
        strongest_demoted_bucket = max(
            ticker_buckets,
            key=lambda bucket: (
                self.to_float(bucket.get("demotion_multiplier"), 0.0),
                self.to_float(bucket.get("demotion_strength"), 0.0),
                self.to_float(bucket.get("adaptive_priority_score"), 0.0),
            ),
        )
        reject_reason_counts = Counter()
        for bucket in ticker_buckets:
            for reason in list(bucket.get("blocker_history") or []):
                if reason:
                    reject_reason_counts[str(reason).strip().lower()] += 1
        top_reject_reason = reject_reason_counts.most_common(1)[0][0] if reject_reason_counts else "none"
        return {
            "scope": "overall",
            "candidate_count": int(len(ticker_buckets)),
            "family_count": int(len(family_buckets)),
            "avg_priority_score": round(avg_priority_score, 4),
            "best_priority_ticker": str(best_bucket.get("ticker") or "").strip() or None,
            "best_priority_family": str(best_bucket.get("family") or "").strip() or None,
            "best_priority_score": round(self.to_float(best_bucket.get("best_priority_score"), 0.0) or 0.0, 4),
            "priority_watch_count": int(priority_watch_count),
            "high_priority_count": int(high_priority_count),
            "monitor_count": int(monitor_count),
            "low_priority_count": int(low_priority_count),
            "ignore_count": int(ignore_count),
            "promoted_candidate_count": int(promoted_candidate_count),
            "demoted_candidate_count": int(demoted_candidate_count),
            "strongest_promoted_family": str(strongest_promoted_bucket.get("family") or "").strip() or None,
            "strongest_demoted_family": str(strongest_demoted_bucket.get("family") or "").strip() or None,
            "highest_priority_candidate": str(best_bucket.get("ticker") or "").strip() or None,
            "stable_regime_bias": round(self.to_float(strongest_promoted_bucket.get("stable_regime_bias"), 0.0) or 0.0, 4),
            "unstable_regime_bias": round(self.to_float(strongest_demoted_bucket.get("unstable_regime_bias"), 0.0) or 0.0, 4),
            "top_reject_reason": top_reject_reason,
        }

    def _emit_adaptive_priority_telemetry(self, *, ticker_bucket=None, family_bucket=None, force=False):
        ticker_bucket = ticker_bucket if isinstance(ticker_bucket, dict) else {}
        family_bucket = family_bucket if isinstance(family_bucket, dict) else {}
        ticker = str(ticker_bucket.get("ticker") or "").strip()
        family = str(family_bucket.get("family") or ticker_bucket.get("family") or "").strip().upper() or "UNKNOWN"
        now = time.time()
        score_payload = ticker_bucket.get("last_summary") if isinstance(ticker_bucket.get("last_summary"), dict) else {}
        if not score_payload:
            score_payload = {
                "ticker": ticker or "unknown",
                "family": family,
                "adaptive_priority_score": round(self.to_float(ticker_bucket.get("best_priority_score"), 0.0) or 0.0, 4),
                "reactivation_score": round(self.to_float(ticker_bucket.get("reactivation_score"), 0.0) or 0.0, 4),
                "execution_survivability_score": round(self.to_float(ticker_bucket.get("execution_survivability_score"), 0.0) or 0.0, 4),
                "edge_durability_score": round(self.to_float(ticker_bucket.get("edge_durability_score"), 0.0) or 0.0, 4),
                "family_microstructure_score": round(self.to_float(ticker_bucket.get("family_microstructure_score"), 0.0) or 0.0, 4),
                "quote_lifetime_score": round(min(1.0, max(0.0, self.to_float(ticker_bucket.get("quote_lifetime_seconds"), 0.0) / 240.0)), 4),
                "spread_lifetime_score": round(min(1.0, max(0.0, self.to_float(ticker_bucket.get("spread_lifetime_seconds"), 0.0) / 240.0)), 4),
                "latest_priority_bucket": str(ticker_bucket.get("latest_priority_bucket") or "ignore").strip().lower(),
                "recent_blocker_reason": ticker_bucket.get("recent_blocker_reason"),
            }
        emit_key = ticker or family
        last_emit = float(getattr(self, "adaptive_priority_last_signal_ts_by_key", {}).get(emit_key, 0.0) or 0.0)
        if not force and ticker and (now - last_emit) < 120.0:
            return None
        if ticker:
            self.adaptive_priority_last_signal_ts_by_key[ticker] = now
        if family:
            self.adaptive_priority_last_signal_ts_by_key[family] = now
        print(
            "[LIVE-ADAPTIVE-PRIORITY] "
            + json.dumps(
                {
                    "ticker": ticker or score_payload.get("ticker"),
                    "family": family,
                    "adaptive_priority_score": score_payload.get("adaptive_priority_score"),
                    "persistence_score": score_payload.get("persistence_score", self.to_float(ticker_bucket.get("persistence_score"), 0.0)),
                    "decay_score": score_payload.get("decay_score", self.to_float(ticker_bucket.get("decay_score"), 0.0)),
                    "promotion_strength": round(self.to_float(ticker_bucket.get("promotion_strength"), 0.0), 4),
                    "demotion_strength": round(self.to_float(ticker_bucket.get("demotion_strength"), 0.0), 4),
                    "promotion_reason": score_payload.get("promotion_reason") or ticker_bucket.get("promotion_reason"),
                    "demotion_reason": score_payload.get("demotion_reason") or ticker_bucket.get("demotion_reason"),
                },
                sort_keys=True,
                default=str,
            )
        )
        print("[LIVE-ADAPTIVE-PRIORITY-SCORE] " + json.dumps(score_payload, sort_keys=True, default=str))
        print(
            "[LIVE-ADAPTIVE-PRIORITY-BUCKET] "
            + json.dumps(
                {
                    "ticker": ticker or score_payload.get("ticker"),
                    "family": family,
                    "adaptive_priority_score": score_payload.get("adaptive_priority_score"),
                    "latest_priority_bucket": score_payload.get("latest_priority_bucket"),
                    "best_priority_score": round(self.to_float(ticker_bucket.get("best_priority_score"), 0.0) or 0.0, 4),
                    "avg_priority_score": round(self.to_float(ticker_bucket.get("avg_priority_score"), 0.0) or 0.0, 4),
                    "recent_blocker_reason": score_payload.get("recent_blocker_reason"),
                },
                sort_keys=True,
                default=str,
            )
        )
        family_summary = self._build_adaptive_priority_family_summary(family=family)
        self.last_adaptive_priority_family_summary = family_summary
        family_bucket["last_summary"] = family_summary
        self.last_adaptive_priority_overall_summary = self._build_adaptive_priority_overall_summary()
        print("[LIVE-PRIORITY-DASHBOARD] " + json.dumps(self.last_adaptive_priority_overall_summary, sort_keys=True, default=str))
        print("[LIVE-FAMILY-PRIORITY-MEMORY] " + json.dumps(family_summary, sort_keys=True, default=str))
        return score_payload

    def _get_adaptive_confidence_bucket(self, container_name, key):
        buckets = getattr(self, container_name, None)
        if not isinstance(buckets, dict):
            buckets = {}
            setattr(self, container_name, buckets)
        bucket = buckets.setdefault(
            key,
            {
                "first_seen_time": None,
                "last_seen_time": 0.0,
                "ticker": None,
                "family": None,
                "predictive_regime_persistence": 0.0,
                "spread_deterioration_frequency": 0.0,
                "momentum_survival": 0.0,
                "quote_stability_trend": 0.0,
                "rejection_recurrence": 0.0,
                "edge_durability": 0.0,
                "volatility_rejection_rate": 0.0,
                "unsafe_pricing_recurrence": 0.0,
                "near_pass_recurrence": 0.0,
                "stable_observation_streak": 0.0,
                "adaptive_confidence_modifier": 0.0,
                "boost_count": 0,
                "decay_count": 0,
                "stable_count": 0,
                "degrading_count": 0,
                "score_history": deque(maxlen=24),
                "modifier_history": deque(maxlen=24),
                "regime_history": deque(maxlen=24),
                "last_summary": {},
            },
        )
        return bucket

    def compute_adaptive_confidence_modifier(
        self,
        *,
        predictive_regime_persistence=None,
        spread_deterioration_frequency=None,
        momentum_survival=None,
        quote_stability_trend=None,
        rejection_recurrence=None,
        edge_durability=None,
        volatility_rejection_rate=None,
        unsafe_pricing_recurrence=None,
        near_pass_recurrence=None,
        stable_observation_streak=None,
        memory_bucket=None,
        base_confidence=None,
    ):
        memory_bucket = memory_bucket if isinstance(memory_bucket, dict) else {}
        predictive_regime_persistence = self._clamp(self.to_float(predictive_regime_persistence, self.to_float(memory_bucket.get("predictive_regime_persistence"), 0.0)))
        spread_deterioration_frequency = self._clamp(self.to_float(spread_deterioration_frequency, self.to_float(memory_bucket.get("spread_deterioration_frequency"), 0.0)))
        momentum_survival = self._clamp(self.to_float(momentum_survival, self.to_float(memory_bucket.get("momentum_survival"), 0.0)))
        quote_stability_trend = self._clamp(self.to_float(quote_stability_trend, self.to_float(memory_bucket.get("quote_stability_trend"), 0.0)))
        rejection_recurrence = self._clamp(self.to_float(rejection_recurrence, self.to_float(memory_bucket.get("rejection_recurrence"), 0.0)))
        edge_durability = self._clamp(self.to_float(edge_durability, self.to_float(memory_bucket.get("edge_durability"), 0.0)))
        volatility_rejection_rate = self._clamp(self.to_float(volatility_rejection_rate, self.to_float(memory_bucket.get("volatility_rejection_rate"), 0.0)))
        unsafe_pricing_recurrence = self._clamp(self.to_float(unsafe_pricing_recurrence, self.to_float(memory_bucket.get("unsafe_pricing_recurrence"), 0.0)))
        near_pass_recurrence = self._clamp(self.to_float(near_pass_recurrence, self.to_float(memory_bucket.get("near_pass_recurrence"), 0.0)))
        stable_observation_streak = self._clamp(self.to_float(stable_observation_streak, self.to_float(memory_bucket.get("stable_observation_streak"), 0.0)))
        base_confidence = self._clamp(self.to_float(base_confidence, 0.0))
        boost_components = (
            predictive_regime_persistence * 0.18
            + momentum_survival * 0.15
            + quote_stability_trend * 0.12
            + edge_durability * 0.16
            + near_pass_recurrence * 0.10
            + stable_observation_streak * 0.12
            + max(0.0, 1.0 - spread_deterioration_frequency) * 0.10
            + max(0.0, 1.0 - volatility_rejection_rate) * 0.07
        )
        decay_components = (
            rejection_recurrence * 0.16
            + unsafe_pricing_recurrence * 0.15
            + spread_deterioration_frequency * 0.18
            + max(0.0, 1.0 - momentum_survival) * 0.13
            + max(0.0, 1.0 - edge_durability) * 0.12
            + volatility_rejection_rate * 0.10
            + max(0.0, 1.0 - predictive_regime_persistence) * 0.08
            + max(0.0, 1.0 - quote_stability_trend) * 0.08
        )
        stability_bias = max(0.0, min(1.0, boost_components))
        decay_bias = max(0.0, min(1.0, decay_components))
        adaptive_confidence_modifier = max(-0.08, min(0.08, (stability_bias - decay_bias) * 0.08))
        if stable_observation_streak >= 0.60:
            adaptive_confidence_modifier += 0.01
        elif stable_observation_streak <= 0.20:
            adaptive_confidence_modifier -= 0.01
        adaptive_confidence_modifier = max(-0.08, min(0.08, adaptive_confidence_modifier))
        adjusted_confidence = max(0.0, min(1.0, base_confidence + adaptive_confidence_modifier))
        promotion_reason = "stable_regime_persistence" if adaptive_confidence_modifier > 0 else "none"
        demotion_reason = "regime_decay_and_rejection_pressure" if adaptive_confidence_modifier < 0 else "none"
        boost_strength = max(0.0, adaptive_confidence_modifier)
        decay_strength = max(0.0, -adaptive_confidence_modifier)
        return {
            "adaptive_confidence_modifier": round(adaptive_confidence_modifier, 4),
            "adaptive_confidence": round(adjusted_confidence, 4),
            "promotion_reason": promotion_reason,
            "demotion_reason": demotion_reason,
            "boost_strength": round(boost_strength, 4),
            "decay_strength": round(decay_strength, 4),
            "predictive_regime_persistence": round(predictive_regime_persistence, 4),
            "spread_deterioration_frequency": round(spread_deterioration_frequency, 4),
            "momentum_survival": round(momentum_survival, 4),
            "quote_stability_trend": round(quote_stability_trend, 4),
            "rejection_recurrence": round(rejection_recurrence, 4),
            "edge_durability": round(edge_durability, 4),
            "volatility_rejection_rate": round(volatility_rejection_rate, 4),
            "unsafe_pricing_recurrence": round(unsafe_pricing_recurrence, 4),
            "near_pass_recurrence": round(near_pass_recurrence, 4),
            "stable_observation_streak": round(stable_observation_streak, 4),
            "stable_confidence_count": int(1 if adaptive_confidence_modifier > 0 else 0),
            "degrading_confidence_count": int(1 if adaptive_confidence_modifier < 0 else 0),
            "confidence_decay_count": int(1 if decay_strength > 0 else 0),
            "confidence_boost_count": int(1 if boost_strength > 0 else 0),
        }

    def _build_adaptive_confidence_family_summary(self, family=None):
        family = str(family or "UNKNOWN").strip().upper() or "UNKNOWN"
        ticker_container = getattr(self, "adaptive_confidence_by_ticker", {}) or {}
        family_buckets = []
        if isinstance(ticker_container, dict):
            for bucket in ticker_container.values():
                if not isinstance(bucket, dict):
                    continue
                if str(bucket.get("family") or "").strip().upper() == family:
                    family_buckets.append(bucket)
        family_bucket = self._get_adaptive_confidence_bucket("adaptive_confidence_by_family", f"family:{family}")
        if not family_buckets:
            summary = {
                "family": family,
                "observations": 0,
                "avg_confidence_modifier": round(self.to_float(family_bucket.get("adaptive_confidence_modifier"), 0.0) or 0.0, 4),
                "best_confidence_ticker": None,
                "best_confidence_modifier": 0.0,
                "confidence_decay_count": int(family_bucket.get("decay_count", 0) or 0),
                "confidence_boost_count": int(family_bucket.get("boost_count", 0) or 0),
                "stable_confidence_count": int(family_bucket.get("stable_count", 0) or 0),
                "degrading_confidence_count": int(family_bucket.get("degrading_count", 0) or 0),
                "top_blocker": "insufficient_data",
            }
            family_bucket["last_summary"] = summary
            return summary
        best_bucket = max(
            family_buckets,
            key=lambda bucket: (
                self.to_float(bucket.get("adaptive_confidence_modifier"), 0.0),
                self.to_float(bucket.get("adaptive_confidence"), 0.0),
                int(bucket.get("boost_count", 0) or 0),
            ),
        )
        avg_confidence_modifier = sum(self.to_float(bucket.get("adaptive_confidence_modifier"), 0.0) or 0.0 for bucket in family_buckets) / max(len(family_buckets), 1)
        confidence_decay_count = sum(int(bucket.get("confidence_decay_count", 0) or 0) for bucket in family_buckets)
        confidence_boost_count = sum(int(bucket.get("confidence_boost_count", 0) or 0) for bucket in family_buckets)
        stable_confidence_count = sum(int(bucket.get("stable_confidence_count", 0) or 0) for bucket in family_buckets)
        degrading_confidence_count = sum(int(bucket.get("degrading_confidence_count", 0) or 0) for bucket in family_buckets)
        summary = {
            "family": family,
            "observations": int(sum(int(bucket.get("observation_count", 0) or 0) for bucket in family_buckets)),
            "avg_confidence_modifier": round(avg_confidence_modifier, 4),
            "best_confidence_ticker": str(best_bucket.get("ticker") or "").strip() or None,
            "best_confidence_modifier": round(self.to_float(best_bucket.get("adaptive_confidence_modifier"), 0.0) or 0.0, 4),
            "confidence_decay_count": int(confidence_decay_count),
            "confidence_boost_count": int(confidence_boost_count),
            "stable_confidence_count": int(stable_confidence_count),
            "degrading_confidence_count": int(degrading_confidence_count),
            "top_blocker": str(family_bucket.get("top_blocker") or "none"),
        }
        family_bucket["last_summary"] = summary
        family_bucket["adaptive_confidence_modifier"] = summary["avg_confidence_modifier"]
        return summary

    def _build_adaptive_confidence_overall_summary(self):
        ticker_container = getattr(self, "adaptive_confidence_by_ticker", {}) or {}
        family_container = getattr(self, "adaptive_confidence_by_family", {}) or {}
        ticker_buckets = [bucket for bucket in ticker_container.values() if isinstance(bucket, dict)]
        family_buckets = [bucket for bucket in family_container.values() if isinstance(bucket, dict)]
        if not ticker_buckets:
            return {
                "scope": "overall",
                "candidate_count": 0,
                "family_count": 0,
                "strongest_confidence_family": None,
                "strongest_confidence_ticker": None,
                "top_confidence_modifier": 0.0,
                "avg_confidence_modifier": 0.0,
                "confidence_decay_count": 0,
                "confidence_boost_count": 0,
                "stable_confidence_count": 0,
                "degrading_confidence_count": 0,
                "top_blocker": "insufficient_data",
            }
        best_bucket = max(
            ticker_buckets,
            key=lambda bucket: (
                self.to_float(bucket.get("adaptive_confidence_modifier"), 0.0),
                self.to_float(bucket.get("adaptive_confidence"), 0.0),
                int(bucket.get("confidence_boost_count", 0) or 0),
            ),
        )
        strongest_family = None
        if family_buckets:
            strongest_family_bucket = max(
                family_buckets,
                key=lambda bucket: (
                    self.to_float(bucket.get("avg_confidence_modifier"), 0.0),
                    self.to_float(bucket.get("best_confidence_modifier"), 0.0),
                ),
            )
            strongest_family = str(strongest_family_bucket.get("family") or "").strip() or None
        summary = {
            "scope": "overall",
            "candidate_count": int(len(ticker_buckets)),
            "family_count": int(len(family_buckets)),
            "strongest_confidence_family": strongest_family,
            "strongest_confidence_ticker": str(best_bucket.get("ticker") or "").strip() or None,
            "top_confidence_modifier": round(self.to_float(best_bucket.get("adaptive_confidence_modifier"), 0.0) or 0.0, 4),
            "avg_confidence_modifier": round(
                sum(self.to_float(bucket.get("adaptive_confidence_modifier"), 0.0) or 0.0 for bucket in ticker_buckets) / max(len(ticker_buckets), 1),
                4,
            ),
            "confidence_decay_count": int(sum(int(bucket.get("confidence_decay_count", 0) or 0) for bucket in ticker_buckets)),
            "confidence_boost_count": int(sum(int(bucket.get("confidence_boost_count", 0) or 0) for bucket in ticker_buckets)),
            "stable_confidence_count": int(sum(int(bucket.get("stable_confidence_count", 0) or 0) for bucket in ticker_buckets)),
            "degrading_confidence_count": int(sum(int(bucket.get("degrading_confidence_count", 0) or 0) for bucket in ticker_buckets)),
            "top_blocker": str(best_bucket.get("top_blocker") or "none"),
        }
        return summary

    def _emit_adaptive_confidence_telemetry(self, *, ticker_bucket=None, family_bucket=None, force=False):
        ticker_bucket = ticker_bucket if isinstance(ticker_bucket, dict) else {}
        family_bucket = family_bucket if isinstance(family_bucket, dict) else {}
        ticker = str(ticker_bucket.get("ticker") or "").strip()
        family = str(family_bucket.get("family") or ticker_bucket.get("family") or "").strip().upper() or "UNKNOWN"
        now = time.time()
        summary = ticker_bucket.get("last_summary") if isinstance(ticker_bucket.get("last_summary"), dict) else {}
        if not summary:
            summary = {
                "ticker": ticker or "unknown",
                "family": family,
                "adaptive_confidence_modifier": round(self.to_float(ticker_bucket.get("adaptive_confidence_modifier"), 0.0) or 0.0, 4),
                "adaptive_confidence": round(self.to_float(ticker_bucket.get("adaptive_confidence"), 0.0) or 0.0, 4),
            }
        emit_key = ticker or family
        last_emit = float(getattr(self, "adaptive_confidence_last_signal_ts_by_key", {}).get(emit_key, 0.0) or 0.0)
        if not force and ticker and (now - last_emit) < 120.0:
            return None
        if ticker:
            self.adaptive_confidence_last_signal_ts_by_key[ticker] = now
        if family:
            self.adaptive_confidence_last_signal_ts_by_key[family] = now
        print("[LIVE-ADAPTIVE-CONFIDENCE] " + json.dumps(summary, sort_keys=True, default=str))
        print("[LIVE-CONFIDENCE-MEMORY] " + json.dumps(family_bucket.get("last_summary") or self._build_adaptive_confidence_family_summary(family=family), sort_keys=True, default=str))
        print("[LIVE-CONFIDENCE-DURABILITY] " + json.dumps({
            "ticker": ticker or summary.get("ticker"),
            "family": family,
            "predictive_regime_persistence": summary.get("predictive_regime_persistence"),
            "edge_durability": summary.get("edge_durability"),
            "momentum_survival": summary.get("momentum_survival"),
            "stable_observation_streak": summary.get("stable_observation_streak"),
            "unsafe_pricing_recurrence": summary.get("unsafe_pricing_recurrence"),
            "near_pass_recurrence": summary.get("near_pass_recurrence"),
        }, sort_keys=True, default=str))
        if self.to_float(summary.get("adaptive_confidence_modifier"), 0.0) > 0:
            print("[LIVE-CONFIDENCE-BOOST] " + json.dumps(summary, sort_keys=True, default=str))
        elif self.to_float(summary.get("adaptive_confidence_modifier"), 0.0) < 0:
            print("[LIVE-CONFIDENCE-DECAY] " + json.dumps(summary, sort_keys=True, default=str))
        self.last_adaptive_confidence_summary = dict(summary)
        self.last_adaptive_confidence_family_summary = dict(family_bucket.get("last_summary") or {})
        self.last_adaptive_confidence_overall_summary = self._build_adaptive_confidence_overall_summary()
        print("[LIVE-CONFIDENCE-DASHBOARD] " + json.dumps(self.last_adaptive_confidence_overall_summary, sort_keys=True, default=str))
        return summary

    def _update_adaptive_confidence_memory(self, *, market=None, q=None, family=None, predictive_regime_summary=None, microstructure_summary=None, family_microstructure_summary=None, reactivation_summary=None, adaptive_priority_summary=None, learning_summary=None, family_learning_summary=None, audit=None, decision_reason=None, force=False):
        market = market if isinstance(market, dict) else {}
        predictive_regime_summary = predictive_regime_summary if isinstance(predictive_regime_summary, dict) else {}
        microstructure_summary = microstructure_summary if isinstance(microstructure_summary, dict) else {}
        family_microstructure_summary = family_microstructure_summary if isinstance(family_microstructure_summary, dict) else {}
        reactivation_summary = reactivation_summary if isinstance(reactivation_summary, dict) else {}
        adaptive_priority_summary = adaptive_priority_summary if isinstance(adaptive_priority_summary, dict) else {}
        learning_summary = learning_summary if isinstance(learning_summary, dict) else {}
        family_learning_summary = family_learning_summary if isinstance(family_learning_summary, dict) else {}
        audit = audit if isinstance(audit, dict) else {}
        ticker = str(
            audit.get("ticker")
            or predictive_regime_summary.get("ticker")
            or getattr(q, "ticker", None)
            or market.get("ticker")
            or ""
        ).strip()
        if not ticker:
            return None
        family = str(
            family
            or audit.get("family")
            or predictive_regime_summary.get("family")
            or family_microstructure_summary.get("family")
            or self.get_market_family(market or {})
            or "UNKNOWN"
        ).strip().upper() or "UNKNOWN"
        market_type = str(
            predictive_regime_summary.get("market_type")
            or market.get("category")
            or market.get("market_category")
            or self.get_market_discovery_category(market or {})
            or "unknown"
        ).strip().lower() or "unknown"
        ticker_bucket = self._get_adaptive_confidence_bucket("adaptive_confidence_by_ticker", f"ticker:{ticker}")
        family_bucket = self._get_adaptive_confidence_bucket("adaptive_confidence_by_family", f"family:{family}")
        now = time.time()
        last_seen = float(ticker_bucket.get("last_seen_time", 0.0) or 0.0)
        elapsed = max(0.0, now - last_seen) if last_seen > 0 else 0.0
        decay_factor = 0.5 ** (elapsed / 10800.0) if elapsed > 0 else 1.0
        predictive_regime_score = self._clamp(
            self.to_float(predictive_regime_summary.get("predictive_regime_score"), self.to_float(adaptive_priority_summary.get("adaptive_priority_score"), 0.0))
        )
        improvement_signal = self._clamp(self.to_float(predictive_regime_summary.get("improvement_signal"), 0.0))
        decay_signal = self._clamp(self.to_float(predictive_regime_summary.get("decay_signal"), 0.0))
        latest_regime_state = str(predictive_regime_summary.get("latest_regime_state") or predictive_regime_summary.get("regime_transition") or "unstable").strip().lower()
        predictive_regime_persistence = self._clamp(
            min(
                1.0,
                predictive_regime_score * 0.55
                + improvement_signal * 0.25
                + max(0.0, 1.0 - decay_signal) * 0.20,
            )
        )
        spread_tightening_velocity = self._clamp(self.to_float(predictive_regime_summary.get("spread_tightening_velocity"), 0.0))
        quote_stability_trend = self._clamp(self.to_float(predictive_regime_summary.get("quote_stability_trend"), 0.0))
        orderbook_consistency_trend = self._clamp(self.to_float(predictive_regime_summary.get("orderbook_consistency_trend"), 0.0))
        edge_durability_trend = self._clamp(self.to_float(predictive_regime_summary.get("edge_durability_trend"), self.to_float(microstructure_summary.get("edge_stability_score"), 0.0)))
        momentum_consistency = self._clamp(self.to_float(predictive_regime_summary.get("momentum_consistency"), 0.0))
        rejection_volatility = self._clamp(self.to_float(predictive_regime_summary.get("rejection_volatility"), 0.0))
        rejection_count = max(
            self.to_float(learning_summary.get("rejection_count"), 0.0) or 0.0,
            self.to_float(learning_summary.get("unsafe_price_count"), 0.0)
            + self.to_float(learning_summary.get("edge_below_cost_count"), 0.0)
            + self.to_float(learning_summary.get("missing_quotes_count"), 0.0)
            + self.to_float(learning_summary.get("low_volume_count"), 0.0)
            + self.to_float(learning_summary.get("unstable_orderbook_count"), 0.0)
            + self.to_float(learning_summary.get("phase55_block_count"), 0.0)
            + self.to_float(learning_summary.get("liquidity_block_count"), 0.0),
        )
        rejection_recurrence = self._clamp(min(1.0, rejection_count / 6.0))
        unsafe_pricing_recurrence = self._clamp(min(1.0, self.to_float(learning_summary.get("unsafe_price_count"), 0.0) / 5.0))
        near_pass_recurrence = self._clamp(
            min(
                1.0,
                (
                    self.to_float(learning_summary.get("improving_count"), 0.0) * 0.35
                    + self.to_float(learning_summary.get("strong_watch_count"), 0.0) * 0.35
                    + self.to_float(adaptive_priority_summary.get("priority_watch_count"), 0.0) * 0.15
                    + self.to_float(adaptive_priority_summary.get("high_priority_count"), 0.0) * 0.15
                )
                / max(self.to_float(learning_summary.get("observations"), 1.0) or 1.0, 1.0),
            )
        )
        stable_observation_streak = self._clamp(
            min(
                1.0,
                (
                    (1.0 if latest_regime_state in {"stable", "high_quality"} else 0.0)
                    + (1.0 if self.to_float(family_microstructure_summary.get("avg_survivability"), 0.0) >= 0.65 else 0.0)
                    + (1.0 if self.to_float(family_microstructure_summary.get("avg_edge_durability"), 0.0) >= 0.60 else 0.0)
                )
                / 3.0,
            )
        )
        confidence_payload = self.compute_adaptive_confidence_modifier(
            predictive_regime_persistence=predictive_regime_persistence,
            spread_deterioration_frequency=max(0.0, min(1.0, 1.0 - spread_tightening_velocity)),
            momentum_survival=momentum_consistency,
            quote_stability_trend=quote_stability_trend,
            rejection_recurrence=rejection_recurrence,
            edge_durability=edge_durability_trend,
            volatility_rejection_rate=rejection_volatility,
            unsafe_pricing_recurrence=unsafe_pricing_recurrence,
            near_pass_recurrence=near_pass_recurrence,
            stable_observation_streak=stable_observation_streak,
            memory_bucket=ticker_bucket,
            base_confidence=predictive_regime_score,
        )
        adaptive_confidence_modifier = self._clamp(self.to_float(confidence_payload.get("adaptive_confidence_modifier"), 0.0))
        adaptive_confidence = self._clamp(self.to_float(confidence_payload.get("adaptive_confidence"), predictive_regime_score))
        bucket_values = {
            "predictive_regime_persistence": predictive_regime_persistence,
            "spread_deterioration_frequency": max(0.0, min(1.0, 1.0 - spread_tightening_velocity)),
            "momentum_survival": momentum_consistency,
            "quote_stability_trend": quote_stability_trend,
            "rejection_recurrence": rejection_recurrence,
            "edge_durability": edge_durability_trend,
            "volatility_rejection_rate": rejection_volatility,
            "unsafe_pricing_recurrence": unsafe_pricing_recurrence,
            "near_pass_recurrence": near_pass_recurrence,
            "stable_observation_streak": stable_observation_streak,
        }
        ticker_bucket["first_seen_time"] = ticker_bucket.get("first_seen_time") or now
        ticker_bucket["last_seen_time"] = now
        ticker_bucket["ticker"] = ticker
        ticker_bucket["family"] = family
        ticker_bucket["market_type"] = market_type
        ticker_bucket["latest_regime_state"] = latest_regime_state
        for key, value in bucket_values.items():
            ticker_bucket[key] = round(self._clamp(self.to_float(value, self.to_float(ticker_bucket.get(key), 0.0))), 4)
        for key in ("boost_count", "decay_count", "stable_count", "degrading_count"):
            ticker_bucket[key] = round(self.to_float(ticker_bucket.get(key), 0.0) * decay_factor, 4)
        ticker_bucket["adaptive_confidence_modifier"] = round(adaptive_confidence_modifier, 4)
        ticker_bucket["adaptive_confidence"] = round(adaptive_confidence, 4)
        ticker_bucket.setdefault("score_history", deque(maxlen=24)).append(round(adaptive_confidence, 4))
        ticker_bucket.setdefault("modifier_history", deque(maxlen=24)).append(round(adaptive_confidence_modifier, 4))
        ticker_bucket.setdefault("regime_history", deque(maxlen=24)).append(latest_regime_state)
        ticker_bucket["observation_count"] = int(ticker_bucket.get("observation_count", 0) or 0) + 1
        if adaptive_confidence_modifier > 0:
            ticker_bucket["boost_count"] = int(ticker_bucket.get("boost_count", 0) or 0) + 1
        elif adaptive_confidence_modifier < 0:
            ticker_bucket["decay_count"] = int(ticker_bucket.get("decay_count", 0) or 0) + 1
        if latest_regime_state in {"stable", "high_quality"} or stable_observation_streak >= 0.66:
            ticker_bucket["stable_count"] = int(ticker_bucket.get("stable_count", 0) or 0) + 1
        if latest_regime_state in {"unstable", "weak"} or adaptive_confidence_modifier < 0:
            ticker_bucket["degrading_count"] = int(ticker_bucket.get("degrading_count", 0) or 0) + 1
        confidence_boost_count = int(ticker_bucket.get("boost_count", 0) or 0)
        confidence_decay_count = int(ticker_bucket.get("decay_count", 0) or 0)
        stable_confidence_count = int(ticker_bucket.get("stable_count", 0) or 0)
        degrading_confidence_count = int(ticker_bucket.get("degrading_count", 0) or 0)
        ticker_bucket["last_summary"] = {
            "ticker": ticker,
            "family": family,
            "market_type": market_type,
            "predictive_regime_persistence": round(predictive_regime_persistence, 4),
            "spread_deterioration_frequency": round(max(0.0, min(1.0, 1.0 - spread_tightening_velocity)), 4),
            "momentum_survival": round(momentum_consistency, 4),
            "quote_stability_trend": round(quote_stability_trend, 4),
            "rejection_recurrence": round(rejection_recurrence, 4),
            "edge_durability": round(edge_durability_trend, 4),
            "volatility_rejection_rate": round(rejection_volatility, 4),
            "unsafe_pricing_recurrence": round(unsafe_pricing_recurrence, 4),
            "near_pass_recurrence": round(near_pass_recurrence, 4),
            "stable_observation_streak": round(stable_observation_streak, 4),
            "adaptive_confidence_modifier": round(adaptive_confidence_modifier, 4),
            "adaptive_confidence": round(adaptive_confidence, 4),
            "promotion_reason": confidence_payload.get("promotion_reason"),
            "demotion_reason": confidence_payload.get("demotion_reason"),
            "boost_strength": round(self.to_float(confidence_payload.get("boost_strength"), 0.0), 4),
            "decay_strength": round(self.to_float(confidence_payload.get("decay_strength"), 0.0), 4),
            "confidence_boost_count": confidence_boost_count,
            "confidence_decay_count": confidence_decay_count,
            "stable_confidence_count": stable_confidence_count,
            "degrading_confidence_count": degrading_confidence_count,
            "last_regime_state": latest_regime_state,
            "previous_regime_state": str(predictive_regime_summary.get("previous_regime_state") or "unstable").strip().lower(),
            "confidence_delta": round(adaptive_confidence_modifier, 4),
            "confidence_decay_factor": round(decay_factor, 4),
            "top_blocker": str(
                learning_summary.get("candidate_learning_top_reason")
                or adaptive_priority_summary.get("recent_blocker_reason")
                or reactivation_summary.get("top_blocker")
                or "none"
            ),
        }
        family_bucket["first_seen_time"] = family_bucket.get("first_seen_time") or now
        family_bucket["last_seen_time"] = now
        family_bucket["ticker"] = ticker
        family_bucket["family"] = family
        family_bucket["market_type"] = market_type
        family_bucket["last_summary"] = self._build_adaptive_confidence_family_summary(family=family)
        family_bucket["adaptive_confidence_modifier"] = self.to_float(family_bucket["last_summary"].get("avg_confidence_modifier"), 0.0)
        self.last_adaptive_confidence_summary = dict(ticker_bucket["last_summary"])
        self.last_adaptive_confidence_family_summary = dict(family_bucket.get("last_summary") or {})
        self.last_adaptive_confidence_overall_summary = self._build_adaptive_confidence_overall_summary()
        self._emit_adaptive_confidence_telemetry(
            ticker_bucket=ticker_bucket,
            family_bucket=family_bucket,
            force=force or abs(adaptive_confidence_modifier) >= 0.06 or latest_regime_state in {"stable", "high_quality"},
        )
        return ticker_bucket["last_summary"]

    def _get_family_rotation_bucket(self, container_name, key):
        buckets = getattr(self, container_name, None)
        if not isinstance(buckets, dict):
            buckets = {}
            setattr(self, container_name, buckets)
        bucket = buckets.setdefault(
            key,
            {
                "first_seen_time": None,
                "last_seen_time": 0.0,
                "family": None,
                "market_type": None,
                "predictive_regime_score_avg": 0.0,
                "confidence_modifier_avg": 0.0,
                "edge_durability_avg": 0.0,
                "execution_survivability_avg": 0.0,
                "rejection_rate": 0.0,
                "unsafe_price_rate": 0.0,
                "edge_below_cost_rate": 0.0,
                "missing_quotes_rate": 0.0,
                "improving_regime_count": 0,
                "decaying_regime_count": 0,
                "stable_observation_streak": 0.0,
                "clean_orderbook_quality": 0.0,
                "family_rotation_score": 0.0,
                "family_rotation_state": "neutral",
                "family_attention_weight": 1.0,
                "boost_count": 0,
                "decay_count": 0,
                "score_history": deque(maxlen=24),
                "weight_history": deque(maxlen=24),
                "state_history": deque(maxlen=24),
                "blocker_history": deque(maxlen=24),
                "last_summary": {},
            },
        )
        return bucket

    def _classify_family_rotation_state(self, *, family_rotation_score=0.0, improving_regime_count=0, decaying_regime_count=0, top_blocker=None):
        score = self._clamp(self.to_float(family_rotation_score, 0.0))
        top_blocker = str(top_blocker or "").strip().lower()
        improving_regime_count = int(improving_regime_count or 0)
        decaying_regime_count = int(decaying_regime_count or 0)
        if score < 0.22 or top_blocker in {"unsafe_price", "edge_below_cost", "missing_quotes"}:
            return "avoid"
        if score < 0.38 or decaying_regime_count > improving_regime_count:
            return "cold"
        if score < 0.55:
            return "neutral"
        if score < 0.72 or improving_regime_count > 0:
            return "warming"
        if score < 0.88:
            return "hot"
        return "priority_watch"

    def _compute_family_rotation_score(
        self,
        *,
        predictive_regime_summary=None,
        adaptive_confidence_summary=None,
        learning_summary=None,
        family_learning_summary=None,
        family_microstructure_summary=None,
        reactivation_summary=None,
        family_bucket=None,
    ):
        predictive_regime_summary = predictive_regime_summary if isinstance(predictive_regime_summary, dict) else {}
        adaptive_confidence_summary = adaptive_confidence_summary if isinstance(adaptive_confidence_summary, dict) else {}
        learning_summary = learning_summary if isinstance(learning_summary, dict) else {}
        family_learning_summary = family_learning_summary if isinstance(family_learning_summary, dict) else {}
        family_microstructure_summary = family_microstructure_summary if isinstance(family_microstructure_summary, dict) else {}
        reactivation_summary = reactivation_summary if isinstance(reactivation_summary, dict) else {}
        family_bucket = family_bucket if isinstance(family_bucket, dict) else {}

        predictive_regime_score_avg = self._clamp(self.to_float(predictive_regime_summary.get("family_predictive_score"), self.to_float(family_bucket.get("predictive_regime_score_avg"), 0.0)))
        confidence_modifier_avg = self._clamp(self.to_float(adaptive_confidence_summary.get("avg_confidence_modifier"), self.to_float(family_bucket.get("confidence_modifier_avg"), 0.0)))
        edge_durability_avg = self._clamp(self.to_float(family_microstructure_summary.get("avg_edge_durability"), self.to_float(family_bucket.get("edge_durability_avg"), 0.0)))
        execution_survivability_avg = self._clamp(self.to_float(family_microstructure_summary.get("avg_survivability"), self.to_float(family_bucket.get("execution_survivability_avg"), 0.0)))
        clean_orderbook_quality = self._clamp(
            max(
                0.0,
                min(
                    1.0,
                    self.to_float(family_microstructure_summary.get("avg_spread_stability"), 0.0) * 0.45
                    + self.to_float(family_microstructure_summary.get("liquidity_reliability"), 0.0) * 0.35
                    + max(0.0, 1.0 - self.to_float(family_microstructure_summary.get("unstable_rate"), 0.0)) * 0.20,
                ),
            )
        )
        safe_observations = max(self.to_float(family_learning_summary.get("observations"), 0.0), self.to_float(learning_summary.get("observations"), 0.0), 1.0)
        rejection_rate = self._clamp(
            min(
                1.0,
                self.to_float(learning_summary.get("rejection_count"), 0.0) / safe_observations,
            )
        )
        unsafe_price_rate = self._clamp(min(1.0, self.to_float(learning_summary.get("unsafe_price_count"), 0.0) / safe_observations))
        edge_below_cost_rate = self._clamp(min(1.0, self.to_float(learning_summary.get("edge_below_cost_count"), 0.0) / safe_observations))
        missing_quotes_rate = self._clamp(min(1.0, self.to_float(learning_summary.get("missing_quotes_count"), 0.0) / safe_observations))
        improving_regime_count = int(self.to_float(predictive_regime_summary.get("improving_regime_count"), self.to_float(family_bucket.get("improving_regime_count"), 0.0)) or 0)
        decaying_regime_count = int(self.to_float(predictive_regime_summary.get("decaying_regime_count"), self.to_float(family_bucket.get("decaying_regime_count"), 0.0)) or 0)
        stable_observation_streak = self._clamp(
            max(
                self.to_float(adaptive_confidence_summary.get("stable_confidence_count"), 0.0),
                self.to_float(adaptive_confidence_summary.get("adaptive_confidence_modifier"), 0.0) + 0.08,
                self.to_float(family_bucket.get("stable_observation_streak"), 0.0),
            )
        )
        family_learning_score = self._clamp(self.to_float(family_learning_summary.get("family_learning_score"), 0.0))
        reactivation_score = self._clamp(self.to_float(reactivation_summary.get("reactivation_score"), 0.0))
        confidence_boost_count = int(self.to_float(adaptive_confidence_summary.get("confidence_boost_count"), 0.0) or 0)
        confidence_decay_count = int(self.to_float(adaptive_confidence_summary.get("confidence_decay_count"), 0.0) or 0)
        family_usable_orderbook_rate = self._clamp(
            max(
                self.to_float(family_microstructure_summary.get("usable_orderbook_rate"), self.to_float(family_bucket.get("usable_orderbook_rate"), 0.0)),
                self.to_float(family_microstructure_summary.get("liquidity_reliability"), 0.0),
            )
        )
        family_executable_quote_rate = self._clamp(
            max(
                self.to_float(family_microstructure_summary.get("executable_quote_rate"), self.to_float(family_bucket.get("executable_quote_rate"), 0.0)),
                self.to_float(family_microstructure_summary.get("quote_content_pass_rate"), 0.0),
                self.to_float(family_microstructure_summary.get("canonical_pass_rate"), 0.0),
            )
        )
        family_canonical_pass_rate = self._clamp(
            max(
                self.to_float(family_microstructure_summary.get("canonical_pass_rate"), self.to_float(family_bucket.get("canonical_pass_rate"), 0.0)),
                self.to_float(learning_summary.get("canonical_pass_count"), 0.0) / safe_observations,
            )
        )
        family_live_submit_attempt_rate = self._clamp(
            max(
                self.to_float(family_microstructure_summary.get("live_submit_attempt_rate"), self.to_float(family_bucket.get("live_submit_attempt_rate"), 0.0)),
                self.to_float(learning_summary.get("live_submit_attempt_count"), 0.0) / safe_observations,
            )
        )
        family_zero_one_book_rate = self._clamp(
            max(
                self.to_float(family_microstructure_summary.get("zero_one_book_rate"), self.to_float(family_bucket.get("zero_one_book_rate"), 0.0)),
                self.to_float(learning_summary.get("zero_one_book_count"), 0.0) / safe_observations,
            )
        )
        family_malformed_book_rate = self._clamp(
            max(
                self.to_float(family_microstructure_summary.get("malformed_book_rate"), self.to_float(family_bucket.get("malformed_book_rate"), 0.0)),
                self.to_float(learning_summary.get("malformed_book_count"), 0.0) / safe_observations,
            )
        )
        family_missing_spread_rate = self._clamp(
            max(
                self.to_float(family_microstructure_summary.get("missing_spread_rate"), self.to_float(family_bucket.get("missing_spread_rate"), 0.0)),
                self.to_float(learning_summary.get("missing_spread_count"), 0.0) / safe_observations,
                self.to_float(learning_summary.get("missing_quotes_count"), 0.0) / safe_observations,
            )
        )
        base_score = (
            predictive_regime_score_avg * 0.22
            + self._clamp((confidence_modifier_avg + 0.08) / 0.16) * 0.10
            + edge_durability_avg * 0.14
            + execution_survivability_avg * 0.14
            + clean_orderbook_quality * 0.12
            + family_learning_score * 0.10
            + reactivation_score * 0.08
            + stable_observation_streak * 0.10
        )
        penalty = (
            rejection_rate * 0.12
            + unsafe_price_rate * 0.12
            + edge_below_cost_rate * 0.10
            + missing_quotes_rate * 0.08
            + max(0.0, decaying_regime_count - improving_regime_count) * 0.02
            + max(0.0, confidence_decay_count - confidence_boost_count) * 0.01
        )
        routing_signal_bonus = (
            family_usable_orderbook_rate * 0.16
            + family_executable_quote_rate * 0.24
            + family_canonical_pass_rate * 0.20
            + family_live_submit_attempt_rate * 0.16
            + max(0.0, family_usable_orderbook_rate - 0.45) * 0.08
            + max(0.0, family_executable_quote_rate - 0.20) * 0.10
            + max(0.0, family_canonical_pass_rate - 0.15) * 0.08
        )
        dead_book_penalty = (
            family_zero_one_book_rate * 0.30
            + family_malformed_book_rate * 0.30
            + family_missing_spread_rate * 0.20
            + max(0.0, 0.45 - family_usable_orderbook_rate) * 0.18
            + max(0.0, 0.25 - family_executable_quote_rate) * 0.18
            + max(0.0, 0.15 - family_live_submit_attempt_rate) * 0.12
        )
        family_rotation_score = self._clamp(base_score + routing_signal_bonus - penalty - dead_book_penalty)
        family_rotation_state = self._classify_family_rotation_state(
            family_rotation_score=family_rotation_score,
            improving_regime_count=improving_regime_count,
            decaying_regime_count=decaying_regime_count,
            top_blocker=family_learning_summary.get("candidate_learning_top_reason") or learning_summary.get("candidate_learning_top_reason") or adaptive_confidence_summary.get("top_blocker"),
        )
        family_attention_weight = max(0.55, min(1.45, 1.0 + (family_rotation_score - 0.5) * 0.85))
        return {
            "family_rotation_score": round(family_rotation_score, 4),
            "family_rotation_state": family_rotation_state,
            "family_attention_weight": round(family_attention_weight, 4),
            "predictive_regime_score_avg": round(predictive_regime_score_avg, 4),
            "confidence_modifier_avg": round(confidence_modifier_avg, 4),
            "edge_durability_avg": round(edge_durability_avg, 4),
            "execution_survivability_avg": round(execution_survivability_avg, 4),
            "rejection_rate": round(rejection_rate, 4),
            "unsafe_price_rate": round(unsafe_price_rate, 4),
            "edge_below_cost_rate": round(edge_below_cost_rate, 4),
            "missing_quotes_rate": round(missing_quotes_rate, 4),
            "improving_regime_count": int(improving_regime_count),
            "decaying_regime_count": int(decaying_regime_count),
            "stable_observation_streak": round(stable_observation_streak, 4),
            "clean_orderbook_quality": round(clean_orderbook_quality, 4),
        }

    def _build_family_rotation_family_summary(self, family=None):
        family = str(family or "UNKNOWN").strip().upper() or "UNKNOWN"
        family_bucket = self._get_family_rotation_bucket("family_rotation_by_family", f"family:{family}")
        summary = dict(family_bucket.get("last_summary") or {})
        if not summary:
            summary = {
                "family": family,
                "observations": 0,
                "family_rotation_score": round(self.to_float(family_bucket.get("family_rotation_score"), 0.0), 4),
                "family_rotation_state": str(family_bucket.get("family_rotation_state") or "neutral"),
                "family_attention_weight": round(self.to_float(family_bucket.get("family_attention_weight"), 1.0), 4),
                "predictive_regime_score_avg": round(self.to_float(family_bucket.get("predictive_regime_score_avg"), 0.0), 4),
                "confidence_modifier_avg": round(self.to_float(family_bucket.get("confidence_modifier_avg"), 0.0), 4),
                "edge_durability_avg": round(self.to_float(family_bucket.get("edge_durability_avg"), 0.0), 4),
                "execution_survivability_avg": round(self.to_float(family_bucket.get("execution_survivability_avg"), 0.0), 4),
                "rejection_rate": round(self.to_float(family_bucket.get("rejection_rate"), 0.0), 4),
                "unsafe_price_rate": round(self.to_float(family_bucket.get("unsafe_price_rate"), 0.0), 4),
                "edge_below_cost_rate": round(self.to_float(family_bucket.get("edge_below_cost_rate"), 0.0), 4),
                "missing_quotes_rate": round(self.to_float(family_bucket.get("missing_quotes_rate"), 0.0), 4),
                "improving_regime_count": int(family_bucket.get("improving_regime_count", 0) or 0),
                "decaying_regime_count": int(family_bucket.get("decaying_regime_count", 0) or 0),
                "stable_observation_streak": round(self.to_float(family_bucket.get("stable_observation_streak"), 0.0), 4),
                "top_blocker": str(family_bucket.get("top_blocker") or "insufficient_data"),
                "live_arb_enabled": bool(AION_LIVE_ARB_ENABLED),
            }
        family_bucket["last_summary"] = summary
        return summary

    def _build_family_rotation_overall_summary(self):
        family_container = getattr(self, "family_rotation_by_family", {}) or {}
        family_buckets = [bucket for bucket in family_container.values() if isinstance(bucket, dict)]
        if not family_buckets:
            return {
                "scope": "overall",
                "family_count": 0,
                "hottest_family": None,
                "coldest_family": None,
                "priority_watch_family_count": 0,
                "avoid_family_count": 0,
                "avg_family_rotation_score": 0.0,
                "strongest_family_score": 0.0,
                "weakest_family_score": 0.0,
                "top_family_blocker": "insufficient_data",
                "live_arb_enabled": bool(AION_LIVE_ARB_ENABLED),
            }
        best_bucket = max(
            family_buckets,
            key=lambda bucket: (
                self.to_float(bucket.get("family_rotation_score"), 0.0),
                self.to_float(bucket.get("family_attention_weight"), 1.0),
            ),
        )
        worst_bucket = min(
            family_buckets,
            key=lambda bucket: (
                self.to_float(bucket.get("family_rotation_score"), 0.0),
                -self.to_float(bucket.get("family_attention_weight"), 1.0),
            ),
        )
        avg_score = sum(self.to_float(bucket.get("family_rotation_score"), 0.0) or 0.0 for bucket in family_buckets) / max(len(family_buckets), 1)
        priority_watch_family_count = sum(1 for bucket in family_buckets if str(bucket.get("family_rotation_state") or "").strip().lower() == "priority_watch")
        avoid_family_count = sum(1 for bucket in family_buckets if str(bucket.get("family_rotation_state") or "").strip().lower() == "avoid")
        blocker_counts = Counter()
        for bucket in family_buckets:
            for reason in list(bucket.get("blocker_history") or []):
                if reason:
                    blocker_counts[str(reason).strip().lower()] += 1
        return {
            "scope": "overall",
            "family_count": int(len(family_buckets)),
            "hottest_family": str(best_bucket.get("family") or "").strip() or None,
            "coldest_family": str(worst_bucket.get("family") or "").strip() or None,
            "priority_watch_family_count": int(priority_watch_family_count),
            "avoid_family_count": int(avoid_family_count),
            "avg_family_rotation_score": round(avg_score, 4),
            "strongest_family_score": round(self.to_float(best_bucket.get("family_rotation_score"), 0.0) or 0.0, 4),
            "weakest_family_score": round(self.to_float(worst_bucket.get("family_rotation_score"), 0.0) or 0.0, 4),
            "top_family_blocker": blocker_counts.most_common(1)[0][0] if blocker_counts else str(best_bucket.get("top_blocker") or "none"),
            "live_arb_enabled": bool(AION_LIVE_ARB_ENABLED),
        }

    def _emit_family_rotation_telemetry(self, *, family_bucket=None, force=False):
        family_bucket = family_bucket if isinstance(family_bucket, dict) else {}
        family = str(family_bucket.get("family") or "").strip().upper()
        now = time.time()
        summary = family_bucket.get("last_summary") if isinstance(family_bucket.get("last_summary"), dict) else {}
        if not summary:
            summary = self._build_family_rotation_family_summary(family=family)
        last_emit = float(getattr(self, "family_rotation_last_signal_ts_by_key", {}).get(family, 0.0) or 0.0)
        if not force and family and (now - last_emit) < 120.0:
            return None
        if family:
            self.family_rotation_last_signal_ts_by_key[family] = now
        print("[LIVE-FAMILY-ROTATION-MEMORY] " + json.dumps(summary, sort_keys=True, default=str))
        print("[LIVE-FAMILY-ROTATION-SCORE] " + json.dumps(summary, sort_keys=True, default=str))
        print("[LIVE-FAMILY-ROTATION-STATE] " + json.dumps({
            "family": summary.get("family"),
            "family_rotation_state": summary.get("family_rotation_state"),
            "family_rotation_score": summary.get("family_rotation_score"),
            "top_blocker": summary.get("top_blocker"),
        }, sort_keys=True, default=str))
        print("[LIVE-FAMILY-ATTENTION-WEIGHT] " + json.dumps({
            "family": summary.get("family"),
            "family_attention_weight": summary.get("family_attention_weight"),
            "family_rotation_score": summary.get("family_rotation_score"),
            "live_arb_enabled": bool(AION_LIVE_ARB_ENABLED),
        }, sort_keys=True, default=str))
        self.last_family_rotation_summary = dict(summary)
        self.last_family_rotation_family_summary = dict(summary)
        self.last_family_rotation_overall_summary = self._build_family_rotation_overall_summary()
        print("[LIVE-FAMILY-ROTATION-DASHBOARD] " + json.dumps(self.last_family_rotation_overall_summary, sort_keys=True, default=str))
        return summary

    def _update_family_rotation_memory(self, *, family=None, predictive_regime_summary=None, adaptive_confidence_summary=None, learning_summary=None, family_learning_summary=None, family_microstructure_summary=None, reactivation_summary=None, force=False):
        family = str(family or "").strip().upper() or "UNKNOWN"
        predictive_regime_summary = predictive_regime_summary if isinstance(predictive_regime_summary, dict) else {}
        adaptive_confidence_summary = adaptive_confidence_summary if isinstance(adaptive_confidence_summary, dict) else {}
        learning_summary = learning_summary if isinstance(learning_summary, dict) else {}
        family_learning_summary = family_learning_summary if isinstance(family_learning_summary, dict) else {}
        family_microstructure_summary = family_microstructure_summary if isinstance(family_microstructure_summary, dict) else {}
        reactivation_summary = reactivation_summary if isinstance(reactivation_summary, dict) else {}
        family_bucket = self._get_family_rotation_bucket("family_rotation_by_family", f"family:{family}")
        now = time.time()
        predictive_regime_score_avg = self.to_float(predictive_regime_summary.get("family_predictive_score"), self.to_float(family_bucket.get("predictive_regime_score_avg"), 0.0)) or 0.0
        confidence_modifier_avg = self.to_float(adaptive_confidence_summary.get("avg_confidence_modifier"), self.to_float(family_bucket.get("confidence_modifier_avg"), 0.0)) or 0.0
        edge_durability_avg = self.to_float(family_microstructure_summary.get("avg_edge_durability"), self.to_float(family_bucket.get("edge_durability_avg"), 0.0)) or 0.0
        execution_survivability_avg = self.to_float(family_microstructure_summary.get("avg_survivability"), self.to_float(family_bucket.get("execution_survivability_avg"), 0.0)) or 0.0
        rejection_rate = self.to_float(learning_summary.get("rejection_count"), 0.0) / max(self.to_float(family_learning_summary.get("observations"), self.to_float(learning_summary.get("observations"), 1.0)) or 1.0, 1.0)
        unsafe_price_rate = self.to_float(learning_summary.get("unsafe_price_count"), 0.0) / max(self.to_float(family_learning_summary.get("observations"), self.to_float(learning_summary.get("observations"), 1.0)) or 1.0, 1.0)
        edge_below_cost_rate = self.to_float(learning_summary.get("edge_below_cost_count"), 0.0) / max(self.to_float(family_learning_summary.get("observations"), self.to_float(learning_summary.get("observations"), 1.0)) or 1.0, 1.0)
        missing_quotes_rate = self.to_float(learning_summary.get("missing_quotes_count"), 0.0) / max(self.to_float(family_learning_summary.get("observations"), self.to_float(learning_summary.get("observations"), 1.0)) or 1.0, 1.0)
        improving_regime_count = int(self.to_float(predictive_regime_summary.get("improving_regime_count"), family_bucket.get("improving_regime_count", 0)) or 0)
        decaying_regime_count = int(self.to_float(predictive_regime_summary.get("decaying_regime_count"), family_bucket.get("decaying_regime_count", 0)) or 0)
        stable_observation_streak = self._clamp(
            max(
                self.to_float(adaptive_confidence_summary.get("stable_observation_streak"), 0.0),
                self.to_float(family_bucket.get("stable_observation_streak"), 0.0),
                self.to_float(family_learning_summary.get("strongest_watch_count"), 0.0) / max(self.to_float(family_learning_summary.get("observations"), 1.0) or 1.0, 1.0),
            )
        )
        rotation_payload = self._compute_family_rotation_score(
            predictive_regime_summary=predictive_regime_summary,
            adaptive_confidence_summary=adaptive_confidence_summary,
            learning_summary=learning_summary,
            family_learning_summary=family_learning_summary,
            family_microstructure_summary=family_microstructure_summary,
            reactivation_summary=reactivation_summary,
            family_bucket=family_bucket,
        )
        family_bucket["first_seen_time"] = family_bucket.get("first_seen_time") or now
        family_bucket["last_seen_time"] = now
        family_bucket["family"] = family
        family_bucket["market_type"] = str(
            predictive_regime_summary.get("market_type")
            or family_learning_summary.get("market_type")
            or family_microstructure_summary.get("market_type")
            or "unknown"
        ).strip().lower() or "unknown"
        family_bucket["predictive_regime_score_avg"] = round(predictive_regime_score_avg, 4)
        family_bucket["confidence_modifier_avg"] = round(confidence_modifier_avg, 4)
        family_bucket["edge_durability_avg"] = round(edge_durability_avg, 4)
        family_bucket["execution_survivability_avg"] = round(execution_survivability_avg, 4)
        family_bucket["rejection_rate"] = round(rejection_rate, 4)
        family_bucket["unsafe_price_rate"] = round(unsafe_price_rate, 4)
        family_bucket["edge_below_cost_rate"] = round(edge_below_cost_rate, 4)
        family_bucket["missing_quotes_rate"] = round(missing_quotes_rate, 4)
        family_bucket["improving_regime_count"] = improving_regime_count
        family_bucket["decaying_regime_count"] = decaying_regime_count
        family_bucket["stable_observation_streak"] = round(stable_observation_streak, 4)
        family_bucket["clean_orderbook_quality"] = round(self.to_float(rotation_payload.get("clean_orderbook_quality"), 0.0), 4)
        family_bucket["family_rotation_score"] = round(self.to_float(rotation_payload.get("family_rotation_score"), 0.0), 4)
        family_bucket["family_rotation_state"] = rotation_payload.get("family_rotation_state") or "neutral"
        family_bucket["family_attention_weight"] = round(self.to_float(rotation_payload.get("family_attention_weight"), 1.0), 4)
        for key in ("family_rotation_score", "family_attention_weight"):
            family_bucket.setdefault("score_history" if key == "family_rotation_score" else "weight_history", deque(maxlen=24)).append(self.to_float(family_bucket.get(key), 0.0))
        family_bucket.setdefault("state_history", deque(maxlen=24)).append(family_bucket["family_rotation_state"])
        if family_bucket["family_rotation_score"] >= 0.55:
            family_bucket["boost_count"] = int(family_bucket.get("boost_count", 0) or 0) + 1
        else:
            family_bucket["decay_count"] = int(family_bucket.get("decay_count", 0) or 0) + 1
        blocker_reason = (
            str(
                family_learning_summary.get("candidate_learning_top_reason")
                or learning_summary.get("candidate_learning_top_reason")
                or adaptive_confidence_summary.get("top_blocker")
                or reactivation_summary.get("top_blocker")
                or "none"
            ).strip().lower()
        )
        if blocker_reason:
            family_bucket.setdefault("blocker_history", deque(maxlen=24)).append(blocker_reason)
        family_bucket["last_summary"] = {
            "family": family,
            "market_type": family_bucket["market_type"],
            "predictive_regime_score_avg": round(predictive_regime_score_avg, 4),
            "confidence_modifier_avg": round(confidence_modifier_avg, 4),
            "edge_durability_avg": round(edge_durability_avg, 4),
            "execution_survivability_avg": round(execution_survivability_avg, 4),
            "rejection_rate": round(rejection_rate, 4),
            "unsafe_price_rate": round(unsafe_price_rate, 4),
            "edge_below_cost_rate": round(edge_below_cost_rate, 4),
            "missing_quotes_rate": round(missing_quotes_rate, 4),
            "improving_regime_count": improving_regime_count,
            "decaying_regime_count": decaying_regime_count,
            "stable_observation_streak": round(stable_observation_streak, 4),
            "family_rotation_score": round(self.to_float(rotation_payload.get("family_rotation_score"), 0.0), 4),
            "family_rotation_state": rotation_payload.get("family_rotation_state") or "neutral",
            "family_attention_weight": round(self.to_float(rotation_payload.get("family_attention_weight"), 1.0), 4),
            "top_family_blocker": blocker_reason,
            "live_arb_enabled": bool(AION_LIVE_ARB_ENABLED),
        }
        self.last_family_rotation_summary = dict(family_bucket["last_summary"])
        self.last_family_rotation_family_summary = dict(family_bucket["last_summary"])
        self.last_family_rotation_overall_summary = self._build_family_rotation_overall_summary()
        self._emit_family_rotation_telemetry(family_bucket=family_bucket, force=force or family_bucket["family_rotation_score"] >= 0.78 or family_bucket["family_rotation_state"] in {"hot", "priority_watch"})
        return family_bucket["last_summary"]

    def _get_safe_opportunity_queue_bucket(self, container_name, key):
        buckets = getattr(self, container_name, None)
        if not isinstance(buckets, dict):
            buckets = {}
            setattr(self, container_name, buckets)
        bucket = buckets.setdefault(
            key,
            {
                "first_seen_time": None,
                "last_seen_time": 0.0,
                "ticker": None,
                "family": None,
                "queue_hits": 0,
                "near_pass_count": 0,
                "hard_reject_count": 0,
                "latest_blocker": None,
                "best_score_seen": 0.0,
                "best_predictive_regime_score": 0.0,
                "best_confidence_modifier": 0.0,
                "best_family_rotation_score": 0.0,
                "best_edge_durability": 0.0,
                "best_execution_survivability": 0.0,
                "latest_queue_state": "blocked",
                "queue_score": 0.0,
                "queue_state": "blocked",
                "score_history": deque(maxlen=24),
                "state_history": deque(maxlen=24),
                "blocker_history": deque(maxlen=24),
                "last_summary": {},
            },
        )
        return bucket

    def _classify_safe_opportunity_queue_state(self, *, queue_score=0.0, near_pass_count=0, hard_reject_count=0, latest_blocker=None, stale_seconds=0.0, improvement_signal=0.0, confidence_modifier=0.0, family_rotation_score=0.0, edge_durability=0.0, execution_survivability=0.0):
        queue_score = self._clamp(self.to_float(queue_score, 0.0))
        latest_blocker = str(latest_blocker or "").strip().lower()
        near_pass_count = int(near_pass_count or 0)
        hard_reject_count = int(hard_reject_count or 0)
        stale_seconds = max(0.0, self.to_float(stale_seconds, 0.0) or 0.0)
        if stale_seconds >= 21600.0 or (hard_reject_count >= 8 and queue_score < 0.22):
            return "expired"
        if latest_blocker in {"unsafe_price", "missing_quotes", "edge_below_cost", "low_volume"} and hard_reject_count >= 4 and queue_score < 0.35:
            return "expired"
        if latest_blocker in {"unsafe_price", "missing_quotes", "edge_below_cost", "low_volume"} and hard_reject_count >= 3 and queue_score < 0.42:
            return "blocked"
        if queue_score < 0.26:
            return "weak_watch"
        if queue_score < 0.45 or improvement_signal < 0.35:
            return "improving_watch"
        if queue_score < 0.68 or near_pass_count >= 2:
            return "near_ready"
        return "strong_watch"

    def _compute_safe_opportunity_queue_score(
        self,
        *,
        predictive_regime_summary=None,
        adaptive_confidence_summary=None,
        family_rotation_summary=None,
        family_learning_summary=None,
        learning_summary=None,
        family_microstructure_summary=None,
        reactivation_summary=None,
        queue_bucket=None,
        event_weight=0.0,
    ):
        predictive_regime_summary = predictive_regime_summary if isinstance(predictive_regime_summary, dict) else {}
        adaptive_confidence_summary = adaptive_confidence_summary if isinstance(adaptive_confidence_summary, dict) else {}
        family_rotation_summary = family_rotation_summary if isinstance(family_rotation_summary, dict) else {}
        family_learning_summary = family_learning_summary if isinstance(family_learning_summary, dict) else {}
        learning_summary = learning_summary if isinstance(learning_summary, dict) else {}
        family_microstructure_summary = family_microstructure_summary if isinstance(family_microstructure_summary, dict) else {}
        reactivation_summary = reactivation_summary if isinstance(reactivation_summary, dict) else {}
        queue_bucket = queue_bucket if isinstance(queue_bucket, dict) else {}
        predictive_regime_score = self._clamp(self.to_float(predictive_regime_summary.get("predictive_regime_score"), self.to_float(queue_bucket.get("best_predictive_regime_score"), 0.0)))
        confidence_modifier = self._clamp(self.to_float(adaptive_confidence_summary.get("adaptive_confidence_modifier"), self.to_float(queue_bucket.get("best_confidence_modifier"), 0.0)))
        family_rotation_score = self._clamp(self.to_float(family_rotation_summary.get("family_rotation_score"), self.to_float(queue_bucket.get("best_family_rotation_score"), 0.0)))
        edge_durability = self._clamp(self.to_float(family_microstructure_summary.get("avg_edge_durability"), self.to_float(queue_bucket.get("best_edge_durability"), 0.0)))
        execution_survivability = self._clamp(self.to_float(family_microstructure_summary.get("avg_survivability"), self.to_float(queue_bucket.get("best_execution_survivability"), 0.0)))
        learning_score = self._clamp(self.to_float(family_learning_summary.get("family_learning_score"), self.to_float(learning_summary.get("learning_score"), 0.0)))
        near_pass_signal = self._clamp(
            min(
                1.0,
                (
                    self.to_float(queue_bucket.get("near_pass_count"), 0.0) * 0.18
                    + max(0.0, self.to_float(adaptive_confidence_summary.get("confidence_boost_count"), 0.0)) * 0.08
                    + max(0.0, self.to_float(family_rotation_summary.get("priority_watch_family_count"), 0.0)) * 0.04
                    + max(0.0, self.to_float(family_learning_summary.get("strongest_watch_count"), 0.0)) * 0.02
                )
                / max(self.to_float(queue_bucket.get("queue_hits"), 1.0), 1.0),
            )
        )
        improvement_signal = self._clamp(
            max(
                0.0,
                min(
                    1.0,
                    predictive_regime_summary.get("improvement_signal", 0.0) * 0.24
                    + max(0.0, 1.0 - self.to_float(predictive_regime_summary.get("decay_signal"), 0.0)) * 0.12
                    + max(0.0, 1.0 - self.to_float(family_learning_summary.get("avoid_count"), 0.0) / max(self.to_float(family_learning_summary.get("observations"), 1.0), 1.0)) * 0.20
                    + max(0.0, 1.0 - self.to_float(learning_summary.get("rejection_count"), 0.0) / max(self.to_float(learning_summary.get("observations"), 1.0), 1.0)) * 0.20
                    + max(0.0, confidence_modifier + 0.08) * 0.10
                    + family_rotation_score * 0.14,
                ),
            )
        )
        score = (
            predictive_regime_score * 0.18
            + ((confidence_modifier + 0.08) / 0.16 if confidence_modifier is not None else 0.5) * 0.12
            + family_rotation_score * 0.14
            + edge_durability * 0.12
            + execution_survivability * 0.12
            + learning_score * 0.08
            + near_pass_signal * 0.14
            + improvement_signal * 0.10
        )
        hard_penalty = (
            min(1.0, self.to_float(queue_bucket.get("hard_reject_count"), 0.0) / 6.0) * 0.18
            + min(1.0, self.to_float(learning_summary.get("unsafe_price_count"), 0.0) / max(self.to_float(learning_summary.get("observations"), 1.0), 1.0)) * 0.12
            + min(1.0, self.to_float(learning_summary.get("edge_below_cost_count"), 0.0) / max(self.to_float(learning_summary.get("observations"), 1.0), 1.0)) * 0.10
            + min(1.0, self.to_float(learning_summary.get("missing_quotes_count"), 0.0) / max(self.to_float(learning_summary.get("observations"), 1.0), 1.0)) * 0.10
            + min(1.0, self.to_float(learning_summary.get("low_volume_count"), 0.0) / max(self.to_float(learning_summary.get("observations"), 1.0), 1.0)) * 0.08
            + max(0.0, self.to_float(predictive_regime_summary.get("decay_signal"), 0.0) - 0.35) * 0.12
        )
        queue_score = self._clamp(score - hard_penalty + min(0.08, max(0.0, self.to_float(event_weight, 0.0)) * 0.08))
        return {
            "queue_score": round(queue_score, 4),
            "predictive_regime_score": round(predictive_regime_score, 4),
            "confidence_modifier": round(confidence_modifier, 4),
            "family_rotation_score": round(family_rotation_score, 4),
            "edge_durability": round(edge_durability, 4),
            "execution_survivability": round(execution_survivability, 4),
            "learning_score": round(learning_score, 4),
            "near_pass_signal": round(near_pass_signal, 4),
            "improvement_signal": round(improvement_signal, 4),
            "hard_penalty": round(hard_penalty, 4),
        }

    def _build_safe_opportunity_queue_family_summary(self, family=None):
        family = str(family or "UNKNOWN").strip().upper() or "UNKNOWN"
        ticker_container = getattr(self, "safe_opportunity_queue_by_ticker", {}) or {}
        family_buckets = []
        if isinstance(ticker_container, dict):
            for bucket in ticker_container.values():
                if not isinstance(bucket, dict):
                    continue
                if str(bucket.get("family") or "").strip().upper() == family:
                    family_buckets.append(bucket)
        family_bucket = self._get_safe_opportunity_queue_bucket("safe_opportunity_queue_by_family", f"family:{family}")
        if not family_buckets:
            summary = {
                "family": family,
                "total_queued": 0,
                "near_ready_count": 0,
                "strong_watch_count": 0,
                "expired_count": 0,
                "top_queue_ticker": None,
                "top_queue_score": 0.0,
                "top_queue_state": str(family_bucket.get("latest_queue_state") or "blocked"),
                "top_queue_blocker": str(family_bucket.get("latest_blocker") or "insufficient_data"),
                "family_attention_weight": round(self.to_float(family_bucket.get("family_attention_weight"), 1.0) or 1.0, 4),
                "live_arb_enabled": bool(AION_LIVE_ARB_ENABLED),
            }
            family_bucket["last_summary"] = summary
            return summary
        best_bucket = max(
            family_buckets,
            key=lambda bucket: (
                self.to_float(bucket.get("queue_score"), 0.0),
                self.to_float(bucket.get("best_score_seen"), 0.0),
                self.to_float(bucket.get("best_predictive_regime_score"), 0.0),
            ),
        )
        summary = {
            "family": family,
            "total_queued": int(len(family_buckets)),
            "near_ready_count": int(sum(1 for bucket in family_buckets if str(bucket.get("latest_queue_state") or "").strip().lower() == "near_ready")),
            "strong_watch_count": int(sum(1 for bucket in family_buckets if str(bucket.get("latest_queue_state") or "").strip().lower() == "strong_watch")),
            "expired_count": int(sum(1 for bucket in family_buckets if str(bucket.get("latest_queue_state") or "").strip().lower() == "expired")),
            "top_queue_ticker": str(best_bucket.get("ticker") or "").strip() or None,
            "top_queue_score": round(self.to_float(best_bucket.get("queue_score"), 0.0) or 0.0, 4),
            "top_queue_state": str(best_bucket.get("latest_queue_state") or "blocked"),
            "top_queue_blocker": str(best_bucket.get("latest_blocker") or "none"),
            "family_attention_weight": round(self.to_float(family_bucket.get("family_attention_weight"), 1.0) or 1.0, 4),
            "live_arb_enabled": bool(AION_LIVE_ARB_ENABLED),
        }
        family_bucket["last_summary"] = summary
        family_bucket["family_attention_weight"] = summary["family_attention_weight"]
        return summary

    def _build_safe_opportunity_queue_overall_summary(self):
        ticker_container = getattr(self, "safe_opportunity_queue_by_ticker", {}) or {}
        family_container = getattr(self, "safe_opportunity_queue_by_family", {}) or {}
        ticker_buckets = [bucket for bucket in ticker_container.values() if isinstance(bucket, dict)]
        family_buckets = [bucket for bucket in family_container.values() if isinstance(bucket, dict)]
        if not ticker_buckets:
            return {
                "scope": "overall",
                "total_queued": 0,
                "near_ready_count": 0,
                "strong_watch_count": 0,
                "expired_count": 0,
                "top_queue_ticker": None,
                "top_queue_family": None,
                "top_queue_state": "blocked",
                "top_queue_score": 0.0,
                "top_queue_blocker": "insufficient_data",
                "live_arb_enabled": bool(AION_LIVE_ARB_ENABLED),
            }
        best_bucket = max(
            ticker_buckets,
            key=lambda bucket: (
                self.to_float(bucket.get("queue_score"), 0.0),
                self.to_float(bucket.get("best_score_seen"), 0.0),
                self.to_float(bucket.get("best_predictive_regime_score"), 0.0),
            ),
        )
        return {
            "scope": "overall",
            "total_queued": int(len(ticker_buckets)),
            "family_count": int(len(family_buckets)),
            "near_ready_count": int(sum(1 for bucket in ticker_buckets if str(bucket.get("latest_queue_state") or "").strip().lower() == "near_ready")),
            "strong_watch_count": int(sum(1 for bucket in ticker_buckets if str(bucket.get("latest_queue_state") or "").strip().lower() == "strong_watch")),
            "expired_count": int(sum(1 for bucket in ticker_buckets if str(bucket.get("latest_queue_state") or "").strip().lower() == "expired")),
            "top_queue_ticker": str(best_bucket.get("ticker") or "").strip() or None,
            "top_queue_family": str(best_bucket.get("family") or "").strip() or None,
            "top_queue_state": str(best_bucket.get("latest_queue_state") or "blocked"),
            "top_queue_score": round(self.to_float(best_bucket.get("queue_score"), 0.0) or 0.0, 4),
            "top_queue_blocker": str(best_bucket.get("latest_blocker") or "none"),
            "live_arb_enabled": bool(AION_LIVE_ARB_ENABLED),
        }

    def _emit_safe_opportunity_queue_telemetry(self, *, ticker_bucket=None, family_bucket=None, force=False):
        ticker_bucket = ticker_bucket if isinstance(ticker_bucket, dict) else {}
        family_bucket = family_bucket if isinstance(family_bucket, dict) else {}
        ticker = str(ticker_bucket.get("ticker") or "").strip()
        family = str(family_bucket.get("family") or ticker_bucket.get("family") or "").strip().upper() or "UNKNOWN"
        now = time.time()
        summary = ticker_bucket.get("last_summary") if isinstance(ticker_bucket.get("last_summary"), dict) else {}
        if not summary:
            summary = {
                "ticker": ticker or "unknown",
                "family": family,
                "queue_hits": int(ticker_bucket.get("queue_hits", 0) or 0),
                "near_pass_count": int(ticker_bucket.get("near_pass_count", 0) or 0),
                "hard_reject_count": int(ticker_bucket.get("hard_reject_count", 0) or 0),
                "queue_score": round(self.to_float(ticker_bucket.get("queue_score"), 0.0) or 0.0, 4),
                "latest_queue_state": str(ticker_bucket.get("latest_queue_state") or "blocked"),
            }
        emit_key = ticker or family
        last_emit = float(getattr(self, "safe_opportunity_queue_last_signal_ts_by_key", {}).get(emit_key, 0.0) or 0.0)
        if not force and ticker and (now - last_emit) < 120.0:
            return None
        if ticker:
            self.safe_opportunity_queue_last_signal_ts_by_key[ticker] = now
        if family:
            self.safe_opportunity_queue_last_signal_ts_by_key[family] = now
        print("[LIVE-SAFE-OPPORTUNITY-QUEUE] " + json.dumps(summary, sort_keys=True, default=str))
        print("[LIVE-QUEUE-STATE] " + json.dumps({
            "ticker": summary.get("ticker"),
            "family": summary.get("family"),
            "latest_queue_state": summary.get("latest_queue_state"),
            "queue_score": summary.get("queue_score"),
            "latest_blocker": summary.get("latest_blocker"),
        }, sort_keys=True, default=str))
        previous_state = str(ticker_bucket.get("previous_queue_state") or ticker_bucket.get("latest_queue_state") or "blocked").strip().lower()
        current_state = str(summary.get("latest_queue_state") or "blocked").strip().lower()
        state_rank = {"expired": 0, "blocked": 1, "weak_watch": 2, "improving_watch": 3, "near_ready": 4, "strong_watch": 5}
        if current_state == "expired":
            print("[LIVE-QUEUE-EXPIRATION] " + json.dumps({
                "ticker": summary.get("ticker"),
                "family": summary.get("family"),
                "previous_state": previous_state,
                "new_state": current_state,
                "queue_score": summary.get("queue_score"),
                "trigger_reason": summary.get("expiration_reason") or summary.get("latest_blocker") or "expired",
            }, sort_keys=True, default=str))
        elif state_rank.get(current_state, 0) > state_rank.get(previous_state, 0):
            print("[LIVE-QUEUE-PROMOTION] " + json.dumps({
                "ticker": summary.get("ticker"),
                "family": summary.get("family"),
                "previous_state": previous_state,
                "new_state": current_state,
                "queue_delta": round(self.to_float(summary.get("queue_score"), 0.0) - self.to_float(ticker_bucket.get("queue_score"), 0.0), 4),
                "trigger_reason": summary.get("promotion_reason") or summary.get("latest_blocker") or "improving_signals",
            }, sort_keys=True, default=str))
        self.last_safe_opportunity_queue_summary = dict(summary)
        self.last_safe_opportunity_queue_family_summary = dict(family_bucket.get("last_summary") or {})
        self.last_safe_opportunity_queue_overall_summary = self._build_safe_opportunity_queue_overall_summary()
        print("[LIVE-QUEUE-DASHBOARD] " + json.dumps(self.last_safe_opportunity_queue_overall_summary, sort_keys=True, default=str))
        return summary

    def _update_safe_opportunity_queue(self, *, ticker=None, family=None, event_type=None, reason=None, score=None, spread=None, predictive_regime_summary=None, adaptive_confidence_summary=None, family_rotation_summary=None, learning_summary=None, family_learning_summary=None, family_microstructure_summary=None, reactivation_summary=None, details=None, force=False):
        ticker = str(ticker or "").strip()
        if not ticker:
            return None
        family = str(family or "").strip().upper() or "UNKNOWN"
        event_type = str(event_type or "reject").strip().lower()
        reason = str(reason or "unknown").strip().lower()
        predictive_regime_summary = predictive_regime_summary if isinstance(predictive_regime_summary, dict) else {}
        adaptive_confidence_summary = adaptive_confidence_summary if isinstance(adaptive_confidence_summary, dict) else {}
        family_rotation_summary = family_rotation_summary if isinstance(family_rotation_summary, dict) else {}
        learning_summary = learning_summary if isinstance(learning_summary, dict) else {}
        family_learning_summary = family_learning_summary if isinstance(family_learning_summary, dict) else {}
        family_microstructure_summary = family_microstructure_summary if isinstance(family_microstructure_summary, dict) else {}
        reactivation_summary = reactivation_summary if isinstance(reactivation_summary, dict) else {}
        details = details if isinstance(details, dict) else {}
        queue_bucket = self._get_safe_opportunity_queue_bucket("safe_opportunity_queue_by_ticker", f"ticker:{ticker}")
        family_bucket = self._get_safe_opportunity_queue_bucket("safe_opportunity_queue_by_family", f"family:{family}")
        now = time.time()
        last_seen = float(queue_bucket.get("last_seen_time", 0.0) or 0.0)
        stale_seconds = max(0.0, now - last_seen) if last_seen > 0 else 0.0
        queue_bucket["first_seen_time"] = queue_bucket.get("first_seen_time") or now
        queue_bucket["last_seen_time"] = now
        queue_bucket["ticker"] = ticker
        queue_bucket["family"] = family
        queue_bucket["queue_hits"] = int(queue_bucket.get("queue_hits", 0) or 0) + 1
        queue_bucket["latest_blocker"] = reason
        if event_type == "near_pass":
            queue_bucket["near_pass_count"] = int(queue_bucket.get("near_pass_count", 0) or 0) + 1
        else:
            queue_bucket["hard_reject_count"] = int(queue_bucket.get("hard_reject_count", 0) or 0) + 1
        if score is not None:
            try:
                score_value = float(score)
            except (TypeError, ValueError):
                score_value = 0.0
            queue_bucket["best_score_seen"] = max(self.to_float(queue_bucket.get("best_score_seen"), 0.0) or 0.0, score_value)
        queue_bucket["best_predictive_regime_score"] = max(self.to_float(queue_bucket.get("best_predictive_regime_score"), 0.0) or 0.0, self.to_float(predictive_regime_summary.get("predictive_regime_score"), self.to_float(predictive_regime_summary.get("family_predictive_score"), 0.0)) or 0.0)
        queue_bucket["best_confidence_modifier"] = max(self.to_float(queue_bucket.get("best_confidence_modifier"), 0.0) or 0.0, self.to_float(adaptive_confidence_summary.get("adaptive_confidence_modifier"), self.to_float(adaptive_confidence_summary.get("avg_confidence_modifier"), 0.0)) or 0.0)
        queue_bucket["best_family_rotation_score"] = max(self.to_float(queue_bucket.get("best_family_rotation_score"), 0.0) or 0.0, self.to_float(family_rotation_summary.get("family_rotation_score"), self.to_float(family_rotation_summary.get("avg_family_rotation_score"), 0.0)) or 0.0)
        queue_bucket["best_edge_durability"] = max(self.to_float(queue_bucket.get("best_edge_durability"), 0.0) or 0.0, self.to_float(family_microstructure_summary.get("avg_edge_durability"), self.to_float(reactivation_summary.get("best_reactivation_score"), 0.0)) or 0.0)
        queue_bucket["best_execution_survivability"] = max(self.to_float(queue_bucket.get("best_execution_survivability"), 0.0) or 0.0, self.to_float(family_microstructure_summary.get("avg_survivability"), 0.0) or 0.0)
        queue_bucket.setdefault("score_history", deque(maxlen=24)).append(round(self.to_float(score, self.to_float(queue_bucket.get("best_score_seen"), 0.0)) or 0.0, 4))
        current_score = self._compute_safe_opportunity_queue_score(
            predictive_regime_summary=predictive_regime_summary if isinstance(predictive_regime_summary, dict) else self._build_predictive_regime_family_summary(family=family),
            adaptive_confidence_summary=adaptive_confidence_summary if isinstance(adaptive_confidence_summary, dict) else self._build_adaptive_confidence_family_summary(family=family),
            family_rotation_summary=family_rotation_summary if isinstance(family_rotation_summary, dict) else self._build_family_rotation_family_summary(family=family),
            family_learning_summary=family_learning_summary if isinstance(family_learning_summary, dict) else self._build_candidate_learning_family_summary(family=family),
            learning_summary=learning_summary if isinstance(learning_summary, dict) else {},
            family_microstructure_summary=family_microstructure_summary if isinstance(family_microstructure_summary, dict) else {},
            reactivation_summary=reactivation_summary if isinstance(reactivation_summary, dict) else {},
            queue_bucket=queue_bucket,
            event_weight=1.0 if event_type == "near_pass" else 0.4,
        )
        queue_bucket["queue_score"] = round(self.to_float(current_score.get("queue_score"), 0.0), 4)
        queue_bucket["previous_queue_state"] = str(queue_bucket.get("latest_queue_state") or "blocked").strip().lower()
        queue_bucket["latest_queue_state"] = self._classify_safe_opportunity_queue_state(
            queue_score=queue_bucket["queue_score"],
            near_pass_count=queue_bucket.get("near_pass_count", 0),
            hard_reject_count=queue_bucket.get("hard_reject_count", 0),
            latest_blocker=reason,
            stale_seconds=stale_seconds,
            improvement_signal=current_score.get("improvement_signal"),
            confidence_modifier=current_score.get("confidence_modifier"),
            family_rotation_score=current_score.get("family_rotation_score"),
            edge_durability=current_score.get("edge_durability"),
            execution_survivability=current_score.get("execution_survivability"),
        )
        queue_bucket["queue_state"] = queue_bucket["latest_queue_state"]
        queue_bucket.setdefault("state_history", deque(maxlen=24)).append(queue_bucket["latest_queue_state"])
        if queue_bucket["latest_queue_state"] in {"near_ready", "strong_watch"}:
            queue_bucket["best_score_seen"] = max(self.to_float(queue_bucket.get("best_score_seen"), 0.0) or 0.0, queue_bucket["queue_score"])
        if queue_bucket["latest_queue_state"] == "expired":
            queue_bucket["expiration_reason"] = reason
        elif queue_bucket["latest_queue_state"] in {"near_ready", "strong_watch"}:
            queue_bucket["promotion_reason"] = reason
        queue_bucket["last_summary"] = {
            "ticker": ticker,
            "family": family,
            "queue_hits": int(queue_bucket.get("queue_hits", 0) or 0),
            "near_pass_count": int(queue_bucket.get("near_pass_count", 0) or 0),
            "hard_reject_count": int(queue_bucket.get("hard_reject_count", 0) or 0),
            "latest_blocker": reason,
            "best_score_seen": round(self.to_float(queue_bucket.get("best_score_seen"), 0.0) or 0.0, 4),
            "best_predictive_regime_score": round(self.to_float(queue_bucket.get("best_predictive_regime_score"), 0.0) or 0.0, 4),
            "best_confidence_modifier": round(self.to_float(queue_bucket.get("best_confidence_modifier"), 0.0) or 0.0, 4),
            "best_family_rotation_score": round(self.to_float(queue_bucket.get("best_family_rotation_score"), 0.0) or 0.0, 4),
            "best_edge_durability": round(self.to_float(queue_bucket.get("best_edge_durability"), 0.0) or 0.0, 4),
            "best_execution_survivability": round(self.to_float(queue_bucket.get("best_execution_survivability"), 0.0) or 0.0, 4),
            "latest_queue_state": queue_bucket["latest_queue_state"],
            "queue_state": queue_bucket["queue_state"],
            "queue_score": round(queue_bucket["queue_score"], 4),
            "promotion_reason": queue_bucket.get("promotion_reason"),
            "expiration_reason": queue_bucket.get("expiration_reason"),
            "live_arb_enabled": bool(AION_LIVE_ARB_ENABLED),
        }
        family_bucket["first_seen_time"] = family_bucket.get("first_seen_time") or now
        family_bucket["last_seen_time"] = now
        family_bucket["family"] = family
        family_bucket["ticker"] = ticker
        family_bucket["latest_queue_state"] = queue_bucket["latest_queue_state"]
        family_bucket["latest_blocker"] = reason
        family_bucket["queue_score"] = max(self.to_float(family_bucket.get("queue_score"), 0.0) or 0.0, queue_bucket["queue_score"])
        family_bucket["last_summary"] = self._build_safe_opportunity_queue_family_summary(family=family)
        self.last_safe_opportunity_queue_summary = dict(queue_bucket["last_summary"])
        self.last_safe_opportunity_queue_family_summary = dict(family_bucket.get("last_summary") or {})
        self.last_safe_opportunity_queue_overall_summary = self._build_safe_opportunity_queue_overall_summary()
        self._emit_safe_opportunity_queue_telemetry(
            ticker_bucket=queue_bucket,
            family_bucket=family_bucket,
            force=force or queue_bucket["latest_queue_state"] in {"near_ready", "strong_watch", "expired"},
        )
        if queue_bucket["latest_queue_state"] == "expired" and stale_seconds >= 86400.0:
            getattr(self, "safe_opportunity_queue_by_ticker", {}).pop(f"ticker:{ticker}", None)
        return queue_bucket["last_summary"]

    def _get_entry_timing_fusion_bucket(self, container_name, key):
        buckets = getattr(self, container_name, None)
        if not isinstance(buckets, dict):
            buckets = {}
            setattr(self, container_name, buckets)
        bucket = buckets.setdefault(
            key,
            {
                "first_seen_time": None,
                "last_seen_time": 0.0,
                "ticker": None,
                "family": None,
                "observations": 0,
                "timing_aligned_count": 0,
                "improving_timing_count": 0,
                "too_early_count": 0,
                "late_decay_count": 0,
                "unsafe_timing_count": 0,
                "best_timing_fusion_score": 0.0,
                "latest_timing_fusion_score": 0.0,
                "latest_timing_fusion_state": "unknown",
                "latest_phase55_status": "unknown",
                "latest_blocker_reason": "unknown",
                "last_summary": {},
                "score_history": deque(maxlen=24),
                "state_history": deque(maxlen=24),
            },
        )
        return bucket

    def _classify_entry_timing_fusion_state(
        self,
        *,
        entry_timing_fusion_score=0.0,
        phase55_ready=False,
        crossover_detected=False,
        micro_pullback_detected=False,
        predictive_support=0.0,
        confidence_support=0.0,
        queue_support=0.0,
        microstructure_support=0.0,
        spread_support=0.0,
        execution_survivability_support=0.0,
        blocker_reason=None,
    ):
        score = self._clamp(self.to_float(entry_timing_fusion_score, 0.0))
        predictive_support = self._clamp(self.to_float(predictive_support, 0.0))
        confidence_support = self._clamp(self.to_float(confidence_support, 0.0))
        queue_support = self._clamp(self.to_float(queue_support, 0.0))
        microstructure_support = self._clamp(self.to_float(microstructure_support, 0.0))
        spread_support = self._clamp(self.to_float(spread_support, 0.0))
        execution_survivability_support = self._clamp(self.to_float(execution_survivability_support, 0.0))
        blocker_reason = str(blocker_reason or "").strip().lower()
        unsafe_blockers = {
            "unsafe_price",
            "missing_quotes",
            "low_volume",
            "edge_below_cost",
            "immediate_entry_protection",
            "immediate_reject",
            "probability_block",
            "capital_block",
            "psychology_block",
            "missing_phase55_status",
        }
        if blocker_reason in unsafe_blockers:
            return "unsafe"
        if not phase55_ready and blocker_reason in {"phase55_status_insufficient_data", "trigger_wait", "pullback_wait"} and score < 0.40:
            return "too_early"
        if phase55_ready and score >= 0.62 and predictive_support >= 0.50 and confidence_support >= 0.50 and queue_support >= 0.35 and microstructure_support >= 0.45 and spread_support >= 0.45 and execution_survivability_support >= 0.45:
            return "timing_aligned"
        if score < 0.30 or (blocker_reason in {"phase55_status_trigger_wait", "phase55_status_pullback_wait"} and execution_survivability_support < 0.45):
            return "late_decay"
        if crossover_detected or micro_pullback_detected or predictive_support >= 0.45 or confidence_support >= 0.45 or queue_support >= 0.40 or microstructure_support >= 0.40:
            return "improving"
        if phase55_ready:
            return "timing_aligned" if score >= 0.55 else "improving"
        return "unknown"

    def _compute_entry_timing_fusion_score(
        self,
        *,
        phase55_status=None,
        entry_ready_reason=None,
        pullback_rule_path=None,
        crossover_detected=False,
        micro_pullback_detected=False,
        predictive_regime_score=0.0,
        adaptive_confidence_modifier=0.0,
        adaptive_confidence_score=0.0,
        family_rotation_score=0.0,
        queue_state=None,
        queue_score=0.0,
        edge_durability_score=0.0,
        execution_survivability_score=0.0,
        spread_stability=0.0,
        quote_stability=0.0,
        blocker_reason=None,
        family_learning_score=0.0,
        microstructure_state=None,
        market_type=None,
        memory_bucket=None,
    ):
        phase55_status = str(phase55_status or "unknown").strip().lower()
        entry_ready_reason = str(entry_ready_reason or "").strip().lower()
        pullback_rule_path = str(pullback_rule_path or "").strip().lower()
        queue_state = str(queue_state or "unknown").strip().lower()
        blocker_reason = str(blocker_reason or "").strip().lower()
        memory_bucket = memory_bucket if isinstance(memory_bucket, dict) else {}
        predictive_regime_score = self._clamp(self.to_float(predictive_regime_score, 0.0))
        adaptive_confidence_modifier = self._clamp(self.to_float(adaptive_confidence_modifier, 0.0))
        adaptive_confidence_score = self._clamp(self.to_float(adaptive_confidence_score, 0.0))
        family_rotation_score = self._clamp(self.to_float(family_rotation_score, 0.0))
        queue_score = self._clamp(self.to_float(queue_score, 0.0))
        edge_durability_score = self._clamp(self.to_float(edge_durability_score, 0.0))
        execution_survivability_score = self._clamp(self.to_float(execution_survivability_score, 0.0))
        spread_stability = self._clamp(self.to_float(spread_stability, 0.0))
        quote_stability = self._clamp(self.to_float(quote_stability, 0.0))
        family_learning_score = self._clamp(self.to_float(family_learning_score, 0.0))
        phase55_ready = phase55_status == "entry_ready"
        predictive_support = self._clamp(
            predictive_regime_score * 0.55
            + max(0.0, self.to_float(memory_bucket.get("improvement_signal"), 0.0)) * 0.20
            + max(0.0, 1.0 - self.to_float(memory_bucket.get("decay_signal"), 0.0)) * 0.10
            + max(0.0, family_learning_score) * 0.15
        )
        confidence_support = self._clamp(
            ((adaptive_confidence_modifier + 0.08) / 0.16) * 0.45
            + adaptive_confidence_score * 0.55
        )
        queue_support = self._clamp(
            queue_score * 0.55
            + {"strong_watch": 1.0, "near_ready": 0.85, "improving_watch": 0.60, "weak_watch": 0.30, "blocked": 0.10, "expired": 0.0}.get(queue_state, 0.20) * 0.45
        )
        microstructure_support = self._clamp(
            edge_durability_score * 0.34
            + execution_survivability_score * 0.36
            + spread_stability * 0.16
            + quote_stability * 0.14
        )
        spread_support = self._clamp(spread_stability * 0.70 + quote_stability * 0.30)
        execution_support = self._clamp(execution_survivability_score * 0.80 + edge_durability_score * 0.20)
        timing_component = 0.20 if phase55_ready else 0.0
        if crossover_detected:
            timing_component += 0.10
        if micro_pullback_detected:
            timing_component += 0.08
        if "fallback" in entry_ready_reason or "override" in entry_ready_reason:
            timing_component -= 0.03
        if pullback_rule_path in {"adaptive_recent_crossover_override", "fallback_no_pullback"}:
            timing_component += 0.03
        if blocker_reason in {"unsafe_price", "missing_quotes", "low_volume", "edge_below_cost"}:
            timing_component -= 0.12
        if blocker_reason in {"immediate_entry_protection", "immediate_reject", "probability_block", "capital_block", "psychology_block"}:
            timing_component -= 0.15
        raw_score = (
            predictive_support * 0.22
            + confidence_support * 0.18
            + queue_support * 0.16
            + microstructure_support * 0.18
            + spread_support * 0.08
            + execution_support * 0.08
            + timing_component * 0.10
        )
        if phase55_ready:
            raw_score += 0.05
        if blocker_reason in {"unsafe_price", "missing_quotes", "low_volume", "edge_below_cost"}:
            raw_score -= 0.08
        if blocker_reason in {"phase55_status_insufficient_data", "phase55_status_trigger_wait", "phase55_status_pullback_wait"}:
            raw_score -= 0.03
        raw_score = self._clamp(raw_score)
        if phase55_ready:
            fusion_adjustment = min(0.06, max(-0.02, (raw_score - 0.52) * 0.12))
        elif blocker_reason in {"unsafe_price", "missing_quotes", "low_volume", "edge_below_cost"}:
            fusion_adjustment = max(-0.06, min(0.0, (raw_score - 0.45) * 0.10 - 0.02))
        else:
            fusion_adjustment = max(-0.03, min(0.04, (raw_score - 0.5) * 0.10))
        return {
            "entry_timing_fusion_score": round(raw_score, 4),
            "timing_fusion_adjustment": round(fusion_adjustment, 4),
            "predictive_support": round(predictive_support, 4),
            "confidence_support": round(confidence_support, 4),
            "queue_support": round(queue_support, 4),
            "microstructure_support": round(microstructure_support, 4),
            "spread_support": round(spread_support, 4),
            "execution_survivability_support": round(execution_support, 4),
            "phase55_ready_support": round(1.0 if phase55_ready else 0.0, 4),
            "crossover_support": round(1.0 if crossover_detected else 0.0, 4),
            "pullback_support": round(1.0 if micro_pullback_detected else 0.0, 4),
        }

    def _build_entry_timing_fusion_family_summary(self, family=None):
        family = str(family or "UNKNOWN").strip().upper() or "UNKNOWN"
        ticker_container = getattr(self, "entry_timing_fusion_by_ticker", {}) or {}
        family_buckets = []
        if isinstance(ticker_container, dict):
            for bucket in ticker_container.values():
                if not isinstance(bucket, dict):
                    continue
                if str(bucket.get("family") or "").strip().upper() == family:
                    family_buckets.append(bucket)
        family_bucket = self._get_entry_timing_fusion_bucket("entry_timing_fusion_by_family", f"family:{family}")
        if not family_buckets:
            summary = {
                "family": family,
                "observations": 0,
                "timing_aligned_count": 0,
                "improving_timing_count": 0,
                "too_early_count": 0,
                "late_decay_count": 0,
                "unsafe_timing_count": 0,
                "best_timing_fusion_ticker": None,
                "best_timing_fusion_score": 0.0,
                "best_timing_fusion_state": str(family_bucket.get("latest_timing_fusion_state") or "unknown"),
                "latest_phase55_status": str(family_bucket.get("latest_phase55_status") or "unknown"),
                "latest_blocker_reason": str(family_bucket.get("latest_blocker_reason") or "unknown"),
                "live_arb_enabled": bool(AION_LIVE_ARB_ENABLED),
            }
            family_bucket["last_summary"] = summary
            return summary
        best_bucket = max(
            family_buckets,
            key=lambda bucket: (
                self.to_float(bucket.get("latest_timing_fusion_score"), 0.0),
                self.to_float(bucket.get("best_timing_fusion_score"), 0.0),
                int(bucket.get("timing_aligned_count", 0) or 0),
            ),
        )
        summary = {
            "family": family,
            "observations": int(sum(int(bucket.get("observations", 0) or 0) for bucket in family_buckets)),
            "timing_aligned_count": int(sum(int(bucket.get("timing_aligned_count", 0) or 0) for bucket in family_buckets)),
            "improving_timing_count": int(sum(int(bucket.get("improving_timing_count", 0) or 0) for bucket in family_buckets)),
            "too_early_count": int(sum(int(bucket.get("too_early_count", 0) or 0) for bucket in family_buckets)),
            "late_decay_count": int(sum(int(bucket.get("late_decay_count", 0) or 0) for bucket in family_buckets)),
            "unsafe_timing_count": int(sum(int(bucket.get("unsafe_timing_count", 0) or 0) for bucket in family_buckets)),
            "best_timing_fusion_ticker": str(best_bucket.get("ticker") or "").strip() or None,
            "best_timing_fusion_score": round(self.to_float(best_bucket.get("latest_timing_fusion_score"), 0.0) or 0.0, 4),
            "best_timing_fusion_state": str(best_bucket.get("latest_timing_fusion_state") or "unknown"),
            "latest_phase55_status": str(best_bucket.get("latest_phase55_status") or "unknown"),
            "latest_blocker_reason": str(best_bucket.get("latest_blocker_reason") or "unknown"),
            "live_arb_enabled": bool(AION_LIVE_ARB_ENABLED),
        }
        family_bucket["last_summary"] = summary
        return summary

    def _build_entry_timing_fusion_overall_summary(self):
        ticker_container = getattr(self, "entry_timing_fusion_by_ticker", {}) or {}
        family_container = getattr(self, "entry_timing_fusion_by_family", {}) or {}
        ticker_buckets = [bucket for bucket in ticker_container.values() if isinstance(bucket, dict)]
        family_buckets = [bucket for bucket in family_container.values() if isinstance(bucket, dict)]
        if not ticker_buckets:
            return {
                "scope": "overall",
                "total_queued": 0,
                "timing_aligned_count": 0,
                "improving_timing_count": 0,
                "too_early_count": 0,
                "late_decay_count": 0,
                "unsafe_timing_count": 0,
                "best_timing_fusion_ticker": None,
                "best_timing_fusion_family": None,
                "best_timing_fusion_state": "unknown",
                "best_timing_fusion_score": 0.0,
                "latest_blocker_reason": "insufficient_data",
                "live_arb_enabled": bool(AION_LIVE_ARB_ENABLED),
            }
        best_bucket = max(
            ticker_buckets,
            key=lambda bucket: (
                self.to_float(bucket.get("latest_timing_fusion_score"), 0.0),
                self.to_float(bucket.get("best_timing_fusion_score"), 0.0),
                int(bucket.get("timing_aligned_count", 0) or 0),
            ),
        )
        return {
            "scope": "overall",
            "total_queued": int(len(ticker_buckets)),
            "family_count": int(len(family_buckets)),
            "timing_aligned_count": int(sum(int(bucket.get("timing_aligned_count", 0) or 0) for bucket in ticker_buckets)),
            "improving_timing_count": int(sum(int(bucket.get("improving_timing_count", 0) or 0) for bucket in ticker_buckets)),
            "too_early_count": int(sum(int(bucket.get("too_early_count", 0) or 0) for bucket in ticker_buckets)),
            "late_decay_count": int(sum(int(bucket.get("late_decay_count", 0) or 0) for bucket in ticker_buckets)),
            "unsafe_timing_count": int(sum(int(bucket.get("unsafe_timing_count", 0) or 0) for bucket in ticker_buckets)),
            "best_timing_fusion_ticker": str(best_bucket.get("ticker") or "").strip() or None,
            "best_timing_fusion_family": str(best_bucket.get("family") or "").strip() or None,
            "best_timing_fusion_state": str(best_bucket.get("latest_timing_fusion_state") or "unknown"),
            "best_timing_fusion_score": round(self.to_float(best_bucket.get("latest_timing_fusion_score"), 0.0) or 0.0, 4),
            "latest_blocker_reason": str(best_bucket.get("latest_blocker_reason") or "unknown"),
            "live_arb_enabled": bool(AION_LIVE_ARB_ENABLED),
        }

    def _emit_entry_timing_fusion_telemetry(self, *, ticker_bucket=None, family_bucket=None, force=False):
        ticker_bucket = ticker_bucket if isinstance(ticker_bucket, dict) else {}
        family_bucket = family_bucket if isinstance(family_bucket, dict) else {}
        ticker = str(ticker_bucket.get("ticker") or "").strip()
        family = str(ticker_bucket.get("family") or family_bucket.get("family") or "").strip().upper() or "UNKNOWN"
        now = time.time()
        summary = ticker_bucket.get("last_summary") if isinstance(ticker_bucket.get("last_summary"), dict) else {}
        if not summary:
            summary = {
                "ticker": ticker or "unknown",
                "family": family,
                "entry_timing_fusion_score": round(self.to_float(ticker_bucket.get("latest_timing_fusion_score"), 0.0) or 0.0, 4),
                "entry_timing_fusion_state": str(ticker_bucket.get("latest_timing_fusion_state") or "unknown"),
                "phase55_status": str(ticker_bucket.get("latest_phase55_status") or "unknown"),
                "latest_blocker_reason": str(ticker_bucket.get("latest_blocker_reason") or "unknown"),
            }
        emit_key = ticker or family
        last_emit = float(getattr(self, "entry_timing_fusion_last_signal_ts_by_key", {}).get(emit_key, 0.0) or 0.0)
        if not force and ticker and (now - last_emit) < 120.0:
            return None
        if ticker:
            self.entry_timing_fusion_last_signal_ts_by_key[ticker] = now
        if family:
            self.entry_timing_fusion_last_signal_ts_by_key[family] = now
        print("[LIVE-ENTRY-TIMING-FUSION] " + json.dumps(summary, sort_keys=True, default=str))
        print("[LIVE-TIMING-FUSION-STATE] " + json.dumps({
            "ticker": summary.get("ticker"),
            "family": summary.get("family"),
            "entry_timing_fusion_state": summary.get("entry_timing_fusion_state"),
            "entry_timing_fusion_score": summary.get("entry_timing_fusion_score"),
            "phase55_status": summary.get("phase55_status"),
            "latest_blocker_reason": summary.get("latest_blocker_reason"),
        }, sort_keys=True, default=str))
        print("[LIVE-TIMING-FUSION-REASON] " + json.dumps({
            "ticker": summary.get("ticker"),
            "family": summary.get("family"),
            "phase55_ready": summary.get("phase55_ready_support"),
            "predictive_support": summary.get("predictive_support"),
            "confidence_support": summary.get("confidence_support"),
            "queue_support": summary.get("queue_support"),
            "microstructure_support": summary.get("microstructure_support"),
            "spread_support": summary.get("spread_support"),
            "execution_survivability_support": summary.get("execution_survivability_support"),
            "blocker_reason": summary.get("latest_blocker_reason"),
            "crossover_support": summary.get("crossover_support"),
            "pullback_support": summary.get("pullback_support"),
        }, sort_keys=True, default=str))
        self.last_entry_timing_fusion_summary = dict(summary)
        self.last_entry_timing_fusion_family_summary = dict(family_bucket.get("last_summary") or {})
        self.last_entry_timing_fusion_overall_summary = self._build_entry_timing_fusion_overall_summary()
        print("[LIVE-TIMING-FUSION-DASHBOARD] " + json.dumps(self.last_entry_timing_fusion_overall_summary, sort_keys=True, default=str))
        return summary

    def _update_entry_timing_fusion(self, *, ticker=None, family=None, market=None, q=None, predictive_regime_summary=None, adaptive_confidence_summary=None, family_rotation_summary=None, queue_summary=None, microstructure_summary=None, learning_summary=None, family_learning_summary=None, entry_timing_observation=None, memory_bucket=None, force=False):
        ticker = str(ticker or getattr(q, "ticker", "") or "").strip()
        if not ticker:
            return None
        family = str(family or getattr(q, "family", "") or "").strip().upper() or "UNKNOWN"
        market = market if isinstance(market, dict) else {}
        predictive_regime_summary = predictive_regime_summary if isinstance(predictive_regime_summary, dict) else {}
        adaptive_confidence_summary = adaptive_confidence_summary if isinstance(adaptive_confidence_summary, dict) else {}
        family_rotation_summary = family_rotation_summary if isinstance(family_rotation_summary, dict) else {}
        queue_summary = queue_summary if isinstance(queue_summary, dict) else {}
        microstructure_summary = microstructure_summary if isinstance(microstructure_summary, dict) else {}
        learning_summary = learning_summary if isinstance(learning_summary, dict) else {}
        family_learning_summary = family_learning_summary if isinstance(family_learning_summary, dict) else {}
        entry_timing_observation = entry_timing_observation if isinstance(entry_timing_observation, dict) else {}
        memory_bucket = memory_bucket if isinstance(memory_bucket, dict) else {}
        ticker_bucket = self._get_entry_timing_fusion_bucket("entry_timing_fusion_by_ticker", f"ticker:{ticker}")
        family_bucket = self._get_entry_timing_fusion_bucket("entry_timing_fusion_by_family", f"family:{family}")
        now = time.time()
        ticker_bucket["first_seen_time"] = ticker_bucket.get("first_seen_time") or now
        ticker_bucket["last_seen_time"] = now
        ticker_bucket["ticker"] = ticker
        ticker_bucket["family"] = family
        ticker_bucket["observations"] = int(ticker_bucket.get("observations", 0) or 0) + 1
        phase55_status = str(entry_timing_observation.get("phase55_status") or "unknown").strip().lower()
        entry_ready_reason = str(entry_timing_observation.get("entry_ready_reason") or entry_timing_observation.get("decision_reason") or "").strip().lower()
        pullback_rule_path = str(entry_timing_observation.get("pullback_rule_path") or "").strip().lower()
        crossover_detected = bool(entry_timing_observation.get("crossover_detected"))
        micro_pullback_detected = bool(entry_timing_observation.get("micro_pullback_detected"))
        blocker_reason = str(
            entry_timing_observation.get("reject_reason")
            or entry_timing_observation.get("block_reason")
            or entry_timing_observation.get("phase55_status")
            or queue_summary.get("top_queue_blocker")
            or queue_summary.get("latest_blocker")
            or "unknown"
        ).strip().lower()
        queue_state = str(queue_summary.get("top_queue_state") or queue_summary.get("queue_state") or "unknown").strip().lower()
        queue_score = self.to_float(queue_summary.get("top_queue_score"), self.to_float(queue_summary.get("queue_score"), 0.0))
        predictive_regime_score = self.to_float(
            predictive_regime_summary.get("predictive_regime_score"),
            self.to_float(predictive_regime_summary.get("top_predictive_score"), 0.0),
        )
        adaptive_confidence_modifier = self.to_float(
            adaptive_confidence_summary.get("adaptive_confidence_modifier"),
            self.to_float(adaptive_confidence_summary.get("avg_confidence_modifier"), 0.0),
        )
        adaptive_confidence_score = self.to_float(
            adaptive_confidence_summary.get("adaptive_confidence"),
            self.to_float(adaptive_confidence_summary.get("avg_confidence"), 0.0),
        )
        family_rotation_score = self.to_float(
            family_rotation_summary.get("family_rotation_score"),
            self.to_float(family_rotation_summary.get("avg_family_rotation_score"), 0.0),
        )
        edge_durability_score = self.to_float(
            microstructure_summary.get("avg_edge_durability"),
            self.to_float(memory_bucket.get("best_edge_durability"), 0.0),
        )
        execution_survivability_score = self.to_float(
            microstructure_summary.get("avg_survivability"),
            self.to_float(memory_bucket.get("best_execution_survivability"), 0.0),
        )
        spread_stability = self.to_float(
            microstructure_summary.get("avg_spread_stability"),
            self.to_float(microstructure_summary.get("spread_stability_score"), 0.0),
        )
        quote_stability = self._clamp(1.0 - self.to_float(microstructure_summary.get("quote_churn_frequency"), 0.0))
        family_learning_score = self.to_float(family_learning_summary.get("family_learning_score"), 0.0)
        timing_payload = self._compute_entry_timing_fusion_score(
            phase55_status=phase55_status,
            entry_ready_reason=entry_ready_reason,
            pullback_rule_path=pullback_rule_path,
            crossover_detected=crossover_detected,
            micro_pullback_detected=micro_pullback_detected,
            predictive_regime_score=predictive_regime_score,
            adaptive_confidence_modifier=adaptive_confidence_modifier,
            adaptive_confidence_score=adaptive_confidence_score,
            family_rotation_score=family_rotation_score,
            queue_state=queue_state,
            queue_score=queue_score,
            edge_durability_score=edge_durability_score,
            execution_survivability_score=execution_survivability_score,
            spread_stability=spread_stability,
            quote_stability=quote_stability,
            blocker_reason=blocker_reason,
            family_learning_score=family_learning_score,
            microstructure_state=microstructure_summary.get("readiness_state"),
            market_type=family_learning_summary.get("market_type") or microstructure_summary.get("market_type"),
            memory_bucket=memory_bucket,
        )
        ticker_bucket["latest_timing_fusion_score"] = timing_payload["entry_timing_fusion_score"]
        ticker_bucket["latest_timing_fusion_state"] = self._classify_entry_timing_fusion_state(
            entry_timing_fusion_score=timing_payload["entry_timing_fusion_score"],
            phase55_ready=phase55_status == "entry_ready",
            crossover_detected=crossover_detected,
            micro_pullback_detected=micro_pullback_detected,
            predictive_support=timing_payload["predictive_support"],
            confidence_support=timing_payload["confidence_support"],
            queue_support=timing_payload["queue_support"],
            microstructure_support=timing_payload["microstructure_support"],
            spread_support=timing_payload["spread_support"],
            execution_survivability_support=timing_payload["execution_survivability_support"],
            blocker_reason=blocker_reason,
        )
        ticker_bucket["latest_phase55_status"] = phase55_status
        ticker_bucket["latest_blocker_reason"] = blocker_reason
        ticker_bucket["best_timing_fusion_score"] = max(self.to_float(ticker_bucket.get("best_timing_fusion_score"), 0.0) or 0.0, timing_payload["entry_timing_fusion_score"])
        ticker_bucket.setdefault("score_history", deque(maxlen=24)).append(timing_payload["entry_timing_fusion_score"])
        ticker_bucket.setdefault("state_history", deque(maxlen=24)).append(ticker_bucket["latest_timing_fusion_state"])
        if ticker_bucket["latest_timing_fusion_state"] == "timing_aligned":
            ticker_bucket["timing_aligned_count"] = int(ticker_bucket.get("timing_aligned_count", 0) or 0) + 1
        elif ticker_bucket["latest_timing_fusion_state"] == "improving":
            ticker_bucket["improving_timing_count"] = int(ticker_bucket.get("improving_timing_count", 0) or 0) + 1
        elif ticker_bucket["latest_timing_fusion_state"] == "too_early":
            ticker_bucket["too_early_count"] = int(ticker_bucket.get("too_early_count", 0) or 0) + 1
        elif ticker_bucket["latest_timing_fusion_state"] == "late_decay":
            ticker_bucket["late_decay_count"] = int(ticker_bucket.get("late_decay_count", 0) or 0) + 1
        elif ticker_bucket["latest_timing_fusion_state"] == "unsafe":
            ticker_bucket["unsafe_timing_count"] = int(ticker_bucket.get("unsafe_timing_count", 0) or 0) + 1
        ticker_bucket["last_summary"] = {
            "ticker": ticker,
            "family": family,
            "entry_timing_fusion_score": round(timing_payload["entry_timing_fusion_score"], 4),
            "entry_timing_fusion_state": ticker_bucket["latest_timing_fusion_state"],
            "phase55_status": phase55_status,
            "entry_ready_reason": entry_ready_reason or None,
            "pullback_rule_path": pullback_rule_path or None,
            "predictive_support": timing_payload["predictive_support"],
            "confidence_support": timing_payload["confidence_support"],
            "queue_support": timing_payload["queue_support"],
            "microstructure_support": timing_payload["microstructure_support"],
            "spread_support": timing_payload["spread_support"],
            "execution_survivability_support": timing_payload["execution_survivability_support"],
            "phase55_ready": phase55_status == "entry_ready",
            "crossover_detected": crossover_detected,
            "micro_pullback_detected": micro_pullback_detected,
            "latest_blocker_reason": blocker_reason,
            "timing_fusion_adjustment": round(timing_payload["timing_fusion_adjustment"], 4),
            "live_arb_enabled": bool(AION_LIVE_ARB_ENABLED),
        }
        family_bucket["first_seen_time"] = family_bucket.get("first_seen_time") or now
        family_bucket["last_seen_time"] = now
        family_bucket["family"] = family
        family_bucket["ticker"] = ticker
        family_bucket["latest_timing_fusion_score"] = max(self.to_float(family_bucket.get("latest_timing_fusion_score"), 0.0) or 0.0, timing_payload["entry_timing_fusion_score"])
        family_bucket["latest_timing_fusion_state"] = ticker_bucket["latest_timing_fusion_state"]
        family_bucket["latest_phase55_status"] = phase55_status
        family_bucket["latest_blocker_reason"] = blocker_reason
        family_bucket["observations"] = int(family_bucket.get("observations", 0) or 0) + 1
        family_bucket.setdefault("score_history", deque(maxlen=24)).append(timing_payload["entry_timing_fusion_score"])
        family_bucket.setdefault("state_history", deque(maxlen=24)).append(ticker_bucket["latest_timing_fusion_state"])
        family_bucket["timing_aligned_count"] = int(family_bucket.get("timing_aligned_count", 0) or 0) + (1 if ticker_bucket["latest_timing_fusion_state"] == "timing_aligned" else 0)
        family_bucket["improving_timing_count"] = int(family_bucket.get("improving_timing_count", 0) or 0) + (1 if ticker_bucket["latest_timing_fusion_state"] == "improving" else 0)
        family_bucket["too_early_count"] = int(family_bucket.get("too_early_count", 0) or 0) + (1 if ticker_bucket["latest_timing_fusion_state"] == "too_early" else 0)
        family_bucket["late_decay_count"] = int(family_bucket.get("late_decay_count", 0) or 0) + (1 if ticker_bucket["latest_timing_fusion_state"] == "late_decay" else 0)
        family_bucket["unsafe_timing_count"] = int(family_bucket.get("unsafe_timing_count", 0) or 0) + (1 if ticker_bucket["latest_timing_fusion_state"] == "unsafe" else 0)
        family_bucket["last_summary"] = self._build_entry_timing_fusion_family_summary(family=family)
        self.last_entry_timing_fusion_summary = dict(ticker_bucket["last_summary"])
        self.last_entry_timing_fusion_family_summary = dict(family_bucket.get("last_summary") or {})
        self.last_entry_timing_fusion_overall_summary = self._build_entry_timing_fusion_overall_summary()
        self._emit_entry_timing_fusion_telemetry(
            ticker_bucket=ticker_bucket,
            family_bucket=family_bucket,
            force=force or ticker_bucket["latest_timing_fusion_state"] in {"timing_aligned", "improving", "late_decay", "unsafe"},
        )
        return ticker_bucket["last_summary"], timing_payload

    def _get_tiny_canary_review_bucket(self, container_name, key):
        buckets = getattr(self, container_name, None)
        if not isinstance(buckets, dict):
            buckets = {}
            setattr(self, container_name, buckets)
        bucket = buckets.setdefault(
            key,
            {
                "first_seen_time": None,
                "last_seen_time": 0.0,
                "ticker": None,
                "family": None,
                "observations": 0,
                "review_candidate_count": 0,
                "canary_ready_count": 0,
                "unsafe_count": 0,
                "rejected_count": 0,
                "stable_review_cycles": 0,
                "unstable_review_cycles": 0,
                "review_decay_count": 0,
                "edge_consistency": 0.0,
                "spread_consistency": 0.0,
                "execution_consistency": 0.0,
                "timing_consistency": 0.0,
                "best_review_score": 0.0,
                "latest_review_score": 0.0,
                "latest_review_state": "rejected",
                "latest_blocker_reason": "unknown",
                "last_summary": {},
                "score_history": deque(maxlen=24),
                "state_history": deque(maxlen=24),
                "blocker_history": deque(maxlen=24),
            },
        )
        return bucket

    def _classify_tiny_canary_review_state(self, *, review_score=0.0, queue_state=None, timing_state=None, phase55_ready=False, blocker_reason=None, repeated_near_pass=False, unsafe_blocker=False):
        review_score = self._clamp(self.to_float(review_score, 0.0))
        queue_state = str(queue_state or "unknown").strip().lower()
        timing_state = str(timing_state or "unknown").strip().lower()
        blocker_reason = str(blocker_reason or "").strip().lower()
        unsafe_blocker = bool(unsafe_blocker or blocker_reason in {"unsafe_price", "low_volume", "missing_quotes", "edge_below_cost", "liquidity_failure", "duplicate_protection", "cooldown_protection", "phase55_failure"})
        if unsafe_blocker:
            return "unsafe"
        if review_score < 0.22 and queue_state in {"expired", "blocked"}:
            return "rejected"
        if review_score < 0.36 or timing_state in {"too_early", "late_decay"}:
            return "weak_watch"
        if review_score < 0.50 or queue_state in {"weak_watch", "improving_watch"}:
            return "improving_watch"
        if review_score < 0.62 and repeated_near_pass:
            return "near_candidate"
        if phase55_ready and review_score >= 0.62 and repeated_near_pass and queue_state in {"near_ready", "strong_watch"}:
            return "review_candidate"
        if phase55_ready and review_score >= 0.74 and queue_state == "strong_watch":
            return "canary_ready"
        return "review_candidate" if review_score >= 0.54 else "near_candidate"

    def _compute_tiny_canary_review_score(
        self,
        *,
        predictive_regime_score=0.0,
        entry_timing_fusion_score=0.0,
        edge_durability_score=0.0,
        execution_survivability_score=0.0,
        orderbook_quality=0.0,
        spread_stability=0.0,
        quote_stability=0.0,
        family_rotation_score=0.0,
        queue_state=None,
        confidence_modifier=0.0,
        edge_over_cost_quality=0.0,
        repeated_near_pass=0.0,
        learning_summary=None,
        microstructure_summary=None,
        family_learning_summary=None,
        review_bucket=None,
        timing_fusion_summary=None,
    ):
        learning_summary = learning_summary if isinstance(learning_summary, dict) else {}
        microstructure_summary = microstructure_summary if isinstance(microstructure_summary, dict) else {}
        family_learning_summary = family_learning_summary if isinstance(family_learning_summary, dict) else {}
        review_bucket = review_bucket if isinstance(review_bucket, dict) else {}
        timing_fusion_summary = timing_fusion_summary if isinstance(timing_fusion_summary, dict) else {}
        queue_state = str(queue_state or "unknown").strip().lower()
        predictive_regime_score = self._clamp(self.to_float(predictive_regime_score, 0.0))
        entry_timing_fusion_score = self._clamp(self.to_float(entry_timing_fusion_score, 0.0))
        edge_durability_score = self._clamp(self.to_float(edge_durability_score, 0.0))
        execution_survivability_score = self._clamp(self.to_float(execution_survivability_score, 0.0))
        orderbook_quality = self._clamp(self.to_float(orderbook_quality, 0.0))
        spread_stability = self._clamp(self.to_float(spread_stability, 0.0))
        quote_stability = self._clamp(self.to_float(quote_stability, 0.0))
        family_rotation_score = self._clamp(self.to_float(family_rotation_score, 0.0))
        confidence_modifier = self._clamp(self.to_float(confidence_modifier, 0.0))
        edge_over_cost_quality = self._clamp(self.to_float(edge_over_cost_quality, 0.0))
        repeated_near_pass = self._clamp(self.to_float(repeated_near_pass, 0.0))
        stable_review_cycles = self.to_float(review_bucket.get("stable_review_cycles"), 0.0)
        review_decay_count = self.to_float(review_bucket.get("review_decay_count"), 0.0)
        edge_consistency = self._clamp(self.to_float(review_bucket.get("edge_consistency"), 0.0))
        spread_consistency = self._clamp(self.to_float(review_bucket.get("spread_consistency"), 0.0))
        execution_consistency = self._clamp(self.to_float(review_bucket.get("execution_consistency"), 0.0))
        timing_consistency = self._clamp(self.to_float(review_bucket.get("timing_consistency"), 0.0))
        learning_score = self._clamp(self.to_float(family_learning_summary.get("family_learning_score"), self.to_float(learning_summary.get("learning_score"), 0.0)))
        microstructure_support = self._clamp(
            orderbook_quality * 0.28
            + edge_durability_score * 0.22
            + execution_survivability_score * 0.22
            + spread_stability * 0.14
            + quote_stability * 0.14
        )
        timing_support = self._clamp(
            entry_timing_fusion_score * 0.50
            + self._clamp(self.to_float(timing_fusion_summary.get("predictive_support"), 0.0)) * 0.10
            + self._clamp(self.to_float(timing_fusion_summary.get("confidence_support"), 0.0)) * 0.10
            + self._clamp(self.to_float(timing_fusion_summary.get("queue_support"), 0.0)) * 0.08
            + self._clamp(self.to_float(timing_fusion_summary.get("microstructure_support"), 0.0)) * 0.08
            + self._clamp(self.to_float(timing_fusion_summary.get("spread_support"), 0.0)) * 0.07
            + self._clamp(self.to_float(timing_fusion_summary.get("execution_survivability_support"), 0.0)) * 0.07
        )
        queue_support = {
            "strong_watch": 1.0,
            "near_ready": 0.82,
            "improving_watch": 0.62,
            "weak_watch": 0.32,
            "blocked": 0.10,
            "expired": 0.0,
        }.get(queue_state, 0.18)
        repeated_support = self._clamp(repeated_near_pass * 0.55 + min(1.0, stable_review_cycles / 4.0) * 0.45)
        base_score = (
            predictive_regime_score * 0.14
            + timing_support * 0.18
            + microstructure_support * 0.18
            + family_rotation_score * 0.10
            + queue_support * 0.08
            + confidence_modifier * 0.08
            + edge_over_cost_quality * 0.10
            + repeated_support * 0.12
            + learning_score * 0.02
            + edge_consistency * 0.02
            + spread_consistency * 0.02
            + execution_consistency * 0.02
            + timing_consistency * 0.02
        )
        blocker_penalty = min(0.38, (
            min(1.0, self.to_float(learning_summary.get("unsafe_price_count"), 0.0) / 4.0) * 0.12
            + min(1.0, self.to_float(learning_summary.get("missing_quotes_count"), 0.0) / 4.0) * 0.08
            + min(1.0, self.to_float(learning_summary.get("low_volume_count"), 0.0) / 4.0) * 0.08
            + min(1.0, self.to_float(learning_summary.get("edge_below_cost_count"), 0.0) / 4.0) * 0.08
            + min(1.0, review_decay_count / 5.0) * 0.04
        ))
        review_score = self._clamp(base_score - blocker_penalty + min(0.06, max(0.0, repeated_near_pass) * 0.06))
        return {
            "tiny_canary_review_score": round(review_score, 4),
            "predictive_support": round(predictive_regime_score, 4),
            "timing_support": round(timing_support, 4),
            "microstructure_support": round(microstructure_support, 4),
            "queue_state_support": queue_state,
            "queue_support": round(queue_support, 4),
            "confidence_modifier": round(confidence_modifier, 4),
            "edge_over_cost_quality": round(edge_over_cost_quality, 4),
            "repeated_near_pass": round(repeated_near_pass, 4),
            "blocker_penalty": round(blocker_penalty, 4),
            "stable_review_cycles": round(stable_review_cycles, 4),
            "review_decay_count": round(review_decay_count, 4),
            "edge_consistency": round(edge_consistency, 4),
            "spread_consistency": round(spread_consistency, 4),
            "execution_consistency": round(execution_consistency, 4),
            "timing_consistency": round(timing_consistency, 4),
        }

    def _build_tiny_canary_review_family_summary(self, family=None):
        family = str(family or "UNKNOWN").strip().upper() or "UNKNOWN"
        ticker_container = getattr(self, "tiny_canary_review_by_ticker", {}) or {}
        family_buckets = []
        if isinstance(ticker_container, dict):
            for bucket in ticker_container.values():
                if not isinstance(bucket, dict):
                    continue
                if str(bucket.get("family") or "").strip().upper() == family:
                    family_buckets.append(bucket)
        family_bucket = self._get_tiny_canary_review_bucket("tiny_canary_review_by_family", f"family:{family}")
        if not family_buckets:
            summary = {
                "family": family,
                "candidate_count": 0,
                "review_candidate_count": 0,
                "canary_ready_count": 0,
                "unsafe_count": 0,
                "rejected_count": 0,
                "best_review_ticker": None,
                "best_review_score": 0.0,
                "best_review_state": str(family_bucket.get("latest_review_state") or "rejected"),
                "latest_blocker_reason": str(family_bucket.get("latest_blocker_reason") or "unknown"),
                "live_arb_enabled": bool(AION_LIVE_ARB_ENABLED),
            }
            family_bucket["last_summary"] = summary
            return summary
        best_bucket = max(
            family_buckets,
            key=lambda bucket: (
                self.to_float(bucket.get("latest_review_score"), 0.0),
                self.to_float(bucket.get("best_review_score"), 0.0),
                int(bucket.get("review_candidate_count", 0) or 0),
            ),
        )
        summary = {
            "family": family,
            "candidate_count": int(len(family_buckets)),
            "review_candidate_count": int(sum(int(bucket.get("review_candidate_count", 0) or 0) for bucket in family_buckets)),
            "canary_ready_count": int(sum(int(bucket.get("canary_ready_count", 0) or 0) for bucket in family_buckets)),
            "unsafe_count": int(sum(int(bucket.get("unsafe_count", 0) or 0) for bucket in family_buckets)),
            "rejected_count": int(sum(int(bucket.get("rejected_count", 0) or 0) for bucket in family_buckets)),
            "best_review_ticker": str(best_bucket.get("ticker") or "").strip() or None,
            "best_review_score": round(self.to_float(best_bucket.get("latest_review_score"), 0.0) or 0.0, 4),
            "best_review_state": str(best_bucket.get("latest_review_state") or "rejected"),
            "latest_blocker_reason": str(best_bucket.get("latest_blocker_reason") or "unknown"),
            "live_arb_enabled": bool(AION_LIVE_ARB_ENABLED),
        }
        family_bucket["last_summary"] = summary
        return summary

    def _build_tiny_canary_review_overall_summary(self):
        ticker_container = getattr(self, "tiny_canary_review_by_ticker", {}) or {}
        family_container = getattr(self, "tiny_canary_review_by_family", {}) or {}
        ticker_buckets = [bucket for bucket in ticker_container.values() if isinstance(bucket, dict)]
        family_buckets = [bucket for bucket in family_container.values() if isinstance(bucket, dict)]
        if not ticker_buckets:
            return {
                "scope": "overall",
                "candidate_count": 0,
                "review_candidate_count": 0,
                "canary_ready_count": 0,
                "unsafe_count": 0,
                "rejected_count": 0,
                "best_review_ticker": None,
                "best_review_family": None,
                "best_review_state": "rejected",
                "best_review_score": 0.0,
                "latest_blocker_reason": "insufficient_data",
                "live_arb_enabled": bool(AION_LIVE_ARB_ENABLED),
            }
        best_bucket = max(
            ticker_buckets,
            key=lambda bucket: (
                self.to_float(bucket.get("latest_review_score"), 0.0),
                self.to_float(bucket.get("best_review_score"), 0.0),
                int(bucket.get("review_candidate_count", 0) or 0),
            ),
        )
        return {
            "scope": "overall",
            "candidate_count": int(len(ticker_buckets)),
            "family_count": int(len(family_buckets)),
            "review_candidate_count": int(sum(int(bucket.get("review_candidate_count", 0) or 0) for bucket in ticker_buckets)),
            "canary_ready_count": int(sum(int(bucket.get("canary_ready_count", 0) or 0) for bucket in ticker_buckets)),
            "unsafe_count": int(sum(int(bucket.get("unsafe_count", 0) or 0) for bucket in ticker_buckets)),
            "rejected_count": int(sum(int(bucket.get("rejected_count", 0) or 0) for bucket in ticker_buckets)),
            "best_review_ticker": str(best_bucket.get("ticker") or "").strip() or None,
            "best_review_family": str(best_bucket.get("family") or "").strip() or None,
            "best_review_state": str(best_bucket.get("latest_review_state") or "rejected"),
            "best_review_score": round(self.to_float(best_bucket.get("latest_review_score"), 0.0) or 0.0, 4),
            "latest_blocker_reason": str(best_bucket.get("latest_blocker_reason") or "unknown"),
            "live_arb_enabled": bool(AION_LIVE_ARB_ENABLED),
        }

    def _emit_tiny_canary_review_telemetry(self, *, ticker_bucket=None, family_bucket=None, force=False):
        ticker_bucket = ticker_bucket if isinstance(ticker_bucket, dict) else {}
        family_bucket = family_bucket if isinstance(family_bucket, dict) else {}
        ticker = str(ticker_bucket.get("ticker") or "").strip()
        family = str(ticker_bucket.get("family") or family_bucket.get("family") or "").strip().upper() or "UNKNOWN"
        now = time.time()
        summary = ticker_bucket.get("last_summary") if isinstance(ticker_bucket.get("last_summary"), dict) else {}
        if not summary:
            summary = {
                "ticker": ticker or "unknown",
                "family": family,
                "tiny_canary_review_score": round(self.to_float(ticker_bucket.get("latest_review_score"), 0.0) or 0.0, 4),
                "tiny_canary_review_state": str(ticker_bucket.get("latest_review_state") or "rejected"),
                "latest_blocker_reason": str(ticker_bucket.get("latest_blocker_reason") or "unknown"),
            }
        emit_key = ticker or family
        last_emit = float(getattr(self, "tiny_canary_review_last_signal_ts_by_key", {}).get(emit_key, 0.0) or 0.0)
        if not force and ticker and (now - last_emit) < 120.0:
            return None
        if ticker:
            self.tiny_canary_review_last_signal_ts_by_key[ticker] = now
        if family:
            self.tiny_canary_review_last_signal_ts_by_key[family] = now
        print("[LIVE-TINY-CANARY-REVIEW] " + json.dumps(summary, sort_keys=True, default=str))
        print("[LIVE-TINY-CANARY-STATE] " + json.dumps({
            "ticker": summary.get("ticker"),
            "family": summary.get("family"),
            "tiny_canary_review_state": summary.get("tiny_canary_review_state"),
            "tiny_canary_review_score": summary.get("tiny_canary_review_score"),
            "latest_blocker_reason": summary.get("latest_blocker_reason"),
        }, sort_keys=True, default=str))
        print("[LIVE-TINY-CANARY-BLOCKERS] " + json.dumps({
            "ticker": summary.get("ticker"),
            "family": summary.get("family"),
            "latest_blocker_reason": summary.get("latest_blocker_reason"),
            "unsafe_price_block": bool(summary.get("unsafe_price_block")),
            "low_volume_block": bool(summary.get("low_volume_block")),
            "missing_quotes_block": bool(summary.get("missing_quotes_block")),
            "edge_below_cost_block": bool(summary.get("edge_below_cost_block")),
            "liquidity_failure_block": bool(summary.get("liquidity_failure_block")),
            "duplicate_protection_block": bool(summary.get("duplicate_protection_block")),
            "cooldown_protection_block": bool(summary.get("cooldown_protection_block")),
            "phase55_failure_block": bool(summary.get("phase55_failure_block")),
        }, sort_keys=True, default=str))
        print("[LIVE-TINY-CANARY-EVIDENCE] " + json.dumps({
            "ticker": summary.get("ticker"),
            "family": summary.get("family"),
            "stable_review_cycles": summary.get("stable_review_cycles"),
            "unstable_review_cycles": summary.get("unstable_review_cycles"),
            "review_decay_count": summary.get("review_decay_count"),
            "edge_consistency": summary.get("edge_consistency"),
            "spread_consistency": summary.get("spread_consistency"),
            "execution_consistency": summary.get("execution_consistency"),
            "timing_consistency": summary.get("timing_consistency"),
        }, sort_keys=True, default=str))
        self.last_tiny_canary_review_summary = dict(summary)
        self.last_tiny_canary_review_family_summary = dict(family_bucket.get("last_summary") or {})
        self.last_tiny_canary_review_overall_summary = self._build_tiny_canary_review_overall_summary()
        print("[LIVE-TINY-CANARY-DASHBOARD] " + json.dumps(self.last_tiny_canary_review_overall_summary, sort_keys=True, default=str))
        return summary

    def _update_tiny_canary_review(self, *, ticker=None, family=None, market=None, q=None, predictive_regime_summary=None, entry_timing_fusion_summary=None, family_rotation_summary=None, queue_summary=None, adaptive_confidence_summary=None, microstructure_summary=None, learning_summary=None, family_learning_summary=None, safe_queue_summary=None, memory_bucket=None, entry_timing_observation=None, force=False):
        ticker = str(ticker or getattr(q, "ticker", "") or "").strip()
        if not ticker:
            return None
        family = str(family or getattr(q, "family", "") or "").strip().upper() or "UNKNOWN"
        predictive_regime_summary = predictive_regime_summary if isinstance(predictive_regime_summary, dict) else {}
        entry_timing_fusion_summary = entry_timing_fusion_summary if isinstance(entry_timing_fusion_summary, dict) else {}
        family_rotation_summary = family_rotation_summary if isinstance(family_rotation_summary, dict) else {}
        queue_summary = queue_summary if isinstance(queue_summary, dict) else {}
        adaptive_confidence_summary = adaptive_confidence_summary if isinstance(adaptive_confidence_summary, dict) else {}
        microstructure_summary = microstructure_summary if isinstance(microstructure_summary, dict) else {}
        learning_summary = learning_summary if isinstance(learning_summary, dict) else {}
        family_learning_summary = family_learning_summary if isinstance(family_learning_summary, dict) else {}
        safe_queue_summary = safe_queue_summary if isinstance(safe_queue_summary, dict) else {}
        memory_bucket = memory_bucket if isinstance(memory_bucket, dict) else {}
        entry_timing_observation = entry_timing_observation if isinstance(entry_timing_observation, dict) else {}
        ticker_bucket = self._get_tiny_canary_review_bucket("tiny_canary_review_by_ticker", f"ticker:{ticker}")
        family_bucket = self._get_tiny_canary_review_bucket("tiny_canary_review_by_family", f"family:{family}")
        now = time.time()
        ticker_bucket["first_seen_time"] = ticker_bucket.get("first_seen_time") or now
        ticker_bucket["last_seen_time"] = now
        ticker_bucket["ticker"] = ticker
        ticker_bucket["family"] = family
        ticker_bucket["observations"] = int(ticker_bucket.get("observations", 0) or 0) + 1
        blocker_reason = str(
            entry_timing_observation.get("reject_reason")
            or entry_timing_observation.get("block_reason")
            or queue_summary.get("top_queue_blocker")
            or queue_summary.get("latest_blocker")
            or learning_summary.get("candidate_learning_top_reason")
            or "unknown"
        ).strip().lower()
        unsafe_blocker = blocker_reason in {"unsafe_price", "low_volume", "missing_quotes", "edge_below_cost", "liquidity_failure", "duplicate_protection", "cooldown_protection", "phase55_failure", "immediate_reject", "probability_block", "capital_block", "psychology_block"}
        phase55_status = str(entry_timing_observation.get("phase55_status") or "unknown").strip().lower()
        phase55_ready = phase55_status == "entry_ready"
        queue_state = str(queue_summary.get("top_queue_state") or queue_summary.get("queue_state") or "unknown").strip().lower()
        repeated_near_pass = self.to_float(queue_summary.get("near_pass_count"), self.to_float(safe_queue_summary.get("near_pass_count"), 0.0))
        review_payload = self._compute_tiny_canary_review_score(
            predictive_regime_score=self.to_float(
                predictive_regime_summary.get("predictive_regime_score"),
                self.to_float(predictive_regime_summary.get("top_predictive_score"), 0.0),
            ),
            entry_timing_fusion_score=self.to_float(entry_timing_fusion_summary.get("entry_timing_fusion_score"), 0.0),
            edge_durability_score=self.to_float(microstructure_summary.get("avg_edge_durability"), self.to_float(memory_bucket.get("best_edge_durability"), 0.0)),
            execution_survivability_score=self.to_float(microstructure_summary.get("avg_survivability"), self.to_float(memory_bucket.get("best_execution_survivability"), 0.0)),
            orderbook_quality=self.to_float(microstructure_summary.get("liquidity_reliability"), self.to_float(microstructure_summary.get("market_maker_behavior_score"), 0.0)),
            spread_stability=self.to_float(microstructure_summary.get("avg_spread_stability"), self.to_float(microstructure_summary.get("spread_stability_score"), 0.0)),
            quote_stability=self._clamp(1.0 - self.to_float(microstructure_summary.get("quote_churn_frequency"), 0.0)),
            family_rotation_score=self.to_float(family_rotation_summary.get("family_rotation_score"), 0.0),
            queue_state=queue_state,
            confidence_modifier=self.to_float(adaptive_confidence_summary.get("adaptive_confidence_modifier"), self.to_float(adaptive_confidence_summary.get("avg_confidence_modifier"), 0.0)),
            edge_over_cost_quality=self._clamp(
                max(
                    0.0,
                    self.to_float(memory_bucket.get("adaptive_priority_score"), 0.0)
                    + self.to_float(entry_timing_fusion_summary.get("timing_fusion_adjustment"), 0.0)
                )
            ),
            repeated_near_pass=repeated_near_pass,
            learning_summary=learning_summary,
            microstructure_summary=microstructure_summary,
            family_learning_summary=family_learning_summary,
            review_bucket=ticker_bucket,
            timing_fusion_summary=entry_timing_fusion_summary,
        )
        review_score = review_payload["tiny_canary_review_score"]
        review_state = self._classify_tiny_canary_review_state(
            review_score=review_score,
            queue_state=queue_state,
            timing_state=str(entry_timing_fusion_summary.get("entry_timing_fusion_state") or "unknown"),
            phase55_ready=phase55_ready,
            blocker_reason=blocker_reason,
            repeated_near_pass=repeated_near_pass >= 2,
            unsafe_blocker=unsafe_blocker,
        )
        ticker_bucket["latest_review_score"] = review_score
        ticker_bucket["latest_review_state"] = review_state
        ticker_bucket["latest_blocker_reason"] = blocker_reason
        ticker_bucket["best_review_score"] = max(self.to_float(ticker_bucket.get("best_review_score"), 0.0) or 0.0, review_score)
        ticker_bucket["review_candidate_count"] = int(ticker_bucket.get("review_candidate_count", 0) or 0) + (1 if review_state in {"review_candidate", "canary_ready"} else 0)
        ticker_bucket["canary_ready_count"] = int(ticker_bucket.get("canary_ready_count", 0) or 0) + (1 if review_state == "canary_ready" else 0)
        ticker_bucket["unsafe_count"] = int(ticker_bucket.get("unsafe_count", 0) or 0) + (1 if review_state == "unsafe" else 0)
        ticker_bucket["rejected_count"] = int(ticker_bucket.get("rejected_count", 0) or 0) + (1 if review_state == "rejected" else 0)
        if review_state in {"review_candidate", "canary_ready"}:
            ticker_bucket["stable_review_cycles"] = int(ticker_bucket.get("stable_review_cycles", 0) or 0) + 1
        else:
            ticker_bucket["unstable_review_cycles"] = int(ticker_bucket.get("unstable_review_cycles", 0) or 0) + 1
        if review_state in {"rejected", "unsafe"}:
            ticker_bucket["review_decay_count"] = int(ticker_bucket.get("review_decay_count", 0) or 0) + 1
        edge_consistency = self._clamp(
            (self.to_float(microstructure_summary.get("edge_durability_score"), 0.0) * 0.5)
            + (self.to_float(entry_timing_fusion_summary.get("execution_survivability_support"), 0.0) * 0.25)
            + (self.to_float(review_payload.get("edge_over_cost_quality"), 0.0) * 0.25)
        )
        spread_consistency = self._clamp(
            self.to_float(microstructure_summary.get("spread_stability_score"), 0.0) * 0.6
            + self.to_float(review_payload.get("spread_stability"), 0.0) * 0.4
        )
        execution_consistency = self._clamp(
            self.to_float(microstructure_summary.get("execution_survivability_score"), 0.0) * 0.6
            + self.to_float(entry_timing_fusion_summary.get("execution_survivability_support"), 0.0) * 0.4
        )
        timing_consistency = self._clamp(
            self.to_float(entry_timing_fusion_summary.get("entry_timing_fusion_score"), 0.0) * 0.65
            + self.to_float(entry_timing_fusion_summary.get("phase55_ready_support"), 0.0) * 0.35
        )
        ticker_bucket["edge_consistency"] = round(edge_consistency, 4)
        ticker_bucket["spread_consistency"] = round(spread_consistency, 4)
        ticker_bucket["execution_consistency"] = round(execution_consistency, 4)
        ticker_bucket["timing_consistency"] = round(timing_consistency, 4)
        ticker_bucket.setdefault("score_history", deque(maxlen=24)).append(review_score)
        ticker_bucket.setdefault("state_history", deque(maxlen=24)).append(review_state)
        ticker_bucket.setdefault("blocker_history", deque(maxlen=24)).append(blocker_reason)
        ticker_bucket["last_summary"] = {
            "ticker": ticker,
            "family": family,
            "tiny_canary_review_score": round(review_score, 4),
            "tiny_canary_review_state": review_state,
            "latest_blocker_reason": blocker_reason,
            "stable_review_cycles": int(ticker_bucket.get("stable_review_cycles", 0) or 0),
            "unstable_review_cycles": int(ticker_bucket.get("unstable_review_cycles", 0) or 0),
            "review_decay_count": int(ticker_bucket.get("review_decay_count", 0) or 0),
            "edge_consistency": round(ticker_bucket["edge_consistency"], 4),
            "spread_consistency": round(ticker_bucket["spread_consistency"], 4),
            "execution_consistency": round(ticker_bucket["execution_consistency"], 4),
            "timing_consistency": round(ticker_bucket["timing_consistency"], 4),
            "review_candidate_count": int(ticker_bucket.get("review_candidate_count", 0) or 0),
            "canary_ready_count": int(ticker_bucket.get("canary_ready_count", 0) or 0),
            "unsafe_count": int(ticker_bucket.get("unsafe_count", 0) or 0),
            "rejected_count": int(ticker_bucket.get("rejected_count", 0) or 0),
            "live_arb_enabled": bool(AION_LIVE_ARB_ENABLED),
            "unsafe_price_block": bool(unsafe_blocker and blocker_reason == "unsafe_price"),
            "low_volume_block": bool(unsafe_blocker and blocker_reason == "low_volume"),
            "missing_quotes_block": bool(unsafe_blocker and blocker_reason == "missing_quotes"),
            "edge_below_cost_block": bool(unsafe_blocker and blocker_reason == "edge_below_cost"),
            "liquidity_failure_block": bool(unsafe_blocker and blocker_reason == "liquidity_failure"),
            "duplicate_protection_block": bool(unsafe_blocker and blocker_reason == "duplicate_protection"),
            "cooldown_protection_block": bool(unsafe_blocker and blocker_reason == "cooldown_protection"),
            "phase55_failure_block": bool(unsafe_blocker and blocker_reason == "phase55_failure"),
        }
        family_bucket["first_seen_time"] = family_bucket.get("first_seen_time") or now
        family_bucket["last_seen_time"] = now
        family_bucket["family"] = family
        family_bucket["ticker"] = ticker
        family_bucket["latest_review_score"] = max(self.to_float(family_bucket.get("latest_review_score"), 0.0) or 0.0, review_score)
        family_bucket["latest_review_state"] = review_state
        family_bucket["latest_blocker_reason"] = blocker_reason
        family_bucket["observations"] = int(family_bucket.get("observations", 0) or 0) + 1
        family_bucket["review_candidate_count"] = int(family_bucket.get("review_candidate_count", 0) or 0) + (1 if review_state in {"review_candidate", "canary_ready"} else 0)
        family_bucket["canary_ready_count"] = int(family_bucket.get("canary_ready_count", 0) or 0) + (1 if review_state == "canary_ready" else 0)
        family_bucket["unsafe_count"] = int(family_bucket.get("unsafe_count", 0) or 0) + (1 if review_state == "unsafe" else 0)
        family_bucket["rejected_count"] = int(family_bucket.get("rejected_count", 0) or 0) + (1 if review_state == "rejected" else 0)
        family_bucket["stable_review_cycles"] = int(family_bucket.get("stable_review_cycles", 0) or 0) + (1 if review_state in {"review_candidate", "canary_ready"} else 0)
        family_bucket["unstable_review_cycles"] = int(family_bucket.get("unstable_review_cycles", 0) or 0) + (1 if review_state not in {"review_candidate", "canary_ready"} else 0)
        family_bucket["review_decay_count"] = int(family_bucket.get("review_decay_count", 0) or 0) + (1 if review_state in {"rejected", "unsafe"} else 0)
        family_bucket["edge_consistency"] = round(edge_consistency, 4)
        family_bucket["spread_consistency"] = round(spread_consistency, 4)
        family_bucket["execution_consistency"] = round(execution_consistency, 4)
        family_bucket["timing_consistency"] = round(timing_consistency, 4)
        family_bucket["last_summary"] = self._build_tiny_canary_review_family_summary(family=family)
        self.last_tiny_canary_review_summary = dict(ticker_bucket["last_summary"])
        self.last_tiny_canary_review_family_summary = dict(family_bucket.get("last_summary") or {})
        self.last_tiny_canary_review_overall_summary = self._build_tiny_canary_review_overall_summary()
        self._emit_tiny_canary_review_telemetry(
            ticker_bucket=ticker_bucket,
            family_bucket=family_bucket,
            force=force or review_state in {"review_candidate", "canary_ready", "unsafe", "rejected"},
        )
        return ticker_bucket["last_summary"], review_payload

    def _get_canary_audit_bucket(self, container_name, key):
        buckets = getattr(self, container_name, None)
        if not isinstance(buckets, dict):
            buckets = {}
            setattr(self, container_name, buckets)
        bucket = buckets.setdefault(
            key,
            {
                "first_seen_time": None,
                "last_seen_time": 0.0,
                "ticker": None,
                "family": None,
                "candidate_count": 0,
                "stable_canary_count": 0,
                "failed_canary_count": 0,
                "decayed_edge_count": 0,
                "survival_rate": 0.0,
                "average_post_cost_edge": 0.0,
                "average_edge_decay_velocity": 0.0,
                "average_survival_probability": 0.0,
                "stable_cycles": 0,
                "failed_cycles": 0,
                "decay_warning_count": 0,
                "unstable_quote_count": 0,
                "latest_canary_audit_state": "failed",
                "latest_blocker_reason": "unknown",
                "best_canary_score": 0.0,
                "best_survival_probability": 0.0,
                "best_post_cost_edge": 0.0,
                "last_summary": {},
                "score_history": deque(maxlen=24),
                "state_history": deque(maxlen=24),
                "blocker_history": deque(maxlen=24),
            },
        )
        return bucket

    def _classify_canary_audit_state(self, *, canary_readiness_score=0.0, blocker_reason=None, would_survive_after_fees=False, would_survive_after_spread=False, would_survive_after_slippage=False, would_survive_after_decay=False, repeated_near_pass=False):
        score = self._clamp(self.to_float(canary_readiness_score, 0.0))
        blocker_reason = str(blocker_reason or "").strip().lower()
        if blocker_reason in {"unsafe_price", "low_volume", "missing_quotes", "edge_below_cost", "liquidity_failure", "duplicate_protection", "cooldown_protection", "phase55_failure"}:
            return "failed"
        if not would_survive_after_fees or not would_survive_after_spread or not would_survive_after_slippage or not would_survive_after_decay:
            return "failed"
        if score < 0.22:
            return "rejected"
        if score < 0.36:
            return "weak_watch"
        if score < 0.50 or not repeated_near_pass:
            return "improving_watch"
        if score < 0.62:
            return "near_candidate"
        if score < 0.74:
            return "review_candidate"
        return "canary_ready"

    def _compute_canary_audit_score(
        self,
        *,
        predictive_regime_score=0.0,
        entry_timing_fusion_score=0.0,
        edge_durability_score=0.0,
        execution_survivability_score=0.0,
        orderbook_quality=0.0,
        spread_stability=0.0,
        quote_stability=0.0,
        family_rotation_score=0.0,
        queue_state=None,
        confidence_modifier=0.0,
        edge_over_cost_quality=0.0,
        repeated_near_pass=0.0,
        canary_memory=None,
        microstructure_summary=None,
        tiny_canary_review_summary=None,
        entry_timing_observation=None,
        market=None,
        q=None,
    ):
        canary_memory = canary_memory if isinstance(canary_memory, dict) else {}
        microstructure_summary = microstructure_summary if isinstance(microstructure_summary, dict) else {}
        tiny_canary_review_summary = tiny_canary_review_summary if isinstance(tiny_canary_review_summary, dict) else {}
        entry_timing_observation = entry_timing_observation if isinstance(entry_timing_observation, dict) else {}
        market = market if isinstance(market, dict) else {}
        queue_state = str(queue_state or "unknown").strip().lower()
        predictive_regime_score = self._clamp(self.to_float(predictive_regime_score, 0.0))
        entry_timing_fusion_score = self._clamp(self.to_float(entry_timing_fusion_score, 0.0))
        edge_durability_score = self._clamp(self.to_float(edge_durability_score, 0.0))
        execution_survivability_score = self._clamp(self.to_float(execution_survivability_score, 0.0))
        orderbook_quality = self._clamp(self.to_float(orderbook_quality, 0.0))
        spread_stability = self._clamp(self.to_float(spread_stability, 0.0))
        quote_stability = self._clamp(self.to_float(quote_stability, 0.0))
        family_rotation_score = self._clamp(self.to_float(family_rotation_score, 0.0))
        confidence_modifier = self._clamp(self.to_float(confidence_modifier, 0.0))
        edge_over_cost_quality = self._clamp(self.to_float(edge_over_cost_quality, 0.0))
        repeated_near_pass = self._clamp(self.to_float(repeated_near_pass, 0.0))
        stable_canary_count = int(canary_memory.get("stable_canary_count", 0) or 0)
        failed_canary_count = int(canary_memory.get("failed_canary_count", 0) or 0)
        decayed_edge_count = int(canary_memory.get("decayed_edge_count", 0) or 0)
        survival_rate = self._clamp(self.to_float(canary_memory.get("survival_rate"), 0.0))
        average_post_cost_edge = self.to_float(canary_memory.get("average_post_cost_edge"), 0.0)
        average_edge_decay_velocity = self.to_float(canary_memory.get("average_edge_decay_velocity"), 0.0)
        stable_edge_persistence = self._clamp(
            edge_durability_score * 0.32
            + execution_survivability_score * 0.28
            + spread_stability * 0.14
            + quote_stability * 0.10
            + survival_rate * 0.16
        )
        fill_quality = self._clamp(
            min(1.0, self.to_float(entry_timing_observation.get("history_points"), 0.0) / max(self._phase55_required_history_points(), 1))
            * 0.20
            + microstructure_summary.get("liquidity_reliability_score", 0.0) * 0.20
            + execution_survivability_score * 0.25
            + spread_stability * 0.15
            + quote_stability * 0.10
            + orderbook_quality * 0.10
        )
        post_cost_edge = self._clamp(
            max(
                0.0,
                self.to_float(entry_timing_observation.get("probability_edge"), 0.0) * 0.35
                + predictive_regime_score * 0.15
                + family_rotation_score * 0.10
                + confidence_modifier * 0.10
                + edge_over_cost_quality * 0.20
                + survival_rate * 0.10,
            )
        )
        spread_decay_risk = self._clamp(
            max(
                0.0,
                (1.0 - spread_stability) * 0.35
                + (1.0 - quote_stability) * 0.25
                + min(1.0, average_edge_decay_velocity * 5.0) * 0.20
                + min(1.0, decayed_edge_count / max(canary_memory.get("candidate_count", 1) or 1, 1)) * 0.20,
            )
        )
        edge_survival_probability = self._clamp(
            stable_edge_persistence * 0.34
            + fill_quality * 0.20
            + post_cost_edge * 0.20
            + survival_rate * 0.18
            + (1.0 - spread_decay_risk) * 0.08
        )
        decay_velocity = self._clamp(min(1.0, average_edge_decay_velocity * 4.0))
        canary_readiness_score = self._clamp(
            predictive_regime_score * 0.14
            + entry_timing_fusion_score * 0.18
            + stable_edge_persistence * 0.18
            + execution_survivability_score * 0.14
            + orderbook_quality * 0.10
            + spread_stability * 0.10
            + quote_stability * 0.08
            + family_rotation_score * 0.08
            + confidence_modifier * 0.04
            + edge_over_cost_quality * 0.04
            + repeated_near_pass * 0.02
            + edge_survival_probability * 0.18
            - spread_decay_risk * 0.14
            - decay_velocity * 0.10
        )
        would_survive_after_fees = bool(post_cost_edge > 0.0 and canary_readiness_score >= 0.25)
        would_survive_after_spread = bool(spread_stability >= 0.30 and spread_decay_risk < 0.75)
        would_survive_after_slippage = bool(fill_quality >= 0.32 and edge_survival_probability >= 0.30)
        would_survive_after_decay = bool(edge_survival_probability >= 0.34 and decay_velocity < 0.70)
        if any(
            bool(entry_timing_observation.get(flag))
            for flag in ("spread_widening_too_fast", "quote_missing", "orderbook_collapsed", "edge_flipped_negative", "volatility_spike")
        ):
            canary_readiness_score = min(canary_readiness_score, 0.15)
            spread_decay_risk = max(spread_decay_risk, 0.75)
            edge_survival_probability = min(edge_survival_probability, 0.25)
            would_survive_after_fees = False
            would_survive_after_spread = False
            would_survive_after_slippage = False
            would_survive_after_decay = False
        canary_readiness_score = self._clamp(canary_readiness_score)
        return {
            "canary_readiness_score": round(canary_readiness_score, 4),
            "predicted_entry_price": round(self.to_float(getattr(q, "yes_ask", None), self.to_float(market.get("yes_ask"), 0.0)), 4),
            "predicted_exit_price": round(self.to_float(getattr(q, "yes_bid", None), self.to_float(market.get("yes_bid"), self.to_float(getattr(q, "last_price", None), 0.0))), 4),
            "expected_fill_quality": round(fill_quality, 4),
            "spread_decay_risk": round(spread_decay_risk, 4),
            "quote_stability": round(quote_stability, 4),
            "edge_survival_probability": round(edge_survival_probability, 4),
            "hypothetical_post_cost_edge": round(post_cost_edge, 4),
            "would_survive_after_fees": bool(would_survive_after_fees),
            "would_survive_after_spread": bool(would_survive_after_spread),
            "would_survive_after_slippage": bool(would_survive_after_slippage),
            "would_survive_after_decay": bool(would_survive_after_decay),
            "stable_edge_persistence": round(stable_edge_persistence, 4),
            "decay_velocity": round(decay_velocity, 4),
            "average_post_cost_edge": round(average_post_cost_edge, 4),
            "average_edge_decay_velocity": round(average_edge_decay_velocity, 4),
            "stable_canary_count": stable_canary_count,
            "failed_canary_count": failed_canary_count,
            "decayed_edge_count": decayed_edge_count,
        }

    def _build_canary_audit_family_summary(self, family=None):
        family = str(family or "UNKNOWN").strip().upper() or "UNKNOWN"
        ticker_container = getattr(self, "canary_audit_by_ticker", {}) or {}
        family_buckets = []
        if isinstance(ticker_container, dict):
            for bucket in ticker_container.values():
                if not isinstance(bucket, dict):
                    continue
                if str(bucket.get("family") or "").strip().upper() == family:
                    family_buckets.append(bucket)
        family_bucket = self._get_canary_audit_bucket("canary_audit_by_family", f"family:{family}")
        if not family_buckets:
            summary = {
                "family": family,
                "candidate_count": 0,
                "stable_canary_count": 0,
                "failed_canary_count": 0,
                "average_survival_rate": 0.0,
                "strongest_canary_ticker": None,
                "strongest_canary_score": 0.0,
                "strongest_post_cost_edge": 0.0,
                "strongest_survival_probability": 0.0,
                "best_canary_state": str(family_bucket.get("latest_canary_audit_state") or "failed"),
                "live_arb_enabled": bool(AION_LIVE_ARB_ENABLED),
            }
            family_bucket["last_summary"] = summary
            return summary
        best_bucket = max(
            family_buckets,
            key=lambda bucket: (
                self.to_float(bucket.get("latest_canary_audit_score"), 0.0),
                self.to_float(bucket.get("best_canary_score"), 0.0),
                self.to_float(bucket.get("best_survival_probability"), 0.0),
            ),
        )
        summary = {
            "family": family,
            "candidate_count": int(len(family_buckets)),
            "stable_canary_count": int(sum(int(bucket.get("stable_canary_count", 0) or 0) for bucket in family_buckets)),
            "failed_canary_count": int(sum(int(bucket.get("failed_canary_count", 0) or 0) for bucket in family_buckets)),
            "average_survival_rate": round(sum(self.to_float(bucket.get("survival_rate"), 0.0) for bucket in family_buckets) / max(len(family_buckets), 1), 4),
            "strongest_canary_ticker": str(best_bucket.get("ticker") or "").strip() or None,
            "strongest_canary_score": round(self.to_float(best_bucket.get("latest_canary_audit_score"), 0.0) or 0.0, 4),
            "strongest_post_cost_edge": round(self.to_float(best_bucket.get("best_post_cost_edge"), 0.0) or 0.0, 4),
            "strongest_survival_probability": round(self.to_float(best_bucket.get("best_survival_probability"), 0.0) or 0.0, 4),
            "best_canary_state": str(best_bucket.get("latest_canary_audit_state") or "failed"),
            "live_arb_enabled": bool(AION_LIVE_ARB_ENABLED),
        }
        family_bucket["last_summary"] = summary
        return summary

    def _build_canary_audit_overall_summary(self):
        ticker_container = getattr(self, "canary_audit_by_ticker", {}) or {}
        family_container = getattr(self, "canary_audit_by_family", {}) or {}
        ticker_buckets = [bucket for bucket in ticker_container.values() if isinstance(bucket, dict)]
        family_buckets = [bucket for bucket in family_container.values() if isinstance(bucket, dict)]
        if not ticker_buckets:
            return {
                "scope": "overall",
                "candidate_count": 0,
                "stable_canary_count": 0,
                "failed_canary_count": 0,
                "average_survival_rate": 0.0,
                "strongest_canary_family": None,
                "strongest_canary_ticker": None,
                "strongest_canary_score": 0.0,
                "strongest_post_cost_edge": 0.0,
                "strongest_survival_probability": 0.0,
                "best_canary_state": "failed",
                "decay_warning_count": 0,
                "unstable_quote_count": 0,
                "live_arb_enabled": bool(AION_LIVE_ARB_ENABLED),
            }
        best_bucket = max(
            ticker_buckets,
            key=lambda bucket: (
                self.to_float(bucket.get("latest_canary_audit_score"), 0.0),
                self.to_float(bucket.get("best_canary_score"), 0.0),
                self.to_float(bucket.get("best_survival_probability"), 0.0),
            ),
        )
        return {
            "scope": "overall",
            "candidate_count": int(len(ticker_buckets)),
            "family_count": int(len(family_buckets)),
            "stable_canary_count": int(sum(int(bucket.get("stable_canary_count", 0) or 0) for bucket in ticker_buckets)),
            "failed_canary_count": int(sum(int(bucket.get("failed_canary_count", 0) or 0) for bucket in ticker_buckets)),
            "average_survival_rate": round(sum(self.to_float(bucket.get("survival_rate"), 0.0) for bucket in ticker_buckets) / max(len(ticker_buckets), 1), 4),
            "strongest_canary_family": str(best_bucket.get("family") or "").strip() or None,
            "strongest_canary_ticker": str(best_bucket.get("ticker") or "").strip() or None,
            "strongest_canary_score": round(self.to_float(best_bucket.get("latest_canary_audit_score"), 0.0) or 0.0, 4),
            "strongest_post_cost_edge": round(self.to_float(best_bucket.get("best_post_cost_edge"), 0.0) or 0.0, 4),
            "strongest_survival_probability": round(self.to_float(best_bucket.get("best_survival_probability"), 0.0) or 0.0, 4),
            "best_canary_state": str(best_bucket.get("latest_canary_audit_state") or "failed"),
            "decay_warning_count": int(sum(int(bucket.get("decay_warning_count", 0) or 0) for bucket in ticker_buckets)),
            "unstable_quote_count": int(sum(int(bucket.get("unstable_quote_count", 0) or 0) for bucket in ticker_buckets)),
            "live_arb_enabled": bool(AION_LIVE_ARB_ENABLED),
        }

    def _emit_canary_audit_telemetry(self, *, ticker_bucket=None, family_bucket=None, force=False):
        ticker_bucket = ticker_bucket if isinstance(ticker_bucket, dict) else {}
        family_bucket = family_bucket if isinstance(family_bucket, dict) else {}
        ticker = str(ticker_bucket.get("ticker") or "").strip()
        family = str(ticker_bucket.get("family") or family_bucket.get("family") or "").strip().upper() or "UNKNOWN"
        now = time.time()
        summary = ticker_bucket.get("last_summary") if isinstance(ticker_bucket.get("last_summary"), dict) else {}
        if not summary:
            summary = {
                "ticker": ticker or "unknown",
                "family": family,
                "canary_readiness_score": round(self.to_float(ticker_bucket.get("latest_canary_audit_score"), 0.0) or 0.0, 4),
                "canary_state": str(ticker_bucket.get("latest_canary_audit_state") or "failed"),
                "hypothetical_post_cost_edge": round(self.to_float(ticker_bucket.get("best_post_cost_edge"), 0.0) or 0.0, 4),
                "edge_survival_probability": round(self.to_float(ticker_bucket.get("best_survival_probability"), 0.0) or 0.0, 4),
                "latest_blocker_reason": str(ticker_bucket.get("latest_blocker_reason") or "unknown"),
            }
        emit_key = ticker or family
        last_emit = float(getattr(self, "canary_audit_last_signal_ts_by_key", {}).get(emit_key, 0.0) or 0.0)
        if not force and ticker and (now - last_emit) < 120.0:
            return None
        if ticker:
            self.canary_audit_last_signal_ts_by_key[ticker] = now
        if family:
            self.canary_audit_last_signal_ts_by_key[family] = now
        print("[LIVE-CANARY-AUDIT] " + json.dumps(summary, sort_keys=True, default=str))
        print("[LIVE-CANARY-STABILITY] " + json.dumps({
            "ticker": summary.get("ticker"),
            "family": summary.get("family"),
            "would_survive_after_fees": summary.get("would_survive_after_fees"),
            "would_survive_after_spread": summary.get("would_survive_after_spread"),
            "would_survive_after_slippage": summary.get("would_survive_after_slippage"),
            "would_survive_after_decay": summary.get("would_survive_after_decay"),
            "expected_fill_quality": summary.get("expected_fill_quality"),
        }, sort_keys=True, default=str))
        print("[LIVE-CANARY-DECAY] " + json.dumps({
            "ticker": summary.get("ticker"),
            "family": summary.get("family"),
            "spread_decay_risk": summary.get("spread_decay_risk"),
            "decay_velocity": summary.get("decay_velocity"),
            "average_edge_decay_velocity": summary.get("average_edge_decay_velocity"),
            "decay_warning_count": summary.get("decay_warning_count"),
            "unstable_quote_count": summary.get("unstable_quote_count"),
        }, sort_keys=True, default=str))
        print("[LIVE-CANARY-SURVIVAL] " + json.dumps({
            "ticker": summary.get("ticker"),
            "family": summary.get("family"),
            "edge_survival_probability": summary.get("edge_survival_probability"),
            "stable_canary_count": summary.get("stable_canary_count"),
            "failed_canary_count": summary.get("failed_canary_count"),
            "average_post_cost_edge": summary.get("average_post_cost_edge"),
        }, sort_keys=True, default=str))
        self.last_canary_audit_summary = dict(summary)
        self.last_canary_audit_family_summary = dict(family_bucket.get("last_summary") or {})
        self.last_canary_audit_overall_summary = self._build_canary_audit_overall_summary()
        print("[LIVE-CANARY-DASHBOARD] " + json.dumps(self.last_canary_audit_overall_summary, sort_keys=True, default=str))
        return summary

    def _update_canary_audit(self, *, ticker=None, family=None, market=None, q=None, predictive_regime_summary=None, entry_timing_fusion_summary=None, tiny_canary_review_summary=None, queue_summary=None, family_rotation_summary=None, adaptive_confidence_summary=None, microstructure_summary=None, learning_summary=None, family_learning_summary=None, entry_timing_observation=None, memory_bucket=None, force=False):
        ticker = str(ticker or getattr(q, "ticker", "") or "").strip()
        if not ticker:
            return None
        family = str(family or getattr(q, "family", "") or "").strip().upper() or "UNKNOWN"
        market = market if isinstance(market, dict) else {}
        predictive_regime_summary = predictive_regime_summary if isinstance(predictive_regime_summary, dict) else {}
        entry_timing_fusion_summary = entry_timing_fusion_summary if isinstance(entry_timing_fusion_summary, dict) else {}
        tiny_canary_review_summary = tiny_canary_review_summary if isinstance(tiny_canary_review_summary, dict) else {}
        queue_summary = queue_summary if isinstance(queue_summary, dict) else {}
        family_rotation_summary = family_rotation_summary if isinstance(family_rotation_summary, dict) else {}
        adaptive_confidence_summary = adaptive_confidence_summary if isinstance(adaptive_confidence_summary, dict) else {}
        microstructure_summary = microstructure_summary if isinstance(microstructure_summary, dict) else {}
        learning_summary = learning_summary if isinstance(learning_summary, dict) else {}
        family_learning_summary = family_learning_summary if isinstance(family_learning_summary, dict) else {}
        entry_timing_observation = entry_timing_observation if isinstance(entry_timing_observation, dict) else {}
        memory_bucket = memory_bucket if isinstance(memory_bucket, dict) else {}
        ticker_bucket = self._get_canary_audit_bucket("canary_audit_by_ticker", f"ticker:{ticker}")
        family_bucket = self._get_canary_audit_bucket("canary_audit_by_family", f"family:{family}")
        now = time.time()
        ticker_bucket["first_seen_time"] = ticker_bucket.get("first_seen_time") or now
        ticker_bucket["last_seen_time"] = now
        ticker_bucket["ticker"] = ticker
        ticker_bucket["family"] = family
        ticker_bucket["candidate_count"] = int(ticker_bucket.get("candidate_count", 0) or 0) + 1
        blocker_reason = str(
            entry_timing_observation.get("reject_reason")
            or entry_timing_observation.get("block_reason")
            or tiny_canary_review_summary.get("latest_blocker_reason")
            or queue_summary.get("top_queue_blocker")
            or learning_summary.get("candidate_learning_top_reason")
            or "unknown"
        ).strip().lower()
        phase55_status = str(entry_timing_observation.get("phase55_status") or "unknown").strip().lower()
        quote_widening = bool(entry_timing_observation.get("spread_widening_too_fast") or microstructure_summary.get("quote_churn_frequency", 0.0) > 0.65)
        quote_missing = bool(entry_timing_observation.get("quote_missing") or tiny_canary_review_summary.get("missing_quotes_block"))
        orderbook_collapsed = bool(entry_timing_observation.get("orderbook_collapsed") or microstructure_summary.get("execution_survivability_score", 1.0) < 0.25)
        edge_flipped_negative = bool(entry_timing_observation.get("edge_flipped_negative") or self.to_float(market.get("yes_ask"), 0.0) <= self.to_float(market.get("yes_bid"), 0.0))
        volatility_spike = bool(entry_timing_observation.get("volatility_spike") or self.to_float(microstructure_summary.get("spread_stability_score"), 1.0) < 0.35)
        failed_flag = bool(quote_widening or quote_missing or orderbook_collapsed or edge_flipped_negative or volatility_spike)
        predicted_entry_price = self.to_float(getattr(q, "yes_ask", None), self.to_float(market.get("yes_ask"), 0.0))
        predicted_exit_price = self.to_float(getattr(q, "yes_bid", None), self.to_float(market.get("yes_bid"), self.to_float(getattr(q, "last_price", None), 0.0)))
        spread = max(0.0, self.to_float(getattr(q, "yes_ask", None), self.to_float(market.get("yes_ask"), 0.0)) - self.to_float(getattr(q, "yes_bid", None), self.to_float(market.get("yes_bid"), 0.0)))
        expected_fill_quality = self._clamp(
            self.to_float(microstructure_summary.get("liquidity_reliability"), 0.0) * 0.30
            + self.to_float(microstructure_summary.get("execution_survivability_score"), 0.0) * 0.30
            + self.to_float(microstructure_summary.get("spread_stability_score"), 0.0) * 0.20
            + self._clamp(1.0 - self.to_float(microstructure_summary.get("quote_churn_frequency"), 0.0)) * 0.20
        )
        spread_decay_risk = self._clamp(
            min(
                1.0,
                spread * 4.0
                + (1.0 - self.to_float(microstructure_summary.get("spread_stability_score"), 0.0)) * 0.30
                + (1.0 - self._clamp(1.0 - self.to_float(microstructure_summary.get("quote_churn_frequency"), 0.0))) * 0.25,
            )
        )
        canary_readiness_score = self._clamp(
            self.to_float(predictive_regime_summary.get("predictive_regime_score"), 0.0) * 0.12
            + self.to_float(entry_timing_fusion_summary.get("entry_timing_fusion_score"), 0.0) * 0.16
            + self.to_float(tiny_canary_review_summary.get("tiny_canary_review_score"), 0.0) * 0.16
            + self.to_float(microstructure_summary.get("execution_survivability_score"), 0.0) * 0.18
            + self.to_float(microstructure_summary.get("spread_stability_score"), 0.0) * 0.10
            + self._clamp(1.0 - self.to_float(microstructure_summary.get("quote_churn_frequency"), 0.0)) * 0.10
            + self.to_float(family_rotation_summary.get("family_rotation_score"), 0.0) * 0.08
            + self.to_float(adaptive_confidence_summary.get("adaptive_confidence_modifier"), 0.0) * 0.04
            + self.to_float(memory_bucket.get("adaptive_priority_score"), 0.0) * 0.06
            + self.to_float(memory_bucket.get("stable_regime_bias"), 0.0) * 0.03
            + self.to_float(memory_bucket.get("promotion_strength"), 0.0) * 0.02
            + self._clamp(self.to_float(tiny_canary_review_summary.get("stable_review_cycles"), 0.0) / 4.0) * 0.05
        )
        survival_probability = self._clamp(
            self.to_float(microstructure_summary.get("execution_survivability_score"), 0.0) * 0.36
            + expected_fill_quality * 0.20
            + self._clamp(1.0 - spread_decay_risk) * 0.16
            + self.to_float(tiny_canary_review_summary.get("edge_consistency"), 0.0) * 0.10
            + self.to_float(tiny_canary_review_summary.get("timing_consistency"), 0.0) * 0.08
            + self.to_float(microstructure_summary.get("liquidity_reliability"), 0.0) * 0.10
        )
        post_cost_edge = self._clamp(
            max(
                0.0,
                predicted_exit_price - predicted_entry_price
                - spread * 0.20
                - spread_decay_risk * 0.05
                + self.to_float(tiny_canary_review_summary.get("edge_over_cost_quality"), 0.0) * 0.20
                + self.to_float(entry_timing_fusion_summary.get("entry_timing_fusion_score"), 0.0) * 0.08,
            )
        )
        stable_canary_count = int(ticker_bucket.get("stable_canary_count", 0) or 0)
        failed_canary_count = int(ticker_bucket.get("failed_canary_count", 0) or 0)
        decayed_edge_count = int(ticker_bucket.get("decayed_edge_count", 0) or 0)
        survival_rate = self._clamp(
            stable_canary_count / max(stable_canary_count + failed_canary_count, 1)
        )
        average_post_cost_edge = self.to_float(ticker_bucket.get("average_post_cost_edge"), 0.0)
        average_edge_decay_velocity = self.to_float(ticker_bucket.get("average_edge_decay_velocity"), 0.0)
        if failed_flag:
            outcome = "failed"
            failed_canary_count += 1
            decayed_edge_count += 1 if edge_flipped_negative or volatility_spike else 0
            ticker_bucket["decay_warning_count"] = int(ticker_bucket.get("decay_warning_count", 0) or 0) + 1
            if quote_missing or quote_widening or orderbook_collapsed:
                ticker_bucket["unstable_quote_count"] = int(ticker_bucket.get("unstable_quote_count", 0) or 0) + 1
        elif canary_readiness_score >= 0.62 and post_cost_edge > 0.0 and survival_probability >= 0.40:
            outcome = "stable"
            stable_canary_count += 1
        else:
            outcome = "failed" if canary_readiness_score < 0.28 else "stable"
            if outcome == "stable":
                stable_canary_count += 1
            else:
                failed_canary_count += 1
        observed_edge_decay_velocity = self._clamp(max(0.0, spread_decay_risk * 0.45 + (1.0 - survival_probability) * 0.55))
        average_post_cost_edge = (average_post_cost_edge * 0.82) + (post_cost_edge * 0.18)
        average_edge_decay_velocity = (average_edge_decay_velocity * 0.82) + (observed_edge_decay_velocity * 0.18)
        survival_rate = self._clamp(stable_canary_count / max(stable_canary_count + failed_canary_count, 1))
        ticker_bucket["stable_canary_count"] = stable_canary_count
        ticker_bucket["failed_canary_count"] = failed_canary_count
        ticker_bucket["decayed_edge_count"] = decayed_edge_count
        ticker_bucket["survival_rate"] = round(survival_rate, 4)
        ticker_bucket["average_post_cost_edge"] = round(average_post_cost_edge, 4)
        ticker_bucket["average_edge_decay_velocity"] = round(average_edge_decay_velocity, 4)
        ticker_bucket["latest_canary_audit_score"] = round(canary_readiness_score, 4)
        ticker_bucket["latest_canary_audit_state"] = outcome
        ticker_bucket["latest_blocker_reason"] = blocker_reason
        ticker_bucket["best_canary_score"] = max(self.to_float(ticker_bucket.get("best_canary_score"), 0.0) or 0.0, canary_readiness_score)
        ticker_bucket["best_survival_probability"] = max(self.to_float(ticker_bucket.get("best_survival_probability"), 0.0) or 0.0, survival_probability)
        ticker_bucket["best_post_cost_edge"] = max(self.to_float(ticker_bucket.get("best_post_cost_edge"), 0.0) or 0.0, post_cost_edge)
        ticker_bucket.setdefault("score_history", deque(maxlen=24)).append(canary_readiness_score)
        ticker_bucket.setdefault("state_history", deque(maxlen=24)).append(outcome)
        ticker_bucket.setdefault("blocker_history", deque(maxlen=24)).append(blocker_reason)
        ticker_bucket["last_summary"] = {
            "ticker": ticker,
            "family": family,
            "canary_readiness_score": round(canary_readiness_score, 4),
            "canary_state": outcome,
            "hypothetical_entry_price": round(predicted_entry_price, 4),
            "hypothetical_exit_price": round(predicted_exit_price, 4),
            "expected_fill_quality": round(expected_fill_quality, 4),
            "spread_decay_risk": round(spread_decay_risk, 4),
            "quote_stability": round(self._clamp(1.0 - self.to_float(microstructure_summary.get("quote_churn_frequency"), 0.0)), 4),
            "edge_survival_probability": round(survival_probability, 4),
            "hypothetical_post_cost_edge": round(post_cost_edge, 4),
            "would_survive_after_fees": bool(post_cost_edge > 0.0),
            "would_survive_after_spread": bool(spread_decay_risk < 0.72 and spread < 0.35),
            "would_survive_after_slippage": bool(expected_fill_quality >= 0.32),
            "would_survive_after_decay": bool(survival_probability >= 0.34),
            "stable_canary_count": int(stable_canary_count),
            "failed_canary_count": int(failed_canary_count),
            "decayed_edge_count": int(decayed_edge_count),
            "survival_rate": round(survival_rate, 4),
            "average_post_cost_edge": round(average_post_cost_edge, 4),
            "average_edge_decay_velocity": round(average_edge_decay_velocity, 4),
            "latest_blocker_reason": blocker_reason,
            "unstable_quote_count": int(ticker_bucket.get("unstable_quote_count", 0) or 0),
            "decay_warning_count": int(ticker_bucket.get("decay_warning_count", 0) or 0),
            "live_arb_enabled": bool(AION_LIVE_ARB_ENABLED),
        }
        family_bucket["first_seen_time"] = family_bucket.get("first_seen_time") or now
        family_bucket["last_seen_time"] = now
        family_bucket["family"] = family
        family_bucket["ticker"] = ticker
        family_bucket["latest_canary_audit_score"] = max(self.to_float(family_bucket.get("latest_canary_audit_score"), 0.0) or 0.0, canary_readiness_score)
        family_bucket["latest_canary_audit_state"] = outcome
        family_bucket["latest_blocker_reason"] = blocker_reason
        family_bucket["candidate_count"] = int(family_bucket.get("candidate_count", 0) or 0) + 1
        family_bucket["stable_canary_count"] = int(family_bucket.get("stable_canary_count", 0) or 0) + (1 if outcome == "stable" else 0)
        family_bucket["failed_canary_count"] = int(family_bucket.get("failed_canary_count", 0) or 0) + (1 if outcome == "failed" else 0)
        family_bucket["decayed_edge_count"] = int(family_bucket.get("decayed_edge_count", 0) or 0) + (1 if edge_flipped_negative or volatility_spike else 0)
        family_bucket["survival_rate"] = round(self._clamp(family_bucket["stable_canary_count"] / max(family_bucket["stable_canary_count"] + family_bucket["failed_canary_count"], 1)), 4)
        family_bucket["average_post_cost_edge"] = round((self.to_float(family_bucket.get("average_post_cost_edge"), 0.0) * 0.82) + (post_cost_edge * 0.18), 4)
        family_bucket["average_edge_decay_velocity"] = round((self.to_float(family_bucket.get("average_edge_decay_velocity"), 0.0) * 0.82) + (observed_edge_decay_velocity * 0.18), 4)
        family_bucket["decay_warning_count"] = int(family_bucket.get("decay_warning_count", 0) or 0) + (1 if edge_flipped_negative or volatility_spike else 0)
        family_bucket["unstable_quote_count"] = int(family_bucket.get("unstable_quote_count", 0) or 0) + (1 if quote_missing or quote_widening or orderbook_collapsed else 0)
        family_bucket["last_summary"] = self._build_canary_audit_family_summary(family=family)
        self.last_canary_audit_summary = dict(ticker_bucket["last_summary"])
        self.last_canary_audit_family_summary = dict(family_bucket.get("last_summary") or {})
        self.last_canary_audit_overall_summary = self._build_canary_audit_overall_summary()
        self._emit_canary_audit_telemetry(
            ticker_bucket=ticker_bucket,
            family_bucket=family_bucket,
            force=force or outcome == "failed" or canary_readiness_score >= 0.62,
        )
        return ticker_bucket["last_summary"], {
            "canary_readiness_score": round(canary_readiness_score, 4),
            "predicted_entry_price": round(predicted_entry_price, 4),
            "predicted_exit_price": round(predicted_exit_price, 4),
            "expected_fill_quality": round(expected_fill_quality, 4),
            "spread_decay_risk": round(spread_decay_risk, 4),
            "edge_survival_probability": round(survival_probability, 4),
            "hypothetical_post_cost_edge": round(post_cost_edge, 4),
            "would_survive_after_fees": bool(post_cost_edge > 0.0),
            "would_survive_after_spread": bool(spread_decay_risk < 0.72 and spread < 0.35),
            "would_survive_after_slippage": bool(expected_fill_quality >= 0.32),
            "would_survive_after_decay": bool(survival_probability >= 0.34),
            "decay_velocity": round(observed_edge_decay_velocity, 4),
        }

    def _get_opportunity_persistence_bucket(self, container_name, key):
        buckets = getattr(self, container_name, None)
        if not isinstance(buckets, dict):
            buckets = {}
            setattr(self, container_name, buckets)
        bucket = buckets.setdefault(
            key,
            {
                "first_seen_time": None,
                "last_seen_time": 0.0,
                "ticker": None,
                "family": None,
                "candidate_count": 0,
                "recovery_count": 0,
                "decay_count": 0,
                "recovered_after_decay_count": 0,
                "permanent_death_count": 0,
                "persistent_edge_count": 0,
                "dead_edge_count": 0,
                "persistence_confidence": 0.0,
                "persistence_score": 0.0,
                "adaptive_persistence_score": 0.0,
                "edge_reappearance_rate": 0.0,
                "temporary_decay_rate": 0.0,
                "permanent_failure_rate": 0.0,
                "recovery_velocity": 0.0,
                "opportunity_lifespan": 0.0,
                "recurring_edge_frequency": 0.0,
                "decay_recovery_probability": 0.0,
                "average_recovery_time": 0.0,
                "average_decay_duration": 0.0,
                "latest_persistence_state": "unknown",
                "latest_blocker_reason": "unknown",
                "latest_recovery_reason": "none",
                "latest_decay_reason": "none",
                "top_recovery_structure": "none",
                "last_summary": {},
                "score_history": deque(maxlen=24),
                "state_history": deque(maxlen=24),
                "blocker_history": deque(maxlen=24),
                "recovery_structure_history": deque(maxlen=24),
                "last_recovery_ts": 0.0,
                "last_decay_ts": 0.0,
                "last_edge_reappearance_ts": 0.0,
                "last_edge_disappearance_ts": 0.0,
            },
        )
        bucket.setdefault("score_history", deque(maxlen=24))
        bucket.setdefault("state_history", deque(maxlen=24))
        bucket.setdefault("blocker_history", deque(maxlen=24))
        bucket.setdefault("recovery_structure_history", deque(maxlen=24))
        return bucket

    def _classify_opportunity_persistence_state(
        self,
        *,
        adaptive_persistence_score=0.0,
        persistence_score=0.0,
        blocker_reason=None,
        edge_reappearance_rate=0.0,
        temporary_decay_rate=0.0,
        permanent_failure_rate=0.0,
        recovery_velocity=0.0,
        recurring_edge_frequency=0.0,
        decay_recovery_probability=0.0,
        repeated_near_pass=False,
        hard_blocker=False,
    ):
        score = self._clamp(max(self.to_float(adaptive_persistence_score, 0.0), self.to_float(persistence_score, 0.0)))
        blocker_reason = str(blocker_reason or "").strip().lower()
        if hard_blocker or blocker_reason in {"unsafe_price", "low_volume", "missing_quotes", "edge_below_cost", "liquidity_failure", "duplicate_protection", "cooldown_protection", "phase55_failure"}:
            if score < 0.35 and permanent_failure_rate >= 0.18:
                return "dead"
            if permanent_failure_rate >= 0.25 and recovery_velocity < 0.12:
                return "dead"
        if score >= 0.68 and (edge_reappearance_rate >= 0.30 or recurring_edge_frequency >= 0.35 or decay_recovery_probability >= 0.55):
            return "persistent"
        if score >= 0.54 and recovery_velocity >= 0.16 and edge_reappearance_rate >= 0.18:
            return "recovering"
        if temporary_decay_rate >= 0.28 or blocker_reason in {"missing_quotes", "unsafe_price", "edge_below_cost", "low_volume"}:
            return "cooling"
        if score >= 0.40:
            return "surviving"
        return "unstable"

    def _compute_adaptive_persistence_score(
        self,
        *,
        predictive_regime_score=0.0,
        adaptive_confidence_modifier=0.0,
        family_rotation_score=0.0,
        entry_timing_fusion_score=0.0,
        edge_durability_score=0.0,
        execution_survivability_score=0.0,
        orderbook_quality=0.0,
        spread_stability=0.0,
        quote_stability=0.0,
        edge_reappearance_rate=0.0,
        temporary_decay_rate=0.0,
        permanent_failure_rate=0.0,
        recovery_velocity=0.0,
        opportunity_lifespan=0.0,
        recurring_edge_frequency=0.0,
        decay_recovery_probability=0.0,
        repeated_near_pass=0.0,
        queue_state=None,
        blocker_reason=None,
        memory_bucket=None,
        base_persistence_score=0.0,
    ):
        memory_bucket = memory_bucket if isinstance(memory_bucket, dict) else {}
        queue_state = str(queue_state or "unknown").strip().lower()
        blocker_reason = str(blocker_reason or "").strip().lower()
        predictive_regime_score = self._clamp(self.to_float(predictive_regime_score, 0.0))
        confidence_support = self._clamp(0.5 + self.to_float(adaptive_confidence_modifier, 0.0))
        family_rotation_score = self._clamp(self.to_float(family_rotation_score, 0.0))
        entry_timing_fusion_score = self._clamp(self.to_float(entry_timing_fusion_score, 0.0))
        edge_durability_score = self._clamp(self.to_float(edge_durability_score, 0.0))
        execution_survivability_score = self._clamp(self.to_float(execution_survivability_score, 0.0))
        orderbook_quality = self._clamp(self.to_float(orderbook_quality, 0.0))
        spread_stability = self._clamp(self.to_float(spread_stability, 0.0))
        quote_stability = self._clamp(self.to_float(quote_stability, 0.0))
        edge_reappearance_rate = self._clamp(self.to_float(edge_reappearance_rate, 0.0))
        temporary_decay_rate = self._clamp(self.to_float(temporary_decay_rate, 0.0))
        permanent_failure_rate = self._clamp(self.to_float(permanent_failure_rate, 0.0))
        recovery_velocity = self._clamp(self.to_float(recovery_velocity, 0.0))
        recurring_edge_frequency = self._clamp(self.to_float(recurring_edge_frequency, 0.0))
        decay_recovery_probability = self._clamp(self.to_float(decay_recovery_probability, 0.0))
        repeated_near_pass = self._clamp(self.to_float(repeated_near_pass, 0.0))
        opportunity_lifespan = max(0.0, self.to_float(opportunity_lifespan, 0.0))
        base_persistence_score = self._clamp(self.to_float(base_persistence_score, 0.0))
        queue_support = {
            "strong_watch": 0.86,
            "near_ready": 0.80,
            "improving_watch": 0.74,
            "weak_watch": 0.60,
            "blocked": 0.42,
            "expired": 0.22,
            "unknown": 0.50,
        }.get(queue_state, 0.50)
        blocker_penalty = 0.0
        if blocker_reason in {"unsafe_price", "low_volume", "missing_quotes", "edge_below_cost", "liquidity_failure", "duplicate_protection", "cooldown_protection", "phase55_failure"}:
            blocker_penalty = 0.16
        recovery_bonus = min(1.0, opportunity_lifespan / 86400.0) * 0.05
        adaptive_persistence_score = self._clamp(
            base_persistence_score * 0.08
            + predictive_regime_score * 0.12
            + confidence_support * 0.09
            + family_rotation_score * 0.09
            + entry_timing_fusion_score * 0.10
            + edge_durability_score * 0.15
            + execution_survivability_score * 0.14
            + orderbook_quality * 0.08
            + spread_stability * 0.08
            + quote_stability * 0.07
            + edge_reappearance_rate * 0.10
            + decay_recovery_probability * 0.08
            + recurring_edge_frequency * 0.05
            + recovery_velocity * 0.05
            + recovery_bonus
            + repeated_near_pass * 0.03
            + queue_support * 0.05
            - temporary_decay_rate * 0.10
            - permanent_failure_rate * 0.16
            - blocker_penalty
        )
        if blocker_reason in {"unsafe_price", "low_volume", "missing_quotes", "edge_below_cost", "liquidity_failure", "duplicate_protection", "cooldown_protection", "phase55_failure"} and adaptive_persistence_score < 0.28:
            adaptive_persistence_score = min(adaptive_persistence_score, 0.18)
        promotion_reason = "edge_reappearance_recovery" if edge_reappearance_rate >= 0.25 else ("regime_rebound" if predictive_regime_score >= 0.55 else "persistence_support")
        demotion_reason = "permanent_failure" if permanent_failure_rate >= 0.20 else (f"blocker_{blocker_reason}" if blocker_reason else "persistence_decay")
        soft_persistence_adjustment = max(-0.015, min(0.015, (adaptive_persistence_score - 0.5) * 0.03))
        persistence_multiplier = max(0.92, min(1.08, 1.0 + soft_persistence_adjustment))
        decay_multiplier = max(0.92, min(1.08, 1.0 - soft_persistence_adjustment))
        return {
            "adaptive_persistence_score": round(adaptive_persistence_score, 4),
            "soft_persistence_adjustment": round(soft_persistence_adjustment, 4),
            "promotion_strength": round(max(0.0, adaptive_persistence_score - 0.5), 4),
            "demotion_strength": round(max(0.0, 0.5 - adaptive_persistence_score), 4),
            "promotion_multiplier": round(persistence_multiplier, 4),
            "demotion_multiplier": round(decay_multiplier, 4),
            "promotion_reason": promotion_reason,
            "demotion_reason": demotion_reason,
        }

    def _build_opportunity_persistence_family_summary(self, family=None):
        family = str(family or "UNKNOWN").strip().upper() or "UNKNOWN"
        ticker_container = getattr(self, "opportunity_persistence_by_ticker", {}) or {}
        family_buckets = []
        if isinstance(ticker_container, dict):
            for bucket in ticker_container.values():
                if not isinstance(bucket, dict):
                    continue
                if str(bucket.get("family") or "").strip().upper() == family:
                    family_buckets.append(bucket)
        family_bucket = self._get_opportunity_persistence_bucket("opportunity_persistence_by_family", f"family:{family}")
        if not family_buckets:
            summary = {
                "family": family,
                "candidate_count": 0,
                "recovery_count": 0,
                "decay_count": 0,
                "recovered_after_decay_count": 0,
                "permanent_death_count": 0,
                "persistent_edge_count": 0,
                "dead_edge_count": 0,
                "recovery_ratio": 0.0,
                "strongest_persistence_ticker": None,
                "strongest_persistence_score": 0.0,
                "strongest_adaptive_persistence_score": 0.0,
                "average_recovery_time": round(self.to_float(family_bucket.get("average_recovery_time"), 0.0), 4),
                "top_recovery_structure": str(family_bucket.get("top_recovery_structure") or "none"),
                "best_persistence_state": str(family_bucket.get("latest_persistence_state") or "unknown"),
                "live_arb_enabled": bool(AION_LIVE_ARB_ENABLED),
            }
            family_bucket["last_summary"] = summary
            return summary
        best_bucket = max(
            family_buckets,
            key=lambda bucket: (
                self.to_float(bucket.get("adaptive_persistence_score"), 0.0),
                self.to_float(bucket.get("persistence_score"), 0.0),
                self.to_float(bucket.get("decay_recovery_probability"), 0.0),
            ),
        )
        structure_counts = Counter(
            str(bucket.get("top_recovery_structure") or "none").strip().lower()
            for bucket in family_buckets
            if str(bucket.get("top_recovery_structure") or "").strip()
        )
        summary = {
            "family": family,
            "candidate_count": int(len(family_buckets)),
            "recovery_count": int(sum(int(bucket.get("recovery_count", 0) or 0) for bucket in family_buckets)),
            "decay_count": int(sum(int(bucket.get("decay_count", 0) or 0) for bucket in family_buckets)),
            "recovered_after_decay_count": int(sum(int(bucket.get("recovered_after_decay_count", 0) or 0) for bucket in family_buckets)),
            "permanent_death_count": int(sum(int(bucket.get("permanent_death_count", 0) or 0) for bucket in family_buckets)),
            "persistent_edge_count": int(sum(int(bucket.get("persistent_edge_count", 0) or 0) for bucket in family_buckets)),
            "dead_edge_count": int(sum(int(bucket.get("dead_edge_count", 0) or 0) for bucket in family_buckets)),
            "recovery_ratio": round(
                self._clamp(
                    self.to_float(sum(int(bucket.get("recovery_count", 0) or 0) for bucket in family_buckets), 0.0)
                    / max(
                        self.to_float(sum(int(bucket.get("recovery_count", 0) or 0) for bucket in family_buckets), 0.0)
                        + self.to_float(sum(int(bucket.get("decay_count", 0) or 0) for bucket in family_buckets), 0.0),
                        1.0,
                    )
                ),
                4,
            ),
            "strongest_persistence_ticker": str(best_bucket.get("ticker") or "").strip() or None,
            "strongest_persistence_score": round(self.to_float(best_bucket.get("adaptive_persistence_score"), 0.0) or 0.0, 4),
            "strongest_adaptive_persistence_score": round(self.to_float(best_bucket.get("adaptive_persistence_score"), 0.0) or 0.0, 4),
            "average_recovery_time": round(sum(self.to_float(bucket.get("average_recovery_time"), 0.0) for bucket in family_buckets) / max(len(family_buckets), 1), 4),
            "top_recovery_structure": structure_counts.most_common(1)[0][0] if structure_counts else str(family_bucket.get("top_recovery_structure") or "none"),
            "best_persistence_state": str(best_bucket.get("latest_persistence_state") or "unknown"),
            "live_arb_enabled": bool(AION_LIVE_ARB_ENABLED),
        }
        family_bucket["last_summary"] = summary
        return summary

    def _build_opportunity_persistence_overall_summary(self):
        ticker_container = getattr(self, "opportunity_persistence_by_ticker", {}) or {}
        family_container = getattr(self, "opportunity_persistence_by_family", {}) or {}
        ticker_buckets = [bucket for bucket in ticker_container.values() if isinstance(bucket, dict)]
        family_buckets = [bucket for bucket in family_container.values() if isinstance(bucket, dict)]
        if not ticker_buckets:
            return {
                "scope": "overall",
                "candidate_count": 0,
                "recovery_count": 0,
                "decay_count": 0,
                "recovery_ratio": 0.0,
                "persistent_edge_count": 0,
                "dead_edge_count": 0,
                "average_recovery_time": 0.0,
                "strongest_persistence_family": None,
                "strongest_persistence_ticker": None,
                "strongest_persistence_score": 0.0,
                "top_recovery_structure": "none",
                "live_arb_enabled": bool(AION_LIVE_ARB_ENABLED),
            }
        best_bucket = max(
            ticker_buckets,
            key=lambda bucket: (
                self.to_float(bucket.get("adaptive_persistence_score"), 0.0),
                self.to_float(bucket.get("persistence_score"), 0.0),
                self.to_float(bucket.get("decay_recovery_probability"), 0.0),
            ),
        )
        structure_counts = Counter(
            str(bucket.get("top_recovery_structure") or "none").strip().lower()
            for bucket in ticker_buckets
            if str(bucket.get("top_recovery_structure") or "").strip()
        )
        total_recovery_count = int(sum(int(bucket.get("recovery_count", 0) or 0) for bucket in ticker_buckets))
        total_decay_count = int(sum(int(bucket.get("decay_count", 0) or 0) for bucket in ticker_buckets))
        return {
            "scope": "overall",
            "candidate_count": int(len(ticker_buckets)),
            "family_count": int(len(family_buckets)),
            "recovery_count": total_recovery_count,
            "decay_count": total_decay_count,
            "recovery_ratio": round(self._clamp(total_recovery_count / max(total_recovery_count + total_decay_count, 1)), 4),
            "persistent_edge_count": int(sum(int(bucket.get("persistent_edge_count", 0) or 0) for bucket in ticker_buckets)),
            "dead_edge_count": int(sum(int(bucket.get("dead_edge_count", 0) or 0) for bucket in ticker_buckets)),
            "average_recovery_time": round(sum(self.to_float(bucket.get("average_recovery_time"), 0.0) for bucket in ticker_buckets) / max(len(ticker_buckets), 1), 4),
            "strongest_persistence_family": str(best_bucket.get("family") or "").strip().upper() or None,
            "strongest_persistence_ticker": str(best_bucket.get("ticker") or "").strip() or None,
            "strongest_persistence_score": round(self.to_float(best_bucket.get("adaptive_persistence_score"), 0.0) or 0.0, 4),
            "strongest_adaptive_persistence_score": round(self.to_float(best_bucket.get("adaptive_persistence_score"), 0.0) or 0.0, 4),
            "top_recovery_structure": structure_counts.most_common(1)[0][0] if structure_counts else "none",
            "live_arb_enabled": bool(AION_LIVE_ARB_ENABLED),
        }

    def _emit_opportunity_persistence_telemetry(self, *, ticker_bucket=None, family_bucket=None, force=False):
        ticker_bucket = ticker_bucket if isinstance(ticker_bucket, dict) else {}
        family_bucket = family_bucket if isinstance(family_bucket, dict) else {}
        ticker = str(ticker_bucket.get("ticker") or "").strip()
        family = str(ticker_bucket.get("family") or family_bucket.get("family") or "").strip().upper() or "UNKNOWN"
        now = time.time()
        summary = ticker_bucket.get("last_summary") if isinstance(ticker_bucket.get("last_summary"), dict) else {}
        if not summary:
            summary = {
                "ticker": ticker or "unknown",
                "family": family,
                "adaptive_persistence_score": round(self.to_float(ticker_bucket.get("adaptive_persistence_score"), 0.0) or 0.0, 4),
                "persistence_score": round(self.to_float(ticker_bucket.get("persistence_score"), 0.0) or 0.0, 4),
                "persistence_state": str(ticker_bucket.get("latest_persistence_state") or "unknown"),
                "latest_blocker_reason": str(ticker_bucket.get("latest_blocker_reason") or "unknown"),
            }
        emit_key = ticker or family
        last_emit = float(getattr(self, "opportunity_persistence_last_signal_ts_by_key", {}).get(emit_key, 0.0) or 0.0)
        if not force and ticker and (now - last_emit) < 120.0:
            return None
        if ticker:
            self.opportunity_persistence_last_signal_ts_by_key[ticker] = now
        if family:
            self.opportunity_persistence_last_signal_ts_by_key[family] = now
        print("[LIVE-PERSISTENCE-TRACK] " + json.dumps(summary, sort_keys=True, default=str))
        print("[LIVE-PERSISTENCE-RECOVERY] " + json.dumps({
            "ticker": summary.get("ticker"),
            "family": summary.get("family"),
            "recovery_count": summary.get("recovery_count"),
            "recovered_after_decay_count": summary.get("recovered_after_decay_count"),
            "edge_reappearance_rate": summary.get("edge_reappearance_rate"),
            "recovery_velocity": summary.get("recovery_velocity"),
            "average_recovery_time": summary.get("average_recovery_time"),
        }, sort_keys=True, default=str))
        print("[LIVE-PERSISTENCE-DECAY] " + json.dumps({
            "ticker": summary.get("ticker"),
            "family": summary.get("family"),
            "decay_count": summary.get("decay_count"),
            "temporary_decay_rate": summary.get("temporary_decay_rate"),
            "permanent_failure_rate": summary.get("permanent_failure_rate"),
            "average_decay_duration": summary.get("average_decay_duration"),
            "latest_blocker_reason": summary.get("latest_blocker_reason"),
        }, sort_keys=True, default=str))
        print("[LIVE-PERSISTENCE-SURVIVAL] " + json.dumps({
            "ticker": summary.get("ticker"),
            "family": summary.get("family"),
            "adaptive_persistence_score": summary.get("adaptive_persistence_score"),
            "persistence_score": summary.get("persistence_score"),
            "decay_recovery_probability": summary.get("decay_recovery_probability"),
            "persistent_edge_count": summary.get("persistent_edge_count"),
            "dead_edge_count": summary.get("dead_edge_count"),
            "persistence_state": summary.get("persistence_state"),
        }, sort_keys=True, default=str))
        self.last_opportunity_persistence_summary = dict(summary)
        self.last_opportunity_persistence_family_summary = dict(family_bucket.get("last_summary") or {})
        self.last_opportunity_persistence_overall_summary = self._build_opportunity_persistence_overall_summary()
        print("[LIVE-PERSISTENCE-DASHBOARD] " + json.dumps(self.last_opportunity_persistence_overall_summary, sort_keys=True, default=str))
        return summary

    def _update_opportunity_persistence(self, *, ticker=None, family=None, market=None, q=None, predictive_regime_summary=None, entry_timing_fusion_summary=None, tiny_canary_review_summary=None, canary_audit_summary=None, queue_summary=None, family_rotation_summary=None, adaptive_confidence_summary=None, microstructure_summary=None, learning_summary=None, family_learning_summary=None, entry_timing_observation=None, memory_bucket=None, force=False):
        ticker = str(ticker or getattr(q, "ticker", "") or "").strip()
        if not ticker:
            return None
        family = str(family or getattr(q, "family", "") or "").strip().upper() or "UNKNOWN"
        market = market if isinstance(market, dict) else {}
        predictive_regime_summary = predictive_regime_summary if isinstance(predictive_regime_summary, dict) else {}
        entry_timing_fusion_summary = entry_timing_fusion_summary if isinstance(entry_timing_fusion_summary, dict) else {}
        tiny_canary_review_summary = tiny_canary_review_summary if isinstance(tiny_canary_review_summary, dict) else {}
        canary_audit_summary = canary_audit_summary if isinstance(canary_audit_summary, dict) else {}
        queue_summary = queue_summary if isinstance(queue_summary, dict) else {}
        family_rotation_summary = family_rotation_summary if isinstance(family_rotation_summary, dict) else {}
        adaptive_confidence_summary = adaptive_confidence_summary if isinstance(adaptive_confidence_summary, dict) else {}
        microstructure_summary = microstructure_summary if isinstance(microstructure_summary, dict) else {}
        learning_summary = learning_summary if isinstance(learning_summary, dict) else {}
        family_learning_summary = family_learning_summary if isinstance(family_learning_summary, dict) else {}
        entry_timing_observation = entry_timing_observation if isinstance(entry_timing_observation, dict) else {}
        memory_bucket = memory_bucket if isinstance(memory_bucket, dict) else {}
        ticker_bucket = self._get_opportunity_persistence_bucket("opportunity_persistence_by_ticker", f"ticker:{ticker}")
        family_bucket = self._get_opportunity_persistence_bucket("opportunity_persistence_by_family", f"family:{family}")
        now = time.time()
        ticker_bucket["first_seen_time"] = ticker_bucket.get("first_seen_time") or now
        ticker_bucket["last_seen_time"] = now
        ticker_bucket["ticker"] = ticker
        ticker_bucket["family"] = family
        family_bucket["first_seen_time"] = family_bucket.get("first_seen_time") or now
        family_bucket["last_seen_time"] = now
        family_bucket["ticker"] = ticker
        family_bucket["family"] = family
        ticker_bucket["candidate_count"] = int(ticker_bucket.get("candidate_count", 0) or 0) + 1
        family_bucket["candidate_count"] = int(family_bucket.get("candidate_count", 0) or 0) + 1
        blocker_reason = str(
            entry_timing_observation.get("reject_reason")
            or entry_timing_observation.get("block_reason")
            or tiny_canary_review_summary.get("latest_blocker_reason")
            or canary_audit_summary.get("latest_blocker_reason")
            or queue_summary.get("top_queue_blocker")
            or learning_summary.get("candidate_learning_top_reason")
            or "unknown"
        ).strip().lower()
        hard_blocker = blocker_reason in {"unsafe_price", "low_volume", "missing_quotes", "edge_below_cost", "liquidity_failure", "duplicate_protection", "cooldown_protection", "phase55_failure"}
        previous_state = str(ticker_bucket.get("latest_persistence_state") or "unknown").strip().lower()
        previous_score = self.to_float(ticker_bucket.get("persistence_score"), 0.0)
        predictive_regime_score = self.to_float(predictive_regime_summary.get("predictive_regime_score"), self.to_float(predictive_regime_summary.get("top_predictive_score"), 0.0))
        entry_timing_score = self.to_float(entry_timing_fusion_summary.get("entry_timing_fusion_score"), 0.0)
        confidence_modifier = self.to_float(adaptive_confidence_summary.get("adaptive_confidence_modifier"), 0.0)
        family_rotation_score = self.to_float(family_rotation_summary.get("family_rotation_score"), 0.0)
        canary_score = self.to_float(canary_audit_summary.get("canary_readiness_score"), 0.0)
        tiny_review_score = self.to_float(tiny_canary_review_summary.get("tiny_canary_review_score"), 0.0)
        queue_state = str(
            queue_summary.get("latest_queue_state")
            or queue_summary.get("queue_state")
            or queue_summary.get("top_queue_state")
            or "unknown"
        ).strip().lower()
        quote_stability = self._clamp(1.0 - self.to_float(microstructure_summary.get("quote_churn_frequency"), 0.0))
        spread_stability = self._clamp(self.to_float(microstructure_summary.get("spread_stability_score"), 0.5))
        orderbook_quality = self._clamp(
            self.to_float(microstructure_summary.get("liquidity_reliability"), self.to_float(microstructure_summary.get("orderbook_quality"), 0.5))
        )
        edge_durability_score = self._clamp(
            self.to_float(microstructure_summary.get("edge_durability_score"), self.to_float(microstructure_summary.get("edge_stability_score"), 0.5))
        )
        execution_survivability_score = self._clamp(self.to_float(microstructure_summary.get("execution_survivability_score"), 0.5))
        repeated_near_pass = max(
            self.to_float(tiny_canary_review_summary.get("stable_review_cycles"), 0.0),
            self.to_float(queue_summary.get("near_pass_count"), 0.0),
            self.to_float(queue_summary.get("queue_hits"), 0.0) * 0.10,
            self.to_float(canary_audit_summary.get("candidate_count"), 0.0) * 0.05,
        )
        recovery_signal = bool(
            quote_stability >= 0.55
            or spread_stability >= 0.55
            or orderbook_quality >= 0.55
            or edge_durability_score >= 0.50
            or execution_survivability_score >= 0.50
            or predictive_regime_score >= 0.50
            or canary_score >= 0.35
            or tiny_review_score >= 0.35
        )
        decay_signal = bool(
            hard_blocker
            or quote_stability < 0.42
            or spread_stability < 0.42
            or orderbook_quality < 0.40
            or edge_durability_score < 0.38
            or execution_survivability_score < 0.35
            or predictive_regime_score < 0.32
            or blocker_reason in {"blocked", "expired", "dead"}
        )
        recovery_structure = "none"
        if recovery_signal:
            if edge_durability_score >= 0.55 and execution_survivability_score >= 0.55:
                recovery_structure = "edge_reappearance"
            elif spread_stability >= 0.60 and quote_stability >= 0.60:
                recovery_structure = "spread_normalization"
            elif orderbook_quality >= 0.60:
                recovery_structure = "orderbook_recovery"
            elif predictive_regime_score >= 0.60:
                recovery_structure = "regime_rebound"
            else:
                recovery_structure = "stability_recovery"
        decay_structure = "none"
        if decay_signal:
            if hard_blocker:
                decay_structure = "hard_blocker_decay"
            elif quote_stability < 0.42:
                decay_structure = "quote_collapse"
            elif spread_stability < 0.42:
                decay_structure = "spread_widening"
            elif orderbook_quality < 0.40:
                decay_structure = "orderbook_weakness"
            elif execution_survivability_score < 0.35:
                decay_structure = "execution_decay"
            else:
                decay_structure = "regime_decay"
        if recovery_signal:
            ticker_bucket["recovery_count"] = int(ticker_bucket.get("recovery_count", 0) or 0) + (1 if previous_state in {"cooling", "decaying", "dead", "unstable"} else 0)
            family_bucket["recovery_count"] = int(family_bucket.get("recovery_count", 0) or 0) + (1 if previous_state in {"cooling", "decaying", "dead", "unstable"} else 0)
            if previous_state in {"cooling", "decaying", "dead", "unstable"}:
                ticker_bucket["recovered_after_decay_count"] = int(ticker_bucket.get("recovered_after_decay_count", 0) or 0) + 1
                family_bucket["recovered_after_decay_count"] = int(family_bucket.get("recovered_after_decay_count", 0) or 0) + 1
            ticker_bucket["last_recovery_ts"] = now
            family_bucket["last_recovery_ts"] = now
            observed_recovery_time = max(0.0, now - float(ticker_bucket.get("last_decay_ts") or ticker_bucket.get("last_edge_disappearance_ts") or ticker_bucket.get("first_seen_time") or now))
            if observed_recovery_time > 0.0:
                ticker_bucket["average_recovery_time"] = round((self.to_float(ticker_bucket.get("average_recovery_time"), 0.0) * 0.82) + (observed_recovery_time * 0.18), 4)
                family_bucket["average_recovery_time"] = round((self.to_float(family_bucket.get("average_recovery_time"), 0.0) * 0.82) + (observed_recovery_time * 0.18), 4)
            ticker_bucket["last_edge_reappearance_ts"] = now
            family_bucket["last_edge_reappearance_ts"] = now
            ticker_bucket["latest_recovery_reason"] = recovery_structure
            family_bucket["latest_recovery_reason"] = recovery_structure
            ticker_bucket.setdefault("recovery_structure_history", deque(maxlen=24)).append(recovery_structure)
            family_bucket.setdefault("recovery_structure_history", deque(maxlen=24)).append(recovery_structure)
        if decay_signal:
            ticker_bucket["decay_count"] = int(ticker_bucket.get("decay_count", 0) or 0) + 1
            family_bucket["decay_count"] = int(family_bucket.get("decay_count", 0) or 0) + 1
            ticker_bucket["last_decay_ts"] = now
            family_bucket["last_decay_ts"] = now
            ticker_bucket["last_edge_disappearance_ts"] = now
            family_bucket["last_edge_disappearance_ts"] = now
            observed_decay_duration = max(0.0, now - float(ticker_bucket.get("last_recovery_ts") or ticker_bucket.get("last_edge_reappearance_ts") or ticker_bucket.get("first_seen_time") or now))
            if observed_decay_duration > 0.0:
                ticker_bucket["average_decay_duration"] = round((self.to_float(ticker_bucket.get("average_decay_duration"), 0.0) * 0.82) + (observed_decay_duration * 0.18), 4)
                family_bucket["average_decay_duration"] = round((self.to_float(family_bucket.get("average_decay_duration"), 0.0) * 0.82) + (observed_decay_duration * 0.18), 4)
            ticker_bucket["latest_decay_reason"] = decay_structure if decay_structure != "none" else blocker_reason
            family_bucket["latest_decay_reason"] = decay_structure if decay_structure != "none" else blocker_reason
            if hard_blocker or (previous_state in {"cooling", "decaying", "unstable"} and previous_score < 0.30 and not recovery_signal):
                ticker_bucket["permanent_death_count"] = int(ticker_bucket.get("permanent_death_count", 0) or 0) + 1
                family_bucket["permanent_death_count"] = int(family_bucket.get("permanent_death_count", 0) or 0) + 1
        if not decay_signal and previous_state in {"cooling", "unstable"} and recovery_signal:
            ticker_bucket["stable_edge_cycles"] = int(ticker_bucket.get("stable_edge_cycles", 0) or 0) + 1
            family_bucket["stable_edge_cycles"] = int(family_bucket.get("stable_edge_cycles", 0) or 0) + 1
        if decay_signal and not hard_blocker and previous_state in {"recovering", "persistent"}:
            ticker_bucket["cooling_cycles"] = int(ticker_bucket.get("cooling_cycles", 0) or 0) + 1
            family_bucket["cooling_cycles"] = int(family_bucket.get("cooling_cycles", 0) or 0) + 1
        if hard_blocker:
            ticker_bucket["dead_edge_count"] = int(ticker_bucket.get("dead_edge_count", 0) or 0) + 1
            family_bucket["dead_edge_count"] = int(family_bucket.get("dead_edge_count", 0) or 0) + 1
        elif recovery_signal:
            ticker_bucket["persistent_edge_count"] = int(ticker_bucket.get("persistent_edge_count", 0) or 0) + 1
            family_bucket["persistent_edge_count"] = int(family_bucket.get("persistent_edge_count", 0) or 0) + 1
        opportunity_lifespan = max(0.0, now - float(ticker_bucket.get("first_seen_time") or now))
        lifespan_hours = max(opportunity_lifespan / 3600.0, 1.0)
        recovery_count = int(ticker_bucket.get("recovery_count", 0) or 0)
        decay_count = int(ticker_bucket.get("decay_count", 0) or 0)
        recovered_after_decay_count = int(ticker_bucket.get("recovered_after_decay_count", 0) or 0)
        permanent_death_count = int(ticker_bucket.get("permanent_death_count", 0) or 0)
        edge_reappearance_rate = self._clamp(recovered_after_decay_count / max(decay_count, 1))
        temporary_decay_rate = self._clamp(max(0.0, decay_count - permanent_death_count) / max(int(ticker_bucket.get("candidate_count", 0) or 0), 1))
        permanent_failure_rate = self._clamp(permanent_death_count / max(int(ticker_bucket.get("candidate_count", 0) or 0), 1))
        recovery_velocity = self._clamp(recovery_count / max(lifespan_hours, 1.0))
        recurring_edge_frequency = self._clamp((int(ticker_bucket.get("persistent_edge_count", 0) or 0) + recovery_count) / max(lifespan_hours, 1.0))
        regime_rebound_probability = self._clamp(
            predictive_regime_score * 0.35
            + self._clamp(0.5 + confidence_modifier) * 0.18
            + family_rotation_score * 0.12
            + entry_timing_score * 0.12
            + quote_stability * 0.08
            + spread_stability * 0.08
            + orderbook_quality * 0.07
        )
        decay_recovery_probability = self._clamp(
            edge_reappearance_rate * 0.34
            + regime_rebound_probability * 0.22
            + quote_stability * 0.12
            + spread_stability * 0.12
            + orderbook_quality * 0.10
            + execution_survivability_score * 0.10
        )
        adaptive_persistence_payload = self._compute_adaptive_persistence_score(
            predictive_regime_score=predictive_regime_score,
            adaptive_confidence_modifier=confidence_modifier,
            family_rotation_score=family_rotation_score,
            entry_timing_fusion_score=entry_timing_score,
            edge_durability_score=edge_durability_score,
            execution_survivability_score=execution_survivability_score,
            orderbook_quality=orderbook_quality,
            spread_stability=spread_stability,
            quote_stability=quote_stability,
            edge_reappearance_rate=edge_reappearance_rate,
            temporary_decay_rate=temporary_decay_rate,
            permanent_failure_rate=permanent_failure_rate,
            recovery_velocity=recovery_velocity,
            opportunity_lifespan=opportunity_lifespan,
            recurring_edge_frequency=recurring_edge_frequency,
            decay_recovery_probability=decay_recovery_probability,
            repeated_near_pass=repeated_near_pass,
            queue_state=queue_state,
            blocker_reason=blocker_reason,
            memory_bucket=ticker_bucket,
            base_persistence_score=previous_score,
        )
        adaptive_persistence_score = self.to_float(adaptive_persistence_payload.get("adaptive_persistence_score"), 0.0)
        persistence_score = self._clamp((previous_score * 0.82) + (adaptive_persistence_score * 0.18))
        persistence_confidence = self._clamp((self.to_float(ticker_bucket.get("persistence_confidence"), 0.0) * 0.80) + (adaptive_persistence_score * 0.20))
        persistence_state = self._classify_opportunity_persistence_state(
            adaptive_persistence_score=adaptive_persistence_score,
            persistence_score=persistence_score,
            blocker_reason=blocker_reason,
            edge_reappearance_rate=edge_reappearance_rate,
            temporary_decay_rate=temporary_decay_rate,
            permanent_failure_rate=permanent_failure_rate,
            recovery_velocity=recovery_velocity,
            recurring_edge_frequency=recurring_edge_frequency,
            decay_recovery_probability=decay_recovery_probability,
            repeated_near_pass=repeated_near_pass >= 1.0,
            hard_blocker=hard_blocker,
        )
        ticker_bucket["edge_reappearance_rate"] = round(edge_reappearance_rate, 4)
        ticker_bucket["temporary_decay_rate"] = round(temporary_decay_rate, 4)
        ticker_bucket["permanent_failure_rate"] = round(permanent_failure_rate, 4)
        ticker_bucket["recovery_velocity"] = round(recovery_velocity, 4)
        ticker_bucket["opportunity_lifespan"] = round(opportunity_lifespan, 4)
        ticker_bucket["recurring_edge_frequency"] = round(recurring_edge_frequency, 4)
        ticker_bucket["decay_recovery_probability"] = round(decay_recovery_probability, 4)
        ticker_bucket["persistence_confidence"] = round(persistence_confidence, 4)
        ticker_bucket["adaptive_persistence_score"] = round(adaptive_persistence_score, 4)
        ticker_bucket["persistence_score"] = round(persistence_score, 4)
        ticker_bucket["latest_persistence_state"] = persistence_state
        ticker_bucket["latest_blocker_reason"] = blocker_reason
        ticker_bucket["score_history"].append(adaptive_persistence_score)
        ticker_bucket["state_history"].append(persistence_state)
        ticker_bucket["blocker_history"].append(blocker_reason)
        ticker_bucket["top_recovery_structure"] = recovery_structure if recovery_signal else str(ticker_bucket.get("top_recovery_structure") or "none")
        ticker_bucket["last_summary"] = {
            "ticker": ticker,
            "family": family,
            "adaptive_persistence_score": round(adaptive_persistence_score, 4),
            "persistence_score": round(persistence_score, 4),
            "persistence_confidence": round(persistence_confidence, 4),
            "persistence_state": persistence_state,
            "edge_reappearance_rate": round(edge_reappearance_rate, 4),
            "temporary_decay_rate": round(temporary_decay_rate, 4),
            "permanent_failure_rate": round(permanent_failure_rate, 4),
            "recovery_velocity": round(recovery_velocity, 4),
            "opportunity_lifespan": round(opportunity_lifespan, 4),
            "recurring_edge_frequency": round(recurring_edge_frequency, 4),
            "decay_recovery_probability": round(decay_recovery_probability, 4),
            "recovery_count": int(recovery_count),
            "decay_count": int(decay_count),
            "recovered_after_decay_count": int(recovered_after_decay_count),
            "permanent_death_count": int(permanent_death_count),
            "average_recovery_time": round(self.to_float(ticker_bucket.get("average_recovery_time"), 0.0), 4),
            "average_decay_duration": round(self.to_float(ticker_bucket.get("average_decay_duration"), 0.0), 4),
            "top_recovery_structure": str(ticker_bucket.get("top_recovery_structure") or "none"),
            "latest_blocker_reason": blocker_reason,
            "live_arb_enabled": bool(AION_LIVE_ARB_ENABLED),
        }
        family_bucket["recovery_count"] = int(family_bucket.get("recovery_count", 0) or 0) + (1 if recovery_signal else 0)
        family_bucket["decay_count"] = int(family_bucket.get("decay_count", 0) or 0) + (1 if decay_signal else 0)
        family_bucket["recovered_after_decay_count"] = int(family_bucket.get("recovered_after_decay_count", 0) or 0) + (1 if recovery_signal and previous_state in {"cooling", "decaying", "dead", "unstable"} else 0)
        family_bucket["permanent_death_count"] = int(family_bucket.get("permanent_death_count", 0) or 0) + (1 if hard_blocker and adaptive_persistence_score < 0.28 else 0)
        family_bucket["persistent_edge_count"] = int(family_bucket.get("persistent_edge_count", 0) or 0) + (1 if persistence_state in {"persistent", "recovering"} else 0)
        family_bucket["dead_edge_count"] = int(family_bucket.get("dead_edge_count", 0) or 0) + (1 if persistence_state == "dead" else 0)
        family_bucket["persistence_confidence"] = round((self.to_float(family_bucket.get("persistence_confidence"), 0.0) * 0.80) + (persistence_confidence * 0.20), 4)
        family_bucket["persistence_score"] = round((self.to_float(family_bucket.get("persistence_score"), 0.0) * 0.80) + (persistence_score * 0.20), 4)
        family_bucket["adaptive_persistence_score"] = round(max(self.to_float(family_bucket.get("adaptive_persistence_score"), 0.0), adaptive_persistence_score), 4)
        family_bucket["edge_reappearance_rate"] = round((self.to_float(family_bucket.get("edge_reappearance_rate"), 0.0) * 0.80) + (edge_reappearance_rate * 0.20), 4)
        family_bucket["temporary_decay_rate"] = round((self.to_float(family_bucket.get("temporary_decay_rate"), 0.0) * 0.80) + (temporary_decay_rate * 0.20), 4)
        family_bucket["permanent_failure_rate"] = round((self.to_float(family_bucket.get("permanent_failure_rate"), 0.0) * 0.80) + (permanent_failure_rate * 0.20), 4)
        family_bucket["recovery_velocity"] = round((self.to_float(family_bucket.get("recovery_velocity"), 0.0) * 0.80) + (recovery_velocity * 0.20), 4)
        family_bucket["opportunity_lifespan"] = round(max(self.to_float(family_bucket.get("opportunity_lifespan"), 0.0), opportunity_lifespan), 4)
        family_bucket["recurring_edge_frequency"] = round((self.to_float(family_bucket.get("recurring_edge_frequency"), 0.0) * 0.80) + (recurring_edge_frequency * 0.20), 4)
        family_bucket["decay_recovery_probability"] = round((self.to_float(family_bucket.get("decay_recovery_probability"), 0.0) * 0.80) + (decay_recovery_probability * 0.20), 4)
        family_bucket["average_recovery_time"] = round((self.to_float(family_bucket.get("average_recovery_time"), 0.0) * 0.80) + (self.to_float(ticker_bucket.get("average_recovery_time"), 0.0) * 0.20), 4)
        family_bucket["average_decay_duration"] = round((self.to_float(family_bucket.get("average_decay_duration"), 0.0) * 0.80) + (self.to_float(ticker_bucket.get("average_decay_duration"), 0.0) * 0.20), 4)
        family_bucket["latest_persistence_state"] = persistence_state
        family_bucket["latest_blocker_reason"] = blocker_reason
        family_bucket["top_recovery_structure"] = recovery_structure if recovery_signal else str(family_bucket.get("top_recovery_structure") or "none")
        family_bucket.setdefault("score_history", deque(maxlen=24)).append(adaptive_persistence_score)
        family_bucket.setdefault("state_history", deque(maxlen=24)).append(persistence_state)
        family_bucket.setdefault("blocker_history", deque(maxlen=24)).append(blocker_reason)
        family_bucket.setdefault("recovery_structure_history", deque(maxlen=24)).append(recovery_structure)
        family_bucket["last_summary"] = self._build_opportunity_persistence_family_summary(family=family)
        self.last_opportunity_persistence_summary = dict(ticker_bucket["last_summary"])
        self.last_opportunity_persistence_family_summary = dict(family_bucket.get("last_summary") or {})
        self.last_opportunity_persistence_overall_summary = self._build_opportunity_persistence_overall_summary()
        self._emit_opportunity_persistence_telemetry(
            ticker_bucket=ticker_bucket,
            family_bucket=family_bucket,
            force=force or adaptive_persistence_score >= 0.60 or persistence_state in {"recovering", "persistent", "dead"},
        )
        return ticker_bucket["last_summary"], {
            "adaptive_persistence_score": round(adaptive_persistence_score, 4),
            "persistence_score": round(persistence_score, 4),
            "persistence_confidence": round(persistence_confidence, 4),
            "persistence_state": persistence_state,
            "edge_reappearance_rate": round(edge_reappearance_rate, 4),
            "temporary_decay_rate": round(temporary_decay_rate, 4),
            "permanent_failure_rate": round(permanent_failure_rate, 4),
            "recovery_velocity": round(recovery_velocity, 4),
            "opportunity_lifespan": round(opportunity_lifespan, 4),
            "recurring_edge_frequency": round(recurring_edge_frequency, 4),
            "decay_recovery_probability": round(decay_recovery_probability, 4),
            "adaptive_persistence_adjustment": round(adaptive_persistence_payload.get("soft_persistence_adjustment", 0.0), 4),
            "top_recovery_structure": str(ticker_bucket.get("top_recovery_structure") or "none"),
            "latest_blocker_reason": blocker_reason,
            "recovery_count": int(recovery_count),
            "decay_count": int(decay_count),
        }

    def _get_candidate_learning_bucket(self, container_name, key):
        buckets = getattr(self, container_name, None)
        if not isinstance(buckets, dict):
            buckets = {}
            setattr(self, container_name, buckets)
        bucket = buckets.setdefault(
            key,
            {
                "first_seen_time": None,
                "last_seen_time": 0.0,
                "ticker": None,
                "family": None,
                "market_type": None,
                "avoid_count": 0,
                "weak_count": 0,
                "improving_count": 0,
                "promising_count": 0,
                "strong_watch_count": 0,
                "unsafe_price_count": 0,
                "edge_below_cost_count": 0,
                "low_volume_count": 0,
                "missing_quotes_count": 0,
                "unstable_orderbook_count": 0,
                "phase55_block_count": 0,
                "liquidity_block_count": 0,
                "high_reactivation_count": 0,
                "high_adaptive_priority_count": 0,
                "stable_edge_durability_count": 0,
                "strong_survivability_count": 0,
                "clean_orderbook_quality_count": 0,
                "edge_above_cost_count": 0,
                "rejection_count": 0,
                "positive_signal_count": 0,
                "learning_score": 0.0,
                "learning_profile": "weak",
                "rejection_reason_counts": Counter(),
                "positive_reason_counts": Counter(),
                "market_type_counts": Counter(),
                "score_history": deque(maxlen=24),
                "profile_history": deque(maxlen=24),
                "last_summary": {},
            },
        )
        return bucket

    def _compute_family_learning_score(self, *, family_bucket=None, learning_bucket=None, learning_summary=None, reactivation_summary=None, adaptive_priority_summary=None):
        family_bucket = family_bucket if isinstance(family_bucket, dict) else {}
        learning_bucket = learning_bucket if isinstance(learning_bucket, dict) else {}
        learning_summary = learning_summary if isinstance(learning_summary, dict) else {}
        reactivation_summary = reactivation_summary if isinstance(reactivation_summary, dict) else {}
        adaptive_priority_summary = adaptive_priority_summary if isinstance(adaptive_priority_summary, dict) else {}
        stable_microstructure = max(
            0.0,
            min(
                1.0,
                (
                    self.to_float(family_bucket.get("avg_survivability"), self.to_float(learning_summary.get("avg_survivability"), 0.0)) * 0.35
                    + self.to_float(family_bucket.get("avg_edge_durability"), self.to_float(learning_summary.get("avg_edge_durability"), 0.0)) * 0.25
                    + self.to_float(family_bucket.get("avg_spread_stability"), self.to_float(learning_summary.get("avg_spread_stability"), 0.0)) * 0.15
                    + self.to_float(reactivation_summary.get("best_reactivation_score"), self.to_float(adaptive_priority_summary.get("best_priority_score"), 0.0)) * 0.15
                    + self.to_float(adaptive_priority_summary.get("avg_priority_score"), 0.0) * 0.10
                ),
            ),
        )
        positive_reward = (
            min(1.0, self.to_float(learning_bucket.get("stable_edge_durability_count"), 0.0) / 5.0) * 0.20
            + min(1.0, self.to_float(learning_bucket.get("strong_survivability_count"), 0.0) / 5.0) * 0.20
            + min(1.0, self.to_float(learning_bucket.get("clean_orderbook_quality_count"), 0.0) / 5.0) * 0.15
            + min(1.0, self.to_float(learning_bucket.get("high_reactivation_count"), 0.0) / 5.0) * 0.15
            + min(1.0, self.to_float(learning_bucket.get("high_adaptive_priority_count"), 0.0) / 5.0) * 0.15
            + min(1.0, self.to_float(learning_bucket.get("edge_above_cost_count"), 0.0) / 5.0) * 0.15
        )
        rejection_penalty = (
            min(1.0, self.to_float(learning_bucket.get("unsafe_price_count"), 0.0) / 5.0) * 0.20
            + min(1.0, self.to_float(learning_bucket.get("edge_below_cost_count"), 0.0) / 5.0) * 0.18
            + min(1.0, self.to_float(learning_bucket.get("missing_quotes_count"), 0.0) / 5.0) * 0.18
            + min(1.0, self.to_float(learning_bucket.get("low_volume_count"), 0.0) / 5.0) * 0.14
            + min(1.0, self.to_float(learning_bucket.get("unstable_orderbook_count"), 0.0) / 5.0) * 0.10
            + min(1.0, self.to_float(learning_bucket.get("liquidity_block_count"), 0.0) / 5.0) * 0.10
            + min(1.0, self.to_float(learning_bucket.get("phase55_block_count"), 0.0) / 5.0) * 0.10
        )
        repetition_bonus = min(0.10, self.to_float(learning_bucket.get("improving_count"), 0.0) * 0.015)
        score = max(0.0, min(1.0, stable_microstructure * 0.45 + positive_reward * 0.35 + repetition_bonus - rejection_penalty))
        return round(score, 4)

    def _classify_candidate_learning_profile(self, *, learning_score=0.0, learning_bucket=None):
        learning_bucket = learning_bucket if isinstance(learning_bucket, dict) else {}
        avoid_pressure = (
            int(learning_bucket.get("unsafe_price_count", 0) or 0)
            + int(learning_bucket.get("edge_below_cost_count", 0) or 0)
            + int(learning_bucket.get("missing_quotes_count", 0) or 0)
            + int(learning_bucket.get("low_volume_count", 0) or 0)
            + int(learning_bucket.get("unstable_orderbook_count", 0) or 0)
        )
        improving_count = int(learning_bucket.get("improving_count", 0) or 0)
        strong_watch_count = int(learning_bucket.get("strong_watch_count", 0) or 0)
        if learning_score < 0.18 or avoid_pressure >= 6:
            return "avoid"
        if learning_score < 0.38 or avoid_pressure >= 3:
            return "weak"
        if learning_score < 0.58 or improving_count >= 2:
            return "improving"
        if learning_score < 0.80 or strong_watch_count == 0:
            return "promising"
        return "strong_watch"

    def _build_candidate_learning_family_summary(self, family=None):
        family = str(family or "UNKNOWN").strip().upper() or "UNKNOWN"
        ticker_container = getattr(self, "candidate_learning_by_ticker", {}) or {}
        family_buckets = []
        if isinstance(ticker_container, dict):
            for bucket in ticker_container.values():
                if not isinstance(bucket, dict):
                    continue
                if str(bucket.get("family") or "").strip().upper() == family:
                    family_buckets.append(bucket)
        family_bucket = self._get_candidate_learning_bucket("candidate_learning_by_family", f"family:{family}")
        if not family_buckets:
            summary = {
                "family": family,
                "observations": 0,
                "family_learning_score": round(self.to_float(family_bucket.get("learning_score"), 0.0) or 0.0, 4),
                "best_learning_ticker": None,
                "best_learning_score": 0.0,
                "worst_learning_ticker": None,
                "worst_learning_score": 0.0,
                "strongest_watch_count": int(family_bucket.get("strong_watch_count", 0) or 0),
                "avoid_count": int(family_bucket.get("avoid_count", 0) or 0),
                "improving_count": int(family_bucket.get("improving_count", 0) or 0),
                "candidate_learning_top_reason": str(family_bucket.get("candidate_learning_top_reason") or "insufficient_data"),
                "market_type": None,
            }
            family_bucket["last_summary"] = summary
            return summary
        best_bucket = max(
            family_buckets,
            key=lambda bucket: (
                self.to_float(bucket.get("learning_score"), 0.0),
                int(bucket.get("strong_watch_count", 0) or 0),
                int(bucket.get("promising_count", 0) or 0),
                int(bucket.get("positive_signal_count", 0) or 0),
            ),
        )
        worst_bucket = min(
            family_buckets,
            key=lambda bucket: (
                self.to_float(bucket.get("learning_score"), 0.0),
                -int(bucket.get("avoid_count", 0) or 0),
                -int(bucket.get("rejection_count", 0) or 0),
            ),
        )
        market_type_counts = Counter()
        rejection_reason_counts = Counter()
        for bucket in family_buckets:
            market_type_counts.update(bucket.get("market_type_counts") or {})
            rejection_reason_counts.update(bucket.get("rejection_reason_counts") or {})
        observations = sum(int(bucket.get("rejection_count", 0) or 0) + int(bucket.get("positive_signal_count", 0) or 0) for bucket in family_buckets)
        family_learning_score = sum(self.to_float(bucket.get("learning_score"), 0.0) or 0.0 for bucket in family_buckets) / max(len(family_buckets), 1)
        candidate_learning_top_reason = rejection_reason_counts.most_common(1)[0][0] if rejection_reason_counts else str(worst_bucket.get("learning_profile") or "none")
        summary = {
            "family": family,
            "observations": int(observations),
            "family_learning_score": round(family_learning_score, 4),
            "best_learning_ticker": str(best_bucket.get("ticker") or "").strip() or None,
            "best_learning_score": round(self.to_float(best_bucket.get("learning_score"), 0.0) or 0.0, 4),
            "worst_learning_ticker": str(worst_bucket.get("ticker") or "").strip() or None,
            "worst_learning_score": round(self.to_float(worst_bucket.get("learning_score"), 0.0) or 0.0, 4),
            "strongest_watch_count": int(sum(int(bucket.get("strong_watch_count", 0) or 0) for bucket in family_buckets)),
            "avoid_count": int(sum(int(bucket.get("avoid_count", 0) or 0) for bucket in family_buckets)),
            "improving_count": int(sum(int(bucket.get("improving_count", 0) or 0) for bucket in family_buckets)),
            "candidate_learning_top_reason": candidate_learning_top_reason,
            "market_type": market_type_counts.most_common(1)[0][0] if market_type_counts else None,
        }
        family_bucket["last_summary"] = summary
        family_bucket["learning_score"] = summary["family_learning_score"]
        family_bucket["candidate_learning_top_reason"] = summary["candidate_learning_top_reason"]
        return summary

    def _build_candidate_learning_overall_summary(self):
        ticker_container = getattr(self, "candidate_learning_by_ticker", {}) or {}
        family_container = getattr(self, "candidate_learning_by_family", {}) or {}
        ticker_buckets = [bucket for bucket in ticker_container.values() if isinstance(bucket, dict)]
        family_buckets = [bucket for bucket in family_container.values() if isinstance(bucket, dict)]
        if not ticker_buckets:
            return {
                "scope": "overall",
                "candidate_count": 0,
                "family_count": 0,
                "best_learning_family": None,
                "worst_learning_family": None,
                "best_learning_ticker": None,
                "best_learning_score": 0.0,
                "worst_learning_score": 0.0,
                "strongest_watch_count": 0,
                "avoid_count": 0,
                "improving_count": 0,
            }
        best_bucket = max(
            ticker_buckets,
            key=lambda bucket: (
                self.to_float(bucket.get("learning_score"), 0.0),
                int(bucket.get("strong_watch_count", 0) or 0),
                int(bucket.get("positive_signal_count", 0) or 0),
            ),
        )
        worst_bucket = min(
            ticker_buckets,
            key=lambda bucket: (
                self.to_float(bucket.get("learning_score"), 0.0),
                -int(bucket.get("avoid_count", 0) or 0),
                -int(bucket.get("rejection_count", 0) or 0),
            ),
        )
        family_scores = []
        for bucket in family_buckets:
            family_scores.append((self.to_float(bucket.get("learning_score"), 0.0), bucket))
        best_family = max(family_scores, key=lambda item: item[0])[1] if family_scores else None
        worst_family = min(family_scores, key=lambda item: item[0])[1] if family_scores else None
        strongest_watch_count = sum(1 for bucket in ticker_buckets if str(bucket.get("learning_profile") or "").strip().lower() == "strong_watch")
        avoid_count = sum(1 for bucket in ticker_buckets if str(bucket.get("learning_profile") or "").strip().lower() == "avoid")
        improving_count = sum(1 for bucket in ticker_buckets if str(bucket.get("learning_profile") or "").strip().lower() == "improving")
        return {
            "scope": "overall",
            "candidate_count": int(len(ticker_buckets)),
            "family_count": int(len(family_buckets)),
            "best_learning_family": str(best_family.get("family") or "").strip() if isinstance(best_family, dict) else None,
            "worst_learning_family": str(worst_family.get("family") or "").strip() if isinstance(worst_family, dict) else None,
            "best_learning_ticker": str(best_bucket.get("ticker") or "").strip() or None,
            "best_learning_score": round(self.to_float(best_bucket.get("learning_score"), 0.0) or 0.0, 4),
            "worst_learning_score": round(self.to_float(worst_bucket.get("learning_score"), 0.0) or 0.0, 4),
            "strongest_watch_count": int(strongest_watch_count),
            "avoid_count": int(avoid_count),
            "improving_count": int(improving_count),
        }

    def _emit_candidate_learning_telemetry(self, *, ticker_bucket=None, family_bucket=None, force=False):
        ticker_bucket = ticker_bucket if isinstance(ticker_bucket, dict) else {}
        family_bucket = family_bucket if isinstance(family_bucket, dict) else {}
        ticker = str(ticker_bucket.get("ticker") or "").strip()
        family = str(family_bucket.get("family") or ticker_bucket.get("family") or "").strip().upper() or "UNKNOWN"
        now = time.time()
        summary = ticker_bucket.get("last_summary") if isinstance(ticker_bucket.get("last_summary"), dict) else {}
        if not summary:
            summary = {
                "ticker": ticker or "unknown",
                "family": family,
                "market_type": ticker_bucket.get("market_type"),
                "learning_score": round(self.to_float(ticker_bucket.get("learning_score"), 0.0) or 0.0, 4),
                "learning_profile": str(ticker_bucket.get("learning_profile") or "weak").strip().lower(),
                "avoid_count": int(ticker_bucket.get("avoid_count", 0) or 0),
                "improving_count": int(ticker_bucket.get("improving_count", 0) or 0),
                "strong_watch_count": int(ticker_bucket.get("strong_watch_count", 0) or 0),
            }
        emit_key = ticker or family
        last_emit = float(getattr(self, "candidate_learning_last_signal_ts_by_key", {}).get(emit_key, 0.0) or 0.0)
        if not force and ticker and (now - last_emit) < 120.0:
            return None
        if ticker:
            self.candidate_learning_last_signal_ts_by_key[ticker] = now
        if family:
            self.candidate_learning_last_signal_ts_by_key[family] = now
        print("[LIVE-REJECTION-LEARNING] " + json.dumps(summary.get("rejection_learning", {}), sort_keys=True, default=str))
        print("[LIVE-POSITIVE-SIGNAL-MEMORY] " + json.dumps(summary.get("positive_signal_memory", {}), sort_keys=True, default=str))
        print("[LIVE-FAMILY-LEARNING-SCORE] " + json.dumps(family_bucket.get("last_summary") or self._build_candidate_learning_family_summary(family=family), sort_keys=True, default=str))
        print("[LIVE-CANDIDATE-LEARNING-PROFILE] " + json.dumps(summary, sort_keys=True, default=str))
        self.last_candidate_learning_summary = summary
        self.last_candidate_learning_family_summary = family_bucket.get("last_summary") or {}
        self.last_candidate_learning_overall_summary = self._build_candidate_learning_overall_summary()
        return summary

    def _get_predictive_regime_bucket(self, container_name, key):
        buckets = getattr(self, container_name, None)
        if not isinstance(buckets, dict):
            buckets = {}
            setattr(self, container_name, buckets)
        bucket = buckets.setdefault(
            key,
            {
                "first_seen_time": None,
                "last_seen_time": 0.0,
                "ticker": None,
                "family": None,
                "market_type": None,
                "previous_regime_state": None,
                "latest_regime_state": "unstable",
                "best_predictive_regime_score": 0.0,
                "predictive_regime_score": 0.0,
                "improving_count": 0,
                "decaying_count": 0,
                "transition_counts": Counter(),
                "score_history": deque(maxlen=24),
                "state_history": deque(maxlen=24),
                "transition_history": deque(maxlen=24),
                "last_summary": {},
            },
        )
        return bucket

    def _classify_predictive_regime_state(self, *, predictive_regime_score=0.0, improvement_signal=0.0, decay_signal=0.0, previous_regime_state=None, current_pressure=None):
        previous_regime_state = str(previous_regime_state or "").strip().lower()
        current_pressure = str(current_pressure or "neutral").strip().lower()
        score = self._clamp(self.to_float(predictive_regime_score, 0.0))
        improvement_signal = self._clamp(self.to_float(improvement_signal, 0.0))
        decay_signal = self._clamp(self.to_float(decay_signal, 0.0))
        if score < 0.24 or decay_signal >= 0.72 or current_pressure in {"collapse", "breaking_down"}:
            return "unstable", ["predictive_regime_unstable"]
        if score < 0.38 or decay_signal >= 0.58:
            return "weak", ["predictive_regime_weak"]
        if score < 0.52 or improvement_signal >= 0.50 or previous_regime_state == "unstable":
            return "stabilizing", ["predictive_regime_stabilizing"]
        if score < 0.72 or improvement_signal >= 0.62:
            return "improving", ["predictive_regime_improving"]
        if score < 0.88:
            return "stable", ["predictive_regime_stable"]
        return "high_quality", ["predictive_regime_high_quality"]

    def _compute_predictive_regime_score(
        self,
        *,
        predictive_profile=None,
        microstructure_summary=None,
        family_microstructure_summary=None,
        reactivation_summary=None,
        adaptive_priority_summary=None,
        learning_summary=None,
        family_learning_summary=None,
        ticker_bucket=None,
        family_bucket=None,
    ):
        predictive_profile = predictive_profile if isinstance(predictive_profile, dict) else {}
        microstructure_summary = microstructure_summary if isinstance(microstructure_summary, dict) else {}
        family_microstructure_summary = family_microstructure_summary if isinstance(family_microstructure_summary, dict) else {}
        reactivation_summary = reactivation_summary if isinstance(reactivation_summary, dict) else {}
        adaptive_priority_summary = adaptive_priority_summary if isinstance(adaptive_priority_summary, dict) else {}
        learning_summary = learning_summary if isinstance(learning_summary, dict) else {}
        family_learning_summary = family_learning_summary if isinstance(family_learning_summary, dict) else {}
        ticker_bucket = ticker_bucket if isinstance(ticker_bucket, dict) else {}
        family_bucket = family_bucket if isinstance(family_bucket, dict) else {}

        predictive_score = self._clamp(self.to_float(predictive_profile.get("predictive_score"), 0.0))
        execution_survivability_score = self._clamp(
            self.to_float(microstructure_summary.get("execution_survivability_score"), self.to_float(family_microstructure_summary.get("avg_survivability"), 0.0))
        )
        edge_durability_score = self._clamp(
            self.to_float(microstructure_summary.get("edge_stability_score", microstructure_summary.get("edge_durability_score")), self.to_float(family_microstructure_summary.get("avg_edge_durability"), 0.0))
        )
        quote_lifetime_seconds = self.to_float(microstructure_summary.get("quote_lifetime_seconds"), 0.0) or 0.0
        spread_lifetime_seconds = self.to_float(microstructure_summary.get("spread_lifetime_seconds"), 0.0) or 0.0
        quote_lifetime_score = self._clamp(min(1.0, quote_lifetime_seconds / 240.0))
        spread_lifetime_score = self._clamp(min(1.0, spread_lifetime_seconds / 240.0))
        family_microstructure_score = self._clamp(
            (
                self.to_float(family_microstructure_summary.get("avg_survivability"), 0.0) * 0.35
                + self.to_float(family_microstructure_summary.get("avg_edge_durability"), 0.0) * 0.25
                + self.to_float(family_microstructure_summary.get("avg_spread_stability"), 0.0) * 0.20
                + self.to_float(family_microstructure_summary.get("liquidity_reliability"), 0.0) * 0.20
            )
        )
        reactivation_score = self._clamp(self.to_float(reactivation_summary.get("reactivation_score"), 0.0))
        adaptive_priority_score = self._clamp(self.to_float(adaptive_priority_summary.get("adaptive_priority_score"), 0.0))
        family_learning_score = self._clamp(self.to_float(family_learning_summary.get("family_learning_score"), 0.0))
        learning_score = self._clamp(self.to_float(learning_summary.get("learning_score"), 0.0))

        spread_tightening_velocity = self._clamp(
            max(
                0.0,
                min(
                    1.0,
                    self.to_float(microstructure_summary.get("spread_stability_score"), 0.0) * 0.7
                    + max(0.0, 1.0 - min(self.to_float(microstructure_summary.get("spread_change_count"), 0.0) / max(int(microstructure_summary.get("repeat_count", 0) or 1), 1), 1.0)) * 0.3,
                ),
            )
        )
        quote_stability_trend = self._clamp(
            max(
                0.0,
                min(
                    1.0,
                    quote_lifetime_score * 0.6
                    + max(0.0, 1.0 - min(self.to_float(microstructure_summary.get("quote_churn_count"), 0.0) / max(int(microstructure_summary.get("repeat_count", 0) or 1), 1), 1.0)) * 0.4,
                ),
            )
        )
        orderbook_consistency_trend = self._clamp(
            max(
                0.0,
                min(
                    1.0,
                    self.to_float(microstructure_summary.get("liquidity_reliability_score"), 0.0) * 0.55
                    + max(0.0, 1.0 - self.to_float(microstructure_summary.get("unstable_rate"), 0.0)) * 0.20
                    + max(0.0, 1.0 - self.to_float(microstructure_summary.get("fake_liquidity_rate"), 0.0)) * 0.15
                    + max(0.0, 1.0 - self.to_float(microstructure_summary.get("quote_withdrawal_rate"), 0.0)) * 0.10,
                ),
            )
        )
        rejection_sources = [
            self.to_float(learning_summary.get("unsafe_price_count"), 0.0),
            self.to_float(learning_summary.get("edge_below_cost_count"), 0.0),
            self.to_float(learning_summary.get("low_volume_count"), 0.0),
            self.to_float(learning_summary.get("missing_quotes_count"), 0.0),
            self.to_float(learning_summary.get("unstable_orderbook_count"), 0.0),
            self.to_float(learning_summary.get("phase55_block_count"), 0.0),
            self.to_float(learning_summary.get("liquidity_block_count"), 0.0),
        ]
        reject_reason_total = sum(float(value or 0.0) for value in rejection_sources)
        reject_reason_unique = sum(1 for value in rejection_sources if float(value or 0.0) > 0.0)
        rejection_volatility = self._clamp(min(1.0, (reject_reason_unique / 6.0) * 0.6 + (min(reject_reason_total, 8) / 8.0) * 0.4))
        edge_durability_trend = self._clamp(
            max(
                0.0,
                min(
                    1.0,
                    edge_durability_score * 0.55
                    + max(0.0, 1.0 - min(self.to_float(microstructure_summary.get("edge_collapse_count"), 0.0) / max(int(microstructure_summary.get("repeat_count", 0) or 1), 1), 1.0)) * 0.45,
                ),
            )
        )
        momentum_direction = str(predictive_profile.get("momentum_direction") or "unknown").strip().lower()
        momentum_strength = str(predictive_profile.get("momentum_strength") or "unknown").strip().lower()
        momentum_consistency = self._clamp(
            max(
                0.0,
                min(
                    1.0,
                    (0.75 if momentum_direction in {"up", "down"} else 0.35)
                    + (0.20 if momentum_strength == "strong" else 0.10 if momentum_strength == "moderate" else 0.0)
                    + max(0.0, 1.0 - rejection_volatility) * 0.05,
                ),
            )
        )
        family_learning_trend = self._clamp(
            max(
                0.0,
                min(
                    1.0,
                    family_learning_score * 0.60
                    + max(0.0, 1.0 - min(self.to_float(family_learning_summary.get("avoid_count"), 0.0) / max(self.to_float(family_learning_summary.get("observations"), 1.0), 1.0), 1.0)) * 0.20
                    + max(0.0, 1.0 - rejection_volatility) * 0.20,
                ),
            )
        )
        adaptive_priority_trend = self._clamp(
            max(
                0.0,
                min(
                    1.0,
                    adaptive_priority_score * 0.65
                    + max(0.0, 1.0 - rejection_volatility) * 0.35,
                ),
            )
        )
        positive_trend_components = [
            spread_tightening_velocity,
            quote_stability_trend,
            orderbook_consistency_trend,
            edge_durability_trend,
            momentum_consistency,
            family_learning_trend,
            adaptive_priority_trend,
            reactivation_score,
            learning_score,
        ]
        decay_signal = self._clamp(max(0.0, 1.0 - min(spread_tightening_velocity, quote_stability_trend, orderbook_consistency_trend, edge_durability_trend, momentum_consistency)))
        improvement_signal = self._clamp(sum(positive_trend_components) / max(len(positive_trend_components), 1))
        base_component = (
            predictive_score * 0.16
            + execution_survivability_score * 0.16
            + edge_durability_score * 0.14
            + quote_lifetime_score * 0.10
            + spread_lifetime_score * 0.10
            + family_microstructure_score * 0.10
            + reactivation_score * 0.08
            + adaptive_priority_score * 0.08
            + family_learning_score * 0.04
            + learning_score * 0.04
        )
        trend_component = (
            spread_tightening_velocity * 0.14
            + quote_stability_trend * 0.14
            + orderbook_consistency_trend * 0.14
            + edge_durability_trend * 0.14
            + momentum_consistency * 0.14
            + family_learning_trend * 0.14
            + adaptive_priority_trend * 0.14
            + max(0.0, 1.0 - rejection_volatility) * 0.02
        )
        previous_score = self.to_float(ticker_bucket.get("predictive_regime_score"), None)
        if previous_score is None:
            previous_score = self.to_float(ticker_bucket.get("best_predictive_regime_score"), 0.0)
        score_delta = max(-0.25, min(0.25, self.to_float(predictive_score, 0.0) - self.to_float(previous_score, 0.0)))
        combined = self._clamp(base_component * 0.52 + trend_component * 0.38 + (score_delta + 0.25) * 0.10)
        return {
            "predictive_regime_score": round(combined, 4),
            "spread_tightening_velocity": round(spread_tightening_velocity, 4),
            "quote_stability_trend": round(quote_stability_trend, 4),
            "orderbook_consistency_trend": round(orderbook_consistency_trend, 4),
            "rejection_volatility": round(rejection_volatility, 4),
            "edge_durability_trend": round(edge_durability_trend, 4),
            "momentum_consistency": round(momentum_consistency, 4),
            "family_learning_trend": round(family_learning_trend, 4),
            "adaptive_priority_trend": round(adaptive_priority_trend, 4),
            "improvement_signal": round(improvement_signal, 4),
            "decay_signal": round(decay_signal, 4),
            "predictive_score": round(predictive_score, 4),
            "execution_survivability_score": round(execution_survivability_score, 4),
            "edge_durability_score": round(edge_durability_score, 4),
            "quote_lifetime_score": round(quote_lifetime_score, 4),
            "spread_lifetime_score": round(spread_lifetime_score, 4),
            "family_microstructure_score": round(family_microstructure_score, 4),
            "reactivation_score": round(reactivation_score, 4),
            "adaptive_priority_score": round(adaptive_priority_score, 4),
            "family_learning_score": round(family_learning_score, 4),
            "learning_score": round(learning_score, 4),
            "score_delta": round(score_delta, 4),
        }

    def _update_predictive_regime_memory(
        self,
        *,
        market=None,
        q=None,
        family=None,
        predictive_profile=None,
        microstructure_summary=None,
        family_microstructure_summary=None,
        reactivation_summary=None,
        adaptive_priority_summary=None,
        learning_summary=None,
        family_learning_summary=None,
    ):
        market = market if isinstance(market, dict) else {}
        predictive_profile = predictive_profile if isinstance(predictive_profile, dict) else {}
        microstructure_summary = microstructure_summary if isinstance(microstructure_summary, dict) else {}
        family_microstructure_summary = family_microstructure_summary if isinstance(family_microstructure_summary, dict) else {}
        reactivation_summary = reactivation_summary if isinstance(reactivation_summary, dict) else {}
        adaptive_priority_summary = adaptive_priority_summary if isinstance(adaptive_priority_summary, dict) else {}
        learning_summary = learning_summary if isinstance(learning_summary, dict) else {}
        family_learning_summary = family_learning_summary if isinstance(family_learning_summary, dict) else {}
        ticker = str(
            predictive_profile.get("ticker")
            or getattr(q, "ticker", None)
            or market.get("ticker")
            or ""
        ).strip()
        if not ticker:
            return None
        family = str(
            family
            or predictive_profile.get("family")
            or adaptive_priority_summary.get("family")
            or family_microstructure_summary.get("family")
            or self.get_market_family(market or {})
            or "UNKNOWN"
        ).strip().upper() or "UNKNOWN"
        market_type = str(
            predictive_profile.get("category")
            or market.get("category")
            or market.get("market_category")
            or self.get_market_discovery_category(market or {})
            or "unknown"
        ).strip().lower() or "unknown"
        ticker_bucket = self._get_predictive_regime_bucket("predictive_regime_by_ticker", f"ticker:{ticker}")
        family_bucket = self._get_predictive_regime_bucket("predictive_regime_by_family", f"family:{family}")
        now = time.time()
        score_payload = self._compute_predictive_regime_score(
            predictive_profile=predictive_profile,
            microstructure_summary=microstructure_summary,
            family_microstructure_summary=family_microstructure_summary,
            reactivation_summary=reactivation_summary,
            adaptive_priority_summary=adaptive_priority_summary,
            learning_summary=learning_summary,
            family_learning_summary=family_learning_summary,
            ticker_bucket=ticker_bucket,
            family_bucket=family_bucket,
        )
        previous_state = str(ticker_bucket.get("latest_regime_state") or "unstable").strip().lower()
        previous_score = self.to_float(ticker_bucket.get("predictive_regime_score"), 0.0)
        latest_state, state_reasons = self._classify_predictive_regime_state(
            predictive_regime_score=score_payload.get("predictive_regime_score", 0.0),
            improvement_signal=score_payload.get("improvement_signal", 0.0),
            decay_signal=score_payload.get("decay_signal", 0.0),
            previous_regime_state=previous_state,
            current_pressure=microstructure_summary.get("pressure_direction") or "neutral",
        )
        transition = f"{previous_state}->{latest_state}" if previous_state and previous_state != latest_state else previous_state
        if previous_state != latest_state:
            ticker_bucket["transition_counts"][transition] += 1
        if latest_state in {"stabilizing", "improving", "stable", "high_quality"}:
            ticker_bucket["improving_count"] = int(ticker_bucket.get("improving_count", 0) or 0) + 1
        if latest_state in {"unstable", "weak"}:
            ticker_bucket["decaying_count"] = int(ticker_bucket.get("decaying_count", 0) or 0) + 1
        ticker_bucket["first_seen_time"] = ticker_bucket.get("first_seen_time") or now
        ticker_bucket["last_seen_time"] = now
        ticker_bucket["ticker"] = ticker
        ticker_bucket["family"] = family
        ticker_bucket["market_type"] = market_type
        ticker_bucket["previous_regime_state"] = previous_state
        ticker_bucket["latest_regime_state"] = latest_state
        ticker_bucket["predictive_regime_score"] = score_payload.get("predictive_regime_score", 0.0)
        ticker_bucket["best_predictive_regime_score"] = max(
            self.to_float(ticker_bucket.get("best_predictive_regime_score"), 0.0) or 0.0,
            score_payload.get("predictive_regime_score", 0.0) or 0.0,
        )
        ticker_bucket.setdefault("score_history", deque(maxlen=24)).append(score_payload.get("predictive_regime_score", 0.0))
        ticker_bucket.setdefault("state_history", deque(maxlen=24)).append(latest_state)
        ticker_bucket.setdefault("transition_history", deque(maxlen=24)).append(transition)
        ticker_bucket["regime_transition"] = transition
        ticker_bucket["top_transition"] = ticker_bucket.get("top_transition") or transition
        ticker_bucket["last_summary"] = {
            "ticker": ticker,
            "family": family,
            "market_type": market_type,
            "previous_regime_state": previous_state,
            "latest_regime_state": latest_state,
            "regime_transition": transition,
            "predictive_regime_score": round(score_payload.get("predictive_regime_score", 0.0), 4),
            "best_predictive_regime_score": round(self.to_float(ticker_bucket.get("best_predictive_regime_score"), 0.0) or 0.0, 4),
            "score_delta": round(score_payload.get("predictive_regime_score", 0.0) - previous_score, 4),
            "spread_tightening_velocity": score_payload.get("spread_tightening_velocity"),
            "quote_stability_trend": score_payload.get("quote_stability_trend"),
            "orderbook_consistency_trend": score_payload.get("orderbook_consistency_trend"),
            "rejection_volatility": score_payload.get("rejection_volatility"),
            "edge_durability_trend": score_payload.get("edge_durability_trend"),
            "momentum_consistency": score_payload.get("momentum_consistency"),
            "family_learning_trend": score_payload.get("family_learning_trend"),
            "adaptive_priority_trend": score_payload.get("adaptive_priority_trend"),
            "improvement_signal": score_payload.get("improvement_signal"),
            "decay_signal": score_payload.get("decay_signal"),
            "state_reasons": state_reasons,
            "top_transition": ticker_bucket.get("top_transition") or transition,
        }
        family_bucket["first_seen_time"] = family_bucket.get("first_seen_time") or now
        family_bucket["last_seen_time"] = now
        family_bucket["ticker"] = ticker
        family_bucket["family"] = family
        family_bucket["market_type"] = market_type
        family_bucket["transition_counts"][transition] += 1
        family_bucket["best_predictive_regime_score"] = max(
            self.to_float(family_bucket.get("best_predictive_regime_score"), 0.0) or 0.0,
            score_payload.get("predictive_regime_score", 0.0) or 0.0,
        )
        if latest_state in {"stabilizing", "improving", "stable", "high_quality"}:
            family_bucket["improving_count"] = int(family_bucket.get("improving_count", 0) or 0) + 1
        if latest_state in {"unstable", "weak"}:
            family_bucket["decaying_count"] = int(family_bucket.get("decaying_count", 0) or 0) + 1
        family_bucket.setdefault("score_history", deque(maxlen=24)).append(score_payload.get("predictive_regime_score", 0.0))
        family_bucket.setdefault("state_history", deque(maxlen=24)).append(latest_state)
        family_bucket.setdefault("transition_history", deque(maxlen=24)).append(transition)
        family_bucket["top_transition"] = transition
        summary = dict(ticker_bucket["last_summary"] or {})
        family_summary = self._build_predictive_regime_family_summary(family=family)
        family_bucket["last_summary"] = family_summary
        self.last_predictive_regime_summary = summary
        self.last_predictive_regime_family_summary = family_summary
        self.last_predictive_regime_overall_summary = self._build_predictive_regime_overall_summary()
        self._emit_predictive_regime_telemetry(ticker_bucket=ticker_bucket, family_bucket=family_bucket, force=False)
        return summary

    def _build_predictive_regime_family_summary(self, family=None):
        family = str(family or "UNKNOWN").strip().upper() or "UNKNOWN"
        ticker_container = getattr(self, "predictive_regime_by_ticker", {}) or {}
        family_buckets = []
        if isinstance(ticker_container, dict):
            for bucket in ticker_container.values():
                if not isinstance(bucket, dict):
                    continue
                if str(bucket.get("family") or "").strip().upper() == family:
                    family_buckets.append(bucket)
        family_bucket = self._get_predictive_regime_bucket("predictive_regime_by_family", f"family:{family}")
        if not family_buckets:
            summary = {
                "family": family,
                "candidate_count": 0,
                "family_predictive_score": round(self.to_float(family_bucket.get("predictive_regime_score"), 0.0) or 0.0, 4),
                "strongest_predictive_ticker": None,
                "strongest_predictive_score": 0.0,
                "top_transition": str(family_bucket.get("top_transition") or "none"),
                "improving_regime_count": int(family_bucket.get("improving_count", 0) or 0),
                "decaying_regime_count": int(family_bucket.get("decaying_count", 0) or 0),
                "regime_counts": {},
                "top_blocker": "insufficient_data",
            }
            family_bucket["last_summary"] = summary
            return summary
        best_bucket = max(
            family_buckets,
            key=lambda bucket: (
                self.to_float(bucket.get("predictive_regime_score"), 0.0),
                self.to_float(bucket.get("best_predictive_regime_score"), 0.0),
                int(bucket.get("improving_count", 0) or 0),
            ),
        )
        regime_counts = Counter()
        transition_counts = Counter()
        improving_count = 0
        decaying_count = 0
        for bucket in family_buckets:
            regime_counts[str(bucket.get("latest_regime_state") or "unstable").strip().lower()] += 1
            transition_counts.update(bucket.get("transition_counts") or {})
            improving_count += int(bucket.get("improving_count", 0) or 0)
            decaying_count += int(bucket.get("decaying_count", 0) or 0)
        family_predictive_score = sum(self.to_float(bucket.get("predictive_regime_score"), 0.0) or 0.0 for bucket in family_buckets) / max(len(family_buckets), 1)
        top_transition = transition_counts.most_common(1)[0][0] if transition_counts else str(family_bucket.get("top_transition") or "none")
        summary = {
            "family": family,
            "candidate_count": int(len(family_buckets)),
            "family_predictive_score": round(family_predictive_score, 4),
            "strongest_predictive_ticker": str(best_bucket.get("ticker") or "").strip() or None,
            "strongest_predictive_score": round(self.to_float(best_bucket.get("predictive_regime_score"), 0.0) or 0.0, 4),
            "top_transition": top_transition,
            "improving_regime_count": int(improving_count),
            "decaying_regime_count": int(decaying_count),
            "regime_counts": dict(regime_counts),
            "top_blocker": str(family_bucket.get("top_blocker") or "none"),
        }
        family_bucket["last_summary"] = summary
        family_bucket["predictive_regime_score"] = summary["family_predictive_score"]
        family_bucket["top_transition"] = summary["top_transition"]
        return summary

    def _build_predictive_regime_overall_summary(self):
        ticker_container = getattr(self, "predictive_regime_by_ticker", {}) or {}
        family_container = getattr(self, "predictive_regime_by_family", {}) or {}
        ticker_buckets = [bucket for bucket in ticker_container.values() if isinstance(bucket, dict)]
        family_buckets = [bucket for bucket in family_container.values() if isinstance(bucket, dict)]
        if not ticker_buckets:
            return {
                "scope": "overall",
                "candidate_count": 0,
                "family_count": 0,
                "strongest_predictive_family": None,
                "strongest_predictive_ticker": None,
                "top_predictive_score": 0.0,
                "top_transition": "none",
                "improving_regime_count": 0,
                "decaying_regime_count": 0,
            }
        best_bucket = max(
            ticker_buckets,
            key=lambda bucket: (
                self.to_float(bucket.get("predictive_regime_score"), 0.0),
                self.to_float(bucket.get("best_predictive_regime_score"), 0.0),
                int(bucket.get("improving_count", 0) or 0),
            ),
        )
        regime_counts = Counter()
        transition_counts = Counter()
        improving_count = 0
        decaying_count = 0
        for bucket in ticker_buckets:
            regime_counts[str(bucket.get("latest_regime_state") or "unstable").strip().lower()] += 1
            transition_counts.update(bucket.get("transition_counts") or {})
            improving_count += int(bucket.get("improving_count", 0) or 0)
            decaying_count += int(bucket.get("decaying_count", 0) or 0)
        strongest_family = None
        if family_buckets:
            strongest_family_bucket = max(
                family_buckets,
                key=lambda bucket: (
                    self.to_float(bucket.get("predictive_regime_score"), 0.0),
                    self.to_float(bucket.get("strongest_predictive_score"), 0.0),
                ),
            )
            strongest_family = str(strongest_family_bucket.get("family") or "").strip() or None
        top_transition = transition_counts.most_common(1)[0][0] if transition_counts else "none"
        return {
            "scope": "overall",
            "candidate_count": int(len(ticker_buckets)),
            "family_count": int(len(family_buckets)),
            "strongest_predictive_family": strongest_family,
            "strongest_predictive_ticker": str(best_bucket.get("ticker") or "").strip() or None,
            "top_predictive_score": round(self.to_float(best_bucket.get("predictive_regime_score"), 0.0) or 0.0, 4),
            "top_transition": top_transition,
            "improving_regime_count": int(improving_count),
            "decaying_regime_count": int(decaying_count),
            "regime_counts": dict(regime_counts),
        }

    def _emit_predictive_regime_telemetry(self, *, ticker_bucket=None, family_bucket=None, force=False):
        ticker_bucket = ticker_bucket if isinstance(ticker_bucket, dict) else {}
        family_bucket = family_bucket if isinstance(family_bucket, dict) else {}
        ticker = str(ticker_bucket.get("ticker") or "").strip()
        family = str(family_bucket.get("family") or ticker_bucket.get("family") or "").strip().upper() or "UNKNOWN"
        now = time.time()
        summary = ticker_bucket.get("last_summary") if isinstance(ticker_bucket.get("last_summary"), dict) else {}
        if not summary:
            summary = {
                "ticker": ticker or "unknown",
                "family": family,
                "market_type": ticker_bucket.get("market_type"),
                "previous_regime_state": ticker_bucket.get("previous_regime_state"),
                "latest_regime_state": ticker_bucket.get("latest_regime_state"),
                "predictive_regime_score": round(self.to_float(ticker_bucket.get("predictive_regime_score"), 0.0) or 0.0, 4),
                "top_transition": ticker_bucket.get("top_transition") or "none",
            }
        emit_key = ticker or family
        last_emit = float(getattr(self, "predictive_regime_last_signal_ts_by_key", {}).get(emit_key, 0.0) or 0.0)
        if not force and ticker and (now - last_emit) < 120.0:
            return None
        if ticker:
            self.predictive_regime_last_signal_ts_by_key[ticker] = now
        if family:
            self.predictive_regime_last_signal_ts_by_key[family] = now
        transition_payload = {
            "ticker": summary.get("ticker"),
            "family": summary.get("family"),
            "previous_regime_state": summary.get("previous_regime_state"),
            "latest_regime_state": summary.get("latest_regime_state"),
            "transition": summary.get("regime_transition") or summary.get("transition"),
            "score_delta": summary.get("score_delta"),
            "predictive_regime_score": summary.get("predictive_regime_score"),
            "improvement_signal": summary.get("improvement_signal"),
            "decay_signal": summary.get("decay_signal"),
        }
        print("[LIVE-REGIME-TRANSITION] " + json.dumps(transition_payload, sort_keys=True, default=str))
        print("[LIVE-PREDICTIVE-REGIME-SCORE] " + json.dumps(summary, sort_keys=True, default=str))
        early_payload = {
            "ticker": summary.get("ticker"),
            "family": summary.get("family"),
            "latest_regime_state": summary.get("latest_regime_state"),
            "predictive_regime_score": summary.get("predictive_regime_score"),
            "improvement_signal": summary.get("improvement_signal"),
            "signals": [],
        }
        if str(summary.get("latest_regime_state") or "").strip().lower() in {"stabilizing", "improving"} and self.to_float(summary.get("predictive_regime_score"), 0.0) < 0.75:
            early_payload["signals"].append("improving_but_not_qualified")
        if self.to_float(summary.get("predictive_regime_score"), 0.0) < 0.55 and self.to_float(summary.get("improvement_signal"), 0.0) >= 0.45:
            early_payload["signals"].append("stabilizing_but_below_cost")
        if self.to_float(summary.get("edge_durability_trend"), 0.0) >= 0.55:
            early_payload["signals"].append("edge_forming")
        if self.to_float(summary.get("quote_stability_trend"), 0.0) >= 0.55 or self.to_float(summary.get("orderbook_consistency_trend"), 0.0) >= 0.55:
            early_payload["signals"].append("recovering_liquidity")
            early_payload["signals"].append("recovering_orderbook_quality")
        if early_payload["signals"]:
            print("[LIVE-EARLY-IMPROVEMENT] " + json.dumps(early_payload, sort_keys=True, default=str))
        decay_payload = {
            "ticker": summary.get("ticker"),
            "family": summary.get("family"),
            "latest_regime_state": summary.get("latest_regime_state"),
            "predictive_regime_score": summary.get("predictive_regime_score"),
            "signals": [],
        }
        if self.to_float(summary.get("spread_tightening_velocity"), 0.0) < 0.35:
            decay_payload["signals"].append("worsening_spread")
        if self.to_float(summary.get("quote_stability_trend"), 0.0) < 0.35:
            decay_payload["signals"].append("quote_collapse")
        if self.to_float(summary.get("orderbook_consistency_trend"), 0.0) < 0.40:
            decay_payload["signals"].append("unstable_orderbook")
        if self.to_float(summary.get("edge_durability_trend"), 0.0) < 0.40:
            decay_payload["signals"].append("weakening_edge_durability")
        if self.to_float(summary.get("momentum_consistency"), 0.0) < 0.40:
            decay_payload["signals"].append("momentum_decay")
        if decay_payload["signals"]:
            print("[LIVE-REGIME-DECAY] " + json.dumps(decay_payload, sort_keys=True, default=str))
        family_summary = self._build_predictive_regime_family_summary(family=family)
        family_bucket["last_summary"] = family_summary
        self.last_predictive_regime_summary = dict(summary)
        self.last_predictive_regime_family_summary = dict(family_summary or {})
        self.last_predictive_regime_overall_summary = self._build_predictive_regime_overall_summary()
        print("[LIVE-PREDICTIVE-DASHBOARD] " + json.dumps(self.last_predictive_regime_overall_summary, sort_keys=True, default=str))
        return summary

    def _update_candidate_learning_memory(self, *, market=None, q=None, family=None, audit=None, decision=None, decision_reason=None, shadow_arb_validation=None, reactivation_summary=None, adaptive_priority_summary=None, family_microstructure_summary=None, count_rejections=True):
        market = market if isinstance(market, dict) else {}
        audit = audit if isinstance(audit, dict) else {}
        shadow_arb_validation = shadow_arb_validation if isinstance(shadow_arb_validation, dict) else {}
        reactivation_summary = reactivation_summary if isinstance(reactivation_summary, dict) else {}
        adaptive_priority_summary = adaptive_priority_summary if isinstance(adaptive_priority_summary, dict) else {}
        family_microstructure_summary = family_microstructure_summary if isinstance(family_microstructure_summary, dict) else {}
        ticker = str(audit.get("ticker") or getattr(q, "ticker", None) or market.get("ticker") or "").strip()
        if not ticker:
            return None
        family = str(family or audit.get("family") or self.get_market_family(market or {}) or getattr(q, "family", None) or "UNKNOWN").strip().upper() or "UNKNOWN"
        market_type = str(
            market.get("category")
            or market.get("market_category")
            or market.get("event_category")
            or self.get_market_discovery_category(market or {})
            or "unknown"
        ).strip().lower() or "unknown"
        learning_bucket = self._get_candidate_learning_bucket("candidate_learning_by_ticker", f"ticker:{ticker}")
        family_learning_bucket = self._get_candidate_learning_bucket("candidate_learning_by_family", f"family:{family}")
        market_learning_bucket = self._get_candidate_learning_bucket("candidate_learning_by_market_type", f"market_type:{market_type}")
        now = time.time()
        rejection_reason = str(audit.get("reject_reason") or decision_reason or shadow_arb_validation.get("reject_reason") or "unknown").strip().lower()
        positive_reactivation = self.to_float(reactivation_summary.get("reactivation_score"), 0.0) or 0.0
        positive_adaptive = self.to_float(adaptive_priority_summary.get("adaptive_priority_score"), 0.0) or 0.0
        positive_edge_durability = self.to_float(family_microstructure_summary.get("avg_edge_durability"), 0.0) or 0.0
        positive_survivability = self.to_float(family_microstructure_summary.get("avg_survivability"), 0.0) or 0.0
        positive_clean_orderbook = max(
            0.0,
            min(
                1.0,
                1.0
                - max(
                    self.to_float(family_microstructure_summary.get("unstable_rate"), 0.0) or 0.0,
                    self.to_float(family_microstructure_summary.get("fake_liquidity_rate"), 0.0) or 0.0,
                    self.to_float(family_microstructure_summary.get("quote_withdrawal_rate"), 0.0) or 0.0,
                ),
            ),
        )
        edge_above_cost = bool(audit.get("edge_above_cost") or shadow_arb_validation.get("edge_above_cost"))
        passed_price_safety = bool(shadow_arb_validation.get("passed_price_safety"))
        for bucket in (learning_bucket, family_learning_bucket, market_learning_bucket):
            bucket["first_seen_time"] = bucket.get("first_seen_time") or now
            bucket["last_seen_time"] = now
            bucket["ticker"] = ticker
            bucket["family"] = family
            bucket["market_type"] = market_type
            if count_rejections:
                bucket["rejection_count"] = int(bucket.get("rejection_count", 0) or 0) + 1
                bucket["market_type_counts"][market_type] += 1
                bucket["rejection_reason_counts"][rejection_reason] += 1
                if rejection_reason == "unsafe_price":
                    bucket["unsafe_price_count"] = int(bucket.get("unsafe_price_count", 0) or 0) + 1
                elif rejection_reason == "edge_below_cost":
                    bucket["edge_below_cost_count"] = int(bucket.get("edge_below_cost_count", 0) or 0) + 1
                elif rejection_reason == "low_volume":
                    bucket["low_volume_count"] = int(bucket.get("low_volume_count", 0) or 0) + 1
                elif rejection_reason == "missing_quotes":
                    bucket["missing_quotes_count"] = int(bucket.get("missing_quotes_count", 0) or 0) + 1
                elif rejection_reason in {"unstable_orderbook", "spread_too_wide", "excessive_imbalance"}:
                    bucket["unstable_orderbook_count"] = int(bucket.get("unstable_orderbook_count", 0) or 0) + 1
                elif rejection_reason in {"timing_penalty", "phase55_status_insufficient_data", "no_stochastic_crossover", "no_micro_pullback", "immediate_entry_protection"}:
                    bucket["phase55_block_count"] = int(bucket.get("phase55_block_count", 0) or 0) + 1
                elif rejection_reason in {"low_liquidity", "liquidity_below_synthetic_floor", "thin_top_book"}:
                    bucket["liquidity_block_count"] = int(bucket.get("liquidity_block_count", 0) or 0) + 1
            if count_rejections:
                if edge_above_cost:
                    bucket["edge_above_cost_count"] = int(bucket.get("edge_above_cost_count", 0) or 0) + 1
                if passed_price_safety and edge_above_cost:
                    bucket["positive_signal_count"] = int(bucket.get("positive_signal_count", 0) or 0) + 1
                if positive_edge_durability >= 0.55:
                    bucket["stable_edge_durability_count"] = int(bucket.get("stable_edge_durability_count", 0) or 0) + 1
                    bucket["positive_reason_counts"]["stable_edge_durability"] += 1
                if positive_survivability >= 0.55:
                    bucket["strong_survivability_count"] = int(bucket.get("strong_survivability_count", 0) or 0) + 1
                    bucket["positive_reason_counts"]["strong_survivability"] += 1
                if positive_clean_orderbook >= 0.65:
                    bucket["clean_orderbook_quality_count"] = int(bucket.get("clean_orderbook_quality_count", 0) or 0) + 1
                    bucket["positive_reason_counts"]["clean_orderbook_quality"] += 1
                if positive_reactivation >= 0.60:
                    bucket["high_reactivation_count"] = int(bucket.get("high_reactivation_count", 0) or 0) + 1
                    bucket["positive_reason_counts"]["high_reactivation_score"] += 1
                if positive_adaptive >= 0.60:
                    bucket["high_adaptive_priority_count"] = int(bucket.get("high_adaptive_priority_count", 0) or 0) + 1
                    bucket["positive_reason_counts"]["high_adaptive_priority_score"] += 1
                if decision == "BUY":
                    bucket["promising_count"] = int(bucket.get("promising_count", 0) or 0) + 1
                    bucket["positive_reason_counts"]["accepted_candidate"] += 1
                    if positive_reactivation >= 0.75 and positive_adaptive >= 0.75:
                        bucket["strong_watch_count"] = int(bucket.get("strong_watch_count", 0) or 0) + 1
                        bucket["positive_reason_counts"]["strong_watch"] += 1
                if rejection_reason in {"unsafe_price", "edge_below_cost", "missing_quotes", "low_volume", "unstable_orderbook", "liquidity_below_synthetic_floor"}:
                    bucket["avoid_count"] = int(bucket.get("avoid_count", 0) or 0) + 1
                elif positive_reactivation >= 0.55 or positive_adaptive >= 0.55:
                    bucket["improving_count"] = int(bucket.get("improving_count", 0) or 0) + 1
            elif positive_adaptive >= 0.60:
                bucket["high_adaptive_priority_count"] = int(bucket.get("high_adaptive_priority_count", 0) or 0) + 1
                bucket["positive_reason_counts"]["high_adaptive_priority_score"] += 1
            bucket["learning_score"] = self._compute_family_learning_score(
                family_bucket=family_learning_bucket,
                learning_bucket=bucket,
                learning_summary=family_microstructure_summary,
                reactivation_summary=reactivation_summary,
                adaptive_priority_summary=adaptive_priority_summary,
            )
            bucket["learning_profile"] = self._classify_candidate_learning_profile(
                learning_score=bucket["learning_score"],
                learning_bucket=bucket,
            )
            bucket["score_history"].append(bucket["learning_score"])
            bucket["profile_history"].append(bucket["learning_profile"])
            bucket["last_summary"] = {
                "ticker": ticker,
                "family": family,
                "market_type": market_type,
                "learning_score": round(bucket["learning_score"], 4),
                "learning_profile": bucket["learning_profile"],
                "avoid_count": int(bucket.get("avoid_count", 0) or 0),
                "weak_count": int(bucket.get("weak_count", 0) or 0),
                "improving_count": int(bucket.get("improving_count", 0) or 0),
                "promising_count": int(bucket.get("promising_count", 0) or 0),
                "strong_watch_count": int(bucket.get("strong_watch_count", 0) or 0),
                "unsafe_price_count": int(bucket.get("unsafe_price_count", 0) or 0),
                "edge_below_cost_count": int(bucket.get("edge_below_cost_count", 0) or 0),
                "low_volume_count": int(bucket.get("low_volume_count", 0) or 0),
                "missing_quotes_count": int(bucket.get("missing_quotes_count", 0) or 0),
                "unstable_orderbook_count": int(bucket.get("unstable_orderbook_count", 0) or 0),
                "phase55_block_count": int(bucket.get("phase55_block_count", 0) or 0),
                "liquidity_block_count": int(bucket.get("liquidity_block_count", 0) or 0),
                "high_reactivation_count": int(bucket.get("high_reactivation_count", 0) or 0),
                "high_adaptive_priority_count": int(bucket.get("high_adaptive_priority_count", 0) or 0),
                "stable_edge_durability_count": int(bucket.get("stable_edge_durability_count", 0) or 0),
                "strong_survivability_count": int(bucket.get("strong_survivability_count", 0) or 0),
                "clean_orderbook_quality_count": int(bucket.get("clean_orderbook_quality_count", 0) or 0),
                "edge_above_cost_count": int(bucket.get("edge_above_cost_count", 0) or 0),
                "rejection_count": int(bucket.get("rejection_count", 0) or 0),
                "positive_signal_count": int(bucket.get("positive_signal_count", 0) or 0),
                "rejection_reason_top": bucket.get("rejection_reason_counts").most_common(1)[0][0] if bucket.get("rejection_reason_counts") else "none",
                "positive_reason_top": bucket.get("positive_reason_counts").most_common(1)[0][0] if bucket.get("positive_reason_counts") else "none",
                "rejection_learning": {
                    "ticker": ticker,
                    "family": family,
                    "market_type": market_type,
                    "unsafe_price_count": int(bucket.get("unsafe_price_count", 0) or 0),
                    "edge_below_cost_count": int(bucket.get("edge_below_cost_count", 0) or 0),
                    "low_volume_count": int(bucket.get("low_volume_count", 0) or 0),
                    "missing_quotes_count": int(bucket.get("missing_quotes_count", 0) or 0),
                    "unstable_orderbook_count": int(bucket.get("unstable_orderbook_count", 0) or 0),
                    "phase55_block_count": int(bucket.get("phase55_block_count", 0) or 0),
                    "liquidity_block_count": int(bucket.get("liquidity_block_count", 0) or 0),
                    "top_reject_reason": bucket.get("rejection_reason_counts").most_common(1)[0][0] if bucket.get("rejection_reason_counts") else "none",
                },
                "positive_signal_memory": {
                    "ticker": ticker,
                    "family": family,
                    "market_type": market_type,
                    "high_reactivation_count": int(bucket.get("high_reactivation_count", 0) or 0),
                    "high_adaptive_priority_count": int(bucket.get("high_adaptive_priority_count", 0) or 0),
                    "stable_edge_durability_count": int(bucket.get("stable_edge_durability_count", 0) or 0),
                    "strong_survivability_count": int(bucket.get("strong_survivability_count", 0) or 0),
                    "clean_orderbook_quality_count": int(bucket.get("clean_orderbook_quality_count", 0) or 0),
                    "edge_above_cost_count": int(bucket.get("edge_above_cost_count", 0) or 0),
                    "top_positive_reason": bucket.get("positive_reason_counts").most_common(1)[0][0] if bucket.get("positive_reason_counts") else "none",
                },
            }
        family_learning_bucket["last_summary"] = self._build_candidate_learning_family_summary(family=family)
        self.last_candidate_learning_summary = dict(learning_bucket.get("last_summary") or {})
        self.last_candidate_learning_family_summary = dict(family_learning_bucket.get("last_summary") or {})
        self.last_candidate_learning_overall_summary = self._build_candidate_learning_overall_summary()
        self._emit_candidate_learning_telemetry(ticker_bucket=learning_bucket, family_bucket=family_learning_bucket, force=False)
        return learning_bucket.get("last_summary")

    def _update_adaptive_priority_watchlist(self, *, ticker=None, family=None, ticker_bucket=None, family_summary=None, reactivation_summary=None, audit=None, decision_reason=None, recent_blocker_reason=None):
        ticker = str(ticker or "").strip()
        family = str(family or "").strip().upper() or "UNKNOWN"
        if not ticker:
            return None
        ticker_bucket = ticker_bucket if isinstance(ticker_bucket, dict) else {}
        family_summary = family_summary if isinstance(family_summary, dict) else {}
        reactivation_summary = reactivation_summary if isinstance(reactivation_summary, dict) else {}
        audit = audit if isinstance(audit, dict) else {}
        now = time.time()
        ticker_key = f"ticker:{ticker}"
        family_key = f"family:{family}"
        score_payload = self._compute_adaptive_priority_score(
            ticker_bucket=ticker_bucket,
            family_summary=family_summary,
            reactivation_summary=reactivation_summary,
            recent_blocker_reason=recent_blocker_reason,
            audit=audit,
            decision_reason=decision_reason,
        )
        ticker_watchlist_bucket = self._get_adaptive_priority_watchlist_bucket("adaptive_priority_by_ticker", ticker_key)
        family_watchlist_bucket = self._get_adaptive_priority_watchlist_bucket("adaptive_priority_by_family", family_key)
        previous_score = self.to_float(ticker_watchlist_bucket.get("last_priority_score"), self.to_float(ticker_watchlist_bucket.get("best_priority_score"), 0.0)) or 0.0
        last_seen = float(ticker_watchlist_bucket.get("last_seen_time", 0.0) or 0.0)
        elapsed = max(0.0, now - last_seen) if last_seen > 0 else 0.0
        decay_factor = 0.5 ** (elapsed / 7200.0) if elapsed > 0 else 1.0
        previous_priority_bucket = str(ticker_watchlist_bucket.get("latest_priority_bucket") or "ignore").strip().lower()
        latest_reactivation_state = str(
            reactivation_summary.get("latest_reactivation_state")
            or ticker_bucket.get("latest_reactivation_state")
            or "dead"
        ).strip().lower()
        adaptive_soft_payload = self.compute_adaptive_priority_score(
            predictive_regime_score=score_payload.get("adaptive_priority_score", 0.0),
            regime_transition=latest_reactivation_state,
            improvement_velocity=max(-1.0, min(1.0, score_payload.get("adaptive_priority_score", 0.0) - previous_score)),
            edge_durability_trend=score_payload.get("edge_durability_score", 0.0),
            quote_stability_trend=score_payload.get("quote_lifetime_score", 0.0),
            orderbook_consistency_trend=self.to_float(family_summary.get("avg_survivability"), 0.0),
            family_learning_trend=self.to_float(family_summary.get("avg_priority_score"), 0.0),
            persistence_score=self.to_float(ticker_watchlist_bucket.get("persistence_score"), 0.0),
            decay_score=self.to_float(ticker_watchlist_bucket.get("decay_score"), 0.0),
            memory_bucket=ticker_watchlist_bucket,
            base_priority_score=score_payload.get("adaptive_priority_score", 0.0),
        )
        score_payload.update(adaptive_soft_payload)
        priority_bucket = self._classify_adaptive_priority_bucket(
            adaptive_priority_score=score_payload.get("adaptive_priority_score", 0.0),
            reactivation_summary=reactivation_summary,
            ticker_bucket=ticker_bucket,
            family_summary=family_summary,
            recent_blocker_reason=score_payload.get("recent_blocker_reason"),
        )
        for bucket in (ticker_watchlist_bucket, family_watchlist_bucket):
            bucket["first_seen_time"] = bucket.get("first_seen_time") or now
            bucket["last_seen_time"] = now
            bucket["ticker"] = ticker
            bucket["family"] = family
            bucket["latest_reactivation_state"] = str(
                reactivation_summary.get("latest_reactivation_state")
                or ticker_bucket.get("latest_reactivation_state")
                or bucket.get("latest_reactivation_state")
                or "dead"
            ).strip().lower()
            bucket["previous_priority_bucket"] = previous_priority_bucket
            bucket["latest_priority_bucket"] = priority_bucket
            bucket["best_priority_score"] = max(self.to_float(bucket.get("best_priority_score"), 0.0) or 0.0, score_payload.get("adaptive_priority_score", 0.0) or 0.0)
            for key in ("improving_hits", "decaying_hits", "unstable_hits", "stable_hits", "persistence_score", "decay_score", "improvement_velocity", "promotion_strength", "demotion_strength", "promotion_multiplier", "demotion_multiplier"):
                bucket[key] = round(self.to_float(bucket.get(key), 0.0) * decay_factor, 4)
            bucket.setdefault("score_history", deque(maxlen=24)).append(score_payload.get("adaptive_priority_score", 0.0))
            bucket.setdefault("bucket_history", deque(maxlen=24)).append(priority_bucket)
            blocker_reason = score_payload.get("recent_blocker_reason")
            if blocker_reason:
                bucket.setdefault("blocker_history", deque(maxlen=24)).append(blocker_reason)
            bucket["avg_priority_score"] = round(
                sum(float(item or 0.0) for item in list(bucket.get("score_history") or [])) / max(len(list(bucket.get("score_history") or [])), 1),
                4,
            )
            bucket["observation_count"] = int(bucket.get("observation_count", 0) or 0) + 1
            if priority_bucket == "priority_watch":
                bucket["priority_watch_count"] = int(bucket.get("priority_watch_count", 0) or 0) + 1
            elif priority_bucket == "high_priority":
                bucket["high_priority_count"] = int(bucket.get("high_priority_count", 0) or 0) + 1
            elif priority_bucket == "monitor":
                bucket["monitor_count"] = int(bucket.get("monitor_count", 0) or 0) + 1
            elif priority_bucket == "low_priority":
                bucket["low_priority_count"] = int(bucket.get("low_priority_count", 0) or 0) + 1
            else:
                bucket["ignore_count"] = int(bucket.get("ignore_count", 0) or 0) + 1
            if latest_reactivation_state in {"improving", "reactivation_candidate", "stable", "high_quality"}:
                bucket["improving_count"] = int(bucket.get("improving_count", 0) or 0) + 1
            if latest_reactivation_state in {"improving", "reactivation_candidate"} or priority_bucket in {"high_priority", "priority_watch"}:
                bucket["improving_hits"] = round(self.to_float(bucket.get("improving_hits"), 0.0) + 1.0, 4)
            if latest_reactivation_state in {"unstable", "dead"} or priority_bucket in {"ignore", "low_priority"}:
                bucket["decaying_hits"] = round(self.to_float(bucket.get("decaying_hits"), 0.0) + 1.0, 4)
            if latest_reactivation_state == "unstable" or blocker_reason in {"missing_quotes", "unsafe_price", "edge_below_cost", "low_volume", "unstable_orderbook", "thin_top_book"}:
                bucket["unstable_hits"] = round(self.to_float(bucket.get("unstable_hits"), 0.0) + 1.0, 4)
            if latest_reactivation_state in {"stable", "high_quality"} or priority_bucket in {"monitor", "high_priority", "priority_watch"}:
                bucket["stable_hits"] = round(self.to_float(bucket.get("stable_hits"), 0.0) + 1.0, 4)
            bucket["persistence_score"] = round(
                self._clamp(
                    (self.to_float(bucket.get("stable_hits"), 0.0) + self.to_float(bucket.get("improving_hits"), 0.0))
                    / max(
                        self.to_float(bucket.get("stable_hits"), 0.0)
                        + self.to_float(bucket.get("decaying_hits"), 0.0)
                        + self.to_float(bucket.get("unstable_hits"), 0.0)
                        + 1.0,
                        1.0,
                    )
                ),
                4,
            )
            bucket["decay_score"] = round(
                self._clamp(
                    (self.to_float(bucket.get("decaying_hits"), 0.0) + self.to_float(bucket.get("unstable_hits"), 0.0))
                    / max(
                        self.to_float(bucket.get("stable_hits"), 0.0)
                        + self.to_float(bucket.get("decaying_hits"), 0.0)
                        + self.to_float(bucket.get("unstable_hits"), 0.0)
                        + 1.0,
                        1.0,
                    )
                ),
                4,
            )
            bucket["improvement_velocity"] = round(self._clamp(max(-1.0, min(1.0, score_payload.get("adaptive_priority_score", 0.0) - previous_score))), 4)
            adaptive_signal = self.compute_adaptive_priority_score(
                predictive_regime_score=score_payload.get("adaptive_priority_score", 0.0),
                regime_transition=str(latest_reactivation_state),
                improvement_velocity=bucket["improvement_velocity"],
                edge_durability_trend=score_payload.get("edge_durability_score", 0.0),
                quote_stability_trend=score_payload.get("quote_lifetime_score", 0.0),
                orderbook_consistency_trend=self.to_float(family_summary.get("liquidity_reliability"), 0.0),
                family_learning_trend=self.to_float(family_summary.get("avg_priority_score"), 0.0),
                persistence_score=bucket["persistence_score"],
                decay_score=bucket["decay_score"],
                memory_bucket=bucket,
                base_priority_score=score_payload.get("adaptive_priority_score", 0.0),
            )
            bucket["promotion_strength"] = adaptive_signal.get("promotion_strength", 0.0)
            bucket["demotion_strength"] = adaptive_signal.get("demotion_strength", 0.0)
            bucket["promotion_multiplier"] = adaptive_signal.get("promotion_multiplier", 0.0)
            bucket["demotion_multiplier"] = adaptive_signal.get("demotion_multiplier", 0.0)
            bucket["last_priority_score"] = score_payload.get("adaptive_priority_score", 0.0)
            bucket["promotion_reason"] = adaptive_signal.get("promotion_reason")
            bucket["demotion_reason"] = adaptive_signal.get("demotion_reason")
            reject_reason_counts = Counter(str(reason).strip().lower() for reason in list(bucket.get("blocker_history") or []) if reason)
            bucket["reject_reason_top"] = reject_reason_counts.most_common(1)[0][0] if reject_reason_counts else score_payload.get("recent_blocker_reason") or "none"
            bucket["last_summary"] = {
                "ticker": ticker,
                "family": family,
                **score_payload,
                "previous_priority_bucket": previous_priority_bucket,
                "promotion_reason": bucket.get("promotion_reason") or score_payload.get("promotion_reason"),
                "demotion_reason": bucket.get("demotion_reason") or score_payload.get("demotion_reason"),
                "soft_priority_adjustment": round(self.to_float(score_payload.get("soft_priority_adjustment"), 0.0), 4),
                "persistence_score": round(self.to_float(bucket.get("persistence_score"), 0.0), 4),
                "decay_score": round(self.to_float(bucket.get("decay_score"), 0.0), 4),
                "improvement_velocity": round(self.to_float(bucket.get("improvement_velocity"), 0.0), 4),
                "promotion_strength": round(self.to_float(bucket.get("promotion_strength"), 0.0), 4),
                "demotion_strength": round(self.to_float(bucket.get("demotion_strength"), 0.0), 4),
                "promotion_multiplier": round(self.to_float(bucket.get("promotion_multiplier"), 0.0), 4),
                "demotion_multiplier": round(self.to_float(bucket.get("demotion_multiplier"), 0.0), 4),
                "latest_priority_bucket": priority_bucket,
                "best_priority_score": round(self.to_float(bucket.get("best_priority_score"), 0.0) or 0.0, 4),
                "avg_priority_score": bucket["avg_priority_score"],
                "reject_reason_top": bucket["reject_reason_top"],
                "observation_count": int(bucket.get("observation_count", 0) or 0),
                "previous_rank": None,
                "new_rank": None,
            }
        self.last_adaptive_priority_summary = dict(ticker_watchlist_bucket.get("last_summary") or {})
        family_watchlist_bucket["last_summary"] = self._build_adaptive_priority_family_summary(family=family)
        self.last_adaptive_priority_family_summary = dict(family_watchlist_bucket.get("last_summary") or {})
        self.last_adaptive_priority_overall_summary = self._build_adaptive_priority_overall_summary()
        self._emit_adaptive_priority_telemetry(ticker_bucket=ticker_watchlist_bucket, family_bucket=family_watchlist_bucket, force=False)
        return ticker_watchlist_bucket.get("last_summary")

    def _emit_live_microstructure_telemetry(self, *, ticker_bucket=None, family_bucket=None, family=None, ticker=None, force=False):
        ticker_bucket = ticker_bucket if isinstance(ticker_bucket, dict) else {}
        family_bucket = family_bucket if isinstance(family_bucket, dict) else {}
        now = time.time()
        ticker_key = str(ticker or ticker_bucket.get("ticker") or "").strip()
        family_key = str(family or family_bucket.get("family") or "").strip().upper() or "UNKNOWN"
        last_signal_ts = float(getattr(self, "live_microstructure_last_signal_ts_by_ticker", {}).get(ticker_key, 0.0) or 0.0)
        should_emit_ticker = force or (ticker_key and now - last_signal_ts >= 120.0)
        if should_emit_ticker and ticker_key:
            self.live_microstructure_last_signal_ts_by_ticker[ticker_key] = now
            quote_lifetime = max(
                self.to_float(ticker_bucket.get("quote_lifetime_seconds"), 0.0) or 0.0,
                max(0.0, now - float(ticker_bucket.get("last_quote_change_ts") or ticker_bucket.get("first_seen_timestamp") or now)),
            )
            spread_lifetime = max(
                self.to_float(ticker_bucket.get("spread_lifetime_seconds"), 0.0) or 0.0,
                max(0.0, now - float(ticker_bucket.get("last_spread_change_ts") or ticker_bucket.get("first_seen_timestamp") or now)),
            )
            edge_lifetime = max(
                self.to_float(ticker_bucket.get("edge_lifetime_seconds"), 0.0) or 0.0,
                max(0.0, now - float(ticker_bucket.get("last_edge_change_ts") or ticker_bucket.get("first_seen_timestamp") or now)),
            )
            unsafe_lifetime = max(
                self.to_float(ticker_bucket.get("unsafe_price_seconds"), 0.0) or 0.0,
                max(0.0, now - float(ticker_bucket.get("last_unsafe_change_ts") or ticker_bucket.get("first_seen_timestamp") or now)),
            )
            quote_payload = {
                "ticker": ticker_key,
                "family": family_key,
                "best_bid_survival_seconds": round(quote_lifetime, 4),
                "best_ask_survival_seconds": round(quote_lifetime, 4),
                "spread_lifetime_seconds": round(spread_lifetime, 4),
                "edge_persistence_seconds": round(edge_lifetime, 4),
                "unsafe_price_duration_seconds": round(unsafe_lifetime, 4),
                "spread_lifetime_cycles": int(ticker_bucket.get("spread_change_count", 0) or 0),
                "quote_churn_count": int(ticker_bucket.get("quote_churn_count", 0) or 0),
                "edge_survival_cycles": int(ticker_bucket.get("edge_survival_cycles", 0) or 0),
                "unsafe_price_cycles": int(ticker_bucket.get("unsafe_price_cycles", 0) or 0),
                "quote_withdrawal_count": int(ticker_bucket.get("quote_withdrawal_count", 0) or 0),
            }
            spread_payload = {
                "ticker": ticker_key,
                "family": family_key,
                "spread": round(self.to_float(ticker_bucket.get("spread_value"), 0.0) or 0.0, 4),
                "spread_lifetime_seconds": round(spread_lifetime, 4),
                "spread_change_count": int(ticker_bucket.get("spread_change_count", 0) or 0),
                "spread_stability_score": round(self.to_float(ticker_bucket.get("spread_stability_score"), 0.5), 4),
            }
            imbalance_payload = {
                "ticker": ticker_key,
                "family": family_key,
                "imbalance_ratio": round(self.to_float(ticker_bucket.get("imbalance_ratio"), 0.0) or 0.0, 4),
                "pressure_direction": ticker_bucket.get("pressure_direction") or "unknown",
                "liquidity_decay_rate": round(self.to_float(ticker_bucket.get("liquidity_decay_rate"), 0.0) or 0.0, 4),
                "yes_depth": round(self.to_float(ticker_bucket.get("yes_depth_value"), 0.0) or 0.0, 4),
                "no_depth": round(self.to_float(ticker_bucket.get("no_depth_value"), 0.0) or 0.0, 4),
                "disappearing_liquidity_count": int(ticker_bucket.get("disappearing_liquidity_count", 0) or 0),
                "quote_withdrawal_count": int(ticker_bucket.get("quote_withdrawal_count", 0) or 0),
            }
            edge_payload = {
                "ticker": ticker_key,
                "family": family_key,
                "edge_stability_score": round(self.to_float(ticker_bucket.get("edge_durability_score"), 0.5), 4),
                "edge_decay_rate": round(max(0.0, 1.0 - self.to_float(ticker_bucket.get("edge_durability_score"), 0.5)), 4),
                "edge_survival_cycles": int(ticker_bucket.get("edge_survival_cycles", 0) or 0),
                "edge_collapse_count": int(ticker_bucket.get("edge_collapse_count", 0) or 0),
                "edge_persistence_seconds": round(edge_lifetime, 4),
            }
            survivability_payload = {
                "ticker": ticker_key,
                "family": family_key,
                "execution_survivability_score": round(self.to_float(ticker_bucket.get("execution_survivability_score"), 0.5), 4),
                "spread_stability_score": round(self.to_float(ticker_bucket.get("spread_stability_score"), 0.5), 4),
                "liquidity_reliability_score": round(self.to_float(ticker_bucket.get("liquidity_reliability_score"), 0.5), 4),
                "imbalance_ratio": round(self.to_float(ticker_bucket.get("imbalance_ratio"), 0.0) or 0.0, 4),
                "quote_churn_count": int(ticker_bucket.get("quote_churn_count", 0) or 0),
                "edge_collapse_count": int(ticker_bucket.get("edge_collapse_count", 0) or 0),
                "unsafe_price_cycles": int(ticker_bucket.get("unsafe_price_cycles", 0) or 0),
            }
            maker_payload = {
                "ticker": ticker_key,
                "family": family_key,
                "rapid_quote_move": bool(ticker_bucket.get("rapid_quote_move_count", 0) or 0),
                "fake_liquidity": bool(ticker_bucket.get("fake_liquidity_count", 0) or 0),
                "unstable_topbook": bool(ticker_bucket.get("unstable_topbook_count", 0) or 0),
                "repeated_spread_widening": int(ticker_bucket.get("repeated_spread_widening_count", 0) or 0),
                "aggressive_quote_fade": bool(ticker_bucket.get("aggressive_quote_fade_count", 0) or 0),
                "market_maker_behavior_score": round(self.to_float(ticker_bucket.get("market_maker_behavior_score"), 0.5), 4),
            }
            print("[LIVE-QUOTE-LIFETIME] " + json.dumps(quote_payload, sort_keys=True, default=str))
            print("[LIVE-SPREAD-LIFETIME] " + json.dumps(spread_payload, sort_keys=True, default=str))
            print("[LIVE-ORDERBOOK-IMBALANCE] " + json.dumps(imbalance_payload, sort_keys=True, default=str))
            print("[LIVE-EDGE-DURABILITY] " + json.dumps(edge_payload, sort_keys=True, default=str))
            print("[LIVE-EXECUTION-SURVIVABILITY] " + json.dumps(survivability_payload, sort_keys=True, default=str))
            print("[LIVE-MARKET-MAKER-BEHAVIOR] " + json.dumps(maker_payload, sort_keys=True, default=str))
        last_family_emit = float(getattr(self, "live_microstructure_last_family_summary_ts", 0.0) or 0.0)
        should_emit_family = force or (now - last_family_emit >= 180.0)
        if should_emit_family:
            self.live_microstructure_last_family_summary_ts = now
            family_summary = self._build_live_microstructure_family_summary(family=family_key)
            self.last_live_microstructure_family_summary = family_summary
            print("[LIVE-FAMILY-MICROSTRUCTURE] " + json.dumps(family_summary, sort_keys=True, default=str))
        return True

    def _get_shadow_arb_reject_reason_counts(self):
        counts = Counter()
        repeat_tracker = getattr(self, "shadow_arb_repeat_tracker", {}) or {}
        if isinstance(repeat_tracker, dict):
            for tracker in repeat_tracker.values():
                if not isinstance(tracker, dict):
                    continue
                reject_reasons = tracker.get("reject_reasons")
                if isinstance(reject_reasons, Counter):
                    counts.update(reject_reasons)
                elif isinstance(reject_reasons, dict):
                    counts.update({str(key): int(value or 0) for key, value in reject_reasons.items()})
        family_stats = getattr(self, "shadow_arb_validation_family_stats", {}) or {}
        if isinstance(family_stats, dict):
            for stats in family_stats.values():
                if not isinstance(stats, dict):
                    continue
                reject_reasons = stats.get("reject_reasons")
                if isinstance(reject_reasons, Counter):
                    counts.update(reject_reasons)
                elif isinstance(reject_reasons, dict):
                    counts.update({str(key): int(value or 0) for key, value in reject_reasons.items()})
        return counts

    def _build_shadow_arb_readiness_snapshot(self):
        ticker_memory = getattr(self, "shadow_arb_stability_by_ticker", {}) or {}
        if not isinstance(ticker_memory, dict):
            ticker_memory = {}
        family_memory = getattr(self, "shadow_arb_stability_by_family", {}) or {}
        if not isinstance(family_memory, dict):
            family_memory = {}
        ticker_buckets = [bucket for bucket in ticker_memory.values() if isinstance(bucket, dict)]
        family_buckets = [bucket for bucket in family_memory.values() if isinstance(bucket, dict)]
        observations = sum(int(bucket.get("repeat_count", 0) or 0) for bucket in ticker_buckets)
        stable_shadow_candidates = sum(1 for bucket in ticker_buckets if self._is_shadow_arb_stable_bucket(bucket))
        unstable_shadow_candidates = sum(1 for bucket in ticker_buckets if int(bucket.get("repeated_unstable_count", 0) or 0) > 0)
        edge_above_cost_count = sum(int(bucket.get("repeated_above_cost_count", 0) or 0) for bucket in ticker_buckets)
        edge_below_cost_count = sum(max(int(bucket.get("repeat_count", 0) or 0) - int(bucket.get("repeated_above_cost_count", 0) or 0), 0) for bucket in ticker_buckets)
        safe_orderbook_count = sum(int(bucket.get("repeated_safe_orderbook_count", 0) or 0) for bucket in ticker_buckets)
        unstable_count = sum(int(bucket.get("repeated_unstable_count", 0) or 0) for bucket in ticker_buckets)
        reject_counts = self._get_shadow_arb_reject_reason_counts()
        top_reject_reason = reject_counts.most_common(1)[0][0] if reject_counts else "none"
        best_bucket = None
        if ticker_buckets:
            best_bucket = max(
                ticker_buckets,
                key=lambda bucket: (
                    int(bucket.get("repeated_above_cost_count", 0) or 0),
                    int(bucket.get("repeated_safe_orderbook_count", 0) or 0),
                    self.to_float(bucket.get("avg_edge"), 0.0),
                    int(bucket.get("repeat_count", 0) or 0),
                ),
            )
        best_ticker = None
        best_family = None
        if isinstance(best_bucket, dict):
            best_ticker = str(best_bucket.get("last_ticker") or best_bucket.get("ticker") or "").strip() or None
            best_family = str(best_bucket.get("last_family") or best_bucket.get("family") or "").strip() or None
        readiness_state = "not_ready"
        if observations <= 0:
            readiness_state = "not_ready"
        elif stable_shadow_candidates > 0 and edge_above_cost_count > edge_below_cost_count and unstable_shadow_candidates == 0:
            readiness_state = "ready_shadow_only"
        elif stable_shadow_candidates > 0 or edge_above_cost_count > 0:
            readiness_state = "collecting_evidence"
        else:
            readiness_state = "collecting_evidence"
        score = 0.0
        if observations > 0:
            stable_ratio = stable_shadow_candidates / max(len(ticker_buckets), 1)
            above_cost_ratio = edge_above_cost_count / max(observations, 1)
            safe_orderbook_ratio = safe_orderbook_count / max(observations, 1)
            liquidity_confirmation_ratio = safe_orderbook_ratio
            repeat_coverage_ratio = min(1.0, observations / max(len(ticker_buckets) * 3.0, 1.0))
            unsafe_price_count = int(reject_counts.get("unsafe_price", 0) or 0)
            low_volume_count = int(reject_counts.get("low_volume", 0) or 0)
            missing_quotes_count = int(reject_counts.get("missing_quotes", 0) or 0)
            unstable_behavior_count = int(reject_counts.get("spread_too_wide", 0) or 0) + int(reject_counts.get("unstable_orderbook", 0) or 0)
            penalty_scale = max(observations, 1)
            penalty = min(0.7, (
                (unsafe_price_count / penalty_scale) * 0.18
                + (low_volume_count / penalty_scale) * 0.12
                + (missing_quotes_count / penalty_scale) * 0.18
                + (unstable_behavior_count / penalty_scale) * 0.22
                + (unstable_count / max(observations, 1)) * 0.20
            ))
            score = max(0.0, min(1.0, (
                stable_ratio * 0.30
                + above_cost_ratio * 0.25
                + safe_orderbook_ratio * 0.20
                + liquidity_confirmation_ratio * 0.10
                + repeat_coverage_ratio * 0.15
                - penalty
            )))
        microstructure_summary = self._build_live_microstructure_overall_summary()
        readiness_state = str(microstructure_summary.get("readiness_state") or readiness_state).strip().lower() or readiness_state
        top_blocker = str(microstructure_summary.get("top_blocker") or top_blocker).strip() or top_blocker
        return {
            "observations": observations,
            "stable_shadow_candidates": int(stable_shadow_candidates),
            "unstable_shadow_candidates": int(unstable_shadow_candidates),
            "edge_above_cost_count": int(edge_above_cost_count),
            "edge_below_cost_count": int(edge_below_cost_count),
            "safe_orderbook_count": int(safe_orderbook_count),
            "unstable_count": int(unstable_count),
            "top_reject_reason": top_reject_reason,
            "readiness_state": readiness_state,
            "legacy_readiness_state": "ready_shadow_only" if stable_shadow_candidates > 0 and edge_above_cost_count > edge_below_cost_count and unstable_shadow_candidates == 0 else ("collecting_evidence" if observations > 0 else "not_ready"),
            "readiness_score": round(score, 4),
            "live_arb_enabled": bool(AION_LIVE_ARB_ENABLED),
            "max_canary_size": int(AION_ARB_MAX_CANARY_CONTRACTS or 1),
            "best_ticker": best_ticker,
            "best_family": best_family,
            "stable_ratio": round(stable_ratio, 4) if observations > 0 else 0.0,
            "above_cost_ratio": round(above_cost_ratio, 4) if observations > 0 else 0.0,
            "safe_orderbook_ratio": round(safe_orderbook_ratio, 4) if observations > 0 else 0.0,
            "liquidity_confirmation_ratio": round(liquidity_confirmation_ratio, 4) if observations > 0 else 0.0,
            "microstructure_summary": microstructure_summary,
            "top_blocker": top_blocker,
        }

    def _is_shadow_arb_stable_bucket(self, bucket):
        bucket = bucket if isinstance(bucket, dict) else {}
        repeat_count = int(bucket.get("repeat_count", 0) or 0)
        safe_count = int(bucket.get("repeated_safe_orderbook_count", 0) or 0)
        above_cost_count = int(bucket.get("repeated_above_cost_count", 0) or 0)
        unstable_count = int(bucket.get("repeated_unstable_count", 0) or 0)
        avg_edge = self.to_float(bucket.get("avg_edge"), 0.0) or 0.0
        avg_estimated_cost = self.to_float(bucket.get("avg_estimated_cost"), 0.0) or 0.0
        last_edge = self.to_float(bucket.get("last_edge"), None)
        last_estimated_cost = self.to_float(bucket.get("last_estimated_cost"), None)
        return bool(
            repeat_count >= 2
            and safe_count >= 2
            and above_cost_count >= 2
            and unstable_count == 0
            and avg_edge > avg_estimated_cost
            and (last_edge is None or last_estimated_cost is None or last_edge > last_estimated_cost)
        )

    def _maybe_emit_shadow_arb_readiness_score(self, *, force=False):
        now = time.time()
        snapshot = self._build_shadow_arb_readiness_snapshot()
        if not force and (now - float(getattr(self, "shadow_arb_readiness_score_last_summary_ts", 0.0) or 0.0)) < 180.0:
            return None
        self.shadow_arb_readiness_score_last_summary_ts = now
        self.shadow_arb_readiness_score_last_state = snapshot.get("readiness_state")
        print("[LIVE-ARB-READINESS-SCORE] " + json.dumps(snapshot, sort_keys=True, default=str))
        return snapshot

    def _maybe_emit_shadow_arb_canary_recommendation(self, *, force=False):
        now = time.time()
        snapshot = self._build_shadow_arb_readiness_snapshot()
        if snapshot.get("observations", 0) <= 0:
            return None
        if snapshot.get("stable_shadow_candidates", 0) <= 0:
            return None
        if snapshot.get("edge_above_cost_count", 0) <= snapshot.get("edge_below_cost_count", 0):
            return None
        if snapshot.get("unstable_shadow_candidates", 0) > 0:
            return None
        best_key = snapshot.get("best_ticker") or snapshot.get("best_family") or "unknown"
        last_emit = float(getattr(self, "shadow_arb_canary_recommendation_last_signal_ts_by_key", {}).get(best_key, 0.0) or 0.0)
        if not force and (now - last_emit) < 180.0:
            return None
        if not force and (now - float(getattr(self, "shadow_arb_canary_recommendation_last_summary_ts", 0.0) or 0.0)) < 180.0:
            return None
        best_bucket = None
        ticker_memory = getattr(self, "shadow_arb_stability_by_ticker", {}) or {}
        if isinstance(ticker_memory, dict):
            for key, bucket in ticker_memory.items():
                if not isinstance(bucket, dict):
                    continue
                if self._is_shadow_arb_stable_bucket(bucket):
                    if best_bucket is None or (
                        int(bucket.get("repeated_above_cost_count", 0) or 0),
                        int(bucket.get("repeated_safe_orderbook_count", 0) or 0),
                        self.to_float(bucket.get("avg_edge"), 0.0),
                    ) > (
                        int(best_bucket.get("repeated_above_cost_count", 0) or 0),
                        int(best_bucket.get("repeated_safe_orderbook_count", 0) or 0),
                        self.to_float(best_bucket.get("avg_edge"), 0.0),
                    ):
                        best_bucket = dict(bucket)
                        best_bucket["bucket_key"] = key
        if not isinstance(best_bucket, dict):
            return None
        bucket_repeat_count = int(best_bucket.get("repeat_count", 0) or 0)
        bucket_safe_count = int(best_bucket.get("repeated_safe_orderbook_count", 0) or 0)
        bucket_above_cost_count = int(best_bucket.get("repeated_above_cost_count", 0) or 0)
        bucket_unstable_count = int(best_bucket.get("repeated_unstable_count", 0) or 0)
        bucket_avg_edge = self.to_float(best_bucket.get("avg_edge"), 0.0) or 0.0
        bucket_avg_cost = self.to_float(best_bucket.get("avg_estimated_cost"), 0.0) or 0.0
        last_edge = self.to_float(best_bucket.get("last_edge"), None)
        last_cost = self.to_float(best_bucket.get("last_estimated_cost"), None)
        if not (
            bucket_repeat_count >= 2
            and bucket_safe_count >= 2
            and bucket_above_cost_count >= 2
            and bucket_unstable_count == 0
            and bucket_avg_edge > bucket_avg_cost
            and (last_edge is None or last_cost is None or last_edge > last_cost)
        ):
            return None
        recommendation = {
            "live_arb_enabled": bool(AION_LIVE_ARB_ENABLED),
            "max_canary_size": int(AION_ARB_MAX_CANARY_CONTRACTS or 1),
            "readiness_state": snapshot.get("readiness_state"),
            "readiness_score": snapshot.get("readiness_score"),
            "ticker": best_bucket.get("last_ticker") or best_bucket.get("bucket_key"),
            "family": best_bucket.get("last_family") or snapshot.get("best_family"),
            "repeat_count": bucket_repeat_count,
            "safe_orderbook_count": bucket_safe_count,
            "above_cost_count": bucket_above_cost_count,
            "unstable_count": bucket_unstable_count,
            "avg_edge": round(bucket_avg_edge, 4),
            "avg_estimated_cost": round(bucket_avg_cost, 4),
            "last_edge": last_edge,
            "last_estimated_cost": last_cost,
            "recommendation": "telemetry_only_canary_candidate",
            "never_trade": True,
        }
        self.shadow_arb_canary_recommendation_last_summary_ts = now
        self.shadow_arb_canary_recommendation_last_signal_ts_by_key[best_key] = now
        print("[LIVE-ARB-CANARY-RECOMMENDATION] " + json.dumps(recommendation, sort_keys=True, default=str))
        return recommendation

    def _maybe_emit_shadow_arb_validation_snapshot(self, *, force=False):
        now = time.time()
        cycle_stats = dict(getattr(self, "shadow_arb_validation_cycle_stats", {}) or {})
        rolling_stats = dict(getattr(self, "shadow_arb_validation_totals", {}) or {})
        if not force and (now - float(getattr(self, "shadow_arb_validation_last_summary_ts", 0.0) or 0.0)) < 90.0:
            return None
        self.shadow_arb_validation_last_summary_ts = now
        best = dict(getattr(self, "shadow_arb_validation_cycle_best", {}) or {})
        summary_payload = {
            "live_arb_enabled": bool(AION_LIVE_ARB_ENABLED),
            "shadow_arb_candidates_seen": int(cycle_stats.get("shadow_arb_candidates_seen", 0) or 0),
            "shadow_arb_candidates_passed_price_safety": int(cycle_stats.get("shadow_arb_candidates_passed_price_safety", 0) or 0),
            "shadow_arb_candidates_edge_above_cost": int(cycle_stats.get("shadow_arb_candidates_edge_above_cost", 0) or 0),
            "shadow_arb_rejected_edge_below_cost": int(cycle_stats.get("shadow_arb_rejected_edge_below_cost", 0) or 0),
            "shadow_arb_rejected_spread": int(cycle_stats.get("shadow_arb_rejected_spread", 0) or 0),
            "shadow_arb_rejected_liquidity": int(cycle_stats.get("shadow_arb_rejected_liquidity", 0) or 0),
            "shadow_arb_rejected_missing_quotes": int(cycle_stats.get("shadow_arb_rejected_missing_quotes", 0) or 0),
            "shadow_arb_rejected_resolution_uncertainty": int(cycle_stats.get("shadow_arb_rejected_resolution_uncertainty", 0) or 0),
            "rolling_shadow_arb_candidates_seen": int(rolling_stats.get("shadow_arb_candidates_seen", 0) or 0),
            "rolling_shadow_arb_candidates_passed_price_safety": int(rolling_stats.get("shadow_arb_candidates_passed_price_safety", 0) or 0),
            "rolling_shadow_arb_candidates_edge_above_cost": int(rolling_stats.get("shadow_arb_candidates_edge_above_cost", 0) or 0),
            "rolling_shadow_arb_rejected_edge_below_cost": int(rolling_stats.get("shadow_arb_rejected_edge_below_cost", 0) or 0),
            "rolling_shadow_arb_rejected_spread": int(rolling_stats.get("shadow_arb_rejected_spread", 0) or 0),
            "rolling_shadow_arb_rejected_liquidity": int(rolling_stats.get("shadow_arb_rejected_liquidity", 0) or 0),
            "rolling_shadow_arb_rejected_missing_quotes": int(rolling_stats.get("shadow_arb_rejected_missing_quotes", 0) or 0),
            "rolling_shadow_arb_rejected_resolution_uncertainty": int(rolling_stats.get("shadow_arb_rejected_resolution_uncertainty", 0) or 0),
            "shadow_arb_best_ticker": best.get("ticker"),
            "shadow_arb_best_family": best.get("family"),
            "shadow_arb_best_edge": best.get("shadow_edge"),
            "shadow_arb_avg_edge": best.get("avg_edge"),
            "shadow_arb_max_edge": best.get("max_edge"),
            "shadow_arb_repeat_count": best.get("repeat_count"),
            "shadow_arb_best_repeat_count": best.get("repeat_count"),
        }
        print("[LIVE-ARB-VALIDATION] " + json.dumps(summary_payload, sort_keys=True, default=str))
        if (now - float(getattr(self, "shadow_arb_validation_last_family_summary_ts", 0.0) or 0.0)) >= 180.0:
            self.shadow_arb_validation_last_family_summary_ts = now
            families = []
            for family, stats in sorted(
                (getattr(self, "shadow_arb_validation_family_stats", {}) or {}).items(),
                key=lambda item: (
                    item[1].get("count", 0),
                    item[1].get("edge_sum", 0.0),
                    item[1].get("max_edge", 0.0),
                ),
                reverse=True,
            )[:8]:
                count = int(stats.get("count", 0) or 0)
                avg_edge = (self.to_float(stats.get("edge_sum"), 0.0) / count) if count else 0.0
                reject_reasons = stats.get("reject_reasons") if isinstance(stats.get("reject_reasons"), Counter) else Counter(stats.get("reject_reasons") or {})
                families.append({
                    "family": family,
                    "count": count,
                    "avg_shadow_edge": round(avg_edge, 4),
                    "max_shadow_edge": round(self.to_float(stats.get("max_edge"), 0.0), 4),
                    "reject_reason_top": reject_reasons.most_common(1)[0][0] if reject_reasons else "none",
                    "edge_above_cost_count": int(stats.get("edge_above_cost_count", 0) or 0),
                })
            print(
                "[LIVE-ARB-FAMILY-SUMMARY] " + json.dumps({
                    "live_arb_enabled": bool(AION_LIVE_ARB_ENABLED),
                    "families": families,
                }, sort_keys=True, default=str)
            )
        return summary_payload

    def _maybe_emit_shadow_arb_canary_readiness_dashboard(self, *, force=False):
        now = time.time()
        if not force and (now - float(getattr(self, "shadow_arb_canary_readiness_last_summary_ts", 0.0) or 0.0)) < 180.0:
            return None
        snapshot = self._build_shadow_arb_readiness_snapshot()
        cycle_stats = dict(getattr(self, "shadow_arb_validation_cycle_stats", {}) or {})
        rolling_stats = dict(getattr(self, "shadow_arb_validation_totals", {}) or {})
        family_stats = dict(getattr(self, "shadow_arb_validation_family_stats", {}) or {})
        repeat_tracker = dict(getattr(self, "shadow_arb_repeat_tracker", {}) or {})
        best = dict(getattr(self, "shadow_arb_validation_cycle_best", {}) or {})
        total_candidates = int(rolling_stats.get("shadow_arb_candidates_seen", 0) or 0)
        total_edge_above_cost = int(rolling_stats.get("shadow_arb_candidates_edge_above_cost", 0) or 0)
        total_passed_price_safety = int(rolling_stats.get("shadow_arb_candidates_passed_price_safety", 0) or 0)
        total_missing_quotes = int(rolling_stats.get("shadow_arb_rejected_missing_quotes", 0) or 0)
        total_liquidity_reject = int(rolling_stats.get("shadow_arb_rejected_liquidity", 0) or 0)
        total_resolution_reject = int(rolling_stats.get("shadow_arb_rejected_resolution_uncertainty", 0) or 0)
        total_spread_reject = int(rolling_stats.get("shadow_arb_rejected_spread", 0) or 0)
        total_edge_below_cost = int(rolling_stats.get("shadow_arb_rejected_edge_below_cost", 0) or 0)
        families_with_positive_shadow_edge = [
            family for family, stats in family_stats.items()
            if self.to_float(stats.get("edge_sum"), 0.0) > 0.0 or self.to_float(stats.get("max_edge"), 0.0) > 0.0
        ]
        reactivation_summary = self._build_reactivation_watchlist_summary()
        adaptive_priority_summary = self._build_adaptive_priority_overall_summary()
        learning_summary = self._build_candidate_learning_overall_summary()
        predictive_regime_summary = self._build_predictive_regime_overall_summary()
        canary_ready_count = sum(1 for tracker in repeat_tracker.values() if int(tracker.get("repeat_count", 0) or 0) >= AION_ARB_MIN_REPEAT_COUNT and self.to_float(tracker.get("pass_count"), 0.0) >= 2 and self.to_float(tracker.get("edge_above_cost_count"), 0.0) >= 1)
        best_ticker = best.get("ticker")
        best_family = best.get("family")
        best_edge = self.to_float(best.get("shadow_edge"), 0.0) or 0.0
        best_repeat_count = int(best.get("repeat_count", 0) or 0)
        readiness_score = 0.0
        if total_candidates > 0:
            repeat_signal_component = min(1.0, sum(min(int(tracker.get("repeat_count", 0) or 0), 5) for tracker in repeat_tracker.values()) / max(total_candidates * 5.0, 1.0))
            avg_edge_component = min(1.0, max(0.0, float(best.get("avg_edge") or 0.0)) / max(AION_ARB_MIN_EDGE * 2.0, 0.0001))
            orderbook_safety_component = max(0.0, 1.0 - (total_liquidity_reject + total_spread_reject + total_missing_quotes) / max(total_candidates, 1))
            price_safety_component = max(0.0, 1.0 - (total_resolution_reject + total_edge_below_cost) / max(total_candidates, 1))
            missing_quote_component = max(0.0, 1.0 - (total_missing_quotes / max(total_candidates, 1)))
            liquidity_component = max(0.0, 1.0 - (total_liquidity_reject / max(total_candidates, 1)))
            resolution_component = max(0.0, 1.0 - (total_resolution_reject / max(total_candidates, 1)))
            readiness_score = round(max(0.0, min(1.0, (
                repeat_signal_component * 0.30
                + avg_edge_component * 0.25
                + orderbook_safety_component * 0.15
                + price_safety_component * 0.15
                + missing_quote_component * 0.05
                + liquidity_component * 0.05
                + resolution_component * 0.05
            ))), 4)
        if total_candidates <= 0:
            readiness_state = "not_ready"
            top_blocker = "no_shadow_candidates"
        elif not AION_LIVE_ARB_ENABLED:
            readiness_state = "collecting_evidence"
            top_blocker = "live_arb_disabled"
        elif canary_ready_count > 0 and best_repeat_count >= AION_ARB_MIN_REPEAT_COUNT and best_edge >= AION_ARB_MIN_EDGE:
            readiness_state = "ready_shadow_only"
            top_blocker = "live_arb_disabled"
        elif best_repeat_count >= max(1, AION_ARB_MIN_REPEAT_COUNT - 1) and best_edge >= max(0.0, AION_ARB_MIN_EDGE * 0.8):
            readiness_state = "nearly_ready"
            if total_edge_below_cost > max(total_candidates // 2, 0):
                top_blocker = "edge_below_cost"
            elif total_liquidity_reject > max(total_candidates // 2, 0):
                top_blocker = "thin_liquidity"
            elif total_missing_quotes > max(total_candidates // 2, 0):
                top_blocker = "missing_quotes"
            elif total_resolution_reject > max(total_candidates // 2, 0):
                top_blocker = "resolution_uncertainty"
            else:
                top_blocker = "insufficient_repeat_count"
        else:
            readiness_state = "collecting_evidence"
            if best_repeat_count < AION_ARB_MIN_REPEAT_COUNT:
                top_blocker = "insufficient_repeat_count"
            elif best_edge < AION_ARB_MIN_EDGE:
                top_blocker = "edge_below_cost"
            elif total_missing_quotes > total_liquidity_reject and total_missing_quotes > total_edge_below_cost:
                top_blocker = "missing_quotes"
            elif total_resolution_reject > total_edge_below_cost:
                top_blocker = "resolution_uncertainty"
            else:
                top_blocker = "thin_liquidity"
        dashboard = {
            "live_arb_enabled": bool(AION_LIVE_ARB_ENABLED),
            "max_canary_contracts": int(AION_ARB_MAX_CANARY_CONTRACTS or 1),
            "max_canary_size": int(snapshot.get("max_canary_size") or int(AION_ARB_MAX_CANARY_CONTRACTS or 1)),
            "total_shadow_candidates": total_candidates,
            "total_edge_above_cost": total_edge_above_cost,
            "best_shadow_ticker": best_ticker,
            "best_shadow_family": best_family,
            "best_shadow_edge": round(best_edge, 4),
            "best_repeat_count": best_repeat_count,
            "families_with_positive_shadow_edge": len(families_with_positive_shadow_edge),
            "canary_ready_count": int(canary_ready_count),
            "top_blocker": top_blocker,
            "readiness_state": readiness_state,
            "readiness_score": readiness_score,
            "shadow_arb_candidates_seen": total_candidates,
            "shadow_arb_candidates_passed_price_safety": total_passed_price_safety,
            "shadow_arb_rejected_edge_below_cost": total_edge_below_cost,
            "shadow_arb_rejected_spread": total_spread_reject,
            "shadow_arb_rejected_liquidity": total_liquidity_reject,
            "shadow_arb_rejected_missing_quotes": total_missing_quotes,
            "shadow_arb_rejected_resolution_uncertainty": total_resolution_reject,
            "best_shadow_max_edge": round(self.to_float(best.get("max_edge"), 0.0), 4),
            "stable_shadow_candidates": int(snapshot.get("stable_shadow_candidates", 0) or 0),
            "unstable_shadow_candidates": int(snapshot.get("unstable_shadow_candidates", 0) or 0),
            "edge_above_cost_count": int(snapshot.get("edge_above_cost_count", 0) or 0),
            "edge_below_cost_count": int(snapshot.get("edge_below_cost_count", 0) or 0),
            "top_reject_reason": snapshot.get("top_reject_reason") or "none",
            "readiness_state": snapshot.get("readiness_state") or readiness_state,
            "legacy_readiness_state": snapshot.get("legacy_readiness_state") or readiness_state,
            "readiness_score": snapshot.get("readiness_score") if snapshot.get("readiness_score") is not None else readiness_score,
            "microstructure_summary": snapshot.get("microstructure_summary") or {},
            "reactivation_candidates_count": int(reactivation_summary.get("reactivation_candidates_count", 0) or 0),
            "improving_candidates_count": int(reactivation_summary.get("improving_candidates_count", 0) or 0),
            "unstable_candidates_count": int(reactivation_summary.get("unstable_candidates_count", 0) or 0),
            "best_reactivation_ticker": reactivation_summary.get("best_reactivation_ticker"),
            "best_reactivation_family": reactivation_summary.get("best_reactivation_family"),
            "best_reactivation_score": reactivation_summary.get("best_reactivation_score"),
            "best_priority_ticker": adaptive_priority_summary.get("best_priority_ticker"),
            "best_priority_family": adaptive_priority_summary.get("best_priority_family"),
            "best_priority_score": adaptive_priority_summary.get("best_priority_score"),
            "priority_watch_count": int(adaptive_priority_summary.get("priority_watch_count", 0) or 0),
            "high_priority_count": int(adaptive_priority_summary.get("high_priority_count", 0) or 0),
            "best_learning_family": learning_summary.get("best_learning_family"),
            "worst_learning_family": learning_summary.get("worst_learning_family"),
            "best_learning_ticker": learning_summary.get("best_learning_ticker"),
            "strongest_watch_count": int(learning_summary.get("strongest_watch_count", 0) or 0),
            "avoid_count": int(learning_summary.get("avoid_count", 0) or 0),
            "improving_count": int(learning_summary.get("improving_count", 0) or 0),
            "improving_regime_count": int(predictive_regime_summary.get("improving_regime_count", 0) or 0),
            "decaying_regime_count": int(predictive_regime_summary.get("decaying_regime_count", 0) or 0),
            "strongest_predictive_family": predictive_regime_summary.get("strongest_predictive_family"),
            "strongest_predictive_ticker": predictive_regime_summary.get("strongest_predictive_ticker"),
            "top_predictive_score": predictive_regime_summary.get("top_predictive_score"),
            "top_transition": predictive_regime_summary.get("top_transition"),
        }
        self.shadow_arb_canary_readiness_last_summary_ts = now
        self.shadow_arb_canary_readiness_last_state = dashboard.get("readiness_state")
        print("[LIVE-ARB-CANARY-READINESS-DASHBOARD] " + json.dumps(dashboard, sort_keys=True, default=str))
        dashboard_state = dashboard.get("readiness_state")
        if dashboard_state != getattr(self, "shadow_arb_canary_readiness_last_telegram_state", None):
            self.shadow_arb_canary_readiness_last_telegram_state = dashboard_state
            if (os.environ.get("TELEGRAM_BOT_TOKEN", "") or "").strip() and (os.environ.get("TELEGRAM_CHAT_ID", "") or "").strip():
                if now - float(getattr(self, "shadow_arb_canary_readiness_last_telegram_ts", 0.0) or 0.0) >= 180.0:
                    self.shadow_arb_canary_readiness_last_telegram_ts = now
                    send_telegram_message(
                        f"Realm XXXV canary readiness changed: {dashboard_state} | blocker={top_blocker} | score={readiness_score:.3f}"
                    )
        return dashboard

    def _build_trade_readiness_snapshot(
        self,
        *,
        total_markets_scanned=0,
        candidates_reaching_prefilter=0,
        candidates_passing_adaptive_spread=0,
        candidates_passing_momentum=0,
        candidates_reaching_phase55=0,
        candidates_blocked_by_execution_safety=0,
        candidate_records=None,
        best_prefilter_candidate=None,
        prefilter_reject_reason_counts=None,
        strict_reject_reason_counts=None,
        decision_skip_reasons=None,
        activation_denial_counts=None,
        selected_candidate=None,
        selected_trade_submitted=False,
    ):
        candidate_records = list(candidate_records or [])
        combined_rejection_counts = Counter()
        for source_counts in (
            prefilter_reject_reason_counts or {},
            strict_reject_reason_counts or {},
            decision_skip_reasons or {},
            activation_denial_counts or {},
        ):
            for reason, count in source_counts.items():
                combined_rejection_counts[str(reason)] += int(count or 0)
        best_candidate = selected_candidate if isinstance(selected_candidate, dict) else None
        if best_candidate is None:
            if candidate_records:
                best_candidate = max(
                    candidate_records,
                    key=lambda item: (
                        self.to_float(item.get("candidate_score"), -9999.0),
                        self.to_float(item.get("probability_confidence"), -9999.0),
                    ),
                )
            elif isinstance(best_prefilter_candidate, dict):
                best_candidate = dict(best_prefilter_candidate)
        nearest_pass_candidate = None
        if not selected_trade_submitted:
            rejected_candidates = [item for item in candidate_records if str(item.get("decision") or "").upper() != "BUY"]
            if rejected_candidates:
                nearest_pass_candidate = max(
                    rejected_candidates,
                    key=lambda item: (
                        self.to_float(item.get("candidate_score"), -9999.0),
                        self.to_float(item.get("probability_confidence"), -9999.0),
                    ),
                )
            elif isinstance(best_prefilter_candidate, dict) and not candidate_records:
                nearest_pass_candidate = dict(best_prefilter_candidate)
        if nearest_pass_candidate is None and candidate_records:
            nearest_pass_candidate = max(
                candidate_records,
                key=lambda item: (
                    self.to_float(item.get("candidate_score"), -9999.0),
                    self.to_float(item.get("probability_confidence"), -9999.0),
                ),
            )
        nearest_pass_reason = "no_viable_candidate"
        if nearest_pass_candidate is not None:
            nearest_pass_reason = self._classify_trade_readiness_nearest_pass(nearest_pass_candidate)
        top_blockers = combined_rejection_counts.most_common(3)
        top_rejection_reason = top_blockers[0][0] if top_blockers else "no_viable_candidate"
        best_candidate_ticker = None
        best_candidate_family = None
        best_candidate_score = None
        best_candidate_confidence = None
        if isinstance(best_candidate, dict):
            best_candidate_ticker = best_candidate.get("ticker")
            best_candidate_family = best_candidate.get("family")
            best_candidate_score = best_candidate.get("candidate_score")
            best_candidate_confidence = best_candidate.get("probability_confidence")
            if best_candidate_confidence is None:
                score_breakdown = best_candidate.get("score_breakdown")
                if isinstance(score_breakdown, dict):
                    best_candidate_confidence = score_breakdown.get("confidence")
        snapshot = {
            "enabled": bool(AION_CALIBRATION_MODE or AION_CALIBRATION_RELAXED_SHADOW),
            "calibration_mode": bool(AION_CALIBRATION_MODE),
            "relaxed_shadow": bool(AION_CALIBRATION_RELAXED_SHADOW),
            "total_markets_scanned": int(total_markets_scanned or 0),
            "candidates_reaching_prefilter": int(candidates_reaching_prefilter or 0),
            "candidates_passing_adaptive_spread": int(candidates_passing_adaptive_spread or 0),
            "candidates_passing_momentum": int(candidates_passing_momentum or 0),
            "candidates_reaching_phase55": int(candidates_reaching_phase55 or 0),
            "candidates_blocked_by_execution_safety": int(candidates_blocked_by_execution_safety or 0),
            "best_candidate_ticker": best_candidate_ticker,
            "best_candidate_family": best_candidate_family,
            "best_candidate_score": best_candidate_score,
            "best_candidate_confidence": best_candidate_confidence,
            "top_rejection_reason": top_rejection_reason,
            "nearest_pass_reason": nearest_pass_reason,
            "suggested_next_condition": self._trade_readiness_next_condition(nearest_pass_reason),
            "top_blockers": top_blockers,
        }
        return snapshot

    def _maybe_emit_trade_readiness_snapshot(self, snapshot, *, selected_trade_submitted=False, no_trade=False, shadow_record=None):
        snapshot = snapshot if isinstance(snapshot, dict) else {}
        if not snapshot.get("enabled"):
            return None
        now = time.time()
        if snapshot.get("calibration_mode") and (now - float(getattr(self, "trade_readiness_last_summary_ts", 0.0) or 0.0)) >= 60.0:
            self.trade_readiness_last_summary_ts = now
            self.last_trade_readiness_snapshot = snapshot
            print(
                f"[LIVE-TRADE-READINESS] scanned_count={snapshot.get('scanned_count', snapshot.get('total_markets_scanned'))} "
                f"candidate_count={snapshot.get('candidate_count', snapshot.get('candidates_reaching_prefilter'))} "
                f"calibration_mode={1 if snapshot.get('calibration_mode') else 0} relaxed_shadow={1 if snapshot.get('relaxed_shadow') else 0} "
                f"total_markets_scanned={snapshot.get('total_markets_scanned')} "
                f"candidates_reaching_prefilter={snapshot.get('candidates_reaching_prefilter')} "
                f"candidates_passing_adaptive_spread={snapshot.get('candidates_passing_adaptive_spread')} "
                f"candidates_passing_momentum={snapshot.get('candidates_passing_momentum')} "
                f"candidates_reaching_phase55={snapshot.get('candidates_reaching_phase55')} "
                f"candidates_blocked_by_execution_safety={snapshot.get('candidates_blocked_by_execution_safety')} "
                f"best_ticker={snapshot.get('best_candidate_ticker')} best_family={snapshot.get('best_candidate_family')} "
                f"best_candidate_score={snapshot.get('best_candidate_score')} best_candidate_confidence={snapshot.get('best_candidate_confidence')} "
                f"top_blocker={(snapshot.get('top_blockers') or [('no_viable_candidate', 1)])[0][0] if snapshot.get('top_blockers') else snapshot.get('top_rejection_reason')} "
                f"nearest_pass_reason={snapshot.get('nearest_pass_reason')} "
                f"top_blockers={snapshot.get('top_blockers')}"
            )
        if no_trade and snapshot.get("calibration_mode") and (now - float(getattr(self, "trade_readiness_last_no_trade_ts", 0.0) or 0.0)) >= 90.0:
            self.trade_readiness_last_no_trade_ts = now
            print(
                f"[LIVE-NO-TRADE-WHY] scanned_count={snapshot.get('scanned_count', snapshot.get('total_markets_scanned'))} "
                f"candidate_count={snapshot.get('candidate_count', snapshot.get('candidates_reaching_prefilter'))} "
                f"calibration_mode={1 if snapshot.get('calibration_mode') else 0} relaxed_shadow={1 if snapshot.get('relaxed_shadow') else 0} "
                f"top_blocker={(snapshot.get('top_blockers') or [('no_viable_candidate', 1)])[0][0] if snapshot.get('top_blockers') else snapshot.get('top_rejection_reason')} "
                f"best_ticker={snapshot.get('best_candidate_ticker')} best_family={snapshot.get('best_candidate_family')} "
                f"best_score={snapshot.get('best_candidate_score')} suggested_next_condition={snapshot.get('suggested_next_condition')} "
                f"nearest_pass_reason={snapshot.get('nearest_pass_reason')}"
            )
        if snapshot.get("relaxed_shadow") and (now - float(getattr(self, "trade_readiness_last_shadow_ts", 0.0) or 0.0)) >= 120.0:
            self.trade_readiness_last_shadow_ts = now
            self.last_trade_readiness_snapshot = snapshot
            shadow_details = shadow_record if isinstance(shadow_record, dict) else {}
            print(
                f"[LIVE-TRADE-READINESS-SHADOW] scanned_count={snapshot.get('scanned_count', snapshot.get('total_markets_scanned'))} "
                f"candidate_count={snapshot.get('candidate_count', snapshot.get('candidates_reaching_prefilter'))} "
                f"calibration_mode={1 if snapshot.get('calibration_mode') else 0} relaxed_shadow={1 if snapshot.get('relaxed_shadow') else 0} "
                f"would_have_passed={'yes' if bool(shadow_details.get('would_have_passed')) else 'no'} "
                f"soft_score_threshold={shadow_details.get('soft_score_threshold')} soft_spread_limit={shadow_details.get('soft_spread_limit')} "
                f"soft_liquidity_threshold={shadow_details.get('soft_liquidity_threshold')} "
                f"best_ticker={snapshot.get('best_candidate_ticker')} best_family={snapshot.get('best_candidate_family')} "
                f"best_candidate_score={snapshot.get('best_candidate_score')} best_candidate_confidence={snapshot.get('best_candidate_confidence')} "
                f"nearest_pass_reason={snapshot.get('nearest_pass_reason')} top_blocker={(snapshot.get('top_blockers') or [('no_viable_candidate', 1)])[0][0] if snapshot.get('top_blockers') else snapshot.get('top_rejection_reason')} "
                f"top_blockers={snapshot.get('top_blockers')}"
            )
        return snapshot

    def _classify_trade_readiness_nearest_pass(self, candidate=None):
        candidate = candidate if isinstance(candidate, dict) else {}
        decision_reason = str(candidate.get("decision_reason") or "").strip().lower()
        phase55_status = str(candidate.get("phase55_status") or "").strip().lower()
        entry_ready_reason = str(candidate.get("entry_ready_reason") or "").strip().lower()
        reject_reason = str(candidate.get("reject_reason") or "").strip().lower()
        score_breakdown = candidate.get("score_breakdown") if isinstance(candidate.get("score_breakdown"), dict) else {}
        if candidate.get("execution_safety_blocked") or phase55_status in {"immediate_reject", "probability_block", "capital_block", "psychology_block"}:
            return "execution_safety_block"
        if decision_reason in {"wide_spread", "poor_spread_score", "spread_too_wide"}:
            return "spread_near_pass"
        if decision_reason in {"low_liquidity_score", "low_liquidity", "not_tradable"}:
            return "liquidity_near_pass"
        if decision_reason in {"timing_penalty", "no_stochastic_crossover", "no_micro_pullback"}:
            return "continuity_near_pass" if decision_reason != "timing_penalty" else "momentum_near_pass"
        if phase55_status in {"pullback_wait", "trigger_wait"} or entry_ready_reason in {"no_micro_pullback", "no_stochastic_crossover", "standard_rules"}:
            return "phase55_near_pass" if phase55_status == "pullback_wait" else "continuity_near_pass"
        if reject_reason in {"insufficient_history", "insufficient_data"} or phase55_status == "insufficient_data":
            return "continuity_near_pass"
        if decision_reason in {"low_score"}:
            liquidity_component = self.to_float(score_breakdown.get("liquidity"), 0.0) if isinstance(score_breakdown, dict) else 0.0
            spread_component = self.to_float(score_breakdown.get("spread"), 0.0) if isinstance(score_breakdown, dict) else 0.0
            timing_component = self.to_float(score_breakdown.get("timing"), 0.0) if isinstance(score_breakdown, dict) else 0.0
            if spread_component < 10.0 and spread_component <= liquidity_component:
                return "spread_near_pass"
            if liquidity_component < 10.0 and liquidity_component <= timing_component:
                return "liquidity_near_pass"
            if timing_component < 5.0:
                return "momentum_near_pass"
            return "phase55_near_pass"
        if phase55_status == "entry_ready":
            return "no_viable_candidate"
        return "no_viable_candidate"

    def _trade_readiness_next_condition(self, nearest_pass_reason):
        mapping = {
            "spread_near_pass": "needs tighter spread",
            "liquidity_near_pass": "needs stronger liquidity",
            "momentum_near_pass": "needs stronger directional momentum",
            "continuity_near_pass": "needs continuity confirmation",
            "phase55_near_pass": "waiting for Phase 5.5 pullback",
            "execution_safety_block": "execution safety must clear",
            "no_viable_candidate": "waiting for a viable candidate",
        }
        return mapping.get(str(nearest_pass_reason or "").strip().lower(), "waiting for a viable candidate")

    def _build_profit_target_guidance(
        self,
        *,
        trade_readiness_records=None,
        failure_summary=None,
        candidate_expectancy=None,
        candidate_score=None,
        spread_bucket=None,
        quote_stability=None,
        edge_durability=None,
        execution_survivability=None,
        near_miss_count=0,
        family=None,
        ticker=None,
    ):
        trade_readiness_records = list(trade_readiness_records or [])
        failure_summary = failure_summary if isinstance(failure_summary, dict) else {}
        state = getattr(self, "aion_expectancy_state", None)
        if not isinstance(state, dict):
            state = self._build_aion_expectancy_default_state()
        now = time.time()
        today = time.strftime("%Y-%m-%d")
        today_dt = None
        try:
            today_dt = datetime.strptime(today, "%Y-%m-%d")
        except Exception:
            today_dt = None
        history = list(state.get("profit_history") or [])
        history_map = {}
        for entry in history:
            if not isinstance(entry, dict):
                continue
            entry_day = str(entry.get("date") or entry.get("snapshot_day") or "").strip()
            if entry_day:
                history_map[entry_day] = dict(entry)
        current_day_entry = {
            "date": today,
            "realized_pnl_today": round(float(getattr(self, "live_realized_pnl_today", 0.0) or 0.0), 4),
            "realized_pnl_week": round(float(getattr(self, "live_realized_pnl_today", 0.0) or 0.0), 4),
            "realized_pnl_month": round(float(getattr(self, "live_realized_pnl_today", 0.0) or 0.0), 4),
            "trades_today": int(getattr(self, "live_perf_trades_today", getattr(self, "live_trade_count_today", 0)) or 0),
            "wins_today": int(getattr(self, "live_perf_wins_today", 0) or 0),
            "losses_today": int(getattr(self, "live_perf_losses_today", 0) or 0),
        }
        history_map[today] = current_day_entry
        profit_history = list(history_map.values())
        weekly_pnl = 0.0
        monthly_pnl = 0.0
        if today_dt is not None:
            for entry in profit_history:
                entry_day = str(entry.get("date") or entry.get("snapshot_day") or "").strip()
                if not entry_day:
                    continue
                try:
                    entry_dt = datetime.strptime(entry_day, "%Y-%m-%d")
                except Exception:
                    continue
                delta_days = (today_dt - entry_dt).days
                pnl_value = self.to_float(entry.get("realized_pnl_today"), 0.0)
                if 0 <= delta_days <= 6:
                    weekly_pnl += pnl_value
                if 0 <= delta_days <= 29:
                    monthly_pnl += pnl_value
        else:
            weekly_pnl = float(self.live_realized_pnl_today or 0.0)
            monthly_pnl = float(self.live_realized_pnl_today or 0.0)
        realized_today = float(getattr(self, "live_realized_pnl_today", 0.0) or 0.0)
        daily_target = max(0.0, self.to_float(AION_DAILY_PROFIT_TARGET, 0.0))
        weekly_target = max(0.0, self.to_float(AION_WEEKLY_PROFIT_TARGET, 0.0))
        monthly_target = max(0.0, self.to_float(AION_MONTHLY_PROFIT_TARGET, 0.0))
        profit_vs_daily_target = realized_today - daily_target
        profit_vs_weekly_target = weekly_pnl - weekly_target
        profit_vs_monthly_target = monthly_pnl - monthly_target
        start_ts = float(getattr(self, "live_perf_day_start_ts", 0.0) or 0.0)
        if start_ts <= 0.0:
            start_ts = float(getattr(self, "last_live_trade_ts", 0.0) or 0.0)
        if start_ts <= 0.0:
            start_ts = float(getattr(self, "trade_readiness_last_no_trade_ts", 0.0) or 0.0)
        elapsed_hours = max(0.0, (now - start_ts) / 3600.0) if start_ts > 0.0 else 0.0
        pnl_velocity_per_hour = realized_today / max(elapsed_hours, 0.25) if elapsed_hours > 0.0 else 0.0
        remaining_hours = max(0.0, 24.0 - elapsed_hours) if elapsed_hours > 0.0 else 0.0
        projected_end_of_day_pnl = realized_today + (pnl_velocity_per_hour * remaining_hours)
        trades_today = int(getattr(self, "live_perf_trades_today", getattr(self, "live_trade_count_today", 0)) or 0)
        wins_today = int(getattr(self, "live_perf_wins_today", 0) or 0)
        losses_today = int(getattr(self, "live_perf_losses_today", 0) or 0)
        average_profit_per_trade = realized_today / max(trades_today, 1)
        if trade_readiness_records:
            expectancy_samples = []
            for item in trade_readiness_records:
                if not isinstance(item, dict):
                    continue
                expectancy_samples.append(self.to_float(item.get("expectancy_score"), self.to_float(item.get("candidate_score"), 0.0)))
            average_expectancy = sum(expectancy_samples) / max(len(expectancy_samples), 1)
            positive_expectancy_rate = sum(1 for value in expectancy_samples if value >= 0.55) / max(len(expectancy_samples), 1)
            opportunity_density = min(1.0, positive_expectancy_rate)
            expectancy_quality = self._clamp((average_expectancy * 0.6) + (positive_expectancy_rate * 0.4))
        else:
            opportunity_density = 0.0
            expectancy_quality = self._clamp(0.0 if realized_today <= 0.0 else min(1.0, realized_today / max(daily_target or 1.0, 1.0)))
        rejection_reason_counts = dict(failure_summary.get("reason_counts") or {})
        negative_expectancy_block_count = 0
        for key in ("edge_below_cost", "edge_at_or_below_zero", "negative_expectancy", "sports_edge_below_cost", "sports_edge_after_cost_negative", "expectancy_negative"):
            negative_expectancy_block_count += int(rejection_reason_counts.get(key, 0) or 0)
        near_miss_pressure = min(1.0, max(0.0, self.to_float(near_miss_count, 0.0)) / 5.0)
        inactivity_seconds = max(
            0.0,
            now
            - max(
                float(getattr(self, "last_live_trade_ts", 0.0) or 0.0),
                float(getattr(self, "trade_readiness_last_no_trade_ts", 0.0) or 0.0),
                float(getattr(self, "last_daily_profitability_dashboard_ts", 0.0) or 0.0),
            ),
        )
        inactivity_hours = inactivity_seconds / 3600.0 if inactivity_seconds > 0.0 else 0.0
        low_activity_pressure = 1.0 if trades_today < 2 else 0.6 if trades_today < 5 else 0.0
        inactivity_pressure = min(1.0, inactivity_hours / 6.0)
        target_pressure = 0.0
        if daily_target > 0.0:
            target_pressure = min(1.0, max(0.0, (daily_target - realized_today) / daily_target))
        if weekly_target > 0.0:
            target_pressure = max(target_pressure, min(1.0, max(0.0, (weekly_target - weekly_pnl) / weekly_target) * 0.75))
        if monthly_target > 0.0:
            target_pressure = max(target_pressure, min(1.0, max(0.0, (monthly_target - monthly_pnl) / monthly_target) * 0.6))
        defensive_mode = bool(
            realized_today <= -max(10.0, daily_target * 0.6 if daily_target > 0.0 else 10.0)
            or (trades_today >= 4 and wins_today <= losses_today and realized_today < 0.0)
            or (int(getattr(self, "relaxation_trades_today", 0) or 0) >= 2 and float(getattr(self, "relaxation_trade_pnl_today", 0.0) or 0.0) < 0.0)
        )
        if defensive_mode:
            target_pressure = max(0.0, target_pressure - 0.35)
        current_expansion_level = self._clamp(
            (target_pressure * 0.45)
            + ((1.0 - opportunity_density) * 0.15)
            + (low_activity_pressure * 0.20)
            + (inactivity_pressure * 0.20)
        )
        if defensive_mode:
            current_expansion_level = max(0.0, current_expansion_level - 0.35)
        current_expansion_level = round(min(1.0, current_expansion_level), 4)
        opportunity_expansion_active = bool(
            AION_PROFIT_EXPANSION_ENABLED
            and AION_EXPECTANCY_SCORE_ENABLED
            and not defensive_mode
            and current_expansion_level >= 0.25
            and (realized_today < daily_target if daily_target > 0.0 else trades_today < 3)
        )
        strongest_candidate_edge = None
        strongest_candidate_family = None
        strongest_candidate_expectancy = None
        if trade_readiness_records:
            best_candidate = max(
                (item for item in trade_readiness_records if isinstance(item, dict)),
                key=lambda item: (
                    self.to_float(item.get("expectancy_score"), self.to_float(item.get("candidate_score"), 0.0)),
                    self.to_float(item.get("sports_edge_after_cost"), -9e9),
                    self.to_float(item.get("candidate_score"), 0.0),
                ),
                default=None,
            )
            if isinstance(best_candidate, dict):
                strongest_candidate_family = best_candidate.get("family")
                strongest_candidate_expectancy = self.to_float(best_candidate.get("expectancy_score"), self.to_float(best_candidate.get("candidate_score"), 0.0))
                strongest_candidate_edge = self.to_float(
                    best_candidate.get("sports_edge_after_cost"),
                    self.to_float(best_candidate.get("expectancy_score"), self.to_float(best_candidate.get("candidate_score"), 0.0)),
                )
        candidate_expectancy_score = self.to_float(candidate_expectancy, 0.0)
        candidate_score_value = self.to_float(candidate_score, 0.0)
        spread_bucket = str(spread_bucket or "").strip().lower()
        quote_stability = self._clamp(self.to_float(quote_stability, 0.5))
        edge_durability = self._clamp(self.to_float(edge_durability, 0.5))
        execution_survivability = self._clamp(self.to_float(execution_survivability, 0.5))
        positive_candidate = bool(candidate_expectancy_score >= 0.55 or candidate_score_value >= (PHASE5_BUY_SCORE_THRESHOLD - 5.0))
        spread_factor = {
            "ultra_tight": 1.0,
            "tight": 0.85,
            "acceptable": 0.60,
            "wide_but_possible": 0.30,
        }.get(spread_bucket, 0.0)
        quality_factor = self._clamp(
            (quote_stability * 0.40) + (edge_durability * 0.35) + (execution_survivability * 0.25)
        )
        profit_target_priority_adjustment = 0.0
        if opportunity_expansion_active and positive_candidate and spread_factor > 0.0:
            profit_target_priority_adjustment = min(
                0.012,
                0.012
                * current_expansion_level
                * max(0.15, min(1.0, candidate_expectancy_score if candidate_expectancy_score > 0.0 else candidate_score_value / max(PHASE5_BUY_SCORE_THRESHOLD, 1.0)))
                * max(0.20, spread_factor)
                * max(0.45, quality_factor)
            )
        guidance = {
            "profit_target_mode": AION_PROFIT_TARGET_MODE,
            "snapshot_day": today,
            "realized_pnl_today": round(realized_today, 4),
            "realized_pnl_week": round(weekly_pnl, 4),
            "realized_pnl_month": round(monthly_pnl, 4),
            "profit_vs_daily_target": round(profit_vs_daily_target, 4),
            "profit_vs_weekly_target": round(profit_vs_weekly_target, 4),
            "profit_vs_monthly_target": round(profit_vs_monthly_target, 4),
            "daily_profit_target": round(daily_target, 4),
            "weekly_profit_target": round(weekly_target, 4),
            "monthly_profit_target": round(monthly_target, 4),
            "percent_to_target": round((realized_today / max(daily_target, 1.0)) * 100.0, 4) if daily_target > 0.0 else 0.0,
            "pnl_velocity_per_hour": round(pnl_velocity_per_hour, 4),
            "projected_end_of_day_pnl": round(projected_end_of_day_pnl, 4),
            "average_profit_per_trade": round(average_profit_per_trade, 4),
            "expectancy_quality": round(expectancy_quality, 4),
            "opportunity_density": round(opportunity_density, 4),
            "current_expansion_level": current_expansion_level,
            "opportunity_expansion_active": bool(opportunity_expansion_active),
            "target_pressure": round(target_pressure, 4),
            "defensive_mode": bool(defensive_mode),
            "strongest_candidate_edge": round(self.to_float(strongest_candidate_edge, 0.0), 4) if strongest_candidate_edge is not None else None,
            "strongest_candidate_family": strongest_candidate_family,
            "strongest_candidate_expectancy": round(self.to_float(strongest_candidate_expectancy, 0.0), 4) if strongest_candidate_expectancy is not None else None,
            "negative_expectancy_block_count": int(negative_expectancy_block_count),
            "trades_today": trades_today,
            "wins_today": wins_today,
            "losses_today": losses_today,
            "trade_count": int(len(trade_readiness_records or [])),
            "near_miss_count": int(near_miss_count or 0),
            "family": str(family or "UNKNOWN").strip().upper() or "UNKNOWN",
            "ticker": str(ticker or "").strip() or None,
            "profit_target_priority_adjustment": round(profit_target_priority_adjustment, 4),
            "opportunity_expansion_reason": (
                "defensive_mode"
                if defensive_mode
                else "below_target_low_activity"
                if target_pressure >= 0.35 and trades_today < 3
                else "expansion_enabled"
                if opportunity_expansion_active
                else "guidance_only"
            ),
        }
        return guidance

    def _emit_profit_target_guidance(self, *, trade_readiness_records=None, failure_summary=None, force=False):
        summary = self._build_profit_target_guidance(
            trade_readiness_records=trade_readiness_records,
            failure_summary=failure_summary,
        )
        now = time.time()
        last_emit = float(getattr(self, "last_profit_target_guidance_ts", 0.0) or 0.0)
        if not force and (now - last_emit) < 180.0:
            return getattr(self, "last_profit_target_guidance", {}) or summary
        self.last_profit_target_guidance_ts = now
        self.last_profit_target_guidance = dict(summary)
        self._refresh_aion_expectancy_state(
            profit_target_summary=summary,
            relaxation_trade_count_today=self.relaxation_trades_today,
            force_save=force,
        )
        print("[AION-PROFIT-TARGET-GUIDANCE] " + json.dumps(summary, sort_keys=True, default=str))
        if summary.get("defensive_mode"):
            defensive_payload = {
                "profit_target_mode": summary.get("profit_target_mode"),
                "realized_pnl_today": summary.get("realized_pnl_today"),
                "daily_profit_target": summary.get("daily_profit_target"),
                "current_expansion_level": summary.get("current_expansion_level"),
                "reason": summary.get("opportunity_expansion_reason"),
                "negative_expectancy_block_count": summary.get("negative_expectancy_block_count"),
            }
            print("[AION-PROFIT-DEFENSIVE-MODE] " + json.dumps(defensive_payload, sort_keys=True, default=str))
        return summary

    def _emit_profit_target_dashboard(self, *, trade_readiness_records=None, failure_summary=None, force=False):
        summary = self._build_profit_target_guidance(
            trade_readiness_records=trade_readiness_records,
            failure_summary=failure_summary,
        )
        now = time.time()
        last_emit = float(getattr(self, "last_profit_target_dashboard_ts", 0.0) or 0.0)
        if not force and (now - last_emit) < 180.0:
            return getattr(self, "last_profit_target_dashboard", {}) or summary
        dashboard = {
            "realized_pnl_today": summary.get("realized_pnl_today"),
            "daily_profit_target": summary.get("daily_profit_target"),
            "percent_to_target": summary.get("percent_to_target"),
            "projected_end_of_day_pnl": summary.get("projected_end_of_day_pnl"),
            "trades_today": summary.get("trades_today"),
            "average_profit_per_trade": summary.get("average_profit_per_trade"),
            "current_expansion_level": summary.get("current_expansion_level"),
            "opportunity_expansion_active": summary.get("opportunity_expansion_active"),
            "strongest_candidate_edge": summary.get("strongest_candidate_edge"),
            "strongest_candidate_family": summary.get("strongest_candidate_family"),
            "strongest_candidate_expectancy": summary.get("strongest_candidate_expectancy"),
            "negative_expectancy_block_count": summary.get("negative_expectancy_block_count"),
            "opportunity_density": summary.get("opportunity_density"),
            "profit_vs_daily_target": summary.get("profit_vs_daily_target"),
            "profit_vs_weekly_target": summary.get("profit_vs_weekly_target"),
            "profit_vs_monthly_target": summary.get("profit_vs_monthly_target"),
            "pnl_velocity_per_hour": summary.get("pnl_velocity_per_hour"),
            "realized_pnl_week": summary.get("realized_pnl_week"),
            "realized_pnl_month": summary.get("realized_pnl_month"),
            "profit_target_mode": summary.get("profit_target_mode"),
            "inactivity_minutes": round(
                max(
                    0.0,
                    (time.time() - max(
                        float(getattr(self, "last_live_trade_ts", 0.0) or 0.0),
                        float(getattr(self, "trade_readiness_last_no_trade_ts", 0.0) or 0.0),
                    )) / 60.0,
                ),
                2,
            ),
            "scan_cycle_count": int(getattr(self, "cycle_count", 0) or 0),
            "live_arb_enabled": bool(AION_LIVE_ARB_ENABLED),
        }
        self.last_profit_target_dashboard_ts = now
        self.last_profit_target_dashboard = dict(dashboard)
        self._refresh_aion_expectancy_state(
            profit_target_summary=dashboard,
            relaxation_trade_count_today=self.relaxation_trades_today,
            force_save=force,
        )
        print("[AION-PROFIT-TARGET-DASHBOARD] " + json.dumps(dashboard, sort_keys=True, default=str))
        return dashboard

    def _build_aion_activity_dashboard(self, *, trade_readiness_records=None, failure_summary=None, profit_target_summary=None):
        trade_readiness_records = list(trade_readiness_records or [])
        failure_summary = failure_summary if isinstance(failure_summary, dict) else {}
        profit_target_summary = profit_target_summary if isinstance(profit_target_summary, dict) else {}
        live_summary = dict(getattr(self, "last_live_select_summary", {}) or {})
        aion_state = getattr(self, "aion_expectancy_state", None)
        if not isinstance(aion_state, dict):
            aion_state = {}
        shadow_trades = list(aion_state.get("shadow_trades") or [])
        profit_history = list(aion_state.get("profit_history") or [])
        ticker_near_pass = dict(aion_state.get("ticker_near_pass_summary") or {})
        family_expectancy = dict(aion_state.get("family_expectancy_summary") or {})
        opportunity_density = self.to_float(profit_target_summary.get("opportunity_density"), 0.0)
        current_expansion_level = self.to_float(profit_target_summary.get("current_expansion_level"), 0.0)
        activity_state = "idle"
        if trade_readiness_records:
            activity_state = "active"
        elif live_summary.get("candidates_found", 0) or live_summary.get("within_window", 0):
            activity_state = "observing"
        if current_expansion_level >= 0.35 and not profit_target_summary.get("defensive_mode"):
            activity_state = "expanding"
        if profit_target_summary.get("defensive_mode"):
            activity_state = "defensive"
        expansion_active = bool(profit_target_summary.get("opportunity_expansion_active"))
        dashboard = {
            "cycle_id": int(self.cycle_count or 0),
            "scan_cycle_count": int(getattr(self, "cycle_count", 0) or 0),
            "activity_state": activity_state,
            "scan_candidates": int(live_summary.get("candidates_found", len(trade_readiness_records)) or 0),
            "trade_readiness_records": int(len(trade_readiness_records)),
            "shadow_watchlist_count": int(len(self.shadow_trade_watchlist_by_ticker or {})),
            "shadow_trade_count": int(len(shadow_trades)),
            "near_pass_count": int(sum(int(item.get("near_pass_count", 0) or 0) for item in (self.shadow_trade_watchlist_by_ticker or {}).values() if isinstance(item, dict))),
            "ticker_near_pass_count": int(len(ticker_near_pass)),
            "family_profile_count": int(len(family_expectancy)),
            "profit_history_count": int(len(profit_history)),
            "opportunity_expansion_active": bool(expansion_active),
            "current_expansion_level": round(current_expansion_level, 4),
            "opportunity_density": round(opportunity_density, 4),
            "inactivity_minutes": round(
                max(
                    0.0,
                    (time.time() - max(
                        float(getattr(self, "last_live_trade_ts", 0.0) or 0.0),
                        float(getattr(self, "trade_readiness_last_no_trade_ts", 0.0) or 0.0),
                    )) / 60.0,
                ),
                2,
            ),
            "best_candidate_ticker": live_summary.get("best_candidate_ticker") or live_summary.get("selected_ticker"),
            "best_candidate_family": live_summary.get("best_candidate_family") or live_summary.get("selected_family"),
            "best_candidate_score": live_summary.get("best_candidate_score"),
            "best_candidate_expectancy": live_summary.get("best_candidate_expectancy"),
            "best_rejected_ticker": failure_summary.get("best_rejected_ticker"),
            "best_rejected_family": failure_summary.get("best_rejected_family"),
            "best_rejected_score": failure_summary.get("best_rejected_score"),
            "most_common_rejection_reason": failure_summary.get("top_failure_reason") or "unknown",
            "live_arb_enabled": bool(AION_LIVE_ARB_ENABLED),
        }
        return dashboard

    def _emit_aion_activity_dashboard(self, *, trade_readiness_records=None, failure_summary=None, profit_target_summary=None, force=False):
        now = time.time()
        last_emit = float(getattr(self, "last_aion_activity_dashboard_ts", 0.0) or 0.0)
        if not force and (now - last_emit) < 180.0:
            return getattr(self, "last_aion_activity_dashboard", {}) or {}
        dashboard = self._build_aion_activity_dashboard(
            trade_readiness_records=trade_readiness_records,
            failure_summary=failure_summary,
            profit_target_summary=profit_target_summary,
        )
        self.last_aion_activity_dashboard_ts = now
        self.last_aion_activity_dashboard = dict(dashboard)
        self._refresh_aion_expectancy_state(
            dashboard_summary=dashboard,
            relaxation_trade_count_today=self.relaxation_trades_today,
            force_save=False,
        )
        print("[AION-ACTIVITY-DASHBOARD] " + json.dumps(dashboard, sort_keys=True, default=str))
        expansion_payload = {
            "cycle_id": dashboard.get("cycle_id"),
            "activity_state": dashboard.get("activity_state"),
            "current_expansion_level": dashboard.get("current_expansion_level"),
            "opportunity_density": dashboard.get("opportunity_density"),
            "best_candidate_ticker": dashboard.get("best_candidate_ticker"),
            "best_candidate_family": dashboard.get("best_candidate_family"),
            "opportunity_expansion_active": bool(dashboard.get("opportunity_expansion_active")),
            "live_arb_enabled": bool(AION_LIVE_ARB_ENABLED),
        }
        print("[AION-OPPORTUNITY-EXPANSION] " + json.dumps(expansion_payload, sort_keys=True, default=str))
        return dashboard

    def _emit_aion_discovery_dashboard(self, *, markets=None, quotes=None, trade_readiness_records=None, failure_summary=None, discovery_scan_depth=None, force=False):
        markets = list(markets or [])
        quotes = list(quotes or [])
        trade_readiness_records = list(trade_readiness_records or [])
        failure_summary = failure_summary if isinstance(failure_summary, dict) else {}
        now = time.time()
        last_emit = float(getattr(self, "last_aion_discovery_dashboard_ts", 0.0) or 0.0)
        if not force and (now - last_emit) < 180.0:
            return getattr(self, "last_aion_discovery_dashboard", {}) or {}
        live_summary = dict(getattr(self, "last_live_select_summary", {}) or {})
        if discovery_scan_depth is None:
            discovery_scan_depth = self._get_aion_discovery_scan_depth()
        discovery_scan_depth = max(1, int(discovery_scan_depth or 1))
        total_markets_seen = int(
            live_summary.get("total_markets_scanned")
            or live_summary.get("scanned_count")
            or len(markets)
            or 0
        )
        candidates_after_prefilter = int(
            live_summary.get("candidates_reaching_prefilter")
            or live_summary.get("candidate_count")
            or len(trade_readiness_records)
            or len(quotes)
            or 0
        )
        candidates_after_strict_validation = int(
            live_summary.get("candidate_count")
            or live_summary.get("ranked_candidate_count")
            or len(trade_readiness_records)
            or len([quote for quote in quotes if getattr(quote, "yes_bid", None) is not None or getattr(quote, "yes_ask", None) is not None])
            or 0
        )
        best_record = None
        if trade_readiness_records:
            best_record = max(
                trade_readiness_records,
                key=lambda item: (
                    self.to_float(item.get("expectancy_score"), self.to_float(item.get("candidate_score"), 0.0)),
                    self.to_float(item.get("candidate_score"), 0.0),
                    self.to_float(item.get("sports_edge_after_cost"), -9e9),
                ),
            )
        top_family = (best_record or {}).get("family") or live_summary.get("best_candidate_family") or live_summary.get("selected_family")
        top_ticker = (best_record or {}).get("ticker") or live_summary.get("best_candidate_ticker") or live_summary.get("selected_ticker")
        top_score = self.to_float((best_record or {}).get("expectancy_score"), self.to_float((best_record or {}).get("candidate_score"), self.to_float(live_summary.get("best_candidate_score"), 0.0)))
        top_edge_after_cost = self.to_float((best_record or {}).get("sports_edge_after_cost"), self.to_float(live_summary.get("best_candidate_edge_after_cost"), self.to_float(self.last_sports_harvest_overall_summary.get("best_sports_edge_after_cost"), 0.0)))
        discovery_dashboard = {
            "total_markets_seen": total_markets_seen,
            "candidates_after_prefilter": candidates_after_prefilter,
            "candidates_after_strict_validation": candidates_after_strict_validation,
            "top_family": top_family,
            "top_ticker": top_ticker,
            "top_score": round(top_score, 4),
            "top_edge_after_cost": round(top_edge_after_cost, 4),
            "rejection_top_reason": failure_summary.get("top_failure_reason") or failure_summary.get("final_no_candidate_reason") or "unknown",
            "scan_depth": int(discovery_scan_depth),
            "expansion_level": round(self.to_float((self.last_profit_target_dashboard or self.last_profit_target_guidance or {}).get("current_expansion_level"), 0.0), 4),
            "live_arb_enabled": bool(AION_LIVE_ARB_ENABLED),
        }
        self.last_aion_discovery_dashboard = dict(discovery_dashboard)
        self.last_aion_discovery_dashboard_ts = now
        print("[AION-DISCOVERY-DASHBOARD] " + json.dumps(discovery_dashboard, sort_keys=True, default=str))
        return discovery_dashboard

    def _emit_aion_scan_heartbeat(self, *, trade_readiness_records=None, failure_summary=None, force=False):
        now = time.time()
        last_emit = float(getattr(self, "last_aion_scan_heartbeat_ts", 0.0) or 0.0)
        if not force and (now - last_emit) < 60.0:
            return False
        profit_summary = self._emit_profit_target_dashboard(
            trade_readiness_records=trade_readiness_records,
            failure_summary=failure_summary,
            force=True,
        )
        self._emit_aion_activity_dashboard(
            trade_readiness_records=trade_readiness_records,
            failure_summary=failure_summary,
            profit_target_summary=profit_summary or self.last_profit_target_dashboard or self.last_profit_target_guidance or {},
            force=True,
        )
        self.last_aion_scan_heartbeat_ts = now
        return True

