    def _emit_runonce_branch_event(self, phase, branch, payload=None, error=None):
        record = {
            "branch": branch,
            "cycle_count": int(getattr(self, "cycle_count", 0) or 0),
            "payload": payload if isinstance(payload, dict) else {},
        }
        if error is not None:
            record["error_type"] = error.__class__.__name__
            record["error_reason"] = str(error)
        print(f"[AION-RUNONCE-BRANCH-{phase}] " + json.dumps(record, sort_keys=True, default=str), flush=True)

    def _run_market_reachability_cycle(self, *, markets=None, quotes=None, quotes_by_ticker=None, markets_by_ticker=None, quote_hydration_summary=None, stage_label="post_quote_build"):
        markets = list(markets or [])
        quotes = list(quotes or [])
        quotes_by_ticker = quotes_by_ticker if isinstance(quotes_by_ticker, dict) else {}
        markets_by_ticker = markets_by_ticker if isinstance(markets_by_ticker, dict) else {}
        quote_hydration_summary = quote_hydration_summary if isinstance(quote_hydration_summary, dict) else {}
        cycle_started_at = time.time()
        markets_fetched_total = int(len(markets))
        quote_objects_total = int(len(quotes))
        hydration_attempted_total = int(quote_hydration_summary.get("attempted", 0) or 0)
        hydration_success_total = int(quote_hydration_summary.get("success", 0) or 0)
        hydration_failure_total = int(quote_hydration_summary.get("failure", 0) or 0)
        hydration_rejected = list(quote_hydration_summary.get("rejected", []) or [])[:5]
        market_families_seen = sorted(
            {
                str(self.get_market_family(market) or "").strip().upper() or "UNKNOWN"
                for market in markets
                if isinstance(market, dict)
            }
        )
        candidate_universe_total = markets_fetched_total if stage_label == "pre_quote_build" else max(quote_objects_total, markets_fetched_total)
        self._emit_runonce_branch_event(
            "START",
            "market_reachability",
            payload={
                "stage": stage_label,
                "markets_fetched_total": markets_fetched_total,
                "quote_objects_total": quote_objects_total,
                "market_families_seen": market_families_seen,
                "quote_hydration_attempted_total": hydration_attempted_total,
                "quote_hydration_success_total": hydration_success_total,
                "quote_hydration_failure_total": hydration_failure_total,
                "quote_hydration_rejected": hydration_rejected,
                "sports_scanned": False,
                "crypto_scanned": False,
                "open_market_scanned": False,
                "candidates_seen_total": candidate_universe_total,
                "eligible_candidates_total": 0,
                "best_family": None,
                "best_ticker": None,
                "best_edge": None,
                "no_trade_reason": "not_scanned_yet",
            },
        )
        overall_missing = Counter()
        branch_totals = {
            "sports": {"seen": 0, "eligible": 0, "best": None, "best_edge": None, "missing": Counter()},
            "crypto": {"seen": 0, "eligible": 0, "best": None, "best_edge": None, "missing": Counter()},
        }

        def _safe_eval_candidate(market, q, branch_name):
            market = market if isinstance(market, dict) else {}
            ticker = str(getattr(q, "ticker", "") or market.get("ticker", "") or "").strip()
            family = self.get_market_family(market or {"ticker": ticker})
            try:
                diag = self._diagnose_quote_readiness_context(
                    market=market,
                    q=q,
                    family=family,
                    sports_context={},
                    source=f"runonce_reachability_{branch_name}",
                ) or {}
            except Exception as exc:
                diag = {"quote_ready": False, "quote_ready_reason": exc.__class__.__name__}
            quote_ready = bool(diag.get("quote_ready"))
            spread_bucket = str(diag.get("spread_bucket") or "unknown").strip().lower() or "unknown"
            final_edge = self.to_float(diag.get("final_edge"), self.to_float(diag.get("sports_edge_after_cost"), 0.0))
            liquidity_depth = self.to_float(diag.get("liquidity_depth"), self.to_float(getattr(q, "liquidity", None), 0.0))
            lifecycle_state = str(diag.get("market_lifecycle_state") or self._get_sports_market_lifecycle_state(market=market, q=q, family=family, event_urgency=None) or "unknown").strip().lower() or "unknown"
            market_live = str(market.get("status") or "open").strip().lower() == "open"
            canonical_tradeability = diag.get("canonical_tradeability") if isinstance(diag.get("canonical_tradeability"), dict) else {}
            spread_classification = str(canonical_tradeability.get("spread_classification") or diag.get("spread_classification") or "UNSAFE").strip().upper() or "UNSAFE"
            safe_spread = spread_bucket in {"ultra_tight", "tight"} or spread_classification in {"SAFE", "AGGRESSIVE_BUT_TRADEABLE"}
            positive_edge = final_edge > 0.0
            lifecycle_allowed = lifecycle_state in {"pregame_near", "active_near", "live_early"}
            duplicate_status = "unknown"
            unsafe_price_detail = self._resolve_unsafe_price_detail(
                market=market,
                q=q,
                family=family,
                quote_diag=diag,
                source=f"runonce_reachability_{branch_name}",
            )
            unsafe_price_status = str(unsafe_price_detail.get("unsafe_price_status") or "unsafe").strip().lower() or "unsafe"
            duplicate_block = False
            unsafe_price_block = not quote_ready or (unsafe_price_status not in {"safe", "caution_wide_spread"} and spread_classification not in {"SAFE", "AGGRESSIVE_BUT_TRADEABLE"}) or not safe_spread
            try:
                duplicate_check = self.check_live_duplicate_position_api(ticker) if ticker else None
                if isinstance(duplicate_check, dict):
                    duplicate_block = bool(duplicate_check.get("blocked"))
                    duplicate_status = "blocked" if duplicate_block else "clear"
                else:
                    duplicate_status = "clear"
            except Exception as exc:
                duplicate_status = exc.__class__.__name__
            eligible = bool(
                quote_ready
                and safe_spread
                and positive_edge
                and lifecycle_allowed
                and market_live
                and liquidity_depth > 0.0
                and not duplicate_block
                and not unsafe_price_block
            )
            missing_reason = []
            if not quote_ready:
                missing_reason.append("no_quote_ready")
            if not safe_spread:
                missing_reason.append("unsafe_spread")
            if not positive_edge:
                missing_reason.append("edge_too_low")
            if not lifecycle_allowed:
                missing_reason.append("lifecycle_not_allowed")
            if duplicate_block:
                missing_reason.append("duplicate")
            if unsafe_price_block:
                missing_reason.append("unsafe_price")
            if not market_live:
                missing_reason.append("market_not_live")
            if liquidity_depth <= 0.0:
                missing_reason.append("no_liquidity")
            return {
                "ticker": ticker or None,
                "family": family,
                "quote_ready": quote_ready,
                "quote_ready_reason": diag.get("quote_ready_reason"),
                "spread_bucket": spread_bucket,
                "final_edge": final_edge,
                "liquidity_depth": liquidity_depth,
                "lifecycle_state": lifecycle_state,
                "market_live": market_live,
                "eligible": eligible,
                "duplicate_status": duplicate_status,
                "unsafe_price_status": unsafe_price_status,
                "missing_reason": ",".join(dict.fromkeys(missing_reason)) or "none",
            }

        def _scan_branch(branch_name, category_names):
            self._emit_runonce_branch_event("START", branch_name, payload={"branch": branch_name})
            result = {
                "branch": branch_name,
                "scanned": False,
                "seen": 0,
                "eligible": 0,
                "best_family": None,
                "best_ticker": None,
                "best_edge": None,
                "top_missing_reason": "unknown",
                "selected_quote": None,
                "selected_reason": None,
                "missing_reason": None,
            }
            best_candidate = None
            missing_counts = Counter()
            try:
                for market in markets:
                    if not isinstance(market, dict):
                        continue
                    ticker = str(market.get("ticker", "") or "").strip()
                    if not ticker:
                        continue
                    family = self.get_market_family(market)
                    category = self.get_market_discovery_category(market or family)
                    if category not in category_names and family not in category_names:
                        continue
                    q = quotes_by_ticker.get(ticker)
                    if q is None:
                        missing_counts["missing_quote_object"] += 1
                        continue
                    evaluated = _safe_eval_candidate(market, q, branch_name)
                    result["seen"] += 1
                    if evaluated.get("eligible"):
                        result["eligible"] += 1
                        if best_candidate is None or evaluated.get("final_edge", 0.0) > self.to_float(best_candidate.get("final_edge"), 0.0):
                            best_candidate = evaluated
                    else:
                        missing_counts[evaluated.get("missing_reason") or "unknown"] += 1
                result["scanned"] = True
                result["top_missing_reason"] = missing_counts.most_common(1)[0][0] if missing_counts else "unknown"
                if best_candidate is not None:
                    result["best_family"] = best_candidate.get("family")
                    result["best_ticker"] = best_candidate.get("ticker")
                    result["best_edge"] = round(self.to_float(best_candidate.get("final_edge"), 0.0), 4)
                    result["selected_reason"] = "eligible_candidate_found"
                    result["selected_quote"] = quotes_by_ticker.get(best_candidate.get("ticker") or "")
                else:
                    result["selected_reason"] = "no_eligible_candidate"
                    result["missing_reason"] = result["top_missing_reason"]
                self._emit_runonce_branch_event(
                    "END",
                    branch_name,
                    payload={
                        "scanned": True,
                        "seen": result["seen"],
                        "eligible": result["eligible"],
                        "best_family": result["best_family"],
                        "best_ticker": result["best_ticker"],
                        "best_edge": result["best_edge"],
                        "top_missing_reason": result["top_missing_reason"],
                    },
                )
            except Exception as exc:
                result["scanned"] = False
                result["missing_reason"] = exc.__class__.__name__
                self._emit_runonce_branch_event("ERROR", branch_name, payload=result, error=exc)
            return result

        sports_result = _scan_branch("sports", {"sports"})
        branch_totals["sports"] = sports_result
        crypto_result = _scan_branch("crypto", {"crypto", "btc", "KXBTC15M"})
        branch_totals["crypto"] = crypto_result

        open_result = {
            "branch": "open_market",
            "scanned": False,
            "seen": 0,
            "eligible": 0,
            "best_family": None,
            "best_ticker": None,
            "best_edge": None,
            "top_missing_reason": "unknown",
            "selected_quote": None,
            "selected_reason": None,
            "missing_reason": None,
        }
        self._emit_runonce_branch_event("START", "open_market", payload={"branch": "open_market"})
        try:
            open_runtime = self._rebalance_open_market_runtime_selection(
                markets=locals().get("markets", []),
                quotes_by_ticker=quotes_by_ticker,
                selected_quote=None,
                selected_family=None,
                selected_reason="market_reachability_cycle",
            ) or {}
            open_result["scanned"] = True
            open_result["seen"] = int(open_runtime.get("summary", {}).get("sports_candidate_count", 0) or 0) + int(open_runtime.get("summary", {}).get("crypto_candidate_count", 0) or 0)
            open_result["eligible"] = int(open_runtime.get("summary", {}).get("sports_eligible_count", 0) or 0) + int(open_runtime.get("summary", {}).get("crypto_eligible_count", 0) or 0)
            open_result["best_family"] = open_runtime.get("summary", {}).get("best_open_family")
            open_result["best_ticker"] = open_runtime.get("summary", {}).get("best_open_ticker")
            open_result["best_edge"] = open_runtime.get("summary", {}).get("best_open_edge")
            open_result["selected_quote"] = open_runtime.get("selected_quote")
            open_result["selected_reason"] = open_runtime.get("summary", {}).get("selected_reason") or "no_eligible_open_market"
            open_result["top_missing_reason"] = open_runtime.get("summary", {}).get("missing_reason") or "unknown"
            self._emit_runonce_branch_event("END", "open_market", payload={
                "scanned": True,
                "seen": open_result["seen"],
                "eligible": open_result["eligible"],
                "best_family": open_result["best_family"],
                "best_ticker": open_result["best_ticker"],
                "best_edge": open_result["best_edge"],
                "top_missing_reason": open_result["top_missing_reason"],
            })
        except Exception as exc:
            open_result["missing_reason"] = exc.__class__.__name__
            self._emit_runonce_branch_event("ERROR", "open_market", payload=open_result, error=exc)

        learning_result = {
            "branch": "learning_trade",
            "scanned": True,
            "selected_quote": None,
            "selected_reason": None,
            "best_family": None,
            "best_ticker": None,
            "best_edge": None,
            "no_trade_reason": None,
        }
        self._emit_runonce_branch_event("START", "learning_trade", payload={"branch": "learning_trade"})
        try:
            candidates_pool = [r for r in (sports_result, crypto_result, open_result) if isinstance(r, dict) and r.get("best_ticker")]
            if candidates_pool:
                best_branch = max(candidates_pool, key=lambda item: self.to_float(item.get("best_edge"), 0.0))
                learning_result.update({
                    "selected_quote": quotes_by_ticker.get(best_branch.get("best_ticker") or ""),
                    "selected_reason": best_branch.get("selected_reason") or "eligible_candidate_found",
                    "best_family": best_branch.get("best_family"),
                    "best_ticker": best_branch.get("best_ticker"),
                    "best_edge": best_branch.get("best_edge"),
                })
            else:
                learning_result["no_trade_reason"] = "no_eligible_candidate"
            self._emit_runonce_branch_event("END", "learning_trade", payload={
                "selected_reason": learning_result.get("selected_reason"),
                "best_family": learning_result.get("best_family"),
                "best_ticker": learning_result.get("best_ticker"),
                "best_edge": learning_result.get("best_edge"),
                "no_trade_reason": learning_result.get("no_trade_reason"),
            })
        except Exception as exc:
            learning_result["no_trade_reason"] = exc.__class__.__name__
            self._emit_runonce_branch_event("ERROR", "learning_trade", payload=learning_result, error=exc)

        execution_result = {
            "branch": "execution_evaluation",
            "scanned": True,
            "best_family": learning_result.get("best_family"),
            "best_ticker": learning_result.get("best_ticker"),
            "best_edge": learning_result.get("best_edge"),
            "no_trade_reason": learning_result.get("no_trade_reason") or ("eligible_candidate_found" if learning_result.get("selected_quote") is not None else "no_eligible_candidate"),
        }
        self._emit_runonce_branch_event("START", "execution_evaluation", payload={"branch": "execution_evaluation"})
        self._emit_runonce_branch_event("END", "execution_evaluation", payload=execution_result)

        selected_quote = learning_result.get("selected_quote") or open_result.get("selected_quote") or sports_result.get("selected_quote") or crypto_result.get("selected_quote")
        selected_reason = learning_result.get("selected_reason") or open_result.get("selected_reason") or sports_result.get("selected_reason") or crypto_result.get("selected_reason")
        candidates_seen_total = int(sports_result.get("seen", 0) or 0) + int(crypto_result.get("seen", 0) or 0) + int(open_result.get("seen", 0) or 0)
        eligible_candidates_total = int(sports_result.get("eligible", 0) or 0) + int(crypto_result.get("eligible", 0) or 0) + int(open_result.get("eligible", 0) or 0)
        best_branch = max(
            [result for result in (sports_result, crypto_result, open_result) if result.get("best_ticker")],
            key=lambda item: self.to_float(item.get("best_edge"), 0.0),
            default={},
        )
        summary = {
            "stage": stage_label,
            "markets_fetched_total": markets_fetched_total,
            "quote_objects_total": quote_objects_total,
            "market_families_seen": market_families_seen,
            "quote_hydration_attempted_total": hydration_attempted_total,
            "quote_hydration_success_total": hydration_success_total,
            "quote_hydration_failure_total": hydration_failure_total,
            "quote_hydration_rejected": hydration_rejected,
            "sports_scanned": bool(sports_result.get("scanned")),
            "crypto_scanned": bool(crypto_result.get("scanned")),
            "open_market_scanned": bool(open_result.get("scanned")),
            "sports_candidate_count": int(sports_result.get("seen", 0) or 0),
            "sports_eligible_count": int(sports_result.get("eligible", 0) or 0),
            "crypto_candidate_count": int(crypto_result.get("seen", 0) or 0),
            "crypto_eligible_count": int(crypto_result.get("eligible", 0) or 0),
            "open_market_candidate_count": int(open_result.get("seen", 0) or 0),
            "open_market_eligible_count": int(open_result.get("eligible", 0) or 0),
            "candidates_seen_total": int(candidates_seen_total if stage_label != "pre_quote_build" else markets_fetched_total),
            "eligible_candidates_total": int(eligible_candidates_total),
            "best_family": best_branch.get("best_family") if isinstance(best_branch, dict) else None,
            "best_ticker": best_branch.get("best_ticker") if isinstance(best_branch, dict) else None,
            "best_edge": best_branch.get("best_edge") if isinstance(best_branch, dict) else None,
            "no_trade_reason": execution_result.get("no_trade_reason") or "unknown",
            "top_missing_reason": (
                sports_result.get("top_missing_reason")
                if sports_result.get("top_missing_reason") and sports_result.get("top_missing_reason") != "unknown"
                else crypto_result.get("top_missing_reason")
                if crypto_result.get("top_missing_reason") and crypto_result.get("top_missing_reason") != "unknown"
                else open_result.get("top_missing_reason")
                if open_result.get("top_missing_reason")
                else "unknown"
            ),
        }
        self.last_runonce_reachability_summary = dict(summary)
        self.last_runonce_reachability_selected_quote = selected_quote
        self._emit_runonce_branch_event("END", "market_reachability", payload=summary)
        print("[AION-MARKET-REACHABILITY-CHECK] " + json.dumps(summary, sort_keys=True, default=str), flush=True)
        print("[AION-ALL-MARKET-CANDIDATE-SUMMARY] " + json.dumps(summary, sort_keys=True, default=str), flush=True)
        print("[AION-RUNONCE-END] " + json.dumps(summary, sort_keys=True, default=str), flush=True)
        return {"summary": summary, "selected_quote": selected_quote, "selected_reason": selected_reason}

    def _build_expectancy_score(
        self,
        *,
        market=None,
        q=None,
        family=None,
        spread=None,
        candidate_score=0.0,
        score_breakdown=None,
        entry_timing_observation=None,
        predictive_regime_summary=None,
        adaptive_confidence_summary=None,
        family_rotation_summary=None,
        queue_summary=None,
        microstructure_summary=None,
        learning_summary=None,
        family_learning_summary=None,
        persistence_summary=None,
        sports_momentum=None,
        sports_edge=None,
        sports_context=None,
        near_miss_count=0,
        phase55_status=None,
    ):
        if candidate_quality_build_expectancy_score is not None:
            return candidate_quality_build_expectancy_score(
                self,
                market=market,
                q=q,
                family=family,
                spread=spread,
                candidate_score=candidate_score,
                score_breakdown=score_breakdown,
                entry_timing_observation=entry_timing_observation,
                predictive_regime_summary=predictive_regime_summary,
                adaptive_confidence_summary=adaptive_confidence_summary,
                family_rotation_summary=family_rotation_summary,
                queue_summary=queue_summary,
                microstructure_summary=microstructure_summary,
                learning_summary=learning_summary,
                family_learning_summary=family_learning_summary,
                persistence_summary=persistence_summary,
                sports_momentum=sports_momentum,
                sports_edge=sports_edge,
                sports_context=sports_context,
                near_miss_count=near_miss_count,
                phase55_status=phase55_status,
            )
        market = market if isinstance(market, dict) else {}
        score_breakdown = score_breakdown if isinstance(score_breakdown, dict) else {}
        entry_timing_observation = entry_timing_observation if isinstance(entry_timing_observation, dict) else {}
        predictive_regime_summary = predictive_regime_summary if isinstance(predictive_regime_summary, dict) else {}
        adaptive_confidence_summary = adaptive_confidence_summary if isinstance(adaptive_confidence_summary, dict) else {}
        family_rotation_summary = family_rotation_summary if isinstance(family_rotation_summary, dict) else {}
        queue_summary = queue_summary if isinstance(queue_summary, dict) else {}
        microstructure_summary = microstructure_summary if isinstance(microstructure_summary, dict) else {}
        learning_summary = learning_summary if isinstance(learning_summary, dict) else {}
        family_learning_summary = family_learning_summary if isinstance(family_learning_summary, dict) else {}
        persistence_summary = persistence_summary if isinstance(persistence_summary, dict) else {}
        sports_momentum = sports_momentum if isinstance(sports_momentum, dict) else {}
        sports_edge = sports_edge if isinstance(sports_edge, dict) else {}
        sports_context = sports_context if isinstance(sports_context, dict) else {}
        quote_readiness_diagnostic = self._diagnose_quote_readiness_context(
            market=market,
            q=q,
            family=family,
            sports_context=sports_context,
            source="expectancy_score",
        )
        sports_context = dict(sports_context)
        sports_context["quote_ready"] = bool(quote_readiness_diagnostic.get("quote_ready"))
        sports_context["quote_missing"] = bool(quote_readiness_diagnostic.get("quote_missing"))
        sports_context["quote_readiness_diagnostic"] = {k: v for k, v in quote_readiness_diagnostic.items() if k != "fallback_quote"}
        ticker = str(getattr(q, "ticker", "") or market.get("ticker", "") or "").strip()
        family = str(family or self.get_market_family(market) or getattr(q, "family", "") or "").strip().upper() or "UNKNOWN"
        spread = self.to_float(spread, None)
        if spread is None:
            yes_bid = self.to_float(getattr(q, "yes_bid", None), self.to_float(market.get("yes_bid"), 0.0))
            yes_ask = self.to_float(getattr(q, "yes_ask", None), self.to_float(market.get("yes_ask"), 0.0))
            spread = max(0.0, yes_ask - yes_bid) if yes_bid > 0.0 and yes_ask > 0.0 else 0.0
        spread = max(0.0, self.to_float(spread, 0.0) or 0.0)
        candidate_score = self.to_float(candidate_score, 0.0) or 0.0
        base_score = self._clamp(candidate_score / max(PHASE5_BUY_SCORE_THRESHOLD, 1.0))
        spread_score = self._clamp(max(0.0, (MAX_ENTRY_SPREAD - spread) / max(MAX_ENTRY_SPREAD, 0.0001)))
        liquidity = self.to_float(score_breakdown.get("liquidity"), 0.0) or 0.0
        spread_component = self._clamp(self.to_float(score_breakdown.get("spread"), 0.0) / 25.0)
        timing_component = self._clamp(self.to_float(score_breakdown.get("timing"), 0.0) / 15.0)
        confidence_component = self._clamp(self.to_float(score_breakdown.get("confidence"), 0.0) / 15.0)
        family_component = self._clamp(
            self.to_float(family_learning_summary.get("family_learning_score"), self.to_float(family_rotation_summary.get("family_rotation_score"), 0.5))
        )
        regime_component = self._clamp(
            self.to_float(predictive_regime_summary.get("predictive_regime_score"), self.to_float(predictive_regime_summary.get("top_predictive_score"), 0.5))
        )
        confidence_modifier = self._clamp(0.5 + self.to_float(adaptive_confidence_summary.get("adaptive_confidence_modifier"), 0.0))
        quote_stability = self._clamp(
            self.to_float(microstructure_summary.get("quote_stability_score"), 1.0 - self.to_float(microstructure_summary.get("quote_churn_frequency"), 0.0))
        )
        edge_durability = self._clamp(
            self.to_float(microstructure_summary.get("edge_durability_score"), self.to_float(persistence_summary.get("adaptive_persistence_score"), 0.5))
        )
        execution_survivability = self._clamp(self.to_float(microstructure_summary.get("execution_survivability_score"), 0.5))
        fill_quality_score = self._clamp(
            execution_survivability * 0.36
            + quote_stability * 0.28
            + edge_durability * 0.20
            + self._clamp(self.to_float(microstructure_summary.get("liquidity_reliability"), 0.5)) * 0.16
        )
        fill_quality_bucket = "strong" if fill_quality_score >= 0.7 else "usable" if fill_quality_score >= 0.5 else "fragile"
        quality_score = 0.0
        reasons = []
        print(
            "[AION-FILL-QUALITY] "
            + json.dumps(
                {
                    "ticker": ticker,
                    "family": family,
                    "fill_quality_score": round(fill_quality_score, 4),
                    "fill_quality_bucket": fill_quality_bucket,
                    "quote_stability": round(quote_stability, 4),
                    "edge_durability": round(edge_durability, 4),
                    "execution_survivability": round(execution_survivability, 4),
                    "reason": "expectancy_fill_quality",
                },
                sort_keys=True,
                default=str,
            )
        )
        queue_state = str(queue_summary.get("queue_state") or queue_summary.get("latest_queue_state") or "unknown").strip().lower()
        queue_component = {
            "strong_watch": 0.86,
            "near_ready": 0.80,
            "improving_watch": 0.74,
            "weak_watch": 0.60,
            "blocked": 0.40,
            "expired": 0.22,
            "unknown": 0.50,
        }.get(queue_state, 0.50)
        near_miss_count = max(0, int(near_miss_count or 0))
        near_miss_component = self._clamp(min(1.0, near_miss_count / 5.0))
        opportunity_component = self._clamp(self.to_float(persistence_summary.get("adaptive_persistence_score"), 0.0))
        sports_edge_after_cost = self.to_float(sports_context.get("sports_edge_after_cost"), None)
        sports_edge_component = 0.0
        if sports_edge_after_cost is not None:
            sports_edge_component = self._clamp(max(0.0, sports_edge_after_cost + 0.02) / 0.06)
        else:
            sports_edge_component = self._clamp(max(0.0, self.to_float(sports_edge.get("score"), 0.0) / 100.0))
        time_to_event = self.get_minutes_to_event(market)
        time_component = 0.5
        if time_to_event is not None:
            if time_to_event <= 30.0:
                time_component = 0.74
            elif time_to_event <= 120.0:
                time_component = 0.62
            elif time_to_event <= 360.0:
                time_component = 0.54
            else:
                time_component = 0.42
        volatility_state = str(
            sports_momentum.get("volatility_state")
            or predictive_regime_summary.get("volatility_state")
            or microstructure_summary.get("volatility_state")
            or "unknown"
        ).strip().lower()
        volatility_component = {
            "low": 0.72,
            "normal": 0.60,
            "stable": 0.68,
            "high": 0.40,
            "volatile": 0.28,
            "decaying": 0.22,
            "unknown": 0.50,
        }.get(volatility_state, 0.50)
        expectancy_score = self._clamp(
            base_score * 0.16
            + sports_edge_component * 0.14
            + spread_score * 0.10
            + self._clamp(liquidity / max(MIN_ENTRY_LIQUIDITY, 1.0)) * 0.08
            + confidence_component * 0.08
            + timing_component * 0.08
            + regime_component * 0.10
            + confidence_modifier * 0.08
            + family_component * 0.08
            + quote_stability * 0.08
            + edge_durability * 0.08
            + execution_survivability * 0.08
            + queue_component * 0.03
            + near_miss_component * 0.03
            + opportunity_component * 0.03
            + time_component * 0.02
            + volatility_component * 0.01
        )
        strong_expectancy = bool(
            expectancy_score >= 0.68
            and sports_edge_component >= 0.48
            and quote_stability >= 0.45
            and edge_durability >= 0.42
            and execution_survivability >= 0.40
        )
        positive_expectancy = bool(expectancy_score >= 0.55 and sports_edge_component > 0.0)
        spread_bucket = str(
            sports_context.get("sports_spread_bucket")
            or sports_context.get("spread_bucket")
            or ("tight" if spread <= 0.03 else "acceptable" if spread <= 0.06 else "wide_but_possible" if spread <= AION_SPORTS_MAX_SPREAD_SOFT else "extreme_wide")
        ).strip().lower()
        liquidity_strength = self._clamp(
            self.to_float(microstructure_summary.get("liquidity_quality"), self.to_float(family_learning_summary.get("liquidity_reliability"), 0.5))
        )
        is_sports = self.is_sports_family(family, ticker=ticker) or self._is_sports_market_or_family(family)
        expect_positive_edge = bool(sports_edge_after_cost is None or sports_edge_after_cost > 0.0)
        spread_liquidity_adaptive_pass = bool(
            expect_positive_edge
            and spread_bucket in {"ultra_tight", "tight", "acceptable", "wide_but_possible"}
            and liquidity_strength >= 0.40
            and quote_stability >= 0.40
        )
        repeated_near_miss = bool(near_miss_count >= 2 or queue_state in {"near_ready", "improving_watch", "strong_watch"})
        controlled_loosening_enabled = bool(AION_CONTROLLED_LOOSENING_ENABLED and AION_EXPECTANCY_SCORE_ENABLED)
        aggression_settings = _aion_aggression_profile_settings(AION_AGGRESSION_PROFILE, family=family, spread_bucket=spread_bucket, context="phase55_fastpath")
        phase55_relaxation = self.to_float(aggression_settings.get("phase55_relaxation"), 0.0) or 0.0
        phase55_quote_stability_threshold = max(0.40, 0.48 - (phase55_relaxation * 0.50))
        phase55_edge_durability_threshold = max(0.35, 0.42 - (phase55_relaxation * 0.60))
        phase55_execution_survivability_threshold = max(0.35, 0.40 - (phase55_relaxation * 0.60))
        phase55_regime_component_threshold = max(0.35, 0.40 - (phase55_relaxation * 0.60))
        micro_pullback_quote_threshold = max(0.42, 0.45 - (phase55_relaxation * 0.45))
        micro_pullback_edge_threshold = max(0.35, 0.40 - (phase55_relaxation * 0.50))
        micro_pullback_execution_threshold = max(0.34, 0.38 - (phase55_relaxation * 0.50))
        micro_pullback_expectancy_threshold = max(0.50, 0.60 - (phase55_relaxation * 0.80))
        phase55_fastpath_allowed = bool(
            controlled_loosening_enabled
            and expect_positive_edge
            and spread_bucket in {"ultra_tight", "tight", "acceptable", "wide_but_possible"}
            and quote_stability >= phase55_quote_stability_threshold
            and edge_durability >= phase55_edge_durability_threshold
            and execution_survivability >= phase55_execution_survivability_threshold
            and regime_component >= phase55_regime_component_threshold
            and strong_expectancy
            and repeated_near_miss
            and (not is_sports or sports_edge_component >= 0.40)
        )
        micro_pullback_relax_allowed = bool(
            controlled_loosening_enabled
            and expect_positive_edge
            and spread_bucket in {"ultra_tight", "tight", "acceptable", "wide_but_possible"}
            and quote_stability >= micro_pullback_quote_threshold
            and edge_durability >= micro_pullback_edge_threshold
            and execution_survivability >= micro_pullback_execution_threshold
            and repeated_near_miss
            and expectancy_score >= micro_pullback_expectancy_threshold
        )
        controlled_cooldown_bypass_allowed = bool(
            controlled_loosening_enabled
            and expect_positive_edge
            and strong_expectancy
            and spread_bucket in {"ultra_tight", "tight", "acceptable", "wide_but_possible"}
            and liquidity_strength >= 0.45
        )
        relaxation_reason = "expectancy_support"
        if phase55_fastpath_allowed:
            relaxation_reason = "phase55_fastpath"
        elif micro_pullback_relax_allowed:
            relaxation_reason = "micro_pullback_relaxation"
        elif controlled_cooldown_bypass_allowed:
            relaxation_reason = "cooldown_soft_bypass"
        soft_priority_adjustment = max(-0.015, min(0.015, (expectancy_score - 0.5) * 0.03))
        _emit_aion_aggression_trace(
            "AION-AGGRESSION-REACHABILITY",
            {
                "active_profile": aggression_settings.get("profile"),
                "reason": relaxation_reason,
                "original_threshold": round(0.60, 4),
                "adjusted_threshold": round(micro_pullback_expectancy_threshold, 4),
                "candidate_count_before": aggression_settings.get("candidate_count_before"),
                "candidate_count_after": aggression_settings.get("candidate_count_after"),
                "payload_ready_count": aggression_settings.get("payload_ready_count"),
                "phase55_ready_count": aggression_settings.get("phase55_ready_count"),
                "safety_gates_preserved": bool(AION_CONTROLLED_LOOSENING_ENABLED and AION_EXPECTANCY_SCORE_ENABLED),
                "ticker": ticker,
                "family": family,
                "spread_bucket": spread_bucket,
                "quote_ready": bool(sports_context.get("quote_ready") or quote_readiness_diagnostic.get("quote_ready")),
                "phase55_ready": bool(phase55_fastpath_allowed),
                "payload_ready": bool(sports_context.get("payload_ready") or quote_readiness_diagnostic.get("payload_ready")),
            },
        )
        _emit_aion_aggression_trace(
            "AION-AGGRESSION-SAFETY-CHECK",
            {
                "active_profile": aggression_settings.get("profile"),
                "reason": aggression_settings.get("reason"),
                "candidate_count_before": aggression_settings.get("candidate_count_before"),
                "candidate_count_after": aggression_settings.get("candidate_count_after"),
                "payload_ready_count": aggression_settings.get("payload_ready_count"),
                "phase55_ready_count": aggression_settings.get("phase55_ready_count"),
                "safety_gates_preserved": bool(AION_CONTROLLED_LOOSENING_ENABLED and AION_EXPECTANCY_SCORE_ENABLED),
                "quote_stability_threshold": round(phase55_quote_stability_threshold, 4),
                "edge_durability_threshold": round(phase55_edge_durability_threshold, 4),
                "execution_survivability_threshold": round(phase55_execution_survivability_threshold, 4),
                "regime_component_threshold": round(phase55_regime_component_threshold, 4),
                "ticker": ticker,
                "family": family,
            },
        )
        # PROFIT TARGETS ARE GUIDANCE ONLY
        # NEVER FORCE NEGATIVE EXPECTANCY TRADES
        # EXPECTANCY OVERRIDES PROFIT TARGET PRESSURE
        profit_target_guidance = self._build_profit_target_guidance(
            candidate_expectancy=expectancy_score,
            candidate_score=candidate_score,
            spread_bucket=spread_bucket,
            quote_stability=quote_stability,
            edge_durability=edge_durability,
            execution_survivability=execution_survivability,
            near_miss_count=near_miss_count,
            family=family,
            ticker=ticker,
        )
        profit_target_priority_adjustment = self._clamp(
            self.to_float(profit_target_guidance.get("profit_target_priority_adjustment"), 0.0)
        )
        if not controlled_loosening_enabled and any((phase55_fastpath_allowed, micro_pullback_relax_allowed, controlled_cooldown_bypass_allowed)):
            self._log_relaxation_blocked(
                ticker=ticker,
                family=family,
                reason="controlled_loosening_disabled",
                expectancy_score=expectancy_score,
                spread_bucket=spread_bucket,
            )
        return {
            "expectancy_score": round(expectancy_score, 4),
            "soft_priority_adjustment": round(soft_priority_adjustment, 4),
            "spread_bucket": spread_bucket,
            "sports_edge_after_cost": round(self.to_float(sports_edge_after_cost, 0.0), 4) if sports_edge_after_cost is not None else None,
            "quote_ready": bool(sports_context.get("quote_ready") or quote_readiness_diagnostic.get("quote_ready")),
            "quote_missing": bool(sports_context.get("quote_missing") or quote_readiness_diagnostic.get("quote_missing")),
            "quote_readiness_diagnostic": sports_context.get("quote_readiness_diagnostic"),
            "expect_positive_edge": bool(expect_positive_edge),
            "positive_expectancy": bool(positive_expectancy),
            "strong_expectancy": bool(strong_expectancy),
            "spread_liquidity_adaptive_pass": bool(spread_liquidity_adaptive_pass),
            "phase55_fastpath_allowed": bool(phase55_fastpath_allowed),
            "micro_pullback_relax_allowed": bool(micro_pullback_relax_allowed),
            "controlled_cooldown_bypass_allowed": bool(controlled_cooldown_bypass_allowed),
            "relaxation_reason": relaxation_reason,
            "near_miss_count": near_miss_count,
            "queue_state": queue_state,
            "profit_target_mode": profit_target_guidance.get("profit_target_mode", AION_PROFIT_TARGET_MODE),
            "profit_target_priority_adjustment": round(profit_target_priority_adjustment, 4),
            "profit_target_expansion_active": bool(profit_target_guidance.get("opportunity_expansion_active")),
            "profit_target_expansion_level": self.to_float(profit_target_guidance.get("current_expansion_level"), 0.0),
            "profit_target_expectancy_quality": self.to_float(profit_target_guidance.get("expectancy_quality"), 0.0),
            "profit_target_opportunity_density": self.to_float(profit_target_guidance.get("opportunity_density"), 0.0),
            "aggression_profile": aggression_settings.get("profile"),
            "aggression_reason": aggression_settings.get("reason"),
            "aggression_phase55_relaxation": round(phase55_relaxation, 4),
            "aggression_flat_market_relaxation": round(self.to_float(aggression_settings.get("flat_market_relaxation"), 0.0), 4),
            "aggression_effective_thresholds": {
                "quote_stability": round(phase55_quote_stability_threshold, 4),
                "edge_durability": round(phase55_edge_durability_threshold, 4),
                "execution_survivability": round(phase55_execution_survivability_threshold, 4),
                "regime_component": round(phase55_regime_component_threshold, 4),
                "expectancy": round(micro_pullback_expectancy_threshold, 4),
            },
            "quote_stability": round(quote_stability, 4),
            "edge_durability": round(edge_durability, 4),
            "execution_survivability": round(execution_survivability, 4),
            "fill_quality_score": round(fill_quality_score, 4),
            "fill_quality_bucket": fill_quality_bucket,
            "family_component": round(family_component, 4),
            "regime_component": round(regime_component, 4),
            "confidence_modifier": round(confidence_modifier, 4),
            "volatility_state": volatility_state,
            "time_to_event": time_to_event,
        }

    def _log_relaxation_blocked(self, *, ticker=None, family=None, reason=None, expectancy_score=None, spread_bucket=None, details=None):
        payload = {
            "ticker": str(ticker or "").strip() or None,
            "family": str(family or "UNKNOWN").strip().upper() or "UNKNOWN",
            "reason": str(reason or "unknown").strip(),
            "expectancy_score": round(self.to_float(expectancy_score, 0.0), 4),
            "spread_bucket": str(spread_bucket or "unknown").strip().lower(),
        }
        if isinstance(details, dict):
            payload.update({key: value for key, value in details.items() if value is not None})
        print("[AION-RELAXATION-BLOCKED] " + json.dumps(payload, sort_keys=True, default=str))
        return payload

    def _emit_aion_final_gate(self, *, ticker=None, family=None, edge_after_cost=None, quote_ready=None, reason=None, stage=None, decision=None):
        payload = {
            "ticker": str(ticker or "").strip() or None,
            "family": str(family or "UNKNOWN").strip().upper() or "UNKNOWN",
            "edge_after_cost": None if edge_after_cost is None else round(self.to_float(edge_after_cost, 0.0), 4),
            "quote_ready": bool(quote_ready),
            "reason": str(reason or "unknown").strip(),
            "stage": str(stage or "unknown").strip(),
            "decision": str(decision or "unknown").strip(),
            "live_arb_enabled": bool(AION_LIVE_ARB_ENABLED),
        }
        print("[AION-FINAL-GATE] " + json.dumps(payload, sort_keys=True, default=str))
        if str(decision or "").strip().upper() == "SKIP":
            blocker_payload = dict(payload)
            blocker_payload["final_gate_status"] = "blocked"
            blocker_payload["final_block_reason"] = blocker_payload.get("reason")
            print("[AION-FINAL-GATE-BLOCKER] " + json.dumps(blocker_payload, sort_keys=True, default=str))
        return payload

    def _resolve_aion_canonical_final_execution(
        self,
        *,
        ticker=None,
        family=None,
        canonical_execution_state=None,
        quote_readiness_diagnostic=None,
        payload_preview=None,
        edge_after_cost=None,
        selected_submission_price=None,
        final_submit_allowed_by_realm_vv=None,
        selected_side_has_price=None,
        selected_side_has_liquidity=None,
        depth_available=None,
        orderbook_ready=None,
        duplicate_guard_detail=None,
        live_mode=None,
        live_armed=None,
        live_env_confirmed=None,
        live_trade_count_today=None,
        max_live_trades=None,
        live_positions=None,
        spread_bucket=None,
        unsafe_price_status=None,
        trace_id=None,
    ):
        canonical_execution_state = canonical_execution_state if isinstance(canonical_execution_state, dict) else {}
        quote_readiness_diagnostic = quote_readiness_diagnostic if isinstance(quote_readiness_diagnostic, dict) else {}
        payload_preview = payload_preview if isinstance(payload_preview, dict) else {}
        duplicate_guard_detail = duplicate_guard_detail if isinstance(duplicate_guard_detail, dict) else {}
        live_positions = live_positions if isinstance(live_positions, list) else []

        executable_side = str(
            payload_preview.get('selected_side')
            or payload_preview.get('side')
            or quote_readiness_diagnostic.get('selected_side')
            or canonical_execution_state.get('selected_side')
            or ''
        ).strip().lower() or None
        selected_price_value = selected_submission_price
        if selected_price_value is None:
            selected_price_value = payload_preview.get('yes_price')
        if selected_price_value is None:
            selected_price_value = payload_preview.get('no_price')
        selected_price_value = self.to_float(selected_price_value, None)
        selected_price_cents_value = (
            payload_preview.get("selected_price_cents")
            if payload_preview.get("selected_price_cents") is not None
            else quote_readiness_diagnostic.get("selected_price_cents")
            if quote_readiness_diagnostic.get("selected_price_cents") is not None
            else canonical_execution_state.get("canonical_selected_price_cents")
            if canonical_execution_state.get("canonical_selected_price_cents") is not None
            else getattr(q, "selected_price_cents", None)
        )
        price_bounds_decision = self._aion_price_bounds_decision(
            selected_price=selected_price_value,
            selected_price_cents=selected_price_cents_value,
            yes_ask=payload_preview.get("yes_ask") if payload_preview.get("yes_ask") is not None else getattr(q, "yes_ask", None),
            yes_bid=payload_preview.get("yes_bid") if payload_preview.get("yes_bid") is not None else getattr(q, "yes_bid", None),
            no_ask=payload_preview.get("no_ask") if payload_preview.get("no_ask") is not None else getattr(q, "no_ask", None),
            no_bid=payload_preview.get("no_bid") if payload_preview.get("no_bid") is not None else getattr(q, "no_bid", None),
        )
        self._emit_aion_price_bounds_source(
            caller="canonical_final_execution",
            price_bounds_decision=price_bounds_decision,
            selected_price=selected_price_value,
            selected_price_cents=selected_price_cents_value,
            ticker=ticker,
            family=family,
            source_of_truth="selected_price_cents" if selected_price_cents_value is not None else "selected_price_normalized",
            rejection_origin=price_bounds_decision.get("block_reason"),
        )
        selected_price_value = price_bounds_decision.get("selected_price_normalized", selected_price_value)
        selected_price_cents_value = price_bounds_decision.get("selected_price_cents", selected_price_cents_value)
        selected_price_valid = bool(price_bounds_decision.get("bounds_pass"))
        near_certain_price_block = bool(
            price_bounds_decision.get("block_reason") in {"selected_price_above_0_99", "selected_price_below_0_01", "selected_price_missing", "malformed_orderbook"}
        )
        payload_ready = bool(payload_preview)
        selected_side_has_price_value = bool(
            selected_side_has_price
            if selected_side_has_price is not None
            else quote_readiness_diagnostic.get('selected_side_has_price')
            if quote_readiness_diagnostic.get('selected_side_has_price') is not None
            else canonical_execution_state.get('canonical_selected_side_has_price')
        )
        selected_side_has_liquidity_value = bool(
            selected_side_has_liquidity
            if selected_side_has_liquidity is not None
            else quote_readiness_diagnostic.get('selected_side_has_liquidity')
            if quote_readiness_diagnostic.get('selected_side_has_liquidity') is not None
            else canonical_execution_state.get('canonical_selected_side_has_liquidity')
        )
        depth_available_value = bool(
            depth_available
            if depth_available is not None
            else quote_readiness_diagnostic.get('depth_available')
            if quote_readiness_diagnostic.get('depth_available') is not None
            else canonical_execution_state.get('canonical_depth_available')
        )
        orderbook_ready_value = bool(
            orderbook_ready
            if orderbook_ready is not None
            else quote_readiness_diagnostic.get('orderbook_ready')
            if quote_readiness_diagnostic.get('orderbook_ready') is not None
            else canonical_execution_state.get('canonical_orderbook_ready')
            if canonical_execution_state.get('canonical_orderbook_ready') is not None
            else depth_available_value
            or selected_side_has_liquidity_value
        )
        quote_content_gate = self._resolve_aion_quote_content_gate(
            caller="resolve_aion_canonical_final_execution",
            quote_payload=payload_preview,
            payload=payload_preview,
            quote_diag=quote_readiness_diagnostic,
            orderbook_resolution=payload_preview,
            selected_side=executable_side,
            ticker=ticker,
            family=family,
        )
        quote_content_pass = bool(quote_content_gate.get("pass"))
        quote_content_reason = str(quote_content_gate.get("reason") or "missing_spread").strip().lower() or "missing_spread"
        live_mode_value = bool(live_mode if live_mode is not None else globals().get('LIVE_MODE', False))
        live_armed_value = bool(live_armed if live_armed is not None else globals().get('LIVE_ARMED', False))
        live_env_confirmed_value = bool(live_env_confirmed if live_env_confirmed is not None else globals().get('LIVE_ENV_CONFIRMED', False))
        auth_ready = bool(live_mode_value and live_armed_value and live_env_confirmed_value)
        duplicate_blocked = bool(duplicate_guard_detail.get('blocked'))
        daily_cap_hit = bool(
            live_trade_count_today is not None
            and max_live_trades is not None
            and int(live_trade_count_today) >= int(max_live_trades)
        )
        max_live_positions = int(globals().get('MAX_LIVE_POSITIONS', 0) or 0)
        open_live_positions = sum(
            1
            for position in live_positions
            if str(position.get('status', 'open') or 'open').strip().lower() == 'open'
        )
        max_positions_hit = bool(max_live_positions > 0 and open_live_positions >= max_live_positions)

        hard_block_reason = None
        if not auth_ready:
            hard_block_reason = 'auth_failure'
        elif duplicate_blocked:
            hard_block_reason = str(duplicate_guard_detail.get('reason') or 'duplicate_live_position').strip().lower() or 'duplicate_live_position'
        elif not payload_ready:
            hard_block_reason = 'malformed_payload'
        elif near_certain_price_block:
            hard_block_reason = 'price_out_of_range'
        elif not selected_price_valid:
            hard_block_reason = 'invalid_selected_price'
        elif not quote_content_pass:
            hard_block_reason = quote_content_reason
        elif not selected_side_has_price_value or not executable_side:
            hard_block_reason = 'missing_executable_selected_side_ask'
        elif not orderbook_ready_value and not depth_available_value and not selected_side_has_liquidity_value:
            hard_block_reason = 'dead_corrupt_orderbook'
        elif daily_cap_hit:
            hard_block_reason = 'daily_cap'
        elif max_positions_hit:
            hard_block_reason = 'max_live_positions'

        final_submit_allowed = bool(
            final_submit_allowed_by_realm_vv
            and payload_ready
            and selected_price_valid
            and selected_side_has_price_value
            and quote_content_pass
            and auth_ready
            and not duplicate_blocked
            and not daily_cap_hit
            and not max_positions_hit
            and (orderbook_ready_value or depth_available_value or selected_side_has_liquidity_value)
            and hard_block_reason is None
        )
        edge_value = self.to_float(edge_after_cost, 0.0)
        spread_bucket_value = str(
            spread_bucket
            or canonical_execution_state.get('canonical_spread_bucket')
            or quote_readiness_diagnostic.get('spread_bucket')
            or 'unknown'
        ).strip().lower() or 'unknown'
        unsafe_price_value = str(
            unsafe_price_status
            or canonical_execution_state.get('canonical_unsafe_price_status')
            or quote_readiness_diagnostic.get('unsafe_price_status')
            or 'unknown'
        ).strip().lower() or 'unknown'
        wide_spread = bool(
            spread_bucket_value in {'unsafe', 'extreme_wide'}
            or unsafe_price_value in {'unsafe_spread', 'unsafe', 'unsafe_price'}
        )
        adaptive_edge_floor = max(
            self.to_float(globals().get('AION_SPORTS_MIN_EDGE_AFTER_COST', 0.0), 0.0),
            self.to_float(globals().get('AION_AGGRESSIVE_EDGE_FLOOR', 0.0), 0.0),
            0.0015,
        )
        if wide_spread:
            adaptive_edge_floor = max(adaptive_edge_floor, 0.0025)
        strong_edge = bool(edge_value >= adaptive_edge_floor)

        if hard_block_reason:
            canonical_state = 'HARD_BLOCK'
            execution_policy = 'hard_block'
            canonical_reason = hard_block_reason
            final_action = 'SKIP'
        elif final_submit_allowed and strong_edge:
            canonical_state = 'EXECUTE'
            execution_policy = 'opportunistic_bounded' if wide_spread else 'normal_limit'
            canonical_reason = 'wide_spread_but_executable' if wide_spread else 'canonical_lane_passed'
            final_action = 'EXECUTE'
        else:
            canonical_state = 'SKIP'
            execution_policy = 'wait' if final_submit_allowed else 'skip'
            if not final_submit_allowed:
                canonical_reason = (
                    'final_submit_not_allowed'
                    if not payload_ready
                    else 'price_bounds_pass=false'
                    if not selected_price_valid
                    else 'missing_executable_selected_side_ask'
                    if not selected_side_has_price_value
                    else 'orderbook_not_usable'
                    if not (orderbook_ready_value or depth_available_value or selected_side_has_liquidity_value)
                    else 'canonical_lane_blocked'
                )
            elif wide_spread:
                canonical_reason = 'wide_spread_wait'
            else:
                canonical_reason = 'edge_below_threshold'
            final_action = 'SKIP'
        if near_certain_price_block and final_action == 'EXECUTE':
            canonical_state = 'HARD_BLOCK'
            execution_policy = 'hard_block'
            canonical_reason = 'price_out_of_range'
            final_action = 'SKIP'
        if near_certain_price_block:
            print(
                "[AION-INVALID-CANONICAL-BUY] "
                + json.dumps(
                    {
                        "ticker": str(ticker or "").strip() or None,
                        "family": str(family or "UNKNOWN").strip().upper() or "UNKNOWN",
                        "selected_price": selected_price_value,
                        "selected_side": executable_side,
                        "selected_side_has_price": bool(selected_side_has_price_value),
                        "selected_side_has_liquidity": bool(selected_side_has_liquidity_value),
                        "depth_available": bool(depth_available_value),
                        "orderbook_ready": bool(orderbook_ready_value),
                        "final_submit_allowed": bool(final_submit_allowed and not near_certain_price_block),
                        "hard_block_reason": "price_out_of_range",
                        "canonical_state": canonical_state,
                        "execution_policy": execution_policy,
                    },
                    sort_keys=True,
                    default=str,
                )
            )

        return {
            'ticker': str(ticker or '').strip() or None,
            'family': str(family or 'UNKNOWN').strip().upper() or 'UNKNOWN',
            'canonical_state': canonical_state,
            'canonical_reason': canonical_reason,
            'final_submit_allowed': bool(final_submit_allowed),
            'executable_price': selected_price_value,
            'executable_side': executable_side,
            'hard_block': bool(hard_block_reason is not None),
            'hard_block_reason': hard_block_reason,
            'execution_policy': execution_policy,
            'final_action': final_action,
            'edge_after_cost': edge_value,
            'spread_bucket': spread_bucket_value,
            'unsafe_price_status': unsafe_price_value,
            'trace_id': trace_id,
            'selected_side_has_price': bool(selected_side_has_price_value),
            'selected_side_has_liquidity': bool(selected_side_has_liquidity_value),
            'depth_available': bool(depth_available_value),
            'orderbook_ready': bool(orderbook_ready_value),
            'quote_content_pass': bool(quote_content_pass),
            'quote_content_reason': quote_content_reason,
            'selected_price_cents': selected_price_cents_value,
            'selected_price_normalized': selected_price_value,
            'price_bounds_pass': bool(selected_price_valid and not near_certain_price_block),
            'price_bounds_block_reason': price_bounds_decision.get("block_reason"),
            'price_valid': bool(selected_price_valid and not near_certain_price_block),
        }

    def _emit_aion_canonical_final(self, *, canonical_final=None):
        canonical_final = canonical_final if isinstance(canonical_final, dict) else {}
        emitted_selected_price = self.to_float(
            canonical_final.get("executable_price"),
            self.to_float(
                canonical_final.get("selected_price"),
                self.to_float(canonical_final.get("selected_price_dollars"), None),
            ),
        )
        emitted_selected_price_cents = canonical_final.get("selected_price_cents")
        emitted_price_bounds = self._aion_price_bounds_decision(
            selected_price=emitted_selected_price,
            selected_price_cents=emitted_selected_price_cents,
            yes_ask=canonical_final.get("yes_ask"),
            yes_bid=canonical_final.get("yes_bid"),
            no_ask=canonical_final.get("no_ask"),
            no_bid=canonical_final.get("no_bid"),
        )
        self._emit_aion_price_bounds_source(
            caller="emit_aion_canonical_final",
            price_bounds_decision=emitted_price_bounds,
            selected_price=emitted_selected_price,
            selected_price_cents=emitted_selected_price_cents,
            ticker=canonical_final.get("ticker"),
            family=canonical_final.get("family"),
            source_of_truth="selected_price_cents" if emitted_selected_price_cents is not None else "selected_price_normalized",
            rejection_origin=emitted_price_bounds.get("block_reason"),
        )
        quote_content_gate = self._resolve_aion_quote_content_gate(
            caller="emit_aion_canonical_final",
            quote_payload=canonical_final,
            payload=canonical_final,
            quote_diag=canonical_final,
            orderbook_resolution=canonical_final,
            selected_side=canonical_final.get("selected_side") or canonical_final.get("executable_side"),
            ticker=canonical_final.get("ticker"),
            family=canonical_final.get("family"),
        )
        quote_content_pass = bool(quote_content_gate.get("pass"))
        emitted_near_certain = bool(
            not emitted_price_bounds.get("bounds_pass")
            and emitted_price_bounds.get("block_reason") in {"selected_price_above_0_99", "selected_price_below_0_01", "selected_price_missing", "malformed_orderbook"}
        )
        if (not quote_content_pass or emitted_near_certain) and bool(canonical_final.get("final_action") in {"BUY", "EXECUTE"} or canonical_final.get("final_submit_allowed")):
            print(
                "[AION-INVALID-CANONICAL-BUY] "
                + json.dumps(
                    {
                        "ticker": canonical_final.get("ticker"),
                        "family": canonical_final.get("family"),
                        "selected_price": emitted_selected_price,
                        "selected_side": canonical_final.get("executable_side"),
                        "final_submit_allowed": False,
                        "final_action": "SKIP",
                        "execution_policy": "skip",
                        "hard_block_reason": "price_out_of_range" if emitted_near_certain else quote_content_gate.get("reason") or "missing_spread",
                    },
                    sort_keys=True,
                    default=str,
                )
            )
            canonical_final = dict(canonical_final)
            canonical_final["final_submit_allowed"] = False
            canonical_final["final_action"] = "SKIP"
            canonical_final["execution_policy"] = "skip"
            canonical_final["canonical_state"] = "HARD_BLOCK"
            canonical_final["canonical_reason"] = "price_out_of_range" if emitted_near_certain else str(quote_content_gate.get("reason") or "missing_spread")
            canonical_final["quote_content_pass"] = bool(quote_content_pass)
            canonical_final["quote_content_reason"] = str(quote_content_gate.get("reason") or "missing_spread")
        payload = {
            'ticker': canonical_final.get('ticker'),
            'family': canonical_final.get('family'),
            'canonical_state': canonical_final.get('canonical_state'),
            'canonical_reason': canonical_final.get('canonical_reason'),
            'final_submit_allowed': bool(canonical_final.get('final_submit_allowed')),
            'executable_price': canonical_final.get('executable_price'),
            'hard_block': bool(canonical_final.get('hard_block')),
            'execution_policy': canonical_final.get('execution_policy'),
            'final_action': canonical_final.get('final_action'),
            'edge_after_cost': canonical_final.get('edge_after_cost'),
            'spread_bucket': canonical_final.get('spread_bucket'),
            'unsafe_price_status': canonical_final.get('unsafe_price_status'),
            'trace_id': canonical_final.get('trace_id'),
        }
        print('[AION-CANONICAL-FINAL] ' + json.dumps(payload, sort_keys=True, default=str))
        try:
            self._record_family_universe_health_sample(
                canonical_final=canonical_final,
                ticker=canonical_final.get("ticker"),
                family=canonical_final.get("family"),
                stage="canonical_final",
                source="emit_aion_canonical_final",
                reason=str(canonical_final.get("canonical_reason") or canonical_final.get("hard_block_reason") or "canonical_final"),
                canonical_pass=bool(canonical_final.get("final_submit_allowed")),
            )
        except Exception as exc:
            print(
                "[AION-UNIVERSE-RECORD-WARN] "
                + json.dumps(
                    {
                        "stage": "canonical_final",
                        "ticker": canonical_final.get("ticker"),
                        "family": canonical_final.get("family"),
                        "error_type": exc.__class__.__name__,
                        "error_reason": str(exc),
                    },
                    sort_keys=True,
                    default=str,
                )
            )
        return payload

    def _emit_candidate_phase55_forensics(
        self,
        *,
        market=None,
        q=None,
        family=None,
        expectancy_summary=None,
        decision=None,
        decision_reason=None,
        phase55_status=None,
        phase55_entry_timing_pass=None,
        execution_safety_blocked=False,
        hard_reject_reason=None,
        source="candidate_selection",
    ):
        market = market if isinstance(market, dict) else {}
        expectancy_summary = expectancy_summary if isinstance(expectancy_summary, dict) else {}
        q = q if q is not None else None
        family = str(family or self.get_market_family(market) or getattr(q, "family", "") or "UNKNOWN").strip().upper() or "UNKNOWN"
        ticker = str(getattr(q, "ticker", "") or market.get("ticker", "") or "").strip()
        normalized_market = market
        normalized_q = q
        quote_fixed = False
        quote_fixed_reason = None
        quote_diag = {}
        try:
            quote_diag = self._diagnose_quote_readiness_context(
                market=market,
                q=q,
                family=family,
                sports_context=expectancy_summary,
                source=source,
            ) or {}
        except Exception as exc:
            quote_diag = {"quote_ready": False, "quote_ready_reason": exc.__class__.__name__}

        quote_ready = bool(quote_diag.get("quote_ready"))
        quote_missing = bool(quote_diag.get("quote_missing", not quote_ready))
        spread_bucket = str(quote_diag.get("spread_bucket") or "unknown").strip().lower() or "unknown"
        source_of_quote_data = str(quote_diag.get("source_of_quote_data") or "unknown").strip().lower() or "unknown"
        unsafe_price_detail = self._resolve_unsafe_price_detail(
            market=normalized_market,
            q=normalized_q,
            family=family,
            quote_diag=quote_diag,
            source=source,
        )
        unsafe_price_status = str(unsafe_price_detail.get("unsafe_price_status") or "unsafe").strip().lower() or "unsafe"
        unsafe_unknown = (
            not quote_ready
            or quote_missing
            or spread_bucket == "unknown"
            or source_of_quote_data in {"missing_orderbook_data", "missing_topbook_depth", "empty_market", "parser_failure", "unknown"}
            or q is None
        )
        if ticker and unsafe_unknown:
            try:
                fresh_market_detail = self.get_live_market_detail(ticker)
            except Exception as exc:
                fresh_market_detail = {}
                quote_fixed_reason = f"market_detail_fetch_{exc.__class__.__name__}"
            if isinstance(fresh_market_detail, dict) and fresh_market_detail:
                try:
                    refreshed_quote = self.build_quote(fresh_market_detail)
                except Exception as exc:
                    refreshed_quote = None
                    quote_fixed_reason = quote_fixed_reason or f"build_quote_{exc.__class__.__name__}"
                if refreshed_quote is not None:
                    normalized_market = fresh_market_detail
                    normalized_q = refreshed_quote
                    quote_fixed = True
                    quote_fixed_reason = quote_fixed_reason or "fresh_orderbook_refreshed"
                    try:
                        quote_diag = self._diagnose_quote_readiness_context(
                            market=normalized_market,
                            q=normalized_q,
                            family=family,
                            sports_context=expectancy_summary,
                            source=f"{source}_refresh",
                        ) or quote_diag
                    except Exception as exc:
                        quote_diag = quote_diag or {"quote_ready": False, "quote_ready_reason": exc.__class__.__name__}
        unsafe_price_detail = self._resolve_unsafe_price_detail(
            market=normalized_market,
            q=normalized_q,
            family=family,
            quote_diag=quote_diag,
            source=source,
        )
        unsafe_price_status = str(unsafe_price_detail.get("unsafe_price_status") or "unsafe").strip().lower() or "unsafe"
        quote_ready = bool(quote_diag.get("quote_ready"))
        quote_missing = bool(quote_diag.get("quote_missing", not quote_ready))
        spread_bucket = str(quote_diag.get("spread_bucket") or "unknown").strip().lower() or "unknown"
        orderbook_age_seconds = quote_diag.get("orderbook_age_seconds")
        best_bid = self.to_float(getattr(normalized_q, "yes_bid", None), None) if normalized_q is not None else None
        best_ask = self.to_float(getattr(normalized_q, "yes_ask", None), None) if normalized_q is not None else None
        spread_value = self.to_float(quote_diag.get("spread"), None)
        if (
            (spread_value is None or spread_value <= 0.0)
            and best_bid is not None
            and best_ask is not None
            and best_ask > best_bid
        ):
            spread_value = max(0.0, best_ask - best_bid)
            quote_diag["spread"] = spread_value
        edge_after_cost = self.to_float(expectancy_summary.get("sports_edge_after_cost"), 0.0)
        family_allowed = bool(self.is_sports_family(normalized_market) and family != "KXBTC15M")
        family_strong = bool(family.startswith(("KXNBA", "KXMLB", "KXNFL")))
        adaptive_spread_limit = self._get_sports_adaptive_spread_threshold(
            normalized_market,
            spread=spread_value,
            quote_diag=quote_diag,
            context=f"{source}_phase55_forensics",
        ).get("adaptive_threshold", AION_SPORTS_MAX_SPREAD_HARD) if family_allowed else AION_SPORTS_MAX_SPREAD_HARD
        direct_book_spread_tradeable = bool(
            spread_value is not None
            and spread_value > 0.0
            and spread_value <= max(AION_SPORTS_MAX_SPREAD_HARD, self.to_float(adaptive_spread_limit, AION_SPORTS_MAX_SPREAD_HARD))
            and best_bid is not None
            and best_ask is not None
            and best_bid > 0.0
            and best_ask > 0.0
        )
        if spread_bucket in {"unknown", "unsafe", "extreme_wide"} and direct_book_spread_tradeable:
            if spread_value <= 0.03:
                spread_bucket = "ultra_tight"
            elif spread_value <= MAX_ENTRY_SPREAD:
                spread_bucket = "tight"
            else:
                spread_bucket = "wide_but_possible"
            quote_diag["spread_bucket"] = spread_bucket
        spread_extreme = bool(
            spread_value is None
            or spread_value <= 0.0
            or spread_value > AION_SPORTS_MAX_SPREAD_HARD
            or spread_bucket in {"extreme_wide"}
        )
        if direct_book_spread_tradeable:
            spread_extreme = False
        invalid_bid_ask = bool(best_bid is None or best_ask is None or best_bid <= 0.0 or best_ask <= 0.0)
        canonical_tradeability = quote_diag.get("canonical_tradeability") if isinstance(quote_diag.get("canonical_tradeability"), dict) else {}
        canonical_final_allowed = bool(
            canonical_tradeability.get("final_submit_allowed_by_realm_vv")
            or quote_diag.get("final_submit_allowed_by_realm_vv")
            or expectancy_summary.get("final_submit_allowed_by_realm_vv")
        )
        canonical_price_valid = bool(
            quote_diag.get("selected_side_has_price")
            or quote_diag.get("selected_price_cents") not in (None, "", 0, 0.0)
            or quote_diag.get("selected_price_dollars") not in (None, "", 0, 0.0)
            or getattr(normalized_q, "selected_price_cents", None) not in (None, "", 0, 0.0)
            or getattr(normalized_q, "selected_price", None) not in (None, "", 0, 0.0)
        )
        canonical_depth_valid = bool(
            quote_diag.get("selected_side_has_liquidity")
            or quote_diag.get("depth_available")
            or quote_diag.get("orderbook_ready")
            or quote_diag.get("topbook_depth_exists")
            or (best_bid is not None and best_ask is not None)
        )
        if canonical_final_allowed and quote_ready and canonical_price_valid and canonical_depth_valid and edge_after_cost > 0.0:
            invalid_bid_ask = False
            spread_extreme = False
            family_allowed = True
            family_strong = True
            if spread_bucket in {"unsafe", "extreme_wide", "unknown"}:
                spread_bucket = "wide_but_possible"
                quote_diag["spread_bucket"] = spread_bucket
            quote_diag["quote_ready"] = True
            quote_diag["quote_missing"] = False
            quote_diag["final_submit_allowed_by_realm_vv"] = True
        if not quote_ready:
            unsafe_price_status = "blocked"
            block_reason = "quote_not_ready_after_refresh" if quote_fixed else "quote_not_ready"
        elif invalid_bid_ask:
            unsafe_price_status = "blocked"
            block_reason = "invalid_bid_ask"
        elif spread_extreme or not family_allowed or not family_strong:
            unsafe_price_status = "blocked"
            block_reason = "spread_extreme"
        else:
            unsafe_price_status = "safe" if (
                unsafe_price_detail.get("unsafe_price_status") == "safe"
                or (canonical_final_allowed and quote_ready and canonical_price_valid and canonical_depth_valid and edge_after_cost > 0.0)
                or (direct_book_spread_tradeable and edge_after_cost > 0.0 and quote_ready)
            ) else "unsafe"
            block_reason = None
        phase55_only_execution_block = bool(
            execution_safety_blocked
            and str(phase55_status or "").strip().lower() in {"entry_ready", "probability_block", "trigger_wait", "pullback_wait", "insufficient_data"}
        )
        direct_book_positive_edge_ready = bool(
            self._is_sports_market_or_family(family)
            and direct_book_spread_tradeable
            and quote_ready
            and edge_after_cost > 0.0
            and str(decision or "").strip().upper() == "BUY"
            and (not execution_safety_blocked or phase55_only_execution_block)
            and not hard_reject_reason
        )
        if direct_book_positive_edge_ready:
            unsafe_price_status = "safe"
            block_reason = None
            phase55_status = "entry_ready"
            phase55_entry_timing_pass = True
            quote_diag["quote_ready"] = True
            quote_diag["quote_missing"] = False
            quote_diag["unsafe_price_status"] = "safe"
            quote_diag["final_submit_allowed_by_realm_vv"] = True
        entry_ready = bool(
            phase55_status == "entry_ready"
            and phase55_entry_timing_pass is True
            and quote_ready
            and unsafe_price_status == "safe"
            and not execution_safety_blocked
            and not hard_reject_reason
        )
        phase55_handoff = bool(entry_ready and str(decision or "").strip().upper() == "BUY")
        if entry_ready and unsafe_price_status == "safe":
            print(
                "[AION-PHASE55-READY] "
                + json.dumps(
                    {
                        "ticker": ticker or None,
                        "family": family,
                        "unsafe_price_status": unsafe_price_status,
                        "unsafe_resolution_reason": unsafe_price_detail.get("unsafe_resolution_reason"),
                        "quote_ready": quote_ready,
                        "phase55_ready": True,
                        "final_gate_status": "entry_ready",
                        "spread_bucket": spread_bucket,
                        "source": source,
                    },
                    sort_keys=True,
                    default=str,
                )
            )
        if not phase55_handoff:
            if block_reason is None:
                if hard_reject_reason:
                    block_reason = str(hard_reject_reason)
                elif not phase55_entry_timing_pass or phase55_status != "entry_ready":
                    block_reason = "phase55_block"
                elif execution_safety_blocked:
                    block_reason = "phase55_block"
                elif edge_after_cost < 0.0015:
                    block_reason = "edge_too_low"
                elif str(decision or "").strip().upper() != "BUY":
                    block_reason = "not_buy_decision"
                else:
                    block_reason = "phase55_block"
        payload = {
            "ticker": ticker or None,
            "family": family,
            "edge_after_cost": round(edge_after_cost, 4),
            "spread_bucket": spread_bucket,
            "quote_ready": quote_ready,
            "unsafe_price_status": unsafe_price_status,
            "best_bid": best_bid,
            "best_ask": best_ask,
            "orderbook_age_seconds": orderbook_age_seconds,
            "phase55_handoff": phase55_handoff,
            "entry_ready": entry_ready,
            "block_reason": block_reason,
            "quote_fixed": quote_fixed,
            "quote_fixed_reason": quote_fixed_reason,
            "decision": str(decision or "unknown").strip(),
            "decision_reason": str(decision_reason or "unknown").strip(),
            "source": source,
        }
        print("[AION-QUOTE-NORMALIZATION] " + json.dumps(payload, sort_keys=True, default=str))
        print("[AION-UNSAFE-PRICE-CHECK] " + json.dumps(payload, sort_keys=True, default=str))
        if entry_ready:
            print("[AION-ENTRY-READINESS] " + json.dumps(payload, sort_keys=True, default=str))
        else:
            print("[AION-ENTRY-READINESS-BLOCKED] " + json.dumps(payload, sort_keys=True, default=str))
        if phase55_handoff:
            print("[AION-PHASE55-HANDOFF] " + json.dumps(payload, sort_keys=True, default=str))
        else:
            print("[AION-PHASE55-HANDOFF-BLOCKED] " + json.dumps(payload, sort_keys=True, default=str))
        return {
            "market": normalized_market,
            "quote": normalized_q,
            "quote_diag": quote_diag,
            "quote_fixed": quote_fixed,
            "quote_fixed_reason": quote_fixed_reason,
            "quote_ready": quote_ready,
            "quote_missing": quote_missing,
            "spread_bucket": spread_bucket,
            "best_bid": best_bid,
            "best_ask": best_ask,
            "orderbook_age_seconds": orderbook_age_seconds,
            "unsafe_price_status": unsafe_price_status,
            "unsafe_resolution_reason": unsafe_price_detail.get("unsafe_resolution_reason"),
            "entry_ready": entry_ready,
            "phase55_handoff": phase55_handoff,
            "block_reason": block_reason,
            "payload": payload,
        }

