    def _check_phase55_live_execution_gate(
        self,
        ticker,
        family=None,
        decision=None,
        override_block_reason=None,
        canonical_execution_state=None,
    ):
        gate_record = self._get_realm_vv_live_execution_gate_record(ticker, stage="realm_vv_gate")
        canonical_execution_state = canonical_execution_state if isinstance(canonical_execution_state, dict) else {}
        realm_vv_status = gate_record.get("realm_vv_status")
        realm_vv_ready = gate_record.get("realm_vv_ready")
        realm_vv_explicit_approval = gate_record.get("realm_vv_explicit_approval")
        if canonical_execution_state:
            realm_vv_status = (
                canonical_execution_state.get("realm_vv_status")
                or canonical_execution_state.get("canonical_readiness_state")
                or canonical_execution_state.get("final_realm_vv_status")
                or realm_vv_status
            )
            if canonical_execution_state.get("realm_vv_ready") is not None:
                realm_vv_ready = canonical_execution_state.get("realm_vv_ready")
            elif canonical_execution_state.get("canonical_final_submit_allowed_by_realm_vv") is not None:
                realm_vv_ready = canonical_execution_state.get("canonical_final_submit_allowed_by_realm_vv")
            if canonical_execution_state.get("realm_vv_explicit_approval") is not None:
                realm_vv_explicit_approval = canonical_execution_state.get("realm_vv_explicit_approval")
        effective_family = family or gate_record.get("family") or "UNKNOWN"
        effective_decision = decision or canonical_execution_state.get("canonical_execution_decision") or gate_record.get("decision") or "unknown"
        live_mode_active = bool(globals().get("LIVE_MODE", False))
        live_arm_active = bool(globals().get("LIVE_ARMED", False))
        service_active = bool(self is not None)
        blocked = False
        reason = "approved"
        if override_block_reason:
            blocked = True
            reason = str(override_block_reason)
        elif realm_vv_status is None or not isinstance(realm_vv_status, str) or not realm_vv_status.strip():
            blocked = True
            reason = "missing_realm_vv_status"
        elif str(realm_vv_status).strip().lower() != "entry_ready":
            blocked = True
            reason = f"realm_vv_status_{str(realm_vv_status).strip().lower()}"
        elif realm_vv_ready is not True and realm_vv_explicit_approval is not True:
            blocked = True
            reason = "realm_vv_explicit_approval_not_true"
        compatibility_alias_only = bool(
            "phase55_status" in gate_record
            or "entry_timing_pass" in gate_record
            or "phase55_ready" in gate_record
        )
        gate_log_payload = {
            "ticker": ticker,
            "family": effective_family,
            "realm_vv_status": realm_vv_status,
            "realm_vv_ready": realm_vv_ready,
            "realm_vv_explicit_approval": realm_vv_explicit_approval,
            "decision": effective_decision,
            "botStatus": "LIVE" if service_active and live_mode_active and live_arm_active and not blocked else ("BLOCKED" if blocked else ("WAITING" if live_mode_active else "OFFLINE")),
            "phase": "realm_vv",
            "live_mode": live_mode_active,
            "live_arm": live_arm_active,
            "service_active": service_active,
            "entry_ready": bool(not blocked),
            "block_reason": None if not blocked else reason,
            "compatibility_alias_only": compatibility_alias_only,
        }
        print("[AION-REALM-VV-SOLE-AUTHORITY] " + json.dumps(gate_log_payload, sort_keys=True, default=str))
        if compatibility_alias_only:
            print("[AION-PHASE55-PURGED] " + json.dumps(gate_log_payload, sort_keys=True, default=str))
            print("[AION-PHASE55-COMPAT-ONLY] " + json.dumps(gate_log_payload, sort_keys=True, default=str))
        self._write_seraph_telemetry_status_snapshot(
            bot_status=gate_log_payload["botStatus"],
            risk_status="NORMAL",
            phase="realm_vv",
            live_mode=live_mode_active,
            live_arm=live_arm_active,
            service_active=service_active,
            entry_ready=bool(not blocked),
            block_reason=None if not blocked else reason,
        )
        return (not blocked), reason, {
            "ticker": ticker,
            "family": effective_family,
            "realm_vv_status": realm_vv_status,
            "realm_vv_ready": realm_vv_ready,
            "realm_vv_explicit_approval": realm_vv_explicit_approval,
            "decision": effective_decision,
            "reason": reason,
            "compatibility_alias_only": compatibility_alias_only,
        }

    def _build_aion_execution_quality_profile(self, *, market=None, q=None, family=None, liquidity_priority=None, expectancy_summary=None):
        market = market if isinstance(market, dict) else {}
        if q is None:
            q = market
            try:
                q_proxy = type("_AIONQuoteProxy", (), {})()
                for _key, _value in self._coerce_aion_orderbook_source(market).items():
                    setattr(q_proxy, _key, _value)
                q = q_proxy
            except Exception:
                q = market
        liquidity_priority = liquidity_priority if isinstance(liquidity_priority, dict) else self.get_market_liquidity_priority(market)
        expectancy_summary = expectancy_summary if isinstance(expectancy_summary, dict) else {}
        family = str(family or self.get_market_family(market) or getattr(q, "family", "") or "UNKNOWN").strip().upper() or "UNKNOWN"
        ticker = str(getattr(q, "ticker", "") or market.get("ticker", "") or "").strip()
        quote_diag = {}
        try:
            quote_diag = self._diagnose_quote_readiness_context(
                market=market,
                q=q,
                family=family,
                sports_context=expectancy_summary,
                source="execution_quality",
            ) or {}
        except Exception:
            quote_diag = {}
        spread_bucket = str(
            liquidity_priority.get("spread_bucket")
            or quote_diag.get("spread_bucket")
            or expectancy_summary.get("spread_bucket")
            or "unknown"
        ).strip().lower() or "unknown"
        quote_ready = bool(quote_diag.get("quote_ready", liquidity_priority.get("quote_ready")))
        unsafe_price_detail = self._resolve_unsafe_price_detail(
            market=market,
            q=q,
            family=family,
            quote_diag=quote_diag,
            source="execution_quality",
        )
        unsafe_price_status = str(unsafe_price_detail.get("unsafe_price_status") or "unknown").strip().lower() or "unknown"
        orderbook_age_seconds = self.to_float(quote_diag.get("orderbook_age_seconds"), self.to_float(market.get("staleness_seconds"), None))
        quote_continuity_cycles = int(quote_diag.get("quote_stability_cycles", 0) or 0)
        yes_top_size = self.to_float(liquidity_priority.get("yes_top_size"), 0.0) or 0.0
        no_top_size = self.to_float(liquidity_priority.get("no_top_size"), 0.0) or 0.0
        top_book_depth = round(yes_top_size + no_top_size, 4)
        liquidity_depth = self.to_float(liquidity_priority.get("effective_liquidity_value"), self.to_float(getattr(q, "liquidity", None), 0.0))
        recent_valid_quotes = int(quote_ready)
        edge_after_cost = self.to_float(expectancy_summary.get("sports_edge_after_cost"), self.to_float(expectancy_summary.get("final_edge"), 0.0))
        near_pass_count = int((self.shadow_trade_watchlist_by_ticker or {}).get(ticker, {}).get("near_pass_count", 0) or 0) if ticker else 0
        score = 0.0
        reasons = []
        if spread_bucket == "tight":
            score += 28.0
            reasons.append("tight_spread")
        elif spread_bucket == "wide_but_possible":
            score += 14.0
            reasons.append("wide_but_possible")
        elif spread_bucket == "unsafe":
            score -= 28.0
            reasons.append("unsafe_spread_bucket")
        if quote_ready:
            score += 18.0
            reasons.append("quote_ready")
        if unsafe_price_status == "safe":
            score += 12.0
            reasons.append("safe_price")
        elif unsafe_price_status not in {"safe", "unknown"}:
            score -= 10.0
            reasons.append("unsafe_price_block")
        if top_book_depth >= 20.0:
            score += 10.0
            reasons.append("deep_top_book")
        elif top_book_depth >= 10.0:
            score += 6.0
            reasons.append("healthy_top_book")
        elif top_book_depth > 0.0:
            score += 2.0
            reasons.append("thin_top_book")
        else:
            score -= 8.0
            reasons.append("empty_top_book")
        if liquidity_depth > 0.0:
            score += min(10.0, liquidity_depth / 20.0)
            reasons.append("liquidity_present")
        if orderbook_age_seconds is not None:
            if orderbook_age_seconds <= 30.0:
                score += 8.0
                reasons.append("fresh_orderbook")
            elif orderbook_age_seconds <= 120.0:
                score += 4.0
                reasons.append("recent_orderbook")
            elif orderbook_age_seconds > 900.0:
                score -= 12.0
                reasons.append("very_stale_orderbook")
            elif orderbook_age_seconds > 300.0:
                score -= 6.0
                reasons.append("stale_orderbook")
        if quote_continuity_cycles >= 3:
            score += 8.0
            reasons.append("strong_quote_continuity")
        elif quote_continuity_cycles >= 1:
            score += 3.0
            reasons.append("quote_continuity")
        else:
            score -= 2.0
            reasons.append("no_quote_continuity")
        if edge_after_cost > 0.0:
            score += min(12.0, edge_after_cost * 1200.0)
            reasons.append("positive_edge")
        else:
            score -= 8.0
            reasons.append("non_positive_edge")
        if near_pass_count >= 2:
            score -= 5.0
            reasons.append("repeated_near_pass")
        if spread_bucket == "unsafe" or orderbook_age_seconds is not None and orderbook_age_seconds > 900.0:
            reasons.append("hard_deprioritize")
        score = round(score, 4)
        execution_probability = self._clamp(
            0.08
            + (0.40 if quote_ready else 0.0)
            + (0.16 if unsafe_price_status == "safe" else 0.0)
            + min(0.18, max(0.0, top_book_depth) / 150.0)
            + min(0.12, max(0.0, liquidity_depth) / 600.0)
            + min(0.10, max(0.0, edge_after_cost) * 8.0)
            + min(0.08, quote_continuity_cycles * 0.03)
            - min(0.10, near_pass_count * 0.02)
        )
        return {
            "ticker": ticker or None,
            "family": family,
            "spread_bucket": spread_bucket,
            "quote_ready": quote_ready,
            "unsafe_price_status": unsafe_price_status,
            "orderbook_age_seconds": orderbook_age_seconds,
            "quote_continuity_cycles": quote_continuity_cycles,
            "top_book_depth": round(top_book_depth, 4),
            "liquidity_depth": round(self.to_float(liquidity_depth, 0.0), 4),
            "recent_valid_quotes": int(recent_valid_quotes),
            "near_pass_count": int(near_pass_count),
            "edge_after_cost": round(edge_after_cost, 6),
            "execution_quality_score": score,
            "execution_probability": round(execution_probability, 4),
            "execution_quality_reasons": reasons,
        }

    def _build_aion_market_priority_profile(self, *, market=None, q=None, family=None, spread=None, liquidity_priority=None, expectancy_summary=None):
        market = market if isinstance(market, dict) else {}
        q = q if q is not None else self.build_quote(market)
        family = str(family or self.get_market_family(market) or getattr(q, "family", "") or "UNKNOWN").strip().upper() or "UNKNOWN"
        liquidity_priority = liquidity_priority if isinstance(liquidity_priority, dict) else self.get_market_liquidity_priority(market)
        liquidity_profile = self._compute_liquidity_priority_score(
            market,
            q=q,
            family=family,
            spread=spread,
            liquidity_priority=liquidity_priority,
        )
        execution_quality_profile = self._build_aion_execution_quality_profile(
            market=market,
            q=q,
            family=family,
            liquidity_priority=liquidity_priority,
            expectancy_summary=expectancy_summary,
        )
        ticker = str(getattr(q, "ticker", "") or market.get("ticker", "") or "").strip()
        priority_tier = int(liquidity_profile.get("tier") or 3)
        liquidity_score = self.to_float(liquidity_profile.get("score"), 0.0)
        execution_quality_score = self.to_float(execution_quality_profile.get("execution_quality_score"), 0.0)
        yes_ask = self.to_float(getattr(q, "yes_ask", None), self.to_float(market.get("yes_ask_dollars"), self.to_float(market.get("yes_ask"), None)))
        no_bid = self.to_float(getattr(q, "no_bid", None), self.to_float(market.get("no_bid_dollars"), self.to_float(market.get("no_bid"), None)))
        yes_bid = self.to_float(getattr(q, "yes_bid", None), self.to_float(market.get("yes_bid_dollars"), self.to_float(market.get("yes_bid"), None)))
        no_ask = self.to_float(getattr(q, "no_ask", None), self.to_float(market.get("no_ask_dollars"), self.to_float(market.get("no_ask"), None)))
        top_yes_size = self.to_float(liquidity_priority.get("yes_top_size"), 0.0) or 0.0
        top_no_size = self.to_float(liquidity_priority.get("no_top_size"), 0.0) or 0.0
        top_depth_total = round(top_yes_size + top_no_size, 4)
        top_depth_balance = 0.0
        if top_depth_total > 0.0:
            top_depth_balance = 1.0 - min(1.0, abs(top_yes_size - top_no_size) / max(top_depth_total, 1.0))
        effective_spread = self.to_float(liquidity_priority.get("spread"), self.to_float(spread, 0.0))
        price_family_state = self._get_price_family_penalty_state(family)
        missing_spread_state = self._get_missing_spread_family_penalty_state(family)
        quality_score = 0.0
        quality_reasons = []
        if spread is None:
            quality_score -= 12.0
            quality_reasons.append("spread_missing")
        if yes_ask is not None and yes_ask >= 0.95:
            quality_score -= 18.0
            quality_reasons.append("yes_ask_ge_0.95")
        if yes_ask is not None and yes_ask >= 0.99:
            quality_score -= 20.0
            quality_reasons.append("yes_ask_ge_0.99")
        elif yes_ask is not None and yes_ask >= 0.90:
            quality_score -= 8.0
            quality_reasons.append("yes_ask_ge_0.90")
        if no_bid is not None and no_bid <= 0.05:
            quality_score -= 18.0
            quality_reasons.append("no_bid_le_0.05")
        if no_ask is not None and no_ask >= 0.95:
            quality_score -= 14.0
            quality_reasons.append("no_ask_ge_0.95")
        selected_price_value = self.to_float(getattr(q, "selected_price", None), None)
        if selected_price_value is not None and (selected_price_value >= 0.99 or selected_price_value <= 0.01):
            quality_score -= 24.0
            quality_reasons.append("selected_price_near_certain")
        elif selected_price_value is not None and selected_price_value >= 0.95:
            quality_score -= 12.0
            quality_reasons.append("selected_price_ge_0.95")
        elif no_bid is not None and no_bid <= 0.10:
            quality_score -= 8.0
            quality_reasons.append("no_bid_le_0.10")
        if yes_bid is not None and no_ask is not None:
            centered_price = min(max((yes_bid + (1.0 - no_ask)) / 2.0, 0.0), 1.0)
        else:
            centered_price = self.to_float(getattr(q, "selected_price", None), None)
        if centered_price is not None:
            if 0.35 <= centered_price <= 0.65:
                quality_score += 8.0
                quality_reasons.append("mid_range_price")
            elif 0.20 <= centered_price <= 0.80:
                quality_score += 4.0
                quality_reasons.append("moderate_price")
            elif centered_price <= 0.08 or centered_price >= 0.92:
                quality_score -= 10.0
                quality_reasons.append("extreme_price")
        if effective_spread is not None:
            if effective_spread <= 0.03:
                quality_score += 10.0
                quality_reasons.append("tight_spread")
            elif effective_spread <= 0.06:
                quality_score += 6.0
                quality_reasons.append("healthy_spread")
            elif effective_spread <= 0.10:
                quality_score += 1.0
                quality_reasons.append("acceptable_spread")
            elif effective_spread <= 0.20:
                quality_score -= 4.0
                quality_reasons.append("wide_spread")
            else:
                quality_score -= 12.0
                quality_reasons.append("very_wide_spread")
        if top_depth_total >= 20.0:
            quality_score += 8.0
            quality_reasons.append("deep_two_sided_depth")
        elif top_depth_total >= 10.0:
            quality_score += 5.0
            quality_reasons.append("healthy_two_sided_depth")
        elif top_depth_total > 0.0:
            quality_score += 1.0
            quality_reasons.append("thin_two_sided_depth")
        else:
            quality_score -= 8.0
            quality_reasons.append("empty_top_book")
        if top_depth_balance >= 0.80:
            quality_score += 5.0
            quality_reasons.append("balanced_liquidity")
        elif top_depth_balance >= 0.55:
            quality_score += 2.0
            quality_reasons.append("somewhat_balanced_liquidity")
        elif top_depth_total > 0.0:
            quality_score -= 4.0
            quality_reasons.append("imbalanced_liquidity")
        if str(liquidity_profile.get("spread_bucket") or "unknown").strip().lower() == "wide_but_possible":
            quality_score -= 3.0
            quality_reasons.append("wide_but_possible")
        elif str(liquidity_profile.get("spread_bucket") or "unknown").strip().lower() == "unsafe":
            quality_score -= 8.0
            quality_reasons.append("unsafe_spread_bucket")
        if self.to_float(execution_quality_profile.get("near_pass_count"), 0.0) >= 2:
            quality_score -= 4.0
            quality_reasons.append("repeated_near_pass")
        if str(execution_quality_profile.get("unsafe_price_status") or "").strip().lower() in {"unsafe_spread", "unexecutable_price"}:
            quality_score -= 6.0
            quality_reasons.append("unsafe_price_status")
        if self.to_float(execution_quality_profile.get("orderbook_age_seconds"), 0.0) > 300.0:
            quality_score -= 4.0
            quality_reasons.append("stale_orderbook")
        if self.to_float(execution_quality_profile.get("orderbook_age_seconds"), 0.0) > 900.0:
            quality_score -= 6.0
            quality_reasons.append("very_stale_orderbook")
        if price_family_state.get("recent_rejects", 0) > 0:
            quality_reasons.append("price_family_pressure")
        if price_family_state.get("cooldown_active"):
            quality_reasons.append("price_family_cooldown")
        quality_score -= min(24.0, float(price_family_state.get("penalty", 0.0) or 0.0))
        if missing_spread_state.get("recent_rejects", 0) > 0:
            quality_reasons.append("missing_spread_family_pressure")
        if missing_spread_state.get("cooldown_active"):
            quality_reasons.append("missing_spread_family_cooldown")
        quality_score -= min(24.0, float(missing_spread_state.get("penalty", 0.0) or 0.0))
        quality_score = round(quality_score, 4)
        quality_bonus = 10.0 if priority_tier == 1 else 6.0 if priority_tier == 2 else 0.0
        if family.startswith(("KXNBA", "KXMLB", "KXNFL")) and execution_quality_profile.get("quote_ready"):
            quality_bonus += 3.0
        market_priority_score = round((liquidity_score * 0.5) + (execution_quality_score * 0.45) + quality_bonus + quality_score, 4)
        deprioritize_reason = None
        if yes_ask is not None and yes_ask >= 0.95 and no_bid is not None and no_bid <= 0.05:
            deprioritize_reason = "near_resolved_low_edge"
        elif selected_price_value is not None and selected_price_value >= 0.99:
            deprioritize_reason = "selected_price_near_certain"
        elif execution_quality_profile.get("spread_bucket") == "unsafe":
            deprioritize_reason = "unsafe_spread_bucket"
        elif self.to_float(liquidity_priority.get("spread"), self.to_float(spread, 0.0)) > 0.20:
            deprioritize_reason = "spread_above_0_20"
        elif spread is None:
            deprioritize_reason = "spread_missing"
        elif price_family_state.get("cooldown_active"):
            deprioritize_reason = "price_family_cooldown"
        elif price_family_state.get("recent_rejects", 0) >= int(AION_PRICE_FAMILY_MIN_REJECTIONS):
            deprioritize_reason = "price_family_penalty"
        elif self.to_float(execution_quality_profile.get("orderbook_age_seconds"), 0.0) and self.to_float(execution_quality_profile.get("orderbook_age_seconds"), 0.0) > 300.0:
            deprioritize_reason = "stale_orderbook"
        elif execution_quality_profile.get("near_pass_count", 0) >= 2:
            deprioritize_reason = "repeated_near_pass"
        elif missing_spread_state.get("cooldown_active"):
            deprioritize_reason = "missing_spread_family_cooldown"
        elif family in DEPRIORITIZED_MARKET_FAMILIES:
            deprioritize_reason = "deprioritized_family"
        execution_probability = self._clamp(
            (execution_quality_profile.get("execution_probability", 0.0) * 0.65)
            + min(0.25, max(0.0, liquidity_score) / 120.0)
            + (0.08 if priority_tier == 1 else 0.04 if priority_tier == 2 else 0.0)
        )
        healthy_candidate = bool(
            spread is not None
            and spread <= 0.045
            and 0.15 <= self.to_float(yes_ask if yes_ask is not None else getattr(q, "selected_price", None), 0.0) <= 0.85
            and top_depth_total >= 10.0
            and top_depth_balance >= 0.55
            and yes_bid is not None
            and yes_ask is not None
            and yes_bid > 0.0
            and yes_ask > 0.0
        )
        if healthy_candidate:
            print(
                "[AION-HEALTHY-CANDIDATE-PROMOTED] "
                + json.dumps(
                    {
                        "ticker": ticker or None,
                        "family": family,
                        "spread": round(spread, 4) if spread is not None else None,
                        "yes_ask": round(yes_ask, 4) if yes_ask is not None else None,
                        "yes_bid": round(yes_bid, 4) if yes_bid is not None else None,
                        "top_depth_total": round(top_depth_total, 4),
                        "top_depth_balance": round(top_depth_balance, 4),
                        "market_priority_score": round((liquidity_score * 0.5) + (execution_quality_score * 0.45) + quality_bonus + quality_score, 4),
                        "deprioritize_reason": deprioritize_reason,
                    },
                    sort_keys=True,
                    default=str,
                )
            )
        return {
            "ticker": ticker or None,
            "family": family,
            "liquidity_score": round(liquidity_score, 4),
            "spread_bucket": execution_quality_profile.get("spread_bucket"),
            "priority_tier": priority_tier,
            "execution_probability": round(execution_probability, 4),
            "deprioritize_reason": deprioritize_reason,
            "market_priority_score": market_priority_score,
            "execution_quality_score": execution_quality_score,
            "market_quality_score": quality_score,
            "market_quality_reasons": quality_reasons,
            "price_family_recent_rejects": price_family_state.get("recent_rejects", 0),
            "price_family_cooldown_active": bool(price_family_state.get("cooldown_active")),
            "price_family_penalty": round(float(price_family_state.get("penalty", 0.0) or 0.0), 4),
            "missing_spread_family_penalty": round(float(missing_spread_state.get("penalty", 0.0) or 0.0), 4),
            "missing_spread_family_recent_rejects": missing_spread_state.get("recent_rejects", 0),
            "missing_spread_family_cooldown_active": bool(missing_spread_state.get("cooldown_active")),
            "near_resolved": bool(
                (yes_ask is not None and yes_ask >= 0.95 and no_bid is not None and no_bid <= 0.05)
                or (selected_price_value is not None and selected_price_value >= 0.99)
                or (selected_price_value is not None and selected_price_value <= 0.01)
            ),
            "balanced_liquidity": bool(top_depth_balance >= 0.55),
            "scan_weight": None,
            "liquidity_priority_profile": liquidity_profile,
            "execution_quality_profile": execution_quality_profile,
            "crypto_priority": bool(
                self.get_market_discovery_category(market) == "crypto"
                or family == "KXBTC15M"
                or family.startswith(("BTC", "ETH", "XRP", "KXBTC", "KXETH", "KXXRP"))
            ),
        }

    def _build_aion_scan_rebalancer_profile(self, *, family=None, market=None, q=None, liquidity_priority=None, execution_quality_profile=None):
        family = str(family or self.get_market_family(market or {}) or getattr(q, "family", "") or "UNKNOWN").strip().upper() or "UNKNOWN"
        market = market if isinstance(market, dict) else {}
        q = q if q is not None else self.build_quote(market)
        runtime_stats = dict((self.live_family_runtime_stats or {}).get(family, {}) or {})
        scan_count = int(runtime_stats.get("scan_count", 0) or runtime_stats.get("session_scan_count", 0) or 0)
        prefilter_survivors = int(runtime_stats.get("prefilter_survivors", 0) or 0)
        strict_validation_entrants = int(runtime_stats.get("strict_validation_entrants", 0) or 0)
        final_candidates = int(runtime_stats.get("final_candidates", 0) or 0)
        both_sides_quoted_count = int(runtime_stats.get("both_sides_quoted_count", 0) or runtime_stats.get("session_both_sides_quoted_count", 0) or 0)
        narrow_spread_count = int(runtime_stats.get("narrow_spread_count", 0) or runtime_stats.get("session_narrow_spread_count", 0) or 0)
        non_empty_top_book_count = int(runtime_stats.get("non_empty_top_book_count", 0) or runtime_stats.get("session_non_empty_top_book_count", 0) or 0)
        recent_activity_count = int(runtime_stats.get("recent_activity_count", 0) or 0)
        execution_hit_rate = (final_candidates / float(scan_count)) if scan_count > 0 else 0.0
        recent_safe_ratio = max(
            (both_sides_quoted_count / float(scan_count)) if scan_count > 0 else 0.0,
            (narrow_spread_count / float(scan_count)) if scan_count > 0 else 0.0,
            (non_empty_top_book_count / float(scan_count)) if scan_count > 0 else 0.0,
        )
        candidate_survival_rate = (final_candidates / float(prefilter_survivors)) if prefilter_survivors > 0 else 0.0
        family_category = self.get_market_discovery_category(market or family)
        universe_health_state = self._get_family_universe_health_snapshot(family)
        universe_health_score = float(universe_health_state.get("health_score", 0.0) or 0.0)
        scan_weight = 1.0
        if family.startswith(("BTC", "ETH", "XRP", "KXBTC", "KXETH", "KXXRP")) or family_category == "crypto":
            scan_weight += 0.45
        if family.startswith(("KXNBA", "KXMLB", "KXNFL")):
            scan_weight += 0.30
        if recent_safe_ratio >= 0.45:
            scan_weight += 0.25
        if candidate_survival_rate >= 0.25:
            scan_weight += 0.20
        if execution_hit_rate >= 0.20:
            scan_weight += 0.20
        if execution_quality_profile and self.to_float(execution_quality_profile.get("execution_quality_score"), 0.0) >= 65.0:
            scan_weight += 0.15
        if recent_activity_count > 0:
            scan_weight += 0.05
        scan_weight += (universe_health_score - 50.0) * 0.01
        if universe_health_state.get("suppressed"):
            scan_weight -= 0.35
        if universe_health_state.get("cooldown_active"):
            scan_weight -= 0.20
        if family in DEPRIORITIZED_MARKET_FAMILIES:
            scan_weight -= 0.35
        if any(value > 0 for value in (runtime_stats.get("wide_spread", 0), runtime_stats.get("missing_quotes", 0), runtime_stats.get("low_liquidity", 0))) and candidate_survival_rate <= 0.0:
            scan_weight -= 0.25
        scan_weight = round(self._clamp(scan_weight, 0.45, 2.0), 4)
        runtime_stats["execution_hit_rate"] = round(execution_hit_rate, 4)
        runtime_stats["recent_safe_ratio"] = round(recent_safe_ratio, 4)
        runtime_stats["candidate_survival_rate"] = round(candidate_survival_rate, 4)
        runtime_stats["scan_weight"] = scan_weight
        runtime_stats["scan_weight_family_category"] = family_category
        runtime_stats["universe_health_score"] = round(universe_health_score, 4)
        runtime_stats["universe_health_suppressed"] = bool(universe_health_state.get("suppressed"))
        runtime_stats["universe_health_suppress_reason"] = universe_health_state.get("suppress_reason")
        self.live_family_runtime_stats[family] = runtime_stats
        return {
            "family": family,
            "scan_weight": scan_weight,
            "execution_hit_rate": round(execution_hit_rate, 4),
            "recent_safe_ratio": round(recent_safe_ratio, 4),
            "candidate_survival_rate": round(candidate_survival_rate, 4),
            "scan_count": scan_count,
            "prefilter_survivors": prefilter_survivors,
            "strict_validation_entrants": strict_validation_entrants,
            "final_candidates": final_candidates,
            "recent_activity_count": recent_activity_count,
            "family_category": family_category,
            "universe_health_score": round(universe_health_score, 4),
            "universe_health_suppressed": bool(universe_health_state.get("suppressed")),
            "universe_health_suppress_reason": universe_health_state.get("suppress_reason"),
            "priority_tier": self._get_liquidity_priority_tier(market, family=family, ticker=getattr(q, "ticker", "")),
        }

    def _emit_aion_execution_blocker(self, *, ticker=None, family=None, exact_blocker=None, execution_path=None, selector_state=None, quote_state=None, cooldown_state=None, duplicate_state=None, position_state=None, auth_state=None, final_decision_state=None):
        payload = {
            "ticker": str(ticker or "").strip() or None,
            "family": str(family or "UNKNOWN").strip().upper() or "UNKNOWN",
            "exact_blocker": str(exact_blocker or "unknown").strip(),
            "execution_path": str(execution_path or "unknown").strip(),
            "selector_state": str(selector_state or "unknown").strip(),
            "quote_state": str(quote_state or "unknown").strip(),
            "cooldown_state": str(cooldown_state or "unknown").strip(),
            "duplicate_state": str(duplicate_state or "unknown").strip(),
            "position_state": str(position_state or "unknown").strip(),
            "auth_state": str(auth_state or "unknown").strip(),
            "final_decision_state": str(final_decision_state or "unknown").strip(),
        }
        print("[AION-EXECUTION-BLOCKER] " + json.dumps(payload, sort_keys=True, default=str))
        return payload

    def _build_aion_performance_dashboard(self, *, trade_readiness_records=None, failure_summary=None, live_select_summary=None, open_market_summary=None, selected_trade_submitted=False):
        trade_readiness_records = list(trade_readiness_records or [])
        failure_summary = failure_summary if isinstance(failure_summary, dict) else {}
        live_select_summary = live_select_summary if isinstance(live_select_summary, dict) else {}
        open_market_summary = open_market_summary if isinstance(open_market_summary, dict) else {}
        total_markets = int(live_select_summary.get("original_market_count") or live_select_summary.get("within_window") or len(trade_readiness_records) or 0)
        candidates_seen = int(live_select_summary.get("candidates_found") or len(trade_readiness_records) or 0)
        safe_book_count = sum(
            1
            for item in trade_readiness_records
            if isinstance(item, dict)
            and bool(item.get("quote_ready"))
            and str(item.get("spread_bucket") or "").strip().lower() in {"tight", "wide_but_possible"}
            and self.to_float(item.get("sports_edge_after_cost"), self.to_float(item.get("expectancy_score"), self.to_float(item.get("candidate_score"), 0.0))) > 0.0
        )
        execution_ready_count = sum(1 for item in trade_readiness_records if isinstance(item, dict) and str(item.get("phase55_status") or "").strip().lower() == "entry_ready")
        live_promotion_count = sum(1 for item in trade_readiness_records if isinstance(item, dict) and bool(item.get("decision") == "BUY") and str(item.get("spread_bucket") or "").strip().lower() in {"tight", "wide_but_possible"})
        execution_conversion_count = 1 if selected_trade_submitted else 0
        scan_efficiency = (candidates_seen / float(total_markets)) if total_markets > 0 else 0.0
        candidate_survival_pct = (execution_ready_count / float(candidates_seen)) if candidates_seen > 0 else 0.0
        safe_book_ratio = (safe_book_count / float(candidates_seen)) if candidates_seen > 0 else 0.0
        execution_ready_ratio = (execution_ready_count / float(candidates_seen)) if candidates_seen > 0 else 0.0
        live_promotion_ratio = (live_promotion_count / float(candidates_seen)) if candidates_seen > 0 else 0.0
        execution_conversion_ratio = (execution_conversion_count / float(live_promotion_count)) if live_promotion_count > 0 else float(execution_conversion_count)
        dashboard = {
            "scan_efficiency": round(scan_efficiency, 4),
            "candidate_survival_pct": round(candidate_survival_pct, 4),
            "safe_book_ratio": round(safe_book_ratio, 4),
            "execution_ready_ratio": round(execution_ready_ratio, 4),
            "live_promotion_ratio": round(live_promotion_ratio, 4),
            "execution_conversion_ratio": round(execution_conversion_ratio, 4),
            "total_markets": total_markets,
            "candidates_seen": candidates_seen,
            "execution_ready_count": execution_ready_count,
            "live_promotion_count": live_promotion_count,
            "execution_conversion_count": execution_conversion_count,
            "best_family": open_market_summary.get("best_open_family") or live_select_summary.get("best_candidate_family"),
            "best_ticker": open_market_summary.get("best_open_ticker") or live_select_summary.get("best_candidate_ticker"),
            "top_blocker": failure_summary.get("top_failure_reason") or live_select_summary.get("final_no_candidate_reason") or "unknown",
            "live_arb_enabled": bool(AION_LIVE_ARB_ENABLED),
        }
        return dashboard

    def _emit_aion_performance_dashboard(self, *, trade_readiness_records=None, failure_summary=None, live_select_summary=None, open_market_summary=None, selected_trade_submitted=False, force=False):
        now = time.time()
        last_emit = float(getattr(self, "last_aion_performance_dashboard_ts", 0.0) or 0.0)
        if not force and (now - last_emit) < 180.0:
            return getattr(self, "last_aion_performance_dashboard", {}) or {}
        dashboard = self._build_aion_performance_dashboard(
            trade_readiness_records=trade_readiness_records,
            failure_summary=failure_summary,
            live_select_summary=live_select_summary,
            open_market_summary=open_market_summary,
            selected_trade_submitted=selected_trade_submitted,
        )
        self.last_aion_performance_dashboard_ts = now
        self.last_aion_performance_dashboard = dict(dashboard)
        print("[AION-PERFORMANCE-DASHBOARD] " + json.dumps(dashboard, sort_keys=True, default=str))
        return dashboard

    def _resolve_aion_selector_edge_value(self, *, sports_context=None):
        sports_context = sports_context if isinstance(sports_context, dict) else {}
        selector_edge_used = None
        source_of_edge_value = None
        for key, source in (
            ("final_edge", "final_edge"),
            ("sports_edge_after_cost_after_family_bias", "sports_edge_after_cost_after_family_bias"),
            ("sports_edge_after_cost", "sports_edge_after_cost"),
        ):
            candidate_value = sports_context.get(key)
            if candidate_value is None:
                continue
            selector_edge_used = self.to_float(candidate_value, None)
            source_of_edge_value = source
            if selector_edge_used is not None:
                break
        if selector_edge_used is None:
            raw_edge_before_cost = self.to_float(sports_context.get("raw_edge_before_cost"), None)
            spread_cost = self.to_float(sports_context.get("spread_cost"), 0.0)
            estimated_cost = self.to_float(sports_context.get("estimated_cost"), 0.0)
            if raw_edge_before_cost is not None:
                selector_edge_used = max(0.0, raw_edge_before_cost - spread_cost - estimated_cost)
                source_of_edge_value = "raw_edge_before_cost_minus_costs"
        if selector_edge_used is None:
            selector_edge_used = 0.0
            source_of_edge_value = "unknown"
        return {
            "selector_edge_used": round(self.to_float(selector_edge_used, 0.0), 6),
            "source_of_edge_value": source_of_edge_value,
        }

    def _record_shadow_trade_track(self, *, ticker=None, family=None, market=None, q=None, score=None, decision_reason=None, spread_bucket=None, sports_edge_after_cost=None, expectancy_score=None, near_pass=False, queue_state=None, entry_timing_observation=None):
        if not AION_SHADOW_TRADE_TRACKING_ENABLED:
            return None
        market = market if isinstance(market, dict) else {}
        entry_timing_observation = entry_timing_observation if isinstance(entry_timing_observation, dict) else {}
        ticker = str(ticker or getattr(q, "ticker", "") or market.get("ticker", "") or "").strip()
        if not ticker:
            return None
        family = str(family or self.get_market_family(market) or getattr(q, "family", "") or "UNKNOWN").strip().upper() or "UNKNOWN"
        now = time.time()
        watchlist = getattr(self, "shadow_trade_watchlist_by_ticker", None)
        if not isinstance(watchlist, dict):
            watchlist = {}
            self.shadow_trade_watchlist_by_ticker = watchlist
        family_watchlist = getattr(self, "shadow_trade_watchlist_by_family", None)
        if not isinstance(family_watchlist, dict):
            family_watchlist = {}
            self.shadow_trade_watchlist_by_family = family_watchlist
        bucket = watchlist.setdefault(
            ticker,
            {
                "first_seen_time": now,
                "last_seen_time": now,
                "scan_count": 0,
                "near_pass_count": 0,
                "improving_count": 0,
                "decaying_count": 0,
                "best_score_seen": None,
                "best_edge_after_cost": None,
                "latest_queue_state": "unknown",
                "latest_blocker": "unknown",
                "latest_family": family,
                "latest_spread_bucket": str(spread_bucket or "unknown").strip().lower(),
                "history": deque(maxlen=24),
            },
        )
        prev_edge = self.to_float(bucket.get("best_edge_after_cost"), None)
        prev_score = self.to_float(bucket.get("best_score_seen"), None)
        current_score = self.to_float(score, 0.0)
        current_edge = self.to_float(sports_edge_after_cost, None)
        bucket["scan_count"] = int(bucket.get("scan_count", 0) or 0) + 1
        bucket["last_seen_time"] = now
        bucket["latest_family"] = family
        bucket["latest_queue_state"] = str(queue_state or bucket.get("latest_queue_state") or "unknown").strip().lower()
        bucket["latest_blocker"] = str(decision_reason or bucket.get("latest_blocker") or "unknown").strip().lower()
        bucket["latest_spread_bucket"] = str(spread_bucket or bucket.get("latest_spread_bucket") or "unknown").strip().lower()
        bucket["history"].append(
            {
                "ts": now,
                "score": round(current_score, 4),
                "edge_after_cost": round(current_edge, 4) if current_edge is not None else None,
                "reason": bucket["latest_blocker"],
                "queue_state": bucket["latest_queue_state"],
            }
        )
        if near_pass:
            bucket["near_pass_count"] = int(bucket.get("near_pass_count", 0) or 0) + 1
        if current_score > self.to_float(bucket.get("best_score_seen"), -1e9):
            bucket["best_score_seen"] = current_score
        if current_edge is not None and (prev_edge is None or current_edge > prev_edge):
            bucket["best_edge_after_cost"] = current_edge
        if prev_edge is not None and current_edge is not None and current_edge > prev_edge:
            bucket["improving_count"] = int(bucket.get("improving_count", 0) or 0) + 1
            print("[AION-SHADOW-TRADE-RESULT] " + json.dumps({
                "ticker": ticker,
                "family": family,
                "previous_edge_after_cost": round(prev_edge, 4),
                "current_edge_after_cost": round(current_edge, 4),
                "improvement_delta": round(current_edge - prev_edge, 4),
                "would_have_won": bool(current_edge > 0.0),
                "estimated_pnl": round((current_edge - prev_edge) * 100.0, 4),
                "scan_count": int(bucket.get("scan_count", 0) or 0),
                "age_seconds": round(now - float(bucket.get("first_seen_time") or now), 2),
                "latest_reason": bucket["latest_blocker"],
            }, sort_keys=True, default=str))
        elif current_edge is not None and prev_edge is not None and current_edge < prev_edge:
            bucket["decaying_count"] = int(bucket.get("decaying_count", 0) or 0) + 1
        family_bucket = family_watchlist.setdefault(
            family,
            {
                "family": family,
                "ticker_count": 0,
                "near_pass_count": 0,
                "improving_count": 0,
                "decaying_count": 0,
                "best_score_seen": None,
                "best_edge_after_cost": None,
                "latest_queue_state": "unknown",
                "latest_blocker": "unknown",
            },
        )
        family_bucket["ticker_count"] = len([item for item in watchlist.values() if isinstance(item, dict) and str(item.get("latest_family") or "").strip().upper() == family])
        family_bucket["near_pass_count"] = int(family_bucket.get("near_pass_count", 0) or 0) + (1 if near_pass else 0)
        family_bucket["improving_count"] = int(family_bucket.get("improving_count", 0) or 0) + (1 if current_edge is not None and prev_edge is not None and current_edge > prev_edge else 0)
        family_bucket["decaying_count"] = int(family_bucket.get("decaying_count", 0) or 0) + (1 if current_edge is not None and prev_edge is not None and current_edge < prev_edge else 0)
        family_bucket["best_score_seen"] = max(self.to_float(family_bucket.get("best_score_seen"), -1e9), current_score)
        if current_edge is not None:
            family_bucket["best_edge_after_cost"] = max(self.to_float(family_bucket.get("best_edge_after_cost"), -1e9), current_edge)
        family_bucket["latest_queue_state"] = bucket["latest_queue_state"]
        family_bucket["latest_blocker"] = bucket["latest_blocker"]
        bucket_summary = {
            "ticker": ticker,
            "family": family,
            "first_seen_time": bucket["first_seen_time"],
            "last_seen_time": bucket["last_seen_time"],
            "scan_count": bucket["scan_count"],
            "near_pass_count": bucket["near_pass_count"],
            "improving_count": bucket["improving_count"],
            "decaying_count": bucket["decaying_count"],
            "best_score_seen": round(self.to_float(bucket.get("best_score_seen"), 0.0), 4),
            "best_edge_after_cost": round(self.to_float(bucket.get("best_edge_after_cost"), 0.0), 4) if bucket.get("best_edge_after_cost") is not None else None,
            "latest_queue_state": bucket["latest_queue_state"],
            "latest_blocker": bucket["latest_blocker"],
            "age_seconds": round(now - float(bucket["first_seen_time"]), 2),
            "spread_bucket": bucket["latest_spread_bucket"],
            "live_arb_enabled": bool(AION_LIVE_ARB_ENABLED),
        }
        bucket["last_summary"] = bucket_summary
        bucket["latest_edge_after_cost"] = current_edge
        self.last_shadow_trade_track_summary = dict(bucket_summary)
        self._refresh_aion_expectancy_state(
            shadow_trade_summary=bucket_summary,
            relaxation_trade_count_today=self.relaxation_trades_today,
        )
        print("[AION-SHADOW-TRADE-TRACK] " + json.dumps(bucket_summary, sort_keys=True, default=str))
        return bucket_summary

    def _build_trade_failure_analyzer_summary(
        self,
        *,
        cycle_id=None,
        candidate_records=None,
        prefilter_rejects=None,
        strict_rejects=None,
        decision_skip_reasons=None,
        activation_denial_counts=None,
        execution_failure_audit=None,
    ):
        candidate_records = list(candidate_records or [])
        reason_counts = Counter()
        for source in (
            prefilter_rejects or {},
            strict_rejects or {},
            decision_skip_reasons or {},
            activation_denial_counts or {},
        ):
            for reason, count in source.items():
                reason_counts[str(reason)] += int(count or 0)
        if isinstance(execution_failure_audit, dict):
            failure_reasons = execution_failure_audit.get("failure_reasons")
            if isinstance(failure_reasons, Counter):
                reason_counts.update({str(reason): int(count or 0) for reason, count in failure_reasons.items()})
            elif isinstance(failure_reasons, dict):
                reason_counts.update({str(reason): int(count or 0) for reason, count in failure_reasons.items()})
        top_failure_reason = reason_counts.most_common(1)[0][0] if reason_counts else "unknown"
        rejected_candidates = [item for item in candidate_records if str(item.get("decision") or "").upper() != "BUY"]
        best_rejected = None
        if rejected_candidates:
            best_rejected = max(
                rejected_candidates,
                key=lambda item: (
                    self.to_float(item.get("expectancy_score"), self.to_float(item.get("candidate_score"), 0.0)),
                    self.to_float(item.get("candidate_score"), 0.0),
                    self.to_float(item.get("sports_edge_after_cost"), -9e9),
                    self.to_float(item.get("score_gap"), -9e9) * -1.0,
                ),
            )
        would_have_passed_if_relaxed = False
        recommended_relaxation = "none"
        best_rejected_score = None
        best_rejected_edge_after_cost = None
        best_rejected_spread_bucket = None
        best_rejected_ticker = None
        best_rejected_family = None
        if isinstance(best_rejected, dict):
            best_rejected_ticker = best_rejected.get("ticker")
            best_rejected_family = best_rejected.get("family")
            best_rejected_score = best_rejected.get("expectancy_score", best_rejected.get("candidate_score"))
            best_rejected_edge_after_cost = best_rejected.get("sports_edge_after_cost")
            best_rejected_spread_bucket = best_rejected.get("spread_bucket")
            would_have_passed_if_relaxed = bool(
                self.to_float(best_rejected.get("expectancy_score"), 0.0) >= 0.66
                and self.to_float(best_rejected.get("candidate_score"), 0.0) >= (PHASE5_BUY_SCORE_THRESHOLD - 6.0)
                and str(best_rejected.get("spread_bucket") or "").strip().lower() in {"ultra_tight", "tight", "acceptable"}
            )
        if top_failure_reason in {"phase55_status_pullback_wait", "phase55_status_trigger_wait", "timing_penalty", "no_micro_pullback", "no_stochastic_crossover"}:
            recommended_relaxation = "phase55_fastpath"
        elif top_failure_reason in {"post_loss_family_cooldown", "cooldown", "execution_attempt_cooldown"}:
            recommended_relaxation = "cooldown_soft_bypass"
        elif top_failure_reason in {"wide_spread", "poor_spread_score", "spread_too_wide", "spread_above_hard_limit"}:
            recommended_relaxation = "spread_liquidity_adaptive_pass"
        elif top_failure_reason in {"low_liquidity_score", "low_liquidity", "weak_liquidity"}:
            recommended_relaxation = "spread_liquidity_adaptive_pass"
        elif top_failure_reason in {"edge_below_cost", "edge_at_or_below_zero"}:
            recommended_relaxation = "no_relaxation"
        else:
            recommended_relaxation = "expectancy_fastpath"
        summary = {
            "cycle_id": int(cycle_id or self.cycle_count or 0),
            "top_failure_reason": top_failure_reason,
            "reason_counts": dict(reason_counts.most_common(12)),
            "best_rejected_ticker": best_rejected_ticker,
            "best_rejected_family": best_rejected_family,
            "best_rejected_score": round(self.to_float(best_rejected_score, 0.0), 4) if best_rejected_score is not None else None,
            "best_rejected_edge_after_cost": round(self.to_float(best_rejected_edge_after_cost, 0.0), 4) if best_rejected_edge_after_cost is not None else None,
            "best_rejected_spread_bucket": best_rejected_spread_bucket,
            "would_have_passed_if_relaxed": bool(would_have_passed_if_relaxed),
            "recommended_relaxation": recommended_relaxation,
            "candidate_count": int(len(candidate_records)),
            "live_arb_enabled": bool(AION_LIVE_ARB_ENABLED),
        }
        self.last_trade_failure_analyzer_summary = dict(summary)
        self._refresh_aion_expectancy_state(
            failure_summary=summary,
            relaxation_trade_count_today=self.relaxation_trades_today,
        )
        return summary

    def _emit_trade_failure_analyzer_telemetry(self, summary=None, *, force=False):
        summary = summary if isinstance(summary, dict) else self.last_trade_failure_analyzer_summary or {}
        if not summary:
            return None
        now = time.time()
        last_emit = float(getattr(self, "last_trade_failure_analyzer_ts", 0.0) or 0.0)
        if not force and (now - last_emit) < 120.0:
            return summary
        self.last_trade_failure_analyzer_ts = now
        print("[AION-TRADE-FAILURE-ANALYZER] " + json.dumps(summary, sort_keys=True, default=str))
        return summary

    def _build_daily_profitability_dashboard(self, *, trade_readiness_records=None, failure_summary=None):
        trade_readiness_records = list(trade_readiness_records or [])
        failure_summary = failure_summary if isinstance(failure_summary, dict) else {}
        family_perf = dict(self.live_family_perf_stats or {})
        best_family = None
        worst_family = None
        if family_perf:
            best_family = max(family_perf.items(), key=lambda item: (self.to_float(item[1].get("pnl"), 0.0), int(item[1].get("trades", 0) or 0)))[0]
            worst_family = min(family_perf.items(), key=lambda item: (self.to_float(item[1].get("pnl"), 0.0), -int(item[1].get("trades", 0) or 0)))[0]
        missed_opportunity_count = sum(
            1
            for item in trade_readiness_records
            if str(item.get("decision") or "").upper() != "BUY"
            and self.to_float(item.get("candidate_score"), 0.0) >= (PHASE5_BUY_SCORE_THRESHOLD - 5.0)
        )
        shadow_would_have_won_count = 0
        shadow_entries = 0
        for bucket in (self.shadow_trade_watchlist_by_ticker or {}).values():
            if not isinstance(bucket, dict):
                continue
            shadow_entries += 1
            if self.to_float(bucket.get("best_edge_after_cost"), -1.0) > 0.0:
                shadow_would_have_won_count += 1
        if self.relaxation_trade_day != time.strftime("%Y-%m-%d"):
            self.relaxation_trade_day = time.strftime("%Y-%m-%d")
            self.relaxation_trades_today = int(self.relaxation_trades_today or 0)
            self.relaxation_trade_pnl_today = float(self.relaxation_trade_pnl_today or 0.0)
            self.relaxation_trade_tickers = set(self.relaxation_trade_tickers or set())
        summary = {
            "live_trades_today": int(self.live_trade_count_today or 0),
            "wins_today": int(self.live_perf_wins_today or 0),
            "losses_today": int(self.live_perf_losses_today or 0),
            "realized_pnl_today": round(float(self.live_realized_pnl_today or 0.0), 4),
            "estimated_fees_today": round(max(0.0, float(self.live_trade_count_today or 0) * 0.01), 4),
            "average_edge_at_entry": round(
                sum(self.to_float(item.get("expectancy_score"), self.to_float(item.get("candidate_score"), 0.0)) for item in trade_readiness_records) / max(len(trade_readiness_records), 1),
                4,
            ),
            "average_spread_at_entry": round(
                sum(self.to_float(item.get("spread"), 0.0) for item in trade_readiness_records) / max(len(trade_readiness_records), 1),
                4,
            ),
            "most_common_rejection_reason": failure_summary.get("top_failure_reason") or (failure_summary.get("reason_counts") or {}).get("unknown") or "unknown",
            "best_family_today": best_family,
            "worst_family_today": worst_family,
            "missed_opportunity_count": int(missed_opportunity_count),
            "shadow_would_have_won_count": int(shadow_would_have_won_count),
            "relaxation_trades_count": int(self.relaxation_trades_today or 0),
            "relaxation_trade_pnl": round(float(self.relaxation_trade_pnl_today or 0.0), 4),
            "best_rejected_ticker": failure_summary.get("best_rejected_ticker"),
            "best_rejected_family": failure_summary.get("best_rejected_family"),
            "best_rejected_score": failure_summary.get("best_rejected_score"),
            "live_arb_enabled": bool(AION_LIVE_ARB_ENABLED),
            "shadow_entries": int(shadow_entries),
        }
        return summary

    def _emit_daily_profitability_dashboard(self, *, trade_readiness_records=None, failure_summary=None, force=False):
        now = time.time()
        last_emit = float(getattr(self, "last_daily_profitability_dashboard_ts", 0.0) or 0.0)
        if not force and (now - last_emit) < 180.0:
            return getattr(self, "last_daily_profitability_dashboard", {}) or {}
        summary = self._build_daily_profitability_dashboard(
            trade_readiness_records=trade_readiness_records,
            failure_summary=failure_summary,
        )
        self.last_daily_profitability_dashboard_ts = now
        self.last_daily_profitability_dashboard = dict(summary)
        self._refresh_aion_expectancy_state(
            dashboard_summary=summary,
            relaxation_trade_count_today=self.relaxation_trades_today,
            force_save=force,
        )
        print("[AION-DAILY-PROFITABILITY-DASHBOARD] " + json.dumps(summary, sort_keys=True, default=str))
        return summary

    def _should_allow_controlled_family_cooldown_bypass(self, *, ticker=None, family=None, gate_record=None, now_ts=None):
        now_ts = float(now_ts or time.time())
        gate_record = gate_record if isinstance(gate_record, dict) else {}
        ticker = str(ticker or gate_record.get("ticker") or "").strip()
        family = str(family or gate_record.get("family") or "UNKNOWN").strip().upper() or "UNKNOWN"
        if not AION_COOLDOWN_SOFT_BYPASS_ENABLED:
            return False, "controlled_loosen_disabled"
        if not AION_CONTROLLED_LOOSENING_ENABLED or not AION_EXPECTANCY_SCORE_ENABLED:
            return False, "loosening_disabled"
        if AION_LIVE_ARB_ENABLED:
            return False, "live_arb_enabled"
        today = time.strftime("%Y-%m-%d")
        if self.relaxation_trade_day != today:
            self.relaxation_trade_day = today
            self.relaxation_trades_today = int(self.relaxation_trades_today or 0)
            self.relaxation_trade_pnl_today = float(self.relaxation_trade_pnl_today or 0.0)
            self.relaxation_trade_tickers = set(self.relaxation_trade_tickers or set())
        if self.relaxation_trades_today >= AION_MAX_RELAXATION_TRADES_PER_DAY:
            return False, "relaxation_trade_cap"
        session_state = self._get_live_session_mode()
        if session_state.get("mode") in {"defensive", "protected"} or self.live_realized_pnl_today <= KALSHI_DEFENSIVE_MODE_PNL:
            return False, "session_risk_too_high"
        if self.trading_halted or self.realized_pnl <= -MAX_DAILY_LOSS:
            return False, "daily_loss_guard"
        family_event = dict((self.live_post_loss_family_cooldowns or {}).get(family, {}) or {})
        if not family_event:
            return False, "no_family_cooldown"
        expires_at = float(family_event.get("expires_at", 0.0) or 0.0)
        if expires_at <= now_ts:
            return False, "family_cooldown_expired"
        if ticker and str(family_event.get("ticker") or "").strip() == ticker:
            return False, "same_ticker_cooldown"
        expectancy_score = self.to_float(gate_record.get("expectancy_score"), 0.0)
        sports_edge_after_cost = self.to_float(gate_record.get("sports_edge_after_cost"), 0.0)
        spread_bucket = str(gate_record.get("spread_bucket") or "").strip().lower()
        if expectancy_score < 0.62 or sports_edge_after_cost <= 0.0 or spread_bucket not in {"ultra_tight", "tight", "acceptable"}:
            return False, "insufficient_expectancy"
        duplicate_check = self.check_live_duplicate_position_api(ticker) if ticker else {"blocked": False}
        if duplicate_check.get("blocked"):
            return False, duplicate_check.get("reason") or "duplicate"
        return True, {
            "family": family,
            "ticker": ticker,
            "family_cooldown_reason": str(family_event.get("reason") or "family_cooldown"),
            "remaining_seconds": int(max(0, expires_at - now_ts)),
            "expectancy_score": round(expectancy_score, 4),
            "sports_edge_after_cost": round(sports_edge_after_cost, 4),
            "spread_bucket": spread_bucket,
        }

    def _build_trade_readiness_snapshot(
        self,
        *,
        total_markets_scanned=0,
        candidates_reaching_prefilter=0,
        candidates_passing_adaptive_spread=0,
        candidates_passing_momentum=0,
        candidates_reaching_phase55=0,
        candidates_blocked_by_execution_safety=0,
        candidate_records=None,
        best_prefilter_candidate=None,
        prefilter_reject_reason_counts=None,
        strict_reject_reason_counts=None,
        decision_skip_reasons=None,
        activation_denial_counts=None,
        selected_candidate=None,
        selected_trade_submitted=False,
    ):
        candidate_records = list(candidate_records or [])
        combined_rejection_counts = Counter()
        for source_counts in (
            prefilter_reject_reason_counts or {},
            strict_reject_reason_counts or {},
            decision_skip_reasons or {},
            activation_denial_counts or {},
        ):
            for reason, count in source_counts.items():
                combined_rejection_counts[str(reason)] += int(count or 0)
        best_candidate = selected_candidate if isinstance(selected_candidate, dict) else None
        if best_candidate is None:
            if candidate_records:
                best_candidate = max(
                    candidate_records,
                    key=lambda item: (
                        self.to_float(item.get("candidate_score"), -9999.0),
                        self.to_float(item.get("probability_confidence"), -9999.0),
                    ),
                )
            elif isinstance(best_prefilter_candidate, dict):
                best_candidate = dict(best_prefilter_candidate)
        nearest_pass_candidate = None
        if not selected_trade_submitted:
            rejected_candidates = [item for item in candidate_records if str(item.get("decision") or "").upper() != "BUY"]
            if rejected_candidates:
                nearest_pass_candidate = max(
                    rejected_candidates,
                    key=lambda item: (
                        self.to_float(item.get("candidate_score"), -9999.0),
                        self.to_float(item.get("probability_confidence"), -9999.0),
                    ),
                )
            elif isinstance(best_prefilter_candidate, dict) and not candidate_records:
                nearest_pass_candidate = dict(best_prefilter_candidate)
        if nearest_pass_candidate is None and candidate_records:
            nearest_pass_candidate = max(
                candidate_records,
                key=lambda item: (
                    self.to_float(item.get("candidate_score"), -9999.0),
                    self.to_float(item.get("probability_confidence"), -9999.0),
                ),
            )
        nearest_pass_reason = "no_viable_candidate"
        suggested_next_condition = self._trade_readiness_next_condition(nearest_pass_reason)
        if nearest_pass_candidate is not None:
            nearest_pass_reason = self._classify_trade_readiness_nearest_pass(nearest_pass_candidate)
            suggested_next_condition = self._trade_readiness_next_condition(nearest_pass_reason)
        top_blockers = combined_rejection_counts.most_common(3)
        top_rejection_reason = top_blockers[0][0] if top_blockers else "no_viable_candidate"
        best_candidate_ticker = None
        best_candidate_family = None
        best_candidate_score = None
        best_candidate_confidence = None
        if isinstance(best_candidate, dict):
            best_candidate_ticker = best_candidate.get("ticker")
            best_candidate_family = best_candidate.get("family")
            best_candidate_score = best_candidate.get("candidate_score")
            best_candidate_confidence = best_candidate.get("probability_confidence")
            if best_candidate_confidence is None:
                score_breakdown = best_candidate.get("score_breakdown")
                if isinstance(score_breakdown, dict):
                    best_candidate_confidence = score_breakdown.get("confidence")
        snapshot = {
            "enabled": bool(AION_CALIBRATION_MODE or AION_CALIBRATION_RELAXED_SHADOW),
            "calibration_mode": bool(AION_CALIBRATION_MODE),
            "relaxed_shadow": bool(AION_CALIBRATION_RELAXED_SHADOW),
            "total_markets_scanned": int(total_markets_scanned or 0),
            "candidates_reaching_prefilter": int(candidates_reaching_prefilter or 0),
            "candidates_passing_adaptive_spread": int(candidates_passing_adaptive_spread or 0),
            "candidates_passing_momentum": int(candidates_passing_momentum or 0),
            "candidates_reaching_phase55": int(candidates_reaching_phase55 or 0),
            "candidates_blocked_by_execution_safety": int(candidates_blocked_by_execution_safety or 0),
            "best_candidate_ticker": best_candidate_ticker,
            "best_candidate_family": best_candidate_family,
            "best_candidate_score": best_candidate_score,
            "best_candidate_confidence": best_candidate_confidence,
            "top_rejection_reason": top_rejection_reason,
            "nearest_pass_reason": nearest_pass_reason,
            "suggested_next_condition": suggested_next_condition,
            "top_blockers": top_blockers,
        }
        return snapshot

    def _calculate_confidence_decay(self, raw_confidence, sample_age_seconds=None, regime_staleness=0.0, sample_size=0, contradictory_score=0.0):
        raw_confidence = self._clamp(raw_confidence)
        sample_size = max(0, int(sample_size or 0))
        sample_age_seconds = max(0.0, float(sample_age_seconds or 0.0))
        age_penalty = min(0.45, sample_age_seconds / float(6 * 3600)) * 0.45
        staleness_penalty = self._clamp(regime_staleness) * 0.25
        sample_penalty = 0.0 if sample_size >= 10 else (0.25 if sample_size < 5 else 0.12)
        contradiction_penalty = self._clamp(contradictory_score) * 0.20
        decay_factor = self._clamp(1.0 - age_penalty - staleness_penalty - sample_penalty - contradiction_penalty, 0.20, 1.0)
        return {
            "raw_confidence": self._safe_round(raw_confidence, 4, 0.0),
            "decay_factor": self._safe_round(decay_factor, 4, 1.0),
            "decayed_confidence": self._safe_round(raw_confidence * decay_factor, 4, 0.0),
            "decay_reason": "age" if age_penalty >= max(staleness_penalty, sample_penalty, contradiction_penalty) else "regime" if staleness_penalty >= max(sample_penalty, contradiction_penalty) else "sample" if sample_penalty >= contradiction_penalty else "contradiction" if contradiction_penalty > 0 else "stable",
        }

    def _update_market_personality_profiles(self, markets=None, quotes=None):
        markets = markets or []
        quotes = quotes or []
        family_summaries = {}
        quote_lookup = {getattr(q, "ticker", ""): q for q in quotes if getattr(q, "ticker", "")}
        for market in markets:
            ticker = str(market.get("ticker", "") or "").strip()
            if not ticker:
                continue
            q = quote_lookup.get(ticker)
            if q is None:
                continue
            family = self.get_market_family(market)
            category = self.get_market_discovery_category(market)
            context = self._build_entry_context(q=q, market=market, strategy_label="observed", source="market_observation")
            summary = family_summaries.setdefault(
                family,
                {
                    "family": family,
                    "category": category,
                    "count": 0,
                    "spread_total": 0.0,
                    "liquidity_total": 0.0,
                    "volume_total": 0.0,
                    "momentum_total": 0.0,
                    "volatility_total": 0.0,
                    "quote_reliability_total": 0.0,
                    "liquidity_reliability_total": 0.0,
                    "spread_stability_total": 0.0,
                    "fake_breakout_total": 0.0,
                    "time_to_event_bucket_counts": {},
                    "last_seen_at": time.time(),
                },
            )
            summary["count"] += 1
            summary["spread_total"] += self.to_float(context.get("spread"), 0.0)
            summary["liquidity_total"] += self.to_float(context.get("liquidity"), 0.0)
            summary["volume_total"] += self.to_float(context.get("volume"), 0.0)
            summary["momentum_total"] += self.to_float(context.get("momentum_score"), 0.0)
            summary["volatility_total"] += self.to_float(context.get("volatility"), 0.0)
            summary["quote_reliability_total"] += self.to_float(context.get("quote_reliability"), 0.0)
            summary["liquidity_reliability_total"] += self.to_float(context.get("liquidity_reliability"), 0.0)
            summary["spread_stability_total"] += self.to_float(context.get("spread_stability"), 0.0)
            summary["fake_breakout_total"] += self.to_float(context.get("fake_breakout_risk"), 0.0)
            bucket = context.get("time_to_event_bucket") or "unknown"
            summary["time_to_event_bucket_counts"][bucket] = summary["time_to_event_bucket_counts"].get(bucket, 0) + 1

        now_ts = time.time()
        updated_families = {}
        for family, observed in family_summaries.items():
            count = max(1, int(observed.get("count", 0) or 0))
            outcome_stats = self._get_combined_family_outcome_stats(family)
            avg_spread = observed["spread_total"] / count
            avg_liquidity = observed["liquidity_total"] / count
            avg_volume = observed["volume_total"] / count
            avg_momentum = observed["momentum_total"] / count
            avg_volatility = observed["volatility_total"] / count
            quote_reliability = observed["quote_reliability_total"] / count
            liquidity_reliability = observed["liquidity_reliability_total"] / count
            spread_stability = observed["spread_stability_total"] / count
            fake_breakout_risk = observed["fake_breakout_total"] / count
            momentum_bias = self._clamp((avg_momentum + max(0.0, quote_reliability - 0.5) + min(0.5, avg_volatility)) / 1.5)
            reversion_bias = self._clamp((max(0.0, 0.5 - avg_momentum) + spread_stability + (1.0 - quote_reliability)) / 3.0)
            personality_type = "balanced"
            if fake_breakout_risk >= 0.65:
                personality_type = "fake_breakout_prone"
            elif momentum_bias >= 0.60 and reversion_bias < 0.45:
                personality_type = "momentum_heavy"
            elif reversion_bias >= 0.60 and momentum_bias < 0.45:
                personality_type = "mean_reversion"
            elif liquidity_reliability < 0.40 or quote_reliability < 0.40:
                personality_type = "unstable"
            historical_confidence = self._clamp(
                min(1.0, (count + outcome_stats.get("samples", 0)) / 30.0)
            )
            sample_age_seconds = max(0.0, now_ts - float(observed.get("last_seen_at") or now_ts))
            decay = self._calculate_confidence_decay(
                historical_confidence,
                sample_age_seconds=sample_age_seconds,
                regime_staleness=0.0 if sample_age_seconds < 3600 else 0.25,
                sample_size=count + outcome_stats.get("samples", 0),
                contradictory_score=max(0.0, reversion_bias - momentum_bias),
            )
            category, used_category_fallback, fallback_category = self._resolve_market_category_label(observed)
            if used_category_fallback:
                title = str(
                    observed.get("title")
                    or observed.get("subtitle")
                    or observed.get("no_sub_title")
                    or ""
                ).strip() or "unknown"
                print(
                    f"[LIVE-CATEGORY-FALLBACK] ticker={observed.get('ticker', 'unknown')} "
                    f"title={title} fallback_category={fallback_category}"
                )
            profile = {
                "family": family,
                "category": category,
                "personality_type": personality_type,
                "momentum_bias": self._safe_round(momentum_bias, 4, 0.0),
                "reversion_bias": self._safe_round(reversion_bias, 4, 0.0),
                "fake_breakout_risk": self._safe_round(fake_breakout_risk, 4, 0.0),
                "liquidity_reliability": self._safe_round(liquidity_reliability, 4, 0.0),
                "spread_stability": self._safe_round(spread_stability, 4, 0.0),
                "quote_reliability": self._safe_round(quote_reliability, 4, 0.0),
                "historical_confidence": decay.get("decayed_confidence"),
                "raw_historical_confidence": decay.get("raw_confidence"),
                "confidence_decay_factor": decay.get("decay_factor"),
                "confidence_decay_reason": decay.get("decay_reason"),
                "sample_count": count,
                "outcome_samples": outcome_stats.get("samples", 0),
                "win_rate": self._safe_round(outcome_stats.get("win_rate"), 4, 0.0),
                "average_pnl": self._safe_round(outcome_stats.get("avg_pnl"), 4, 0.0),
                "typical_volatility": self._safe_round(avg_volatility, 4, 0.0),
                "typical_execution_quality": self._safe_round((quote_reliability + liquidity_reliability + spread_stability) / 3.0, 4, 0.0),
                "avg_spread": self._safe_round(avg_spread, 4, 0.0),
                "avg_liquidity": self._safe_round(avg_liquidity, 4, 0.0),
                "avg_volume": self._safe_round(avg_volume, 4, 0.0),
                "last_seen_at": now_ts,
                "time_to_event_bucket_counts": observed.get("time_to_event_bucket_counts", {}),
            }
            updated_families[family] = profile
            print(
                f"[LIVE-MARKET-PERSONALITY] family={family} category={profile.get('category', 'unknown')} "
                f"personality_type={profile['personality_type']} momentum_bias={profile['momentum_bias']} "
                f"reversion_bias={profile['reversion_bias']} fake_breakout_risk={profile['fake_breakout_risk']} "
                f"liquidity_reliability={profile['liquidity_reliability']} spread_stability={profile['spread_stability']} "
                f"quote_reliability={profile['quote_reliability']} historical_confidence={profile['historical_confidence']}"
            )
        if updated_families:
            profiles = self.market_personality_profiles if isinstance(self.market_personality_profiles, dict) else {"version": 1, "updated_at": None, "families": {}}
            profiles["version"] = int(profiles.get("version", 1) or 1)
            profiles["updated_at"] = now_ts
            families = profiles.setdefault("families", {})
            families.update(updated_families)
            self.market_personality_profiles = profiles
            self.save_market_personality_profiles(profiles)
        return updated_families

    def _score_trade_memory_similarity(self, current_context):
        rows = self._load_trade_history_rows(limit=400)
        if not rows:
            return {
                "similar_setups_found": 0,
                "similar_win_rate": None,
                "similar_average_pnl": None,
                "similar_failure_pattern": "insufficient_history",
                "similarity_confidence": 0.0,
                "memory_recommendation": "neutral",
                "sample_size": 0,
            }
        family = current_context.get("family")
        category = current_context.get("category")
        spread_bucket = current_context.get("spread_bucket")
        liquidity_bucket = current_context.get("liquidity_bucket")
        volatility_bucket = current_context.get("volatility_bucket")
        momentum_bucket = current_context.get("momentum_bucket")
        probabilistic_bucket = current_context.get("probability_bucket")
        strategy_label = current_context.get("strategy_label")
        time_to_event_bucket = current_context.get("time_to_event_bucket")
        entry_timing_state = current_context.get("entry_timing_state")
        similar_rows = []
        for row in rows:
            row_family = self.get_market_family({"ticker": row.get("ticker", "")})
            row_category = row.get("category") or self.get_market_discovery_category({"ticker": row.get("ticker", "")})
            row_spread_bucket = row.get("spread_bucket") or self._spread_bucket(self.to_float(row.get("yes_ask"), None) - self.to_float(row.get("yes_bid"), None) if row.get("yes_bid") and row.get("yes_ask") else None)
            row_liquidity_bucket = row.get("liquidity_bucket") or self._liquidity_bucket(self.to_float(row.get("liquidity"), None))
            row_volatility_bucket = row.get("volatility_bucket") or self._volatility_bucket(self.to_float(row.get("volatility"), None))
            row_momentum_bucket = row.get("momentum_bucket") or self._momentum_bucket(self.to_float(row.get("momentum_score"), None))
            row_probability_bucket = row.get("probability_bucket") or self._probability_bucket(self.to_float(row.get("probabilistic_score"), None))
            row_strategy_label = row.get("strategy_label") or "unknown"
            row_time_bucket = row.get("time_to_event_bucket") or "unknown"
            row_entry_timing = row.get("entry_timing_state") or "unknown"
            matches = 0
            weight = 0.0
            if family and row_family == family:
                matches += 1
                weight += 1.0
            if category and row_category == category:
                matches += 1
                weight += 1.0
            if spread_bucket and row_spread_bucket == spread_bucket:
                matches += 1
                weight += 1.0
            if liquidity_bucket and row_liquidity_bucket == liquidity_bucket:
                matches += 1
                weight += 1.0
            if volatility_bucket and row_volatility_bucket == volatility_bucket:
                matches += 1
                weight += 1.0
            if momentum_bucket and row_momentum_bucket == momentum_bucket:
                matches += 1
                weight += 1.0
            if probabilistic_bucket and row_probability_bucket == probabilistic_bucket:
                matches += 1
                weight += 1.0
            if strategy_label and row_strategy_label == strategy_label:
                matches += 1
                weight += 0.5
            if time_to_event_bucket and row_time_bucket == time_to_event_bucket:
                matches += 1
                weight += 0.5
            if entry_timing_state and row_entry_timing == entry_timing_state:
                matches += 1
                weight += 0.5
            if weight < 2.5:
                continue
            pnl = self.to_float(row.get("realized_pnl"), 0.0)
            similar_rows.append({
                "row": row,
                "weight": weight,
                "pnl": pnl,
                "win": pnl > 0,
            })
        if not similar_rows:
            return {
                "similar_setups_found": 0,
                "similar_win_rate": None,
                "similar_average_pnl": None,
                "similar_failure_pattern": "no_similar_history",
                "similarity_confidence": 0.0,
                "memory_recommendation": "neutral",
                "sample_size": 0,
            }
        similar_rows.sort(key=lambda item: item["weight"], reverse=True)
        top_rows = similar_rows[:25]
        similar_setups_found = len(top_rows)
        wins = sum(1 for item in top_rows if item["win"])
        total_pnl = sum(item["pnl"] for item in top_rows)
        similar_win_rate = wins / similar_setups_found if similar_setups_found else None
        similar_average_pnl = total_pnl / similar_setups_found if similar_setups_found else None
        failure_reason_counts = {}
        for item in top_rows:
            if item["pnl"] < 0:
                reason = str(item["row"].get("reason") or "negative_pnl").strip() or "negative_pnl"
                failure_reason_counts[reason] = failure_reason_counts.get(reason, 0) + 1
        failure_pattern = "negative_pnl" if not failure_reason_counts else sorted(failure_reason_counts.items(), key=lambda item: item[1], reverse=True)[0][0]
        similarity_confidence = self._clamp(similar_setups_found / 12.0)
        if similar_win_rate is not None and similar_average_pnl is not None and similar_win_rate >= 0.6 and similar_average_pnl > 0:
            recommendation = "support_entry"
        elif similar_win_rate is not None and similar_win_rate < 0.4:
            recommendation = "avoid_if_optional"
        elif similar_average_pnl is not None and similar_average_pnl < 0:
            recommendation = "reduce_confidence"
        else:
            recommendation = "neutral"
        return {
            "similar_setups_found": similar_setups_found,
            "similar_win_rate": self._safe_round(similar_win_rate, 4, None),
            "similar_average_pnl": self._safe_round(similar_average_pnl, 4, None),
            "similar_failure_pattern": failure_pattern,
            "similarity_confidence": self._safe_round(similarity_confidence, 4, 0.0),
            "memory_recommendation": recommendation,
            "sample_size": similar_setups_found,
        }

    def _classify_market_behavior_state(self, context, profile=None):
        profile = profile or {}
        liquidity_reliability = self._clamp(context.get("liquidity_reliability", 0.0))
        quote_reliability = self._clamp(context.get("quote_reliability", 0.0))
        fake_breakout_risk = self._clamp(context.get("fake_breakout_risk", 0.0))
        volatility = self._clamp((context.get("volatility") or 0.0) / 0.10)
        momentum = self._clamp(abs(context.get("momentum_score") or 0.0))
        spread_stability = self._clamp(context.get("spread_stability", 0.0))
        spread = context.get("spread")
        spread_shock = self._clamp((spread or 0.0) / max(MAX_ENTRY_SPREAD, 0.01))
        panic_score = self._clamp((volatility * 0.45) + ((1.0 - liquidity_reliability) * 0.35) + (spread_shock * 0.20))
        euphoria_score = self._clamp((max(0.0, context.get("momentum_score") or 0.0) * 0.55) + (1.0 - spread_stability) * 0.25 + volatility * 0.20)
        exhaustion_score = self._clamp((volatility * 0.40) + ((1.0 - momentum) * 0.30) + ((1.0 - quote_reliability) * 0.30))
        fake_urgency_score = self._clamp((fake_breakout_risk * 0.55) + (spread_shock * 0.25) + ((1.0 - quote_reliability) * 0.20))
        dead_liquidity_risk = self._clamp(((1.0 - liquidity_reliability) * 0.60) + ((1.0 - quote_reliability) * 0.25) + (1.0 - spread_stability) * 0.15)
        if dead_liquidity_risk >= 0.75:
            behavior_state = "dead_liquidity_trap"
            recommended_response = "avoid"
        elif panic_score >= 0.72:
            behavior_state = "panic_spike"
            recommended_response = "reduce_confidence"
        elif euphoria_score >= 0.72:
            behavior_state = "euphoric_spike"
            recommended_response = "wait_for_confirmation"
        elif exhaustion_score >= 0.68:
            behavior_state = "exhausted_momentum"
            recommended_response = "caution"
        elif fake_urgency_score >= 0.70:
            behavior_state = "fake_urgency"
            recommended_response = "avoid"
        elif quote_reliability < 0.45:
            behavior_state = "quote_instability"
            recommended_response = "reduce_confidence"
        elif spread_shock >= 0.65:
            behavior_state = "spread_shock"
            recommended_response = "caution"
        elif volatility >= 0.65:
            behavior_state = "volatility_burst"
            recommended_response = "caution"
        else:
            behavior_state = "normal"
            recommended_response = "normal"
        return {
            "behavior_state": behavior_state,
            "panic_score": self._safe_round(panic_score, 4, 0.0),
            "euphoria_score": self._safe_round(euphoria_score, 4, 0.0),
            "exhaustion_score": self._safe_round(exhaustion_score, 4, 0.0),
            "fake_urgency_score": self._safe_round(fake_urgency_score, 4, 0.0),
            "dead_liquidity_risk": self._safe_round(dead_liquidity_risk, 4, 0.0),
            "recommended_response": recommended_response,
        }

    def _classify_market_regime(self, context, summary=None):
        summary = summary or {}
        profile = context.get("profile") or {}
        market_category = context.get("category") or "unknown"
        volatility = self._clamp((context.get("volatility") or 0.0) / 0.10)
        liquidity = self._clamp(context.get("liquidity_reliability", 0.0))
        momentum = self._clamp(abs(context.get("momentum_score") or 0.0))
        edge_density = self._clamp(context.get("edge_density", 0.0))
        no_candidate_streak = int(summary.get("no_candidate_cycle_streak", self.no_candidate_cycle_streak) or 0)
        current_hour = int(time.gmtime().tm_hour)
        weekend = time.gmtime().tm_wday >= 5
        if liquidity < 0.25 and edge_density < 0.25:
            regime = "dead_liquidity"
            strategy_bias = "defensive"
        elif volatility >= 0.72 and momentum >= 0.40:
            regime = "news_like_volatility"
            strategy_bias = "wait"
        elif volatility >= 0.60:
            regime = "high_volatility"
            strategy_bias = "defensive"
        elif volatility <= 0.22 and liquidity >= 0.55:
            regime = "low_volatility"
            strategy_bias = "momentum" if momentum >= 0.30 else "normal"
        elif momentum >= 0.35 and summary.get("candidate_count", 0) > 0:
            regime = "trending"
            strategy_bias = "momentum"
        else:
            regime = "choppy" if edge_density < 0.5 else "normal"
            strategy_bias = "reversion" if regime == "choppy" else "normal"
        if market_category == "crypto" and weekend:
            regime = "weekend_crypto_behavior"
            strategy_bias = "defensive" if liquidity < 0.5 else strategy_bias
        elif market_category == "sports" and context.get("time_to_event_bucket") in {"immediate", "near_term"}:
            regime = "sports_event_urgency"
            strategy_bias = "momentum"
        elif current_hour >= 0 and current_hour <= 12 and liquidity < 0.45:
            regime = "overnight_slowdown"
            strategy_bias = "wait"
        if no_candidate_streak >= 3 and regime not in {"dead_liquidity", "news_like_volatility"}:
            regime = "dead_liquidity"
            strategy_bias = "observe"
        regime_confidence = self._clamp((abs(momentum - 0.25) + liquidity + edge_density) / 3.0)
        return {
            "regime": regime,
            "regime_confidence": self._safe_round(regime_confidence, 4, 0.0),
            "volatility_state": context.get("volatility_bucket") or "unknown",
            "liquidity_state": context.get("liquidity_bucket") or "unknown",
            "momentum_state": context.get("momentum_bucket") or "unknown",
            "recommended_strategy_bias": strategy_bias,
        }

    def _evaluate_entry_quality_replay(self, current_context):
        rows = self._load_trade_history_rows(limit=400)
        if not rows:
            return {
                "entry_quality_score": None,
                "best_entry_traits": "insufficient_history",
                "weak_entry_traits": "insufficient_history",
                "replay_sample_size": 0,
                "entry_quality_recommendation": "wait_for_better_entry",
            }
        family = current_context.get("family")
        category = current_context.get("category")
        current_spread = current_context.get("spread")
        current_liquidity = current_context.get("liquidity")
        current_volatility = current_context.get("volatility")
        current_momentum = current_context.get("momentum_score")
        current_probability = current_context.get("probabilistic_score")
        current_time_bucket = current_context.get("time_to_event_bucket")
        current_timing = current_context.get("entry_timing_state")
        scored_rows = []
        for row in rows:
            row_family = self.get_market_family({"ticker": row.get("ticker", "")})
            row_category = row.get("category") or self.get_market_discovery_category({"ticker": row.get("ticker", "")})
            row_spread = self.to_float(row.get("spread"), None)
            if row_spread is None and row.get("yes_bid") and row.get("yes_ask"):
                row_spread = self.to_float(row.get("yes_ask"), 0.0) - self.to_float(row.get("yes_bid"), 0.0)
            row_liquidity = self.to_float(row.get("liquidity"), None)
            row_volatility = self.to_float(row.get("volatility"), None)
            row_momentum = self.to_float(row.get("momentum_score"), None)
            row_probability = self.to_float(row.get("probabilistic_score"), None)
            row_time_bucket = row.get("time_to_event_bucket") or "unknown"
            row_timing = row.get("entry_timing_state") or "unknown"
            score = 0.0
            if family and row_family == family:
                score += 1.8
            if category and row_category == category:
                score += 1.0
            if current_spread is not None and row_spread is not None:
                score += max(0.0, 1.0 - abs(float(current_spread) - float(row_spread)) / max(MAX_ENTRY_SPREAD, 0.01))
            if current_liquidity is not None and row_liquidity is not None:
                score += max(0.0, 1.0 - abs(float(current_liquidity) - float(row_liquidity)) / max(MIN_ENTRY_LIQUIDITY * 3.0, 1.0))
            if current_volatility is not None and row_volatility is not None:
                score += max(0.0, 1.0 - abs(float(current_volatility) - float(row_volatility)) / 0.12)
            if current_momentum is not None and row_momentum is not None:
                score += max(0.0, 1.0 - abs(float(current_momentum) - float(row_momentum)) / 0.50)
            if current_probability is not None and row_probability is not None:
                score += max(0.0, 1.0 - abs(float(current_probability) - float(row_probability)) / 0.35)
            if current_time_bucket and row_time_bucket == current_time_bucket:
                score += 0.45
            if current_timing and row_timing == current_timing:
                score += 0.35
            if score <= 0:
                continue
            scored_rows.append((score, row))
        if not scored_rows:
            return {
                "entry_quality_score": None,
                "best_entry_traits": "no_matching_history",
                "weak_entry_traits": "no_matching_history",
                "replay_sample_size": 0,
                "entry_quality_recommendation": "wait_for_better_entry",
            }
        scored_rows.sort(key=lambda item: item[0], reverse=True)
        top_rows = scored_rows[:20]
        entry_quality_score = self._clamp(sum(score for score, _row in top_rows) / (len(top_rows) * 6.0))
        best_entry_traits = top_rows[0][1]
        weak_entry_traits = min(top_rows, key=lambda item: self.to_float(item[1].get("realized_pnl"), 0.0))[1]
        positive_rows = [row for score, row in top_rows if self.to_float(row.get("realized_pnl"), 0.0) > 0]
        if entry_quality_score >= 0.65 and len(positive_rows) >= max(3, len(top_rows) // 2):
            recommendation = "entry_quality_strong"
        elif entry_quality_score >= 0.40:
            recommendation = "entry_quality_neutral"
        else:
            recommendation = "entry_quality_weak"
        if entry_quality_score < 0.35:
            recommendation = "wait_for_better_entry"
        return {
            "entry_quality_score": self._safe_round(entry_quality_score, 4, None),
            "best_entry_traits": {
                "family": self.get_market_family({"ticker": best_entry_traits.get("ticker", "")}),
                "spread_bucket": best_entry_traits.get("spread_bucket") or self._spread_bucket(self.to_float(best_entry_traits.get("spread"), None)),
                "liquidity_bucket": best_entry_traits.get("liquidity_bucket") or self._liquidity_bucket(self.to_float(best_entry_traits.get("liquidity"), None)),
                "time_to_event_bucket": best_entry_traits.get("time_to_event_bucket") or "unknown",
            },
            "weak_entry_traits": {
                "family": self.get_market_family({"ticker": weak_entry_traits.get("ticker", "")}),
                "spread_bucket": weak_entry_traits.get("spread_bucket") or self._spread_bucket(self.to_float(weak_entry_traits.get("spread"), None)),
                "liquidity_bucket": weak_entry_traits.get("liquidity_bucket") or self._liquidity_bucket(self.to_float(weak_entry_traits.get("liquidity"), None)),
                "time_to_event_bucket": weak_entry_traits.get("time_to_event_bucket") or "unknown",
            },
            "replay_sample_size": len(top_rows),
            "entry_quality_recommendation": recommendation,
        }

    def _detect_opportunity_scarcity(self, summary=None, candidates=None):
        summary = summary or {}
        candidates = candidates or []
        candidate_count = int(summary.get("candidates_found", len(candidates)) or len(candidates) or 0)
        valid_candidate_count = len([item for item in candidates if isinstance(item, tuple) and item and self.to_float(item[0], 0.0) > 0]) if candidates else candidate_count
        edge_density = self._clamp(valid_candidate_count / max(candidate_count, 1))
        liquidity_availability = self._clamp((summary.get("within_window", 0) or candidate_count) / max(summary.get("original_market_count", candidate_count) or 1, 1))
        market_quality = self._clamp((edge_density + liquidity_availability) / 2.0)
        weak_confidence_distribution = self._clamp(1.0 - market_quality)
        repeated_no_valid = int(getattr(self, "no_candidate_cycle_streak", 0) or 0)
        high_rejection_concentration = self._clamp((summary.get("spread_skip_count", 0) or 0) / max(candidate_count or 1, 1))
        low_liquidity_period = bool(summary.get("low_liquidity_reject_count", 0) or 0)
        high_spread_period = bool(summary.get("spread_skip_count", 0) or 0)
        if repeated_no_valid >= 3 or market_quality < 0.18:
            scarcity_state = "observe_only"
            recommended_mode = "observe_only"
        elif low_liquidity_period or high_spread_period or weak_confidence_distribution > 0.55:
            scarcity_state = "defensive"
            recommended_mode = "defensive"
        elif market_quality < 0.45 or high_rejection_concentration > 0.45:
            scarcity_state = "selective"
            recommended_mode = "selective"
        else:
            scarcity_state = "normal"
            recommended_mode = "normal"
        return {
            "scarcity_state": scarcity_state,
            "candidate_count": candidate_count,
            "valid_candidate_count": valid_candidate_count,
            "edge_density": self._safe_round(edge_density, 4, 0.0),
            "liquidity_availability": self._safe_round(liquidity_availability, 4, 0.0),
            "market_quality": self._safe_round(market_quality, 4, 0.0),
            "recommended_mode": recommended_mode,
            "weak_confidence_distribution": self._safe_round(weak_confidence_distribution, 4, 0.0),
        }

    def _compute_adaptive_aggression(self, summary=None, regime=None, scarcity=None, execution_quality=None):
        summary = summary or {}
        scarcity = scarcity or {}
        regime = regime or {}
        execution_quality = execution_quality or {}
        recent_win_rate = self._safe_round((self.live_perf_wins_today / self.live_perf_trades_today) if self.live_perf_trades_today else 0.0, 4, 0.0)
        recent_pnl = self._safe_round(self.live_realized_pnl_today, 4, 0.0)
        confidence_quality = self._clamp(execution_quality.get("historical_confidence", 0.0))
        regime_name = regime.get("regime", "unknown")
        scarcity_state = scarcity.get("scarcity_state", "normal")
        recovery_watchdog = "healthy"
        if self.last_error_message:
            recovery_watchdog = "watch"
        if int(self.consecutive_losses or 0) >= 3 or recent_pnl <= -0.10:
            posture = "defensive"
            reason = "drawdown_or_loss_streak"
        elif scarcity_state in {"observe_only", "defensive"}:
            posture = "defensive"
            reason = "opportunity_scarcity"
        elif regime_name in {"dead_liquidity", "news_like_volatility"}:
            posture = "defensive"
            reason = "regime_risk"
        elif recent_win_rate < 0.45 or recent_pnl < 0:
            posture = "cautious"
            reason = "recent_underperformance"
        elif recent_win_rate > 0.60 and recent_pnl > 0 and confidence_quality >= 0.55 and scarcity_state == "normal":
            posture = "opportunistic"
            reason = "positive_recent_momentum"
        else:
            posture = "normal"
            reason = "steady_state"
        return {
            "aggression_posture": posture,
            "reason": reason,
            "recent_win_rate": recent_win_rate,
            "recent_pnl": recent_pnl,
            "execution_quality": self._safe_round(confidence_quality, 4, 0.0),
            "risk_adjustment_recommendation": "reduce_confidence" if posture in {"defensive", "cautious"} else "normal",
            "recovery_watchdog_state": recovery_watchdog,
            "confidence_quality": self._safe_round(confidence_quality, 4, 0.0),
        }

    def emit_ascension_v2_telemetry(self, markets=None, quotes=None, candidates=None, selected_quote=None, live_select_summary=None, auto_live_ticker=None, auto_live_reason=None):
        markets = markets or []
        quotes = quotes or []
        candidates = candidates or []
        live_select_summary = live_select_summary or self.last_live_select_summary or {}
        if not quotes and selected_quote is not None:
            quotes = [selected_quote]
        active_context = None
        if selected_quote is None and candidates:
            first_candidate = candidates[0]
            if isinstance(first_candidate, tuple) and len(first_candidate) >= 2:
                selected_quote = first_candidate[1]
        if selected_quote is not None:
            selected_ticker = getattr(selected_quote, "ticker", "") or ""
            selected_market = next((market for market in markets if str(market.get("ticker", "") or "").strip() == selected_ticker), None)
            timing_state = {}
            if selected_ticker:
                timing_state = self._get_phase55_live_execution_gate_record(selected_ticker, stage="ascension_v2")
            active_context = self._build_entry_context(
                q=selected_quote,
                market=selected_market or {"ticker": selected_ticker},
                strategy_label="live_candidate" if auto_live_ticker else "scan_candidate",
                timing_state=timing_state,
                source="ascension_v2",
            )
        elif markets:
            fallback_market = markets[0]
            fallback_quote = quotes[0] if quotes else None
            if fallback_quote is not None:
                active_context = self._build_entry_context(
                    q=fallback_quote,
                    market=fallback_market,
                    strategy_label="scan_candidate",
                    timing_state=self._get_phase55_live_execution_gate_record(fallback_market.get("ticker", ""), stage="ascension_v2_fallback"),
                    source="ascension_v2_fallback",
                )
        if active_context is None:
            print("[LIVE-ASCENSIONV2-SUMMARY] status=waiting_for_more_data reason=insufficient_behavioral_history")
            return {
                "status": "waiting_for_more_data",
                "reason": "insufficient_behavioral_history",
            }
        market_personality = self._update_market_personality_profiles(markets=locals().get("markets", []), quotes=locals().get("quotes", []))
        personality_summary = self.last_realm_xxi_summary or {}
        if not personality_summary or personality_summary.get("source") not in {"live_cycle", "ascension_v2"}:
            personality_summary = self._refresh_personality_intelligence(
                source="ascension_v2",
                markets=locals().get("markets", []),
                quotes=locals().get("quotes", []),
                live_select_summary=live_select_summary,
                force=False,
            ) or self.last_realm_xxi_summary or {}
        probability_summary = self.last_realm_xxiii_summary or {}
        if not probability_summary or probability_summary.get("source") not in {"live_cycle", "ascension_v2"}:
            probability_summary = self._refresh_probability_intelligence(
                source="ascension_v2",
                markets=locals().get("markets", []),
                quotes=locals().get("quotes", []),
                selected_quote=selected_quote,
                live_select_summary=live_select_summary,
                force=False,
            ) or self.last_realm_xxiii_summary or {}
        family = active_context.get("family", "UNKNOWN")
        profile = dict((self.market_personality_profiles or {}).get("families", {}).get(family, {}) or {})
        behavior_state = self._classify_market_behavior_state(active_context, profile=profile)
        regime = self._classify_market_regime(
            {**active_context, "profile": profile, "edge_density": live_select_summary.get("candidates_found", 0) / max(live_select_summary.get("original_market_count", 1) or 1, 1)},
            summary=live_select_summary,
        )
        memory = self._score_trade_memory_similarity(active_context)
        decay = self._calculate_confidence_decay(
            profile.get("historical_confidence", 0.0),
            sample_age_seconds=max(0.0, time.time() - float(profile.get("last_seen_at") or time.time())),
            regime_staleness=0.0 if regime.get("regime") in {"trending", "normal", "low_volatility"} else 0.20,
            sample_size=int(profile.get("sample_count", 0) or 0) + int(profile.get("outcome_samples", 0) or 0),
            contradictory_score=max(0.0, self.to_float(memory.get("similar_win_rate"), 0.0) - self.to_float(profile.get("win_rate"), 0.0)),
        )
        entry_replay = self._evaluate_entry_quality_replay(active_context)
        scarcity = self._detect_opportunity_scarcity(summary=live_select_summary, candidates=locals().get("candidates", []))
        aggression = self._compute_adaptive_aggression(summary=live_select_summary, regime=regime, scarcity=scarcity, execution_quality=profile)
        insufficient_data = any(
            (
                int(profile.get("sample_count", 0) or 0) + int(profile.get("outcome_samples", 0) or 0) < 5,
                memory.get("sample_size", 0) < 3,
                entry_replay.get("replay_sample_size", 0) < 3,
            )
        )
        summary_status = "waiting_for_more_data" if insufficient_data else "operational"
        final_behavioral_recommendation = aggression.get("risk_adjustment_recommendation", "normal")
        if regime.get("recommended_strategy_bias") in {"wait", "defensive"} and final_behavioral_recommendation == "normal":
            final_behavioral_recommendation = regime.get("recommended_strategy_bias")
        elif behavior_state.get("recommended_response") in {"avoid", "reduce_confidence", "wait_for_confirmation"}:
            final_behavioral_recommendation = behavior_state.get("recommended_response")
        print(
            f"[LIVE-MARKET-BEHAVIOR-STATE] behavior_state={behavior_state.get('behavior_state')} "
            f"panic_score={behavior_state.get('panic_score')} euphoria_score={behavior_state.get('euphoria_score')} "
            f"exhaustion_score={behavior_state.get('exhaustion_score')} fake_urgency_score={behavior_state.get('fake_urgency_score')} "
            f"dead_liquidity_risk={behavior_state.get('dead_liquidity_risk')} recommended_response={behavior_state.get('recommended_response')}"
        )
        print(
            f"[LIVE-TRADE-MEMORY-SIMILARITY] similar_setups_found={memory.get('similar_setups_found')} "
            f"similar_win_rate={memory.get('similar_win_rate')} similar_average_pnl={memory.get('similar_average_pnl')} "
            f"similar_failure_pattern={memory.get('similar_failure_pattern')} similarity_confidence={memory.get('similarity_confidence')} "
            f"memory_recommendation={memory.get('memory_recommendation')}"
        )
        print(
            f"[LIVE-CONFIDENCE-DECAY] raw_confidence={decay.get('raw_confidence')} decay_factor={decay.get('decay_factor')} "
            f"decayed_confidence={decay.get('decayed_confidence')} decay_reason={decay.get('decay_reason')} "
            f"sample_age={self._safe_round(time.time() - float(profile.get('last_seen_at') or time.time()), 2, 0.0)} "
            f"regime_staleness={'yes' if regime.get('regime') in {'dead_liquidity', 'news_like_volatility', 'high_volatility'} else 'no'}"
        )
        print(
            f"[LIVE-REGIME-AWARENESS] regime={regime.get('regime')} regime_confidence={regime.get('regime_confidence')} "
            f"volatility_state={regime.get('volatility_state')} liquidity_state={regime.get('liquidity_state')} "
            f"momentum_state={regime.get('momentum_state')} recommended_strategy_bias={regime.get('recommended_strategy_bias')}"
        )
        print(
            f"[LIVE-ENTRY-QUALITY-REPLAY] entry_quality_score={entry_replay.get('entry_quality_score')} "
            f"best_entry_traits={entry_replay.get('best_entry_traits')} weak_entry_traits={entry_replay.get('weak_entry_traits')} "
            f"replay_sample_size={entry_replay.get('replay_sample_size')} entry_quality_recommendation={entry_replay.get('entry_quality_recommendation')}"
        )
        print(
            f"[LIVE-OPPORTUNITY-SCARCITY] scarcity_state={scarcity.get('scarcity_state')} candidate_count={scarcity.get('candidate_count')} "
            f"valid_candidate_count={scarcity.get('valid_candidate_count')} edge_density={scarcity.get('edge_density')} "
            f"liquidity_availability={scarcity.get('liquidity_availability')} market_quality={scarcity.get('market_quality')} "
            f"recommended_mode={scarcity.get('recommended_mode')}"
        )
        print(
            f"[LIVE-ADAPTIVE-AGGRESSION] aggression_posture={aggression.get('aggression_posture')} reason={aggression.get('reason')} "
            f"recent_win_rate={aggression.get('recent_win_rate')} recent_pnl={aggression.get('recent_pnl')} "
            f"execution_quality={aggression.get('execution_quality')} risk_adjustment_recommendation={aggression.get('risk_adjustment_recommendation')}"
        )
        print(
            f"[LIVE-ASCENSIONV2-SUMMARY] market_personality_profiles={len((self.market_personality_profiles or {}).get('families', {}) if isinstance(self.market_personality_profiles, dict) else {})} "
            f"behavior_state={behavior_state.get('behavior_state')} similarity_confidence={memory.get('similarity_confidence')} "
            f"confidence_decay_applied={decay.get('decay_factor')} current_regime={regime.get('regime')} "
            f"entry_quality_score={entry_replay.get('entry_quality_score')} scarcity_state={scarcity.get('scarcity_state')} "
            f"aggression_posture={aggression.get('aggression_posture')} final_behavioral_recommendation={final_behavioral_recommendation} "
            f"personality_top_families={','.join(item.get('family') for item in (personality_summary.get('top_families') or [])[:3] if item.get('family')) or 'none'} "
            f"probability_top_families={','.join(item.get('family') for item in (probability_summary.get('top_families') or [])[:3] if item.get('family')) or 'none'} "
            f"status={summary_status}"
        )
        if summary_status != "operational":
            print("[LIVE-ASCENSIONV2-SUMMARY] status=waiting_for_more_data reason=insufficient_behavioral_history")
        realm_xvii_engine = getattr(self, "realm_xvii_engine", None)
        if realm_xvii_engine is not None and getattr(realm_xvii_engine, "enabled", False):
            try:
                realm_xvii_engine.observe_shadow_cycle(
                    markets=locals().get("markets", []),
                    quotes=locals().get("quotes", []),
                    candidates=locals().get("candidates", []),
                    selected_quote=selected_quote,
                    live_select_summary=live_select_summary,
                    realm_xvi_summary=getattr(self, "last_realm_xvi_summary", {}) or {},
                    portfolio_state=getattr(self, "last_realm_xviii_summary", {}) or {},
                    source="live",
                )
                self.last_realm_xvii_summary = realm_xvii_engine.last_report or self.last_realm_xvii_summary
            except Exception as exc:
                print(f"[REALM-XVII-ERROR] reason={exc.__class__.__name__}")
        return {
            "status": summary_status,
            "market_personality_profiles": market_personality,
            "behavior_state": behavior_state,
            "memory": memory,
            "confidence_decay": decay,
            "regime": regime,
            "entry_quality": entry_replay,
            "scarcity": scarcity,
            "aggression": aggression,
            "final_behavioral_recommendation": final_behavioral_recommendation,
        }

    def is_debug_live_enabled(self):
        return DEBUG_LIVE

    def get_live_execution_flags(self):
        live_mode = bool(globals().get("LIVE_MODE", False))
        live_armed = bool(globals().get("LIVE_ARMED", False))
        live_env_confirmed = bool(globals().get("LIVE_ENV_CONFIRMED", False))
        effective_live_dry_run = compute_effective_live_dry_run(
            live_mode=live_mode,
            live_armed=live_armed,
            live_env_confirmed=live_env_confirmed,
            configured_dry_run=DRY_RUN_LIVE_ORDERS,
        )
        return {
            "live_mode": live_mode,
            "live_armed": live_armed,
            "live_env_confirmed": live_env_confirmed,
            "all_live_switches_on": bool(live_mode and live_armed and live_env_confirmed),
            "effective_live_dry_run": effective_live_dry_run,
            "real_submit_enabled": bool(live_mode and live_armed and live_env_confirmed and not effective_live_dry_run),
        }

    def get_live_submit_authorization(self, payload=None):
        payload = payload if isinstance(payload, dict) else {}
        ticker = str(payload.get("ticker") or "").strip()
        flags = self.get_live_execution_flags()
        supplied_ticker = str(globals().get("LIVE_TEST_TICKER") or "").strip() or None
        authorized_canary_ticker = str(getattr(self, "live_canary_authorized_ticker", None) or "").strip() or None
        allowed_ticker = authorized_canary_ticker or supplied_ticker
        normal_live_service_mode = bool(flags["all_live_switches_on"] and not supplied_ticker)
        if not flags["live_mode"]:
            reason = "live_mode_disabled"
        elif not flags["live_armed"]:
            reason = "live_not_armed"
        elif not flags["live_env_confirmed"]:
            reason = "live_env_not_confirmed"
        elif flags["effective_live_dry_run"]:
            reason = "effective_dry_run"
        elif not normal_live_service_mode:
            if not allowed_ticker:
                reason = "no_live_test_ticker"
            elif ticker and ticker != allowed_ticker:
                reason = "ticker_not_allowed"
            elif self.live_canary_submitted and not authorized_canary_ticker:
                reason = "canary_already_used"
            else:
                reason = "authorized_canary_ticker"
        else:
            reason = "authorized_live_service"
        return {
            "ok": reason in {"authorized_live_service", "authorized_canary_ticker"},
            "reason": reason,
            "flags": flags,
            "supplied_ticker": supplied_ticker,
            "authorized_canary_ticker": authorized_canary_ticker,
            "allowed_ticker": allowed_ticker,
            "normal_live_service_mode": normal_live_service_mode,
        }

    def prune_live_position_state(self, active_tickers=None):
        active_tickers = {
            str(ticker or "").strip()
            for ticker in (active_tickers or [])
            if str(ticker or "").strip()
        }
        tracked_open_tickers = {
            str(position.get("ticker") or "").strip()
            for position in self.live_positions
            if isinstance(position, dict)
            and str(position.get("ticker") or "").strip()
            and str(position.get("status", "open") or "open").strip().lower() == "open"
        }
        keep_tickers = active_tickers | tracked_open_tickers
        state = self.load_live_position_state()
        removed = []
        for ticker in list(state.keys()):
            if ticker not in keep_tickers:
                removed.append(ticker)
                state.pop(ticker, None)
        if removed:
            print(f"[LIVE-STATE-PRUNE] removed={removed} keep_count={len(keep_tickers)}")
            self.save_live_position_state(state)
        return removed

    def normalize_contract_price(self, price, ticker=None, source="unknown"):
        if price is None:
            print(
                f"[LIVE-PRICE-NORMALIZE] ticker={ticker or 'UNKNOWN'} source={source} "
                f"raw_pre=None normalized_price=None action=rejected"
            )
            return None
        try:
            numeric_price = float(price)
        except (TypeError, ValueError):
            print(
                f"[LIVE-PRICE-NORMALIZE] ticker={ticker or 'UNKNOWN'} source={source} "
                f"raw_pre={price} normalized_price=None action=rejected"
            )
            return None
        if 0 < numeric_price <= 1:
            normalized_price = round(numeric_price, 4)
            action = "kept"
        elif 1 < numeric_price <= 100:
            normalized_price = round(numeric_price / 100.0, 4)
            action = "divided_by_100"
        else:
            normalized_price = None
            action = "rejected"
        print(
            f"[LIVE-PRICE-NORMALIZE] ticker={ticker or 'UNKNOWN'} source={source} "
            f"raw_pre={numeric_price} normalized_price={normalized_price} action={action}"
        )
        return normalized_price

    def _resolve_aion_canonical_binary_prices(self, source=None, *, ticker=None, source_label="unknown"):
        source_dict = self._coerce_aion_orderbook_source(source)
        ticker_text = str(ticker or source_dict.get("ticker") or "").strip()

        def _normalized_price(raw_value, key_label):
            normalized = self.normalize_contract_price(
                raw_value,
                ticker=ticker_text or None,
                source=f"{source_label}.{key_label}",
            )
            return self.to_float(normalized, None)

        raw_yes_bid = source_dict.get("yes_bid_dollars", source_dict.get("yes_bid"))
        raw_yes_ask = source_dict.get("yes_ask_dollars", source_dict.get("yes_ask"))
        raw_no_bid = source_dict.get("no_bid_dollars", source_dict.get("no_bid"))
        raw_no_ask = source_dict.get("no_ask_dollars", source_dict.get("no_ask"))

        yes_bid = _normalized_price(raw_yes_bid, "yes_bid")
        yes_ask = _normalized_price(raw_yes_ask, "yes_ask")
        no_bid = _normalized_price(raw_no_bid, "no_bid")
        no_ask = _normalized_price(raw_no_ask, "no_ask")

        derived_yes_bid = False
        derived_yes_ask = False
        derived_no_bid = False
        derived_no_ask = False

        if yes_ask is None and no_bid is not None:
            yes_ask = self._clamp(1.0 - no_bid, 0.0, 1.0)
            derived_yes_ask = True
        if no_ask is None and yes_bid is not None:
            no_ask = self._clamp(1.0 - yes_bid, 0.0, 1.0)
            derived_no_ask = True
        if yes_bid is None and no_ask is not None:
            yes_bid = self._clamp(1.0 - no_ask, 0.0, 1.0)
            derived_yes_bid = True
        if no_bid is None and yes_ask is not None:
            no_bid = self._clamp(1.0 - yes_ask, 0.0, 1.0)
            derived_no_bid = True

        yes_bid_cents = int(round(yes_bid * 100.0)) if yes_bid is not None else None
        yes_ask_cents = int(round(yes_ask * 100.0)) if yes_ask is not None else None
        no_bid_cents = int(round(no_bid * 100.0)) if no_bid is not None else None
        no_ask_cents = int(round(no_ask * 100.0)) if no_ask is not None else None

        yes_spread = round(max(0.0, yes_ask - yes_bid), 4) if yes_bid is not None and yes_ask is not None else None
        no_spread = round(max(0.0, no_ask - no_bid), 4) if no_bid is not None and no_ask is not None else None
        spread = yes_spread if yes_spread is not None else no_spread
        book_valid = bool(
            yes_bid is not None and yes_ask is not None and no_bid is not None and no_ask is not None
            and 0.0 <= yes_bid <= 1.0 and 0.0 <= yes_ask <= 1.0 and 0.0 <= no_bid <= 1.0 and 0.0 <= no_ask <= 1.0
        )
        normalized_consistent = bool(
            yes_bid is not None and yes_ask is not None and no_bid is not None and no_ask is not None
            and abs((yes_bid + no_ask) - 1.0) <= 0.02 and abs((no_bid + yes_ask) - 1.0) <= 0.02
        )
        return {
            "ticker": ticker_text or None,
            "raw_yes_bid": self.to_float(raw_yes_bid, None),
            "raw_yes_ask": self.to_float(raw_yes_ask, None),
            "raw_no_bid": self.to_float(raw_no_bid, None),
            "raw_no_ask": self.to_float(raw_no_ask, None),
            "yes_bid": yes_bid,
            "yes_ask": yes_ask,
            "no_bid": no_bid,
            "no_ask": no_ask,
            "yes_bid_cents": yes_bid_cents,
            "yes_ask_cents": yes_ask_cents,
            "no_bid_cents": no_bid_cents,
            "no_ask_cents": no_ask_cents,
            "derived_yes_bid": derived_yes_bid,
            "derived_yes_ask": derived_yes_ask,
            "derived_no_bid": derived_no_bid,
            "derived_no_ask": derived_no_ask,
            "yes_spread": yes_spread,
            "no_spread": no_spread,
            "spread": spread,
            "book_valid": book_valid,
            "normalized_consistent": normalized_consistent,
            "source_label": source_label,
        }

    def _resolve_aion_canonical_spread_context(self, *, market=None, q=None, payload=None, quote_diag=None, selected_side=None, source_label="unknown"):
        market = market if isinstance(market, dict) else {}
        payload = payload if isinstance(payload, dict) else {}
        quote_diag = quote_diag if isinstance(quote_diag, dict) else {}
        q = q if q is not None else None
        def _q_get(obj, *names, default=None):
            if obj is None:
                return default
            for name in names:
                if isinstance(obj, dict):
                    value = obj.get(name)
                else:
                    value = getattr(obj, name, None)
                if value is not None:
                    return value
            return default
        ticker = str(
            _q_get(q, "ticker", default="")
            or payload.get("ticker", "")
            or market.get("ticker", "")
            or quote_diag.get("ticker", "")
            or ""
        ).strip() or None
        family = str(
            quote_diag.get("family")
            or market.get("family")
            or (self.get_market_family(market) if market else None)
            or getattr(q, "family", "")
            or "UNKNOWN"
        ).strip().upper() or "UNKNOWN"

        def _pick(*values):
            for value in values:
                if value is None:
                    continue
                if isinstance(value, str) and not value.strip():
                    continue
                return value
            return None

        def _as_bool(value, default=None):
            if value is None:
                return default
            if isinstance(value, bool):
                return value
            if isinstance(value, (int, float)):
                return bool(value)
            if isinstance(value, str):
                normalized = value.strip().lower()
                if normalized in {"true", "1", "yes", "y", "on"}:
                    return True
                if normalized in {"false", "0", "no", "n", "off", "none", "null", ""}:
                    return False
            return bool(value)

        def _normalize_price(raw_value, field_label):
            normalized = self.normalize_contract_price(
                raw_value,
                ticker=ticker or None,
                source=f"{source_label}.{field_label}",
            )
            price = self.to_float(normalized, None)
            return price if price is not None and price > 0.0 else None

        selected_side_value = str(
            selected_side
            or _q_get(q, "selected_side")
            or _q_get(q, "side")
            or payload.get("selected_side")
            or quote_diag.get("selected_side")
            or ""
        ).strip().lower() or None
        raw_selected_price = _pick(
            _q_get(q, "selected_price"),
            _q_get(q, "selected_price_dollars"),
            payload.get("selected_price"),
            payload.get("selected_price_dollars"),
            quote_diag.get("selected_price"),
            quote_diag.get("selected_price_dollars"),
        )
        selected_price = _normalize_price(raw_selected_price, "selected_price")
        selected_price_cents = _pick(
            payload.get("selected_price_cents"),
            _q_get(q, "selected_price_cents"),
            quote_diag.get("selected_price_cents"),
        )
        try:
            if selected_price_cents not in (None, ""):
                selected_price_cents = int(round(float(selected_price_cents)))
        except (TypeError, ValueError):
            selected_price_cents = None

        yes_bid = _normalize_price(
            _pick(
                _q_get(q, "yes_bid"),
                _q_get(q, "yes_bid_dollars"),
                payload.get("yes_bid"),
                payload.get("yes_bid_dollars"),
                market.get("yes_bid_dollars"),
                market.get("yes_bid"),
                quote_diag.get("yes_bid"),
                quote_diag.get("yes_bid_dollars"),
            ),
            "yes_bid",
        )
        yes_ask = _normalize_price(
            _pick(
                _q_get(q, "yes_ask"),
                _q_get(q, "yes_ask_dollars"),
                payload.get("yes_ask"),
                payload.get("yes_ask_dollars"),
                market.get("yes_ask_dollars"),
                market.get("yes_ask"),
                quote_diag.get("yes_ask"),
                quote_diag.get("yes_ask_dollars"),
            ),
            "yes_ask",
        )
        no_bid = _normalize_price(
            _pick(
                _q_get(q, "no_bid"),
                _q_get(q, "no_bid_dollars"),
                payload.get("no_bid"),
                payload.get("no_bid_dollars"),
                market.get("no_bid_dollars"),
                market.get("no_bid"),
                quote_diag.get("no_bid"),
                quote_diag.get("no_bid_dollars"),
            ),
            "no_bid",
        )
        no_ask = _normalize_price(
            _pick(
                _q_get(q, "no_ask"),
                _q_get(q, "no_ask_dollars"),
                payload.get("no_ask"),
                payload.get("no_ask_dollars"),
                market.get("no_ask_dollars"),
                market.get("no_ask"),
                quote_diag.get("no_ask"),
                quote_diag.get("no_ask_dollars"),
            ),
            "no_ask",
        )
        yes_top_price = _normalize_price(
            _pick(
                market.get("yes_top_price"),
                quote_diag.get("yes_top_price"),
                quote_diag.get("top_yes_price"),
                payload.get("yes_top_price"),
                _q_get(q, "yes_top_price"),
            ),
            "yes_top_price",
        )
        no_top_price = _normalize_price(
            _pick(
                market.get("no_top_price"),
                quote_diag.get("no_top_price"),
                quote_diag.get("top_no_price"),
                payload.get("no_top_price"),
                _q_get(q, "no_top_price"),
            ),
            "no_top_price",
        )
        yes_top_size = self.to_float(
            _pick(
                market.get("yes_top_size"),
                quote_diag.get("yes_top_size"),
                payload.get("yes_top_size"),
                _q_get(q, "yes_top_size"),
            ),
            None,
        )
        no_top_size = self.to_float(
            _pick(
                market.get("no_top_size"),
                quote_diag.get("no_top_size"),
                payload.get("no_top_size"),
                _q_get(q, "no_top_size"),
            ),
            None,
        )
        source_fields_checked = [
            "q.selected_price",
            "q.selected_price_dollars",
            "q.selected_price_cents",
            "q.selected_side",
            "q.side",
            "q.yes_bid",
            "q.yes_ask",
            "q.no_bid",
            "q.no_ask",
            "q.yes_top_price",
            "q.no_top_price",
            "q.yes_top_size",
            "q.no_top_size",
            "payload.selected_price",
            "payload.selected_price_dollars",
            "payload.selected_price_cents",
            "payload.selected_side",
            "payload.yes_bid",
            "payload.yes_ask",
            "payload.no_bid",
            "payload.no_ask",
            "payload.yes_top_price",
            "payload.no_top_price",
            "market.yes_bid_dollars",
            "market.yes_ask_dollars",
            "market.no_bid_dollars",
            "market.no_ask_dollars",
            "market.yes_top_price",
            "market.no_top_price",
            "market.yes_top_size",
            "market.no_top_size",
            "quote_diag.yes_bid",
            "quote_diag.yes_ask",
            "quote_diag.no_bid",
            "quote_diag.no_ask",
            "quote_diag.yes_top_price",
            "quote_diag.no_top_price",
            "quote_diag.yes_top_size",
            "quote_diag.no_top_size",
        ]
        spread = None
        spread_cents = None
        spread_source = None
        spread_reason = None
        computed_spread_attempted = False
        fallback_attempted = False
        spread_missing_fields = []
        spread_candidate_details = []

        def _pair_spread(pair_label, bid_value, ask_value):
            if orderbook_health_compute_pair_spread is not None:
                return orderbook_health_compute_pair_spread(pair_label, bid_value, ask_value)
            pair_missing_fields = []
            if bid_value is None:
                pair_missing_fields.append(f"{pair_label}_bid")
            if ask_value is None:
                pair_missing_fields.append(f"{pair_label}_ask")
            if pair_missing_fields:
                return None, pair_missing_fields, "missing_bid_ask"
            try:
                bid_float = float(bid_value)
                ask_float = float(ask_value)
            except (TypeError, ValueError):
                return None, [f"{pair_label}_bid", f"{pair_label}_ask"], "non_numeric_bid_ask"
            if bid_float <= 0.0 or ask_float <= 0.0:
                return None, [f"{pair_label}_bid", f"{pair_label}_ask"], "fake_book"
            if ask_float < bid_float:
                return None, [f"{pair_label}_bid", f"{pair_label}_ask"], "inverted_bid_ask"
            return round(max(0.0, ask_float - bid_float), 4), [], None

        def _topbook_spread(yes_top_price_value, no_top_price_value):
            if orderbook_health_compute_topbook_spread is not None:
                return orderbook_health_compute_topbook_spread(yes_top_price_value, no_top_price_value)
            if yes_top_price_value is None or no_top_price_value is None:
                missing = []
                if yes_top_price_value is None:
                    missing.append("yes_top_price")
                if no_top_price_value is None:
                    missing.append("no_top_price")
                return None, missing, "missing_topbook_pair"
            try:
                yes_top_float = float(yes_top_price_value)
                no_top_float = float(no_top_price_value)
            except (TypeError, ValueError):
                return None, ["yes_top_price", "no_top_price"], "non_numeric_topbook_pair"
            if yes_top_float <= 0.0 or no_top_float <= 0.0:
                return None, ["yes_top_price", "no_top_price"], "fake_topbook"
            raw_spread_value = yes_top_float + no_top_float - 1.0
            if raw_spread_value < 0.0:
                return None, ["yes_top_price", "no_top_price"], "inverted_topbook_pair"
            spread_value = round(raw_spread_value, 4)
            return spread_value, [], None

        selected_side_preference = selected_side_value if selected_side_value in {"yes", "no"} else None
        pair_order = []
        if selected_side_preference == "yes":
            pair_order = [("yes", yes_bid, yes_ask), ("no", no_bid, no_ask)]
        elif selected_side_preference == "no":
            pair_order = [("no", no_bid, no_ask), ("yes", yes_bid, yes_ask)]
        else:
            pair_order = [("yes", yes_bid, yes_ask), ("no", no_bid, no_ask)]

        for pair_label, bid_value, ask_value in pair_order:
            computed_spread_attempted = True
            pair_spread, pair_missing_fields, pair_reason = _pair_spread(pair_label, bid_value, ask_value)
            if pair_spread is not None:
                spread = pair_spread
                if pair_order and pair_label != pair_order[0][0]:
                    fallback_attempted = True
                if selected_side_preference is None:
                    spread_source = "yes_bid_yes_ask" if pair_label == "yes" else "no_bid_no_ask"
                elif pair_label == selected_side_preference:
                    spread_source = f"selected_side_{pair_label}"
                else:
                    spread_source = f"opposite_side_{pair_label}"
                spread_reason = pair_reason or "bid_ask_pair"
                break
            if pair_reason is not None:
                spread_candidate_details.append(
                    {
                        "pair": pair_label,
                        "reason": pair_reason,
                        "missing_fields": pair_missing_fields,
                    }
                )

        if spread is None:
            fallback_attempted = True
            topbook_spread, topbook_missing_fields, topbook_reason = _topbook_spread(yes_top_price, no_top_price)
            if topbook_spread is not None:
                spread = topbook_spread
                spread_source = "topbook_yes_no_prices"
                spread_reason = topbook_reason or "topbook_complement"
            elif topbook_reason is not None:
                spread_candidate_details.append(
                    {
                        "pair": "topbook",
                        "reason": topbook_reason,
                        "missing_fields": topbook_missing_fields,
                    }
                )

        if spread is not None:
            try:
                spread_cents = int(round(float(spread) * 100.0))
            except (TypeError, ValueError):
                spread_cents = None
            print(
                "[AION-SPREAD-COMPUTED] "
                + json.dumps(
                    {
                        "ticker": ticker,
                        "family": family,
                        "caller": source_label,
                        "selected_side": selected_side_value,
                        "selected_price": selected_price,
                        "selected_price_cents": selected_price_cents,
                        "yes_bid": yes_bid,
                        "yes_ask": yes_ask,
                        "no_bid": no_bid,
                        "no_ask": no_ask,
                        "yes_top_price": yes_top_price,
                        "no_top_price": no_top_price,
                        "spread": spread,
                        "spread_cents": spread_cents,
                        "source": spread_source,
                        "reason": spread_reason or "computed",
                    },
                    sort_keys=True,
                    default=str,
                )
            )
        else:
            if not spread_candidate_details:
                spread_candidate_details.append(
                    {
                        "pair": "selected_side",
                        "reason": "missing_bid_ask",
                        "missing_fields": ["yes_bid", "yes_ask", "no_bid", "no_ask", "yes_top_price", "no_top_price"],
                    }
                )
            spread_missing_fields = []
            for detail in spread_candidate_details:
                spread_missing_fields.extend(detail.get("missing_fields") or [])
            spread_missing_fields = list(dict.fromkeys(spread_missing_fields))
            spread_reason = spread_candidate_details[0].get("reason") if spread_candidate_details else "missing_bid_ask"
            exact_missing_field = spread_missing_fields[0] if spread_missing_fields else (spread_reason or "missing_spread")
            self._emit_aion_spread_missing_detail_trace(
                caller=source_label,
                return_path=f"{source_label}.missing_spread",
                ticker=ticker,
                family=family,
                selected_side=selected_side_value,
                selected_price=selected_price,
                yes_bid=yes_bid,
                yes_ask=yes_ask,
                no_bid=no_bid,
                no_ask=no_ask,
                spread_cents=spread_cents,
                exact_missing_field=exact_missing_field,
                computed_spread_attempted=computed_spread_attempted,
                fallback_attempted=fallback_attempted,
                spread_missing_fields=spread_missing_fields,
                source_fields_checked=source_fields_checked,
            )
        print(
            "[AION-SPREAD-FINAL] "
            + json.dumps(
                {
                    "ticker": ticker,
                    "family": family,
                    "caller": source_label,
                    "selected_side": selected_side_value,
                    "selected_price": selected_price,
                    "selected_price_cents": selected_price_cents,
                    "yes_bid": yes_bid,
                    "yes_ask": yes_ask,
                    "no_bid": no_bid,
                    "no_ask": no_ask,
                    "yes_top_price": yes_top_price,
                    "no_top_price": no_top_price,
                    "spread": spread,
                    "spread_cents": spread_cents,
                    "spread_source": spread_source,
                    "spread_present": bool(spread is not None),
                    "computed_spread_attempted": bool(computed_spread_attempted),
                    "fallback_attempted": bool(fallback_attempted),
                    "spread_missing_fields": spread_missing_fields,
                    "reason": spread_reason or ("computed" if spread is not None else "missing_spread"),
                },
                sort_keys=True,
                default=str,
            )
        )
        return {
            "ticker": ticker,
            "family": family,
            "selected_side": selected_side_value,
            "selected_price": selected_price,
            "selected_price_cents": selected_price_cents,
            "yes_bid": yes_bid,
            "yes_ask": yes_ask,
            "no_bid": no_bid,
            "no_ask": no_ask,
            "yes_top_price": yes_top_price,
            "no_top_price": no_top_price,
            "yes_top_size": yes_top_size,
            "no_top_size": no_top_size,
            "spread": spread,
            "spread_cents": spread_cents,
            "spread_source": spread_source,
            "spread_reason": spread_reason,
            "spread_ready": bool(spread is not None and spread >= 0.0),
            "spread_present": bool(spread is not None),
            "computed_spread_attempted": bool(computed_spread_attempted),
            "fallback_attempted": bool(fallback_attempted),
            "spread_missing_fields": spread_missing_fields,
            "source_fields_checked": source_fields_checked,
            "source_label": source_label,
        }

    def persist_live_entry_metadata(self, order=None, payload=None, order_id=None):
        summary = self.extract_order_execution_summary(order or {})
        ticker = (summary.get("ticker") or (payload or {}).get("ticker") or "").strip()
        side = summary.get("side") or (payload or {}).get("side")
        entry_price = summary.get("price")
        if entry_price is None and payload:
            entry_price = payload.get("yes_price")
            if entry_price is None:
                entry_price = payload.get("no_price")
        count = summary.get("filled_count")
        if count is None and payload:
            try:
                count = float(payload.get("count"))
            except (TypeError, ValueError):
                count = None
        if not ticker or not side or count in (None, 0):
            return
        entry_price = self.normalize_contract_price(entry_price, ticker=ticker, source="persist_live_entry_metadata")
        state = self.load_live_position_state()
        entry_context = (payload or {}).get("entry_context")
        state[ticker] = {
            "ticker": ticker,
            "side": side,
            "entry_price": entry_price,
            "count": count,
            "entry_ts": time.time(),
            "order_id": summary.get("order_id") or order_id,
            "entry_context": entry_context if isinstance(entry_context, dict) else None,
            "aion_relaxation_used": bool((payload or {}).get("aion_relaxation_used")),
            "aion_relaxation_reason": (payload or {}).get("aion_relaxation_reason"),
        }
        self.save_live_position_state(state)

    def remove_live_entry_metadata(self, ticker):
        ticker = (ticker or "").strip()
        if not ticker:
            return
        state = self.load_live_position_state()
        if ticker in state:
            state.pop(ticker, None)
            self.save_live_position_state(state)

    def get_live_entry_metadata(self, ticker):
        ticker = (ticker or "").strip()
        state = self.load_live_position_state()
        entry = state.get(ticker)
        print(
            f"[LIVE-STATE-LOOKUP] ticker={ticker} "
            f"found={'yes' if isinstance(entry, dict) else 'no'} keys={sorted(list(state.keys()))[:10]}"
        )
        return entry if isinstance(entry, dict) else None

    def upsert_live_entry_metadata_from_position(self, position_summary):
        ticker = (position_summary.get("ticker") or "").strip()
        count = position_summary.get("count")
        if not ticker or count is None or abs(count) == 0:
            return None
        state = self.load_live_position_state()
        existing = state.get(ticker) if isinstance(state.get(ticker), dict) else None
        updated_ts = position_summary.get("updated_ts")
        source = "last_updated_ts" if updated_ts is not None else "now"
        entry_ts = updated_ts if updated_ts is not None else time.time()
        if existing and existing.get("entry_ts") is not None:
            entry_ts = existing.get("entry_ts")
        elif not existing:
            print(f"[LIVE-STATE-BACKFILL] ticker={ticker} entry_ts={entry_ts} source={source}")
        normalized_avg_price = self.normalize_contract_price(
            position_summary.get("avg_price"),
            ticker=ticker,
            source="upsert_live_entry_metadata_from_position.avg_price",
        )
        selected_entry_price = normalized_avg_price
        if existing:
            existing_entry_price = self.normalize_contract_price(
                existing.get("entry_price"),
                ticker=ticker,
                source="upsert_live_entry_metadata_from_position.existing_entry_price",
            )
            if existing_entry_price is not None and 0 < existing_entry_price <= 1:
                selected_entry_price = existing_entry_price
        state[ticker] = {
            "ticker": ticker,
            "side": position_summary.get("side"),
            "entry_price": selected_entry_price,
            "count": count,
            "entry_ts": entry_ts,
            "last_update_ts": updated_ts if updated_ts is not None else time.time(),
            "entry_context": position_summary.get("entry_context") if isinstance(position_summary.get("entry_context"), dict) else existing.get("entry_context") if isinstance(existing, dict) else None,
            "aion_relaxation_used": bool(existing.get("aion_relaxation_used")) if isinstance(existing, dict) else False,
            "aion_relaxation_reason": existing.get("aion_relaxation_reason") if isinstance(existing, dict) else None,
        }
        self.save_live_position_state(state)
        return state[ticker]

    def print_recent_live_audit_entries(self, last_n=5):
        if not os.path.exists(LIVE_AUDIT_LOG_FILE):
            print("[LIVE-AUDIT] no audit log found")
            return
        try:
            with open(LIVE_AUDIT_LOG_FILE, newline="") as csv_file:
                rows = list(csv.DictReader(csv_file))
        except OSError:
            print("[LIVE-AUDIT] unable to read audit log")
            return
        if not rows:
            print("[LIVE-AUDIT] no audit log found")
            return
        recent_rows = rows[-last_n:]
        print(f"[LIVE-AUDIT] showing last {len(recent_rows)} entries")
        for row in recent_rows:
            print(
                f"[LIVE-AUDIT] {row.get('timestamp', '')} | {row.get('event_type', '')} | "
                f"ticker={row.get('ticker', '')} | order_id={row.get('order_id', '')} | "
                f"reason={row.get('reason', '')}"
            )

    def print_live_startup_checklist(self, args=None):
        config_status = self.get_live_config_status()
        effective_live_dry_run = compute_effective_live_dry_run()
        canary_required = bool(args is not None and getattr(args, "run_live_canary", False))
        canary_ticker_ok = (not canary_required) or bool(
            getattr(args, "live_test_ticker", None) or globals().get("LIVE_TEST_TICKER")
        )
        canary_available_ok = (not canary_required) or (not self.live_canary_submitted)
        checks = [
            ("LIVE_MODE", bool(globals().get("LIVE_MODE", False))),
            ("LIVE_ARMED", bool(globals().get("LIVE_ARMED", False))),
            ("ENV_CONFIRMED", bool(globals().get("LIVE_ENV_CONFIRMED", False))),
            ("EFFECTIVE_DRY_RUN", bool(effective_live_dry_run)),
            ("CONFIG_READY", bool(config_status.get("ok"))),
            ("AUTH_READY", bool(self.can_build_live_auth())),
            ("ORDER_API_PATH", bool(self.has_live_order_api_path())),
            ("RATE_LIMIT_CONFIG", bool(LIVE_ORDER_RATE_LIMIT and LIVE_ORDER_RATE_WINDOW_SEC)),
            ("DAILY_CAP_CONFIG", bool(MAX_LIVE_TRADES_PER_DAY)),
            ("SIZE_CAP_CONFIG", bool(MAX_LIVE_ORDER_SIZE)),
            ("CANARY_TICKER", canary_ticker_ok),
            ("CANARY_AVAILABLE", canary_available_ok),
        ]
        for name, ok in checks:
            print(f"[LIVE-CHECK] {name}: {'PASS' if ok else 'FAIL'}")

    def run_live_preflight(self, args=None):
        print("[LIVE-PREFLIGHT] starting")
        config_status = self.get_live_config_status()
        effective_live_dry_run = compute_effective_live_dry_run()
        canary_required = bool(args is not None and getattr(args, "run_live_canary", False))
        canary_ticker_ok = (not canary_required) or bool(
            getattr(args, "live_test_ticker", None) or globals().get("LIVE_TEST_TICKER")
        )
        canary_available_ok = (not canary_required) or (not self.live_canary_submitted)
        checks = {
            "LIVE_MODE": bool(globals().get("LIVE_MODE", False)),
            "LIVE_ARMED": bool(globals().get("LIVE_ARMED", False)),
            "ENV_CONFIRMED": bool(globals().get("LIVE_ENV_CONFIRMED", False)),
            "EFFECTIVE_DRY_RUN": bool(effective_live_dry_run),
            "CONFIG_READY": bool(config_status.get("ok")),
            "AUTH_READY": bool(self.can_build_live_auth()),
            "ORDER_API_PATH": bool(self.has_live_order_api_path()),
            "RATE_LIMIT_CONFIG": bool(LIVE_ORDER_RATE_LIMIT and LIVE_ORDER_RATE_WINDOW_SEC),
            "DAILY_CAP_CONFIG": bool(MAX_LIVE_TRADES_PER_DAY),
            "SIZE_CAP_CONFIG": bool(MAX_LIVE_ORDER_SIZE),
            "CANARY_TICKER": canary_ticker_ok,
            "CANARY_AVAILABLE": canary_available_ok,
        }
        for name, ok in checks.items():
            print(f"[LIVE-PREFLIGHT] {name}={'PASS' if ok else 'FAIL'}")
        required_checks = (
            "LIVE_MODE",
            "LIVE_ARMED",
            "ENV_CONFIRMED",
            "CONFIG_READY",
            "AUTH_READY",
            "ORDER_API_PATH",
            "RATE_LIMIT_CONFIG",
            "DAILY_CAP_CONFIG",
            "SIZE_CAP_CONFIG",
        )
        if canary_required:
            required_checks = required_checks + ("CANARY_TICKER", "CANARY_AVAILABLE")
        ready = all(checks[name] for name in required_checks)
        print(f"[LIVE-PREFLIGHT] {'READY' if ready else 'NOT READY'}")
        return {
            "ok": ready,
            "reason": "ready" if ready else "not_ready",
            "checks": checks,
        }

    def build_quote(self, market):
        ticker = market.get("ticker", "N/A")
        title = market.get("title") or market.get("subtitle") or "Untitled"
        family = self.get_market_family(market)

        def _normalize_price_like(value):
            numeric = self.to_float(value, None)
            if numeric is None or numeric <= 0.0:
                return None
            return numeric

        def _present(value):
            return value not in (None, "", [], {})

        sports_quote_snapshot = {}
        orderbook_shape = "none"
        if isinstance(market.get("orderbook_fp"), dict):
            orderbook_shape = "orderbook_fp"
        elif isinstance(market.get("orderbook"), dict):
            orderbook_shape = "orderbook"
        elif market.get("yes") not in (None, "", [], {} ) or market.get("no") not in (None, "", [], {}):
            orderbook_shape = "side_levels"
        elif market.get("yes_dollars") not in (None, "", [], {} ) or market.get("no_dollars") not in (None, "", [], {}):
            orderbook_shape = "root_dollars"
        if self._is_sports_market_or_family(family):
            try:
                sports_quote_snapshot = self._extract_non_targeted_topbook_snapshot(market)
            except Exception as exc:
                sports_quote_snapshot = {
                    "failure_stage": "topbook_snapshot_exception",
                    "failure_reason": exc.__class__.__name__,
                }

        try:
            print(
                "[AION-QUOTE-HYDRATION-ROOT] "
                + json.dumps(
                    {
                        "ticker": ticker or None,
                        "family": family,
                        "source_path": "build_quote",
                        "market_keys": sorted(list(market.keys()))[:64],
                        "has_orderbook": bool(orderbook_shape != "none"),
                        "orderbook_shape": orderbook_shape,
                        "build_quote_called": True,
                        "recursion_detected": False,
                        "fallback_attempted": False,
                        "fallback_success": False,
                        "topbook_extract_success": False,
                        "yes_bid": None,
                        "yes_ask": None,
                        "no_bid": None,
                        "no_ask": None,
                    },
                    sort_keys=True,
                    default=str,
                )
            )
        except Exception:
            pass

        yes_bid_raw = self.to_float(market.get("yes_bid_dollars", market.get("yes_bid")), None)
        yes_ask_raw = self.to_float(market.get("yes_ask_dollars", market.get("yes_ask")), None)
        last_price = self.to_float(
            market.get("last_price_dollars", market.get("last_price", yes_bid_raw))
        )
        volume = self.to_float(market.get("volume_fp", market.get("volume")), 0.0)
        liquidity = self.to_float(market.get("liquidity_dollars"), 0.0)

        no_bid_raw = self.to_float(market.get("no_bid_dollars", market.get("no_bid")), None)
        no_ask_raw = self.to_float(market.get("no_ask_dollars", market.get("no_ask")), None)

        yes_bid = _normalize_price_like(yes_bid_raw)
        yes_ask = _normalize_price_like(yes_ask_raw)
        no_bid = _normalize_price_like(no_bid_raw)
        no_ask = _normalize_price_like(no_ask_raw)

        source_fields_snapshot = {
            "yes_bid_dollars": yes_bid_raw,
            "yes_ask_dollars": yes_ask_raw,
            "no_bid_dollars": no_bid_raw,
            "no_ask_dollars": no_ask_raw,
            "best_yes_price": self.to_float(market.get("best_yes_price"), None),
            "best_no_price": self.to_float(market.get("best_no_price"), None),
            "yes_top_price": self.to_float(sports_quote_snapshot.get("yes_top_price"), None),
            "no_top_price": self.to_float(sports_quote_snapshot.get("no_top_price"), None),
            "yes_top_size": self.to_float(sports_quote_snapshot.get("yes_top_size"), None),
            "no_top_size": self.to_float(sports_quote_snapshot.get("no_top_size"), None),
            "orderbook": market.get("orderbook"),
            "orderbook_fp": market.get("orderbook_fp"),
            "yes_dollars": market.get("yes_dollars"),
            "no_dollars": market.get("no_dollars"),
            "yes": market.get("yes"),
            "no": market.get("no"),
        }
        source_quote_fields_present = sorted(
            [name for name, value in source_fields_snapshot.items() if _present(value)]
        )
        source_quote_fields_missing = sorted(
            [name for name in ("yes_bid_dollars", "yes_ask_dollars", "no_bid_dollars", "no_ask_dollars") if not _normalize_price_like(source_fields_snapshot.get(name))]
        )
        candidate_price_fields_before_mapping = {
            "yes_bid": yes_bid,
            "yes_ask": yes_ask,
            "no_bid": no_bid,
            "no_ask": no_ask,
        }
        quote_mapping_applied = False
        quote_mapping_reason = "direct_fields"
        quote_mapping_block_reason = None

        if self._is_sports_market_or_family(family):
            yes_top_price = self.to_float(sports_quote_snapshot.get("yes_top_price"), None)
            no_top_price = self.to_float(sports_quote_snapshot.get("no_top_price"), None)
            if yes_ask is None and yes_top_price is not None and yes_top_price > 0.0:
                yes_ask = yes_top_price
                quote_mapping_applied = True
                quote_mapping_reason = "yes_top_price_fallback"
            if no_ask is None and no_top_price is not None and no_top_price > 0.0:
                no_ask = no_top_price
                quote_mapping_applied = True
                quote_mapping_reason = "no_top_price_fallback"
            if yes_bid is None and no_ask is not None:
                yes_bid = max(0.0, 1.0 - float(no_ask))
                quote_mapping_applied = True
                quote_mapping_reason = "paired_topbook_recovery"
            if no_bid is None and yes_ask is not None:
                no_bid = max(0.0, 1.0 - float(yes_ask))
                quote_mapping_applied = True
                quote_mapping_reason = "paired_topbook_recovery"
            yes_bid, yes_ask, no_bid, no_ask = self._infer_missing_binary_quotes(yes_bid, yes_ask, no_bid, no_ask)
            if (
                yes_bid is None
                and yes_ask is None
                and no_bid is None
                and no_ask is None
                and (yes_top_price is None or yes_top_price <= 0.0)
                and (no_top_price is None or no_top_price <= 0.0)
            ):
                quote_mapping_block_reason = "no_valid_quote_or_orderbook_prices"
        else:
            yes_bid, yes_ask, no_bid, no_ask = self._infer_missing_binary_quotes(yes_bid, yes_ask, no_bid, no_ask)

        if self._is_sports_market_or_family(family):
            self._emit_topbook_trace(
                "[LIVE-TOPBOOK-RAW]",
                market,
                family=family,
                reason="build_quote_input",
                ticker=ticker,
                yes_bid=yes_bid,
                yes_ask=yes_ask,
                no_bid=no_bid,
                no_ask=no_ask,
            )

        continuity_used = False
        continuity_reason = "not_needed"
        if self._is_sports_market_or_family(family):
            yes_bid, yes_ask, no_bid, no_ask, continuity_used, continuity_reason = self._apply_sports_quote_continuity(
                market,
                yes_bid,
                yes_ask,
                no_bid,
                no_ask,
            )

        yes_bid = self.to_float(yes_bid, 0.0)
        yes_ask = self.to_float(yes_ask, 0.0)
        no_bid = self.to_float(no_bid, 0.0)
        no_ask = self.to_float(no_ask, 0.0)
        provisional_quote_ready = bool((yes_bid > 0.0 and yes_ask > 0.0) or (no_bid > 0.0 and no_ask > 0.0))
        quote_complete = bool(yes_bid > 0.0 and yes_ask > 0.0 and no_bid > 0.0 and no_ask > 0.0)
        final_quote_ready = provisional_quote_ready
        quote_ready_reason = "direct_fields" if provisional_quote_ready else "missing_quote_object"
        if self._is_sports_market_or_family(family):
            spread = round(yes_ask - yes_bid, 4) if yes_bid > 0.0 and yes_ask > 0.0 else None
            if sports_quote_snapshot.get("failure_stage") or sports_quote_snapshot.get("failure_reason"):
                self._record_execution_failure_audit(
                    reason=sports_quote_snapshot.get("failure_reason") or sports_quote_snapshot.get("failure_stage") or "orderbook_parse_failed",
                    stage="orderbook_parse",
                    orderbook_parse_failure=True,
                )
                if sports_quote_snapshot.get("failure_reason"):
                    quote_mapping_block_reason = quote_mapping_block_reason or f"quote_orderbook_snapshot_{sports_quote_snapshot.get('failure_reason')}"
            provisional_quote_ready = bool((yes_bid > 0.0 and yes_ask > 0.0) or (no_bid > 0.0 and no_ask > 0.0))
            final_quote_ready = provisional_quote_ready
            sports_threshold_quote_diag = {
                "ticker": ticker,
                "quote_ready": bool(provisional_quote_ready),
                "quote_ready_before_fallback": bool(quote_ready_reason != "missing_quote_object"),
                "quote_ready_after_fallback": bool(provisional_quote_ready),
                "quote_complete": bool(quote_complete),
                "selected_side": selected_side if 'selected_side' in locals() else None,
                "selected_price": selected_price if 'selected_price' in locals() else None,
                "orderbook_exists": bool((yes_bid > 0.0 and yes_ask > 0.0) or (no_bid > 0.0 and no_ask > 0.0) or (sports_quote_snapshot.get("yes_top_size") or 0.0) > 0.0 or (sports_quote_snapshot.get("no_top_size") or 0.0) > 0.0),
                "topbook_snapshot_present": bool(sports_quote_snapshot and not sports_quote_snapshot.get("failure_stage")),
                "orderbook_exists": bool((yes_bid > 0.0 and yes_ask > 0.0) or (no_bid > 0.0 and no_ask > 0.0) or (sports_quote_snapshot.get("yes_top_size") or 0.0) > 0.0 or (sports_quote_snapshot.get("no_top_size") or 0.0) > 0.0 or (sports_quote_snapshot and not sports_quote_snapshot.get("failure_stage"))),
                "topbook_depth_exists": bool((sports_quote_snapshot.get("yes_top_size") or 0.0) > 0.0 or (sports_quote_snapshot.get("no_top_size") or 0.0) > 0.0 or (sports_quote_snapshot and not sports_quote_snapshot.get("failure_stage"))),
                "no_top_size": sports_quote_snapshot.get("no_top_size"),
                "quote_source": quote_ready_reason,
                "source_of_quote_data": quote_ready_reason,
                "failure_stage": sports_quote_snapshot.get("failure_stage"),
                "failure_reason": sports_quote_snapshot.get("failure_reason"),
                "orderbook_ready": bool((sports_quote_snapshot.get("yes_top_size") or 0.0) > 0.0 or (sports_quote_snapshot.get("no_top_size") or 0.0) > 0.0 or quote_mapping_applied),
                "orderbook_ready": bool((sports_quote_snapshot.get("yes_top_size") or 0.0) > 0.0 or (sports_quote_snapshot.get("no_top_size") or 0.0) > 0.0 or quote_mapping_applied or (sports_quote_snapshot and not sports_quote_snapshot.get("failure_stage"))),
            }
            adaptive_spread_limit = self._get_sports_adaptive_spread_threshold(
                market,
                spread=spread,
                liquidity=liquidity,
                yes_top_size=sports_quote_snapshot.get("yes_top_size"),
                no_top_size=sports_quote_snapshot.get("no_top_size"),
                context="build_quote_final",
                quote_diag=sports_threshold_quote_diag,
            ).get("adaptive_threshold", MAX_ENTRY_SPREAD)
            reject_reason = self._topbook_reject_reason(
                yes_price=yes_ask if yes_ask > 0.0 else None,
                yes_size=sports_quote_snapshot.get("yes_top_size"),
                no_price=no_ask if no_ask > 0.0 else None,
                no_size=sports_quote_snapshot.get("no_top_size"),
                spread=spread,
                max_spread=adaptive_spread_limit,
            )
            self._emit_topbook_trace(
                "[LIVE-TOPBOOK-FINAL]",
                market,
                family=family,
                reason=f"{reject_reason};continuity={continuity_reason}",
                ticker=ticker,
                yes_bid=yes_bid,
                yes_ask=yes_ask,
                no_bid=no_bid,
                no_ask=no_ask,
                yes_price=yes_ask,
                no_price=no_ask,
                yes_size=sports_quote_snapshot.get("yes_top_size"),
                no_size=sports_quote_snapshot.get("no_top_size"),
                spread=spread,
                continuity_used="yes" if continuity_used else "no",
            )
            self._record_sports_quote_continuity_snapshot(
                ticker,
                family,
                yes_bid,
                yes_ask,
                no_bid,
                no_ask,
                yes_top_size=sports_quote_snapshot.get("yes_top_size"),
                no_top_size=sports_quote_snapshot.get("no_top_size"),
                source="build_quote",
            )
            quote_complete = bool(yes_bid > 0.0 and yes_ask > 0.0 and no_bid > 0.0 and no_ask > 0.0)
            final_quote_ready = bool((yes_bid > 0.0 and yes_ask > 0.0) or (no_bid > 0.0 and no_ask > 0.0))
            if quote_mapping_applied or quote_mapping_block_reason or spread is None or not final_quote_ready:
                quote_ready_reason = (
                    "recovered_from_topbook_pair"
                    if quote_mapping_applied and final_quote_ready
                    else (
                        quote_mapping_block_reason
                        or (
                            "incomplete_quote_fields:"
                            + ",".join(
                                name
                                for name, value in {
                                    "yes_bid": yes_bid,
                                    "yes_ask": yes_ask,
                                    "no_bid": no_bid,
                                    "no_ask": no_ask,
                                }.items()
                                if value in (None, "", 0, 0.0)
                            )
                            if not final_quote_ready
                            else "direct_fields"
                        )
                    )
                )
                quote_source_trace = {
                    "ticker": ticker,
                    "family": family,
                    "source_quote_fields_present": source_quote_fields_present,
                    "source_quote_fields_missing": source_quote_fields_missing,
                    "candidate_price_fields_before_mapping": candidate_price_fields_before_mapping,
                    "candidate_price_fields_after_mapping": {
                        "yes_bid": yes_bid,
                        "yes_ask": yes_ask,
                        "no_bid": no_bid,
                        "no_ask": no_ask,
                    },
                    "computed_spread": spread,
                    "quote_ready": final_quote_ready,
                    "quote_complete": quote_complete,
                    "quote_missing_fields": [
                        name
                        for name, value in {
                            "yes_bid": yes_bid,
                            "yes_ask": yes_ask,
                            "no_bid": no_bid,
                            "no_ask": no_ask,
                        }.items()
                        if value in (None, "", 0, 0.0)
                    ],
                    "quote_ready_reason": quote_ready_reason,
                    "orderbook_source_object": sports_quote_snapshot,
                    "source_of_quote_data": sports_quote_snapshot.get("source_path") or ("topbook_recovery" if quote_mapping_applied else "direct_fields"),
                }
                print("[AION-QUOTE-SOURCE-TRACE] " + json.dumps(quote_source_trace, sort_keys=True, default=str))
                print("[AION-PRICE-MAPPING-TRACE] " + json.dumps(
                    {
                        **quote_source_trace,
                        "mapping_applied": quote_mapping_applied,
                        "mapping_reason": quote_mapping_reason,
                        "mapping_block_reason": quote_mapping_block_reason,
                    },
                    sort_keys=True,
                    default=str,
                ))
                if final_quote_ready and not quote_complete:
                    print(
                        "[AION-QUOTE-CONSISTENCY-WARN] "
                        + json.dumps(
                            {
                                "ticker": ticker,
                                "quote_ready": True,
                                "quote_complete": False,
                                "quote_missing_fields": quote_source_trace.get("quote_missing_fields"),
                                "source_of_quote_data": quote_source_trace.get("source_of_quote_data"),
                                "block_reason": "partial_quote_complete",
                            },
                            sort_keys=True,
                            default=str,
                        )
                    )
                if final_quote_ready and quote_mapping_applied:
                    print("[AION-QUOTE-MAPPING-RECOVERED] " + json.dumps(
                        {
                            **quote_source_trace,
                            "recovery_source": quote_source_trace.get("source_of_quote_data"),
                            "mapping_reason": quote_mapping_reason,
                        },
                        sort_keys=True,
                        default=str,
                    ))
                elif not final_quote_ready:
                    if not quote_mapping_block_reason:
                        quote_mapping_block_reason = (
                            "incomplete_quote_fields:"
                            + ",".join(
                                name
                                for name, value in {
                                    "yes_bid": yes_bid,
                                    "yes_ask": yes_ask,
                                    "no_bid": no_bid,
                                    "no_ask": no_ask,
                                }.items()
                                if value in (None, "", 0, 0.0)
                            )
                        )
                    print("[AION-QUOTE-MAPPING-BLOCKED] " + json.dumps(
                        {
                            **quote_source_trace,
                            "block_reason": quote_mapping_block_reason or "incomplete_quote_fields",
                        },
                        sort_keys=True,
                        default=str,
                    ))

        try:
            print(
                "[AION-QUOTE-HYDRATION-SOURCE] "
                + json.dumps(
                    {
                        "ticker": ticker or None,
                        "family": family,
                        "source_path": sports_quote_snapshot.get("source_path") or "none",
                        "market_keys": sorted(list(market.keys()))[:64],
                        "has_orderbook": bool(orderbook_shape != "none"),
                        "orderbook_shape": orderbook_shape,
                        "build_quote_called": True,
                        "recursion_detected": bool(sports_quote_snapshot.get("failure_reason") == "RecursionError"),
                        "fallback_attempted": bool(quote_mapping_applied),
                        "fallback_success": bool(quote_mapping_applied and final_quote_ready),
                        "topbook_extract_success": bool((sports_quote_snapshot.get("yes_top_size") or 0.0) > 0.0 or (sports_quote_snapshot.get("no_top_size") or 0.0) > 0.0),
                        "recursion_guard_hit": bool(sports_quote_snapshot.get("failure_reason") == "RecursionError" or getattr(self, "_last_orderbook_recursion_guard_hit", False)),
                        "yes_bid": yes_bid,
                        "yes_ask": yes_ask,
                        "no_bid": no_bid,
                        "no_ask": no_ask,
                    },
                    sort_keys=True,
                    default=str,
                )
            )
            print(
                "[AION-QUOTE-HYDRATION-BUILD] "
                + json.dumps(
                    {
                        "ticker": ticker or None,
                        "family": family,
                        "source_path": sports_quote_snapshot.get("source_path") or "none",
                        "market_keys": sorted(list(market.keys()))[:64],
                        "has_orderbook": bool(orderbook_shape != "none"),
                        "orderbook_shape": orderbook_shape,
                        "build_quote_called": True,
                        "build_quote_success": bool(final_quote_ready),
                        "failure_reason": None if final_quote_ready else (quote_mapping_block_reason or "missing_quote_object"),
                        "recursion_detected": bool(sports_quote_snapshot.get("failure_reason") == "RecursionError"),
                        "fallback_attempted": bool(quote_mapping_applied),
                        "fallback_success": bool(quote_mapping_applied and final_quote_ready),
                        "topbook_extract_success": bool((sports_quote_snapshot.get("yes_top_size") or 0.0) > 0.0 or (sports_quote_snapshot.get("no_top_size") or 0.0) > 0.0),
                        "yes_bid": yes_bid,
                        "yes_ask": yes_ask,
                        "no_bid": no_bid,
                        "no_ask": no_ask,
                    },
                    sort_keys=True,
                    default=str,
                )
            )
            if not final_quote_ready:
                print(
                    "[AION-QUOTE-HYDRATION-FAIL] "
                    + json.dumps(
                        {
                            "ticker": ticker or None,
                            "family": family,
                            "source_path": sports_quote_snapshot.get("source_path") or "none",
                            "market_keys": sorted(list(market.keys()))[:64],
                            "has_orderbook": bool(orderbook_shape != "none"),
                            "orderbook_shape": orderbook_shape,
                            "build_quote_called": True,
                            "build_quote_success": False,
                            "failure_reason": quote_mapping_block_reason or "missing_quote_object",
                            "recursion_detected": bool(sports_quote_snapshot.get("failure_reason") == "RecursionError"),
                            "fallback_attempted": bool(quote_mapping_applied),
                            "fallback_success": False,
                            "topbook_extract_success": bool((sports_quote_snapshot.get("yes_top_size") or 0.0) > 0.0 or (sports_quote_snapshot.get("no_top_size") or 0.0) > 0.0),
                            "yes_bid": yes_bid,
                            "yes_ask": yes_ask,
                            "no_bid": no_bid,
                            "no_ask": no_ask,
                        },
                        sort_keys=True,
                        default=str,
                    )
                )
        except Exception:
            pass

        yes_top_size = self.to_float(
            sports_quote_snapshot.get("yes_top_size") if isinstance(sports_quote_snapshot, dict) else None,
            self.to_float(market.get("yes_top_size"), None),
        )
        no_top_size = self.to_float(
            sports_quote_snapshot.get("no_top_size") if isinstance(sports_quote_snapshot, dict) else None,
            self.to_float(market.get("no_top_size"), None),
        )
        return Quote(
            ticker=ticker,
            title=title,
            yes_bid=yes_bid,
            yes_ask=yes_ask,
            no_bid=no_bid,
            no_ask=no_ask,
            last_price=last_price,
            volume=volume,
            liquidity=liquidity,
            yes_top_size=yes_top_size,
            no_top_size=no_top_size,
        )

    def _diagnose_quote_readiness_context(self, *, market=None, q=None, family=None, sports_context=None, source="unknown"):
        market = market if isinstance(market, dict) else {}
        sports_context = sports_context if isinstance(sports_context, dict) else {}
        q = q if q is not None else None
        ticker = str(getattr(q, "ticker", "") or market.get("ticker", "") or "").strip()
        family = str(family or self.get_market_family(market) or getattr(q, "family", "") or "UNKNOWN").strip().upper() or "UNKNOWN"

        def _value_or_none(*values):
            for value in values:
                if value is None:
                    continue
                if isinstance(value, str) and not value.strip():
                    continue
                return value
            return None

        yes_bid = self.to_float(_value_or_none(getattr(q, "yes_bid", None), market.get("yes_bid_dollars"), market.get("yes_bid")), None)
        yes_ask = self.to_float(_value_or_none(getattr(q, "yes_ask", None), market.get("yes_ask_dollars"), market.get("yes_ask")), None)
        no_bid = self.to_float(_value_or_none(getattr(q, "no_bid", None), market.get("no_bid_dollars"), market.get("no_bid")), None)
        no_ask = self.to_float(_value_or_none(getattr(q, "no_ask", None), market.get("no_ask_dollars"), market.get("no_ask")), None)
        last_price = self.to_float(_value_or_none(getattr(q, "last_price", None), market.get("last_price_dollars"), market.get("last_price")), None)
        volume = self.to_float(_value_or_none(getattr(q, "volume", None), market.get("volume_fp"), market.get("volume")), 0.0) or 0.0
        liquidity = self.to_float(_value_or_none(getattr(q, "liquidity", None), market.get("liquidity_dollars"), market.get("liquidity")), 0.0) or 0.0

        topbook_snapshot = {}
        try:
            topbook_snapshot = self._extract_non_targeted_topbook_snapshot(market) if market else {}
        except Exception as exc:
            topbook_snapshot = {"failure_stage": "topbook_snapshot_exception", "failure_reason": exc.__class__.__name__}

        quote_orderbook_snapshot = {}
        try:
            quote_orderbook_snapshot = self.resolve_aion_quote_orderbook_snapshot(
                ticker or market.get("ticker", "") or None,
                candidate=q,
                market=market,
                quote_diag=sports_context,
                price_source="bid",
                selected_side=sports_context.get("selected_side"),
                selection_stage=source,
                allow_refresh=True,
            ) or {}
        except Exception as exc:
            try:
                import traceback as _traceback
                print(
                    "[AION-QUOTE-USABILITY-TRACE] "
                    + json.dumps(
                        {
                            "ticker": ticker or None,
                            "family": family,
                            "quote_ready": False,
                            "orderbook_ready": False,
                            "source_of_quote_data": "diagnostic_exception",
                            "quote_source": f"quote_orderbook_snapshot_{exc.__class__.__name__}",
                            "topbook_snapshot_present": bool(topbook_snapshot and not topbook_snapshot.get("failure_stage")),
                            "normalized_quote_present": False,
                            "normalized_orderbook_present": False,
                            "selected_side": None,
                            "selected_price": None,
                            "selected_price_source": "bid",
                            "missing_fields": [],
                            "stale_seconds": None,
                            "cache_hit": False,
                            "cache_age": None,
                            "fetch_attempted": False,
                            "fetch_success": False,
                            "failure_stage": f"quote_orderbook_snapshot_{exc.__class__.__name__}",
                            "block_reason": f"quote_orderbook_snapshot_{exc.__class__.__name__}",
                            "traceback": _traceback.format_exc(limit=18),
                        },
                        sort_keys=True,
                        default=str,
                    )
                )
            except Exception:
                pass
            quote_orderbook_snapshot = {
                "quote_ready": False,
                "quote_missing": True,
                "quote_complete": False,
                "quote_missing_fields": [],
                "quote_source": f"quote_orderbook_snapshot_{exc.__class__.__name__}",
                "orderbook_ready": False,
                "orderbook_source": None,
                "orderbook_missing_reason": f"quote_orderbook_snapshot_{exc.__class__.__name__}",
                "orderbook_fetch_called": False,
                "orderbook_fetch_success": False,
                "cache_hit": False,
                "cache_age_seconds": None,
                "yes_bid": None,
                "yes_ask": None,
                "no_bid": None,
                "no_ask": None,
                "yes_bid_dollars": None,
                "yes_ask_dollars": None,
                "no_bid_dollars": None,
                "no_ask_dollars": None,
                "selected_side": None,
                "selected_price": None,
                "payload_price_source": "bid",
                "blocker_reason": f"quote_orderbook_snapshot_{exc.__class__.__name__}",
                "orderbook_keys": [],
                "best_action": None,
            }

        canonical_tradeability = {}
        try:
            canonical_tradeability = self.resolve_canonical_tradeability(
                market,
                quote=q,
                context={
                    "quote_diag": sports_context,
                    "selected_side": sports_context.get("selected_side"),
                    "price_source": "bid",
                    "selection_stage": source,
                    "allow_refresh": True,
                    "ticker": ticker or market.get("ticker", ""),
                },
                source=source,
            ) or {}
        except Exception:
            canonical_tradeability = {}
        if canonical_tradeability:
            quote_orderbook_snapshot.update(canonical_tradeability)

        yes_top_price = self.to_float(topbook_snapshot.get("yes_top_price"), None)
        no_top_price = self.to_float(topbook_snapshot.get("no_top_price"), None)
        yes_top_size = self.to_float(topbook_snapshot.get("yes_top_size"), 0.0) or 0.0
        no_top_size = self.to_float(topbook_snapshot.get("no_top_size"), 0.0) or 0.0
        topbook_bucket = str(topbook_snapshot.get("top_book_bucket") or "unknown").strip().lower()
        topbook_snapshot_present = bool(topbook_snapshot and not topbook_snapshot.get("failure_stage"))
        market_direct_quote_ready = bool(
            any(
                self.to_float(market.get(key), None) not in (None, 0.0)
                for key in (
                    "yes_bid_dollars", "yes_bid", "yes_ask_dollars", "yes_ask",
                    "no_bid_dollars", "no_bid", "no_ask_dollars", "no_ask",
                )
            )
        )
        market_direct_orderbook_ready = bool(
            yes_top_size > 0.0
            or no_top_size > 0.0
            or self.to_float(market.get("yes_ask_size_fp"), None) not in (None, 0.0)
            or self.to_float(market.get("yes_bid_size_fp"), None) not in (None, 0.0)
            or self.to_float(market.get("no_ask_size_fp"), None) not in (None, 0.0)
            or self.to_float(market.get("no_bid_size_fp"), None) not in (None, 0.0)
            or self.to_float(market.get("yes_top_price"), None) not in (None, 0.0)
            or self.to_float(market.get("no_top_price"), None) not in (None, 0.0)
            or bool(market.get("orderbook"))
            or bool(market.get("orderbook_fp"))
        )

        quote_fields = {
            "yes_bid": yes_bid,
            "yes_ask": yes_ask,
            "no_bid": no_bid,
            "no_ask": no_ask,
            "last_price": last_price,
            "volume": volume,
            "liquidity": liquidity,
        }
        missing_fields = [name for name, value in quote_fields.items() if value in (None, "", 0, 0.0)]
        yes_bid_missing = yes_bid is None or yes_bid <= 0.0
        yes_ask_missing = yes_ask is None or yes_ask <= 0.0
        no_bid_missing = no_bid is None or no_bid <= 0.0
        no_ask_missing = no_ask is None or no_ask <= 0.0
        orderbook_exists = bool(
            (yes_bid is not None and yes_bid > 0.0)
            or (yes_ask is not None and yes_ask > 0.0)
            or (no_bid is not None and no_bid > 0.0)
            or (no_ask is not None and no_ask > 0.0)
            or (yes_top_price is not None and yes_top_price > 0.0)
            or (no_top_price is not None and no_top_price > 0.0)
            or yes_top_size > 0.0
            or no_top_size > 0.0
            or bool(topbook_bucket and topbook_bucket not in {"unknown", "zero_top_book"})
        )
        canonical_source = {}
        canonical_source_guard_fallback_used = True
        try:
            canonical_source = self._resolve_aion_canonical_binary_prices(
                q if q is not None else market,
                ticker=ticker or None,
                source_label=f"quote_readiness.{source}",
            ) or {}
            canonical_source_guard_fallback_used = False
        except Exception:
            canonical_source = {}
            canonical_source_guard_fallback_used = True
        try:
            print("[AION-CANONICAL-SOURCE-GUARD] " + json.dumps({
                "function": "_diagnose_quote_readiness_context",
                "ticker": ticker or None,
                "canonical_source": canonical_source,
                "fallback_used": bool(canonical_source_guard_fallback_used),
            }, sort_keys=True, default=str))
        except Exception:
            pass
        book_valid = bool(
            canonical_source.get("book_valid")
            or canonical_source.get("orderbook_ready")
            or canonical_source.get("quote_ready")
            or topbook_snapshot_present
        )
        topbook_depth_exists = bool(
            yes_top_size > 0.0
            or no_top_size > 0.0
            or topbook_bucket in {"both_non_zero", "one_non_zero"}
            or self.to_float(canonical_source.get("yes_bid_cents"), 0.0) > 0.0
            or self.to_float(canonical_source.get("no_bid_cents"), 0.0) > 0.0
            or self.to_float(canonical_source.get("yes_ask_cents"), 0.0) > 0.0
            or self.to_float(canonical_source.get("no_ask_cents"), 0.0) > 0.0
            or market_direct_quote_ready
            or market_direct_orderbook_ready
            or book_valid
        )
        liquidity_depth = round(yes_top_size + no_top_size, 4)
        quote_ready_from_fields = bool(
            (yes_bid is not None or yes_ask is not None or no_bid is not None or no_ask is not None)
            and not (yes_bid_missing and yes_ask_missing and no_bid_missing and no_ask_missing)
        )
        quote_missing = not quote_ready_from_fields
        parser_related = bool(topbook_snapshot.get("failure_stage") or topbook_snapshot.get("failure_reason"))
        stale_seconds = self.to_float(market.get("staleness_seconds"), None)
        stale_related = bool(
            (stale_seconds is not None and stale_seconds > REALM_XX_WS_STALE_SECONDS)
            or str(market.get("status") or "").strip().lower() in {"closed", "resolved", "expired", "halted"}
            or bool(market.get("is_stale"))
        )
        empty_market_related = bool(not orderbook_exists and quote_missing and not topbook_depth_exists)
        fallback_quote = None
        fallback_quote_ready = False
        fallback_source = "none"
        recent_cache = dict(self.sports_quote_continuity_cache.get(ticker, {}) or {}) if self._is_sports_market_or_family(family) else {}
        cache_age_seconds = None
        if recent_cache.get("ts"):
            try:
                cache_age_seconds = max(0.0, time.time() - float(recent_cache.get("ts") or 0.0))
            except (TypeError, ValueError):
                cache_age_seconds = None
        cache_stable_cycles = int(recent_cache.get("stable_cycles", 0) or 0) if recent_cache else 0
        if not quote_ready_from_fields and market:
            try:
                fallback_snapshot = topbook_snapshot if isinstance(topbook_snapshot, dict) else {}
                fallback_quote = q
                fallback_source = "topbook_snapshot"
                fallback_quote_ready = bool(
                    (fallback_snapshot.get("yes_top_size") or 0.0) > 0.0
                    or (fallback_snapshot.get("no_top_size") or 0.0) > 0.0
                    or (fallback_snapshot.get("yes_top_price") or 0.0) > 0.0
                    or (fallback_snapshot.get("no_top_price") or 0.0) > 0.0
                    or topbook_depth_exists
                    or orderbook_exists
                )
            except Exception as exc:
                parser_related = True
                fallback_quote = None
                fallback_source = f"topbook_snapshot_{exc.__class__.__name__}"
        if not fallback_quote_ready and topbook_depth_exists and orderbook_exists:
            fallback_quote_ready = True
            if fallback_source == "none":
                fallback_source = "topbook_snapshot"
        resolved_quote_ready = bool(quote_orderbook_snapshot.get("quote_ready"))
        resolved_quote_missing = bool(quote_orderbook_snapshot.get("quote_missing"))
        resolved_quote_complete = bool(quote_orderbook_snapshot.get("quote_complete"))
        resolved_selected_side = quote_orderbook_snapshot.get("selected_side")
        resolved_selected_price = quote_orderbook_snapshot.get("selected_price")
        resolved_orderbook_ready = bool(quote_orderbook_snapshot.get("orderbook_ready") or quote_orderbook_snapshot.get("selected_price") not in (None, "", 0, 0.0) or quote_orderbook_snapshot.get("yes_bid") not in (None, "", 0, 0.0) or quote_orderbook_snapshot.get("yes_ask") not in (None, "", 0, 0.0) or quote_orderbook_snapshot.get("no_bid") not in (None, "", 0, 0.0) or quote_orderbook_snapshot.get("no_ask") not in (None, "", 0, 0.0) or (topbook_snapshot and not topbook_snapshot.get("failure_stage")) or topbook_snapshot_present)
        quote_ready = bool(quote_ready_from_fields or fallback_quote_ready or resolved_quote_ready or bool(sports_context.get("quote_ready")))
        hydrated_quote_ready = bool(
            q is not None and any(
                self.to_float(getattr(q, field, None), None) not in (None, 0.0)
                for field in ("yes_bid", "yes_ask", "no_bid", "no_ask")
            )
        )
        if q is not None and hydrated_quote_ready and not quote_ready:
            quote_ready = True
            quote_ready_reason = "hydrated_quote_object"
            source_of_quote_data = "hydrated_quote_object"
            fallback_quote_ready = True
            resolved_quote_ready = True
            quote_missing = False
        orderbook_salvaged = False
        if not resolved_orderbook_ready and (topbook_snapshot_present or topbook_depth_exists) and (
            resolved_selected_price not in (None, "", 0, 0.0)
            or yes_bid is not None
            or yes_ask is not None
            or no_bid is not None
            or no_ask is not None
            or resolved_quote_ready
        ):
            resolved_orderbook_ready = True
            orderbook_salvaged = True
            quote_orderbook_snapshot["orderbook_ready"] = True
            quote_orderbook_snapshot["orderbook_exists"] = True
            quote_orderbook_snapshot["normalized_orderbook_present"] = True
            quote_orderbook_snapshot["topbook_snapshot_present"] = bool(topbook_snapshot_present)
            quote_orderbook_snapshot["topbook_depth_exists"] = bool(topbook_depth_exists)
            quote_orderbook_snapshot["orderbook_missing_reason"] = None
            quote_orderbook_snapshot["blocker_reason"] = None
            try:
                print("[AION-ORDERBOOK-SALVAGED] " + json.dumps({
                    "ticker": ticker or None,
                    "family": family,
                    "source_path": source,
                    "topbook_snapshot_present": bool(topbook_snapshot_present),
                    "topbook_depth_exists": bool(topbook_depth_exists),
                    "selected_side": resolved_selected_side,
                    "selected_price": resolved_selected_price,
                    "quote_ready": bool(quote_ready),
                    "orderbook_ready": True,
                    "failure_reason": None,
                }, sort_keys=True, default=str))
            except Exception:
                pass
        elif not resolved_orderbook_ready:
            try:
                print("[AION-ORDERBOOK-REJECT] " + json.dumps({
                    "ticker": ticker or None,
                    "family": family,
                    "source_path": source,
                    "topbook_snapshot_present": bool(topbook_snapshot_present),
                    "topbook_depth_exists": bool(topbook_depth_exists),
                    "selected_side": resolved_selected_side,
                    "selected_price": resolved_selected_price,
                    "quote_ready": bool(quote_ready),
                    "orderbook_ready": False,
                    "failure_reason": quote_orderbook_snapshot.get("orderbook_missing_reason") or "orderbook_not_usable",
                }, sort_keys=True, default=str))
            except Exception:
                pass
        quote_complete = bool(
            resolved_quote_complete
            or (yes_bid is not None and yes_bid > 0.0 and yes_ask is not None and yes_ask > 0.0 and no_bid is not None and no_bid > 0.0 and no_ask is not None and no_ask > 0.0)
        )
        raw_quote_candidates = {
            "yes_bid": getattr(q, "yes_bid", None) if q is not None else market.get("yes_bid"),
            "yes_ask": getattr(q, "yes_ask", None) if q is not None else market.get("yes_ask"),
            "no_bid": getattr(q, "no_bid", None) if q is not None else market.get("no_bid"),
            "no_ask": getattr(q, "no_ask", None) if q is not None else market.get("no_ask"),
        }
        malformed_quote_fields = [
            name for name, raw_value in raw_quote_candidates.items()
            if raw_value not in (None, "", 0, 0.0) and self.to_float(raw_value, None) is None
        ]
        missing_quote_fields = [
            name for name, raw_value in raw_quote_candidates.items()
            if raw_value in (None, "", 0, 0.0)
        ]
        if quote_ready:
            quote_missing = False
        if quote_ready_from_fields:
            quote_ready_reason = "direct_fields"
            source_of_quote_data = "direct_fields"
        elif fallback_quote_ready:
            quote_ready_reason = fallback_source
            source_of_quote_data = fallback_source
        elif resolved_quote_ready:
            quote_ready_reason = quote_orderbook_snapshot.get("quote_source") or "resolved_orderbook"
            source_of_quote_data = quote_orderbook_snapshot.get("quote_source") or "resolved_orderbook"
        elif parser_related:
            quote_ready_reason = "parser_failure"
            source_of_quote_data = "parser_failure"
        elif stale_related:
            quote_ready_reason = "stale_or_closed"
            source_of_quote_data = "stale_or_closed"
        elif empty_market_related:
            quote_ready_reason = "empty_market"
            source_of_quote_data = "empty_market"
        elif not orderbook_exists:
            quote_ready_reason = "missing_orderbook_data"
            source_of_quote_data = "missing_orderbook_data"
        elif not topbook_depth_exists:
            quote_ready_reason = "missing_topbook_depth"
            source_of_quote_data = "missing_topbook_depth"
        elif not recent_cache:
            quote_ready_reason = "no_recent_valid_quote"
            source_of_quote_data = "no_recent_valid_quote"
        elif cache_age_seconds is not None and cache_age_seconds > SPORTS_QUOTE_CONTINUITY_MAX_AGE_SECONDS:
            quote_ready_reason = "recent_quote_too_old"
            source_of_quote_data = "continuity_cache_too_old"
        else:
            quote_ready_reason = "quote_not_ready"
            source_of_quote_data = fallback_source if fallback_source != "none" else "unknown"
        diagnostics = {
            "ticker": ticker or None,
            "family": family,
            "source": source,
            "quote_source": quote_orderbook_snapshot.get("quote_source"),
            "selected_side": resolved_selected_side,
            "selected_price": resolved_selected_price,
            "normalized_quote_present": bool(quote_ready and not quote_missing),
            "normalized_orderbook_present": bool(resolved_orderbook_ready),
            "quote_ready_before_fallback": bool(sports_context.get("quote_ready") or quote_ready_from_fields),
            "quote_ready_after_fallback": bool(quote_ready),
            "quote_complete": bool(quote_complete),
            "quote_ready_reason": quote_ready_reason,
            "quote_missing_before_fallback": bool(sports_context.get("quote_missing") or quote_missing),
            "quote_missing_after_fallback": bool(not quote_ready),
            "missing_fields": missing_fields,
            "missing_quote_fields": missing_quote_fields,
            "usable_yes_bid": quote_orderbook_snapshot.get("yes_bid"),
            "usable_yes_ask": quote_orderbook_snapshot.get("yes_ask"),
            "usable_no_bid": quote_orderbook_snapshot.get("no_bid"),
            "usable_no_ask": quote_orderbook_snapshot.get("no_ask"),
            "malformed_quote_fields": malformed_quote_fields,
            "yes_bid_missing": bool(yes_bid_missing),
            "yes_ask_missing": bool(yes_ask_missing),
            "no_bid_missing": bool(no_bid_missing),
            "no_ask_missing": bool(no_ask_missing),
            "orderbook_exists": bool(orderbook_exists),
            "topbook_depth_exists": bool(topbook_depth_exists),
            "liquidity_depth": liquidity_depth,
            "topbook_bucket": topbook_bucket,
            "yes_top_size": round(yes_top_size, 4),
            "no_top_size": round(no_top_size, 4),
            "cache_hit": bool(quote_orderbook_snapshot.get("cache_hit")),
            "cache_age": quote_orderbook_snapshot.get("cache_age_seconds"),
            "fetch_attempted": bool(quote_orderbook_snapshot.get("orderbook_fetch_called")),
            "fetch_success": bool(quote_orderbook_snapshot.get("orderbook_fetch_success")),
            "failure_stage": quote_orderbook_snapshot.get("blocker_reason") or topbook_snapshot.get("failure_stage"),
            "spread": round(self.to_float(yes_ask - yes_bid, None), 4) if yes_bid is not None and yes_ask is not None else None,
            "spread_bucket": str(sports_context.get("spread_bucket") or sports_context.get("sports_spread_bucket") or "unknown").strip().lower(),
            "orderbook_age_seconds": round(cache_age_seconds, 2) if cache_age_seconds is not None else None,
            "quote_stability_cycles": int(cache_stable_cycles or 0),
            "parser_related": bool(parser_related),
            "stale_related": bool(stale_related),
            "empty_market_related": bool(empty_market_related),
            "fallback_source": fallback_source,
            "source_of_quote_data": source_of_quote_data,
            "fallback_quote_ready": bool(fallback_quote_ready),
            "quote_ready": bool(quote_ready),
            "quote_missing": bool(not quote_ready),
            "fallback_quote": fallback_quote,
        }
        diagnostics["canonical_tradeability"] = canonical_tradeability
        diagnostics["market_personality"] = _classify_market_personality(self, market=market, quote_diag=diagnostics, q=q, family=family)
        diagnostics["confidence_profile"] = _compute_realm_vv_confidence(self, 
            edge_after_cost=canonical_tradeability.get("edge_after_cost", sports_context.get("edge_after_cost")),
            liquidity_depth=liquidity_depth,
            spread_bucket=diagnostics.get("spread_bucket"),
            market_personality=diagnostics["market_personality"],
            profile_settings={"profile": _normalize_aion_aggression_profile(AION_AGGRESSION_PROFILE)},
        )
        if yes_bid is not None and yes_ask is not None:
            try:
                diagnostics["spread"] = round(max(0.0, float(yes_ask) - float(yes_bid)), 4)
            except (TypeError, ValueError):
                diagnostics["spread"] = None
        if not quote_ready or quote_missing or parser_related or stale_related or empty_market_related or not resolved_orderbook_ready:
            print(
                "[AION-QUOTE-USABILITY-TRACE] "
                + json.dumps(
                    {
                        "ticker": ticker or None,
                        "family": family,
                        "quote_ready": bool(quote_ready),
                        "orderbook_ready": bool(resolved_orderbook_ready),
                        "source_of_quote_data": source_of_quote_data,
                        "quote_source": quote_orderbook_snapshot.get("quote_source"),
                        "topbook_snapshot_present": bool(topbook_snapshot and not topbook_snapshot.get("failure_stage")),
                        "normalized_quote_present": bool(quote_ready and not quote_missing),
                        "normalized_orderbook_present": bool(resolved_orderbook_ready),
                        "selected_side": resolved_selected_side,
                        "selected_price": resolved_selected_price,
                        "selected_price_source": quote_orderbook_snapshot.get("selected_price_source_used") or quote_orderbook_snapshot.get("payload_price_source"),
                        "usable_yes_bid": quote_orderbook_snapshot.get("yes_bid"),
                        "usable_yes_ask": quote_orderbook_snapshot.get("yes_ask"),
                        "usable_no_bid": quote_orderbook_snapshot.get("no_bid"),
                        "usable_no_ask": quote_orderbook_snapshot.get("no_ask"),
                        "missing_fields": missing_fields,
                        "stale_seconds": stale_seconds,
                        "cache_hit": bool(quote_orderbook_snapshot.get("cache_hit")),
                        "cache_age": quote_orderbook_snapshot.get("cache_age_seconds"),
                        "fetch_attempted": bool(quote_orderbook_snapshot.get("orderbook_fetch_called")),
                        "fetch_success": bool(quote_orderbook_snapshot.get("orderbook_fetch_success")),
                        "failure_stage": quote_orderbook_snapshot.get("blocker_reason") or (topbook_snapshot.get("failure_stage") if isinstance(topbook_snapshot, dict) else None),
                        "block_reason": quote_orderbook_snapshot.get("blocker_reason") or quote_ready_reason,
                    },
                    sort_keys=True,
                    default=str,
                )
            )
            print("[AION-QUOTE-READINESS-DIAGNOSTIC] " + json.dumps({k: v for k, v in diagnostics.items() if k != "fallback_quote"}, sort_keys=True, default=str))
        return diagnostics

    def _resolve_unsafe_price_detail(self, *, market=None, q=None, family=None, quote_diag=None, source="unknown"):
        market = market if isinstance(market, dict) else {}
        quote_diag = quote_diag if isinstance(quote_diag, dict) else {}
        q = q if q is not None else None
        family = str(family or self.get_market_family(market) or getattr(q, "family", "") or "UNKNOWN").strip().upper() or "UNKNOWN"
        ticker = str(getattr(q, "ticker", "") or market.get("ticker", "") or "").strip()
        aggression_profile = _normalize_aion_aggression_profile(
            quote_diag.get("profile") or quote_diag.get("aggression_profile") or AION_AGGRESSION_PROFILE
        )

        def _pick(*values):
            for value in values:
                if value is None:
                    continue
                if isinstance(value, str) and not value.strip():
                    continue
                return value
            return None

        canonical_source = self._resolve_aion_canonical_binary_prices(
            q if q is not None else market,
            ticker=ticker or None,
            source_label=f"unsafe_price.{source}",
        )
        yes_bid = canonical_source.get("yes_bid")
        yes_ask = canonical_source.get("yes_ask")
        no_bid = canonical_source.get("no_bid")
        no_ask = canonical_source.get("no_ask")
        raw_yes_price = canonical_source.get("raw_yes_ask") if canonical_source.get("raw_yes_ask") is not None else canonical_source.get("raw_yes_bid")
        raw_no_price = canonical_source.get("raw_no_ask") if canonical_source.get("raw_no_ask") is not None else canonical_source.get("raw_no_bid")

        yes_bid_valid = yes_bid is not None and yes_bid > 0.0
        yes_ask_valid = yes_ask is not None and yes_ask > 0.0
        no_bid_valid = no_bid is not None and no_bid > 0.0
        no_ask_valid = no_ask is not None and no_ask > 0.0

        book_source = None
        best_bid = None
        best_ask = None
        midpoint = None
        spread = canonical_source.get("spread")
        if yes_bid_valid and yes_ask_valid:
            book_source = "yes"
            best_bid = yes_bid
            best_ask = yes_ask
            midpoint = (yes_bid + yes_ask) / 2.0
        elif no_bid_valid and no_ask_valid:
            book_source = "no"
            best_bid = max(0.0, 1.0 - no_ask)
            best_ask = max(0.0, 1.0 - no_bid)
            midpoint = max(0.0, min(1.0, 1.0 - ((no_bid + no_ask) / 2.0)))
        elif yes_bid_valid or yes_ask_valid:
            book_source = "yes_partial"
            best_bid = yes_bid if yes_bid_valid else None
            best_ask = yes_ask if yes_ask_valid else None
            if best_bid is not None and best_ask is not None:
                midpoint = (best_bid + best_ask) / 2.0
                spread = max(0.0, best_ask - best_bid)
        elif no_bid_valid or no_ask_valid:
            book_source = "no_partial"
            best_bid = max(0.0, 1.0 - no_ask) if no_ask_valid else None
            best_ask = max(0.0, 1.0 - no_bid) if no_bid_valid else None
            if best_bid is not None and best_ask is not None:
                midpoint = (best_bid + best_ask) / 2.0
                spread = max(0.0, best_ask - best_bid)

        normalized_yes_price = None
        normalized_no_price = None
        if midpoint is not None:
            normalized_yes_price = self._clamp(midpoint, 0.0, 1.0)
            normalized_no_price = self._clamp(1.0 - normalized_yes_price, 0.0, 1.0)
        elif raw_yes_price is not None:
            normalized_yes_price = self._clamp(raw_yes_price, 0.0, 1.0)
            normalized_no_price = self._clamp(1.0 - normalized_yes_price, 0.0, 1.0)
        elif raw_no_price is not None:
            normalized_no_price = self._clamp(raw_no_price, 0.0, 1.0)
            normalized_yes_price = self._clamp(1.0 - normalized_no_price, 0.0, 1.0)

        spread_bucket = str(
            quote_diag.get("spread_bucket")
            or quote_diag.get("sports_spread_bucket")
            or ("ultra_tight" if spread is not None and spread <= 0.012 else ("tight" if spread is not None and spread <= 0.03 else ("wide_but_possible" if spread is not None and spread <= AION_SPORTS_MAX_SPREAD_SOFT else ("extreme_wide" if spread is not None and spread <= AION_SPORTS_MAX_SPREAD_HARD else "unsafe"))))
        ).strip().lower() or "unknown"
        canonical_tradeability = quote_diag.get("canonical_tradeability") if isinstance(quote_diag.get("canonical_tradeability"), dict) else {}
        canonical_spread_classification = str(
            canonical_tradeability.get("spread_classification")
            or quote_diag.get("spread_classification")
            or quote_diag.get("canonical_spread_classification")
            or "UNSAFE"
        ).strip().upper() or "UNSAFE"
        valid_spread_bucket = spread_bucket in {"ultra_tight", "tight", "wide_but_possible", "extreme_wide"}
        book_valid = bool(canonical_source.get("book_valid"))
        normalized_consistent = bool(canonical_source.get("normalized_consistent"))
        bid_ask_consistent = bool(best_bid is None or best_ask is None or best_bid <= best_ask)
        book_missing_reasons = []
        if not yes_bid_valid and not yes_ask_valid:
            book_missing_reasons.append("yes_side_missing")
        if not no_bid_valid and not no_ask_valid:
            book_missing_reasons.append("no_side_missing")
        if best_bid is None or best_ask is None:
            book_missing_reasons.append("missing_bid_ask")
        elif best_bid <= 0.0 or best_ask <= 0.0:
            book_missing_reasons.append("non_positive_bid_ask")
        elif not bid_ask_consistent:
            book_missing_reasons.append("inverted_bid_ask")
        if not normalized_consistent:
            book_missing_reasons.append("normalized_inconsistent")
        if not valid_spread_bucket:
            book_missing_reasons.append("spread_bucket_not_allowed")
        if not book_valid and not book_missing_reasons:
            book_missing_reasons.append("insufficient_quote_detail")

        selected_price_candidate = self.to_float(
            quote_diag.get("selected_price_dollars", quote_diag.get("selected_price")),
            None,
        )
        if selected_price_candidate is None:
            selected_side_candidate = str(quote_diag.get("selected_side") or "").strip().lower() or None
            if selected_side_candidate == "yes":
                selected_price_candidate = yes_ask if yes_ask is not None else yes_bid
            elif selected_side_candidate == "no":
                selected_price_candidate = no_ask if no_ask is not None else no_bid
            else:
                selected_price_candidate = yes_ask if yes_ask is not None else (no_ask if no_ask is not None else (yes_bid if yes_bid is not None else no_bid))
        price_bounds_pass = bool(selected_price_candidate is not None and KALSHI_CONTRACT_MIN_PRICE <= selected_price_candidate <= KALSHI_CONTRACT_MAX_PRICE)
        topbook_depth_exists = bool(
            self.to_float(quote_diag.get("yes_top_size"), 0.0) > 0.0
            or self.to_float(quote_diag.get("no_top_size"), 0.0) > 0.0
            or self.to_float(quote_diag.get("yes_bid"), 0.0) > 0.0
            or self.to_float(quote_diag.get("no_bid"), 0.0) > 0.0
            or self.to_float(quote_diag.get("yes_ask"), 0.0) > 0.0
            or self.to_float(quote_diag.get("no_ask"), 0.0) > 0.0
            or self.to_float(canonical_source.get("yes_bid_cents"), 0.0) > 0.0
            or self.to_float(canonical_source.get("no_bid_cents"), 0.0) > 0.0
            or self.to_float(canonical_source.get("yes_ask_cents"), 0.0) > 0.0
            or self.to_float(canonical_source.get("no_ask_cents"), 0.0) > 0.0
            or bool(quote_diag.get("topbook_snapshot_present"))
            or bool(quote_diag.get("normalized_orderbook_present"))
        )
        edge_after_cost_value = self.to_float(quote_diag.get("edge_after_cost"), self.to_float(quote_diag.get("final_edge"), self.to_float(quote_diag.get("sports_edge_after_cost"), 0.0)))
        liquidity_depth_value = self.to_float(quote_diag.get("liquidity_depth"), self.to_float(quote_diag.get("liquidity"), 0.0))
        if liquidity_depth_value <= 0.0 and topbook_depth_exists:
            liquidity_depth_value = max(1.0, self.to_float(quote_diag.get("yes_top_size"), 0.0) + self.to_float(quote_diag.get("no_top_size"), 0.0))
        aggression_profile = _normalize_aion_aggression_profile(AION_AGGRESSION_PROFILE)
        aggression_settings = _aion_aggression_profile_settings(aggression_profile, family=family, spread_bucket=spread_bucket, context=source)
        freshness_seconds = self.to_float(quote_diag.get("stale_seconds"), self.to_float(quote_diag.get("cache_age_seconds"), None))
        fresh_enough = bool(freshness_seconds is None or freshness_seconds <= 900.0)
        selected_side_has_price = bool(price_bounds_pass and selected_price_candidate is not None)
        selected_side_has_liquidity = bool(
            topbook_depth_exists
            or liquidity_depth_value > 0.0
            or self.to_float(quote_diag.get("yes_top_size"), 0.0) > 0.0
            or self.to_float(quote_diag.get("no_top_size"), 0.0) > 0.0
        )
        depth_available = bool(topbook_depth_exists or selected_side_has_liquidity)
        book_usable = bool(book_valid or topbook_depth_exists or selected_side_has_price or selected_side_has_liquidity)
        opportunistic_edge_floor = max(self.to_float(aggression_settings.get("effective_edge_threshold"), 0.001), 0.0015)
        extreme_edge_floor = max(opportunistic_edge_floor * 1.5, 0.0025)
        if not book_valid and not any(book_missing_reasons):
            unsafe_price_status = "both_sides_unexecutable"
            unsafe_resolution_reason = "missing_quote_book"
        elif not price_bounds_pass:
            unsafe_price_status = "unexecutable_price"
            unsafe_resolution_reason = "selected_price_out_of_bounds"
        elif book_valid and spread_bucket in {"ultra_tight", "tight", "wide_but_possible"} and normalized_consistent:
            unsafe_price_status = "safe"
            unsafe_resolution_reason = "valid_structurally_consistent_book"
        elif book_usable and spread_bucket in {"unsafe", "extreme_wide"}:
            edge_floor = extreme_edge_floor if spread_bucket == "extreme_wide" else opportunistic_edge_floor
            opportunistic_wide_spread_ok = bool(
                aggression_profile in {"opportunistic", "beast"}
                and price_bounds_pass
                and selected_side_has_price
                and fresh_enough
                and edge_after_cost_value >= edge_floor
                and (normalized_consistent or book_valid or topbook_depth_exists)
            )
            if opportunistic_wide_spread_ok:
                unsafe_price_status = "caution_wide_spread"
                unsafe_resolution_reason = "wide_spread_but_executable"
                spread_bucket = "wide_but_possible"
            else:
                unsafe_price_status = "unsafe_spread"
                unsafe_resolution_reason = "spread_bucket_not_allowed" if spread_bucket != "extreme_wide" else "extreme_wide_edge_weak"
        elif book_usable:
            unsafe_price_status = "caution_wide_spread" if price_bounds_pass and selected_side_has_price and edge_after_cost_value >= opportunistic_edge_floor else "unsafe_spread"
            unsafe_resolution_reason = "partial_quote_but_executable" if unsafe_price_status == "caution_wide_spread" else "spread_bucket_not_allowed"
        elif yes_bid_valid or yes_ask_valid or no_bid_valid or no_ask_valid:
            unsafe_price_status = "unexecutable_price"
            unsafe_resolution_reason = "partial_quote_book"
        else:
            unsafe_price_status = "both_sides_unexecutable"
            unsafe_resolution_reason = "missing_quote_book"

        beast_spread_override_applied = bool(
            aggression_profile == "beast"
            and canonical_spread_classification == "AGGRESSIVE_BUT_TRADEABLE"
            and price_bounds_pass
            and edge_after_cost_value > 0.0
            and (book_valid or normalized_consistent or topbook_depth_exists or selected_side_has_price)
        )
        if beast_spread_override_applied and unsafe_price_status in {"unsafe_spread", "unsafe"}:
            unsafe_price_status = "caution_wide_spread"
            unsafe_resolution_reason = "beast_mode_wide_spread_allowed"
            if spread_bucket == "unsafe":
                spread_bucket = "wide_but_possible"
        thin_book_override_applied = bool(
            aggression_profile == "beast"
            and canonical_spread_classification == "AGGRESSIVE_BUT_TRADEABLE"
            and selected_side_has_price
            and edge_after_cost_value > 0.0
            and (book_valid or topbook_depth_exists or selected_side_has_liquidity or normalized_consistent or fresh_enough)
            and unsafe_price_status not in {"unsafe_spread", "unexecutable_price", "both_sides_unexecutable"}
        )
        if thin_book_override_applied:
            unsafe_price_status = "caution_wide_spread"
            unsafe_resolution_reason = "thin_book_beast_allowed"

        spread_severity = "catastrophic" if unsafe_price_status in {"unsafe_spread", "unexecutable_price", "both_sides_unexecutable"} else "survivable"
        spread_is_catastrophic = bool(spread_severity == "catastrophic" and not beast_spread_override_applied)
        spread_is_survivable = bool(not spread_is_catastrophic)
        final_submit_allowed_by_realm_vv = bool(
            price_bounds_pass
            and edge_after_cost_value > 0.0
            and quote_diag.get("quote_ready", True)
            and (not spread_is_catastrophic or thin_book_override_applied)
        )
        payload = {
            "ticker": ticker or None,
            "family": family,
            "best_bid": round(best_bid, 4) if best_bid is not None else None,
            "best_ask": round(best_ask, 4) if best_ask is not None else None,
            "midpoint": round(midpoint, 4) if midpoint is not None else None,
            "spread": round(spread, 4) if spread is not None else None,
            "raw_yes_price": round(raw_yes_price, 4) if raw_yes_price is not None else None,
            "raw_no_price": round(raw_no_price, 4) if raw_no_price is not None else None,
            "normalized_yes_price": round(normalized_yes_price, 4) if normalized_yes_price is not None else None,
            "normalized_no_price": round(normalized_no_price, 4) if normalized_no_price is not None else None,
            "book_valid": bool(book_valid),
            "book_missing_reason": ",".join(dict.fromkeys(book_missing_reasons)) or None,
            "selected_side_has_price": bool(selected_side_has_price),
            "selected_side_has_liquidity": bool(selected_side_has_liquidity),
            "depth_available": bool(depth_available),
            "derived_price_used": bool(quote_diag.get("derived_price_used") or quote_diag.get("derived_price_source") not in (None, "", "unknown")),
            "derived_price_source": str(quote_diag.get("derived_price_source") or "unknown").strip().lower() or "unknown",
            "thin_book_override_applied": bool(thin_book_override_applied),
            "unsafe_price_status": unsafe_price_status,
            "unsafe_resolution_reason": unsafe_resolution_reason,
            "spread_classification": canonical_spread_classification,
            "spread_severity": spread_severity,
            "spread_is_catastrophic": bool(spread_is_catastrophic),
            "spread_is_survivable": bool(spread_is_survivable),
            "beast_spread_override_applied": bool(beast_spread_override_applied),
            "final_submit_allowed_by_realm_vv": bool(final_submit_allowed_by_realm_vv),
            "source": source,
        }
        print("[AION-UNSAFE-PRICE-DETAIL] " + json.dumps(payload, sort_keys=True, default=str))
        return payload

    def _realm_vv_selection_priority(self, market, q):
        market = market if isinstance(market, dict) else {}
        ticker = str(getattr(q, "ticker", "") or market.get("ticker", "") or "").strip()
        gate_record = self._get_phase55_live_execution_gate_record(ticker, stage="canary_selection") if ticker else {}
        if not self._realm_vv_record_has_meaningful_data(gate_record):
            return False, 0.0, gate_record
        candidate_source = str(gate_record.get("candidate_source") or "").strip().lower()
        decision = str(gate_record.get("decision") or "").strip().upper()
        entry_ready = bool(gate_record.get("entry_ready") is True or gate_record.get("entry_timing_pass") is True or gate_record.get("normalized_ready") is True)
        final_submit_allowed = bool(
            gate_record.get("final_submit_allowed_by_realm_vv")
            if gate_record.get("final_submit_allowed_by_realm_vv") is not None
            else gate_record.get("realm_vv_final_submit_allowed_by_realm_vv")
        )
        quote_ready = bool(gate_record.get("quote_ready") is not False)
        price = self.to_float(getattr(q, "yes_ask", None), self.to_float(gate_record.get("selected_price_dollars"), None))
        price_bounds_pass = bool(price is not None and 0.0 < price < 1.0)
        allowed = bool(
            candidate_source == "realm_vv_entry_engine"
            and decision in {"BUY", "LIVE_PROMOTION"}
            and entry_ready
            and final_submit_allowed
            and quote_ready
            and price_bounds_pass
        )
        if not allowed:
            return False, 0.0, gate_record
        priority_boost = 20.0
        if gate_record.get("beast_spread_override_applied") is True:
            priority_boost += 5.0
        if gate_record.get("spread_classification") in {"AGGRESSIVE_BUT_TRADEABLE", "CAUTION_WIDE_SPREAD"}:
            priority_boost += 5.0
        return True, priority_boost, gate_record

    def _score_live_ticker_candidate(self, q: Quote, market=None):
        market = market if isinstance(market, dict) else {}
        spread = q.yes_ask - q.yes_bid
        mid_price = q.yes_ask
        if q.yes_bid > 0:
            mid_price = (q.yes_bid + q.yes_ask) / 2
        score = 0.0
        score += max(0.0, MAX_ENTRY_SPREAD - spread) * 40
        score += min(q.liquidity, 500) / 25
        score += min(q.volume, 500) / 40
        if 0.68 <= q.yes_ask <= 0.93 and 0 <= spread <= 0.045:
            score += 10.0
        if q.volume > SMART_ENTRY_PRIORITY_VOLUME_THRESHOLD and 0 <= spread <= SMART_ENTRY_PRIORITY_TIGHT_SPREAD:
            score += 8.0
            if 0.68 <= q.yes_ask <= 0.93:
                score += 6.0
        realm_vv_priority, realm_vv_priority_boost, _realm_vv_gate = self._realm_vv_selection_priority(market, q)
        if realm_vv_priority:
            score += realm_vv_priority_boost
        score += max(0.0, 0.25 - abs(mid_price - 0.5)) * 8
        score += max(0.0, 24 - len(q.ticker)) / 24
        return round(score, 4)

    def _should_adaptive_allow_momentum_warning(self, ticker, yes_ask=None, spread=None, payload=None):
        ticker = str(ticker or "").strip()
        gate_record = self._get_phase55_live_execution_gate_record(ticker, stage="adaptive_momentum")
        payload_action = str((payload or {}).get("action") or "").strip().lower() if isinstance(payload, dict) else ""
        decision = str(gate_record.get("decision") or "").strip().upper()
        buy_intent = bool(decision == "BUY" or payload_action == "buy")
        phase55_status = str(gate_record.get("phase55_status") or "").strip()
        entry_timing_pass = gate_record.get("entry_timing_pass") is True
        price_valid = yes_ask is not None and yes_ask > 0
        spread_valid = spread is not None and spread <= 0.03
        adaptive_allow = bool(
            ticker
            and buy_intent
            and price_valid
            and spread_valid
        )
        why = []
        if not ticker:
            why.append("missing_ticker")
        if not buy_intent:
            why.append("decision_not_buy")
        if not price_valid:
            why.append("invalid_price")
        if not spread_valid:
            why.append("spread_above_0.03")
        return adaptive_allow, {
            "decision": decision,
            "buy_intent": buy_intent,
            "phase55_status": phase55_status,
            "entry_timing_pass": entry_timing_pass,
            "price_valid": price_valid,
            "spread_valid": spread_valid,
            "why": ",".join(why) if why else "eligible",
        }

    def _evaluate_mlb_total_entry_confirmation(self, ticker, recent_prices, recent_delta, spread, adaptive_allow=False):
        recent_prices = [float(price) for price in (recent_prices or []) if price is not None]
        if spread is None or spread > 0.03:
            return False, "spread_not_tight_enough"
        if len(recent_prices) < 3:
            return False, "insufficient_recent_price_history"
        recent_range = max(recent_prices) - min(recent_prices)
        last_step_delta = recent_prices[-1] - recent_prices[-2]
        reversing = recent_prices[-1] < recent_prices[-2]
        if recent_delta is None or recent_delta < MLB_TOTAL_MIN_MOMENTUM_DELTA:
            return False, "momentum_too_weak"
        if recent_range < MLB_TOTAL_MIN_MOMENTUM_RANGE:
            return False, "price_action_flat"
        if last_step_delta < MLB_TOTAL_MIN_LAST_STEP_DELTA:
            return False, "last_step_not_improving"
        if reversing:
            return False, "recent_reversal_detected"
        if adaptive_allow and last_step_delta <= 0:
            return False, "adaptive_allow_without_stronger_confirmation"
        return True, "confirmed"

    def _evaluate_smart_entry_gate(self, market, q, payload=None):
        ticker = getattr(q, "ticker", "") or str((market or {}).get("ticker", "") or "").strip()
        family = self.get_market_family(market or {"ticker": ticker}) if ticker else "UNKNOWN"
        payload = payload if isinstance(payload, dict) else {}
        def _q_get(obj, *names, default=None):
            if obj is None:
                return default
            for name in names:
                if isinstance(obj, dict):
                    value = obj.get(name)
                else:
                    value = getattr(obj, name, None)
                if value is not None:
                    return value
            return default
        price_source_fields_checked = []
        yes_bid = self.normalize_contract_price(_q_get(q, "yes_bid", default=0.0) or 0.0, ticker=ticker, source="smart_entry.yes_bid")
        yes_ask = self.normalize_contract_price(_q_get(q, "yes_ask", default=0.0) or 0.0, ticker=ticker, source="smart_entry.yes_ask")
        no_bid = self.normalize_contract_price(_q_get(q, "no_bid", default=0.0) or 0.0, ticker=ticker, source="smart_entry.no_bid")
        no_ask = self.normalize_contract_price(_q_get(q, "no_ask", default=0.0) or 0.0, ticker=ticker, source="smart_entry.no_ask")
        selected_side = str(
            _q_get(q, "selected_side")
            or _q_get(q, "side")
            or payload.get("selected_side")
            or ""
        ).strip().lower() or None
        raw_selected_price = _q_get(q, "selected_price")
        raw_selected_price_dollars = _q_get(q, "selected_price_dollars")
        raw_selected_price_cents = _q_get(q, "selected_price_cents")
        payload_selected_price = payload.get("selected_price")
        payload_selected_price_dollars = payload.get("selected_price_dollars")
        payload_selected_price_cents = payload.get("selected_price_cents")
        raw_price_candidate = (
            raw_selected_price
            if raw_selected_price is not None
            else raw_selected_price_dollars
            if raw_selected_price_dollars is not None
            else payload_selected_price
            if payload_selected_price is not None
            else payload_selected_price_dollars
            if payload_selected_price_dollars is not None
            else yes_ask
            if selected_side == "yes"
            else no_ask
            if selected_side == "no"
            else yes_ask
        )
        normalized_price = self.normalize_contract_price(raw_price_candidate, ticker=ticker, source="smart_entry.selected_price_candidate")
        selected_price_value = self.to_float(
            raw_selected_price_dollars if raw_selected_price_dollars is not None else raw_selected_price,
            self.to_float(payload_selected_price_dollars if payload_selected_price_dollars is not None else payload_selected_price, normalized_price),
        )
        selected_price_cents = raw_selected_price_cents if raw_selected_price_cents is not None else payload_selected_price_cents
        try:
            if selected_price_cents is not None and selected_price_cents != "":
                selected_price_cents = int(round(float(selected_price_cents)))
        except (TypeError, ValueError):
            selected_price_cents = None
        evaluated_price = normalized_price if normalized_price is not None else yes_ask if selected_side == "yes" else no_ask if selected_side == "no" else yes_ask
        min_price_bound = KALSHI_CONTRACT_MIN_PRICE
        max_price_bound = KALSHI_CONTRACT_MAX_PRICE
        price_bounds_decision = self._aion_price_bounds_decision(
            selected_price=selected_price_value,
            selected_price_cents=selected_price_cents,
            yes_ask=yes_ask,
            yes_bid=yes_bid,
            no_ask=no_ask,
            no_bid=no_bid,
            min_price=min_price_bound,
            max_price=max_price_bound,
        )
        spread_context = self._resolve_aion_canonical_spread_context(
            market=market,
            q=q,
            payload=payload,
            quote_diag={},
            selected_side=selected_side,
            source_label="smart_entry.spread",
        )
        spread = self.to_float(spread_context.get("spread"), None)
        spread_cents = spread_context.get("spread_cents")
        spread_source = spread_context.get("spread_source")
        spread_reason = spread_context.get("spread_reason")
        spread_missing_fields = list(spread_context.get("spread_missing_fields") or [])
        spread_source_fields_checked = list(spread_context.get("source_fields_checked") or [])
        self._emit_aion_price_bounds_source(
            caller="smart_entry_gate",
            price_bounds_decision=price_bounds_decision,
            selected_price=selected_price_value,
            selected_price_cents=selected_price_cents,
            ticker=ticker,
            family=family,
            source_of_truth="selected_price_cents" if selected_price_cents is not None else "selected_price_normalized",
            rejection_origin=price_bounds_decision.get("block_reason"),
        )
        spread_trace = {
            "ticker": ticker or None,
            "family": family,
            "stage": "smart_entry_gate",
            "selected_side": selected_side,
            "yes_ask": yes_ask,
            "yes_bid": yes_bid,
            "no_ask": no_ask,
            "no_bid": no_bid,
            "spread": spread,
            "spread_cents": spread_cents,
            "spread_source": spread_source,
            "spread_reason": spread_reason,
            "spread_missing_fields": spread_missing_fields,
            "source_fields_checked": sorted(set(price_source_fields_checked + spread_source_fields_checked)),
        }
        print("[AION-SPREAD-EVAL] " + json.dumps(spread_trace, sort_keys=True, default=str))
        if spread_source and spread_source != "yes_bid_yes_ask":
            print("[AION-SPREAD-DERIVED] " + json.dumps(spread_trace, sort_keys=True, default=str))
        edge = "bad"
        reason = "missing_yes_top_book"
        momentum_ok = True
        recent_delta = None
        high_prob_ok = False
        adaptive_allow = False
        recent_prices = []
        session_adjustment = self._get_live_session_entry_adjustment(adaptive_entry=False, borderline=False)
        price_source_fields_checked = [
            "q.selected_price",
            "q.selected_price_dollars",
            "q.selected_price_cents",
            "q.selected_side",
            "q.side",
            "q.yes_ask",
            "q.no_ask",
            "q.yes_bid",
            "q.no_bid",
            "payload.selected_price",
            "payload.selected_price_dollars",
            "payload.selected_price_cents",
            "payload.yes_price",
            "payload.no_price",
        ]
        print(
            "[AION-PRICE-RANGE-EVAL] "
            + json.dumps(
                {
                    "ticker": ticker or None,
                    "family": family,
                    "selected_side": selected_side,
                    "raw_price": raw_price_candidate,
                    "normalized_price": normalized_price,
                    "evaluated_price": evaluated_price,
                    "min_bound": min_price_bound,
                    "max_bound": max_price_bound,
                    "selected_price": selected_price_value,
                    "selected_price_cents": selected_price_cents,
                    "yes_ask": yes_ask,
                    "yes_bid": yes_bid,
                    "no_ask": no_ask,
                    "no_bid": no_bid,
                    "source_fields_checked": price_source_fields_checked,
                },
                sort_keys=True,
                default=str,
            ),
            flush=True,
        )
        if evaluated_price is None or evaluated_price <= 0 or evaluated_price < min_price_bound or evaluated_price > max_price_bound:
            allowed = False
            reason = "price_out_of_range"
            try:
                reject_key = (
                    ticker,
                    str(raw_price_candidate),
                    str(yes_ask),
                    str(no_ask),
                    str(payload_selected_price),
                )
                reject_seen = getattr(self, "_aion_price_range_real_reject_seen_ts", {})
                now_ts = time.time()
                last_seen_ts = float(reject_seen.get(reject_key, 0.0) or 0.0) if isinstance(reject_seen, dict) else 0.0
                if now_ts - last_seen_ts >= 60.0:
                    if not isinstance(reject_seen, dict):
                        reject_seen = {}
                    reject_seen[reject_key] = now_ts
                    self._aion_price_range_real_reject_seen_ts = reject_seen
                    print(
                        "[AION-PRICE-RANGE-REAL-REJECT] "
                        + json.dumps(
                            {
                                "ticker": ticker or None,
                                "family": family,
                                "reason": reason,
                                "selected_side": selected_side,
                                "raw_price": raw_price_candidate,
                                "normalized_price": normalized_price,
                                "evaluated_price": evaluated_price,
                                "min_bound": min_price_bound,
                                "max_bound": max_price_bound,
                                "selected_price": selected_price_value,
                                "selected_price_cents": selected_price_cents,
                                "yes_ask": yes_ask,
                                "yes_bid": yes_bid,
                                "no_ask": no_ask,
                                "no_bid": no_bid,
                                "payload_selected_price": payload_selected_price,
                                "payload_selected_price_dollars": payload_selected_price_dollars,
                                "payload_selected_price_cents": payload_selected_price_cents,
                                "payload_selected_side": payload.get("selected_side"),
                                "source_fields_checked": price_source_fields_checked,
                            },
                            sort_keys=True,
                            default=str,
                        ),
                        flush=True,
                    )
            except Exception:
                pass
        elif spread is None or spread < 0:
            allowed = False
            reason = "missing_spread"
            reject_ts = time.time()
            print("[AION-SPREAD-REAL-REJECT] " + json.dumps(spread_trace, sort_keys=True, default=str))
            reject_ticker = ticker or None
            if reject_ticker:
                cooldown_until = reject_ts + float(AION_MISSING_SPREAD_TICKER_COOLDOWN_SECONDS)
                current_cooldown_until = float(self.market_cooldowns.get(reject_ticker, 0.0) or 0.0)
                if cooldown_until > current_cooldown_until:
                    self.market_cooldowns[reject_ticker] = cooldown_until
                print(
                    "[AION-MISSING-SPREAD-TICKER-COOLDOWN] "
                    + json.dumps(
                        {
                            "ticker": reject_ticker,
                            "family": family,
                            "reason": reason,
                            "cooldown_seconds": int(AION_MISSING_SPREAD_TICKER_COOLDOWN_SECONDS),
                            "cooldown_until": round(cooldown_until, 3),
                            "source_fields_checked": sorted(set(price_source_fields_checked + spread_source_fields_checked)),
                        },
                        sort_keys=True,
                        default=str,
                    )
                )
                print(
                    "[AION-SCAN-CONTINUE-AFTER-SPREAD-REJECT] "
                    + json.dumps(
                        {
                            "ticker": reject_ticker,
                            "family": family,
                            "reason": reason,
                            "next_action": "continue_scan",
                            "cooldown_applied": True,
                        },
                        sort_keys=True,
                        default=str,
                    )
                )
            self._record_missing_spread_family_reject(family, ticker, reason, now_ts=reject_ts)
        else:
            high_prob_spread_limit = 0.045
            if self._is_sports_market_or_family(family):
                adaptive_spread_context = self._get_sports_adaptive_spread_threshold(
                    market or {"ticker": ticker},
                    spread=spread,
                    context="smart_entry_gate",
                )
                high_prob_spread_limit = max(
                    high_prob_spread_limit,
                    self.to_float(adaptive_spread_context.get("adaptive_threshold"), high_prob_spread_limit),
                )
            high_prob_ok = bool(spread <= high_prob_spread_limit)
            timing_history_key = self._build_phase55_timing_history_key(market or {"ticker": ticker}, q, family=family)
            rolling_history = list(self.phase55_rolling_price_history.get(str(timing_history_key or "").strip(), []))
            recent_prices = [float(price) for price in rolling_history[-4:] if price is not None]
            if len(recent_prices) >= 2:
                recent_delta = recent_prices[-1] - recent_prices[0]
                momentum_ok = recent_delta >= 0
            allowed = bool(high_prob_ok and momentum_ok)
            if allowed:
                edge = "good"
                reason = "junk_bond_neutral_momentum" if recent_delta is None else "junk_bond"
            elif not high_prob_ok:
                reason = "spread_too_wide"
            else:
                adaptive_allow, adaptive_details = self._should_adaptive_allow_momentum_warning(
                    ticker,
                    yes_ask=yes_ask,
                    spread=spread,
                    payload=payload,
                )
                if adaptive_allow:
                    borderline_adaptive = bool(yes_ask >= 0.85 or (spread is not None and spread >= 0.025) or recent_delta is None)
                    session_adjustment = self._get_live_session_entry_adjustment(
                        adaptive_entry=True,
                        borderline=borderline_adaptive,
                    )
                    if session_adjustment.get("adaptive_block"):
                        adaptive_allow = False
                        allowed = False
                        reason = "session_mode_requires_stronger_confirmation"
                    else:
                        allowed = True
                        edge = "good"
                        reason = "momentum_warning"
                        print(
                            f"[LIVE-EXECUTION-MOMENTUM-WARN] ticker={ticker} "
                            f"adaptive_allow=yes original_reason=momentum_not_stable "
                            f"price={yes_ask} spread={spread}"
                        )
                else:
                    reason = "momentum_not_stable"
                    now_ts = time.time()
                    last_log_ts = float(self.live_momentum_hard_block_log_last_seen.get(ticker, 0.0) or 0.0)
                    if (now_ts - last_log_ts) >= 30.0:
                        print(
                            f"[LIVE-EXECUTION-MOMENTUM-HARD-BLOCK] ticker={ticker} "
                            f"reason=momentum_not_stable why={adaptive_details.get('why')}"
                        )
                        self.live_momentum_hard_block_log_last_seen[ticker] = now_ts
        if family == "KXMLBTOTAL" and (allowed or adaptive_allow):
            mlb_confirm_ok, mlb_confirm_reason = self._evaluate_mlb_total_entry_confirmation(
                ticker,
                recent_prices=recent_prices,
                recent_delta=recent_delta,
                spread=spread,
                adaptive_allow=adaptive_allow,
            )
            if mlb_confirm_ok:
                print(
                    f"[LIVE-MLB-ENTRY-CONFIRM-PASS] ticker={ticker} spread={spread} "
                    f"delta={recent_delta} adaptive_allow={'yes' if adaptive_allow else 'no'}"
                )
            else:
                print(
                    f"[LIVE-MLB-ENTRY-CONFIRM-REJECT] ticker={ticker} spread={spread} "
                    f"delta={recent_delta} adaptive_allow={'yes' if adaptive_allow else 'no'} reason={mlb_confirm_reason}"
                )
                allowed = False
                adaptive_allow = False
                edge = "bad"
                reason = mlb_confirm_reason
        status = "adaptive_allowed" if adaptive_allow else ("accepted" if allowed else "rejected")
        momentum_status = "passed" if momentum_ok else "blocked"
        print(f"[MOMENTUM-CHECK] ticker={ticker} status={momentum_status} delta={recent_delta}")
        print(f"[SMART-ENTRY] ticker={ticker} price={yes_ask} spread={spread} edge={edge}")
        print(f"[HIGH-PROB-ENTRY] ticker={ticker} price={yes_ask} spread={spread} status={status} reason={reason}")
        print(f"[EDGE-ENTRY] ticker={ticker} price={yes_ask} spread={spread} status={status} reason={reason}")
        return allowed, reason, {
            "ticker": ticker,
            "family": family,
            "price": yes_ask,
            "edge": edge,
            "momentum_ok": momentum_ok,
            "recent_delta": recent_delta,
            "spread": spread,
            "high_prob_ok": high_prob_ok,
            "high_prob_spread_limit": high_prob_spread_limit if spread is not None else None,
            "adaptive_allow": adaptive_allow,
            "raw_price": raw_price_candidate,
            "normalized_price": normalized_price,
            "evaluated_price": evaluated_price,
            "min_bound": min_price_bound,
            "max_bound": max_price_bound,
            "selected_price": selected_price_value,
            "selected_price_cents": selected_price_cents,
            "spread": spread,
            "spread_source": spread_source,
            "spread_missing_fields": spread_missing_fields,
            "yes_ask": yes_ask,
            "yes_bid": yes_bid,
            "no_ask": no_ask,
            "no_bid": no_bid,
            "source_fields_checked": sorted(set(price_source_fields_checked + spread_source_fields_checked)),
        }

    def _is_high_prob_submission_candidate(self, q, market=None):
        ticker = getattr(q, "ticker", "") or str((market or {}).get("ticker", "") or "").strip()
        market = market or {"ticker": ticker}
        family = self.get_market_family(market) if ticker else "UNKNOWN"
        yes_bid = self.normalize_contract_price(getattr(q, "yes_bid", 0.0) or 0.0, ticker=ticker, source="submission_candidate.yes_bid")
        yes_ask = self.normalize_contract_price(getattr(q, "yes_ask", 0.0) or 0.0, ticker=ticker, source="submission_candidate.yes_ask")
        spread = (yes_ask - yes_bid) if yes_ask and yes_bid else None
        recent_delta = None
        momentum_ok = True
        if yes_ask is None or yes_ask < KALSHI_CONTRACT_MIN_PRICE or yes_ask > KALSHI_CONTRACT_MAX_PRICE or spread is None or spread < 0 or spread > 0.045:
            return False, {"ticker": ticker, "family": family, "yes_ask": yes_ask, "spread": spread, "recent_delta": recent_delta}
        timing_history_key = self._build_phase55_timing_history_key(market, q, family=family)
        rolling_history = list(self.phase55_rolling_price_history.get(str(timing_history_key or "").strip(), []))
        recent_prices = [float(price) for price in rolling_history[-4:] if price is not None]
        if len(recent_prices) >= 2:
            recent_delta = recent_prices[-1] - recent_prices[0]
            momentum_ok = recent_delta >= 0
        return bool(momentum_ok), {"ticker": ticker, "family": family, "yes_ask": yes_ask, "spread": spread, "recent_delta": recent_delta}

    def _classify_entry_block_reason(self, reason):
        reason = str(reason or "").strip().lower()
        if (
            "phase55" in reason
            or reason in {
                "insufficient_data",
                "trigger_wait",
                "no_crossover",
                "pullback_wait",
                "immediate_entry_block",
            }
        ):
            return "phase55"
        if "negative_edge" in reason or "top_book" in reason:
            return "negative_edge"
        if "stale_signal" in reason or "direction_changed" in reason or "spread_deteriorated" in reason:
            return "stale"
        if "duplicate" in reason or "sim_position_open" in reason or "live_position_open_same_ticker" in reason:
            return "duplicate"
        return "other"

    def _record_live_family_performance(self, family, realized_value):
        family = self._normalize_family_for_profit_memory(family)
        stats = dict(self.live_family_perf_stats.get(family, {}) or {})
        stats["trades"] = int(stats.get("trades", 0) or 0) + 1
        stats["wins"] = int(stats.get("wins", 0) or 0)
        stats["losses"] = int(stats.get("losses", 0) or 0)
        stats["loss_streak"] = int(stats.get("loss_streak", 0) or 0)
        stats["pnl"] = round(float(stats.get("pnl", 0.0) or 0.0) + float(realized_value or 0.0), 4)
        if realized_value > 0:
            stats["wins"] += 1
            stats["loss_streak"] = 0
        elif realized_value < 0:
            stats["losses"] += 1
            stats["loss_streak"] += 1
        self.live_family_perf_stats[family] = stats
        self.live_realized_pnl_by_family_today[family] = stats["pnl"]
        self.live_recent_family_pnl_events.append({
            "ts": time.time(),
            "family": family,
            "pnl": float(realized_value or 0.0),
        })
        self.live_recent_family_pnl_events = list(self.live_recent_family_pnl_events or [])[-200:]
        self.family_profit_memory_cache = {"loaded_at": 0.0, "stats": {}}
        print(
            f"[LIVE-FAMILY-PERFORMANCE-UPDATE] family={family} trades={stats.get('trades')} "
            f"wins={stats.get('wins')} losses={stats.get('losses')} "
            f"pnl={stats.get('pnl')} loss_streak={stats.get('loss_streak')}"
        )

    def _normalize_family_for_profit_memory(self, family=None, ticker=None, market=None, q=None):
        family_value = str(family or "").strip().upper()
        if family_value in {"NONE", "NULL", "UNKNOWN"}:
            family_value = ""
        if not family_value and isinstance(market, dict):
            family_value = str(market.get("family") or market.get("series_ticker") or "").strip().upper()
            if family_value in {"NONE", "NULL", "UNKNOWN"}:
                family_value = ""
        ticker_value = str(ticker or getattr(q, "ticker", None) or "").strip()
        if not ticker_value and isinstance(market, dict):
            ticker_value = str(market.get("ticker") or "").strip()
        if not family_value and ticker_value:
            try:
                family_value = str(self.get_market_family({"ticker": ticker_value}) or "").strip().upper()
            except Exception:
                family_value = ""
        if not family_value and ticker_value:
            family_value = ticker_value.split("-")[0].strip().upper()
        return family_value or "UNKNOWN"

    def _family_profit_memory_rows_from_sqlite(self, limit=None):
        path = str(getattr(self, "seraph_memory_db_path", None) or SERAPH_MEMORY_SQLITE_PATH or "").strip()
        if not path or not os.path.exists(path):
            return []
        limit_value = max(1, int(limit or KALSHI_FAMILY_PROFIT_MEMORY_LOOKBACK or 400))
        try:
            with sqlite3.connect(path, timeout=2) as conn:
                conn.row_factory = sqlite3.Row
                rows = conn.execute(
                    """
                    SELECT timestamp, timestamp_ts, ticker, family, realized_pnl_delta, outcome
                    FROM seraph_trade_memory
                    WHERE COALESCE(family, '') != ''
                       OR COALESCE(ticker, '') != ''
                    ORDER BY id DESC
                    LIMIT ?
                    """,
                    (limit_value,),
                ).fetchall()
            return [dict(row) for row in rows if row]
        except Exception:
            return []

    def _family_profit_memory_rows_from_csv(self, limit=None):
        rows = []
        for row in self._load_trade_history_rows(limit=limit or KALSHI_FAMILY_PROFIT_MEMORY_LOOKBACK):
            if not isinstance(row, dict):
                continue
            rows.append({
                "timestamp": row.get("timestamp") or row.get("time") or row.get("created_at"),
                "timestamp_ts": row.get("timestamp_ts") or row.get("ts"),
                "ticker": row.get("ticker") or row.get("market_ticker"),
                "family": row.get("family") or row.get("series_ticker"),
                "realized_pnl_delta": (
                    row.get("realized_pnl_delta")
                    if row.get("realized_pnl_delta") is not None
                    else row.get("pnl")
                    if row.get("pnl") is not None
                    else row.get("realized_pnl")
                ),
                "outcome": row.get("outcome") or row.get("result"),
            })
        return rows

    def _build_family_profit_memory_stats(self, limit=None):
        limit_value = max(1, int(limit or KALSHI_FAMILY_PROFIT_MEMORY_LOOKBACK or 400))
        rows = self._family_profit_memory_rows_from_sqlite(limit=limit_value)
        rows.extend(self._family_profit_memory_rows_from_csv(limit=limit_value))
        stats_by_family = {}

        def _ensure_stats(family_key):
            return stats_by_family.setdefault(
                family_key,
                {
                    "family": family_key,
                    "trade_count": 0,
                    "wins": 0,
                    "losses": 0,
                    "breakevens": 0,
                    "family_pnl": 0.0,
                    "recent_pnls": [],
                    "latest_ts": 0.0,
                    "source": "history",
                },
            )

        for row in rows:
            if not isinstance(row, dict):
                continue
            family = self._normalize_family_for_profit_memory(row.get("family"), ticker=row.get("ticker"))
            pnl = self.to_float(row.get("realized_pnl_delta"), None)
            outcome = str(row.get("outcome") or "").strip().lower()
            if pnl is None and outcome not in {"win", "loss", "breakeven"}:
                continue
            if pnl is None:
                pnl = 1.0 if outcome == "win" else -1.0 if outcome == "loss" else 0.0
            stats = _ensure_stats(family)
            stats["trade_count"] += 1
            stats["family_pnl"] += float(pnl or 0.0)
            if outcome == "win" or pnl > 0:
                stats["wins"] += 1
            elif outcome == "loss" or pnl < 0:
                stats["losses"] += 1
            else:
                stats["breakevens"] += 1
            if len(stats["recent_pnls"]) < max(1, int(KALSHI_FAMILY_PROFIT_MEMORY_RECENT_WINDOW or 5)):
                stats["recent_pnls"].append(float(pnl or 0.0))
            timestamp_ts = self.to_float(row.get("timestamp_ts"), 0.0) or 0.0
            stats["latest_ts"] = max(float(stats.get("latest_ts", 0.0) or 0.0), timestamp_ts)

        for family, live_stats in (self.live_family_perf_stats or {}).items():
            if not isinstance(live_stats, dict):
                continue
            family_key = self._normalize_family_for_profit_memory(family)
            stats = _ensure_stats(family_key)
            session_trades = int(live_stats.get("trades", 0) or 0)
            session_wins = int(live_stats.get("wins", 0) or 0)
            session_losses = int(live_stats.get("losses", 0) or 0)
            session_pnl = self.to_float(live_stats.get("pnl"), 0.0) or 0.0
            if session_trades > 0:
                stats["trade_count"] += session_trades
                stats["wins"] += session_wins
                stats["losses"] += session_losses
                stats["breakevens"] += max(0, session_trades - session_wins - session_losses)
                stats["family_pnl"] += session_pnl
                stats["source"] = "history+session" if stats.get("source") == "history" else "session"

        for family, stats in list(stats_by_family.items()):
            trade_count = int(stats.get("trade_count", 0) or 0)
            wins = int(stats.get("wins", 0) or 0)
            losses = int(stats.get("losses", 0) or 0)
            family_pnl = round(self.to_float(stats.get("family_pnl"), 0.0) or 0.0, 4)
            recent_pnls = [self.to_float(value, 0.0) or 0.0 for value in list(stats.get("recent_pnls") or [])]
            recent_pnl = sum(recent_pnls)
            win_rate = (wins / trade_count) if trade_count > 0 else None
            if recent_pnl > 0:
                recent_trend = "up"
            elif recent_pnl < 0:
                recent_trend = "down"
            else:
                recent_trend = "flat" if trade_count > 0 else "unknown"
            stats.update({
                "family": family,
                "trade_count": trade_count,
                "wins": wins,
                "losses": losses,
                "family_pnl": family_pnl,
                "win_rate": self._safe_round(win_rate, 4, None),
                "recent_pnl": round(recent_pnl, 4),
                "recent_trend": recent_trend,
            })
        return stats_by_family

    def _get_family_profit_memory_stats(self, family, *, refresh=False):
        family = self._normalize_family_for_profit_memory(family)
        now = time.time()
        cache = self.family_profit_memory_cache if isinstance(getattr(self, "family_profit_memory_cache", None), dict) else {}
        loaded_at = self.to_float(cache.get("loaded_at"), 0.0) or 0.0
        if refresh or not isinstance(cache.get("stats"), dict) or (now - loaded_at) >= max(5.0, KALSHI_FAMILY_PROFIT_MEMORY_CACHE_SECONDS):
            cache = {
                "loaded_at": now,
                "stats": self._build_family_profit_memory_stats(limit=KALSHI_FAMILY_PROFIT_MEMORY_LOOKBACK),
            }
            self.family_profit_memory_cache = cache
        return dict((cache.get("stats") or {}).get(family, {}) or {
            "family": family,
            "trade_count": 0,
            "wins": 0,
            "losses": 0,
            "family_pnl": 0.0,
            "win_rate": None,
            "recent_trend": "unknown",
            "recent_pnl": 0.0,
            "adjustment": 0.0,
        })

    def _get_family_profit_memory_adjustment(self, family, *, log=True, source="ranking"):
        family = self._normalize_family_for_profit_memory(family)
        stats = self._get_family_profit_memory_stats(family)
        trade_count = int(stats.get("trade_count", 0) or 0)
        family_pnl = self.to_float(stats.get("family_pnl"), 0.0) or 0.0
        win_rate = self.to_float(stats.get("win_rate"), None)
        recent_pnl = self.to_float(stats.get("recent_pnl"), 0.0) or 0.0
        recent_trend = str(stats.get("recent_trend") or "unknown").strip().lower() or "unknown"
        min_trades = max(1, int(KALSHI_FAMILY_MIN_TRADES_FOR_PENALTY or 2))
        if not KALSHI_FAMILY_PERF_ENABLED or trade_count < min_trades:
            adjustment = 0.0
        else:
            sample_factor = min(1.0, max(0.0, (trade_count - min_trades + 1) / 8.0))
            avg_pnl = family_pnl / max(trade_count, 1)
            pnl_signal = max(-1.0, min(1.0, avg_pnl * 12.0))
            win_signal = 0.0 if win_rate is None else max(-1.0, min(1.0, (win_rate - 0.5) * 2.0))
            trend_signal = max(-1.0, min(1.0, recent_pnl * 6.0))
            raw_adjustment = ((pnl_signal * 0.55) + (win_signal * 0.30) + (trend_signal * 0.15)) * KALSHI_FAMILY_PROFIT_MEMORY_MAX_RANK_ADJUSTMENT
            adjustment = max(
                -KALSHI_FAMILY_PROFIT_MEMORY_MAX_RANK_ADJUSTMENT,
                min(KALSHI_FAMILY_PROFIT_MEMORY_MAX_RANK_ADJUSTMENT, raw_adjustment * sample_factor),
            )
            if family_pnl < 0 and adjustment > 0:
                adjustment = 0.0
            elif family_pnl > 0 and adjustment < 0:
                adjustment = 0.0
        adjustment = round(float(adjustment or 0.0), 4)
        stats["adjustment"] = adjustment
        if log:
            marker = (
                int(time.time() // 60),
                family,
                round(family_pnl, 4),
                stats.get("win_rate"),
                trade_count,
                recent_trend,
                adjustment,
            )
            if self.family_profit_memory_log_markers.get(family) != marker:
                self.family_profit_memory_log_markers[family] = marker
                print(
                    f"[FAMILY-PROFIT-MEMORY] family={family} family_pnl={round(family_pnl, 4)} "
                    f"win_rate={stats.get('win_rate')} trade_count={trade_count} "
                    f"recent_trend={recent_trend} adjustment={adjustment} source={source}"
                )
        return adjustment

    def _extract_family_from_ranked_candidate(self, item):
        if isinstance(item, dict):
            return self._normalize_family_for_profit_memory(item.get("family"), ticker=item.get("ticker"))
        if isinstance(item, (list, tuple)):
            family = item[3] if len(item) > 3 else None
            q = item[1] if len(item) > 1 else None
            return self._normalize_family_for_profit_memory(family, q=q)
        return "UNKNOWN"

    def _rank_score_for_family_profit_memory(self, item):
        if isinstance(item, dict):
            return self.to_float(item.get("adjusted_score"), self.to_float(item.get("candidate_score"), self.to_float(item.get("quality_score"), 0.0)))
        if isinstance(item, (list, tuple)) and item:
            return self.to_float(item[0], 0.0)
        return 0.0

    def _apply_family_profit_memory_ranking(self, ranked, *, source="ranking"):
        ranked = list(ranked or [])
        if not ranked:
            return ranked
        decorated = []
        for index, item in enumerate(ranked):
            family = self._extract_family_from_ranked_candidate(item)
            adjustment = self._get_family_profit_memory_adjustment(family, log=True, source=source)
            decorated.append((self._rank_score_for_family_profit_memory(item) + adjustment, -index, item))
        decorated.sort(key=lambda entry: (entry[0], entry[1]), reverse=True)
        return [item for _rank_score, _tie_breaker, item in decorated]

    def _normalize_orderbook_imbalance_side(self, side):
        side_value = str(side or "").strip().lower()
        if side_value in {"yes", "y"}:
            return "yes"
        if side_value in {"no", "n"}:
            return "no"
        return None

    def _extract_ticker_from_ranked_candidate(self, item):
        if isinstance(item, dict):
            q = item.get("q") or item.get("quote")
            return str(item.get("ticker") or getattr(q, "ticker", "") or "").strip()
        if isinstance(item, (list, tuple)) and len(item) > 1:
            return str(getattr(item[1], "ticker", "") or "").strip()
        return ""

    def _extract_orderbook_imbalance_context(self, item=None, *, market=None, q=None, spread=None, family=None):
        item = item if item is not None else {}
        market = market if isinstance(market, dict) else {}
        if isinstance(item, dict):
            q = q or item.get("q") or item.get("quote")
            family = family or item.get("family")
            spread = spread if spread is not None else item.get("spread")
            if not market and isinstance(item.get("market"), dict):
                market = item.get("market") or {}
        elif isinstance(item, (list, tuple)):
            q = q or (item[1] if len(item) > 1 else None)
            spread = spread if spread is not None else (item[2] if len(item) > 2 else None)
            family = family or (item[3] if len(item) > 3 else None)

        def _pick(*values):
            for value in values:
                if value is None:
                    continue
                if isinstance(value, str) and not value.strip():
                    continue
                return value
            return None

        def _item_get(key):
            return item.get(key) if isinstance(item, dict) else None

        def _q_get(key):
            return getattr(q, key, None) if q is not None else None

        def _market_get(*keys):
            for key in keys:
                if key in market:
                    value = market.get(key)
                    if value is not None and not (isinstance(value, str) and not value.strip()):
                        return value
            return None

        ticker = str(_pick(_item_get("ticker"), _q_get("ticker"), _market_get("ticker")) or "").strip()
        family = self._normalize_family_for_profit_memory(family, ticker=ticker, market=market, q=q)
        direction_decision = {}
        try:
            direction_decision = (self.live_direction_decisions_by_ticker or {}).get(ticker, {}) or {}
        except Exception:
            direction_decision = {}

        yes_top_size = self.to_float(
            _pick(_item_get("yes_top_size"), _q_get("yes_top_size"), _market_get("yes_top_size")),
            None,
        )
        no_top_size = self.to_float(
            _pick(_item_get("no_top_size"), _q_get("no_top_size"), _market_get("no_top_size")),
            None,
        )
        if (yes_top_size is None or no_top_size is None) and market:
            try:
                liquidity_priority = self.get_market_liquidity_priority(market, q=q)
                yes_top_size = self.to_float(liquidity_priority.get("yes_top_size"), yes_top_size)
                no_top_size = self.to_float(liquidity_priority.get("no_top_size"), no_top_size)
            except Exception:
                pass
        yes_top_size = self.to_float(yes_top_size, 0.0) or 0.0
        no_top_size = self.to_float(no_top_size, 0.0) or 0.0

        yes_bid = self.to_float(_pick(_item_get("yes_bid"), _q_get("yes_bid"), _market_get("yes_bid_dollars", "yes_bid")), None)
        yes_ask = self.to_float(_pick(_item_get("yes_ask"), _q_get("yes_ask"), _market_get("yes_ask_dollars", "yes_ask")), None)
        no_bid = self.to_float(_pick(_item_get("no_bid"), _q_get("no_bid"), _market_get("no_bid_dollars", "no_bid")), None)
        no_ask = self.to_float(_pick(_item_get("no_ask"), _q_get("no_ask"), _market_get("no_ask_dollars", "no_ask")), None)
        spread_value = self.to_float(_pick(spread, _item_get("spread"), _q_get("spread"), _market_get("spread")), None)
        if spread_value is None and yes_bid is not None and yes_ask is not None and yes_bid > 0.0 and yes_ask > 0.0:
            spread_value = max(0.0, yes_ask - yes_bid)

        selected_side = self._normalize_orderbook_imbalance_side(
            _pick(
                _item_get("selected_side"),
                _item_get("side"),
                _q_get("selected_side"),
                _q_get("side"),
                direction_decision.get("selected_side"),
                direction_decision.get("intended_side"),
                _market_get("selected_side", "side"),
            )
        )
        total_size = max(0.0, yes_top_size) + max(0.0, no_top_size)
        imbalance = ((yes_top_size - no_top_size) / total_size) if total_size > 0.0 else 0.0
        pressure_side = "yes" if imbalance > 0.0 else "no" if imbalance < 0.0 else None
        if selected_side is None and abs(imbalance) >= max(0.0, KALSHI_ORDERBOOK_IMBALANCE_NEUTRAL_BAND):
            selected_side = pressure_side

        selected_price = self.to_float(
            _pick(
                _item_get("selected_price"),
                _item_get("selected_price_dollars"),
                _q_get("selected_price"),
                _q_get("selected_price_dollars"),
                direction_decision.get("selected_price"),
                _market_get("selected_price", "selected_price_dollars"),
            ),
            None,
        )
        if selected_price is None and selected_side == "yes":
            selected_price = self.to_float(yes_ask, self.to_float(yes_bid, None))
        elif selected_price is None and selected_side == "no":
            selected_price = self.to_float(no_ask, self.to_float(no_bid, None))

        yes_executable = bool((yes_ask is not None and yes_ask > 0.0) or (yes_bid is not None and yes_bid > 0.0))
        no_executable = bool((no_ask is not None and no_ask > 0.0) or (no_bid is not None and no_bid > 0.0))
        return {
            "ticker": ticker,
            "family": family,
            "side": selected_side or "unknown",
            "pressure_side": pressure_side or "unknown",
            "selected_price": selected_price,
            "yes_bid": yes_bid,
            "yes_ask": yes_ask,
            "no_bid": no_bid,
            "no_ask": no_ask,
            "yes_top_size": yes_top_size,
            "no_top_size": no_top_size,
            "spread": spread_value,
            "imbalance": imbalance,
            "total_size": total_size,
            "yes_executable": yes_executable,
            "no_executable": no_executable,
        }

    def _get_orderbook_imbalance_adjustment(self, item=None, *, market=None, q=None, spread=None, family=None, log=True, source="ranking"):
        context = self._extract_orderbook_imbalance_context(
            item,
            market=market,
            q=q,
            spread=spread,
            family=family,
        )
        side = self._normalize_orderbook_imbalance_side(context.get("side"))
        yes_size = self.to_float(context.get("yes_top_size"), 0.0) or 0.0
        no_size = self.to_float(context.get("no_top_size"), 0.0) or 0.0
        total_size = self.to_float(context.get("total_size"), yes_size + no_size) or 0.0
        imbalance = self.to_float(context.get("imbalance"), 0.0) or 0.0
        neutral_band = max(0.0, min(0.95, KALSHI_ORDERBOOK_IMBALANCE_NEUTRAL_BAND))
        adjustment = 0.0
        if KALSHI_ORDERBOOK_IMBALANCE_ENABLED and total_size >= max(0.0, KALSHI_ORDERBOOK_IMBALANCE_MIN_TOTAL_SIZE):
            if side is None and abs(imbalance) >= neutral_band:
                side = "yes" if imbalance > 0.0 else "no"
            if side in {"yes", "no"} and abs(imbalance) >= neutral_band:
                side_support = imbalance if side == "yes" else -imbalance
                strength = max(0.0, (abs(side_support) - neutral_band) / max(1.0 - neutral_band, 0.01))
                spread_value = self.to_float(context.get("spread"), None)
                if spread_value is None:
                    spread_factor = 1.0
                else:
                    spread_factor = max(0.65, min(1.0, 1.0 - max(0.0, spread_value) / max(MAX_ENTRY_SPREAD * 2.0, 0.01)))
                depth_factor = min(1.0, total_size / max(KALSHI_ORDERBOOK_IMBALANCE_MIN_TOTAL_SIZE * 4.0, 1.0))
                executable = bool(context.get("yes_executable")) if side == "yes" else bool(context.get("no_executable"))
                executable_factor = 1.0 if executable or self.to_float(context.get("selected_price"), 0.0) > 0.0 else 0.5
                if side_support > neutral_band:
                    adjustment = (
                        KALSHI_ORDERBOOK_IMBALANCE_MAX_RANK_ADJUSTMENT
                        * strength
                        * (0.65 + 0.35 * depth_factor)
                        * spread_factor
                        * executable_factor
                    )
                elif side_support < -neutral_band:
                    adjustment = -KALSHI_ORDERBOOK_IMBALANCE_MAX_RANK_PENALTY * strength
        adjustment = round(float(adjustment or 0.0), 4)
        context["side"] = side or context.get("side") or "unknown"
        context["adjustment"] = adjustment
        if log:
            ticker = str(context.get("ticker") or "unknown").strip() or "unknown"
            marker = (
                int(time.time() // 60),
                ticker,
                context.get("side"),
                round(yes_size, 4),
                round(no_size, 4),
                round(imbalance, 4),
                adjustment,
            )
            if self.orderbook_imbalance_log_markers.get(ticker) != marker:
                self.orderbook_imbalance_log_markers[ticker] = marker
                print(
                    f"[ORDERBOOK-IMBALANCE] ticker={ticker} side={context.get('side') or 'unknown'} "
                    f"yes_size={round(yes_size, 4)} no_size={round(no_size, 4)} "
                    f"imbalance={round(imbalance, 4)} adjustment={adjustment}"
                )
        return context

    def _is_btc_volatility_family(self, family=None, *, ticker=None, market=None, q=None):
        ticker_key = str(
            ticker
            or getattr(q, "ticker", "")
            or ((market or {}).get("ticker") if isinstance(market, dict) else "")
            or ""
        ).strip().upper()
        family_key = self._normalize_family_for_profit_memory(
            family,
            ticker=ticker_key,
            market=market if isinstance(market, dict) else None,
            q=q,
        )
        combined = f"{family_key} {ticker_key}"
        return bool(
            "KXBTC" in combined
            or "BTC" in combined
            or "CRYPTO" in combined
            or "ETH" in combined
        )

    def _coerce_btc_volatility_price(self, value):
        try:
            coerced = self._coerce_live_exit_price(value)
            if coerced is not None:
                return coerced
        except Exception:
            pass
        price = self.to_float(value, None)
        if price is None:
            return None
        if 0.0 < price <= 1.0:
            return round(price, 4)
        if 1.0 < price <= 100.0:
            return round(price / 100.0, 4)
        return None

    def _extract_btc_volatility_price_context(self, *, market=None, q=None, selected_side=None):
        market = market if isinstance(market, dict) else {}

        def _pick(*values):
            for value in values:
                if value is None:
                    continue
                if isinstance(value, str) and not value.strip():
                    continue
                return value
            return None

        def _q_get(*names):
            for name in names:
                if q is not None:
                    value = getattr(q, name, None)
                    if value is not None and not (isinstance(value, str) and not value.strip()):
                        return value
            return None

        def _market_get(*names):
            for name in names:
                if name in market:
                    value = market.get(name)
                    if value is not None and not (isinstance(value, str) and not value.strip()):
                        return value
            return None

        side = self._normalize_orderbook_imbalance_side(
            selected_side
            or _q_get("selected_side", "side")
            or _market_get("selected_side", "side")
        )
        yes_bid = self._coerce_btc_volatility_price(_pick(_q_get("yes_bid", "yes_bid_dollars"), _market_get("yes_bid_dollars", "yes_bid")))
        yes_ask = self._coerce_btc_volatility_price(_pick(_q_get("yes_ask", "yes_ask_dollars"), _market_get("yes_ask_dollars", "yes_ask")))
        no_bid = self._coerce_btc_volatility_price(_pick(_q_get("no_bid", "no_bid_dollars"), _market_get("no_bid_dollars", "no_bid")))
        no_ask = self._coerce_btc_volatility_price(_pick(_q_get("no_ask", "no_ask_dollars"), _market_get("no_ask_dollars", "no_ask")))
        selected_price = self._coerce_btc_volatility_price(
            _pick(
                _q_get("selected_price", "selected_price_dollars"),
                _market_get("selected_price", "selected_price_dollars"),
            )
        )
        last_price = self._coerce_btc_volatility_price(
            _pick(
                _q_get("last_price", "last_price_dollars", "price"),
                _market_get("last_price_dollars", "last_price", "price"),
            )
        )
        yes_mid = None
        no_mid = None
        if yes_bid is not None and yes_ask is not None and yes_bid > 0.0 and yes_ask > 0.0:
            yes_mid = round((yes_bid + yes_ask) / 2.0, 4)
        if no_bid is not None and no_ask is not None and no_bid > 0.0 and no_ask > 0.0:
            no_mid = round((no_bid + no_ask) / 2.0, 4)
        if last_price is not None:
            yes_probability = last_price if side != "no" else round(1.0 - last_price, 4)
            source = "last_price"
        elif selected_price is not None and side in {"yes", "no"}:
            yes_probability = selected_price if side == "yes" else round(1.0 - selected_price, 4)
            source = "selected_price"
        elif yes_mid is not None:
            yes_probability = yes_mid
            source = "yes_mid"
        elif no_mid is not None:
            yes_probability = round(1.0 - no_mid, 4)
            source = "no_mid_inverse"
        elif yes_ask is not None:
            yes_probability = yes_ask
            source = "yes_ask"
        elif yes_bid is not None:
            yes_probability = yes_bid
            source = "yes_bid"
        elif no_ask is not None:
            yes_probability = round(1.0 - no_ask, 4)
            source = "no_ask_inverse"
        elif no_bid is not None:
            yes_probability = round(1.0 - no_bid, 4)
            source = "no_bid_inverse"
        else:
            yes_probability = None
            source = "missing"
        if yes_probability is not None:
            yes_probability = round(self._clamp(yes_probability, 0.0, 1.0), 4)
        return {
            "yes_probability": yes_probability,
            "source": source,
            "selected_side": side,
            "selected_price": selected_price,
            "last_price": last_price,
            "yes_bid": yes_bid,
            "yes_ask": yes_ask,
            "no_bid": no_bid,
            "no_ask": no_ask,
            "yes_mid": yes_mid,
            "no_mid": no_mid,
        }

    def _get_btc_volatility_mode(self, *, market=None, q=None, family=None, spread=None, source="ranking", log=True):
        ticker = str(
            getattr(q, "ticker", "")
            or ((market or {}).get("ticker") if isinstance(market, dict) else "")
            or ""
        ).strip()
        family_key = self._normalize_family_for_profit_memory(family, ticker=ticker, market=market if isinstance(market, dict) else None, q=q)
        if not self._is_btc_volatility_family(family_key, ticker=ticker, market=market, q=q):
            return {
                "active": False,
                "direction": "neutral",
                "volatility": 0.0,
                "preferred_side": None,
                "rank_boost": 0.0,
                "score_boost": 0.0,
                "threshold_relaxation": 0.0,
                "spread_relaxation": 0.0,
                "source": source,
            }
        ticker_key = ticker or family_key or "BTC"
        now_ts = time.time()
        price_context = self._extract_btc_volatility_price_context(market=market, q=q)
        price = self.to_float(price_context.get("yes_probability"), None)
        imbalance_context = self._extract_orderbook_imbalance_context(
            None,
            market=market,
            q=q,
            spread=spread,
            family=family_key,
        )
        imbalance = self.to_float(imbalance_context.get("imbalance"), 0.0) or 0.0
        state_store = getattr(self, "btc_volatility_state", None)
        if not isinstance(state_store, dict):
            self.btc_volatility_state = {}
            state_store = self.btc_volatility_state
        state = dict(state_store.get(ticker_key, {}) or {})
        history = list(state.get("history") or [])
        cycle_id = None
        try:
            cycle_id = self._get_phase55_cycle_id()
        except Exception:
            cycle_id = None
        if price is not None:
            last_price = self.to_float(state.get("last_price"), None)
            same_cycle = bool(cycle_id and state.get("last_cycle_id") == cycle_id)
            if not same_cycle or last_price is None or abs(price - last_price) >= 0.0001:
                history.append({"ts": now_ts, "price": price, "source": price_context.get("source")})
            history = [
                item for item in history[-16:]
                if now_ts - self.to_float((item or {}).get("ts"), now_ts) <= 900.0
                and self.to_float((item or {}).get("price"), None) is not None
            ]
            state.update({
                "history": history,
                "last_price": price,
                "last_cycle_id": cycle_id,
                "updated_ts": now_ts,
                "last_source": price_context.get("source"),
            })
            state_store[ticker_key] = state

        delta = 0.0
        step_delta = 0.0
        velocity = 0.0
        step_velocity = 0.0
        if price is not None and len(history) >= 2:
            base = history[0]
            previous = history[-2]
            base_price = self.to_float(base.get("price"), price)
            previous_price = self.to_float(previous.get("price"), price)
            elapsed = max(1.0, now_ts - self.to_float(base.get("ts"), now_ts))
            step_elapsed = max(1.0, now_ts - self.to_float(previous.get("ts"), now_ts))
            delta = round(price - base_price, 6)
            step_delta = round(price - previous_price, 6)
            velocity = round(delta / elapsed, 8)
            step_velocity = round(step_delta / step_elapsed, 8)

        price_trigger = max(0.001, float(BTC_VOLATILITY_PRICE_DELTA_TRIGGER or 0.018))
        velocity_trigger = max(0.00001, float(BTC_VOLATILITY_VELOCITY_TRIGGER or 0.00045))
        imbalance_trigger = max(0.05, min(0.95, float(BTC_VOLATILITY_IMBALANCE_TRIGGER or 0.28)))
        signal_candidates = [
            ("price_delta", delta / price_trigger if price is not None else 0.0),
            ("step_delta", step_delta / max(price_trigger * 0.50, 0.001) if price is not None else 0.0),
            ("velocity", velocity / velocity_trigger if price is not None else 0.0),
            ("step_velocity", step_velocity / velocity_trigger if price is not None else 0.0),
            ("book_pressure", imbalance / imbalance_trigger if imbalance_context.get("total_size", 0.0) else 0.0),
        ]
        signal_name, signal_ratio = max(signal_candidates, key=lambda item: abs(item[1]))
        volatility = round(min(3.0, max(abs(ratio) for _name, ratio in signal_candidates)), 4)
        active = bool(BTC_VOLATILITY_MODE_ENABLED and volatility >= 1.0 and signal_ratio != 0.0)
        direction = "pump" if active and signal_ratio > 0.0 else "crash" if active and signal_ratio < 0.0 else "neutral"
        preferred_side = "yes" if direction == "pump" else "no" if direction == "crash" else None
        rank_boost = round((min(1.0, volatility / 2.0) * float(BTC_VOLATILITY_MAX_RANK_BOOST or 0.0)) if active else 0.0, 4)
        score_boost = round((min(1.0, volatility / 2.0) * float(BTC_VOLATILITY_SCORE_BOOST or 0.0)) if active else 0.0, 4)
        threshold_relaxation = round((min(1.0, volatility / 2.0) * float(BTC_VOLATILITY_THRESHOLD_RELAXATION or 0.0)) if active else 0.0, 4)
        spread_relaxation = round((min(1.0, volatility / 2.0) * float(BTC_VOLATILITY_SPREAD_RELAXATION or 0.0)) if active else 0.0, 4)
        mode = {
            "active": active,
            "direction": direction,
            "volatility": volatility,
            "preferred_side": preferred_side,
            "rank_boost": rank_boost,
            "score_boost": score_boost,
            "threshold_relaxation": threshold_relaxation,
            "spread_relaxation": spread_relaxation,
            "signal": signal_name,
            "signal_ratio": round(signal_ratio, 4),
            "price": price,
            "price_source": price_context.get("source"),
            "delta": round(delta, 6),
            "step_delta": round(step_delta, 6),
            "velocity": round(velocity, 8),
            "step_velocity": round(step_velocity, 8),
            "imbalance": round(imbalance, 4),
            "ticker": ticker_key,
            "family": family_key,
            "source": source,
        }
        if log:
            log_store = getattr(self, "btc_volatility_log_markers", None)
            if not isinstance(log_store, dict):
                self.btc_volatility_log_markers = {}
                log_store = self.btc_volatility_log_markers
            last_marker = log_store.get(ticker_key, {}) if isinstance(log_store.get(ticker_key, {}), dict) else {}
            marker = (active, direction, round(volatility, 2), preferred_side, signal_name)
            last_ts = self.to_float(last_marker.get("ts"), 0.0) or 0.0
            if last_marker.get("marker") != marker or now_ts - last_ts >= max(1.0, float(BTC_VOLATILITY_LOG_COOLDOWN_SECONDS or 20.0)):
                log_store[ticker_key] = {"ts": now_ts, "marker": marker}
                print(
                    f"[BTC-VOLATILITY-MODE] active={'yes' if active else 'no'} "
                    f"direction={direction} volatility={volatility} selected={ticker_key}"
                )
        return mode

    def _get_btc_volatility_rank_adjustment(self, item=None, *, market=None, q=None, spread=None, family=None, log=True, source="ranking"):
        if item is not None and isinstance(item, (list, tuple)):
            q = q or (item[1] if len(item) > 1 else None)
            spread = spread if spread is not None else (item[2] if len(item) > 2 else None)
            family = family or (item[3] if len(item) > 3 else None)
        elif isinstance(item, dict):
            q = q or item.get("q") or item.get("quote")
            spread = spread if spread is not None else item.get("spread")
            family = family or item.get("family")
            market = market or item.get("market")
        mode = self._get_btc_volatility_mode(
            market=market,
            q=q,
            family=family,
            spread=spread,
            source=source,
            log=log,
        )
        adjustment = 0.0
        if mode.get("active"):
            imbalance_context = self._extract_orderbook_imbalance_context(
                item,
                market=market,
                q=q,
                spread=spread,
                family=family,
            )
            side = self._normalize_orderbook_imbalance_side(mode.get("preferred_side"))
            side_support = self.to_float(imbalance_context.get("imbalance"), 0.0) or 0.0
            if side == "no":
                side_support = -side_support
            spread_value = self.to_float(imbalance_context.get("spread"), spread)
            if spread_value is None:
                spread_factor = 1.0
            else:
                spread_limit = max(MAX_ENTRY_SPREAD, min(float(BTC_VOLATILITY_MAX_EFFECTIVE_SPREAD or MAX_ENTRY_SPREAD), MAX_ENTRY_SPREAD + float(BTC_VOLATILITY_SPREAD_RELAXATION or 0.0)))
                spread_factor = max(0.45, min(1.0, 1.0 - max(0.0, spread_value) / max(spread_limit * 1.5, 0.01)))
            executable = bool(imbalance_context.get("yes_executable")) if side == "yes" else bool(imbalance_context.get("no_executable")) if side == "no" else True
            executable_factor = 1.0 if executable else 0.55
            volatility_strength = min(1.0, self.to_float(mode.get("volatility"), 0.0) / 2.0)
            momentum_strength = min(1.0, max(abs(self.to_float(mode.get("delta"), 0.0)) / max(float(BTC_VOLATILITY_PRICE_DELTA_TRIGGER or 0.018), 0.001), abs(self.to_float(mode.get("velocity"), 0.0)) / max(float(BTC_VOLATILITY_VELOCITY_TRIGGER or 0.00045), 0.00001)))
            pressure_strength = self._clamp(max(0.0, side_support), 0.0, 1.0)
            adjustment = (
                float(BTC_VOLATILITY_MAX_RANK_BOOST or 0.0)
                * (0.45 * volatility_strength + 0.35 * momentum_strength + 0.20 * pressure_strength)
                * spread_factor
                * executable_factor
            )
            if side_support < -float(BTC_VOLATILITY_IMBALANCE_TRIGGER or 0.28):
                adjustment -= min(1.5, float(BTC_VOLATILITY_MAX_RANK_BOOST or 0.0) * 0.18 * min(1.0, abs(side_support)))
        mode["adjustment"] = round(float(adjustment or 0.0), 4)
        return mode

    def _attach_ev_score_to_candidate(
        self,
        item=None,
        *,
        market=None,
        q=None,
        spread=None,
        family=None,
        expectancy_summary=None,
        quality_snapshot=None,
        family_profit_memory_adjustment=0.0,
        orderbook_imbalance_context=None,
        dynamic_memory_adjustment=0.0,
        adaptive_confidence_summary=None,
        source="ranking",
    ):
        if candidate_quality_compute_candidate_ev is None:
            return {}
        item = item if item is not None else {}
        market = market if isinstance(market, dict) else {}
        expectancy_summary = expectancy_summary if isinstance(expectancy_summary, dict) else {}
        quality_snapshot = quality_snapshot if isinstance(quality_snapshot, dict) else {}
        orderbook_imbalance_context = orderbook_imbalance_context if isinstance(orderbook_imbalance_context, dict) else {}
        adaptive_confidence_summary = adaptive_confidence_summary if isinstance(adaptive_confidence_summary, dict) else {}
        if isinstance(item, dict):
            q = q or item.get("q") or item.get("quote")
            spread = spread if spread is not None else item.get("spread")
            family = family or item.get("family")
            if not expectancy_summary and isinstance(item.get("expectancy_summary"), dict):
                expectancy_summary = item.get("expectancy_summary") or {}
            if not quality_snapshot and isinstance(item.get("quality_snapshot"), dict):
                quality_snapshot = item.get("quality_snapshot") or {}
        elif isinstance(item, (list, tuple)):
            q = q or (item[1] if len(item) > 1 else None)
            spread = spread if spread is not None else (item[2] if len(item) > 2 else None)
            family = family or (item[3] if len(item) > 3 else None)
        ticker = str(
            (item.get("ticker") if isinstance(item, dict) else "")
            or getattr(q, "ticker", "")
            or market.get("ticker", "")
            or ""
        ).strip()
        family = self._normalize_family_for_profit_memory(family, ticker=ticker, market=market, q=q)
        memory_profile = {}
        try:
            memory_profile = dict((getattr(self, "market_memory_profiles", {}) or {}).get(ticker, {}) or {})
        except Exception:
            memory_profile = {}
        selected_side = (
            expectancy_summary.get("selected_side")
            or quality_snapshot.get("selected_side")
            or (item.get("selected_side") if isinstance(item, dict) else None)
            or getattr(q, "selected_side", None)
            or getattr(q, "side", None)
        )
        selected_price = (
            expectancy_summary.get("selected_price")
            or expectancy_summary.get("selected_price_dollars")
            or quality_snapshot.get("selected_price")
            or quality_snapshot.get("selected_price_dollars")
            or (item.get("selected_price") if isinstance(item, dict) else None)
            or getattr(q, "selected_price", None)
        )
        ev_candidate = {
            "ticker": ticker or None,
            "family": family,
            "q": q,
            "side": selected_side,
            "selected_side": selected_side,
            "selected_price": selected_price,
            "spread": spread,
            "yes_bid": getattr(q, "yes_bid", None) if q is not None else market.get("yes_bid"),
            "yes_ask": getattr(q, "yes_ask", None) if q is not None else market.get("yes_ask"),
            "no_bid": getattr(q, "no_bid", None) if q is not None else market.get("no_bid"),
            "no_ask": getattr(q, "no_ask", None) if q is not None else market.get("no_ask"),
            "probability_estimate": (
                expectancy_summary.get("probability_estimate")
                or quality_snapshot.get("probability_estimate")
                or (item.get("probability_estimate") if isinstance(item, dict) else None)
            ),
            "implied_probability": (
                expectancy_summary.get("implied_probability")
                or quality_snapshot.get("implied_probability")
                or (item.get("implied_probability") if isinstance(item, dict) else None)
            ),
            "confidence_score": (
                expectancy_summary.get("confidence_score")
                or quality_snapshot.get("confidence_score")
                or quality_snapshot.get("profitability_score")
                or (item.get("confidence_score") if isinstance(item, dict) else None)
            ),
            "probability_confidence": expectancy_summary.get("probability_confidence") or quality_snapshot.get("probability_confidence"),
            "family_profit_memory_adjustment": family_profit_memory_adjustment,
            "dynamic_memory_adjustment": dynamic_memory_adjustment,
            "orderbook_imbalance_adjustment": (orderbook_imbalance_context or {}).get("adjustment"),
            "orderbook_imbalance": orderbook_imbalance_context,
            "memory_profile": memory_profile,
            "adaptive_confidence_summary": adaptive_confidence_summary,
            "expectancy_summary": expectancy_summary,
            "quality_snapshot": quality_snapshot,
            "source": source,
        }
        ev_context = candidate_quality_compute_candidate_ev(ev_candidate)
        ev_fields = (
            "market_implied_probability",
            "estimated_win_probability",
            "expected_value",
            "expected_roi",
            "ev_edge",
            "ev_score",
            "ev_selected_price",
            "ev_tier",
            "ev_reason",
            "ev_sizing_multiplier",
            "ev_action",
        )
        for target in (item if isinstance(item, dict) else None, expectancy_summary, quality_snapshot):
            if isinstance(target, dict):
                for field in ev_fields:
                    target[field] = ev_context.get(field)
        if q is not None:
            for field in ev_fields:
                try:
                    setattr(q, field, ev_context.get(field))
                except Exception:
                    pass
        return ev_context

    def _ev_rank_adjustment(self, ev_context):
        ev_context = ev_context if isinstance(ev_context, dict) else {}
        ev_score = self.to_float(ev_context.get("ev_score"), 0.0) or 0.0
        ev_tier = str(ev_context.get("ev_tier") or "").strip().upper()
        if ev_tier == "S":
            return max(1.50, min(4.00, ev_score * 0.35))
        if ev_tier == "A":
            return max(0.75, min(2.50, ev_score * 0.30))
        if ev_tier == "B":
            return max(0.10, min(1.25, ev_score * 0.20))
        if ev_tier == "C":
            return max(-0.25, min(0.25, ev_score * 0.10))
        if ev_tier == "D":
            return min(-0.50, max(-3.50, ev_score * 0.25))
        return max(-0.25, min(0.25, ev_score * 0.10))

    def _resolve_ev_contract_size(self, ev_context=None, q=None):
        ev_context = ev_context if isinstance(ev_context, dict) else {}
        base_size = max(1, int(AION_AGGRESSIVE_MAX_CONTRACTS or 1))
        max_size = max(1, int(MAX_LIVE_ORDER_SIZE or base_size))
        multiplier = self.to_float(ev_context.get("ev_sizing_multiplier"), None)
        if multiplier is None and q is not None:
            multiplier = self.to_float(getattr(q, "ev_sizing_multiplier", None), None)
        if multiplier is None:
            multiplier = 1.0
        multiplier = max(0.0, min(1.60, float(multiplier)))
        ev_tier = str(ev_context.get("ev_tier") or getattr(q, "ev_tier", None) or "C").strip().upper() or "C"
        requested_size = int(round(base_size * multiplier))
        if ev_tier == "S" and multiplier > 1.0 and max_size > base_size:
            requested_size = max(requested_size, base_size + 1)
        if requested_size <= 0:
            requested_size = 1
        return max(1, min(max_size, requested_size))

    def _apply_rank_only_memory_adjustments(self, ranked, *, source="ranking", markets=None):
        ranked = list(ranked or [])
        if not ranked:
            return ranked
        market_lookup = {
            str(market.get("ticker", "") or "").strip(): market
            for market in (markets or [])
            if isinstance(market, dict) and str(market.get("ticker", "") or "").strip()
        }
        decorated = []
        for index, item in enumerate(ranked):
            ticker = self._extract_ticker_from_ranked_candidate(item)
            market = market_lookup.get(ticker, {})
            family = self._extract_family_from_ranked_candidate(item)
            family_adjustment = self._get_family_profit_memory_adjustment(family, log=True, source=source)
            imbalance_context = self._get_orderbook_imbalance_adjustment(
                item,
                market=market,
                log=True,
                source=source,
            )
            btc_volatility_context = self._get_btc_volatility_rank_adjustment(
                item,
                market=market,
                log=True,
                source=source,
            )
            ev_context = self._attach_ev_score_to_candidate(
                item,
                market=market,
                family=family,
                family_profit_memory_adjustment=family_adjustment,
                orderbook_imbalance_context=imbalance_context,
                source=source,
            )
            total_score = (
                self._rank_score_for_family_profit_memory(item)
                + family_adjustment
                + self.to_float(imbalance_context.get("adjustment"), 0.0)
                + self.to_float(btc_volatility_context.get("adjustment"), 0.0)
                + self._ev_rank_adjustment(ev_context)
            )
            decorated.append((total_score, -index, item))
        decorated.sort(key=lambda entry: (entry[0], entry[1]), reverse=True)
        return [item for _total_score, _tie_breaker, item in decorated]

    def _record_live_session_outcome(self, realized_value, now_ts=None):
        now_ts = float(now_ts or time.time())
        self.live_recent_session_outcomes.append({"ts": now_ts, "pnl": float(realized_value or 0.0)})
        self.live_recent_session_outcomes = [
            item for item in list(self.live_recent_session_outcomes or [])
            if now_ts - float((item or {}).get("ts", 0.0) or 0.0) <= 6 * 3600
        ]

    def _get_live_session_streaks(self):
        profit_streak = 0
        loss_streak = 0
        for item in reversed(list(self.live_recent_session_outcomes or [])):
            pnl_value = float((item or {}).get("pnl", 0.0) or 0.0)
            if pnl_value > 0:
                if loss_streak > 0:
                    break
                profit_streak += 1
            elif pnl_value < 0:
                if profit_streak > 0:
                    break
                loss_streak += 1
            else:
                break
        return profit_streak, loss_streak

    def _get_live_session_mode(self):
        wins_today = int(self.live_perf_wins_today or 0)
        losses_today = int(self.live_perf_losses_today or 0)
        realized_pnl_today = float(self.live_realized_pnl_today or 0.0)
        profit_streak, loss_streak = self._get_live_session_streaks()
        mode = "neutral"
        reason = "flat_session"
        if not KALSHI_SESSION_PROTECTION_ENABLED:
            reason = "feature_disabled"
        elif realized_pnl_today <= KALSHI_DEFENSIVE_MODE_PNL or loss_streak >= 2 or (losses_today >= wins_today + 2 and losses_today >= 3):
            mode = "defensive"
            reason = "drawdown_or_loss_streak"
        elif realized_pnl_today >= KALSHI_PROTECTED_MODE_PNL:
            mode = "protected"
            reason = "protecting_session_gains"
        elif realized_pnl_today > 0 or profit_streak >= 2:
            mode = "aggressive"
            reason = "positive_session_flow"
        log_marker = (mode, round(realized_pnl_today, 4), wins_today, losses_today, profit_streak, loss_streak)
        if self.live_session_mode_log_marker != log_marker:
            print(
                f"[LIVE-SESSION-MODE] mode={mode} realized_pnl_today={round(realized_pnl_today, 4)} "
                f"wins_today={wins_today} losses_today={losses_today} "
                f"profit_streak={profit_streak} loss_streak={loss_streak} reason={reason}"
            )
            if mode == "protected":
                print(
                    f"[LIVE-SESSION-PROTECTED] realized_pnl_today={round(realized_pnl_today, 4)} "
                    f"threshold={KALSHI_PROTECTED_MODE_PNL}"
                )
            elif mode == "defensive":
                print(
                    f"[LIVE-SESSION-DEFENSIVE] realized_pnl_today={round(realized_pnl_today, 4)} "
                    f"threshold={KALSHI_DEFENSIVE_MODE_PNL}"
                )
            elif mode == "aggressive":
                print(
                    f"[LIVE-SESSION-AGGRESSIVE] realized_pnl_today={round(realized_pnl_today, 4)} "
                    f"profit_streak={profit_streak}"
                )
            self.live_session_mode_log_marker = log_marker
            self.live_session_mode = mode
        return {
            "mode": mode,
            "reason": reason,
            "realized_pnl_today": realized_pnl_today,
            "wins_today": wins_today,
            "losses_today": losses_today,
            "profit_streak": profit_streak,
            "loss_streak": loss_streak,
        }

    def _get_live_session_entry_adjustment(self, adaptive_entry=False, borderline=False):
        session_state = self._get_live_session_mode()
        mode = session_state.get("mode", "neutral")
        if not KALSHI_SESSION_PROTECTION_ENABLED:
            return {"mode": mode, "score_penalty": 0.0, "adaptive_block": False, "reason": "feature_disabled"}
        score_penalty = 0.0
        adaptive_block = False
        reason = "neutral"
        if mode == "protected":
            score_penalty = PHASE5_BUY_SCORE_THRESHOLD * KALSHI_PROTECTED_MODE_ENTRY_PENALTY
            if adaptive_entry and borderline:
                adaptive_block = True
                reason = "protected_mode_blocks_borderline_adaptive"
            else:
                reason = "protected_mode_penalty"
        elif mode == "defensive":
            score_penalty = PHASE5_BUY_SCORE_THRESHOLD * KALSHI_DEFENSIVE_MODE_ENTRY_PENALTY
            if adaptive_entry or borderline:
                adaptive_block = True
                reason = "defensive_mode_blocks_adaptive_or_borderline"
            else:
                reason = "defensive_mode_penalty"
        elif mode == "aggressive":
            reason = "normal_operation"
        print(
            f"[LIVE-SESSION-ENTRY-ADJUSTMENT] mode={mode} adaptive_entry={'yes' if adaptive_entry else 'no'} "
            f"borderline={'yes' if borderline else 'no'} score_penalty={round(score_penalty, 4)} "
            f"adaptive_block={'yes' if adaptive_block else 'no'} reason={reason}"
        )
        return {
            "mode": mode,
            "score_penalty": float(score_penalty),
            "adaptive_block": adaptive_block,
            "reason": reason,
        }

    def _get_family_performance_weight(self, family):
        family = self._normalize_family_for_profit_memory(family)
        self._get_family_profit_memory_adjustment(family, log=False, source="legacy_decision_hook")
        return 0.0

    def _prune_post_loss_cooldowns(self, now_ts=None):
        now_ts = float(now_ts or time.time())
        for ticker, event in list((self.live_post_loss_ticker_cooldowns or {}).items()):
            expires_at = float((event or {}).get("expires_at", 0.0) or 0.0)
            if expires_at and expires_at <= now_ts:
                print(
                    f"[LIVE-POST-LOSS-COOLDOWN-EXPIRED] scope=ticker ticker={ticker} "
                    f"family={(event or {}).get('family')} reason={(event or {}).get('reason')}"
                )
                self.live_post_loss_ticker_cooldowns.pop(ticker, None)
        for family, event in list((self.live_post_loss_family_cooldowns or {}).items()):
            expires_at = float((event or {}).get("expires_at", 0.0) or 0.0)
            if expires_at and expires_at <= now_ts:
                print(
                    f"[LIVE-POST-LOSS-COOLDOWN-EXPIRED] scope=family family={family} "
                    f"reason={(event or {}).get('reason')}"
                )
                self.live_post_loss_family_cooldowns.pop(family, None)
        recent_window = max(1800, KALSHI_POST_LOSS_TICKER_COOLDOWN_SECONDS)
        self.live_recent_negative_exit_events = [
            event for event in list(self.live_recent_negative_exit_events or [])
            if now_ts - float((event or {}).get("ts", 0.0) or 0.0) <= recent_window
        ]

    def _prune_degenerate_family_cooldowns(self, now_ts=None):
        now_ts = float(now_ts or time.time())
        window_seconds = float(KALSHI_DEGENERATE_FAMILY_WINDOW_SECONDS)
        history_container = getattr(self, "live_degenerate_family_reject_history", {}) or {}
        for family, state in list(history_container.items()):
            recent_timestamps = [
                float(ts)
                for ts in list((state or {}).get("recent_timestamps", []))
                if now_ts - float(ts or 0.0) <= window_seconds
            ]
            if recent_timestamps:
                state = dict(state or {})
                state["recent_timestamps"] = recent_timestamps
                history_container[family] = state
            else:
                history_container.pop(family, None)
        cooldown_container = getattr(self, "live_degenerate_family_cooldowns", {}) or {}
        for family, event in list(cooldown_container.items()):
            expires_at = float((event or {}).get("expires_at", 0.0) or 0.0)
            if expires_at and expires_at <= now_ts:
                print(
                    f"[AION-DEGENERATE-FAMILY-COOLDOWN-EXPIRED] family={family} "
                    f"reason={(event or {}).get('reason')} cooldown_until={round(expires_at, 3)}"
                )
                cooldown_container.pop(family, None)

    def _get_degenerate_family_penalty_state(self, family, now_ts=None):
        now_ts = float(now_ts or time.time())
        family = str(family or "UNKNOWN").strip().upper() or "UNKNOWN"
        self._prune_degenerate_family_cooldowns(now_ts=now_ts)
        history = dict((self.live_degenerate_family_reject_history or {}).get(family, {}) or {})
        recent_timestamps = [
            float(ts)
            for ts in list(history.get("recent_timestamps", []))
            if now_ts - float(ts or 0.0) <= float(KALSHI_DEGENERATE_FAMILY_WINDOW_SECONDS)
        ]
        recent_rejects = len(recent_timestamps)
        cooldown_event = dict((self.live_degenerate_family_cooldowns or {}).get(family, {}) or {})
        cooldown_expires_at = float(cooldown_event.get("expires_at", 0.0) or 0.0)
        cooldown_remaining_seconds = max(0.0, cooldown_expires_at - now_ts)
        cooldown_active = cooldown_remaining_seconds > 0.0
        penalty = 0.0
        if recent_rejects > 0:
            penalty += float(recent_rejects) * float(KALSHI_DEGENERATE_FAMILY_BASE_PENALTY)
        if recent_rejects >= int(KALSHI_DEGENERATE_FAMILY_MIN_REJECTIONS):
            penalty += 18.0 + max(0.0, float(recent_rejects) - float(KALSHI_DEGENERATE_FAMILY_MIN_REJECTIONS)) * 4.0
        if cooldown_active:
            penalty += float(KALSHI_DEGENERATE_FAMILY_ACTIVE_COOLDOWN_PENALTY)
        penalty += min(20.0, cooldown_remaining_seconds / 30.0) if cooldown_active else 0.0
        return {
            "family": family,
            "recent_rejects": recent_rejects,
            "cooldown_active": cooldown_active,
            "cooldown_remaining_seconds": int(max(0.0, cooldown_remaining_seconds)),
            "cooldown_reason": str(cooldown_event.get("reason") or "degenerate_family_cooldown"),
            "cooldown_until": round(cooldown_expires_at, 3) if cooldown_expires_at else 0.0,
            "penalty": round(penalty, 4),
            "window_seconds": int(KALSHI_DEGENERATE_FAMILY_WINDOW_SECONDS),
            "trigger_rejections": int(KALSHI_DEGENERATE_FAMILY_MIN_REJECTIONS),
        }

    def _record_degenerate_family_reject(self, family, ticker, reason, now_ts=None):
        now_ts = float(now_ts or time.time())
        family = str(family or "UNKNOWN").strip().upper() or "UNKNOWN"
        ticker = str(ticker or "").strip().upper()
        reason = str(reason or "degenerate_book").strip() or "degenerate_book"
        self._prune_degenerate_family_cooldowns(now_ts=now_ts)
        history = dict((self.live_degenerate_family_reject_history or {}).get(family, {}) or {})
        recent_timestamps = [
            float(ts)
            for ts in list(history.get("recent_timestamps", []))
            if now_ts - float(ts or 0.0) <= float(KALSHI_DEGENERATE_FAMILY_WINDOW_SECONDS)
        ]
        recent_timestamps.append(now_ts)
        history["recent_timestamps"] = recent_timestamps
        history["last_ticker"] = ticker
        history["last_reason"] = reason
        history["last_ts"] = now_ts
        self.live_degenerate_family_reject_history[family] = history
        family_state = self._get_degenerate_family_penalty_state(family, now_ts=now_ts)
        print(
            "[AION-DEGENERATE-FAMILY-PENALTY] "
            + json.dumps(
                {
                    "family": family,
                    "ticker": ticker,
                    "reason": reason,
                    "recent_rejects": family_state.get("recent_rejects", 0),
                    "penalty": family_state.get("penalty", 0.0),
                    "cooldown_active": family_state.get("cooldown_active", False),
                    "cooldown_remaining_seconds": family_state.get("cooldown_remaining_seconds", 0),
                    "window_seconds": family_state.get("window_seconds", 0),
                    "trigger_rejections": family_state.get("trigger_rejections", 0),
                },
                sort_keys=True,
                default=str,
            )
        )
        if family_state.get("recent_rejects", 0) >= int(KALSHI_DEGENERATE_FAMILY_MIN_REJECTIONS):
            cooldown_until = now_ts + float(KALSHI_DEGENERATE_FAMILY_COOLDOWN_SECONDS)
            current_cooldown_until = float((self.live_degenerate_family_cooldowns or {}).get(family, {}).get("expires_at", 0.0) or 0.0)
            if cooldown_until > current_cooldown_until:
                self.live_degenerate_family_cooldowns[family] = {
                    "family": family,
                    "ticker": ticker,
                    "reason": "repeated_degenerate_book",
                    "recent_rejects": family_state.get("recent_rejects", 0),
                    "expires_at": cooldown_until,
                }
                print(
                    "[AION-DEGENERATE-FAMILY-COOLDOWN] "
                    + json.dumps(
                        {
                            "family": family,
                            "ticker": ticker,
                            "reason": "repeated_degenerate_book",
                            "recent_rejects": family_state.get("recent_rejects", 0),
                            "cooldown_seconds": int(KALSHI_DEGENERATE_FAMILY_COOLDOWN_SECONDS),
                            "cooldown_until": round(cooldown_until, 3),
                        },
                        sort_keys=True,
                        default=str,
                    )
                )
                print(
                    "[AION-SCAN-CONTINUE-AFTER-DEGENERATE] "
                    + json.dumps(
                        {
                            "family": family,
                            "ticker": ticker,
                            "reason": "repeated_degenerate_book",
                            "next_action": "continue_scan",
                            "cooldown_applied": True,
                        },
                        sort_keys=True,
                        default=str,
                    )
                )
        return family_state

