                f"stage_label={stage_label} block_reason={psychology_context.get('block_reason')} "
                f"psychology_regime={psychology_context.get('psychology_regime')} psychology_score={psychology_context.get('psychology_score')} "
                f"shadow_only={'yes' if psychology_context.get('shadow_only') else 'no'} "
                f"hard_block_enabled={'yes' if psychology_context.get('hard_block_enabled') else 'no'} cached=yes"
