    def _canonical_quote_object_from_candidate(self, candidate):
        if candidate is None:
            return None
        source = candidate if isinstance(candidate, dict) else self._coerce_aion_orderbook_source(candidate)
        if not isinstance(source, dict) or not source:
            return None
        proxy = type("_AIONCanonicalQuoteProxy", (), {})()
        for key, value in source.items():
            try:
                setattr(proxy, key, value)
            except Exception:
                continue
        return proxy

    def _quote_has_executable_content(self, candidate):
        if candidate is None:
            return False
        source = candidate if isinstance(candidate, dict) else self._coerce_aion_orderbook_source(candidate)
        if not isinstance(source, dict) or not source:
            return False
        def _as_float(value):
            try:
                if value in (None, "", []):
                    return None
                return float(value)
            except (TypeError, ValueError):
                return None
        price = _as_float(
            source.get("selected_price")
            or source.get("selected_price_dollars")
            or source.get("yes_ask")
            or source.get("no_ask")
            or source.get("yes_price")
            or source.get("no_price")
        )
        cents = source.get("selected_price_cents")
        try:
            if cents not in (None, ""):
                cents = int(round(float(cents)))
            else:
                cents = None
        except (TypeError, ValueError):
            cents = None
        selected_side = str(source.get("selected_side") or source.get("side") or "").strip().lower() or None
        yes_bid = _as_float(source.get("yes_bid"))
        yes_ask = _as_float(source.get("yes_ask"))
        no_bid = _as_float(source.get("no_bid"))
        no_ask = _as_float(source.get("no_ask"))
        executable_depth_present = bool(
            (yes_bid is not None and yes_ask is not None)
            or (no_bid is not None and no_ask is not None)
        )
        spread_present = bool(
            source.get("spread_present")
            or source.get("spread_cents") is not None
            or source.get("spread") is not None
        )
        selected_price_present = bool(
            (price is not None and 0.0 < price < 1.0)
            or (cents is not None and 0 < cents < 100)
        )
        selected_side_present = selected_side in {"yes", "no"}
        if not selected_price_present or not selected_side_present:
            return False
        return bool(executable_depth_present or spread_present)

    def _candidate_price_in_contract_bounds(self, field_name, value):
        try:
            if value in (None, "", []):
                return False
            numeric = float(value)
        except (TypeError, ValueError):
            return False
        field = str(field_name or "").strip().lower()
        if field.endswith("_cents"):
            return 1 <= int(round(numeric)) <= 99
        if field in {"yes_price", "no_price", "price"}:
            if numeric > 1.0:
                return 1 <= int(round(numeric)) <= 99
            if numeric == 1.0:
                return True
        return bool(KALSHI_CONTRACT_MIN_PRICE <= numeric <= KALSHI_CONTRACT_MAX_PRICE)

    def _candidate_has_explicit_unexecutable_price(self, candidate):
        source = candidate if isinstance(candidate, dict) else self._coerce_aion_orderbook_source(candidate)
        if not isinstance(source, dict) or not source:
            return False
        yes_bid = self.to_float(source.get("yes_bid_dollars", source.get("yes_bid")), None)
        yes_ask = self.to_float(source.get("yes_ask_dollars", source.get("yes_ask")), None)
        no_bid = self.to_float(source.get("no_bid_dollars", source.get("no_bid")), None)
        no_ask = self.to_float(source.get("no_ask_dollars", source.get("no_ask")), None)
        selected_side = str(source.get("selected_side") or source.get("side") or "").strip().lower()
        selected_price = self.to_float(source.get("selected_price_dollars", source.get("selected_price")), None)
        selected_price_cents = self.to_float(source.get("selected_price_cents"), None)
        if selected_price is None and selected_price_cents is not None:
            selected_price = round(float(selected_price_cents) / 100.0, 4)
        yes_spread = (float(yes_ask) - float(yes_bid)) if yes_bid is not None and yes_ask is not None else None
        no_spread = (float(no_ask) - float(no_bid)) if no_bid is not None and no_ask is not None else None
        visible_depth = max(
            self.to_float(source.get("yes_top_size", source.get("yes_ask_size_fp", source.get("yes_ask_size"))), 0.0) or 0.0,
            self.to_float(source.get("no_top_size", source.get("no_ask_size_fp", source.get("no_ask_size"))), 0.0) or 0.0,
            self.to_float(source.get("liquidity_dollars", source.get("liquidity")), 0.0) or 0.0,
        )
        yes_catastrophic = bool(
            yes_ask is not None
            and yes_ask >= KALSHI_CONTRACT_MAX_PRICE
            and (yes_bid is None or yes_bid <= 0.0)
            and visible_depth <= 0.0
        )
        no_catastrophic = bool(
            no_ask is not None
            and no_ask >= KALSHI_CONTRACT_MAX_PRICE
            and (no_bid is None or no_bid <= 0.0)
            and visible_depth <= 0.0
        )
        if yes_catastrophic or no_catastrophic:
            return True
        if selected_side == "yes" and selected_price is not None and selected_price >= KALSHI_CONTRACT_MAX_PRICE and (yes_spread is None or yes_spread >= 0.50):
            return True
        if selected_side == "no" and selected_price is not None and selected_price >= KALSHI_CONTRACT_MAX_PRICE and (no_spread is None or no_spread >= 0.50):
            return True
        price_fields = (
            "selected_price",
            "selected_price_dollars",
            "selected_price_cents",
            "chosen_price",
            "chosen_price_dollars",
            "chosen_price_cents",
            "yes_ask",
            "yes_ask_dollars",
            "no_ask",
            "no_ask_dollars",
            "yes_price",
            "no_price",
            "price",
        )
        seen = []
        for field in price_fields:
            value = source.get(field)
            if value in (None, "", []):
                continue
            try:
                numeric = float(value)
            except (TypeError, ValueError):
                continue
            seen.append((field, numeric))
            if self._candidate_price_in_contract_bounds(field, numeric):
                return False
        if not seen:
            return False
        boundary_values = []
        for field, numeric in seen:
            field_text = str(field).lower()
            if field_text.endswith("_cents") or field_text in {"yes_price", "no_price", "price"}:
                boundary_values.append(numeric <= 0.0 or numeric >= 100.0)
            else:
                boundary_values.append(numeric <= 0.0 or numeric >= 1.0)
        return any(boundary_values)

    def _mark_unexecutable_price_reject(self, ticker=None, family=None, reason="price_out_of_range", source="unknown"):
        ticker = str(ticker or "").strip()
        family = str(family or self.get_market_family({"ticker": ticker}) or "UNKNOWN").strip().upper() or "UNKNOWN"
        if not ticker:
            return
        now_ts = time.time()
        cooldown_until = now_ts + float(AION_PRICE_RANGE_REJECT_TICKER_COOLDOWN_SECONDS)
        current_cooldown_until = float((self.market_cooldowns or {}).get(ticker, 0.0) or 0.0)
        if current_cooldown_until > now_ts:
            return
        self.market_cooldowns[ticker] = max(cooldown_until, current_cooldown_until)
        self._record_price_family_reject(family, ticker, reason, now_ts=now_ts)
        print(
            "[AION-PRICE-RANGE-PREFILTER] "
            + json.dumps(
                {
                    "ticker": ticker,
                    "family": family,
                    "reason": reason,
                    "source": source,
                    "cooldown_seconds": int(AION_PRICE_RANGE_REJECT_TICKER_COOLDOWN_SECONDS),
                    "next_action": "continue_scan",
                },
                sort_keys=True,
                default=str,
            )
        )

    def _filter_unexecutable_price_ranked_candidates(self, ranked, *, source="unknown"):
        if not ranked:
            return ranked
        kept = []
        rejected = []
        for item in ranked:
            try:
                score, q, spread, family = item
            except (TypeError, ValueError):
                kept.append(item)
                continue
            ticker = str(getattr(q, "ticker", "") or "").strip()
            if self._candidate_has_explicit_unexecutable_price(q):
                rejected.append(ticker)
                self._mark_unexecutable_price_reject(
                    ticker=ticker,
                    family=family,
                    reason="explicit_unexecutable_price",
                    source=source,
                )
                continue
            kept.append((score, q, spread, family))
        if rejected:
            print(
                "[AION-PRICE-RANGE-FILTER] "
                + json.dumps(
                    {
                        "source": source,
                        "before": len(ranked),
                        "after": len(kept),
                        "filtered": len(rejected),
                        "tickers": rejected[:10],
                    },
                    sort_keys=True,
                    default=str,
                )
            )
        return kept

    def _resolve_aion_quote_content_gate(self, *, caller=None, quote_payload=None, payload=None, quote_diag=None, orderbook_resolution=None, selected_side=None, ticker=None, family=None):
        quote_payload = quote_payload if isinstance(quote_payload, dict) else {}
        payload = payload if isinstance(payload, dict) else {}
        quote_diag = quote_diag if isinstance(quote_diag, dict) else {}
        orderbook_resolution = orderbook_resolution if isinstance(orderbook_resolution, dict) else {}
        selected_side_value = str(
            selected_side
            or quote_diag.get("selected_side")
            or payload.get("selected_side")
            or getattr(quote_payload, "selected_side", None)
            or getattr(quote_payload, "side", None)
            or ""
        ).strip().lower() or None
        selected_price_value = self.to_float(
            quote_diag.get("selected_price_dollars"),
            self.to_float(
                quote_diag.get("selected_price"),
                self.to_float(
                    payload.get("selected_price"),
                    self.to_float(
                        payload.get("selected_price_dollars"),
                        self.to_float(
                            getattr(quote_payload, "selected_price", None),
                            self.to_float(getattr(quote_payload, "selected_price_dollars", None), None),
                        ),
                    ),
                ),
            ),
        )
        selected_price_cents_value = quote_diag.get("selected_price_cents")
        try:
            if selected_price_cents_value not in (None, ""):
                selected_price_cents_value = int(round(float(selected_price_cents_value)))
            else:
                selected_price_cents_value = None
        except (TypeError, ValueError):
            selected_price_cents_value = None
        yes_bid = self.to_float(
            quote_diag.get("yes_bid"),
            self.to_float(payload.get("yes_bid"), self.to_float(getattr(quote_payload, "yes_bid", None), None)),
        )
        yes_ask = self.to_float(
            quote_diag.get("yes_ask"),
            self.to_float(payload.get("yes_ask"), self.to_float(getattr(quote_payload, "yes_ask", None), None)),
        )
        no_bid = self.to_float(
            quote_diag.get("no_bid"),
            self.to_float(payload.get("no_bid"), self.to_float(getattr(quote_payload, "no_bid", None), None)),
        )
        no_ask = self.to_float(
            quote_diag.get("no_ask"),
            self.to_float(payload.get("no_ask"), self.to_float(getattr(quote_payload, "no_ask", None), None)),
        )
        spread_cents = (
            quote_diag.get("spread_cents")
            if quote_diag.get("spread_cents") is not None
            else payload.get("spread_cents")
            if payload.get("spread_cents") is not None
            else orderbook_resolution.get("spread_cents")
        )
        try:
            if spread_cents not in (None, ""):
                spread_cents = int(round(float(spread_cents)))
            else:
                spread_cents = None
        except (TypeError, ValueError):
            spread_cents = None
        yes_pair_present = bool(yes_bid is not None and yes_ask is not None)
        no_pair_present = bool(no_bid is not None and no_ask is not None)
        executable_depth_present = bool(yes_pair_present or no_pair_present)
        spread_present = bool(spread_cents is not None or quote_diag.get("spread_present") or payload.get("spread_present") or orderbook_resolution.get("spread_present"))
        selected_price_present = bool(
            selected_price_value is not None
            and 0.0 < float(selected_price_value) < 1.0
        ) or bool(selected_price_cents_value is not None and 0 < int(selected_price_cents_value) < 100)
        pass_gate = bool(selected_price_present and selected_side_value in {"yes", "no"} and (executable_depth_present or spread_present))
        reason = "passed" if pass_gate else "missing_spread"
        if not selected_price_present:
            reason = "missing_selected_price"
        elif selected_side_value not in {"yes", "no"}:
            reason = "missing_selected_side"
        elif not executable_depth_present and not spread_present:
            reason = "missing_bid_ask"
        payload_out = {
            "caller": str(caller or "unknown").strip() or "unknown",
            "family": family,
            "ticker": ticker,
            "selected_side": selected_side_value,
            "selected_price": selected_price_value,
            "selected_price_cents": selected_price_cents_value,
            "yes_bid": yes_bid,
            "yes_ask": yes_ask,
            "no_bid": no_bid,
            "no_ask": no_ask,
            "spread_cents": spread_cents,
            "spread_present": bool(spread_present),
            "executable_depth_present": bool(executable_depth_present),
            "pass": bool(pass_gate),
            "reason": reason,
        }
        print(
            "[AION-EXECUTABLE-QUOTE-GATE] "
            + json.dumps(payload_out, sort_keys=True, default=str)
        )
        return payload_out

    def _resolve_canonical_submit_quote(self, *, payload=None, quote=None):
        payload = payload if isinstance(payload, dict) else {}
        source_fields_checked = []
        candidate_sources = [
            ("local.quote", quote),
            ("payload.selected_quote", payload.get("selected_quote")),
            ("payload.quote_object", payload.get("quote_object")),
            ("payload.selected_context_quote", payload.get("selected_context_quote")),
            ("payload.canonical_selected_quote", payload.get("canonical_selected_quote")),
            ("payload.canonical_quote_object", payload.get("canonical_quote_object")),
            ("payload.quote", payload.get("quote")),
            ("payload.canonical_quote_payload", payload.get("canonical_quote_payload")),
        ]
        for source_field, candidate in candidate_sources:
            source_fields_checked.append(source_field)
            if candidate is None:
                continue
            resolved = self._canonical_quote_object_from_candidate(candidate)
            if resolved is None:
                continue
            if not self._quote_has_executable_content(resolved):
                continue
            if resolved is None:
                continue
            try:
                selected_price = self.to_float(getattr(resolved, "selected_price", None), None)
                if selected_price is None:
                    selected_price = self.to_float(getattr(resolved, "selected_price_dollars", None), None)
                if selected_price is None:
                    cents = getattr(resolved, "selected_price_cents", None)
                    if cents not in (None, ""):
                        selected_price = round(float(cents) / 100.0, 4)
                if selected_price is None or not (0.0 < float(selected_price) < 1.0):
                    continue
            except (TypeError, ValueError):
                continue
            selected_side = str(
                getattr(resolved, "selected_side", None)
                or getattr(resolved, "side", None)
                or payload.get("selected_side")
                or ""
            ).strip().lower() or None
            print(
                "[AION-SUBMIT-QUOTE-FOUND] "
                + json.dumps(
                    {
                        "ticker": payload.get("ticker") or getattr(resolved, "ticker", None),
                        "family": payload.get("family") or getattr(resolved, "family", None),
                        "stage": "resolve_aion_trade_readiness",
                        "trace_id": payload.get("trace_id"),
                        "source_field": source_field,
                        "source_fields_checked": source_fields_checked,
                        "selected_price": selected_price,
                        "selected_side": selected_side,
                        "selected_ticker": getattr(resolved, "ticker", None),
                    },
                    sort_keys=True,
                    default=str,
                )
            )
            return resolved, source_field, source_fields_checked
        print(
            "[AION-SUBMIT-QUOTE-MISSING] "
            + json.dumps(
                {
                    "ticker": payload.get("ticker"),
                    "family": payload.get("family"),
                    "stage": "resolve_aion_trade_readiness",
                    "trace_id": payload.get("trace_id"),
                    "source_fields_checked": source_fields_checked,
                    "reason": "missing_submit_quote",
                },
                sort_keys=True,
                default=str,
            )
        )
        return None, None, source_fields_checked

    def build_live_dispatch_decision(self, candidate_or_payload=None):
        source = candidate_or_payload if candidate_or_payload is not None else {}

        def _read(key, default=None):
            if isinstance(source, dict):
                return source.get(key, default)
            if source is None:
                return default
            return getattr(source, key, default)

        ticker = str(_read('ticker', '') or '').strip() or None
        family = str(_read('family', '') or '').strip().upper() or None
        selected_price = self.safe_price(
            _read(
                'selected_price',
                _read('selected_price_dollars', _read('yes_ask', _read('no_ask', None))),
            )
        )
        selected_side = str(_read('selected_side', _read('side', '')) or '').strip().lower() or None
        quote_content_pass = self.safe_bool(_read('quote_content_pass', False))
        executable_quote_pass = self.safe_bool(_read('executable_quote_pass', False))
        spread_present = self.safe_bool(_read('spread_present', False)) or _read('spread_cents') is not None or _read('spread') is not None
        auth_ready = self.safe_bool(_read('auth_ready', False))
        payload_ready = self.safe_bool(_read('payload_ready', False))
        duplicate_block = self.safe_bool(_read('duplicate_block', False))
        final_submit_allowed = self.safe_bool(_read('final_submit_allowed', False))
        submit_quote_present = self.safe_bool(_read('submit_quote_present', True))
        selected_price_ok = selected_price is not None and 0.01 <= float(selected_price) <= 0.99
        selected_side_ok = selected_side in {'yes', 'no'}
        can_submit = bool(
            submit_quote_present
            and final_submit_allowed
            and auth_ready
            and payload_ready
            and not duplicate_block
            and quote_content_pass
            and executable_quote_pass
            and spread_present
            and selected_price_ok
            and selected_side_ok
        )
        if can_submit:
            block_reason = 'none'
        elif not auth_ready:
            block_reason = 'auth_not_ready'
        elif not payload_ready:
            block_reason = 'payload_not_ready'
        elif duplicate_block:
            block_reason = 'duplicate_block'
        elif not final_submit_allowed:
            block_reason = 'final_submit_not_allowed'
        elif not quote_content_pass:
            block_reason = 'quote_content_failed'
        elif not executable_quote_pass:
            block_reason = 'executable_quote_failed'
        elif not spread_present:
            block_reason = 'missing_spread'
        elif selected_price is None:
            block_reason = 'missing_selected_price'
        elif not selected_price_ok:
            block_reason = 'price_out_of_range'
        elif not selected_side_ok:
            block_reason = 'missing_selected_side'
        else:
            block_reason = 'unknown_dispatch_block'
        return {
            'can_submit': bool(can_submit),
            'block_reason': block_reason,
            'ticker': ticker,
            'family': family,
            'selected_price': selected_price,
            'selected_side': selected_side,
            'quote_content_pass': bool(quote_content_pass),
            'executable_quote_pass': bool(executable_quote_pass),
            'spread_present': bool(spread_present),
            'auth_ready': bool(auth_ready),
            'payload_ready': bool(payload_ready),
            'duplicate_block': bool(duplicate_block),
            'final_submit_allowed': bool(final_submit_allowed),
        }

