            family_learning_summary=(self.last_candidate_learning_family_summary or {}) if isinstance(self.last_candidate_learning_family_summary, dict) else {},
            microstructure_summary=self.last_live_microstructure_summary or {},
            safe_queue_summary=self.last_safe_opportunity_queue_summary or {},
            entry_timing_observation=(self.last_live_select_summary or {}).get("entry_timing_status") or {},
            sports_harvest_summary=self.last_sports_harvest_summary or {},
            sports_context=(sports_harvest_payload if isinstance(locals().get("sports_harvest_payload"), dict) else {}),
